window.TAFSEER_DATA = [{"surahNumber": 53, "surahNameArabic": "سُورَةُ النَّجۡمِ", "surahNameMalayalam": "സൂറത്തുന്നജ്മ് (നക്ഷത്രം)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ وَٱلنَّجۡمِ إِذَا هَوَىٰ\n", "jalalayn": "«والنَّجْم» الثُّرَيّا «إذا هَوى» غابَ", "malayalam": "«നക്ഷത്രത്തെ തന്നെയാണ് സത്യം» (സുറയ്യ അഥവാ കാർത്തിക നക്ഷത്രം), «അത് അസ്തമിക്കുമ്പോൾ» (അത് മറഞ്ഞുപോകുമ്പോൾ).", "malayalamMatn": "നക്ഷത്രം അസ്തമിക്കുമ്പോള്‍ അതിനെ തന്നെയാണ, സത്യം."}, {"ayahNumber": 2, "quranText": "مَا ضَلَّ صَاحِبُكُمۡ وَمَا غَوَىٰ\n", "jalalayn": "«ما ضَلَّ صاحِبكُمْ» مُحَمَّد عَلَيْهِ الصَّلاة والسَّلام عَنْ طَرِيق الهِدايَة «وما غَوى» ما لابَسَ الغَيّ وهُوَ جَهْل مِن اعْتِقاد فاسِد", "malayalam": "«നിങ്ങളുടെ കൂട്ടുകാരൻ» (മുഹമ്മദ് നബി ﷺ സന്മാർഗ്ഗത്തിൽ നിന്ന്) «വഴിതെറ്റിയിട്ടില്ല», «ദുർമാർഗ്ഗിയായിട്ടുമില്ല» (ദുഷിച്ച വിശ്വാസത്തിൽ നിന്നുള്ള അജ്ഞത അദ്ദേഹത്തെ ബാധിച്ചിട്ടില്ല).", "malayalamMatn": "നിങ്ങളുടെ കൂട്ടുകാരന്‍ വഴിതെറ്റിയിട്ടില്ല. ദുര്‍മാര്‍ഗിയായിട്ടുമില്ല."}, {"ayahNumber": 3, "quranText": "وَمَا یَنطِقُ عَنِ ٱلۡهَوَىٰۤ\n", "jalalayn": "«وما يَنْطِق» بِما يَأْتِيكُمْ بِهِ «عَنِ الهَوى» هَوى نَفْسه", "malayalam": "«അദ്ദേഹം സംസാരിക്കുന്നുമില്ല» (നിങ്ങൾക്ക് കൊണ്ടുവന്നു തരുന്ന സന്ദേശങ്ങളെക്കുറിച്ച്) «തന്നിഷ്ടപ്രകാരം» (തന്റെ സ്വന്തം ഇച്ഛയനുസരിച്ച്).", "malayalamMatn": "അദ്ദേഹം തന്നിഷ്ടപ്രകാരം സംസാരിക്കുന്നുമില്ല."}, {"ayahNumber": 4, "quranText": "إِنۡ هُوَ إِلَّا وَحۡیࣱ یُوحَىٰ\n", "jalalayn": "«إنْ» ما «هُوَ إلّا وحْي يُوحى» إلَيْهِ", "malayalam": "«അത്» (അദ്ദേഹം പറയുന്ന ഖുർആൻ) «അദ്ദേഹത്തിന് നൽകപ്പെടുന്ന ദിവ്യസന്ദേശം (വഹ്‌യ്) മാത്രമാകുന്നു».", "malayalamMatn": "അത് അദ്ദേഹത്തിന് ദിവ്യസന്ദേശമായി നല്‍കപ്പെടുന്ന ഒരു ഉല്‍ബോധനം മാത്രമാകുന്നു."}, {"ayahNumber": 5, "quranText": "عَلَّمَهُۥ شَدِیدُ ٱلۡقُوَىٰ\n", "jalalayn": "«عَلَّمَهُ» إيّاهُ مَلَك", "malayalam": "«കരുത്തുറ്റ ശക്തിയുള്ളവൻ» (ശക്തിശാലിയായ മലക്ക്, അതായത് ജിബ്‌രീൽ അലൈഹിസ്സലാം) «അദ്ദേഹത്തെ അത് പഠിപ്പിച്ചു».", "malayalamMatn": "ശക്തിമത്തായ കഴിവുള്ളവനാണ് (ജിബ്‌രീല്‍ എന്ന മലക്കാണ്‌) അദ്ദേഹത്തെ പഠിപ്പിച്ചിട്ടുള്ളത്‌."}, {"ayahNumber": 6, "quranText": "ذُو مِرَّةࣲ فَٱسۡتَوَىٰ\n", "jalalayn": "«ذُو مِرَّة» قُوَّة وشِدَّة أوْ مَنظَر حَسَن أيْ جِبْرِيل عَلَيْهِ السَّلام «فاسْتَوى» اسْتَقَرَّ", "malayalam": "«കരുത്തനായവൻ» (ശക്തമായ ശരീരപ്രകൃതമുള്ളവൻ), «എന്നിട്ട് അദ്ദേഹം നേരെ നിന്നു» (തന്റെ യഥാർത്ഥ രൂപത്തിൽ നിലകൊണ്ടു).", "malayalamMatn": "കരുത്തുള്ള ഒരു വ്യക്തി. അങ്ങനെ അദ്ദേഹം (സാക്ഷാല്‍ രൂപത്തില്‍) നിലകൊണ്ടു."}, {"ayahNumber": 7, "quranText": "وَهُوَ بِٱلۡأُفُقِ ٱلۡأَعۡلَىٰ\n", "jalalayn": "«وهُوَ بِالأُفُقِ الأَعْلى» أُفُق الشَّمْس أيْ عِنْد مَطْلَعها عَلى صُورَته الَّتِي خُلِقَ عَلَيْها فَرَآهُ النَّبِيّ ﷺ وكانَ بِحِراءٍ قَدْ سَدَّ الأُفُق إلى المَغْرِب فَخَرَّ مَغْشِيًّا عَلَيْهِ وكانَ قَدْ سَأَلَهُ أنْ يُرِيه نَفْسه عَلى صُورَته الَّتِي خُلِقَ عَلَيْها فَواعَدَهُ بِحِراءٍ فَنَزَلَ جِبْرِيل لَهُ فِي صُورَة الآدَمِيِّينَ", "malayalam": "«അദ്ദേഹമാകട്ടെ അത്യുന്നതമായ ചക്രവാളത്തിലായിരുന്നു» (സൂര്യോദയ സ്ഥാനത്ത്, നബി ﷺ അദ്ദേഹത്തെ സൃഷ്ടിക്കപ്പെട്ട യഥാർത്ഥ രൂപത്തിൽ കണ്ടു).", "malayalamMatn": "അദ്ദേഹമാകട്ടെ അത്യുന്നതമായ മണ്ഡലത്തിലായിരുന്നു."}, {"ayahNumber": 8, "quranText": "ثُمَّ دَنَا فَتَدَلَّىٰ\n", "jalalayn": "«ثُمَّ دَنا» قَرُبَ مِنهُ «فَتَدَلّى» زادَ فِي القُرْب", "malayalam": "«പിന്നെ അദ്ദേഹം അടുത്തു, അങ്ങനെ താഴോട്ട് ഇറങ്ങി വന്നു» (നബി ﷺ യുടെ അടുത്തേക്ക്).", "malayalamMatn": "പിന്നെ അദ്ദേഹം അടുത്തു വന്നു. അങ്ങനെ കൂടുതല്‍ അടുത്തു."}, {"ayahNumber": 9, "quranText": "فَكَانَ قَابَ قَوۡسَیۡنِ أَوۡ أَدۡنَىٰ\n", "jalalayn": "«فَكانَ» مِنهُ «قاب» قَدْر «قَوْسَيْنِ أوْ أدْنى» مِن ذَلِكَ حَتّى أفاقَ وسَكَنَ رَوْعَهُ", "malayalam": "«അങ്ങനെ രണ്ടു വില്ലിന്റെ അകലമോ» (അളവോ) «അതിനേക്കാൾ അടുത്തോ ആയിത്തീർന്നു».", "malayalamMatn": "അങ്ങനെ അദ്ദേഹം രണ്ടു വില്ലുകളുടെ അകലത്തിലോ അതിനെക്കാള്‍ അടുത്തോ ആയിരുന്നു."}, {"ayahNumber": 10, "quranText": "فَأَوۡحَىٰۤ إِلَىٰ عَبۡدِهِۦ مَاۤ أَوۡحَىٰ\n", "jalalayn": "«فَأَوْحى» تَعالى «إلى عَبْده» جِبْرِيل «ما أوْحى» جِبْرِيل إلى النَّبِيّ ﷺ ولَمْ يَذْكُر المُوحى تَفْخِيمًا لِشَأْنِهِ", "malayalam": "«അപ്പോൾ അല്ലാഹു തന്റെ ദാസന്» (മുഹമ്മദ് നബി ﷺ ക്ക് ജിബ്‌രീൽ വഴി) «സന്ദേശം നൽകേണ്ടതിനെല്ലാം സന്ദേശം നൽകി».", "malayalamMatn": "അപ്പോള്‍ അവന്‍ (അല്ലാഹു) തന്‍റെ ദാസന് അവന്‍ ബോധനം നല്‍കിയതെല്ലാം ബോധനം നല്‍കി."}, {"ayahNumber": 11, "quranText": "مَا كَذَبَ ٱلۡفُؤَادُ مَا رَأَىٰۤ\n", "jalalayn": "«ما كَذَبَ» بِالتَّخْفِيفِ والتَّشْدِيد أنْكَرَ «الفُؤاد» فُؤاد النَّبِيّ «ما رَأى» بِبَصَرِهِ مِن صُورَة جِبْرِيل", "malayalam": "«അദ്ദേഹം കണ്ടതിനെക്കുറിച്ച്» (തന്റെ കണ്ണുകൊണ്ട് ജിബ്‌രീലിനെ യഥാർത്ഥ രൂപത്തിൽ കണ്ടതിനെ) «ഹൃദയം കളവ് പറഞ്ഞിട്ടില്ല» (അത് പൂർണ്ണ സത്യമായിരുന്നു).", "malayalamMatn": "അദ്ദേഹം കണ്ട ആ കാഴ്ച (അദ്ദേഹത്തിന്‍റെ) ഹൃദയം നിഷേധിച്ചിട്ടില്ല."}, {"ayahNumber": 12, "quranText": "أَفَتُمَـٰرُونَهُۥ عَلَىٰ مَا یَرَىٰ\n", "jalalayn": "«أفَتُمارُونَهُ» تُجادِلُونَهُ وتَغْلِبُونَهُ «عَلى ما يَرى» خِطاب لِلْمُشْرِكِينَ المُنْكِرِينَ رُؤْيَة النَّبِيّ ﷺ لِجِبْرِيل", "malayalam": "«എന്നിരിക്കെ അദ്ദേഹം കാണുന്ന കാര്യത്തെപ്പറ്റി» (മിഅ്‌റാജിലും മറ്റും ദർശിച്ച ദൃഷ്ടാന്തങ്ങളെക്കുറിച്ച്) «നിങ്ങൾ അദ്ദേഹത്തോട് തർക്കിക്കുകയാണോ?»", "malayalamMatn": "എന്നിരിക്കെ അദ്ദേഹം (നേരില്‍) കാണുന്നതിന്‍റെ പേരില്‍ നിങ്ങള്‍ അദ്ദേഹത്തോട് തര്‍ക്കിക്കുകയാണോ?"}, {"ayahNumber": 13, "quranText": "وَلَقَدۡ رَءَاهُ نَزۡلَةً أُخۡرَىٰ\n", "jalalayn": "«ولَقَدْ رَآهُ» عَلى صُورَته «نَزْلَة» مَرَّة", "malayalam": "«തീർച്ചയായും അദ്ദേഹത്തെ മറ്റൊരു ഇറങ്ങലിലും» (മറ്റൊരു പ്രാവശ്യവും) «അദ്ദേഹം കണ്ടിട്ടുണ്ട്» (മിഅ്‌റാജിന്റെ രാത്രിയിൽ തന്റെ യഥാർത്ഥ രൂപത്തിൽ).", "malayalamMatn": "മറ്റൊരു ഇറക്കത്തിലും അദ്ദേഹം മലക്കിനെ കണ്ടിട്ടുണ്ട്‌."}, {"ayahNumber": 14, "quranText": "عِندَ سِدۡرَةِ ٱلۡمُنتَهَىٰ\n", "jalalayn": "«عِنْد سِدْرَة المُنْتَهى» لَمّا أُسْرِيَ بِهِ فِي السَّماوات وهِيَ شَجَرَة نَبْق عَنْ يَمِين العَرْش لا يَتَجاوَزها أحَد مِن المَلائِكَة وغَيْرهمْ", "malayalam": "«സിദ്റത്തുൽ മുൻതഹായുടെ» (ഏഴാം ആകാശത്തുള്ള അതിർത്തിയിലെ ഇലന്തമരത്തിന്റെ) «അടുത്ത് വെച്ച്».", "malayalamMatn": "അറ്റത്തെ ഇലന്തമരത്തിനടുത്ത് വെച്ച്‌"}, {"ayahNumber": 15, "quranText": "عِندَهَا جَنَّةُ ٱلۡمَأۡوَىٰۤ\n", "jalalayn": "«عِنْدها جَنَّة المَأْوى» تَأْوِي إلَيْها المَلائِكَة وأَرْواح الشُّهَداء المُتَّقِينَ", "malayalam": "«അതിന്റെ അടുത്താകുന്നു അഭയകേന്ദ്രമായ സ്വർഗ്ഗം» (സത്യവിശ്വാസികളുടെയും ശുഹദാക്കളുടെയും ആത്മാക്കൾ ചേക്കേറുന്ന ഇടം).", "malayalamMatn": "അതിന്നടുത്താകുന്നു താമസിക്കാനുള്ള സ്വര്‍ഗം."}, {"ayahNumber": 16, "quranText": "إِذۡ یَغۡشَى ٱلسِّدۡرَةَ مَا یَغۡشَىٰ\n", "jalalayn": "«إذْ» حِين وإذْ مَعْمُولَة لِرَآهُ «يَغْشى السِّدْرَة ما يَغْشى» مِن طَيْر وغَيْره", "malayalam": "«ആ ഇലന്തമരത്തെ മൂടുന്നത് മൂടിയപ്പോൾ» (സ്വർണ്ണ പൂമ്പാറ്റകളും അല്ലാഹുവിന്റെ പ്രകാശവും മലക്കുകളും അതിനെ ആവരണം ചെയ്തപ്പോൾ).", "malayalamMatn": "ആ ഇലന്തമരത്തെ ആവരണം ചെയ്യുന്നതൊക്കെ അതിനെ ആവരണം ചെയ്തിരുന്നപ്പോള്‍."}, {"ayahNumber": 17, "quranText": "مَا زَاغَ ٱلۡبَصَرُ وَمَا طَغَىٰ\n", "jalalayn": "«ما زاغَ البَصَر» مِن النَّبِيّ ﷺ «وما طَغى» أيْ ما مالَ بَصَره عَنْ مَرْئِيّه المَقْصُود لَهُ ولا جاوَزَهُ تِلْكَ اللَّيْلَة", "malayalam": "«ദൃഷ്ടി തെറ്റിപ്പോയിട്ടില്ല» (കൽപ്പിക്കപ്പെട്ടതിൽ നിന്ന് വ്യതിചലിച്ചില്ല), «അതിര് കവിഞ്ഞിട്ടുമില്ല» (അനുവദിക്കപ്പെട്ടതിലപ്പുറം കടന്നതുമില്ല).", "malayalamMatn": "(നബിയുടെ) ദൃഷ്ടി തെറ്റിപോയിട്ടില്ല. അതിക്രമിച്ചുപോയിട്ടുമില്ല."}, {"ayahNumber": 18, "quranText": "لَقَدۡ رَأَىٰ مِنۡ ءَایَـٰتِ رَبِّهِ ٱلۡكُبۡرَىٰۤ\n", "jalalayn": "«لَقَدْ رَأى» فِي تِلْكَ اللَّيْلَة «مِن آيات رَبّه الكُبْرى» العِظام أيْ بَعْضها فَرَأى مِن عَجائِب المَلَكُوت رَفْرَفًا أخْضَر سَدَّ أُفُق السَّماء وجِبْرِيل لَهُ سِتّمِائَةِ جَناح", "malayalam": "«തീർച്ചയായും തന്റെ രക്ഷിതാവിന്റെ ഏറ്റവും വലിയ ദൃഷ്ടാന്തങ്ങളിൽ ചിലത് അദ്ദേഹം കാണുകയുണ്ടായി» (ജിബ്‌രീലിന്റെ യഥാർത്ഥ രൂപവും സ്വർഗ്ഗ-നരക കാഴ്ചകളും).", "malayalamMatn": "തീര്‍ച്ചയായും തന്‍റെ രക്ഷിതാവിന്‍റെ അതിമഹത്തായ ദൃഷ്ടാന്തങ്ങളില്‍ ചിലത് അദ്ദേഹം കാണുകയുണ്ടായി."}, {"ayahNumber": 19, "quranText": "أَفَرَءَیۡتُمُ ٱللَّـٰتَ وَٱلۡعُزَّىٰ\n", "jalalayn": "«أَفَرَءَیۡتُمُ ٱللَّـٰتَ وَٱلۡعُزَّىٰ».", "malayalam": "«നിങ്ങൾ കണ്ടുവോ ലാത്തയെയും ഉസ്സയെയും?» (നിങ്ങൾ ആരാധിക്കുന്ന കല്ലുകൊണ്ടുള്ള വിഗ്രഹങ്ങളെക്കുറിച്ച് ആലോചിച്ചുനോക്കൂ).", "malayalamMatn": "ലാത്തയെയും ഉസ്സയെയും പറ്റി നിങ്ങള്‍ ചിന്തിച്ചു നോക്കിയിട്ടുണ്ടോ?"}, {"ayahNumber": 20, "quranText": "وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلۡأُخۡرَىٰۤ\n", "jalalayn": "«ومَناة الثّالِثَة» لِلَّتَيْنِ قَبْلها «الأُخْرى» صِفَة ذَمّ لِلثّالِثَةِ وهِيَ أصْنام مِن حِجارَة كانَ المُشْرِكُونَ يَعْبُدُونَها ويَزْعُمُونَ أنَّها تَشْفَع لَهُمْ عِنْد اللَّه ومَفْعُول أفَرَأَيْتُمْ الأَوَّل اللّاتِي وما عُطِفَ عَلَيْهِ والثّانِي مَحْذُوف والمَعْنى أخْبِرُونِي ألِهَذِهِ الأَصْنام قُدْرَة عَلى شَيْء ما فَتَعْبُدُونَها دُون اللَّه القادِر عَلى ما تَقَدَّمَ ذِكْره ولَمّا زَعَمُوا أيْضًا أنَّ المَلائِكَة بَنات اللَّه مَعَ كَراهَتهمْ البَنات نَزَلَتْ", "malayalam": "«വേറെ മൂന്നാമതായിട്ടുള്ള മനാത്തെയെ പറ്റിയും?» (അവർക്ക് എന്തെങ്കിലും ഉപകാരമോ ഉപദ്രവമോ ചെയ്യാൻ കഴിയുമോ? മലക്കുകൾ പെൺമക്കളാണെന്ന നിങ്ങളുടെ വാദവും ഇതുപോലെ നിരർത്ഥകമാണ്).", "malayalamMatn": "വേറെ മൂന്നാമതായുള്ള മനാത്തയെ പറ്റിയും"}, {"ayahNumber": 21, "quranText": "أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلۡأُنثَىٰ\n", "jalalayn": "«أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلۡأُنثَىٰ».", "malayalam": "«നിങ്ങൾക്ക് ആണും അവന് പെണ്ണുമാണോ?» (നിങ്ങൾ ഇഷ്ടപ്പെടുന്നത് നിങ്ങൾക്കും, നിങ്ങൾ വെറുക്കുന്ന പെൺമക്കളെ അല്ലാഹുവിലേക്ക് ചേർത്തുപറയുകയുമാണോ?).", "malayalamMatn": "(സന്താനമായി) നിങ്ങള്‍ക്ക് ആണും അല്ലാഹുവിന് പെണ്ണുമാണെന്നോ?"}, {"ayahNumber": 22, "quranText": "تِلۡكَ إِذࣰا قِسۡمَةࣱ ضِیزَىٰۤ\n", "jalalayn": "«ضِيزى» جائِرَة مِن ضازَهُ يَضِيزهُ إذا ظَلَمَهُ وجارَ عَلَيْهِ", "malayalam": "«എങ്കിൽ അത് നീതിയില്ലാത്ത ഒരു ഓഹരിവെക്കൽ തന്നെയാണ്!» (അങ്ങേയറ്റം അന്യായമായ വിഭജനം).", "malayalamMatn": "എങ്കില്‍ അത് നീതിയില്ലാത്ത ഒരു ഓഹരി വെക്കല്‍ തന്നെ."}, {"ayahNumber": 23, "quranText": "إِنۡ هِیَ إِلَّاۤ أَسۡمَاۤءࣱ سَمَّیۡتُمُوهَاۤ أَنتُمۡ وَءَابَاۤؤُكُم مَّاۤ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَـٰنٍۚ إِن یَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهۡوَى ٱلۡأَنفُسُۖ وَلَقَدۡ جَاۤءَهُم مِّن رَّبِّهِمُ ٱلۡهُدَىٰۤ\n", "jalalayn": "«إنْ هِيَ» أيْ ما المَذْكُورات «إلّا أسْماء سَمَّيْتُمُوها أنْتُمْ وآباؤُكُمْ» أيْ سَمَّيْتُمْ بِها أصْنامًا تَعْبُدُونَها «ما أنْزَلَ اللَّه بِها» أيْ بِعِبادَتِها «مِن سُلْطان» حُجَّة وبُرْهان «إنْ» ما «يَتَّبِعُونَ» فِي عِبادَتها «إلّا الظَّنّ وما تَهْوى الأَنْفُس» مِمّا زَيَّنَ لَهُمْ الشَّيْطان مِن أنَّها تَشْفَع لَهُمْ عِنْد اللَّه تَعالى «ولَقَدْ جاءَهُمْ مِن رَبِّهُمُ الهُدى» عَلى لِسان النَّبِيّ ﷺ بِالبُرْهانِ القاطِع فَلَمْ يَرْجِعُوا عَمّا هُمْ عَلَيْهِ", "malayalam": "«അവ കേവലം ചില പേരുകൾ മാത്രമാകുന്നു; നിങ്ങളും നിങ്ങളുടെ പിതാക്കളും നൽകിയ പേരുകൾ» (നിങ്ങൾ സ്വയം മെനഞ്ഞുണ്ടാക്കിയ വിഗ്രഹങ്ങൾ). «അല്ലാഹു അവയ്ക്ക് യാതൊരു പ്രമാണവും അവതരിപ്പിച്ചിട്ടില്ല. അവർ ഊഹത്തെയും മനസ്സുകൾ കൊതിക്കുന്നതിനെയുമാണ് പിന്തുടരുന്നത്. തീർച്ചയായും അവർക്ക് തങ്ങളുടെ രക്ഷിതാവിങ്കൽ നിന്ന് സന്മാർഗ്ഗം വന്നിട്ടുണ്ട്» (നബി ﷺ യിലൂടെ വ്യക്തമായ തെളിവുകളോടെ).", "malayalamMatn": "നിങ്ങളും നിങ്ങളുടെ പിതാക്കളും നാമകരണം ചെയ്ത ചില പേരുകളല്ലാതെ മറ്റൊന്നുമല്ല അവ (ദേവതകള്‍.) അവയെപ്പറ്റി അല്ലാഹു യാതൊരു പ്രമാണവും ഇറക്കിതന്നിട്ടില്ല. ഊഹത്തെയും മനസ്സുകള്‍ ഇച്ഛിക്കുന്നതിനെയും മാത്രമാണ് അവര്‍ പിന്തുടരുന്നത്‌. അവര്‍ക്ക് തങ്ങളുടെ രക്ഷിതാവിങ്കല്‍ നിന്ന് സന്‍മാര്‍ഗം വന്നിട്ടുണ്ട് താനും."}, {"ayahNumber": 24, "quranText": "أَمۡ لِلۡإِنسَـٰنِ مَا تَمَنَّىٰ\n", "jalalayn": "«أمْ لِلْإنْسانِ» أيْ لِكُلِّ إنْسان مِنهُمْ «ما تَمَنّى» مِن أنَّ الأَصْنام تَشْفَع لَهُمْ ؟ لَيْسَ الأَمْر كَذَلِكَ", "malayalam": "«അതല്ല, മനുഷ്യൻ കൊതിച്ചതൊക്കെ അവന് ലഭിക്കുമോ?» (വിഗ്രഹങ്ങൾ തങ്ങൾക്ക് ശുപാർശ ചെയ്യുമെന്ന അവരുടെ വ്യാമോഹം ഒരിക്കലും നടക്കില്ല).", "malayalamMatn": "അതല്ല, മനുഷ്യന് അവന്‍ മോഹിച്ചതാണോ ലഭിക്കുന്നത്‌?"}, {"ayahNumber": 25, "quranText": "فَلِلَّهِ ٱلۡـَٔاخِرَةُ وَٱلۡأُولَىٰ\n", "jalalayn": "«فَلِلَّهِ الآخِرَة والأُولى» أيْ الدُّنْيا فَلا يَقَع فِيهِما إلّا ما يُرِيدهُ تَعالى", "malayalam": "«എന്നാൽ അല്ലാഹുവിന്നുള്ളതാകുന്നു പരലോകവും ഇഹലോകവും» (രണ്ടിടത്തും അവന്റെ ഇച്ഛ മാത്രമേ നടപ്പിലാകൂ).", "malayalamMatn": "എന്നാല്‍ അല്ലാഹുവിന്നാകുന്നു ഇഹലോകവും പരലോകവും."}, {"ayahNumber": 26, "quranText": "۞ وَكَم مِّن مَّلَكࣲ فِی ٱلسَّمَـٰوَ ٰ⁠تِ لَا تُغۡنِی شَفَـٰعَتُهُمۡ شَیۡـًٔا إِلَّا مِنۢ بَعۡدِ أَن یَأۡذَنَ ٱللَّهُ لِمَن یَشَاۤءُ وَیَرۡضَىٰۤ\n", "jalalayn": "«وكَمْ مِن مَلَك» أيْ وكَثِير مِن المَلائِكَة «فِي السَّمَوات» وما أكْرَمهمْ عِنْد اللَّه «لا تُغْنِي شَفاعَتهمْ شَيْئًا إلّا مِن بَعْد أنْ يَأْذَن اللَّه» لَهُمْ فِيها «لِمَن يَشاء» مِن عِباده «ويَرْضى» عَنْهُ لِقَوْلِهِ «ولا يَشْفَعُونَ إلّا لِمَنِ ارْتَضى» ومَعْلُوم أنَّها لا تُوجَد مِنهُمْ إلّا بَعْد الإذْن فِيها «مَن ذا الَّذِي يَشْفَع عِنْده إلّا بِإذْنِهِ»", "malayalam": "«ആകാശങ്ങളിൽ എത്രയെത്ര മലക്കുകളാണുള്ളത്! അവരുടെ ശുപാർശ ഒട്ടും പ്രയോജനപ്പെടുകയില്ല; അല്ലാഹു താൻ ഉദ്ദേശിക്കുന്നവർക്ക് അനുവാദം നൽകുകയും തൃപ്തിപ്പെടുകയും ചെയ്ത ശേഷമല്ലാതെ» (അങ്ങനെയെങ്കിൽ വിഗ്രഹങ്ങൾക്കെങ്ങനെ ശുപാർശ ലഭിക്കാനാണ്!).", "malayalamMatn": "ആകാശങ്ങളില്‍ എത്ര മലക്കുകളാണുള്ളത്‌! അവരുടെ ശുപാര്‍ശ യാതൊരു പ്രയോജനവും ചെയ്യുകയില്ല; അല്ലാഹു അവന്‍ ഉദ്ദേശിക്കുകയും തൃപ്തിപ്പെടുകയും ചെയ്യുന്നവര്‍ക്ക് (ശുപാര്‍ശയ്ക്ക്‌) അനുവാദം നല്‍കിയതിന്‍റെ ശേഷമല്ലാതെ."}, {"ayahNumber": 27, "quranText": "إِنَّ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ لَیُسَمُّونَ ٱلۡمَلَـٰۤىِٕكَةَ تَسۡمِیَةَ ٱلۡأُنثَىٰ\n", "jalalayn": "«إنّ الَّذِينَ لا يُؤْمِنُونَ بِالآخِرَةِ لَيُسَمُّونَ المَلائِكَة تَسْمِيَة الأُنْثى» حَيْثُ قالُوا: هُمْ بَنات اللَّه", "malayalam": "«തീർച്ചയായും പരലോകത്തിൽ വിശ്വസിക്കാത്തവരാണ് മലക്കുകൾക്ക് സ്ത്രീനാമങ്ങൾ നൽകുന്നത്» (അവർ അല്ലാഹുവിന്റെ പെൺമക്കളാണെന്ന് ജൽപിച്ചുകൊണ്ട്).", "malayalamMatn": "തീര്‍ച്ചയായും പരലോകത്തില്‍ വിശ്വസിക്കാത്തവര്‍ മലക്കുകള്‍ക്ക് പേരിടുന്നത് സ്ത്രീ നാമങ്ങളാകുന്നു."}, {"ayahNumber": 28, "quranText": "وَمَا لَهُم بِهِۦ مِنۡ عِلۡمٍۖ إِن یَتَّبِعُونَ إِلَّا ٱلظَّنَّۖ وَإِنَّ ٱلظَّنَّ لَا یُغۡنِی مِنَ ٱلۡحَقِّ شَیۡـࣰٔا\n", "jalalayn": "«وما لَهُمْ بِهِ» بِهَذا القَوْل «مِن عِلْم إنْ» ما «يَتَّبِعُونَ» فِيهِ «إلّا الظَّنّ» الَّذِي تَخَيَّلُوهُ «وإنَّ الظَّنّ لا يُغْنِي مِنَ الحَقّ شَيْئًا» أيْ عَنْ العِلْم فِيما المَطْلُوب فِيهِ العِلْم", "malayalam": "«അവർക്ക് അതിനെക്കുറിച്ച് യാതൊരു അറിവുമില്ല. അവർ ഊഹത്തെ മാത്രമാണ് പിന്തുടരുന്നത്. തീർച്ചയായും ഊഹം സത്യത്തിന്റെ സ്ഥാനത്ത് ഒട്ടും ഉപകരിക്കുകയില്ല» (വിശ്വാസപരമായ കാര്യങ്ങളിൽ അറിവാണ് ആവശ്യം).", "malayalamMatn": "അവര്‍ക്ക് അതിനെ പറ്റി യാതൊരു അറിവുമില്ല. അവര്‍ ഊഹത്തെ മാത്രമാകുന്നു പിന്തുടരുന്നത്‌. തീര്‍ച്ചയായും ഊഹം സത്യത്തെ സംബന്ധിച്ചേടത്തോളം ഒട്ടും പ്രയോജനം ചെയ്യുകയില്ല."}, {"ayahNumber": 29, "quranText": "فَأَعۡرِضۡ عَن مَّن تَوَلَّىٰ عَن ذِكۡرِنَا وَلَمۡ یُرِدۡ إِلَّا ٱلۡحَیَوٰةَ ٱلدُّنۡیَا\n", "jalalayn": "«فَأَعْرِضْ عَمَّنْ تَوَلّى عَنْ ذِكْرنا» أيْ القُرْآن «ولَمْ يُرِدْ إلّا الحَياة الدُّنْيا» وهَذا قَبْل الأَمْر بِالجِهادِ", "malayalam": "«ആകയാൽ നമ്മുടെ ഉൽബോധനത്തെ» (ഖുർആനിനെ) «വിട്ട് തിരിഞ്ഞുകളയുകയും ഐഹികജീവിതമല്ലാതെ മറ്റൊന്നും ആഗ്രഹിക്കാതിരിക്കുകയും ചെയ്തവരിൽ നിന്ന് നീ തിരിഞ്ഞുകളയുക».", "malayalamMatn": "ആകയാല്‍ നമ്മുടെ സ്മരണ വിട്ടു തിരിഞ്ഞുകളയുകയും ഐഹികജീവിതം മാത്രം ലക്ഷ്യമാക്കുകയും ചെയ്തവരില്‍ നിന്ന് നീ തിരിഞ്ഞുകളയുക."}, {"ayahNumber": 30, "quranText": "ذَ ٰ⁠لِكَ مَبۡلَغُهُم مِّنَ ٱلۡعِلۡمِۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِیلِهِۦ وَهُوَ أَعۡلَمُ بِمَنِ ٱهۡتَدَىٰ\n", "jalalayn": "«ذَلِكَ» أيْ طَلَب الدُّنْيا «مَبْلَغهمْ مِنَ العِلْم» أيْ نِهايَة عِلْمهمْ أنْ آثَرُوا الدُّنْيا عَلى الآخِرَة «إنّ رَبّك هُوَ أعْلَم بِمَن ضَلَّ عَنْ سَبِيله وهُوَ أعْلَم بِمَنِ اهْتَدى» عالِم بِهِما فَيُجازِيهِما", "malayalam": "«അവരുടെ അറിവിന്റെ പരിധി അതത്രെ» (ഭൗതിക താല്പര്യങ്ങൾക്കപ്പുറം അവർക്കൊന്നുമറിയില്ല). «തീർച്ചയായും നിന്റെ രക്ഷിതാവ് തന്റെ മാർഗ്ഗത്തിൽ നിന്ന് പിഴച്ചുപോയവനെപ്പറ്റി ഏറ്റവും നന്നായി അറിയുന്നവനാണ്. അവൻ സന്മാർഗ്ഗം പ്രാപിച്ചവനെപ്പറ്റിയും ഏറ്റവും നന്നായി അറിയുന്നവനാണ്».", "malayalamMatn": "അറിവില്‍നിന്ന് അവര്‍ ആകെ എത്തിയിട്ടുള്ളത് അത്രത്തോളമാകുന്നു. തീര്‍ച്ചയായും നിന്‍റെ രക്ഷിതാവാകുന്നു അവന്‍റെ മാര്‍ഗത്തില്‍ നിന്ന് തെറ്റിപ്പോയവരെപ്പറ്റി കൂടുതല്‍ അറിവുള്ളവന്‍. സന്‍മാര്‍ഗം പ്രാപിച്ചവരെ പറ്റി കൂടുതല്‍ അറിവുള്ളവനും അവന്‍ തന്നെയാകുന്നു."}, {"ayahNumber": 31, "quranText": "وَلِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِ لِیَجۡزِیَ ٱلَّذِینَ أَسَـٰۤـُٔوا۟ بِمَا عَمِلُوا۟ وَیَجۡزِیَ ٱلَّذِینَ أَحۡسَنُوا۟ بِٱلۡحُسۡنَى\n", "jalalayn": "«ولِلَّهِ ما فِي السَّماوات وما فِي الأَرْض» هُوَ مالِك لِذَلِكَ ومِنهُ الضّالّ والمُهْتَدِي يُضِلّ مَن يَشاء ويَهْدِي مَن يَشاء «لِيَجْزِيَ الَّذِينَ أساءُوا بِما عَمِلُوا» مِن الشِّرْك وغَيْره «ويَجْزِيَ الَّذِينَ أحْسَنُوا» بِالتَّوْحِيدِ وغَيْره مِن الطّاعات «بِالحُسْنى» الجَنَّة وبَيَّنَ المُحْسِنِينَ بِقَوْلِهِ:", "malayalam": "«അല്ലാഹുവിന്നുള്ളതാകുന്നു ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതുമെല്ലാം. തിന്മ പ്രവർത്തിച്ചവർക്ക് അവർ ചെയ്തതനുസരിച്ച് അവൻ പ്രതിഫലം നൽകുവാനും, നന്മ പ്രവർത്തിച്ചവർക്ക് ഏറ്റവും ഉത്തമമായ പ്രതിഫലം» (സ്വർഗ്ഗം) «നൽകുവാനും വേണ്ടിയത്രെ അത്».", "malayalamMatn": "അല്ലാഹുവിന്നുള്ളതാകുന്നു ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതും. തിന്‍മ പ്രവര്‍ത്തിച്ചവര്‍ക്ക് അവര്‍ ചെയ്യുന്നതിനനുസരിച്ച് പ്രതിഫലം നല്‍കുവാന്‍ വേണ്ടിയത്രെ അത്‌. നന്‍മ പ്രവര്‍ത്തിച്ചവര്‍ക്ക് ഏറ്റവും നല്ല പ്രതിഫലം നല്‍കുവാന്‍ വേണ്ടിയും."}, {"ayahNumber": 32, "quranText": "ٱلَّذِینَ یَجۡتَنِبُونَ كَبَـٰۤىِٕرَ ٱلۡإِثۡمِ وَٱلۡفَوَ ٰ⁠حِشَ إِلَّا ٱللَّمَمَۚ إِنَّ رَبَّكَ وَ ٰ⁠سِعُ ٱلۡمَغۡفِرَةِۚ هُوَ أَعۡلَمُ بِكُمۡ إِذۡ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَإِذۡ أَنتُمۡ أَجِنَّةࣱ فِی بُطُونِ أُمَّهَـٰتِكُمۡۖ فَلَا تُزَكُّوۤا۟ أَنفُسَكُمۡۖ هُوَ أَعۡلَمُ بِمَنِ ٱتَّقَىٰۤ\n", "jalalayn": "«الَّذِينَ يَجْتَنِبُونَ كَبائِر الإثْم والفَواحِش إلّا اللَّمَم» هُوَ صِغار الذُّنُوب كالنَّظْرَةِ والقُبْلَة واللَّمْسَة فَهُوَ اسْتِثْناء مُنْقَطِع والمَعْنى لَكِنَّ اللَّمَم يُغْفَر بِاجْتِنابِ الكَبائِر «إنّ رَبّك واسِع المَغْفِرَة» بِذَلِكَ وبِقَبُولِ التَّوْبَة ونَزَلَ فِيمَن كانَ يَقُول: صَلاتنا صِيامنا حَجّنا «هُوَ أعْلَم» أيْ عالِم «بِكُمْ إذْ أنْشَأَكُمْ مِنَ الأَرْض» أيْ خَلَقَ أباكُمْ آدَم مِن التُّراب «وإذْ أنْتُمْ أجِنَّة» جَمْع جَنِين «فَلا تُزَكُّوا أنْفُسكُمْ» لا تَمْدَحُوها عَلى سَبِيل الإعْجاب أمّا عَلى سَبِيل الِاعْتِراف بِالنِّعْمَةِ فَحَسَن «هُوَ أعْلَم» أيْ عالِم", "malayalam": "«വലിയ പാപങ്ങളിൽ നിന്നും നീചവൃത്തികളിൽ നിന്നും വിട്ടുനിൽക്കുന്നവരത്രെ അവർ; ചെറിയ വീഴ്ചകളൊഴികെ» (ചെറിയ തെറ്റുകൾ തൗബയിലൂടെയും വൻപാപങ്ങൾ ഒഴിവാക്കുന്നതിലൂടെയും അവൻ പൊറുത്തുനൽകും). «തീർച്ചയായും നിന്റെ രക്ഷിതാവ് വിശാലമായ പാപമോചനമുള്ളവനത്രെ. അവൻ നിങ്ങളെപ്പറ്റി ഏറ്റവും നന്നായി അറിയുന്നവനാണ്; അവൻ ഭൂമിയിൽ നിന്ന് നിങ്ങളെ സൃഷ്ടിച്ചുണ്ടാക്കിയ സന്ദർഭത്തിലും, നിങ്ങളുടെ മാതാക്കളുടെ വയറുകളിൽ നിങ്ങൾ ഭ്രൂണങ്ങളായിരുന്ന സന്ദർഭത്തിലും. അതിനാൽ നിങ്ങൾ സ്വയം പരിശുദ്ധി ചമയരുത്; ഭയഭക്തിയുള്ളവൻ ആരാണെന്ന് അവനാണ് ഏറ്റവും നന്നായി അറിയുന്നത്».", "malayalamMatn": "അതായത് വലിയ പാപങ്ങളില്‍ നിന്നും, നിസ്സാരമായതൊഴിച്ചുള്ള നീചവൃത്തികളില്‍ നിന്നും വിട്ടകന്നു നില്‍ക്കുന്നവര്‍ക്ക്‌. തീര്‍ച്ചയായും നിന്‍റെ രക്ഷിതാവ് വിശാലമായി പാപമോചനം നല്‍കുന്നവനാകുന്നു. നിങ്ങളെ ഭൂമിയില്‍ നിന്ന് സൃഷ്ടിച്ചുണ്ടാക്കിയ സന്ദര്‍ഭത്തിലും, നിങ്ങള്‍ നിങ്ങളുടെ ഉമ്മമാരുടെ വയറുകളില്‍ ഗര്‍ഭസ്ഥശിശുക്കളായിരിക്കുന്ന സന്ദര്‍ഭത്തിലും അവനാകുന്നു നിങ്ങളെ പറ്റി കൂടുതല്‍ അറിവുള്ളവന്‍. അതിനാല്‍ നിങ്ങള്‍ ആത്മപ്രശംസ നടത്താതിരിക്കുക. അവനാകുന്നു സൂക്ഷ്മത പാലിച്ചവരെപ്പറ്റി നന്നായി അറിയുന്നവന്‍."}, {"ayahNumber": 33, "quranText": "أَفَرَءَیۡتَ ٱلَّذِی تَوَلَّىٰ\n", "jalalayn": "«أفَرَأَيْت الَّذِي تَوَلّى» عَنْ الإيمان ارْتَدَّ لَمّا عُيِّرَ بِهِ وقالَ إنِّي خَشِيت عِقاب اللَّه فَضَمِنَ لَهُ المُعِير لَهُ أنْ يَحْمِل عَنْهُ عَذاب اللَّه إنْ رَجَعَ إلى شِرْكه وأَعْطاهُ مِن ماله كَذا فَرَجَعَ", "malayalam": "«പിന്തിരിഞ്ഞുകളഞ്ഞ ഒരുവനെ നീ കണ്ടുവോ?» (ഇസ്ലാമിലേക്ക് വന്ന ശേഷം പിന്തിരിഞ്ഞുപോയവനെ).", "malayalamMatn": "എന്നാല്‍ പിന്‍മാറിക്കളഞ്ഞ ഒരുത്തനെ നീ കണ്ടുവോ?"}, {"ayahNumber": 34, "quranText": "وَأَعۡطَىٰ قَلِیلࣰا وَأَكۡدَىٰۤ\n", "jalalayn": "«وأَعْطى قَلِيلًا» مِن المال المُسَمّى «وأَكْدى» مَنَعَ الباقِي مَأْخُوذ مِن الكَدِيَّة وهِيَ أرْض صُلْبَة كالصَّخْرَةِ تَمْنَع حافِر البِئْر إذا وصَلَ إلَيْها مِن الحَفْر", "malayalam": "«അവൻ അല്പം ദാനം നൽകുകയും» (സത്യത്തിൽ ഉറച്ചുനിൽക്കാതെ) «പിന്നെ നിർത്തിക്കളയുകയും ചെയ്തു» (പാറയിൽ തട്ടി കിണർ കുഴിക്കൽ നിലച്ചവനെപ്പോലെ).", "malayalamMatn": "അല്‍പമൊക്കെ അവന്‍ ദാനം നല്‍കുകയും എന്നിട്ട് അത് നിര്‍ത്തിക്കളയുകയും ചെയ്തു."}, {"ayahNumber": 35, "quranText": "أَعِندَهُۥ عِلۡمُ ٱلۡغَیۡبِ فَهُوَ یَرَىٰۤ\n", "jalalayn": "«أعِنْده عِلْم الغَيْب فَهُوَ يَرى» يَعْلَم مِن جُمْلَته أنَّ غَيْره يَتَحَمَّل عَنْهُ عَذاب الآخِرَة ؟ لا وهُوَ الوَلِيد بْن المُغِيرَة أوْ غَيْره وجُمْلَة أعِنْده المَفْعُول الثّانِي لِرَأَيْت بِمَعْنى أخْبِرْنِي", "malayalam": "«അവന്റെ പക്കൽ അദൃശ്യജ്ഞാനമുണ്ടായിട്ട് അവൻ കാണുകയാണോ?» (പരലോകത്ത് മറ്റൊരാൾ തന്റെ ശിക്ഷ വഹിക്കുമെന്ന് ഉറപ്പിക്കാൻ അവന് വല്ല ജ്ഞാനവുമുണ്ടോ? ഇല്ല).", "malayalamMatn": "അവന്‍റെ അടുക്കല്‍ അദൃശ്യജ്ഞാനമുണ്ടായിട്ട് അതു മുഖേന അവന്‍ കണ്ടറിഞ്ഞ് കൊണ്ടിരിക്കുകയാണോ?"}, {"ayahNumber": 36, "quranText": "أَمۡ لَمۡ یُنَبَّأۡ بِمَا فِی صُحُفِ مُوسَىٰ\n", "jalalayn": "«أمْ» بَلْ «لَمْ يُنَبَّأ بِما فِي صُحُف مُوسى» أسْفار التَّوْراة أوْ صُحُف قَبْلها", "malayalam": "«അതല്ല, മൂസായുടെ ഏടുകളിലുള്ളതിനെപ്പറ്റി അവൻ വിവരമറിയിക്കപ്പെട്ടിട്ടില്ലയോ?»", "malayalamMatn": "അതല്ല, മൂസായുടെ പത്രികകളില്‍ ഉള്ളതിനെ പറ്റി അവന് വിവരം അറിയിക്കപ്പെട്ടിട്ടില്ലേ?"}, {"ayahNumber": 37, "quranText": "وَإِبۡرَ ٰ⁠هِیمَ ٱلَّذِی وَفَّىٰۤ\n", "jalalayn": "«و» صُحُف «إبْراهِيم الَّذِي وفّى» تَمَّمَ ما أُمِرَ بِهِ نَحْو «وإذِ ابْتَلى إبْراهِيم رَبّه بِكَلِماتٍ فَأَتَمّهنَّ» وبَيان ما", "malayalam": "«കൽപിക്കപ്പെട്ട കടമകളെല്ലാം തികച്ചും നിറവേറ്റിയ ഇബ്രാഹീമിന്റെ ഏടുകളിലുള്ളതിനെപ്പറ്റിയും?»", "malayalamMatn": "(കടമകള്‍) നിറവേറ്റിയ ഇബ്രാഹീമിന്‍റെയും (പത്രികകളില്‍)"}, {"ayahNumber": 38, "quranText": "أَلَّا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰ\n", "jalalayn": "«أ» أنْ «لا تَزِر وازِرَة وِزْر أُخْرى» إلَخْ وأَنْ مُخَفَّفَة مِن الثَّقِيلَة أيْ لا تَحْمِل نَفْس ذَنْب غَيْرها", "malayalam": "«അതായത്, പാപം ചുമക്കുന്ന യാതൊരു ആത്മാവും മറ്റൊരാളുടെ പാപഭാരം ചുമക്കുകയില്ല എന്നതിനെപ്പറ്റി».", "malayalamMatn": "അതായത് പാപഭാരം വഹിക്കുന്ന ഒരാളും മറ്റൊരാളുടെ പാപഭാരം വഹിക്കുകയില്ലെന്നും,"}, {"ayahNumber": 39, "quranText": "وَأَن لَّیۡسَ لِلۡإِنسَـٰنِ إِلَّا مَا سَعَىٰ\n", "jalalayn": "«وأَنْ» أيْ أنَّهُ «لَيْسَ لِلْإنْسانِ إلّا ما سَعى» مِن خَيْر فَلَيْسَ لَهُ مِن سَعْي غَيْره الخَيْر شَيْء", "malayalam": "«മനുഷ്യന് അവൻ പ്രയത്നിച്ചതല്ലാതെ മറ്റൊന്നുമില്ല എന്നതിനെപ്പറ്റിയും».", "malayalamMatn": "മനുഷ്യന്ന് താന്‍ പ്രയത്നിച്ചതല്ലാതെ മറ്റൊന്നുമില്ല എന്നും."}, {"ayahNumber": 40, "quranText": "وَأَنَّ سَعۡیَهُۥ سَوۡفَ یُرَىٰ\n", "jalalayn": "«وأَنَّ سَعْيه سَوْف يُرى» يُبْصَر فِي الآخِرَة", "malayalam": "«അവന്റെ പ്രയത്നഫലം വഴിയെ കാണിച്ചുകൊടുക്കപ്പെടും എന്നതിനെപ്പറ്റിയും» (പരലോക വിചാരണാ വേളയിൽ).", "malayalamMatn": "അവന്‍റെ പ്രയത്നഫലം വഴിയെ കാണിച്ചുകൊടുക്കപ്പെടും എന്നുമുള്ള കാര്യം."}, {"ayahNumber": 41, "quranText": "ثُمَّ یُجۡزَىٰهُ ٱلۡجَزَاۤءَ ٱلۡأَوۡفَىٰ\n", "jalalayn": "«ثُمَّ يُجْزاهُ الجَزاء الأَوْفى» الأَكْمَل يُقال: جَزَيْته سَعْيه وبِسَعْيِهِ", "malayalam": "«പിന്നീട് അവന് തികഞ്ഞ പ്രതിഫലം നൽകപ്പെടുന്നതാണ്».", "malayalamMatn": "പിന്നീട് അവന് അതിന് ഏറ്റവും പൂര്‍ണ്ണമായ പ്രതിഫലം നല്‍കപ്പെടുന്നതാണെന്നും,"}, {"ayahNumber": 42, "quranText": "وَأَنَّ إِلَىٰ رَبِّكَ ٱلۡمُنتَهَىٰ\n", "jalalayn": "«وأَنَّ» بِالفَتْحِ عَطْفًا وقُرِئَ بِالكَسْرِ اسْتِئْنافًا وكَذا ما بَعْدها فَلا يَكُون مَضْمُون الجُمَل فِي الصُّحُف عَلى الثّانِي «إلى رَبّك المُنْتَهى» المَرْجِع والمَصِير بَعْد المَوْت فَيُجازِيهِمْ", "malayalam": "«നിന്റെ രക്ഷിതാവിങ്കലേക്കാണ് സർവ്വരുടെയും തിരിച്ചുവരവ് എന്നതിനെപ്പറ്റിയും».", "malayalamMatn": "നിന്‍റെ രക്ഷിതാവിങ്കലേക്കാണ് എല്ലാം ചെന്ന് അവസാനിക്കുന്നതെന്നും,"}, {"ayahNumber": 43, "quranText": "وَأَنَّهُۥ هُوَ أَضۡحَكَ وَأَبۡكَىٰ\n", "jalalayn": "«وأَنَّهُ هُوَ أضْحَكَ» مَن شاءَ أفْرَحَهُ «وأَبْكى» مَن شاءَ أحْزَنَهُ", "malayalam": "«അവൻ തന്നെയാണ് ചിരിപ്പിക്കുകയും» (സന്തോഷം നൽകുകയും) «കരയിക്കുകയും ചെയ്തത്» (ദുഃഖം നൽകിയത്).", "malayalamMatn": "അവന്‍ തന്നെയാണ് ചിരിപ്പിക്കുകയും കരയിക്കുകയും ചെയ്തതെന്നും,"}, {"ayahNumber": 44, "quranText": "وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحۡیَا\n", "jalalayn": "«وأَنَّهُ هُوَ أماتَ» فِي الدُّنْيا «وأَحْيا» لِلْبَعْثِ", "malayalam": "«അവൻ തന്നെയാണ് മരിപ്പിക്കുകയും» (ഇഹലോകത്ത്) «ജീവിപ്പിക്കുകയും ചെയ്തത്» (പുനരുത്ഥാന നാളിൽ).", "malayalamMatn": "അവന്‍ തന്നെയാണ് മരിപ്പിക്കുകയും ജീവിപ്പിക്കുകയും ചെയ്തതെന്നും,"}, {"ayahNumber": 45, "quranText": "وَأَنَّهُۥ خَلَقَ ٱلزَّوۡجَیۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰ\n", "jalalayn": "«وأَنَّهُ خَلَقَ الزَّوْجَيْنِ» الصِّنْفَيْنِ", "malayalam": "«ആണും പെണ്ണുമാകുന്ന ഇണകളെ അവൻ തന്നെയാണ് സൃഷ്ടിച്ചത്».", "malayalamMatn": "ആണ്‍‍ , പെണ്‍‍ എന്നീ രണ്ട് ഇണകളെ അവനാണ് സൃഷ്ടിച്ചതെന്നും"}, {"ayahNumber": 46, "quranText": "مِن نُّطۡفَةٍ إِذَا تُمۡنَىٰ\n", "jalalayn": "«مِن نُطْفَة» مَنِيّ «إذا تُمْنى» تُصَبّ فِي الرَّحِم", "malayalam": "«ഒരു ബീജത്തിൽ നിന്ന്, അത് ഗർഭാശയത്തിൽ സ്രവിക്കപ്പെടുമ്പോൾ».", "malayalamMatn": "ഒരു ബീജം സ്രവിക്കപ്പെടുമ്പോള്‍ അതില്‍ നിന്ന്‌"}, {"ayahNumber": 47, "quranText": "وَأَنَّ عَلَیۡهِ ٱلنَّشۡأَةَ ٱلۡأُخۡرَىٰ\n", "jalalayn": "«وأَنَّ عَلَيْهِ النَّشْأَة» بِالمَدِّ والقَصْر «الأُخْرى» الخَلْقَة الأُخْرى لِلْبَعْثِ بَعْد الخَلْقَة الأُولى", "malayalam": "«തീർച്ചയായും മറ്റേ സൃഷ്ടിപ്പ്» (പരലോകത്തിലെ ഉയിർത്തെഴുന്നേൽപ്) «അവന്റെ ബാധ്യതയിലുള്ളതാകുന്നു».", "malayalamMatn": "രണ്ടാമത് ജനിപ്പിക്കുക എന്നത് അവന്‍റെ ചുമതലയിലാണെന്നും,"}, {"ayahNumber": 48, "quranText": "وَأَنَّهُۥ هُوَ أَغۡنَىٰ وَأَقۡنَىٰ\n", "jalalayn": "«وأَنَّهُ هُوَ أغْنى» النّاس بِالكِفايَةِ بِالأَمْوالِ «وأَقْنى» أعْطى المال المُتَّخَذ قِنْيَة", "malayalam": "«അവൻ തന്നെയാണ് ധന്യനാക്കുകയും» (ഐശ്വര്യം നൽകുകയും) «സമ്പാദ്യം നൽകുകയും ചെയ്തത്».", "malayalamMatn": "ഐശ്വര്യം നല്‍കുകയും സംതൃപ്തി വരുത്തുകയും ചെയ്തത് അവന്‍ തന്നെയാണ് എന്നും,"}, {"ayahNumber": 49, "quranText": "وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعۡرَىٰ\n", "jalalayn": "«وأَنَّهُ هُوَ رَبّ الشِّعْرى» هُوَ كَوْكَب خَلْف الجَوْزاء كانَتْ تُعْبَد فِي الجاهِلِيَّة", "malayalam": "«അവൻ തന്നെയാണ് ശിഅ്‌റാ എന്ന നക്ഷത്രത്തിന്റെ രക്ഷിതാവ്» (അജ്ഞാനകാലത്ത് ജനങ്ങൾ ആരാധിച്ചിരുന്ന തിളക്കമുള്ള നക്ഷത്രം).", "malayalamMatn": "അവന്‍ തന്നെയാണ് ശിഅ്‌റാ നക്ഷത്രത്തിന്‍റെ രക്ഷിതാവ്‌. എന്നുമുള്ള കാര്യങ്ങള്‍."}, {"ayahNumber": 50, "quranText": "وَأَنَّهُۥۤ أَهۡلَكَ عَادًا ٱلۡأُولَىٰ\n", "jalalayn": "«وأَنَّهُ أهْلَكَ عادًا الأُولى» وفِي قِراءَة بِإدْغامِ التَّنْوِين فِي اللّام وضَمّها بِلا هَمْزَة وهِيَ قَوْم عادٍ والأُخْرى قَوْم صالِح", "malayalam": "«ആദ്യത്തെ ആദ് സമുദായത്തെ അവൻ തന്നെയാണ് നശിപ്പിച്ചത്».", "malayalamMatn": "ആദിമ ജനതയായ ആദിനെ അവനാണ് നശിപ്പിച്ചതെന്നും,"}, {"ayahNumber": 51, "quranText": "وَثَمُودَا۟ فَمَاۤ أَبۡقَىٰ\n", "jalalayn": "«وثَمُودَ» بِالصَّرْفِ اسْم لِلْأَبِ وبِلا صَرْف لِلْقَبِيلَةِ وهُوَ مَعْطُوف عَلى عادًا «فَما أبْقى» مِنهُمْ أحَدًا", "malayalam": "«ഥമൂദ് സമുദായത്തെയും; അവരിൽ ഒരാളെപ്പോലും അവൻ ബാക്കിവെച്ചില്ല».", "malayalamMatn": "ഥമൂദിനെയും. എന്നിട്ട് (ഒരാളെയും) അവന്‍ അവശേഷിപ്പിച്ചില്ല."}, {"ayahNumber": 52, "quranText": "وَقَوۡمَ نُوحࣲ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُوا۟ هُمۡ أَظۡلَمَ وَأَطۡغَىٰ\n", "jalalayn": "«وقَوْم نُوح مِن قَبْل» أيْ قَبْل عادٍ وثَمُود أهْلَكْناهُمْ «إنّهُمْ كانُوا هُمْ أظْلَم وأَطْغى» مِن عادٍ وثَمُود لِطُولِ لُبْث نُوح فِيهِمْ «فَلَبِثَ فِيهِمْ ألْف سَنَة إلّا خَمْسِينَ عامًا» وهُمْ مَعَ عَدَم إيمانهمْ بِهِ يُؤْذُونَهُ ويَضْرِبُونَهُ", "malayalam": "«അതിന് മുമ്പ് നൂഹിന്റെ ജനതയെയും» (അവൻ നശിപ്പിച്ചു); «തീർച്ചയായും അവർ കൂടുതൽ അക്രമികളും കൂടുതൽ ധിക്കാരികളുമായിരുന്നു» (നൂഹ് നബി അവരിൽ 950 വർഷം പ്രബോധനം ചെയ്തിട്ടും അവർ അദ്ദേഹത്തെ ഉപദ്രവിക്കുകയാണുണ്ടായത്).", "malayalamMatn": "അതിന് മുമ്പ് നൂഹിന്‍റെ ജനതയെയും (അവന്‍ നശിപ്പിച്ചു.) തീര്‍ച്ചയായും അവര്‍ കൂടുതല്‍ അക്രമവും, കൂടുതല്‍ ധിക്കാരവും കാണിച്ചവരായിരുന്നു."}, {"ayahNumber": 53, "quranText": "وَٱلۡمُؤۡتَفِكَةَ أَهۡوَىٰ\n", "jalalayn": "«والمُؤْتَفِكَة» وهِيَ قُرى قَوْم لُوط «أهْوى» أسْقَطَها بَعْد رَفْعها إلى السَّماء مَقْلُوبَة إلى الأَرْض بِأَمْرِهِ جِبْرِيل بِذَلِكَ", "malayalam": "«തലകീഴായി മറിഞ്ഞ നാടുകളെയും» (ലൂത്വ് നബിയുടെ ജനതയുടെ ഗ്രാമങ്ങളെ) «അവൻ തകിടംമറിച്ചു തള്ളിക്കളഞ്ഞു» (ആകാശത്തോളം ഉയർത്തി ഭൂമിയിലേക്ക് കീഴ്മേൽ മറിച്ചു).", "malayalamMatn": "കീഴ്മേല്‍ മറിഞ്ഞ രാജ്യത്തെയും, അവന്‍ തകര്‍ത്തു കളഞ്ഞു."}, {"ayahNumber": 54, "quranText": "فَغَشَّىٰهَا مَا غَشَّىٰ\n", "jalalayn": "«فَغَشّاها» مِن الحِجارَة بَعْد ذَلِكَ «ما غَشّى» أُبْهِمَ تَهْوِيلًا وفِي هُود: «جَعَلْنا عالِيها سافِلها وأَمْطَرْنا عَلَيْها حِجارَة مِن سِجِّيل»", "malayalam": "«അങ്ങനെ അവയെ മൂടിയതൊക്കെ മൂടുകയും ചെയ്തു» (ചുട്ടുപഴുത്ത കല്ലുകളുടെ പേമാരികൊണ്ട് അല്ലാഹു അവരെ മൂടിക്കളഞ്ഞു).", "malayalamMatn": "അങ്ങനെ ആ രാജ്യത്തെ അവന്‍ ഭയങ്കരമായ ഒരു (ശിക്ഷയുടെ) ആവരണം കൊണ്ട് പൊതിഞ്ഞു."}, {"ayahNumber": 55, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكَ تَتَمَارَىٰ\n", "jalalayn": "«فَبِأَيِّ آلاء رَبّك» أنْعُمه الدّالَّة عَلى وحْدانِيّته وقُدْرَته «تَتَمارى» تَتَشَكَّك أيّها الإنْسان أوْ تَكْذِب", "malayalam": "«ആകയാൽ നിന്റെ രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെപ്പറ്റിയാണ് നീ തർക്കിക്കുന്നത്?» (ഹേ മനുഷ്യനേ, അവന്റെ ശക്തിയും ഏകത്വവും വ്യക്തമാക്കുന്ന ദൃഷ്ടാന്തങ്ങളിൽ നീ സംശയിക്കുകയാണോ?).", "malayalamMatn": "അപ്പോള്‍ നിന്‍റെ രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതൊന്നിനെപ്പറ്റിയാണ് നീ തര്‍ക്കിച്ചുകൊണ്ടിരിക്കുന്നത്‌?"}, {"ayahNumber": 56, "quranText": "هَـٰذَا نَذِیرࣱ مِّنَ ٱلنُّذُرِ ٱلۡأُولَىٰۤ\n", "jalalayn": "«هَذا» مُحَمَّد «نَذِير مِن النُّذُر الأُولى» مِن جِنْسهمْ أيْ رَسُول كالرُّسُلِ قَبْله أرْسَلَ إلَيْكُمْ كَما أرْسَلُوا إلى أقْوامهمْ", "malayalam": "«ഇദ്ദേഹം» (മുഹമ്മദ് നബി ﷺ) «പൂർവ്വകാല താക്കീതുകാരിൽപെട്ട ഒരു താക്കീതുകാരനത്രെ» (മുൻകഴിഞ്ഞ പ്രവാചകന്മാരെപ്പോലെ അല്ലാഹുവിന്റെ സന്ദേശമെത്തിക്കാൻ നിയോഗിക്കപ്പെട്ട റസൂൽ).", "malayalamMatn": "ഇദ്ദേഹം (മുഹമ്മദ് നബി) പൂര്‍വ്വികരായ താക്കീതുകാരുടെ കൂട്ടത്തില്‍ പെട്ട ഒരു താക്കീതുകാരന്‍ ആകുന്നു."}, {"ayahNumber": 57, "quranText": "أَزِفَتِ ٱلۡـَٔازِفَةُ\n", "jalalayn": "«أزِفَتِ الآزِفَة» قَرُبَتْ القِيامَة", "malayalam": "«ആസന്നമായ ആ സംഭവം» (ഖിയാമത്ത് നാൾ) «ഇതാ അടുത്തു കഴിഞ്ഞു».", "malayalamMatn": "സമീപസ്ഥമായ ആ സംഭവം ആസന്നമായിരിക്കുന്നു."}, {"ayahNumber": 58, "quranText": "لَیۡسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ\n", "jalalayn": "«لَيْسَ لَها مِن دُون اللَّه» نَفْس «كاشِفَة» أيْ لا يَكْشِفها ويُظْهِرها إلّا هُوَ كَقَوْلِهِ «لا يُجَلِّيها لِوَقْتِها إلّا هُوَ»", "malayalam": "«അല്ലാഹുവിന് പുറമെ അതിനെ തടഞ്ഞുനിർത്താനോ വെളിപ്പെടുത്താനോ ആരുമില്ല» (അതിന്റെ സമയം അറിയുന്നവനും അത് കൊണ്ടുവരുന്നവനും അവൻ മാത്രം).", "malayalamMatn": "അല്ലാഹുവിന് പുറമെ അതിനെ തട്ടിനീക്കാന്‍ ആരുമില്ല."}, {"ayahNumber": 59, "quranText": "أَفَمِنۡ هَـٰذَا ٱلۡحَدِیثِ تَعۡجَبُونَ\n", "jalalayn": "«أفَمِن هَذا الحَدِيث» أيْ القُرْآن «تَعْجَبُونَ» تَكْذِيبًا", "malayalam": "«അപ്പോൾ ഈ വർത്തമാനത്തെപ്പറ്റിയാണോ» (മഹത്തായ ഖുർആനിനെക്കുറിച്ചാണോ) «നിങ്ങൾ അത്ഭുതപ്പെടുന്നത്?» (അവിശ്വസിച്ചുകൊണ്ട്).", "malayalamMatn": "അപ്പോള്‍ ഈ വാര്‍ത്തയെപ്പറ്റി നിങ്ങള്‍ അത്ഭുതപ്പെടുകയും,"}, {"ayahNumber": 60, "quranText": "وَتَضۡحَكُونَ وَلَا تَبۡكُونَ\n", "jalalayn": "«وتَضْحَكُونَ» اسْتِهْزاء «ولا تَبْكُونَ» لِسَماعِ وعْده ووَعِيده", "malayalam": "«നിങ്ങൾ ചിരിക്കുകയും ചെയ്യുന്നു, നിങ്ങൾ കരയുന്നതുമില്ല!» (അതിലെ താക്കീതുകളും വാഗ്ദാനങ്ങളും കേട്ടിട്ടും).", "malayalamMatn": "നിങ്ങള്‍ ചിരിച്ച് കൊണ്ടിരിക്കുകയും നിങ്ങള്‍ കരയാതിരിക്കുകയും,"}, {"ayahNumber": 61, "quranText": "وَأَنتُمۡ سَـٰمِدُونَ\n", "jalalayn": "«وأَنْتُمْ سامِدُونَ» لاهُونَ غافِلُونَ عَمّا يُطْلَب مِنكُمْ", "malayalam": "«നിങ്ങളാകട്ടെ അശ്രദ്ധയിൽ മുഴുകിയവരുമാണ്» (കളിതമാശകളിൽ ആമഗ്നരായി കഴിയുന്നു).", "malayalamMatn": "നിങ്ങള്‍ അശ്രദ്ധയില്‍ കഴിയുകയുമാണോ?."}, {"ayahNumber": 62, "quranText": "فَٱسۡجُدُوا۟ لِلَّهِ وَٱعۡبُدُوا۟ ۩\n", "jalalayn": "«فاسْجُدُوا لِلَّهِ» الَّذِي خَلَقَكُمْ «واعْبُدُوا» ولا تَسْجُدُوا لِلْأَصْنامِ ولا تَعْبُدُوها", "malayalam": "«ആകയാൽ നിങ്ങൾ» (നിങ്ങളെ സൃഷ്ടിച്ച) «അല്ലാഹുവിന് സാഷ്ടാംഗം ചെയ്യുകയും അവനെ ആരാധിക്കുകയും ചെയ്യുവിൻ!» (വിഗ്രഹങ്ങളെ വെടിഞ്ഞ് അവന് മാത്രം വഴിപ്പെടുവിൻ).", "malayalamMatn": "അതിനാല്‍ നിങ്ങള്‍ അല്ലാഹുവിന് പ്രണാമം ചെയ്യുകയും (അവനെ) ആരാധിക്കുകയും ചെയ്യുവിന്‍."}], "topPoints": ["നബി(സ)യുടെ മിഅ്‌റാജ് യാത്രയുടെ സത്യസന്ധത", "അല്ലാഹുവിന്റെ അപാരമായ ശക്തിയും അറിവും"], "topQuestions": [{"q": "സൂറത്തുന്നജ്മിൽ പ്രധാനമായും പ്രതിപാദിക്കുന്നത് എന്താണ്?", "a": "പ്രവാചകത്വത്തിന്റെ സത്യതയും പരലോകവുമെല്ലാമാണ് ഇതിലെ പ്രധാന വിഷയം."}], "asbabAlNuzul": [{"ayahNumber": 20, "quranText": "أَفَرَءَیۡتُمُ ٱللَّـٰتَ وَٱلۡعُزَّىٰ • وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلۡأُخۡرَىٰۤ", "arabicSnippet": "«ومناة الثالثة» للتين قبلها «الأخرى» صفة ذم للثالثة وهي أصنام من حجارة كان المشركون يعبدونها ويزعمون أنها تشفع لهم عند الله... ولما زعموا أيضا أن الملائكة بنات الله مع كراهتهم البنات نزلت.", "malayalamExplanation": "ഖുറൈശി മുശ്‌രിക്കുകൾ ലാത, ഉസ്സ, മനാത തുടങ്ങിയ വിഗ്രഹങ്ങളെ ആരാധിക്കുകയും, അതോടൊപ്പം 'മലക്കുകൾ അല്ലാഹുവിന്റെ പെൺമക്കളാണ്' എന്ന് ജൽപിക്കുകയും ചെയ്തു. എന്നാൽ തങ്ങൾക്ക് പെൺമക്കൾ ജനിക്കുന്നത് അവർ കഠിനമായി വെറുക്കുകയും ജീവനോടെ കുഴിച്ചുമൂടുകയും ചെയ്തിരുന്നു. തങ്ങൾ വെറുക്കുന്ന പെൺമക്കളെ അല്ലാഹുവിന് ചാർത്തിക്കൊടുക്കുകയും വിഗ്രഹങ്ങളെ ഇടയാളന്മാരാക്കുകയും ചെയ്ത ഇവരുടെ ഇരട്ടത്താപ്പിനെയും വിഗ്രഹാരാധനയെയും ശക്തമായി ഖണ്ഡിച്ചുകൊണ്ടാണ് ഈ സൂക്തങ്ങൾ അവതരിച്ചത്."}, {"ayahNumber": 32, "quranText": "فَلَا تُزَكُّوۤا۟ أَنفُسَكُمۡۖ هُوَ أَعۡلَمُ بِمَنِ ٱتَّقَىٰۤ", "arabicSnippet": "«الذين يجتنبون كبائر الإثم والفواحش إلا الَّلمَمَ»... ونزل فيمن كان يقول: صلاتنا صيامنا حجنا: «هو أعلم بكم إذ أنشأكم من الأرض وإذ أنتم أجنة في بطون أمهاتكم فلا تزكوا أنفسكم هو أعلم بمن اتقى».", "malayalamExplanation": "ചില ആളുകൾ \"ഞങ്ങളുടെ നമസ്കാരം, ഞങ്ങളുടെ നോമ്പ്, ഞങ്ങളുടെ ഹജ്ജ്...\" എന്നിങ്ങനെ തങ്ങളുടെ സൽകർമ്മങ്ങളെ സ്വയം എടുത്തുപറഞ്ഞ് വലിയ ഭക്തന്മാരായി അഹംഭാവത്തോടെ സ്വയം പുകഴ്ത്തിപ്പറഞ്ഞിരുന്നു. ഇതിനെ തിരുത്തിക്കൊണ്ട്, മനുഷ്യൻ ആത്മാർത്ഥതയോടെയുള്ള ഭയഭക്തി (തഖ്‌വ) ഉള്ളവനാണോ എന്ന് ഏറ്റവും നന്നായി അറിയുന്നത് അല്ലാഹു മാത്രമാണെന്നും അതിനാൽ ആരും സ്വയം പരിശുദ്ധി ചമയരുതെന്നും പഠിപ്പിച്ചുകൊണ്ട് ഈ വചനം അവതരിച്ചു."}]}, {"surahNumber": 54, "surahNameArabic": "سُورَةُ القَمَرِ", "surahNameMalayalam": "സൂറത്തുൽ ഖമർ (ചന്ദ്രൻ)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ ٱقۡتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلۡقَمَرُ\n", "jalalayn": "«اقْتَرَبَتِ السّاعَة» قَرُبَتْ القِيامَة «وانْشَقَّ القَمَر» انْفَلَقَ فِلْقَتَيْنِ عَلى أبِي قُبَيْسٍ وقَيْقَعانَ آيَة لَهُ ﷺ وقَدْ سُئِلَها فَقالَ \"اشْهَدُوا\" رَواهُ الشَّيْخانِ", "malayalam": "«അന്ത്യസമയം അടുത്തു» (ഖിയാമത്ത് നാൾ ആസന്നമായി), «ചന്ദ്രൻ പിളരുകയും ചെയ്തു» (നബി ﷺ യുടെ മുഅ്ജിസത്തായി അബൂഖുബൈസ്, ഖുഐഖിആൻ എന്നീ പർവ്വതങ്ങൾക്ക് മീതെ രണ്ട് കഷ്ണങ്ങളായി പിളർന്നു; നബി ﷺ 'നിങ്ങൾ സാക്ഷ്യം വഹിക്കുവിൻ' എന്ന് ജനങ്ങളോട് പറഞ്ഞു - ബുഖാരിയും മുസ്‌ലിമും ഉദ്ധരിച്ചത്).", "malayalamMatn": "ആ (അന്ത്യ) സമയം അടുത്തു. ചന്ദ്രന്‍ പിളരുകയും ചെയ്തു."}, {"ayahNumber": 2, "quranText": "وَإِن یَرَوۡا۟ ءَایَةࣰ یُعۡرِضُوا۟ وَیَقُولُوا۟ سِحۡرࣱ مُّسۡتَمِرࣱّ\n", "jalalayn": "«وإنْ يَرَوْا» أيْ كُفّار قُرَيْش «آيَة» مُعْجِزَة لَهُ ﷺ «يُعْرِضُوا ويَقُولُوا» هَذا «سِحْر مُسْتَمِرّ» قَوِيّ مِن المِرَّة: القُوَّة أوْ دائِم", "malayalam": "«ഏതൊരു ദൃഷ്ടാന്തം അവർ കാണുകയാണെങ്കിലും» (മുഅ്ജിസത്ത് നേരിൽ കണ്ടാലും ഖുറൈശികൾ) «അവർ പിന്തിരിഞ്ഞു കളയുകയും, ഇത് നിലനിന്നു വരുന്ന ശക്തമായ ജാലവിദ്യയാകുന്നു എന്ന് അവർ പറയുകയും ചെയ്യും».", "malayalamMatn": "ഏതൊരു ദൃഷ്ടാന്തം അവര്‍ കാണുകയാണെങ്കിലും അവര്‍ പിന്തിരിഞ്ഞു കളയുകയും, ഇത് നിലനിന്നു വരുന്ന ജാലവിദ്യയാകുന്നു എന്ന് അവര്‍ പറയുകയും ചെയ്യും."}, {"ayahNumber": 3, "quranText": "وَكَذَّبُوا۟ وَٱتَّبَعُوۤا۟ أَهۡوَاۤءَهُمۡۚ وَكُلُّ أَمۡرࣲ مُّسۡتَقِرࣱّ\n", "jalalayn": "«وكَذَّبُوا» النَّبِيّ ﷺ «واتَّبَعُوا أهْواءَهُمْ» فِي الباطِل «وكُلّ أمْر» مِن الخَيْر والشَّرّ «مُسْتَقِرّ» بِأَهْلِهِ فِي الجَنَّة أوْ النّار", "malayalam": "«അവർ» (പ്രവാചകനെ) «നിഷേധിച്ചു തള്ളുകയും തങ്ങളുടെ തന്നിഷ്ടങ്ങളെ പിൻപറ്റുകയും ചെയ്തിരിക്കുന്നു. എന്നാൽ ഏതൊരു കാര്യവും ഒരു നിശ്ചിത സ്ഥാനം പ്രാപിക്കുന്നതാകുന്നു» (നന്മ ചെയ്തവർക്ക് സ്വർഗ്ഗവും തിന്മ ചെയ്തവർക്ക് നരകവും എത്തിച്ചേരുക തന്നെ ചെയ്യും).", "malayalamMatn": "അവര്‍ നിഷേധിച്ചു തള്ളുകയും തങ്ങളുടെ തന്നിഷ്ടങ്ങളെ പിന്‍പറ്റുകയും ചെയ്തിരിക്കുന്നു. ഏതൊരു കാര്യവും ഒരു നിശ്ചിത സ്ഥാനം പ്രാപിക്കുന്നതാകുന്നു."}, {"ayahNumber": 4, "quranText": "وَلَقَدۡ جَاۤءَهُم مِّنَ ٱلۡأَنۢبَاۤءِ مَا فِیهِ مُزۡدَجَرٌ\n", "jalalayn": "«ولَقَدْ جاءَهُمْ مِنَ الأَنْباء» أخْبار إهْلاك الأُمَم المُكَذِّبَة رُسُلهمْ «ما فِيهِ مُزْدَجَر» لَهُمْ اسْم مَصْدَر أوْ اسْم مَكان والدّال بَدَل مِن تاء الِافْتِعال وازْدَجَرْته وزَجَرْته: نَهَيْته بِغِلْظَةٍ وما مَوْصُولَة أوْ مَوْصُوفَة", "malayalam": "«തീർച്ചയായും അവരെ പിന്തിരിപ്പിക്കാൻ പര്യാപ്തമായ താക്കീതുകൾ ഉൾക്കൊള്ളുന്ന വിവരങ്ങൾ» (മുൻകാല ജനതകൾക്ക് സംഭവിച്ച നാശത്തിന്റെ ചരിത്രം) «അവർക്ക് വന്നെത്തിയിട്ടുണ്ട്».", "malayalamMatn": "(ദൈവ നിഷേധത്തില്‍ നിന്ന്‌) അവര്‍ ഒഴിഞ്ഞു നില്‍ക്കാന്‍ പര്യാപ്തമായ കാര്യങ്ങളടങ്ങിയ ചില വൃത്താന്തങ്ങള്‍ തീര്‍ച്ചയായും അവര്‍ക്ക് വന്നുകിട്ടിയിട്ടുണ്ട്‌."}, {"ayahNumber": 5, "quranText": "حِكۡمَةُۢ بَـٰلِغَةࣱۖ فَمَا تُغۡنِ ٱلنُّذُرُ\n", "jalalayn": "«حِكْمَة» خَبَر مُبْتَدَأ مَحْذُوف أوْ بَدَل مِن ما أوْ مِن مُزْدَجَر «بالِغَة» تامَّة «فَما تُغْنِ» تَنْفَع فِيهِمْ ما لِلنَّفْيِ أوْ لِلِاسْتِفْهامِ الإنْكارِيّ وهِيَ عَلى الثّانِي مَفْعُول مُقَدَّم «النُّذُر» جَمْع نَذِير بِمَعْنى مُنْذِر أيْ الأُمُور المُنْذِرَة لَهُمْ", "malayalam": "«അത് അത്യഗാധമായ ജ്ഞാനമാകുന്നു; എന്നാൽ ആ താക്കീതുകൾ അവർക്കൊന്നും ഉപകരിക്കുന്നില്ല!» (നിഷേധികളായ ജനങ്ങൾക്ക്).", "malayalamMatn": "അതെ, പരിപൂര്‍ണ്ണമായ വിജ്ഞാനം. എന്നിട്ടും താക്കീതുകള്‍ പര്യാപ്തമാകുന്നില്ല."}, {"ayahNumber": 6, "quranText": "فَتَوَلَّ عَنۡهُمۡۘ یَوۡمَ یَدۡعُ ٱلدَّاعِ إِلَىٰ شَیۡءࣲ نُّكُرٍ\n", "jalalayn": "«فَتَوَلَّ عَنْهُمْ» هُوَ فائِدَة ما قَبْله وتَمَّ بِهِ الكَلام «يَوْم يَدْعُ الدّاعِي» هُوَ إسْرافِيل وناصِب يَوْم يَخْرُجُونَ بَعْد «إلى شَيْء نُكُر» بِضَمِّ الكاف وسُكُونها أيْ مُنْكَر تُنْكِرهُ النُّفُوس وهُوَ الحِساب", "malayalam": "«ആകയാൽ നീ അവരിൽ നിന്ന് തിരിഞ്ഞുകളയുക. വിളിക്കുന്നവൻ വെറുക്കപ്പെട്ട ഒരു കാര്യത്തിലേക്ക്» (ഭയങ്കരമായ വിചാരണയിലേക്ക്) «വിളിക്കുന്ന ദിവസം».", "malayalamMatn": "ആകയാല്‍ (നബിയേ,) നീ അവരില്‍ നിന്ന് പിന്തിരിഞ്ഞ് കളയുക. അനിഷ്ടകരമായ ഒരു കാര്യത്തിലേക്ക് വിളിക്കുന്നവന്‍ വിളിക്കുന്ന ദിവസം."}, {"ayahNumber": 7, "quranText": "خُشَّعًا أَبۡصَـٰرُهُمۡ یَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ كَأَنَّهُمۡ جَرَادࣱ مُّنتَشِرࣱ\n", "jalalayn": "«خُشَّعًا» أيْ ذَلِيلًا وفِي قِراءَة خُشَّعًا بِضَمِّ الخاء وفَتْح الشِّين مُشَدَّدَة «أبْصارهمْ» حال مِن الفاعِل «يَخْرُجُونَ» أيْ النّاس «مِنَ الأَجْداث» القُبُور «كَأَنَّهُمْ جَراد مُنْتَشِر» لا يَدْرُونَ أيْنَ يَذْهَبُونَ مِن الخَوْف والحِيرَة والجُمْلَة حال مِن فاعِل يَخْرُجُونَ", "malayalam": "«അവരുടെ കണ്ണുകൾ താഴ്ന്ന നിലയിൽ, ചിതറിപ്പരന്ന വെട്ടുക്കിളികളെപ്പോലെ അവർ ഖബറുകളിൽ നിന്ന് പുറത്തു വരും».", "malayalamMatn": "ദൃഷ്ടികള്‍ താഴ്ന്നു പോയവരായ നിലയില്‍ ഖബ്‌റുകളില്‍ നിന്ന് (നാലുപാടും) പരന്ന വെട്ടുകിളികളെന്നോണം അവര്‍ പുറപ്പെട്ട് വരും."}, {"ayahNumber": 8, "quranText": "مُّهۡطِعِینَ إِلَى ٱلدَّاعِۖ یَقُولُ ٱلۡكَـٰفِرُونَ هَـٰذَا یَوۡمٌ عَسِرࣱ\n", "jalalayn": "«مُهْطِعِينَ» مُسْرِعِينَ مادِّينِ أعْناقهمْ «إلى الدّاعِ يَقُول الكافِرُونَ» مِنهُمْ «هَذا يَوْم عَسِر» صَعْب عَلى الكافِرِينَ كَما فِي المُدَّثِّر «يَوْم عَسِير عَلى الكافِرِينَ»", "malayalam": "«ആ വിളിക്കുന്ന ആളുടെ അടുത്തേക്ക് അവർ ധൃതിപ്പെട്ട് ഓടുന്നവരായിരിക്കും. സത്യനിഷേധികൾ പറയും: ഇത് വളരെ പ്രയാസകരമായ ഒരു ദിവസമാകുന്നു!»", "malayalamMatn": "വിളിക്കുന്നവന്‍റെ അടുത്തേക്ക് അവര്‍ ധൃതിപ്പെട്ട് ചെല്ലുന്നവരായിരിക്കും. സത്യനിഷേധികള്‍ (അന്ന്‌) പറയും: ഇതൊരു പ്രയാസകരമായ ദിവസമാകുന്നു."}, {"ayahNumber": 9, "quranText": "۞ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ فَكَذَّبُوا۟ عَبۡدَنَا وَقَالُوا۟ مَجۡنُونࣱ وَٱزۡدُجِرَ\n", "jalalayn": "«كَذَّبَتْ قَبْلهمْ» قَبْل قُرَيْش «قَوْم نُوح» وتَأْنِيث الفِعْل كَذَّبَتْ لِمَعْنى قَوْم «فَكَذَّبُوا عَبْدنا» نُوحًا «وقالُوا مَجْنُون وازْدُجِرَ» انْتَهَرُوهُ بِالسَّبِّ وغَيْره", "malayalam": "«ഇവർക്ക് മുമ്പ് നൂഹിന്റെ ജനതയും നിഷേധിച്ചു കളഞ്ഞു; അവർ നമ്മുടെ ദാസനെ നിഷേധിക്കുകയും ഭ്രാന്തൻ എന്ന് വിളിക്കുകയും ചെയ്തു. അദ്ദേഹം ആട്ടിയോടിക്കപ്പെടുകയും ചെയ്തു».", "malayalamMatn": "അവര്‍ക്ക് മുമ്പ് നൂഹിന്‍റെ ജനതയും നിഷേധിച്ചു കളഞ്ഞിട്ടുണ്ട്‌. അങ്ങനെ നമ്മുടെ ദാസനെ അവര്‍ നിഷേധിച്ച് തള്ളുകയും ഭ്രാന്തന്‍ എന്നു പറയുകയും ചെയ്തു. അദ്ദേഹം വിരട്ടി ഓടിക്കപ്പെടുകയും ചെയ്തു."}, {"ayahNumber": 10, "quranText": "فَدَعَا رَبَّهُۥۤ أَنِّی مَغۡلُوبࣱ فَٱنتَصِرۡ\n", "jalalayn": "«فَدَعا رَبّه أنِّي» بِالفَتْحِ أيْ بِأَنِّي", "malayalam": "«അപ്പോൾ അദ്ദേഹം തന്റെ രക്ഷിതാവിനെ വിളിച്ചു പ്രാർത്ഥിച്ചു: ഞാൻ പരാജിതനാകുന്നു, അതിനാൽ നീ എന്നെ സഹായിക്കേണമേ!»", "malayalamMatn": "അപ്പോള്‍ അദ്ദേഹം തന്‍റെ രക്ഷിതാവിനെ വിളിച്ചു പ്രാര്‍ത്ഥിച്ചു: ഞാന്‍ പരാജിതനാകുന്നു. അതിനാല്‍ (എന്‍റെ) രക്ഷയ്ക്കായി നീ നടപടി സ്വീകരിക്കണമേ."}, {"ayahNumber": 11, "quranText": "فَفَتَحۡنَاۤ أَبۡوَ ٰ⁠بَ ٱلسَّمَاۤءِ بِمَاۤءࣲ مُّنۡهَمِرࣲ\n", "jalalayn": "«فَفَتَحْنا» بِالتَّخْفِيفِ والتَّشْدِيد «أبْواب السَّماء بِماءٍ مُنْهَمِر» مُنْصَبّ انْصِبابًا شَدِيدًا", "malayalam": "«അപ്പോൾ ശക്തിയായി ഒഴുകുന്ന വെള്ളം കൊണ്ട് നാം ആകാശത്തിന്റെ കവാടങ്ങൾ തുറന്നു കൊടുത്തു».", "malayalamMatn": "അപ്പോള്‍ കുത്തിച്ചൊരിയുന്ന വെള്ളവും കൊണ്ട് ആകാശത്തിന്‍റെ കവാടങ്ങള്‍ നാം തുറന്നു."}, {"ayahNumber": 12, "quranText": "وَفَجَّرۡنَا ٱلۡأَرۡضَ عُیُونࣰا فَٱلۡتَقَى ٱلۡمَاۤءُ عَلَىٰۤ أَمۡرࣲ قَدۡ قُدِرَ\n", "jalalayn": "«وفَجَّرْنا الأَرْض عُيُونًا» تَنْبُع «فالتَقى الماء» ماء السَّماء والأَرْض «عَلى أمْر» حال «قَدْ قُدِرَ» قُضِيَ بِهِ فِي الأَزَل وهُوَ هَلاكهمْ غَرَقًا", "malayalam": "«ഭൂമിയിൽ നിന്ന് നാം ഉറവകൾ പൊട്ടിക്കുകയും ചെയ്തു. അങ്ങനെ മുൻകൂട്ടി നിർണ്ണയിക്കപ്പെട്ട ഒരു കാര്യത്തിനായി വെള്ളം സന്ധിച്ചു» (ജനങ്ങളെ മുക്കിക്കൊല്ലാൻ).", "malayalamMatn": "ഭൂമിയില്‍ നാം ഉറവുകള്‍ പൊട്ടിക്കുകയും ചെയ്തു. അങ്ങനെ നിര്‍ണയിക്കപ്പെട്ടു കഴിഞ്ഞ ഒരു കാര്യത്തിന്നായി വെള്ളം സന്ധിച്ചു."}, {"ayahNumber": 13, "quranText": "وَحَمَلۡنَـٰهُ عَلَىٰ ذَاتِ أَلۡوَ ٰ⁠حࣲ وَدُسُرࣲ\n", "jalalayn": "«وحَمَلْناهُ» أيْ نُوحًا «عَلى» سَفِينَة «ذات ألْواح ودُسُر» وهُوَ ما تُشَدّ بِهِ الأَلْواح مِن المَسامِير وغَيْرها وأَحَدها دِسار كَكِتابٍ", "malayalam": "«പലകകളും ആണികളും കൊണ്ട് നിർമ്മിക്കപ്പെട്ട ഒരു കപ്പലിൽ അദ്ദേഹത്തെ നാം കയറ്റി വഹിച്ചു».", "malayalamMatn": "പലകകളും ആണികളുമുള്ള ഒരു കപ്പലില്‍ അദ്ദേഹത്തെ നാം വഹിക്കുകയും ചെയ്തു."}, {"ayahNumber": 14, "quranText": "تَجۡرِی بِأَعۡیُنِنَا جَزَاۤءࣰ لِّمَن كَانَ كُفِرَ\n", "jalalayn": "«تَجْرِي بِأَعْيُنِنا» بِمَرْأى مِنّا أيْ مَحْفُوظَة «جَزاء» مَنصُوب بِفِعْلٍ مُقَدَّر أيْ أُغْرِقُوا انْتِصارًا «لِمَن كانَ كُفِرَ» وهُوَ نُوح عَلَيْهِ السَّلام وقُرِئَ كَفَرَ بِالبِناءِ لِلْفاعِلِ أيْ أُغْرِقُوا عِقابًا لَهُمْ", "malayalam": "«നമ്മുടെ മേൽനോട്ടത്തിൽ അത് സഞ്ചരിച്ചുകൊണ്ടിരുന്നു; നിഷേധിക്കപ്പെട്ടു കഴിഞ്ഞിരുന്ന ആ പ്രവാചകന് പ്രതിഫലമായിക്കൊണ്ട്».", "malayalamMatn": "നമ്മുടെ മേല്‍നോട്ടത്തില്‍ അത് സഞ്ചരിക്കുന്നു. നിഷേധിച്ചു തള്ളപ്പെട്ടിരുന്നവന്നു (ദൈവദൂതന്ന്‌) ഉള്ള പ്രതിഫലമത്രെ അത്‌."}, {"ayahNumber": 15, "quranText": "وَلَقَد تَّرَكۡنَـٰهَاۤ ءَایَةࣰ فَهَلۡ مِن مُّدَّكِرࣲ\n", "jalalayn": "«ولَقَدْ تَرَكْناها» أبْقَيْنا هَذِهِ الفِعْلَة «آيَة» لِمَن يَعْتَبِر بِها أيْ شاعَ خَبَرها واسْتَمَرَّ «فَهَلْ مِن مُدَّكِر» مُعْتَبِر ومُتَّعِظ بِها وأَصْله مُذْتَكِرٌ أُبْدِلَتْ التّاء دالًا مُهْمَلَة وكَذا المُعْجَمَة وأُدْغِمَتْ فِيها", "malayalam": "«തീർച്ചയായും അതിനെ നാം ഒരു ദൃഷ്ടാന്തമായി അവശേഷിപ്പിച്ചിരിക്കുന്നു; എന്നാൽ ചിന്തിച്ചു മനസ്സിലാക്കുന്നവരായി ആരെങ്കിലുമുണ്ടോ?»", "malayalamMatn": "തീര്‍ച്ചയായും അതിനെ(പ്രളയത്തെ)നാം ഒരു ദൃഷ്ടാന്തമായി അവശേഷിപ്പിച്ചിരിക്കുന്നു. എന്നാല്‍ ആലോചിച്ച് മനസ്സിലാക്കുന്നവരായി ആരെങ്കിലുമുണ്ടോ?"}, {"ayahNumber": 16, "quranText": "فَكَیۡفَ كَانَ عَذَابِی وَنُذُرِ\n", "jalalayn": "«فَكَيْفَ كانَ عَذابِي ونُذُر» أيْ إنْذارِي اسْتِفْهام تَقْرِير وكَيْفَ خَبَر كانَ وهِيَ لِلسُّؤالِ عَنْ الحال والمَعْنى حَمْل المُخاطَبِينَ عَلى الإقْرار بِوُقُوعِ عَذابه تَعالى بِالمُكَذِّبِينَ لِنُوحٍ مَوْقِعه", "malayalam": "«അപ്പോൾ എന്റെ ശിക്ഷയും എന്റെ താക്കീതുകളും എങ്ങനെയുണ്ടായിരുന്നു?» (അത് എത്ര ഭയാനകമായിരുന്നു!).", "malayalamMatn": "അപ്പോള്‍ എന്‍റെ ശിക്ഷയും താക്കീതുകളും എങ്ങനെയായിരുന്നു.(എന്നു നോക്കുക)"}, {"ayahNumber": 17, "quranText": "وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ\n", "jalalayn": "«ولَقَدْ يَسَّرْنا القُرْآن لِلذِّكْرِ» سَهَّلْناهُ لِلْحِفْظِ وهَيَّأْناهُ لِلتَّذَكُّرِ «فَهَلْ مِن مُدَّكِر» مُتَّعِظ بِهِ وحافِظ لَهُ والِاسْتِفْهام بِمَعْنى الأَمْر أيْ احْفَظُوهُ واتَّعِظُوا بِهِ ولَيْسَ يُحْفَظ مِن كُتُب اللَّه عَنْ ظَهْر القَلْب غَيْره", "malayalam": "«തീർച്ചയായും ഖുർആനെ ഉൽബോധനത്തിനായി നാം എളുപ്പമാക്കിയിരിക്കുന്നു; എന്നാൽ ചിന്തിച്ചു മനസ്സിലാക്കുന്നവരായി ആരെങ്കിലുമുണ്ടോ?»", "malayalamMatn": "തീര്‍ച്ചയായും ആലോചിച്ചു മനസ്സിലാക്കാന്‍ ഖുര്‍ആന്‍ നാം എളുപ്പമുള്ളതാക്കിയിരിക്കുന്നു. എന്നാല്‍ ആലോചിച്ചു മനസ്സിലാക്കുന്നവരായി ആരെങ്കിലുമുണ്ടോ?"}, {"ayahNumber": 18, "quranText": "كَذَّبَتۡ عَادࣱ فَكَیۡفَ كَانَ عَذَابِی وَنُذُرِ\n", "jalalayn": "«كَذَّبَتْ عاد» نَبِيّهمْ هُودًا فَعُذِّبُوا «فَكَيْفَ كانَ عَذابِي ونُذُر» إنْذارِي لَهُمْ بِالعَذابِ قَبْل نُزُوله أيْ وقَعَ مَوْقِعه وقَدْ بَيَّنَهُ تَعالى فِي الآيَة التّالِيَة", "malayalam": "«ആദ് ജനതയും നിഷേധിച്ചു തള്ളുകയുണ്ടായി; അപ്പോൾ എന്റെ ശിക്ഷയും എന്റെ താക്കീതുകളും എങ്ങനെയുണ്ടായിരുന്നു?»", "malayalamMatn": "ആദ് സമുദായം (സത്യത്തെ) നിഷേധിച്ചു കളഞ്ഞു. എന്നിട്ട് എന്‍റെ ശിക്ഷയും എന്‍റെ താക്കീതുകളും എങ്ങനെയായിരുന്നു.(എന്ന് നോക്കുക.)"}, {"ayahNumber": 19, "quranText": "إِنَّاۤ أَرۡسَلۡنَا عَلَیۡهِمۡ رِیحࣰا صَرۡصَرࣰا فِی یَوۡمِ نَحۡسࣲ مُّسۡتَمِرࣲّ\n", "jalalayn": "«إنّا أرْسَلْنا عَلَيْهِمْ رِيحًا صَرْصَرًا» أيْ شَدِيدَة الصَّوْت «فِي يَوْم نَحْس» شُؤْم «مُسْتَمِرّ» دائِم الشُّؤْم أوْ قَوِيّه وكانَ يَوْم الأَرْبِعاء آخِر الشَّهْر", "malayalam": "«ഒഴിയാത്ത നിർഭാഗ്യത്തിന്റെ ഒരു ദിവസത്തിൽ, ശക്തിയായി ആഞ്ഞടിക്കുന്ന ശീതക്കാറ്റിനെ നാം അവരുടെ നേരെ അയച്ചു».", "malayalamMatn": "വിട്ടുമാറാത്ത ദുശ്ശകുനത്തിന്‍റെ ഒരു ദിവസത്തില്‍ ഉഗ്രമായ ഒരു കാറ്റ് നാം അവരുടെ നേര്‍ക്ക് അയക്കുക തന്നെ ചെയ്തു."}, {"ayahNumber": 20, "quranText": "تَنزِعُ ٱلنَّاسَ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلࣲ مُّنقَعِرࣲ\n", "jalalayn": "«تَنْزِع النّاس» تَقْلَعُهُمْ مِن حُفَر الأَرْض المُنْدَسِّينَ فِيها وتَصْرَعهُمْ عَلى رُءُوسهمْ فَتَدُقّ رِقابهمْ فَتُبَيِّن الرَّأْس عَنْ الجَسَد «كَأَنَّهُمْ» وحالهمْ ما ذُكِرَ «أعْجاز» أُصُول «نَخْل مُنْقَعِر» مُنْقَطِع ساقِط عَلى الأَرْض وشُبِّهُوا بِالنَّخْلِ لِطُولِهِمْ وذُكِّرَ هُنا وأُنِّثَ فِي الحاقَّة «نَخْل خاوِيَة» مُراعاة لِلْفَواصِلِ فِي المَوْضِعَيْنِ", "malayalam": "«വേരോടെ പിഴുതെറിയപ്പെട്ട ഈത്തപ്പനത്തടികൾ പോലെ അത് മനുഷ്യരെ പിഴുതെറിഞ്ഞുകൊണ്ടിരുന്നു».", "malayalamMatn": "കടപുഴകി വീഴുന്ന ഈന്തപ്പനത്തടികളെന്നോണം അത് മനുഷ്യരെ പറിച്ചെറിഞ്ഞു കൊണ്ടിരുന്നു."}, {"ayahNumber": 21, "quranText": "فَكَیۡفَ كَانَ عَذَابِی وَنُذُرِ\n", "jalalayn": "«فَكَیۡفَ كَانَ عَذَابِی وَنُذُرِ».", "malayalam": "«അപ്പോൾ എന്റെ ശിക്ഷയും എന്റെ താക്കീതുകളും എങ്ങനെയുണ്ടായിരുന്നു?»", "malayalamMatn": "അപ്പോള്‍ എന്‍റെ ശിക്ഷയും എന്‍റെ താക്കീതുകളും എങ്ങനെയായിരുന്നു.(എന്നു നോക്കുക.)"}, {"ayahNumber": 22, "quranText": "وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ\n", "jalalayn": "«وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ».", "malayalam": "«തീർച്ചയായും ഖുർആനെ ഉൽബോധനത്തിനായി നാം എളുപ്പമാക്കിയിരിക്കുന്നു; എന്നാൽ ചിന്തിച്ചു മനസ്സിലാക്കുന്നവരായി ആരെങ്കിലുമുണ്ടോ?»", "malayalamMatn": "തീര്‍ച്ചയായും ആലോചിച്ച് മനസ്സിലാക്കുവാന്‍ ഖുര്‍ആന്‍ നാം എളുപ്പമുള്ളതാക്കിയിരിക്കുന്നു. എന്നാല്‍ ആലോചിച്ച് മനസ്സിലാക്കുന്നവരായി ആരെങ്കിലുമുണ്ടോ?"}, {"ayahNumber": 23, "quranText": "كَذَّبَتۡ ثَمُودُ بِٱلنُّذُرِ\n", "jalalayn": "«كَذَّبَتْ ثَمُود بِالنُّذُرِ» جَمْع نَذِير بِمَعْنى مُنْذِر أيْ بِالأُمُورِ الَّتِي أنْذَرَهُمْ بِها نَبِيّهمْ صالِح إنْ لَمْ يُؤْمِنُوا بِهِ ويَتَّبِعُوهُ", "malayalam": "«ഥമൂദ് ജനത താക്കീതുകളെ നിഷേധിച്ചു കളഞ്ഞു».", "malayalamMatn": "ഥമൂദ് സമുദായം താക്കീതുകളെ നിഷേധിച്ചു കളഞ്ഞു."}, {"ayahNumber": 24, "quranText": "فَقَالُوۤا۟ أَبَشَرࣰا مِّنَّا وَ ٰ⁠حِدࣰا نَّتَّبِعُهُۥۤ إِنَّاۤ إِذࣰا لَّفِی ضَلَـٰلࣲ وَسُعُرٍ\n", "jalalayn": "«فَقالُوا أبَشَرًا» مَنصُوب عَلى الِاشْتِغال «مِنّا واحِدًا» صِفَتانِ لبَشَرًا «نَتَّبِعهُ» مُفَسِّر لِلْفِعْلِ النّاصِب لَهُ والِاسْتِفْهام بِمَعْنى النَّفْي المَعْنِيّ كَيْفَ نَتَّبِعهُ ونَحْنُ جَماعَة كَثِيرَة وهُوَ واحِد مِنّا ولَيْسَ بِمَلَكٍ أيْ لا نَتَّبِعهُ «إنّا إذًا» إنِ اتَّبَعْناهُ «لَفِي ضَلال» ذَهاب عَنْ الصَّواب «وسُعُر» جُنُون", "malayalam": "«അവർ പറഞ്ഞു: നമ്മിൽപെട്ട ഒരു മനുഷ്യനെയാണോ നാം പിന്തുടരേണ്ടത്? എങ്കിൽ തീർച്ചയായും നാം ദുർമാർഗ്ഗത്തിലും ഭ്രാന്തിലുമായിരിക്കും».", "malayalamMatn": "അങ്ങനെ അവര്‍ പറഞ്ഞു. നമ്മളില്‍ പെട്ട ഒരു മനുഷ്യനെ, ഒറ്റപ്പെട്ട ഒരുത്തനെ നാം പിന്തുടരുകയോ? എങ്കില്‍ തീര്‍ച്ചയായും നാം വഴിപിഴവിലും ബുദ്ധിശൂന്യതയിലും തന്നെയായിരിക്കും"}, {"ayahNumber": 25, "quranText": "أَءُلۡقِیَ ٱلذِّكۡرُ عَلَیۡهِ مِنۢ بَیۡنِنَا بَلۡ هُوَ كَذَّابٌ أَشِرࣱ\n", "jalalayn": "«أأُلْقِيَ» بِتَحْقِيقِ الهَمْزَتَيْنِ وتَسْهِيل الثّانِيَة وإدْخال ألِف بَيْنهما عَلى الوَجْهَيْنِ وتَرْكه «الذِّكْر» الوَحْي «عَلَيْهِ مِن بَيْننا» أيْ لَمْ يُوحَ إلَيْهِ «بَلْ هُوَ كَذّاب» فِي قَوْله إنّهُ أُوحِيَ إلَيْهِ ما ذُكِرَ «أشِر» مُتَكَبِّر بَطِر", "malayalam": "«നമ്മുടെ കൂട്ടത്തിൽ നിന്ന് ഇദ്ദേഹത്തിനാണോ ഉൽബോധനം നൽകപ്പെട്ടത്? അല്ല, അവൻ പെരുംകള്ളനും അഹങ്കാരിയുമാകുന്നു!»", "malayalamMatn": "നമ്മുടെ കൂട്ടത്തില്‍ നിന്ന് അവന്നു പ്രത്യേകമായി ഉല്‍ബോധനം നല്‍കപ്പെട്ടു എന്നോ? അല്ല, അവന്‍ അഹങ്കാരിയായ ഒരു വ്യാജവാദിയാകുന്നു."}, {"ayahNumber": 26, "quranText": "سَیَعۡلَمُونَ غَدࣰا مَّنِ ٱلۡكَذَّابُ ٱلۡأَشِرُ\n", "jalalayn": "«سَيَعْلَمُونَ غَدًا» فِي الآخِرَة «مَنِ الكَذّاب الأَشِر» وهُوَ هَمّ بِأَنْ يُعَذَّبُوا عَلى تَكْذِيبهمْ نَبِيّهمْ صالِحًا", "malayalam": "«നാളെ അവർ അറിഞ്ഞുകൊള്ളും; ആരാണ് പെരുംകള്ളനും അഹങ്കാരിയുമെന്ന്» (ശിക്ഷ നേരിട്ട് കാണുമ്പോൾ).", "malayalamMatn": "എന്നാല്‍ നാളെ അവര്‍ അറിഞ്ഞ് കൊള്ളും; ആരാണ് അഹങ്കാരിയായ വ്യാജവാദിയെന്ന്‌."}, {"ayahNumber": 27, "quranText": "إِنَّا مُرۡسِلُوا۟ ٱلنَّاقَةِ فِتۡنَةࣰ لَّهُمۡ فَٱرۡتَقِبۡهُمۡ وَٱصۡطَبِرۡ\n", "jalalayn": "«إنّا مُرْسِلُو النّاقَة» مُخْرِجُوها مِن الهَضْبَة الصَّخْرَة كَما سَأَلُوا «فِتْنَة» مِحْنَة «لَهُمْ» لِنَخْتَبِرهُمْ «فارْتَقِبْهُمْ» يا صالِح أيْ انْتَظِرْ ما هُمْ صانِعُونَ وما يُصْنَع بِهِمْ «واصْطَبِرْ» الطّاء بَدَل مِن تاء الِافْتِعال أيْ اصْبِرْ عَلى أذاهُمْ", "malayalam": "«അവരെ പരീക്ഷിക്കുവാനായി നാം ഒട്ടകത്തെ അയക്കുകയാണ്; അതിനാൽ നീ അവരെ നിരീക്ഷിക്കുകയും ക്ഷമിക്കുകയും ചെയ്യുക» (എന്ന് സ്വാലിഹ് നബിയോട് അല്ലാഹു പറഞ്ഞു).", "malayalamMatn": "(അവരുടെ പ്രവാചകന്‍ സ്വാലിഹിനോട് നാം പറഞ്ഞു:) തീര്‍ച്ചയായും അവര്‍ക്ക് ഒരു പരീക്ഷണമെന്ന നിലയില്‍ നാം ഒട്ടകത്തെ അയക്കുകയാകുന്നു. അത് കൊണ്ട് നീ അവരെ നിരീക്ഷിച്ച് കൊണ്ടിരിക്കുക. ക്ഷമ കൈക്കൊള്ളുകയും ചെയ്യുക."}, {"ayahNumber": 28, "quranText": "وَنَبِّئۡهُمۡ أَنَّ ٱلۡمَاۤءَ قِسۡمَةُۢ بَیۡنَهُمۡۖ كُلُّ شِرۡبࣲ مُّحۡتَضَرࣱ\n", "jalalayn": "«ونَبِّئْهُمْ أنَّ الماء قِسْمَة» مَقْسُوم «بَيْنهمْ» وبَيْن النّاقَة يَوْم لَهُمْ ويَوْم لَها «كُلّ شِرْب» نَصِيب مِن الماء «مُحْتَضَر» يَحْضُرهُ القَوْم يَوْمهمْ والنّاقَة يَوْمها فَتَمادَوْا عَلى ذَلِكَ ثُمَّ مَلَّوْهُ فَهَمُّوا بِقَتْلِ النّاقَة", "malayalam": "«വെള്ളം അവർക്കിടയിൽ വീതിക്കപ്പെട്ടതാണെന്ന കാര്യം നീ അവർക്ക് വിവരമറിയിക്കുക; ഓരോരുത്തരുടെയും ഊഴത്തിൽ അവരവർ ഹാജരാകേണ്ടതാണ്» (ഒരു ദിവസം ഒട്ടകത്തിനും അടുത്ത ദിവസം ജനങ്ങൾക്കും).", "malayalamMatn": "വെള്ളം അവര്‍ക്കിടയില്‍ (അവര്‍ക്കും ഒട്ടകത്തിനുമിടയില്‍) പങ്കുവെക്കപ്പെട്ടതാണ് എന്ന് നീ അവര്‍ക്ക് വിവരം അറിയിക്കുകയും ചെയ്യുക. ഓരോരുത്തരുടെയും ജലപാനത്തിന്നുള്ള ഊഴത്തില്‍ (അതിന്ന് അവകാശപ്പെട്ടവര്‍) ഹാജരാകേണ്ടതാണ്‌."}, {"ayahNumber": 29, "quranText": "فَنَادَوۡا۟ صَاحِبَهُمۡ فَتَعَاطَىٰ فَعَقَرَ\n", "jalalayn": "«فَنادَوْا صاحِبهمْ» قِدارًا لِيَقْتُلها «فَتَعاطى» تَناوَلَ السَّيْف «فَعَقَرَ» بِهِ النّاقَة أيْ قَتَلَها مُوافَقَة لَهُمْ", "malayalam": "«എന്നിട്ട് അവർ തങ്ങളുടെ കൂട്ടുകാരനെ» (ഖുദാർ ബിൻ സാലിഫിനെ) «വിളിച്ചു; അവൻ വാളെടുത്ത് അതിനെ വെട്ടിക്കൊന്നു».", "malayalamMatn": "അപ്പോള്‍ അവര്‍ അവരുടെ ചങ്ങാതിയെ വിളിച്ചു. ങ്ങനെ അവന്‍ (ആ കൃത്യം) ഏറ്റെടുത്തു. (ആ ഒട്ടകത്തെ) അറുകൊലചെയ്തു."}, {"ayahNumber": 30, "quranText": "فَكَیۡفَ كَانَ عَذَابِی وَنُذُرِ\n", "jalalayn": "«فَكَيْفَ كانَ عَذابِي ونُذُر» إنْذارِي لَهُمْ بِالعَذابِ قَبْل نُزُوله أيْ وقَعَ مَوْقِعه وبَيَّنَهُ تَعالى فِي الآيَة التّالِيَة", "malayalam": "«അപ്പോൾ എന്റെ ശിക്ഷയും എന്റെ താക്കീതുകളും എങ്ങനെയുണ്ടായിരുന്നു?»", "malayalamMatn": "അപ്പോള്‍ എന്‍റെ ശിക്ഷയും എന്‍റെ താക്കീതുകളും എങ്ങനെയായിരുന്നു (എന്നു നോക്കുക.)"}, {"ayahNumber": 31, "quranText": "إِنَّاۤ أَرۡسَلۡنَا عَلَیۡهِمۡ صَیۡحَةࣰ وَ ٰ⁠حِدَةࣰ فَكَانُوا۟ كَهَشِیمِ ٱلۡمُحۡتَظِرِ\n", "jalalayn": "«إنّا أرْسَلْنا عَلَيْهِمْ صَيْحَة واحِدَة فَكانُوا كَهَشِيمِ المُحْتَظِر» هُوَ الَّذِي يَجْعَل لِغَنَمِهِ حَظِيرَة مِن يابِس الشَّجَر والشَّوْك يَحْفَظهُنَّ فِيها مِن الذِّئاب والسِّباع وما سَقَطَ مِن ذَلِكَ فَداسَتْهُ هُوَ الهَشِيم", "malayalam": "«തീർച്ചയായും നാം അവരുടെ നേരെ ഒരൊറ്റ ഘോരശബ്ദം അയച്ചു; അപ്പോൾ അവർ കന്നുകാലികളുടെ തൊഴുത്തുണ്ടാക്കുന്നവൻ ഉപേക്ഷിച്ച ഉണങ്ങിയ ചുള്ളിക്കമ്പുകൾ പോലെ ആയിത്തീർന്നു».", "malayalamMatn": "നാം അവരുടെ നേരെ ഒരു ഘോരശബ്ദം അയക്കുക തന്നെ ചെയ്തു. അപ്പോള്‍ അവര്‍ ആല വളച്ച് കെട്ടുന്നവര്‍ വിട്ടേച്ചുപോയ ചുള്ളിത്തുരുമ്പുകള്‍ പോലെ ആയിത്തീര്‍ന്നു."}, {"ayahNumber": 32, "quranText": "وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ\n", "jalalayn": "«وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ».", "malayalam": "«തീർച്ചയായും ഖുർആനെ ഉൽബോധനത്തിനായി നാം എളുപ്പമാക്കിയിരിക്കുന്നു; എന്നാൽ ചിന്തിച്ചു മനസ്സിലാക്കുന്നവരായി ആരെങ്കിലുമുണ്ടോ?»", "malayalamMatn": "തീര്‍ച്ചയായും ആലോചിച്ചു മനസ്സിലാക്കുവാന്‍ ഖുര്‍ആന്‍ നാം എളുപ്പമുള്ളതാക്കിയിരിക്കുന്നു. എന്നാല്‍ ആലോചിച്ച് മനസ്സിലാക്കുന്നവരായി ആരെങ്കിലുമുണ്ടോ?"}, {"ayahNumber": 33, "quranText": "كَذَّبَتۡ قَوۡمُ لُوطِۭ بِٱلنُّذُرِ\n", "jalalayn": "«كَذَّبَتْ قَوْم لُوط بِالنُّذُرِ» بِالأُمُورِ المُنْذِرَة لَهُمْ عَلى لِسانه", "malayalam": "«ലൂത്വിന്റെ ജനതയും താക്കീതുകളെ നിഷേധിച്ചു തള്ളി».", "malayalamMatn": "ലൂത്വിന്‍റെ ജനത താക്കീതുകളെ നിഷേധിച്ചു കളഞ്ഞു."}, {"ayahNumber": 34, "quranText": "إِنَّاۤ أَرۡسَلۡنَا عَلَیۡهِمۡ حَاصِبًا إِلَّاۤ ءَالَ لُوطࣲۖ نَّجَّیۡنَـٰهُم بِسَحَرࣲ\n", "jalalayn": "«إنّا أرْسَلْنا عَلَيْهِمْ حاصِبًا» رِيحًا تَرْمِيهِمْ بِالحَصْباءِ وهِيَ صِغار الحِجارَة الواحِد دُون مِلْء الكَفّ فَهَلَكُوا «إلّا آل لُوط» وهُمْ ابْنَتاهُ مَعَهُ «نَجَّيْناهُمْ بِسَحَرٍ» مِن الأَسْحار وقْت الصُّبْح مِن يَوْم غَيْر مُعَيَّن ولَوْ أُرِيدَ مِن يَوْم مُعَيَّن لَمُنِعَ مِنَ الصَّرْف لِأَنَّهُ مَعْرِفَة مَعْدُول عَنْ السَّحَر لِأَنَّ حَقّه أنْ يُسْتَعْمَل فِي المَعْرِفَة بِأَلْ وهَلْ أُرْسِلَ الحاصِب عَلى آل لُوط أوْ لا ؟ قَوْلانِ وعَبَّرَ عَنْ الِاسْتِثْناء عَلى الأَوَّل بِأَنَّهُ مُتَّصِل وعَلى الثّانِي بِأَنَّهُ مُنْقَطِع وإنْ كانَ مِن الجِنْس تَسَمُّحًا", "malayalam": "«തീർച്ചയായും നാം അവരുടെ നേരെ കല്ലുമഴ അയച്ചു; ലൂത്വിന്റെ കുടുംബമൊഴികെ; പ്രഭാതവേളയിൽ നാം അവരെ രക്ഷപ്പെടുത്തി».", "malayalamMatn": "തീര്‍ച്ചയായും നാം അവരുടെ നേരെ ഒരു ചരല്‍കാറ്റ് അയച്ചു. ലൂത്വിന്‍റെ കുടുംബം അതില്‍ നിന്ന് ഒഴിവായിരുന്നു. രാത്രിയുടെ അന്ത്യവേളയില്‍ നാം അവരെ രക്ഷപ്പെടുത്തി."}, {"ayahNumber": 35, "quranText": "نِّعۡمَةࣰ مِّنۡ عِندِنَاۚ كَذَ ٰ⁠لِكَ نَجۡزِی مَن شَكَرَ\n", "jalalayn": "«نِعْمَة» مَصْدَر أيْ إنْعامًا «مِن عِنْدنا كَذَلِكَ» أيْ مِثْل ذَلِكَ الجَزاء «نَجْزِي مَن شَكَرَ» أنْعَمْنا وهُوَ مُؤْمِن أوْ مَن آمَنَ بِاللَّهِ ورَسُوله وأَطاعَهُما", "malayalam": "«നമ്മുടെ പക്കൽ നിന്നുള്ള ഒരു അനുഗ്രഹമായിക്കൊണ്ട്; അപ്രകാരമാണ് നന്ദി കാണിച്ചവർക്ക് നാം പ്രതിഫലം നൽകുന്നത്».", "malayalamMatn": "നമ്മുടെ പക്കല്‍ നിന്നുള്ള ഒരു അനുഗ്രഹമെന്ന നിലയില്‍. അപ്രകാരമാകുന്നു നന്ദികാണിച്ചവര്‍ക്ക് നാം പ്രതിഫലം നല്‍കുന്നത്‌."}, {"ayahNumber": 36, "quranText": "وَلَقَدۡ أَنذَرَهُم بَطۡشَتَنَا فَتَمَارَوۡا۟ بِٱلنُّذُرِ\n", "jalalayn": "«ولَقَدْ أنْذَرَهُمْ» خَوَّفَهُمْ لُوط «بَطْشَتنا» أخْذَتنا إيّاهُمْ بِالعَذابِ «فَتَمارَوْا» تَجادَلُوا وكَذَّبُوا «بِالنُّذُرِ» بِإنْذارِهِ", "malayalam": "«തീർച്ചയായും നമ്മുടെ പിടിത്തത്തെക്കുറിച്ച് അദ്ദേഹം അവർക്ക് മുന്നറിയിപ്പ് നൽകിയിരുന്നു; എന്നിട്ടും അവർ താക്കീതുകളെപ്പറ്റി തർക്കിച്ചു തള്ളുകയാണുണ്ടായത്».", "malayalamMatn": "നമ്മുടെ ശിക്ഷയെപറ്റി അദ്ദേഹം (ലൂത്വ്‌) അവര്‍ക്കു താക്കീത് നല്‍കുകയുണ്ടായി. അപ്പോള്‍ അവര്‍ താക്കീതുകള്‍ സംശയിച്ച് തള്ളുകയാണ് ചെയ്തത്‌."}, {"ayahNumber": 37, "quranText": "وَلَقَدۡ رَ ٰ⁠وَدُوهُ عَن ضَیۡفِهِۦ فَطَمَسۡنَاۤ أَعۡیُنَهُمۡ فَذُوقُوا۟ عَذَابِی وَنُذُرِ\n", "jalalayn": "«ولَقَدْ راوَدُوهُ عَنْ ضَيْفه» أنْ يُخَلِّي بَيْنهمْ وبَيْن القَوْم الَّذِينَ أتَوْهُ فِي صُورَة الأَضْياف لِيَخْبُثُوا بِهِمْ وكانُوا مَلائِكَة «فَطَمَسْنا أعْيُنهمْ» أعْمَيْناها وجَعَلْناها بِلا شَقّ كَباقِي الوَجْه بِأَنْ صَفَقَها جِبْرِيل بِجَناحِهِ «فَذُوقُوا» فَقُلْنا لَهُمْ ذُوقُوا «عَذابِي ونُذُر» إنْذارِي وتَخْوِيفِي أيْ ثَمَرَته وفائِدَته", "malayalam": "«അദ്ദേഹത്തിന്റെ അതിഥികളെക്കുറിച്ച് അവർ അദ്ദേഹത്തോട് ദുരുദ്ദേശ്യത്തോടെ ആവശ്യപ്പെടുകയുണ്ടായി; അപ്പോൾ നാം അവരുടെ കണ്ണുകളെ തുടച്ചുനീക്കി അന്ധരാക്കി; എന്നിട്ട് പറഞ്ഞു: എന്റെ ശിക്ഷയും എന്റെ താക്കീതുകളും നിങ്ങൾ ആസ്വദിച്ചു കൊള്ളുക!»", "malayalamMatn": "അദ്ദേഹത്തോട് (ലൂത്വിനോട്‌) അദ്ദേഹത്തിന്‍റെ അതിഥികളെ (ദുര്‍വൃത്തിക്കായി) വിട്ടുകൊടുക്കുവാനും അവര്‍ ആവശ്യപ്പെടുകയുണ്ടായി. അപ്പോള്‍ അവരുടെ കണ്ണുകളെ നാം തുടച്ചുനീക്കി. എന്‍റെ ശിക്ഷയും എന്‍റെ താക്കീതുകളും നിങ്ങള്‍ അനുഭവിച്ച് കൊള്ളുക (എന്ന് നാം അവരോട് പറഞ്ഞു.)"}, {"ayahNumber": 38, "quranText": "وَلَقَدۡ صَبَّحَهُم بُكۡرَةً عَذَابࣱ مُّسۡتَقِرࣱّ\n", "jalalayn": "«ولَقَدْ صَبَّحَهُمْ بُكْرَة» وقْت الصُّبْح مِن يَوْم غَيْر مُعَيَّن «عَذاب مُسْتَقِرّ» دائِم مُتَّصِل بِعَذابِ الآخِرَة", "malayalam": "«പ്രഭാതവേളയിൽ ഉറച്ചുനിൽക്കുന്ന ശിക്ഷ അവരുടെ മേൽ വന്നെത്തുക തന്നെ ചെയ്തു».", "malayalamMatn": "അതിരാവിലെ അവര്‍ക്ക് സുസ്ഥിരമായ ശിക്ഷ വന്നെത്തുക തന്നെ ചെയ്തു."}, {"ayahNumber": 39, "quranText": "فَذُوقُوا۟ عَذَابِی وَنُذُرِ\n", "jalalayn": "«فَذُوقُوا۟ عَذَابِی وَنُذُرِ».", "malayalam": "«ആകയാൽ എന്റെ ശിക്ഷയും എന്റെ താക്കീതുകളും നിങ്ങൾ ആസ്വദിച്ചു കൊള്ളുക!»", "malayalamMatn": "എന്‍റെ ശിക്ഷയും എന്‍റെ താക്കീതുകളും നിങ്ങള്‍ അനുഭവിച്ചു കൊള്ളുക.(എന്ന് നാം അവരോട് പറഞ്ഞു.)"}, {"ayahNumber": 40, "quranText": "وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ\n", "jalalayn": "«وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ».", "malayalam": "«തീർച്ചയായും ഖുർആനെ ഉൽബോധനത്തിനായി നാം എളുപ്പമാക്കിയിരിക്കുന്നു; എന്നാൽ ചിന്തിച്ചു മനസ്സിലാക്കുന്നവരായി ആരെങ്കിലുമുണ്ടോ?»", "malayalamMatn": "തീര്‍ച്ചയായും ആലോചിച്ചു മനസ്സിലാക്കുന്നതിന് ഖുര്‍ആന്‍ നാം എളുപ്പമുള്ളതാക്കിയിരിക്കുന്നു. എന്നാല്‍ ആലോചിച്ച് മനസ്സിലാക്കുന്നവരായി ആരെങ്കിലുമുണ്ടോ?"}, {"ayahNumber": 41, "quranText": "وَلَقَدۡ جَاۤءَ ءَالَ فِرۡعَوۡنَ ٱلنُّذُرُ\n", "jalalayn": "«ولَقَدْ جاءَ آل فِرْعَوْن» قَوْمه مَعَهُ «النُّذُر» الإنْذار عَلى لِسان مُوسى وهارُون فَلَمْ يُؤْمِنُوا", "malayalam": "«ഫിർഔന്റെ ആളുകളുടെ അടുക്കലും താക്കീതുകൾ വരികയുണ്ടായി».", "malayalamMatn": "ഫിര്‍ഔന്‍ കുടുംബത്തിനും താക്കീതുകള്‍ വന്നെത്തുകയുണ്ടായി."}, {"ayahNumber": 42, "quranText": "كَذَّبُوا۟ بِـَٔایَـٰتِنَا كُلِّهَا فَأَخَذۡنَـٰهُمۡ أَخۡذَ عَزِیزࣲ مُّقۡتَدِرٍ\n", "jalalayn": "«كَذَّبُوا بِآياتِنا كُلّها» التِّسْع الَّتِي أُوتِيَها مُوسى «فَأَخَذْناهُمْ» بِالعَذابِ «أخْذ عَزِيز» قَوِيّ «مُقْتَدِر» قادِر لا يُعْجِزهُ شَيْء", "malayalam": "«അവർ നമ്മുടെ എല്ലാ ദൃഷ്ടാന്തങ്ങളെയും നിഷേധിച്ചു തള്ളി; അപ്പോൾ പ്രതാപിയും സർവ്വശക്തനുമായ ഒരുവൻ പിടികൂടും വിധം നാം അവരെ പിടികൂടി» (കടലിൽ മുക്കിക്കൊന്നു).", "malayalamMatn": "അവര്‍ നമ്മുടെ ദൃഷ്ടാന്തങ്ങളെ മുഴുവന്‍ നിഷേധിച്ചു തള്ളിക്കളഞ്ഞു.അപ്പോള്‍ പ്രതാപിയും ശക്തനുമായ ഒരുത്തന്‍ പിടികൂടുന്ന വിധം നാം അവരെ പിടികൂടി."}, {"ayahNumber": 43, "quranText": "أَكُفَّارُكُمۡ خَیۡرࣱ مِّنۡ أُو۟لَـٰۤىِٕكُمۡ أَمۡ لَكُم بَرَاۤءَةࣱ فِی ٱلزُّبُرِ\n", "jalalayn": "«أكُفّاركُمْ» يا قُرَيْش «خَيْر مِن أُوْلَئِكُمْ» المَذْكُورِينَ مِن قَوْم نُوح إلى فِرْعَوْن فَلَمْ يُعْذَرُوا «أمْ لَكُمْ» يا كُفّار قُرَيْش «بَراءَة» مِن العَذاب «فِي الزُّبُر» الكُتُب والِاسْتِفْهام فِي المَوْضِعَيْنِ بِمَعْنى النَّفْي أيْ لَيْسَ الأَمْر كَذَلِكَ", "malayalam": "«നിങ്ങളിലെ അവിശ്വാസികൾ» (ഹേ ഖുറൈശികളേ) «അവരേക്കാളൊക്കെ ഉത്തമന്മാരാണോ? അതല്ല വേദഗ്രന്ഥങ്ങളിൽ നിങ്ങൾക്ക് വല്ല രക്ഷാപത്രവുമുണ്ടോ?» (ശിക്ഷയിൽ നിന്ന് മുക്തരാണെന്ന രേഖയുണ്ടോ?).", "malayalamMatn": "(ഹേ, അറബികളേ,) നിങ്ങളുടെ കൂട്ടത്തിലെ സത്യനിഷേധികള്‍ അവരെക്കാളൊക്കെ ഉത്തമന്‍മാരാണോ? അതല്ല, വേദപ്രമാണങ്ങളില്‍ നിങ്ങള്‍ക്ക് (മാത്രം) വല്ല ഒഴിവുമുണ്ടോ?"}, {"ayahNumber": 44, "quranText": "أَمۡ یَقُولُونَ نَحۡنُ جَمِیعࣱ مُّنتَصِرࣱ\n", "jalalayn": "«أمْ يَقُولُونَ» أيْ كُفّار قُرَيْش «نَحْنُ جَمِيع» جَمْع «مُنْتَصِر» عَلى مُحَمَّد", "malayalam": "«അതല്ല, ഞങ്ങൾ പരസ്പരം സഹായിക്കുന്നവരും വിജയം വരിക്കുന്നവരുമായ ഒരു വലിയ സംഘമാണെന്ന് അവർ പറയുകയാണോ?» (ബദ്റിൽ അബൂജഹൽ അഹങ്കാരത്തോടെ പറഞ്ഞതുപോലെ).", "malayalamMatn": "അതല്ല, അവര്‍ പറയുന്നുവോ; ഞങ്ങള്‍ സംഘടിതരും സ്വയം പ്രതിരോധിക്കാന്‍ കഴിവുള്ളവരുമാണ് എന്ന്‌."}, {"ayahNumber": 45, "quranText": "سَیُهۡزَمُ ٱلۡجَمۡعُ وَیُوَلُّونَ ٱلدُّبُرَ\n", "jalalayn": "«سَيُهْزَمُ الجَمْع ويُوَلُّونَ الدُّبُر» ولَمّا قالَ أبُو جَهْل يَوْم بَدْر إنّا جَمْع مُنْتَصِر نَزَلَتْ الآيَة فَهُزِمُوا بِبَدْرٍ ونُصِرَ رَسُولُ اللَّه ﷺ عَلَيْهِمْ", "malayalam": "«ആ സംഘം ഉടൻ പരാജയപ്പെടുകയും അവർ പിന്തിരിഞ്ഞോടുകയും ചെയ്യും» (ബദ്റിൽ സംഭവിച്ചതുപോലെ).", "malayalamMatn": "എന്നാല്‍ വഴിയെ ആ സംഘം തോല്‍പിക്കപ്പെടുന്നതാണ്‌. അവര്‍ പിന്തിരിഞ്ഞ് ഓടുകയും ചെയ്യും."}, {"ayahNumber": 46, "quranText": "بَلِ ٱلسَّاعَةُ مَوۡعِدُهُمۡ وَٱلسَّاعَةُ أَدۡهَىٰ وَأَمَرُّ\n", "jalalayn": "«بَلِ السّاعَةُ مَوْعِدُهُمْ» بِالعَذابِ «والسّاعَة» أيْ عَذابها «أدْهى» أعْظَم بَلِيَّة «وأَمَرّ» أشَدّ مَرارَة مِن عَذاب الدُّنْيا", "malayalam": "«എന്നാൽ അന്ത്യസമയമാകുന്നു അവർക്ക് നിശ്ചയിക്കപ്പെട്ട സമയം; ആ അന്ത്യസമയം കൂടുതൽ ഭയാനകവും കൂടുതൽ കയ്പേറിയതുമാകുന്നു!»", "malayalamMatn": "തന്നെയുമല്ല, ആ അന്ത്യസമയമാകുന്നു അവര്‍ക്കുള്ള നിശ്ചിത സന്ദര്‍ഭം. ആ അന്ത്യസമയം ഏറ്റവും ആപല്‍ക്കരവും അത്യന്തം കയ്പേറിയതുമാകുന്നു."}, {"ayahNumber": 47, "quranText": "إِنَّ ٱلۡمُجۡرِمِینَ فِی ضَلَـٰلࣲ وَسُعُرࣲ\n", "jalalayn": "«إنّ المُجْرِمِينَ فِي ضَلال» هَلاك بِالقَتْلِ فِي الدُّنْيا «وسُعُر» نار مُسَعَّرَة بِالتَّشْدِيدِ أيْ مُهَيَّجَة فِي الآخِرَة", "malayalam": "«തീർച്ചയായും ആ കുറ്റവാളികൾ ദുർമാർഗ്ഗത്തിലും ജ്വലിക്കുന്ന നരകാഗ്നിയിലുമാകുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും ആ കുറ്റവാളികള്‍ വഴിപിഴവിലും ബുദ്ധിശൂന്യതയിലുമാകുന്നു."}, {"ayahNumber": 48, "quranText": "یَوۡمَ یُسۡحَبُونَ فِی ٱلنَّارِ عَلَىٰ وُجُوهِهِمۡ ذُوقُوا۟ مَسَّ سَقَرَ\n", "jalalayn": "«يَوْم يُسْحَبُونَ فِي النّار عَلى وُجُوههمْ» فِي الآخِرَة ويُقال لَهُمْ «ذُوقُوا مَسَّ سَقَر» إصابَة جَهَنَّم لَكُمْ", "malayalam": "«അവരുടെ മുഖങ്ങൾ നിലത്തിഴച്ച് നരകത്തിലേക്ക് വലിച്ചിഴക്കപ്പെടുന്ന ദിവസം! നരകത്തിന്റെ സ്പർശനം നിങ്ങൾ ആസ്വദിച്ചു കൊള്ളുവിൻ എന്ന് അവരോട് പറയപ്പെടും».", "malayalamMatn": "മുഖം നിലത്തു കുത്തിയനിലയില്‍ അവര്‍ നരകാഗ്നിയിലൂടെ വലിച്ചിഴക്കപ്പെടുന്ന ദിവസം. (അവരോട് പറയപ്പെടും:) നിങ്ങള്‍ നരകത്തിന്‍റെ സ്പര്‍ശനം അനുഭവിച്ച് കൊള്ളുക."}, {"ayahNumber": 49, "quranText": "إِنَّا كُلَّ شَیۡءٍ خَلَقۡنَـٰهُ بِقَدَرࣲ\n", "jalalayn": "«إنّا كُلّ شَيْء» مَنصُوب بِفِعْلٍ يُفَسِّرهُ «خَلَقْناهُ» وقُرِئَ كُلّ بِالرَّفْعِ مُبْتَدَأ خَبَره خَلَقْناهُ «خَلَقْناهُ بِقَدَرٍ» بِتَقْدِيرِ حال مِن كُلّ أيْ مُقَدَّرًا", "malayalam": "«തീർച്ചയായും ഏതൊരു വസ്തുവെയും നാം സൃഷ്ടിച്ചിരിക്കുന്നത് കൃത്യമായ ഒരു കണക്കനുസരിച്ചാകുന്നു» (നമ്മുടെ മുൻനിശ്ചയപ്രകാരം).", "malayalamMatn": "തീര്‍ച്ചയായും ഏതു വസ്തുവെയും നാം സൃഷ്ടിച്ചിട്ടുള്ളത് ഒരു വ്യവസ്ഥപ്രകാരമാകുന്നു."}, {"ayahNumber": 50, "quranText": "وَمَاۤ أَمۡرُنَاۤ إِلَّا وَ ٰ⁠حِدَةࣱ كَلَمۡحِۭ بِٱلۡبَصَرِ\n", "jalalayn": "«وما أمْرنا» لِشَيْءٍ نُرِيد وُجُوده «إلّا» مَرَّة «واحِدَة كَلَمْحٍ بِالبَصَرِ» فِي السُّرْعَة وهِيَ قَوْل: كُنْ فَيُوجَد «إنّما أمْره إذا أرادَ شَيْئًا أنْ يَقُول لَهُ كُنْ فَيَكُون»", "malayalam": "«നമ്മുടെ കൽപന കണ്ണിറുക്കുന്നതുപോലെ ഒരൊറ്റ വാക്ക് മാത്രമാകുന്നു» (കുൻ - ഉണ്ടാകൂ എന്ന് മാത്രം).", "malayalamMatn": "നമ്മുടെ കല്‍പന ഒരൊറ്റ പ്രഖ്യാപനം മാത്രമാകുന്നു. കണ്ണിന്‍റെ ഒരു ഇമവെട്ടല്‍ പോലെ."}, {"ayahNumber": 51, "quranText": "وَلَقَدۡ أَهۡلَكۡنَاۤ أَشۡیَاعَكُمۡ فَهَلۡ مِن مُّدَّكِرࣲ\n", "jalalayn": "«ولَقَدْ أهْلَكْنا أشْياعكُمْ» أشْباهكُمْ فِي الكُفْر مِن الأُمَم الماضِيَة «فَهَلْ مِن مُدَّكِر» اسْتِفْهام بِمَعْنى الأَمْر أيْ اُذْكُرُوا واتَّعِظُوا", "malayalam": "«തീർച്ചയായും നിങ്ങളെപ്പോലെയുള്ളവരെ നാം നശിപ്പിച്ചിട്ടുണ്ട്; എന്നാൽ ചിന്തിച്ചു മനസ്സിലാക്കുന്നവരായി ആരെങ്കിലുമുണ്ടോ?»", "malayalamMatn": "(ഹേ, സത്യനിഷേധികളേ,) തീര്‍ച്ചയായും നിങ്ങളുടെ കക്ഷിക്കാരെ നാം നശിപ്പിക്കുകയുണ്ടായിട്ടുണ്ട്‌. എന്നാല്‍ ആലോചിച്ച് മനസ്സിലാക്കുന്നവരായി ആരെങ്കിലുമുണ്ടോ?"}, {"ayahNumber": 52, "quranText": "وَكُلُّ شَیۡءࣲ فَعَلُوهُ فِی ٱلزُّبُرِ\n", "jalalayn": "«وكُلّ شَيْء فَعَلُوهُ» أيْ العِباد مَكْتُوب «فِي الزُّبُر» كُتُب الحَفَظَة", "malayalam": "«അവർ പ്രവർത്തിച്ച ഏതൊരു കാര്യവും രേഖകളിൽ ഉണ്ടായിരുന്നു» (മലക്കുകൾ എഴുതിവെച്ച കർമ്മപുസ്തകങ്ങളിൽ).", "malayalamMatn": "അവര്‍ പ്രവര്‍ത്തിച്ച ഏത് കാര്യവും രേഖകളിലുണ്ട്‌."}, {"ayahNumber": 53, "quranText": "وَكُلُّ صَغِیرࣲ وَكَبِیرࣲ مُّسۡتَطَرٌ\n", "jalalayn": "«وكُلّ صَغِير وكَبِير» مِن الذَّنْب أوْ العَمَل «مُسْتَطَر» مَكْتُوب فِي اللَّوْح المَحْفُوظ", "malayalam": "«ചെറുതും വലുതുമായ ഏതൊരു കാര്യവും രേഖപ്പെടുത്തപ്പെട്ടതാകുന്നു».", "malayalamMatn": "ഏത് ചെറിയകാര്യവും വലിയ കാര്യവും രേഖപ്പെടുത്തി വെക്കപ്പെടുന്നതാണ്‌."}, {"ayahNumber": 54, "quranText": "إِنَّ ٱلۡمُتَّقِینَ فِی جَنَّـٰتࣲ وَنَهَرࣲ\n", "jalalayn": "«إنّ المُتَّقِينَ فِي جَنّات» بَساتِين «ونَهَر» أُرِيدَ بِهِ الجِنْس وقُرِئَ بِضَمِّ النُّون والهاء جَمْعًا كَأَسَدِ وأُسْد والمَعْنى أنَّهُمْ يَشْرَبُونَ مِن أنَهارها الماء واللَّبَن والعَسَل والخَمْر", "malayalam": "«തീർച്ചയായും ഭയഭക്തിയുള്ളവർ സ്വർഗ്ഗത്തോപ്പുകളിലും അരുവികളിലുമായിരിക്കും».", "malayalamMatn": "തീര്‍ച്ചയായും ധര്‍മ്മനിഷ്ഠ പാലിച്ചവര്‍ ഉദ്യാനങ്ങളിലും അരുവികളിലുമായിരിക്കും."}, {"ayahNumber": 55, "quranText": "فِی مَقۡعَدِ صِدۡقٍ عِندَ مَلِیكࣲ مُّقۡتَدِرِۭ\n", "jalalayn": "«فِي مَقْعَد صِدْق» مَجْلِس حَقّ لا لَغْو فِيهِ ولا تَأْثِيم أُرِيدَ بِهِ الجِنْس وقُرِئَ مَقاعِد المَعْنى أنَّهُمْ فِي مَجالِس مِن الجَنّات سالِمَة مِن اللَّغْو والتَّأْثِيم بِخِلافِ مَجالِس الدُّنْيا فَقَلَّ أنْ تَسْلَم مِن ذَلِكَ وأُعْرِبَ هَذا خَبَرًا ثانِيًا وبَدَلًا وهُوَ صادِق بِبَدَلِ البَعْض وغَيْره «عِنْد مَلِيك» مِثال مُبالَغَة أيْ عَزِيز المُلْك واسِعه «مُقْتَدِر» قادِر لا يُعْجِزهُ شَيْء وهُوَ اللَّه تَعالى وعِنْده إشارَة إلى الرُّتْبَة والقُرْبَة مِن فَضْله تَعالى", "malayalam": "«സത്യസന്ധതയുടെ ഇരിപ്പിടത്തിൽ, സർവ്വാധിപനായ രാജാവിന്റെ അടുക്കൽ» (അല്ലാഹുവിന്റെ അപാരമായ പ്രീതിയിലും സാമീപ്യത്തിലും).", "malayalamMatn": "സത്യത്തിന്‍റെ ഇരിപ്പിടത്തില്‍, ശക്തനായ രാജാവിന്‍റെ അടുക്കല്‍."}], "topPoints": ["ചന്ദ്രൻ പിളർന്ന അത്ഭുത സംഭവം (خلاصة السورة)", "മുൻകാല സമുദായങ്ങളുടെ ധിക്കാരവും അവർക്കേറ്റ ശിക്ഷയും"], "topQuestions": [{"q": "ഖുർആൻ പഠിക്കാൻ എളുപ്പമാണോ?", "a": "അതെ, ഖുർആൻ പഠിക്കാനും ഓർമ്മിക്കാനും അല്ലാഹു എളുപ്പമാക്കിയിട്ടുണ്ടെന്ന് ഈ സൂറത്ത് ആവർത്തിച്ചു പറയുന്നു."}], "asbabAlNuzul": [{"ayahNumber": 45, "quranText": "سَیُهۡزَمُ ٱلۡجَمۡعُ وَیُوَلُّونَ ٱلدُّبُرَ", "arabicSnippet": "«أم يقولون نحن جميع منتصر» أي كفار قريش جمع منتصر على محمد، ولما قال أبو جهل يوم بدر إنا جمع منتصر نزل: «سيهزم الجمع ويولون الدبر».", "malayalamExplanation": "ബദ്ർ യുദ്ധദിവസം ഖുറൈശി സൈന്യത്തിന്റെ മുന്നിൽ വെച്ച് അബൂജഹൽ \"ഞങ്ങൾ ആർക്കും തോൽപിക്കാൻ കഴിയാത്ത, പരസ്പരം സഹായിക്കുന്ന അതിശക്തമായ ഒരു സംഘമാണ് (ഇന്നാ ജംഉൻ മുൻതസ്വിർ)\" എന്ന് അഹങ്കാരത്തോടെ വിളിച്ചുപറഞ്ഞു. അബൂജഹലിന്റെ ഈ അഹങ്കാരത്തിന് മറുപടിയായി, ആ സംഘം ഉടൻ തന്നെ ദയനീയമായി പരാജയപ്പെടുമെന്നും അവർ യുദ്ധക്കളത്തിൽ നിന്ന് പിന്തിരിഞ്ഞോടുമെന്നും പ്രവചിച്ചുകൊണ്ട് അല്ലാഹു ഈ സൂക്തം അവതരിപ്പിച്ചു."}]}, {"surahNumber": 55, "surahNameArabic": "سُورَةُ الرَّحۡمَٰن", "surahNameMalayalam": "സൂറത്തുറഹ്‌മാൻ (പരമകാരുണികൻ)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ ٱلرَّحۡمَـٰنُ\n", "jalalayn": "«الرَّحْمَن» اللَّه تَعالى", "malayalam": "«പരമകാരുണികനായ അല്ലാഹു».", "malayalamMatn": "പരമകാരുണികന്‍"}, {"ayahNumber": 2, "quranText": "عَلَّمَ ٱلۡقُرۡءَانَ\n", "jalalayn": "«عَلَّمَ» مَن شاءَ", "malayalam": "«അവൻ ഖുർആൻ പഠിപ്പിച്ചു കൊടുത്തു» (താൻ ഉദ്ദേശിച്ച തന്റെ ദാസന്മാർക്ക്).", "malayalamMatn": "ഈ ഖുര്‍ആന്‍ പഠിപ്പിച്ചു."}, {"ayahNumber": 3, "quranText": "خَلَقَ ٱلۡإِنسَـٰنَ\n", "jalalayn": "«خَلَقَ الإنْسان» أيْ الجِنْس", "malayalam": "«അവൻ മനുഷ്യനെ സൃഷ്ടിച്ചു» (മനുഷ്യവർഗ്ഗത്തെ).", "malayalamMatn": "അവന്‍ മനുഷ്യനെ സൃഷ്ടിച്ചു."}, {"ayahNumber": 4, "quranText": "عَلَّمَهُ ٱلۡبَیَانَ\n", "jalalayn": "«عَلَّمَهُ البَيان» النُّطْق", "malayalam": "«അവന് ആശയവിനിമയം» (സംസാരശേഷിയും കാര്യങ്ങൾ വ്യക്തമാക്കാനുള്ള കഴിവും) «പഠിപ്പിച്ചു».", "malayalamMatn": "അവനെ അവന്‍ സംസാരിക്കാന്‍ പഠിപ്പിച്ചു."}, {"ayahNumber": 5, "quranText": "ٱلشَّمۡسُ وَٱلۡقَمَرُ بِحُسۡبَانࣲ\n", "jalalayn": "«الشَّمْس والقَمَر بِحُسْبانٍ» يَجْرِيانِ", "malayalam": "«സൂര്യനും ചന്ദ്രനും കൃത്യമായ കണക്കനുസരിച്ചാകുന്നു സഞ്ചരിക്കുന്നത്».", "malayalamMatn": "സൂര്യനും ചന്ദ്രനും ഒരു കണക്കനുസരിച്ചാകുന്നു (സഞ്ചരിക്കുന്നത്‌.)"}, {"ayahNumber": 6, "quranText": "وَٱلنَّجۡمُ وَٱلشَّجَرُ یَسۡجُدَانِ\n", "jalalayn": "«والنَّجْم» ما لا ساقَ لَهُ مِن النَّبات «والشَّجَر» ما لَهُ ساق «يَسْجُدانِ» يَخْضَعانِ لِما يُراد مِنهُما", "malayalam": "«ചെടികളും മരങ്ങളും അവന് സാഷ്ടാംഗം ചെയ്യുന്നു» (അവന്റെ കൽപനകൾക്ക് വഴങ്ങുന്നു).", "malayalamMatn": "ചെടികളും വൃക്ഷങ്ങളും (അല്ലാഹുവിന്‌) പ്രണാമം അര്‍പ്പിച്ചു കൊണ്ടിരിക്കുന്നു."}, {"ayahNumber": 7, "quranText": "وَٱلسَّمَاۤءَ رَفَعَهَا وَوَضَعَ ٱلۡمِیزَانَ\n", "jalalayn": "«والسَّماء رَفَعَها ووَضَعَ المِيزان» أثْبَت العَدْل", "malayalam": "«ആകാശത്തെ അവൻ ഉയർത്തുകയും തുലാസ്സ്» (നീതിയുടെ അളവുകോൽ) «സ്ഥാപിക്കുകയും ചെയ്തു».", "malayalamMatn": "ആകാശത്തെ അവന്‍ ഉയര്‍ത്തുകയും, (എല്ലാകാര്യവും തൂക്കികണക്കാക്കുവാനുള്ള) തുലാസ് അവന്‍ സ്ഥാപിക്കുകയും ചെയ്തിരിക്കുന്നു."}, {"ayahNumber": 8, "quranText": "أَلَّا تَطۡغَوۡا۟ فِی ٱلۡمِیزَانِ\n", "jalalayn": "«ألّا تَطْغَوْا» أيْ لِأَجْلِ أنْ لا تَجُورُوا «فِي المِيزان» ما يُوزَن بِهِ", "malayalam": "«നിങ്ങൾ അളവിൽ അതിരുകവിയാതിരിക്കാൻ വേണ്ടി».", "malayalamMatn": "നിങ്ങള്‍ തുലാസില്‍ ക്രമക്കേട് വരുത്താതിരിക്കുവാന്‍ വേണ്ടിയാണത്‌."}, {"ayahNumber": 9, "quranText": "وَأَقِیمُوا۟ ٱلۡوَزۡنَ بِٱلۡقِسۡطِ وَلَا تُخۡسِرُوا۟ ٱلۡمِیزَانَ\n", "jalalayn": "«وأَقِيمُوا الوَزْن بِالقِسْطِ» بِالعَدْلِ «ولا تُخْسِرُوا المِيزان» تُنْقِصُوا المَوْزُون", "malayalam": "«നിങ്ങൾ തുലനം നീതിപൂർവ്വം നിലനിർത്തുക, അളവിൽ കുറവ് വരുത്തരുത്».", "malayalamMatn": "നിങ്ങള്‍ നീതി പൂര്‍വ്വം തൂക്കം ശരിയാക്കുവിന്‍. തുലാസില്‍ നിങ്ങള്‍ കമ്മി വരുത്തരുത്‌."}, {"ayahNumber": 10, "quranText": "وَٱلۡأَرۡضَ وَضَعَهَا لِلۡأَنَامِ\n", "jalalayn": "«والأَرْض وضَعَها» أثْبَتَها «لِلْأَنامِ» لِلْخَلْقِ الإنْس والجِنّ وغَيْرهمْ", "malayalam": "«ഭൂമിയെ അവൻ സൃഷ്ടികൾക്കായി വിരിച്ചു കൊടുത്തു».", "malayalamMatn": "ഭൂമിയെ അവന്‍ മനുഷ്യര്‍ക്കായി വെച്ചിരിക്കുന്നു."}, {"ayahNumber": 11, "quranText": "فِیهَا فَـٰكِهَةࣱ وَٱلنَّخۡلُ ذَاتُ ٱلۡأَكۡمَامِ\n", "jalalayn": "«فِيها فاكِهَة والنَّخْل» المَعْهُود «ذات الأَكْمام» أوْعِيَة طَلْعها", "malayalam": "«അതിൽ പഴവർഗ്ഗങ്ങളും പോളകളുള്ള ഈത്തപ്പനകളുമുണ്ട്».", "malayalamMatn": "അതില്‍ പഴങ്ങളും കൂമ്പോളകളുള്ള ഈന്തപ്പനകളുമുണ്ട്‌."}, {"ayahNumber": 12, "quranText": "وَٱلۡحَبُّ ذُو ٱلۡعَصۡفِ وَٱلرَّیۡحَانُ\n", "jalalayn": "«والحَبّ» كالحِنْطَةِ والشَّعِير «ذُو العَصْف» التِّبْن «والرَّيْحان» الوَرَق المَشْمُوم", "malayalam": "«വൈക്കോലോടു കൂടിയ ധാന്യങ്ങളും സുഗന്ധ സസ്യങ്ങളുമുണ്ട്».", "malayalamMatn": "വൈക്കോലുള്ള ധാന്യങ്ങളും സുഗന്ധച്ചെടികളുമുണ്ട്‌."}, {"ayahNumber": 13, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَيِّ آلاء» نِعَم «رَبّكُما» أيّها الإنْس والجِنّ «تُكَذِّبانِ» ذُكِرَتْ إحْدى وثَلاثِينَ مَرَّة والِاسْتِفْهام فِيها لِلتَّقْرِيرِ لِما رَوى الحاكِم عَنْ جابِر قالَ: \"قَرَأَ عَلَيْنا رَسُول اللَّه ﷺ سُورَة الرَّحْمَن حَتّى خَتَمَها ثُمَّ قالَ: مالِي أراكُمْ سُكُوتًا لَلْجِنّ كانُوا أحْسَن مِنكُمْ رَدًّا ما قَرَأْت عَلَيْهِمْ هَذِهِ الآيَة مِن مَرَّة «فَبِأَيِّ آلاء رَبّكُما تُكَذِّبانِ» إلّا قالُوا: ولا بِشَيْءٍ مِن نِعَمك رَبّنا نُكَذِّب فَلَك الحَمْد", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും» (മനുഷ്യരുടെയും ജിന്നുകളുടെയും) «രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവ് ചെയ്ത അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 14, "quranText": "خَلَقَ ٱلۡإِنسَـٰنَ مِن صَلۡصَـٰلࣲ كَٱلۡفَخَّارِ\n", "jalalayn": "«خَلَقَ الإنْسان» آدَم «مِن صَلْصال» طِين يابِس يُسْمَع لَهُ صَلْصَلَة أيْ صَوْت إذا نُقِرَ «كالفَخّارِ» وهُوَ ما طُبِخَ مِن طِين", "malayalam": "«ചുട്ട കളിമൺപാത്രം പോലെയുള്ള ഉണങ്ങിയ മണ്ണിൽ നിന്നാണ് അവൻ മനുഷ്യനെ» (ആദം നബിയെ) «സൃഷ്ടിച്ചത്».", "malayalamMatn": "കലം പോലെ മുട്ടിയാല്‍ മുഴക്കമുണ്ടാകുന്ന (ഉണങ്ങിയ) കളിമണ്ണില്‍ നിന്ന് മനുഷ്യനെ അവന്‍ സൃഷ്ടിച്ചു."}, {"ayahNumber": 15, "quranText": "وَخَلَقَ ٱلۡجَاۤنَّ مِن مَّارِجࣲ مِّن نَّارࣲ\n", "jalalayn": "«وخَلَقَ الجانّ» أبا الجِنّ وهُوَ إبْلِيس «مِن مارِج مِن نار» هُوَ لَهَبها الخالِص مِن الدُّخان", "malayalam": "«പുകയില്ലാത്ത ശുദ്ധമായ തീജ്വാലയിൽ നിന്നാണ് അവൻ ജിന്നിനെ സൃഷ്ടിച്ചത്».", "malayalamMatn": "തിയ്യിന്‍റെ പുകയില്ലാത്ത ജ്വാലയില്‍ നിന്ന് ജിന്നിനെയും അവന്‍ സൃഷ്ടിച്ചു."}, {"ayahNumber": 16, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരുവിഭാഗത്തിന്‍റെയും രക്ഷിതാവ് ചെയ്ത അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 17, "quranText": "رَبُّ ٱلۡمَشۡرِقَیۡنِ وَرَبُّ ٱلۡمَغۡرِبَیۡنِ\n", "jalalayn": "«رَبّ المَشْرِقَيْنِ» مَشْرِق الشِّتاء ومَشْرِق الصَّيْف «ورَبّ المَغْرِبَيْنِ» مَغْرِب الصَّيْف ومَغْرِب الشِّتاء", "malayalam": "«രണ്ട് ഉദയസ്ഥാനങ്ങളുടെയും രണ്ട് അസ്തമയസ്ഥാനങ്ങളുടെയും രക്ഷിതാവാകുന്നു അവൻ» (വേനൽക്കാലത്തെയും തണുപ്പുകാലത്തെയും ഉദയാസ്തമയങ്ങൾ).", "malayalamMatn": "രണ്ട് ഉദയസ്ഥാനങ്ങളുടെ രക്ഷിതാവും രണ്ട് അസ്തമന സ്ഥാനങ്ങളുടെ രക്ഷിതാവുമാകുന്നു അവന്‍."}, {"ayahNumber": 18, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവ് ചെയ്ത അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 19, "quranText": "مَرَجَ ٱلۡبَحۡرَیۡنِ یَلۡتَقِیَانِ\n", "jalalayn": "«مَرَجَ» أرْسَلَ «البَحْرَيْنِ» العَذْب والمِلْح «يَلْتَقِيانِ» فِي رَأْي العَيْن", "malayalam": "«പരസ്പരം സന്ധിക്കുന്ന രണ്ട് കടലുകളെ അവൻ ഒഴുക്കിവിട്ടു» (ഉപ്പുരസമുള്ളതും മധുരമുള്ളതുമായ ജലാശയങ്ങൾ).", "malayalamMatn": "രണ്ട് കടലുകളെ (ജലാശയങ്ങളെ) തമ്മില്‍ കൂടിച്ചേരത്തക്ക വിധം അവന്‍ അയച്ചുവിട്ടിരിക്കുന്നു."}, {"ayahNumber": 20, "quranText": "بَیۡنَهُمَا بَرۡزَخࣱ لَّا یَبۡغِیَانِ\n", "jalalayn": "«بَيْنهما بَرْزَخ» حاجِز مِن قُدْرَته تَعالى «لا يَبْغِيانِ» لا يَبْغِي واحِد مِنهُما عَلى الآخَر فَيَخْتَلِط بِهِ", "malayalam": "«അവ രണ്ടിനുമിടയിൽ ഒരു മറയുണ്ട്; അവ പരസ്പരം അതിരുകടക്കുകയില്ല» (ഒന്നിന്റെ രസം മറ്റൊന്നിനെ നശിപ്പിക്കാത്ത വിധം).", "malayalamMatn": "അവ രണ്ടിനുമിടക്ക് അവ അന്യോന്യം അതിക്രമിച്ച് കടക്കാതിരിക്കത്തക്കവിധം ഒരു തടസ്സമുണ്ട്‌."}, {"ayahNumber": 21, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 22, "quranText": "یَخۡرُجُ مِنۡهُمَا ٱللُّؤۡلُؤُ وَٱلۡمَرۡجَانُ\n", "jalalayn": "«يَخْرُج» بِالبِناءِ لِلْمَفْعُولِ والفاعِل «مِنهُما» مِن مَجْمُوعهما الصّادِق بِأَحَدِهِما وهُوَ المِلْح «اللُّؤْلُؤ والمَرْجان» خَرَز أحْمَر أوْ صِغار اللُّؤْلُؤ", "malayalam": "«അവ രണ്ടിൽ നിന്നുമായി മുത്തും പവിഴവും പുറപ്പെടുന്നു».", "malayalamMatn": "അവ രണ്ടില്‍ നിന്നും മുത്തും പവിഴവും പുറത്തു വരുന്നു."}, {"ayahNumber": 23, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 24, "quranText": "وَلَهُ ٱلۡجَوَارِ ٱلۡمُنشَـَٔاتُ فِی ٱلۡبَحۡرِ كَٱلۡأَعۡلَـٰمِ\n", "jalalayn": "«ولَهُ الجَوار» السُّفُن «المُنْشَآت» المُحْدَثات «فِي البَحْر كالأَعْلامِ» كالجِبالِ عِظَمًا وارْتِفاعًا", "malayalam": "«പർവ്വതങ്ങളെപ്പോലെ സമുദ്രത്തിൽ ഉയർന്നുനിൽക്കുന്ന കപ്പലുകളും അവന്നുള്ളതാകുന്നു».", "malayalamMatn": "സമുദ്രത്തില്‍ (സഞ്ചരിക്കുവാന്‍) മലകള്‍ പോലെ പൊക്കി ഉണ്ടാക്കപ്പെടുന്ന കപ്പലുകളും അവന്‍റെ നിയന്ത്രണത്തിലാകുന്നു."}, {"ayahNumber": 25, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 26, "quranText": "كُلُّ مَنۡ عَلَیۡهَا فَانࣲ\n", "jalalayn": "«كُلّ مَن عَلَيْها» أيْ الأَرْض مِن الحَيَوان «فانٍ» هالِك وعَبَّرَ بِمَن تَغْلِيبًا لِلْعُقَلاءِ", "malayalam": "«ഭൂമിയിലുള്ള സർവ്വ വസ്തുക്കളും നശിച്ചുപോകുന്നവയാകുന്നു».", "malayalamMatn": "അവിടെ (ഭൂമുഖത്ത്‌)യുള്ള എല്ലാവരും നശിച്ച് പോകുന്നവരാകുന്നു."}, {"ayahNumber": 27, "quranText": "وَیَبۡقَىٰ وَجۡهُ رَبِّكَ ذُو ٱلۡجَلَـٰلِ وَٱلۡإِكۡرَامِ\n", "jalalayn": "«ويَبْقى وجْه رَبّك» ذاته «ذُو الجَلال» العَظَمَة «والإكْرام» لِلْمُؤْمِنِينَ بِأَنْعُمِهِ عَلَيْهِمْ", "malayalam": "«മഹത്വവും ആദരവുമുള്ളവനായ നിന്റെ രക്ഷിതാവിന്റെ മുഖം» (സത്ത) «മാത്രം ശാശ്വതമായി അവശേഷിക്കും».", "malayalamMatn": "മഹത്വവും ഉദാരതയും ഉള്ളവനായ നിന്‍റെ രക്ഷിതാവിന്‍റെ മുഖം അവശേഷിക്കുന്നതാണ്‌."}, {"ayahNumber": 28, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 29, "quranText": "یَسۡـَٔلُهُۥ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ كُلَّ یَوۡمٍ هُوَ فِی شَأۡنࣲ\n", "jalalayn": "«يَسْأَلهُ مَن فِي السَّماوات والأَرْض» بِنُطْقٍ أوْ حال: ما يَحْتاجُونَ إلَيْهِ مِن القُوَّة عَلى العِبادَة والرِّزْق والمَغْفِرَة وغَيْر ذَلِكَ «كُلّ يَوْم» وقْت «هُوَ فِي شَأْن» أمْر يُظْهِرهُ عَلى وفْق ما قَدَّرَهُ فِي الأَزَل مِن إحْياء وإماتَة وإعْزاز وإذْلال وإغْناء وإعْدام وإجابَة داعٍ وإعْطاء سائِل وغَيْر ذَلِكَ", "malayalam": "«ആകാശങ്ങളിലും ഭൂമിയിലുമുള്ള സർവ്വരും അവനോടാണ് ചോദിച്ചുകൊണ്ടിരിക്കുന്നത്; ഓരോ ദിവസവും അവൻ ഓരോ കാര്യത്തിലാകുന്നു» (ഒരാളെ ജീവിപ്പിക്കുന്നു, മറ്റൊരാളെ മരിപ്പിക്കുന്നു, പ്രാർത്ഥനകൾക്ക് ഉത്തരം നൽകുന്നു).", "malayalamMatn": "ആകാശങ്ങളിലും ഭൂമിയിലും ഉള്ളവര്‍ അവനോട് ചോദിച്ചു കൊണ്ടിരിക്കുന്നു. എല്ലാ ദിവസവും അവന്‍ കാര്യനിര്‍വഹണത്തിലാകുന്നു."}, {"ayahNumber": 30, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 31, "quranText": "سَنَفۡرُغُ لَكُمۡ أَیُّهَ ٱلثَّقَلَانِ\n", "jalalayn": "«سَنَفْرُغُ لَكُمْ» سَنَقْصِدُ لِحِسابِكُمْ «أيّها الثَّقَلانِ» الإنْس والجِنّ", "malayalam": "«ഹേ രണ്ടു ഭാരമുള്ള വിഭാഗങ്ങളേ» (മനുഷ്യരേ, ജിന്നുകളേ), «വഴിയെ നാം നിങ്ങളുടെ കാര്യം തീർപ്പാക്കാനായി ഒഴിവ് കണ്ടെത്തുന്നതാണ്» (വിചാരണക്കായി).", "malayalamMatn": "ഹേ; ഭാരിച്ച രണ്ട് സമൂഹങ്ങളേ, നിങ്ങളുടെ കാര്യത്തിനായി നാം ഒഴിഞ്ഞിരിക്കുന്നതാണ്‌."}, {"ayahNumber": 32, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 33, "quranText": "یَـٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ إِنِ ٱسۡتَطَعۡتُمۡ أَن تَنفُذُوا۟ مِنۡ أَقۡطَارِ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ فَٱنفُذُوا۟ۚ لَا تَنفُذُونَ إِلَّا بِسُلۡطَـٰنࣲ\n", "jalalayn": "«يا مَعْشَر الجِنّ والإنْس إنِ اسْتَطَعْتُمْ أنْ تَنْفُذُوا» تَخْرُجُوا «مِن أقْطار» نَواحِي «السَّماوات والأَرْض فانْفُذُوا» أمْر تَعْجِيز «لا تَنْفُذُونَ إلّا بِسُلْطانٍ» بِقُوَّةٍ ولا قُوَّة لَكُمْ عَلى ذَلِكَ", "malayalam": "«ജിന്നുകളുടെയും മനുഷ്യരുടെയും സംഘമേ, ആകാശങ്ങളുടെയും ഭൂമിയുടെയും അതിരുകൾ ഭേദിച്ച് പുറത്തുപോകാൻ നിങ്ങൾക്ക് സാധിക്കുമെങ്കിൽ നിങ്ങൾ പുറത്തുപോവുക! വ്യക്തമായ ഒരു അധികാരത്തോടു കൂടിയല്ലാതെ» (അല്ലാഹുവിന്റെ ശക്തിയില്ലാതെ) «നിങ്ങൾക്ക് കടന്നുപോവാനാകില്ല!».", "malayalamMatn": "ജിന്നുകളുടെയും മനുഷ്യരുടെയും സമൂഹമേ, ആകാശങ്ങളുടെയും ഭൂമിയുടെയും മേഖലകളില്‍ നിന്ന് പുറത്ത് കടന്നു പോകാന്‍ നിങ്ങള്‍ക്ക് സാധിക്കുന്ന പക്ഷം നിങ്ങള്‍ കടന്നു പോയിക്കൊള്ളുക. ഒരു അധികാരം ലഭിച്ചിട്ടല്ലാതെ നിങ്ങള്‍ കടന്നു പോകുകയില്ല."}, {"ayahNumber": 34, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 35, "quranText": "یُرۡسَلُ عَلَیۡكُمَا شُوَاظࣱ مِّن نَّارࣲ وَنُحَاسࣱ فَلَا تَنتَصِرَانِ\n", "jalalayn": "«يُرْسَل عَلَيْكُما شُواظ مِن نار» هُوَ لَهَبها الخالِص مِن الدُّخان أوْ مَعَهُ «ونُحاس» أيْ دُخان لا لَهَب فِيهِ «فَلا تَنْتَصِرانِ» تَمْتَنِعانِ مِن ذَلِكَ بَلْ يَسُوقكُمْ إلى المَحْشَر", "malayalam": "«പുകയില്ലാത്ത തീജ്വാലകളും ഉരുകിയ ചെമ്പും നിങ്ങളുടെ നേരെ അയക്കപ്പെടും; അപ്പോൾ നിങ്ങൾക്ക് സ്വയം രക്ഷിക്കാനാവില്ല!».", "malayalamMatn": "നിങ്ങള്‍ ഇരുവിഭാഗത്തിന്‍റെയും നേര്‍ക്ക് തീജ്വാലയും പുകയും അയക്കപ്പെടും. അപ്പോള്‍ നിങ്ങള്‍ക്ക് രക്ഷാമാര്‍ഗം സ്വീകരിക്കാനാവില്ല."}, {"ayahNumber": 36, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരുവിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌."}, {"ayahNumber": 37, "quranText": "فَإِذَا ٱنشَقَّتِ ٱلسَّمَاۤءُ فَكَانَتۡ وَرۡدَةࣰ كَٱلدِّهَانِ\n", "jalalayn": "«فَإذا انْشَقَّتِ السَّماء» انْفَرَجَتْ أبْوابًا لِنُزُولِ المَلائِكَة «فَكانَتْ ورْدَة» أيْ مِثْلها مُحْمَرَّة «كالدِّهانِ» كالأَدِيمِ الأَحْمَر عَلى خِلاف العَهْد بِها وجَواب إذا فَما أعْظَم الهَوْل", "malayalam": "«ആകാശം പിളർന്ന് അത് ചുവന്ന തോൽ പോലെയായിത്തീരുന്ന സന്ദർഭം!».", "malayalamMatn": "എന്നാല്‍ ആകാശം പൊട്ടിപ്പിളരുകയും, അത് കുഴമ്പു പോലുള്ളതും റോസ് നിറമുള്ളതും ആയിത്തീരുകയും ചെയ്താല്‍"}, {"ayahNumber": 38, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 39, "quranText": "فَیَوۡمَىِٕذࣲ لَّا یُسۡـَٔلُ عَن ذَنۢبِهِۦۤ إِنسࣱ وَلَا جَاۤنࣱّ\n", "jalalayn": "«فَيَوْمئِذٍ لا يُسْأَل عَنْ ذَنْبه إنْس ولا جانّ» عَنْ ذَنْبه ويُسْأَلُونَ فِي وقْت آخَر «فَوَرَبِّك لَنَسْأَلَنَّهُمْ أجْمَعِينَ» والجانّ هُنا وفِيما سَيَأْتِي بِمَعْنى الجِنّ والإنْس فِيهِما بِمَعْنى الإنْسِيّ", "malayalam": "«അന്നേ ദിവസം മനുഷ്യനോ ജിന്നോ തന്റെ പാപത്തെപ്പറ്റി ചോദിക്കപ്പെടുകയില്ല» (അവരുടെ മുഖലക്ഷണങ്ങൾ തന്നെ അവരുടെ അവസ്ഥ വെളിപ്പെടുത്തും).", "malayalamMatn": "ഒരു മനുഷ്യനോടോ, ജിന്നിനോടോ അന്നേ ദിവസം അവന്‍റെ പാപത്തെപ്പറ്റി അന്വേഷിക്കപ്പെടുകയില്ല."}, {"ayahNumber": 40, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 41, "quranText": "یُعۡرَفُ ٱلۡمُجۡرِمُونَ بِسِیمَـٰهُمۡ فَیُؤۡخَذُ بِٱلنَّوَ ٰ⁠صِی وَٱلۡأَقۡدَامِ\n", "jalalayn": "«يُعْرَف المُجْرِمُونَ بِسِيماهُمْ» سَواد الوُجُوه وزُرْقَة العُيُون «فَيُؤْخَذ بِالنَّواصِي والأَقْدام» «فَبِأَيِّ آلاء رَبّكُما تُكَذِّبانِ» تُضَمّ ناصِيَة كُلّ مِنهُمْ إلى قَدَمَيْهِ مِن خَلْف أوْ قُدّام ويُلْقى فِي النّار ويُقال لَهُمْ: «هَذِهِ جَهَنَّم الَّتِي يُكَذِّب بِها المُجْرِمُونَ»", "malayalam": "«കുറ്റവാളികൾ തങ്ങളുടെ അടയാളങ്ങൾ കൊണ്ട് തിരിച്ചറിയപ്പെടും; അവരുടെ നെറ്റിത്തടത്തിലെ മുൻകുടുമികളും കാലുകളും പിടിക്കപ്പെടും» (എന്നിട്ട് നരകത്തിലേക്ക് എറിയപ്പെടും).", "malayalamMatn": "കുറ്റവാളികള്‍ അവരുടെ അടയാളം കൊണ്ട് തിരിച്ചറിയപ്പെടും. എന്നിട്ട് (അവരുടെ) കുടുമകളിലും പാദങ്ങളിലും പിടിക്കപ്പെടും."}, {"ayahNumber": 42, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 43, "quranText": "هَـٰذِهِۦ جَهَنَّمُ ٱلَّتِی یُكَذِّبُ بِهَا ٱلۡمُجۡرِمُونَ\n", "jalalayn": "«هَـٰذِهِۦ جَهَنَّمُ ٱلَّتِی یُكَذِّبُ بِهَا ٱلۡمُجۡرِمُونَ».", "malayalam": "«കുറ്റവാളികൾ നിഷേധിച്ചു തള്ളിക്കളഞ്ഞിരുന്ന നരകം ഇതാകുന്നു!».", "malayalamMatn": "ഇതാകുന്നു കുറ്റവാളികള്‍ നിഷേധിച്ച് തള്ളുന്നതായ നരകം."}, {"ayahNumber": 44, "quranText": "یَطُوفُونَ بَیۡنَهَا وَبَیۡنَ حَمِیمٍ ءَانࣲ\n", "jalalayn": "«يَطُوفُونَ» يَسْعَوْنَ «بَيْنها وبَيْن حَمِيم» ماء حارّ «آنٍ» شَدِيد الحَرارَة يُسْقَوْنَهُ إذا اسْتَغاثُوا مِن حَرّ النّار وهُوَ مَنقُوص كَقاضٍ", "malayalam": "«അതിനും അത്യധികം തിളച്ചുമറിയുന്ന വെള്ളത്തിനുമിടയിൽ അവർ ചുറ്റിക്കറങ്ങിക്കൊണ്ടിരിക്കും».", "malayalamMatn": "അതിന്നും തിളച്ചുപൊള്ളുന്ന ചുടുവെള്ളത്തിനുമിടക്ക് അവര്‍ ചുറ്റിത്തിരിയുന്നതാണ്‌."}, {"ayahNumber": 45, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 46, "quranText": "وَلِمَنۡ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ\n", "jalalayn": "«ولِمَن خافَ» أيْ لِكُلٍّ مِنهُمْ أوْ لِمَجْمُوعِهِمْ «مَقام رَبّه» قِيامه بَيْن يَدَيْهِ لِلْحِسابِ فَتَرَكَ مَعْصِيَته", "malayalam": "«തന്റെ രക്ഷിതാവിന്റെ സന്നിധിയെ ഭയപ്പെട്ടവന് രണ്ട് സ്വർഗ്ഗത്തോപ്പുകളുണ്ട്».", "malayalamMatn": "തന്‍റെ രക്ഷിതാവിന്‍റെ സന്നിധിയെ ഭയപ്പെട്ടവന്ന് രണ്ട് സ്വര്‍ഗത്തോപ്പുകളുണ്ട്‌."}, {"ayahNumber": 47, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 48, "quranText": "ذَوَاتَاۤ أَفۡنَانࣲ\n", "jalalayn": "«ذَواتا» تَثْنِيَة ذَوات عَلى الأَصْل ولامها ياء «أفْنان» أغْصان جَمْع فَنَن كَطَلَلٍ", "malayalam": "«വിവിധ ശാഖകളോടും തണലുകളോടും കൂടിയവയാകുന്നു അവ രണ്ടും».", "malayalamMatn": "പല തരം സുഖഐശ്വര്യങ്ങളുള്ള രണ്ടു (സ്വര്‍ഗത്തോപ്പുകള്‍)"}, {"ayahNumber": 49, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 50, "quranText": "فِیهِمَا عَیۡنَانِ تَجۡرِیَانِ\n", "jalalayn": "«فِیهِمَا عَیۡنَانِ تَجۡرِیَانِ».", "malayalam": "«അവ രണ്ടിലും ഒഴുകിക്കൊണ്ടിരിക്കുന്ന രണ്ട് ഉറവകളുണ്ട്».", "malayalamMatn": "അവ രണ്ടിലും ഒഴുകികൊണ്ടിരിക്കുന്ന രണ്ടു അരുവികളുണ്ട്‌."}, {"ayahNumber": 51, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 52, "quranText": "فِیهِمَا مِن كُلِّ فَـٰكِهَةࣲ زَوۡجَانِ\n", "jalalayn": "«فِيهِما مِن كُلّ فاكِهَة» فِي الدُّنْيا أوْ كُلّ ما يُتَفَكَّه بِهِ «زَوْجانِ» نَوْعانِ رَطْب ويابِس والمُرّ مِنهُما فِي الدُّنْيا كالحَنْظَلِ حُلْو", "malayalam": "«അവ രണ്ടിലും എല്ലാ ഫലവർഗ്ഗങ്ങളിൽ നിന്നും ഈരണ്ട് തരങ്ങൾ ഉണ്ടായിരിക്കും».", "malayalamMatn": "അവ രണ്ടിലും ഓരോ പഴവര്‍ഗത്തില്‍ നിന്നുമുള്ള ഈ രണ്ടു ഇനങ്ങളുണ്ട്‌."}, {"ayahNumber": 53, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിൻ്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 54, "quranText": "مُتَّكِـِٔینَ عَلَىٰ فُرُشِۭ بَطَاۤىِٕنُهَا مِنۡ إِسۡتَبۡرَقࣲۚ وَجَنَى ٱلۡجَنَّتَیۡنِ دَانࣲ\n", "jalalayn": "«مُتَّكِئِينَ» حال عامِله مَحْذُوف أيْ يَتَنَعَّمُونَ «عَلى فُرُش بَطائِنها مِن إسْتَبْرَق» ما غَلُظَ مِن الدِّيباج وخَشُنَ والظَّهائِر مِن السُّنْدُس «وجَنى الجَنَّتَيْنِ» ثَمَرهما «دانٍ» قَرِيب يَنالهُ القائِم والقاعِد والمُضْطَجِع", "malayalam": "«കട്ടിപ്പട്ടു കൊണ്ട് ഉൾഭാഗം നിർമ്മിക്കപ്പെട്ട വിരിപ്പുകളിൽ ചാരിയിരിക്കുന്നവരായിരിക്കും അവർ; ആ രണ്ട് സ്വർഗ്ഗത്തോപ്പുകളിലെയും പഴങ്ങൾ കൈയെത്തും ദൂരത്ത് പറിച്ചെടുക്കാവുന്നതായിരിക്കും».", "malayalamMatn": "അവര്‍ ചില മെത്തകളില്‍ ചാരി ഇരിക്കുന്നവരായിരിക്കും. അവയുടെ ഉള്‍ഭാഗങ്ങള്‍ കട്ടികൂടിയ പട്ടുകൊണ്ട് നിര്‍മിക്കപ്പെട്ടതാകുന്നു. ആ രണ്ട് തോപ്പുകളിലെയും കായ്കനികള്‍ താഴ്ന്നു നില്‍ക്കുകയായിരിക്കും."}, {"ayahNumber": 55, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 56, "quranText": "فِیهِنَّ قَـٰصِرَ ٰ⁠تُ ٱلطَّرۡفِ لَمۡ یَطۡمِثۡهُنَّ إِنسࣱ قَبۡلَهُمۡ وَلَا جَاۤنࣱّ\n", "jalalayn": "«فِيهِنَّ» فِي الجَنَّتَيْنِ وما اشْتَمَلَتا عَلَيْهِ مِن العَلالِيّ والقُصُور «قاصِرات الطَّرْف» العَيْن عَلى أزْواجهنَّ المُتَّكِئِينَ مِن الإنْس والجِنّ «لَمْ يَطْمِثهُنَّ» يَفْتَضّهُنَّ وهُنَّ مِن الحُور أوْ مِن نِساء الدُّنْيا المُنْشَآت", "malayalam": "«അവിടെ ദൃഷ്ടികൾ താഴ്ത്തിയ ഇണകളുണ്ടാകും; അവർക്ക് മുമ്പ് മനുഷ്യനോ ജിന്നോ അവരെ സ്പർശിച്ചിട്ടുണ്ടാകില്ല».", "malayalamMatn": "അവയില്‍ ദൃഷ്ടി നിയന്ത്രിക്കുന്നവരായ സ്ത്രീകളുണ്ടായിരിക്കും. അവര്‍ക്ക് മുമ്പ് മനുഷ്യനോ, ജിന്നോ അവരെ സ്പര്‍ശിച്ചിട്ടില്ല."}, {"ayahNumber": 57, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 58, "quranText": "كَأَنَّهُنَّ ٱلۡیَاقُوتُ وَٱلۡمَرۡجَانُ\n", "jalalayn": "«كَأَنَّهُنَّ الياقُوت» مِن صَفاء «والمَرْجان» اللُّؤْلُؤ بَياضًا", "malayalam": "«അവർ മാണിക്യവും പവിഴവും പോലെയായിരിക്കും» (സൗന്ദര്യത്തിലും തെളിമയിലും).", "malayalamMatn": "അവര്‍ മാണിക്യവും പവിഴവും പോലെയായിരിക്കും."}, {"ayahNumber": 59, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 60, "quranText": "هَلۡ جَزَاۤءُ ٱلۡإِحۡسَـٰنِ إِلَّا ٱلۡإِحۡسَـٰنُ\n", "jalalayn": "«هَلْ» ما «جَزاء الإحْسان» بِالطّاعَةِ «إلّا الإحْسان» بِالنَّعِيمِ", "malayalam": "«നന്മയ്ക്ക് നന്മയല്ലാതെ വല്ല പ്രതിഫലവുമുണ്ടോ?» (സൽകർമ്മങ്ങൾ ചെയ്തവർക്ക് സ്വർഗ്ഗമല്ലാതെ മറ്റെന്താണ് പ്രതിഫലം!).", "malayalamMatn": "നല്ല പ്രവൃത്തിക്കുള്ള പ്രതിഫലം നല്ലത് ചെയ്ത് കൊടുക്കലല്ലാതെ മറ്റു വല്ലതുമാണോ?"}, {"ayahNumber": 61, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 62, "quranText": "وَمِن دُونِهِمَا جَنَّتَانِ\n", "jalalayn": "«ومِن دُونهما» مِن دُون الجَنَّتَيْنِ المَذْكُورَتَيْنِ «جَنَّتانِ» أيْضًا لِمَن خافَ مَقام رَبّه", "malayalam": "«ആ രണ്ട് സ്വർഗ്ഗങ്ങൾക്ക് പുറമെ വേറെ രണ്ട് സ്വർഗ്ഗത്തോപ്പുകൾ കൂടിയുണ്ട്».", "malayalamMatn": "അവ രണ്ടിനും പുറമെ വേറെയും രണ്ടു സ്വര്‍ഗത്തോപ്പുകളുണ്ട്‌."}, {"ayahNumber": 63, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 64, "quranText": "مُدۡهَاۤمَّتَانِ\n", "jalalayn": "«مُدْهامَّتانِ» سَوْداوانِ مِن شِدَّة خُضْرَتهما", "malayalam": "«കടുംപച്ച നിറത്തിലുള്ളവയാകുന്നു അവ രണ്ടും» (സമൃദ്ധമായ ജലസേചനം കൊണ്ട്).", "malayalamMatn": "കടും പച്ചയണിഞ്ഞ രണ്ടുസ്വര്‍ഗത്തോപ്പുകള്‍"}, {"ayahNumber": 65, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 66, "quranText": "فِیهِمَا عَیۡنَانِ نَضَّاخَتَانِ\n", "jalalayn": "«فِيهِما عَيْنانِ نَضّاخَتانِ» فَوّارَتانِ بِالماءِ", "malayalam": "«അവ രണ്ടിലും ശക്തിയായി തെറിച്ചൊഴുകുന്ന രണ്ട് ഉറവകളുണ്ട്».", "malayalamMatn": "അവ രണ്ടിലും കുതിച്ചൊഴുകുന്ന രണ്ടു അരുവികളുണ്ട്‌."}, {"ayahNumber": 67, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 68, "quranText": "فِیهِمَا فَـٰكِهَةࣱ وَنَخۡلࣱ وَرُمَّانࣱ\n", "jalalayn": "«فِيهِما فاكِهَة ونَخْل ورُمّان» هُما مِنها وقِيلَ مِن غَيْرها", "malayalam": "«അവ രണ്ടിലും പഴവർഗ്ഗങ്ങളും ഈത്തപ്പഴങ്ങളും മാതളനാരങ്ങകളുമുണ്ട്».", "malayalamMatn": "അവ രണ്ടിലും പഴവര്‍ഗങ്ങളുണ്ട്‌. ഈന്തപ്പനകളും റുമാമ്പഴവുമുണ്ട്‌."}, {"ayahNumber": 69, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 70, "quranText": "فِیهِنَّ خَیۡرَ ٰ⁠تٌ حِسَانࣱ\n", "jalalayn": "«فِيهِنَّ» أيْ الجَنَّتَيْنِ وما فِيهِما «خَيْرات» أخَلاقها خَيِّرَة «حِسان» حَسَنَة الوُجُوه", "malayalam": "«അവയിൽ സൽസ്വഭാവികളും സുന്ദരികളുമായ ഇണകളുണ്ടായിരിക്കും».", "malayalamMatn": "അവയില്‍ സുന്ദരികളായ ഉത്തമ തരുണികളുണ്ട്‌."}, {"ayahNumber": 71, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 72, "quranText": "حُورࣱ مَّقۡصُورَ ٰ⁠تࣱ فِی ٱلۡخِیَامِ\n", "jalalayn": "«حُور» شَدِيدات سَواد العُيُون وبَياضها\" «» \"مَقْصُورات\" «مَسْتُورات» \"فِي الخِيام\" «خِيام مِن دُرّ مُجَوَّف مُضافَة إلى القُصُور شَبِيهَة بِالخُدُورِ»", "malayalam": "«കൂടാരങ്ങളിൽ സംരക്ഷിക്കപ്പെട്ട വിശാലനേത്രകളായ ഹൂറികൾ».", "malayalamMatn": "കൂടാരങ്ങളില്‍ ഒതുക്കി നിര്‍ത്തപ്പെട്ട വെളുത്ത തരുണികള്‍!"}, {"ayahNumber": 73, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 74, "quranText": "لَمۡ یَطۡمِثۡهُنَّ إِنسࣱ قَبۡلَهُمۡ وَلَا جَاۤنࣱّ\n", "jalalayn": "«لَمْ يَطْمِثهُنَّ إنْس قَبْلهمْ» قَبْل أزْواجهنَّ", "malayalam": "«അവർക്ക് മുമ്പ് മനുഷ്യനോ ജിന്നോ അവരെ സ്പർശിച്ചിട്ടുണ്ടാകില്ല».", "malayalamMatn": "അവര്‍ക്ക് മുമ്പ് മനുഷ്യനോ ജിന്നോ അവരെ സ്പര്‍ശിച്ചിട്ടില്ല."}, {"ayahNumber": 75, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 76, "quranText": "مُتَّكِـِٔینَ عَلَىٰ رَفۡرَفٍ خُضۡرࣲ وَعَبۡقَرِیٍّ حِسَانࣲ\n", "jalalayn": "«مُتَّكِئِينَ» أيْ أزْواجهمْ وإعْرابه كَما تَقَدَّمَ «عَلى رَفْرَف خُضْر» جَمْع رَفْرَفَة أيْ بُسُط أوْ وسائِد «وعَبْقَرِيّ حِسان» جَمْع عَبْقَرِيَّة أيْ طَنافِس", "malayalam": "«പച്ച നിറത്തിലുള്ള തലയിണകളിലും മനോഹരമായ പരവതാനികളിലും ചാരിയിരിക്കുന്നവരായിരിക്കും അവർ».", "malayalamMatn": "പച്ചനിറമുള്ള തലയണകളിലും അഴകുള്ള പരവതാനികളിലും ചാരി കിടക്കുന്നവര്‍ ആയിരിക്കും അവര്‍."}, {"ayahNumber": 77, "quranText": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ\n", "jalalayn": "«فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ».", "malayalam": "«അതിനാൽ നിങ്ങൾ ഇരുവിഭാഗത്തിന്റെയും രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ ഇരു വിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്‌?"}, {"ayahNumber": 78, "quranText": "تَبَـٰرَكَ ٱسۡمُ رَبِّكَ ذِی ٱلۡجَلَـٰلِ وَٱلۡإِكۡرَامِ\n", "jalalayn": "«تَبارَكَ اسْم رَبّك ذِي الجَلال والإكْرام» تَقَّدَمَ ولَفْظ اسْم زائِد", "malayalam": "«മഹത്വവും ആദരവുമുള്ളവനായ നിന്റെ രക്ഷിതാവിന്റെ നാമം എത്രയോ അനുഗ്രഹപൂർണ്ണമായിരിക്കുന്നു!»", "malayalamMatn": "മഹത്വവും ഔദാര്യവും ഉള്ളവനായ നിന്‍റെ രക്ഷിതാവിന്‍റെ നാമം ഉല്‍കൃഷ്ടമായിരിക്കുന്നു."}], "topPoints": ["അല്ലാഹുവിന്റെ അനുഗ്രഹങ്ങളുടെ എണ്ണമറ്റ പട്ടിക (خلاصة السورة)", "മനുഷ്യരെയും ജിന്നുകളെയും ഒരുപോലെ സംബോധന ചെയ്യുന്നു"], "topQuestions": [{"q": "ഏത് വാക്യമാണ് ഈ സൂറത്തിൽ ആവർത്തിച്ചു വരുന്നത്?", "a": "'അതിനാൽ നിങ്ങള്‍ ഇരുവിഭാഗത്തിന്‍റെയും രക്ഷിതാവിന്‍റെ അനുഗ്രഹങ്ങളില്‍ ഏതിനെയാണ് നിങ്ങള്‍ നിഷേധിക്കുന്നത്?' എന്നത്."}], "asbabAlNuzul": []}, {"surahNumber": 56, "surahNameArabic": "سُورَةُ الوَاقِعَةِ", "surahNameMalayalam": "സൂറത്തുൽ വാഖിഅ (സംഭവിക്കുന്ന കാര്യം)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ إِذَا وَقَعَتِ ٱلۡوَاقِعَةُ\n", "jalalayn": "«إذا وقَعَتْ الواقِعَة» قامَتْ القِيامَة", "malayalam": "«ആ അനിവാര്യമായ സംഭവം» (ഖിയാമത്ത് നാൾ) «സംഭവിച്ചു കഴിഞ്ഞാൽ».", "malayalamMatn": "ആ സംഭവം സംഭവിച്ച് കഴിഞ്ഞാല്‍."}, {"ayahNumber": 2, "quranText": "لَیۡسَ لِوَقۡعَتِهَا كَاذِبَةٌ\n", "jalalayn": "«لَيْسَ لِوَقْعَتِها كاذِبَة» نَفْس تَكْذِب بِأَنْ تَنْفِيها كَما نَفَتْها فِي الدُّنْيا", "malayalam": "«അതിന്റെ സംഭവ്യതയെ നിഷേധിക്കുന്ന ആരും ഉണ്ടായിരിക്കുകയില്ല» (അന്ന് ആർക്കും അത് തള്ളിക്കളയാനാവില്ല).", "malayalamMatn": "അതിന്‍റെ സംഭവ്യതയെ നിഷേധിക്കുന്ന ആരും ഉണ്ടായിരിക്കുകയില്ല."}, {"ayahNumber": 3, "quranText": "خَافِضَةࣱ رَّافِعَةٌ\n", "jalalayn": "«خافِضَة رافِعَة» أيْ هِيَ مُظْهِرَة لِخَفْضِ أقْوام بِدُخُولِهِمْ النّار ولِرَفْعِ آخَرِينَ بِدُخُولِهِمْ الجَنَّة", "malayalam": "«അത് ചിലരെ താഴ്ത്തുന്നതും» (നരകത്തിലേക്ക് തള്ളിക്കൊണ്ട്) «ചിലരെ ഉയർത്തുന്നതുമായിരിക്കും» (സ്വർഗ്ഗത്തിലേക്ക് പ്രവേശിപ്പിച്ചുകൊണ്ട്).", "malayalamMatn": "(ആ സംഭവം, ചിലരെ) താഴ്ത്തുന്നതും (ചിലരെ) ഉയര്‍ത്തുന്നതുമായിരിക്കും."}, {"ayahNumber": 4, "quranText": "إِذَا رُجَّتِ ٱلۡأَرۡضُ رَجࣰّا\n", "jalalayn": "«إذا رُجَّتْ الأَرْض رَجًّا» حُرِّكَتْ حَرَكَة شَدِيدَة وإذا هَذِهِ بَدَل مِن الأُولى", "malayalam": "«ഭൂമി അതിശക്തമായി പ്രകമ്പനം കൊള്ളുമ്പോൾ».", "malayalamMatn": "ഭൂമി കിടുകിടാ വിറപ്പിക്കപ്പെടുകയും,"}, {"ayahNumber": 5, "quranText": "وَبُسَّتِ ٱلۡجِبَالُ بَسࣰّا\n", "jalalayn": "«وبُسَّتْ الجِبال بَسًّا» فُتِّتَتْ", "malayalam": "«പർവ്വതങ്ങൾ പൂർണ്ണമായും പൊടിപൊടിയാക്കപ്പെടുമ്പോൾ».", "malayalamMatn": "പര്‍വ്വതങ്ങള്‍ ഇടിച്ച് പൊടിയാക്കപ്പെടുകയും;"}, {"ayahNumber": 6, "quranText": "فَكَانَتۡ هَبَاۤءࣰ مُّنۢبَثࣰّا\n", "jalalayn": "«فَكانَتْ هَباء» غُبارًا «مُنْبَثًّا» مُنْتَشِرًا", "malayalam": "«അങ്ങനെ അത് പാറിപ്പറക്കുന്ന ധൂളികളായിത്തീരുമ്പോൾ».", "malayalamMatn": "അങ്ങനെ അത് പാറിപ്പറക്കുന്ന ധൂളിയായിത്തീരുകയും,"}, {"ayahNumber": 7, "quranText": "وَكُنتُمۡ أَزۡوَ ٰ⁠جࣰا ثَلَـٰثَةࣰ\n", "jalalayn": "«وكُنْتُمْ» فِي القِيامَة «أزْواجًا» أصْنافًا", "malayalam": "«നിങ്ങൾ മൂന്ന് വിഭാഗങ്ങളായിത്തീരുകയും ചെയ്യുമ്പോൾ».", "malayalamMatn": "നിങ്ങള്‍ മൂന്ന് തരക്കാരായിത്തീരുകയും ചെയ്യുന്ന സന്ദര്‍ഭമത്രെ അത്‌."}, {"ayahNumber": 8, "quranText": "فَأَصۡحَـٰبُ ٱلۡمَیۡمَنَةِ مَاۤ أَصۡحَـٰبُ ٱلۡمَیۡمَنَةِ\n", "jalalayn": "«فَأَصْحاب المَيْمَنَة» وهُمْ الَّذِينَ يُؤْتُونَ كُتُبهمْ بِأَيْمانِهِمْ مُبْتَدَأ خَبَره «ما أصْحاب المَيْمَنَة» تَعْظِيم لِشَأْنِهِمْ بِدُخُولِهِمْ الجَنَّة", "malayalam": "«അപ്പോൾ വലതുപക്ഷക്കാർ; എന്താണ് വലതുപക്ഷക്കാരുടെ പദവി!» (അവരുടെ പദവി എത്രയോ ഉന്നതമാണ്!).", "malayalamMatn": "അപ്പോള്‍ ഒരു വിഭാഗം വലതുപക്ഷക്കാര്‍. എന്താണ് ഈ വലതുപക്ഷക്കാരുടെ അവസ്ഥ!"}, {"ayahNumber": 9, "quranText": "وَأَصۡحَـٰبُ ٱلۡمَشۡـَٔمَةِ مَاۤ أَصۡحَـٰبُ ٱلۡمَشۡـَٔمَةِ\n", "jalalayn": "«وأَصْحاب المَشْأَمَة» أيْ الشِّمال بِأَنْ يُؤْتى كُلّ مِنهُمْ كِتابه بِشِمالِهِ «ما أصْحاب المَشْأَمَة» تَحْقِير لِشَأْنِهِمْ بِدُخُولِهِمْ النّار", "malayalam": "«ഇടതുപക്ഷക്കാർ; എന്താണ് ഇടതുപക്ഷക്കാരുടെ അവസ്ഥ!» (അവരുടെ അവസ്ഥ എത്രയോ ദയനീയമാണ്!).", "malayalamMatn": "മറ്റൊരു വിഭാഗം ഇടതുപക്ഷക്കാര്‍. എന്താണ് ഈ ഇടതുപക്ഷക്കാരുടെ അവസ്ഥ!"}, {"ayahNumber": 10, "quranText": "وَٱلسَّـٰبِقُونَ ٱلسَّـٰبِقُونَ\n", "jalalayn": "«والسّابِقُونَ» إلى الخَيْر وهُمْ الأَنْبِياء مُبْتَدَأ «السّابِقُونَ» تَأْكِيد لِتَعْظِيمِ شَأْنهمْ", "malayalam": "«മുൻകടന്നവർ» (നന്മയിൽ മുന്നേറിയവർ), «അവർ തന്നെയാണ് മുൻകടന്നവർ» (സ്വർഗ്ഗപ്രവേശനത്തിലും ഉന്നത സ്ഥാനങ്ങളിലും).", "malayalamMatn": "(സത്യവിശ്വാസത്തിലും സല്‍പ്രവൃത്തികളിലും) മുന്നേറിയവര്‍ (പരലോകത്തും) മുന്നോക്കക്കാര്‍ തന്നെ."}, {"ayahNumber": 11, "quranText": "أُو۟لَـٰۤىِٕكَ ٱلۡمُقَرَّبُونَ\n", "jalalayn": "«أُو۟لَـٰۤىِٕكَ ٱلۡمُقَرَّبُونَ».", "malayalam": "«അവരാകുന്നു അല്ലാഹുവിലേക്ക് സാമീപ്യം സിദ്ധിച്ചവർ».", "malayalamMatn": "അവരാകുന്നു സാമീപ്യം നല്‍കപ്പെട്ടവര്‍."}, {"ayahNumber": 12, "quranText": "فِی جَنَّـٰتِ ٱلنَّعِیمِ\n", "jalalayn": "«فِی جَنَّـٰتِ ٱلنَّعِیمِ».", "malayalam": "«അനുഗ്രഹങ്ങളുടെ സ്വർഗ്ഗത്തോപ്പുകളിൽ».", "malayalamMatn": "സുഖാനുഭൂതികളുടെ സ്വര്‍ഗത്തോപ്പുകളില്‍."}, {"ayahNumber": 13, "quranText": "ثُلَّةࣱ مِّنَ ٱلۡأَوَّلِینَ\n", "jalalayn": "«ثُلَّة مِن الأَوَّلِينَ» مُبْتَدَأ أيْ جَماعَة مِن الأُمَم الماضِيَة", "malayalam": "«മുൻഗാമികളിൽ നിന്ന് ഒരു വലിയ സംഘവും».", "malayalamMatn": "പൂര്‍വ്വികന്‍മാരില്‍ നിന്ന് ഒരു വിഭാഗവും"}, {"ayahNumber": 14, "quranText": "وَقَلِیلࣱ مِّنَ ٱلۡـَٔاخِرِینَ\n", "jalalayn": "«وقَلِيل مِن الآخِرِينَ» مِن أُمَّة مُحَمَّد ﷺ وهُمْ السّابِقُونَ مِن الأُمَم الماضِيَة وهَذِهِ الأُمَّة والخَبَر", "malayalam": "«പിൻഗാമികളിൽ നിന്ന് കുറഞ്ഞ ഒരു വിഭാഗവും».", "malayalamMatn": "പില്‍ക്കാലക്കാരില്‍ നിന്ന് കുറച്ചു പേരുമത്രെ ഇവര്‍."}, {"ayahNumber": 15, "quranText": "عَلَىٰ سُرُرࣲ مَّوۡضُونَةࣲ\n", "jalalayn": "«عَلى سُرَر مَوْضُونَة» مَنسُوجَة بِقُضْبانِ الذَّهَب والجَواهِر", "malayalam": "«സ്വർണ്ണനൂലുകൾ കൊണ്ട് തുന്നിപ്പിടിപ്പിച്ച കട്ടിലുകളിൽ».", "malayalamMatn": "സ്വര്‍ണനൂലുകൊണ്ട് മെടഞ്ഞുണ്ടാക്കപ്പെട്ട കട്ടിലുകളില്‍ ആയിരിക്കും. അവര്‍."}, {"ayahNumber": 16, "quranText": "مُّتَّكِـِٔینَ عَلَیۡهَا مُتَقَـٰبِلِینَ\n", "jalalayn": "«مُتَّكِئِينَ عَلَيْها مُتَقابِلِينَ» حالانِ مِن الضَّمِير فِي الخَبَر", "malayalam": "«പരസ്പരം അഭിമുഖമായി ചാരിയിരിക്കുന്നവരായിക്കൊണ്ട്».", "malayalamMatn": "അവയില്‍ അവര്‍ പരസ്പരം അഭിമുഖമായി ചാരിയിരിക്കുന്നവരായിരിക്കും."}, {"ayahNumber": 17, "quranText": "یَطُوفُ عَلَیۡهِمۡ وِلۡدَ ٰ⁠نࣱ مُّخَلَّدُونَ\n", "jalalayn": "«يَطُوف عَلَيْهِمْ» لِلْخِدْمَةِ «وِلْدان مُخَلَّدُونَ» عَلى شَكْل الأَوْلاد لا يَهْرَمُونَ", "malayalam": "«ശാശ്വത യൗവനം നൽകപ്പെട്ട ബാലന്മാർ അവരുടെ ഇടയിൽ ചുറ്റിനടക്കും».", "malayalamMatn": "നിത്യജീവിതം നല്‍കപ്പെട്ട ബാലന്‍മാര്‍ അവരുടെ ഇടയില്‍ ചുറ്റി നടക്കും."}, {"ayahNumber": 18, "quranText": "بِأَكۡوَابࣲ وَأَبَارِیقَ وَكَأۡسࣲ مِّن مَّعِینࣲ\n", "jalalayn": "«بِأَكْوابٍ» أقْداح لا عُرا لَها «وأَبارِيق» لَها عُرا وخَراطِيم «وكَأْس» إناء شُرْب الخَمْر «مِن مَعِين» أيْ خَمْر جارِيَة مِن مَنبَع لا يَنْقَطِع أبَدًا", "malayalam": "«ഒഴുകുന്ന ഉറവയിൽ നിന്നുള്ള മദ്യം നിറഞ്ഞ കോപ്പകളും കൂജകളും പാനപാത്രങ്ങളുമായി».", "malayalamMatn": "കോപ്പകളും കൂജകളും ശുദ്ധമായ ഉറവു ജലം നിറച്ച പാനപാത്രവും കൊണ്ട്‌."}, {"ayahNumber": 19, "quranText": "لَّا یُصَدَّعُونَ عَنۡهَا وَلَا یُنزِفُونَ\n", "jalalayn": "«لا يُصَدَّعُونَ عَنْها ولا يُنْزَفُونَ» بِفَتْحِ الزّاي وكَسْرها مِن نَزَفَ الشّارِب وأَنْزَفَ أيْ لا يَحْصُل لَهُمْ مِنها صُداع ولا ذَهاب عَقْل بِخِلافِ خَمْر الدُّنْيا", "malayalam": "«അത് കുടിക്കുന്നത് കാരണം അവർക്ക് തലവേദനയുണ്ടാകില്ല, അവർക്ക് ലഹരിബാധിക്കുകയുമില്ല».", "malayalamMatn": "അതു (കുടിക്കുക) മൂലം അവര്‍ക്ക് തലവേദനയുണ്ടാവുകയോ, ലഹരി ബാധിക്കുകയോ ഇല്ല."}, {"ayahNumber": 20, "quranText": "وَفَـٰكِهَةࣲ مِّمَّا یَتَخَیَّرُونَ\n", "jalalayn": "«وَفَـٰكِهَةࣲ مِّمَّا یَتَخَیَّرُونَ».", "malayalam": "«അവർ ഇഷ്ടപ്പെട്ടു തിരഞ്ഞെടുക്കുന്ന പഴവർഗ്ഗങ്ങളുമായി».", "malayalamMatn": "അവര്‍ ഇഷ്ടപ്പെട്ടു തെരഞ്ഞെടുക്കുന്ന തരത്തില്‍ പെട്ട പഴവര്‍ഗങ്ങളും."}, {"ayahNumber": 21, "quranText": "وَلَحۡمِ طَیۡرࣲ مِّمَّا یَشۡتَهُونَ\n", "jalalayn": "«ولَحْم طَيْر مِمّا يَشْتَهُونَ» لَهُمْ لِلِاسْتِمْتاعِ", "malayalam": "«അവർ കൊതിക്കുന്ന പക്ഷികളുടെ മാംസവുമായി».", "malayalamMatn": "അവര്‍ കൊതിക്കുന്ന തരത്തില്‍ പെട്ട പക്ഷിമാംസവും കൊണ്ട് (അവര്‍ ചുറ്റി നടക്കും.)"}, {"ayahNumber": 22, "quranText": "وَحُورٌ عِینࣱ\n", "jalalayn": "«وحُور» نِساء شَدِيدات سَواد العُيُون وبَياضها «عِين» ضِخام العُيُون كُسِرَتْ عَيْنه بَدَل ضَمّها لِمُجانَسَةِ الياء ومُفْرَده عَيْناء كَحَمْراء وفِي قِراءَة بِجَرِّ حُور عِين", "malayalam": "«വിശാലമായ കൃഷ്ണമണികളുള്ള സുന്ദരികളായ ഹൂറികളും ഉണ്ടായിരിക്കും».", "malayalamMatn": "വിശാലമായ നയനങ്ങളുള്ള വെളുത്ത തരുണികളും. (അവര്‍ക്കുണ്ട്‌.)"}, {"ayahNumber": 23, "quranText": "كَأَمۡثَـٰلِ ٱللُّؤۡلُوِٕ ٱلۡمَكۡنُونِ\n", "jalalayn": "«كَأَمْثالِ اللُّؤْلُؤ المَكْنُون» المَصُون", "malayalam": "«ചിപ്പികളിൽ സൂക്ഷിക്കപ്പെട്ട മുത്തുകൾ പോലെ».", "malayalamMatn": "(ചിപ്പികളില്‍) ഒളിച്ചു വെക്കപ്പെട്ട മുത്തുപോലെയുള്ളവര്‍,"}, {"ayahNumber": 24, "quranText": "جَزَاۤءَۢ بِمَا كَانُوا۟ یَعۡمَلُونَ\n", "jalalayn": "«جَزاء» مَفْعُول لَهُ أوْ مَصْدَر والعامِل المُقَدَّر أيْ جَعَلْنا لَهُمْ ما ذُكِرَ لِلْجَزاءِ أوْ جَزَيْناهُمْ", "malayalam": "«അവർ പ്രവർത്തിച്ചുകൊണ്ടിരുന്ന സൽകർമ്മങ്ങൾക്കുള്ള പ്രതിഫലമായിക്കൊണ്ട്».", "malayalamMatn": "അവര്‍ പ്രവര്‍ത്തിച്ച് കൊണ്ടിരുന്നതിനുള്ള പ്രതിഫലമായികൊണ്ടാണ് (അതെല്ലാം നല്‍കപ്പെടുന്നത്‌)"}, {"ayahNumber": 25, "quranText": "لَا یَسۡمَعُونَ فِیهَا لَغۡوࣰا وَلَا تَأۡثِیمًا\n", "jalalayn": "«لا يَسْمَعُونَ فِيها» فِي الجَنَّة «لَغْوًا» فاحِشًا مِن الكَلام «ولا تَأْثِيمًا» ما يُؤْثِم", "malayalam": "«അനാവശ്യമായ വാക്കുകളോ പാപകരമായ സംസാരങ്ങളോ അവിടെ അവർ കേൾക്കുകയില്ല».", "malayalamMatn": "അനാവശ്യവാക്കോ കുറ്റപ്പെടുത്തലോ അവര്‍ അവിടെ വെച്ച് കേള്‍ക്കുകയില്ല."}, {"ayahNumber": 26, "quranText": "إِلَّا قِیلࣰا سَلَـٰمࣰا سَلَـٰمࣰا\n", "jalalayn": "«إلّا» لَكِنْ «قِيلًا» قَوْلًا «سَلامًا سَلامًا» بَدَل مِن قِيلًا فَإنَّهُمْ يَسْمَعُونَهُ", "malayalam": "«സലാം, സലാം (ശാന്തി, സമാധാനം) എന്ന ആശംസയല്ലാതെ».", "malayalamMatn": "സമാധാനം! സമാധാനം! എന്നുള്ള വാക്കല്ലാതെ."}, {"ayahNumber": 27, "quranText": "وَأَصۡحَـٰبُ ٱلۡیَمِینِ مَاۤ أَصۡحَـٰبُ ٱلۡیَمِینِ\n", "jalalayn": "«وَأَصۡحَـٰبُ ٱلۡیَمِینِ مَاۤ أَصۡحَـٰبُ ٱلۡیَمِینِ».", "malayalam": "«വലതുപക്ഷക്കാർ; എന്താണ് വലതുപക്ഷക്കാരുടെ സൗഭാഗ്യം!».", "malayalamMatn": "വലതുപക്ഷക്കാര്‍! എന്താണീ വലതുപക്ഷക്കാരുടെ അവസ്ഥ!"}, {"ayahNumber": 28, "quranText": "فِی سِدۡرࣲ مَّخۡضُودࣲ\n", "jalalayn": "«فِي سِدْر» شَجَر النَّبْق «مَخْضُود» لا شَوْك فِيهِ", "malayalam": "«മുള്ളില്ലാത്ത ഇലന്തമരങ്ങൾക്കിടയിലും».", "malayalamMatn": "മുള്ളിലാത്ത ഇലന്തമരം,"}, {"ayahNumber": 29, "quranText": "وَطَلۡحࣲ مَّنضُودࣲ\n", "jalalayn": "«وطَلْح» شَجَر المَوْز «مَنضُود» بِالحَمْلِ مِن أسْفَله إلى أعْلاهُ", "malayalam": "«അടുക്കടുക്കായി കുലകളുള്ള വാഴകൾക്കിടയിലും».", "malayalamMatn": "അടുക്കടുക്കായി കുലകളുള്ള വാഴ,"}, {"ayahNumber": 30, "quranText": "وَظِلࣲّ مَّمۡدُودࣲ\n", "jalalayn": "«وظِلّ مَمْدُود» دائِم", "malayalam": "«വിശാലമായ തണലിലും».", "malayalamMatn": "വിശാലമായ തണല്‍,"}, {"ayahNumber": 31, "quranText": "وَمَاۤءࣲ مَّسۡكُوبࣲ\n", "jalalayn": "«وماء مَسْكُوب» جارٍ دائِمًا", "malayalam": "«സദാ പ്രവഹിക്കുന്ന ജലാശയങ്ങൾക്കരികിലും».", "malayalamMatn": "സദാ ഒഴുക്കപ്പെട്ടു കൊണ്ടിരിക്കുന്ന വെള്ളം,"}, {"ayahNumber": 32, "quranText": "وَفَـٰكِهَةࣲ كَثِیرَةࣲ\n", "jalalayn": "«وَفَـٰكِهَةࣲ كَثِیرَةࣲ».", "malayalam": "«ധാരാളം പഴവർഗ്ഗങ്ങൾക്കിടയിലും».", "malayalamMatn": "ധാരാളം പഴവര്‍ഗങ്ങള്‍,"}, {"ayahNumber": 33, "quranText": "لَّا مَقۡطُوعَةࣲ وَلَا مَمۡنُوعَةࣲ\n", "jalalayn": "«لا مَقْطُوعَة» فِي زَمَن «ولا مَمْنُوعَة» بِثَمَنٍ", "malayalam": "«കാലഭേദമില്ലാതെ തീർന്നുപോകാത്തതും, ആർക്കും തടയപ്പെടാത്തതുമായ പഴങ്ങൾ».", "malayalamMatn": "നിലച്ചു പോവാത്തതും തടസ്സപ്പെട്ടുപോവാത്തതുമായ"}, {"ayahNumber": 34, "quranText": "وَفُرُشࣲ مَّرۡفُوعَةٍ\n", "jalalayn": "«وفُرُش مَرْفُوعَة» عَلى السُّرَر", "malayalam": "«ഉയർത്തപ്പെട്ട വിരിപ്പുകളിലും».", "malayalamMatn": "ഉയര്‍ന്നമെത്തകള്‍ എന്നീ സുഖാനുഭവങ്ങളിലായിരിക്കും അവര്‍."}, {"ayahNumber": 35, "quranText": "إِنَّاۤ أَنشَأۡنَـٰهُنَّ إِنشَاۤءࣰ\n", "jalalayn": "«إنّا أنْشَأْناهُنَّ إنْشاء» أيْ الحُور العِين مِن غَيْر وِلادَة", "malayalam": "«തീർച്ചയായും അവരെ» (സ്വർഗ്ഗസ്ത്രീകളെ) «നാം ഒരു പ്രത്യേക രീതിയിൽ സൃഷ്ടിച്ചുണ്ടാക്കിയിരിക്കുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും അവരെ (സ്വര്‍ഗസ്ത്രീകളെ) നാം ഒരു പ്രത്യേക പ്രകൃതിയോടെ സൃഷ്ടിച്ചുണ്ടാക്കിയിരിക്കുകയാണ്‌."}, {"ayahNumber": 36, "quranText": "فَجَعَلۡنَـٰهُنَّ أَبۡكَارًا\n", "jalalayn": "«فَجَعَلْناهُنَّ أبْكارًا» عَذارى كُلَّما أتاهُنَّ أزْواجهنَّ وجَدُوهُنَّ عَذارى ولا وجَع", "malayalam": "«അങ്ങനെ നാം അവരെ കന്യകമാരാക്കിയിരിക്കുന്നു».", "malayalamMatn": "അങ്ങനെ അവരെ നാം കന്യകമാരാക്കിയിരിക്കുന്നു."}, {"ayahNumber": 37, "quranText": "عُرُبًا أَتۡرَابࣰا\n", "jalalayn": "«عُرُبًا» بِضَمِّ الرّاء وسُكُونها جَمْع عُرُوب وهِيَ المُتَحَبِّبَة إلى زَوْجها عِشْقًا لَهُ «أتْرابًا» جَمْع تِرْب أيْ مُسْتَوِيات فِي السِّنّ", "malayalam": "«ഭർത്താക്കന്മാരെ സ്നേഹിക്കുന്നവരും ഒരേ പ്രായത്തിലുള്ളവരുമാക്കിയിരിക്കുന്നു».", "malayalamMatn": "സ്നേഹവതികളും സമപ്രായക്കാരും ആക്കിയിരിക്കുന്നു."}, {"ayahNumber": 38, "quranText": "لِّأَصۡحَـٰبِ ٱلۡیَمِینِ\n", "jalalayn": "«لِأَصْحابِ اليَمِين» صِلَة أنْشَأْناهُنَّ أوْ جَعَلْناهُنَّ وهُمْ: «ثُلَّة مِن الأَوَّلِينَ وثُلَّة مِن الآخِرِينَ»", "malayalam": "«വലതുപക്ഷക്കാർക്ക് വേണ്ടിയത്രെ അത്».", "malayalamMatn": "വലതുപക്ഷക്കാര്‍ക്ക് വേണ്ടിയത്രെ അത്‌."}, {"ayahNumber": 39, "quranText": "ثُلَّةࣱ مِّنَ ٱلۡأَوَّلِینَ\n", "jalalayn": "«ثُلَّةࣱ مِّنَ ٱلۡأَوَّلِینَ».", "malayalam": "«മുൻഗാമികളിൽ നിന്ന് ഒരു സംഘവും».", "malayalamMatn": "പൂര്‍വ്വികന്‍മാരില്‍ നിന്ന് ഒരു വിഭാഗവും"}, {"ayahNumber": 40, "quranText": "وَثُلَّةࣱ مِّنَ ٱلۡـَٔاخِرِینَ\n", "jalalayn": "«وَثُلَّةࣱ مِّنَ ٱلۡـَٔاخِرِینَ».", "malayalam": "«പിൻഗാമികളിൽ നിന്ന് ഒരു സംഘവും» (വലതുപക്ഷക്കാരായിരിക്കും).", "malayalamMatn": "പിന്‍ഗാമികളില്‍ നിന്ന് ഒരു വിഭാഗവും ആയിരിക്കും അവര്‍."}, {"ayahNumber": 41, "quranText": "وَأَصۡحَـٰبُ ٱلشِّمَالِ مَاۤ أَصۡحَـٰبُ ٱلشِّمَالِ\n", "jalalayn": "«وَأَصۡحَـٰبُ ٱلشِّمَالِ مَاۤ أَصۡحَـٰبُ ٱلشِّمَالِ».", "malayalam": "«ഇടതുപക്ഷക്കാർ; എന്താണ് ഇടതുപക്ഷക്കാരുടെ ദുരവസ്ഥ!».", "malayalamMatn": "ഇടതുപക്ഷക്കാര്‍, എന്താണീ ഇടതുപക്ഷക്കാരുടെ അവസ്ഥ!"}, {"ayahNumber": 42, "quranText": "فِی سَمُومࣲ وَحَمِیمࣲ\n", "jalalayn": "«فِي سَمُوم» رِيح حارَّة مِن النّار تَنْفُذ فِي المَسامّ «وحَمِيم» ماء شَدِيد الحَرارَة", "malayalam": "«ചുട്ടുപൊള്ളുന്ന കാറ്റിലും തിളച്ചുമറിയുന്ന വെള്ളത്തിലും».", "malayalamMatn": "തുളച്ചു കയറുന്ന ഉഷ്ണകാറ്റ്‌, ചുട്ടുതിളക്കുന്ന വെള്ളം,"}, {"ayahNumber": 43, "quranText": "وَظِلࣲّ مِّن یَحۡمُومࣲ\n", "jalalayn": "«وظِلّ مِن يَحْمُوم» دُخان شَدِيد السَّواد", "malayalam": "«കറുത്ത പുകയുടെ തണലിലും».", "malayalamMatn": "കരിമ്പുകയുടെ തണല്‍"}, {"ayahNumber": 44, "quranText": "لَّا بَارِدࣲ وَلَا كَرِیمٍ\n", "jalalayn": "«لا بارِد» كَغَيْرِهِ مِن الظِّلال «ولا كَرِيم» حَسَن المَنظَر", "malayalam": "«യാതൊരു തണുപ്പോ സുഖമോ ഇല്ലാത്ത തണൽ».", "malayalamMatn": "തണുപ്പുള്ളതോ, സുഖദായകമോ അല്ലാത്ത (എന്നീ ദുരിതങ്ങളിലായിരിക്കും അവര്‍.)"}, {"ayahNumber": 45, "quranText": "إِنَّهُمۡ كَانُوا۟ قَبۡلَ ذَ ٰ⁠لِكَ مُتۡرَفِینَ\n", "jalalayn": "«إنّهُمْ كانُوا قَبْل ذَلِك» فِي الدُّنْيا «مُتْرَفِينَ» مُنَعَّمِينَ لا يَتْعَبُونَ فِي الطّاعَة", "malayalam": "«തീർച്ചയായും അവർ ഇതിന് മുമ്പ് സുഖലോലുപരായി ജീവിച്ചവരായിരുന്നു».", "malayalamMatn": "എന്തുകൊണ്ടെന്നാല്‍ തീര്‍ച്ചയായും അവര്‍ അതിനു മുമ്പ് സുഖലോലുപന്‍മാരായിരുന്നു."}, {"ayahNumber": 46, "quranText": "وَكَانُوا۟ یُصِرُّونَ عَلَى ٱلۡحِنثِ ٱلۡعَظِیمِ\n", "jalalayn": "«وكانُوا يُصِرُّونَ عَلى الحِنْث» الذَّنْب «العَظِيم» أيْ الشِّرْك", "malayalam": "«വലിയ പാപത്തിൽ» (ശിർക്കിലും നിഷേധത്തിലും) «അവർ ഉറച്ചുനിൽക്കുന്നവരുമായിരുന്നു».", "malayalamMatn": "അവര്‍ ഗുരുതരമായ പാപത്തില്‍ ശഠിച്ചുനില്‍ക്കുന്നവരുമായിരുന്നു."}, {"ayahNumber": 47, "quranText": "وَكَانُوا۟ یَقُولُونَ أَىِٕذَا مِتۡنَا وَكُنَّا تُرَابࣰا وَعِظَـٰمًا أَءِنَّا لَمَبۡعُوثُونَ\n", "jalalayn": "«وكانُوا يَقُولُونَ أإذا مِتْنا وكُنّا تُرابًا وعِظامًا أإنّا لَمَبْعُوثُونَ» فِي الهَمْزَتَيْنِ فِي المَوْضِعَيْنِ التَّحْقِيق وتَسْهِيل الثّانِيَة وإدْخال ألِف بَيْنهما عَلى الوَجْهَيْنِ", "malayalam": "«അവർ പറയുമായിരുന്നു: ഞങ്ങൾ മരിച്ച് മണ്ണും അസ്ഥികളുമായിക്കഴിഞ്ഞാൽ ഞങ്ങളോ, ഞങ്ങൾ ഉയിർത്തെഴുന്നേൽപിക്കപ്പെടുമെന്നോ?»", "malayalamMatn": "അവര്‍ ഇപ്രകാരം പറയുകയും ചെയ്തിരുന്നു: ഞങ്ങള്‍ മരിച്ചിട്ട് മണ്ണും അസ്ഥിശകലങ്ങളുമായിക്കഴിഞ്ഞിട്ടാണോ ഞങ്ങള്‍ ഉയിര്‍ത്തെഴുന്നേല്‍പിക്കപ്പെടാന്‍ പോകുന്നത്‌?"}, {"ayahNumber": 48, "quranText": "أَوَءَابَاۤؤُنَا ٱلۡأَوَّلُونَ\n", "jalalayn": "«أوَ آباؤُنا الأَوَّلُونَ» بِفَتْحِ الواو لِلْعَطْفِ والهَمْزَة لِلِاسْتِفْهامِ وهُوَ فِي ذَلِكَ وفِيما قَبْله لِلِاسْتِبْعادِ وفِي قِراءَة بِسُكُونِ الواو عَطْفًا بِأَوْ والمَعْطُوف عَلَيْهِ مَحَلّ إنّ واسْمها", "malayalam": "«ഞങ്ങളുടെ പൂർവ്വികരായ പിതാക്കന്മാരുമോ?»", "malayalamMatn": "ഞങ്ങളുടെ പൂര്‍വ്വികരായ പിതാക്കളും (ഉയിര്‍ത്തെഴുന്നേല്‍പിക്കപ്പെടുമെന്നോ?)"}, {"ayahNumber": 49, "quranText": "قُلۡ إِنَّ ٱلۡأَوَّلِینَ وَٱلۡـَٔاخِرِینَ\n", "jalalayn": "«قُلۡ إِنَّ ٱلۡأَوَّلِینَ وَٱلۡـَٔاخِرِینَ».", "malayalam": "«പറയുക: തീർച്ചയായും പൂർവ്വികരും പിൻഗാമികളുമെല്ലാം».", "malayalamMatn": "നീ പറയുക: തീര്‍ച്ചയായും പൂര്‍വ്വികരും പില്‍ക്കാലക്കാരും എല്ലാം-"}, {"ayahNumber": 50, "quranText": "لَمَجۡمُوعُونَ إِلَىٰ مِیقَـٰتِ یَوۡمࣲ مَّعۡلُومࣲ\n", "jalalayn": "«لَمَجْمُوعُونَ إلى مِيقات» لِوَقْتِ «يَوْم مَعْلُوم» أيْ يَوْم القِيامَة", "malayalam": "«നിശ്ചിതമായ ഒരു ദിവസത്തിലെ നിശ്ചിത സമയത്ത് ഒരുമിച്ചുകൂട്ടപ്പെടുക തന്നെ ചെയ്യും».", "malayalamMatn": "ഒരു നിശ്ചിത ദിവസത്തെ കൃത്യമായ ഒരു അവധിക്ക് ഒരുമിച്ചുകൂട്ടപ്പെടുന്നവര്‍ തന്നെയാകുന്നു."}, {"ayahNumber": 51, "quranText": "ثُمَّ إِنَّكُمۡ أَیُّهَا ٱلضَّاۤلُّونَ ٱلۡمُكَذِّبُونَ\n", "jalalayn": "«ثُمَّ إِنَّكُمۡ أَیُّهَا ٱلضَّاۤلُّونَ ٱلۡمُكَذِّبُونَ».", "malayalam": "«പിന്നെ തീർച്ചയായും സത്യം നിഷേധിച്ചു തള്ളിയ ദുർമാർഗ്ഗികളായ ഹേ മനുഷ്യരേ!».", "malayalamMatn": "എന്നിട്ട്‌, ഹേ; സത്യനിഷേധികളായ ദുര്‍മാര്‍ഗികളേ,"}, {"ayahNumber": 52, "quranText": "لَـَٔاكِلُونَ مِن شَجَرࣲ مِّن زَقُّومࣲ\n", "jalalayn": "«لَآكِلُونَ مِن شَجَر مِن زَقُّوم» بَيان لِلشَّجَرِ", "malayalam": "«നിങ്ങൾ സഖൂം വൃക്ഷത്തിൽ നിന്ന് ഭക്ഷിക്കുക തന്നെ ചെയ്യും».", "malayalamMatn": "തീര്‍ച്ചയായും നിങ്ങള്‍ ഒരു വൃക്ഷത്തില്‍ നിന്ന് അതായത് സഖ്ഖൂമില്‍ നിന്ന് ഭക്ഷിക്കുന്നവരാകുന്നു."}, {"ayahNumber": 53, "quranText": "فَمَالِـُٔونَ مِنۡهَا ٱلۡبُطُونَ\n", "jalalayn": "«فَمالِئُونَ مِنها» مِن الشَّجَر", "malayalam": "«അങ്ങനെ അതിൽ നിന്ന് നിങ്ങളുടെ വയറുകൾ നിറയ്ക്കും».", "malayalamMatn": "അങ്ങനെ അതില്‍ നിന്ന് വയറുകള്‍ നിറക്കുന്നവരും,"}, {"ayahNumber": 54, "quranText": "فَشَـٰرِبُونَ عَلَیۡهِ مِنَ ٱلۡحَمِیمِ\n", "jalalayn": "«فَشارِبُونَ عَلَيْهِ» أيْ الزَّقُّوم المَأْكُول", "malayalam": "«എന്നിട്ട് അതിന്റെ മീതെ തിളച്ചുമറിയുന്ന വെള്ളം കുടിക്കും».", "malayalamMatn": "അതിന്‍റെ മീതെ തിളച്ചുപൊള്ളുന്ന വെള്ളത്തില്‍ നിന്ന് കുടിക്കുന്നവരുമാകുന്നു."}, {"ayahNumber": 55, "quranText": "فَشَـٰرِبُونَ شُرۡبَ ٱلۡهِیمِ\n", "jalalayn": "«فَشارِبُونَ شَرْب» بِفَتْحِ الشِّين وضَمّها مَصْدَر «الهِيم» الإبِل العِطاش جَمْع هَيْمان لِلذَّكَرِ وهَيْمى لِلْأُنْثى كَعَطْشان وعَطْشى", "malayalam": "«ദാഹിച്ചുവലഞ്ഞ ഒട്ടകങ്ങൾ കുടിക്കുന്നതുപോലെ നിങ്ങൾ കുടിക്കും».", "malayalamMatn": "അങ്ങനെ ദാഹിച്ചു വലഞ്ഞ ഒട്ടകം കുടിക്കുന്നപോലെ കുടിക്കുന്നവരാകുന്നു."}, {"ayahNumber": 56, "quranText": "هَـٰذَا نُزُلُهُمۡ یَوۡمَ ٱلدِّینِ\n", "jalalayn": "«هَذا نُزُلهمْ» ما أُعِدَّ لَهُمْ «يَوْم الدِّين» يَوْم القِيامَة", "malayalam": "«പ്രതിഫലദിവസത്തിൽ ഇതത്രെ അവരുടെ സൽക്കാരം!».", "malayalamMatn": "ഇതായിരിക്കും പ്രതിഫലത്തിന്‍റെ നാളില്‍ അവര്‍ക്കുള്ള സല്‍ക്കാരം."}, {"ayahNumber": 57, "quranText": "نَحۡنُ خَلَقۡنَـٰكُمۡ فَلَوۡلَا تُصَدِّقُونَ\n", "jalalayn": "«نَحْنُ خَلَقْناكُمْ» أوَجَدْناكُمْ مِن عَدَم «فَلَوْلا» هَلّا «تُصَدِّقُونَ» بِالبَعْثِ إذْ القادِر عَلى الإنْشاء قادِر عَلى الإعادَة", "malayalam": "«നാമാണ് നിങ്ങളെ സൃഷ്ടിച്ചത്; എന്നിരിക്കെ നിങ്ങൾ അതംഗീകരിച്ച് സത്യപ്പെടുത്താത്തതെന്താണ്?»", "malayalamMatn": "നാമാണ് നിങ്ങളെ സൃഷ്ടിച്ചിരിക്കുന്നത്‌. എന്നിരിക്കെ നിങ്ങളെന്താണ് (എന്‍റെ സന്ദേശങ്ങളെ) സത്യമായി അംഗീകരിക്കാത്തത്‌?"}, {"ayahNumber": 58, "quranText": "أَفَرَءَیۡتُم مَّا تُمۡنُونَ\n", "jalalayn": "«أفَرَأَيْتُمْ ما تُمْنُونَ» تُرِيقُونَ مِن المَنِيّ فِي أرْحام النِّساء", "malayalam": "«നിങ്ങൾ സ്രവിക്കുന്ന ശുക്ലത്തെപ്പറ്റി നിങ്ങൾ ചിന്തിച്ചു നോക്കിയിട്ടുണ്ടോ?»", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ സ്രവിക്കുന്ന ശുക്ലത്തെപ്പറ്റി നിങ്ങള്‍ ചിന്തിച്ചു നോക്കിയിട്ടുണ്ടോ?"}, {"ayahNumber": 59, "quranText": "ءَأَنتُمۡ تَخۡلُقُونَهُۥۤ أَمۡ نَحۡنُ ٱلۡخَـٰلِقُونَ\n", "jalalayn": "«أأَنْتُمْ» بِتَحْقِيقِ الهَمْزَتَيْنِ وإبْدال الثّانِيَة ألِفًا وتَسْهِيلها وإدْخال ألِف بَيْن المُسَهَّلَة والأُخْرى وتَرْكه فِي المَواضِع الأُخْرى «تَخْلُقُونَهُ» أيْ المَنِيّ بَشَرًا", "malayalam": "«നിങ്ങളാണോ അത് സൃഷ്ടിക്കുന്നത്, അതോ നാമാണോ സ്രഷ്ടാവ്?»", "malayalamMatn": "നിങ്ങളാണോ അത് സൃഷ്ടിച്ചുണ്ടാക്കുന്നത്‌. അതല്ല, നാമാണോ സൃഷ്ടികര്‍ത്താവ്‌?"}, {"ayahNumber": 60, "quranText": "نَحۡنُ قَدَّرۡنَا بَیۡنَكُمُ ٱلۡمَوۡتَ وَمَا نَحۡنُ بِمَسۡبُوقِینَ\n", "jalalayn": "«نَحْنُ قَدَّرْنا» بِالتَّشْدِيدِ والتَّخْفِيف «بَيْنكُمْ المَوْت وما نَحْنُ بِمَسْبُوقِينَ» بِعاجِزِينَ", "malayalam": "«നിങ്ങൾക്കിടയിൽ മരണം നിശ്ചയിച്ചത് നാമാകുന്നു; നമ്മെ ആർക്കും തോൽപിക്കാനാവില്ല».", "malayalamMatn": "നാം നിങ്ങള്‍ക്കിടയില്‍ മരണം കണക്കാക്കിയിരിക്കുന്നു. നാം ഒരിക്കലും തോല്‍പിക്കപ്പെടുന്നവനല്ല."}, {"ayahNumber": 61, "quranText": "عَلَىٰۤ أَن نُّبَدِّلَ أَمۡثَـٰلَكُمۡ وَنُنشِئَكُمۡ فِی مَا لَا تَعۡلَمُونَ\n", "jalalayn": "«عَلى» عَنْ «أنْ نُبَدِّل» نَجْعَل «أمْثالكُمْ» مَكانكُمْ «ونُنْشِئكُمْ» نَخْلُقكُمْ «فِي ما لا تَعْلَمُونَ» مِن الصُّوَر كالقِرَدَةِ والخَنازِير", "malayalam": "«നിങ്ങൾക്ക് പകരം നിങ്ങളെപ്പോലെയുള്ളവരെ കൊണ്ടുവരുവാനും, നിങ്ങൾക്കറിയാത്ത മറ്റൊരു രൂപത്തിൽ നിങ്ങളെ പുനർസൃഷ്ടിക്കുവാനും».", "malayalamMatn": "(നിങ്ങള്‍ക്കു) പകരം നിങ്ങളെ പോലുള്ളവരെ കൊണ്ടുവരികയും. നിങ്ങള്‍ക്ക് അറിവില്ലാത്ത വിധത്തില്‍ നിങ്ങളെ (വീണ്ടും) സൃഷ്ടിച്ചുണ്ടാക്കുകയും ചെയ്യുന്ന കാര്യത്തില്‍"}, {"ayahNumber": 62, "quranText": "وَلَقَدۡ عَلِمۡتُمُ ٱلنَّشۡأَةَ ٱلۡأُولَىٰ فَلَوۡلَا تَذَكَّرُونَ\n", "jalalayn": "«ولَقَدْ عَلِمْتُمْ النَّشْأَة الأُولى» وفِي قِراءَة بِسُكُونِ الشِّين «فَلَوْلا تَذَكَّرُونَ» فِيهِ إدْغام التّاء الثّانِيَة فِي الأَصْل فِي الذّال", "malayalam": "«തീർച്ചയായും ആദ്യത്തെ സൃഷ്ടിപ്പിനെപ്പറ്റി നിങ്ങൾ മനസ്സിലാക്കിയിട്ടുണ്ടല്ലോ; എന്നിട്ടും നിങ്ങൾ ചിന്തിച്ചുനോക്കുന്നില്ലേ?»", "malayalamMatn": "ആദ്യതവണ സൃഷ്ടിക്കപ്പെട്ടതിനെപ്പറ്റി തീര്‍ച്ചയായും നിങ്ങള്‍ മനസ്സിലാക്കിയിട്ടുണ്ട്‌. എന്നിട്ടും നിങ്ങള്‍ എന്തുകൊണ്ട് ആലോചിച്ചു നോക്കുന്നില്ല."}, {"ayahNumber": 63, "quranText": "أَفَرَءَیۡتُم مَّا تَحۡرُثُونَ\n", "jalalayn": "«أفَرَأَيْتُمْ ما تَحْرُثُونَ» تُثِيرُونَ فِي الأَرْض وتُلْقُونَ البَذْر فِيها", "malayalam": "«നിങ്ങൾ വിതക്കുന്ന വിത്തിനെപ്പറ്റി നിങ്ങൾ ചിന്തിച്ചു നോക്കിയിട്ടുണ്ടോ?»", "malayalamMatn": "എന്നാല്‍ നിങ്ങള്‍ കൃഷി ചെയ്യുന്നതിനെ പറ്റി നിങ്ങള്‍ ചിന്തിച്ചു നോക്കിയിട്ടുണ്ടോ?"}, {"ayahNumber": 64, "quranText": "ءَأَنتُمۡ تَزۡرَعُونَهُۥۤ أَمۡ نَحۡنُ ٱلزَّ ٰ⁠رِعُونَ\n", "jalalayn": "«أأَنْتُمْ تَزْرَعُونَهُ» تُنْبِتُونَهُ", "malayalam": "«നിങ്ങളാണോ അത് മുളപ്പിച്ചു വളർത്തുന്നത്, അതോ നാമാണോ വളർത്തുന്നവൻ?»", "malayalamMatn": "നിങ്ങളാണോ അത് മുളപ്പിച്ചു വളര്‍ത്തുന്നത്‌. അതല്ല നാമാണോ, അത് മുളപ്പിച്ച് വളര്‍ത്തുന്നവന്‍?"}, {"ayahNumber": 65, "quranText": "لَوۡ نَشَاۤءُ لَجَعَلۡنَـٰهُ حُطَـٰمࣰا فَظَلۡتُمۡ تَفَكَّهُونَ\n", "jalalayn": "«لَوْ نَشاء لَجَعَلْناهُ حُطامًا» نَباتًا يابِسًا لا حَبّ فِيهِ «فَظَلْتُمْ» أصْله ظَلِلْتُمْ بِكَسْرِ اللّام حُذِفَتْ تَخْفِيفًا أيْ أقَمْتُمْ نَهارًا «تَفَكَّهُونَ» حُذِفَتْ مِنهُ إحْدى التّاءَيْنِ فِي الأَصْل تَعْجَبُونَ مِن ذَلِكَ وتَقُولُونَ:", "malayalam": "«നാം ഉദ്ദേശിച്ചിരുന്നുവെങ്കിൽ അതിനെ നാം ഉണങ്ങിയ വൈക്കോൽ തുണ്ടുകളാക്കി മാറ്റുമായിരുന്നു; അപ്പോൾ നിങ്ങൾ ആശ്ചര്യപ്പെട്ടു ഖേദിക്കുന്നവരായി മാറുമായിരുന്നു».", "malayalamMatn": "നാം ഉദ്ദേശിച്ചിരുന്നെങ്കില്‍ അത് (വിള) നാം തുരുമ്പാക്കിത്തീര്‍ക്കുമായിരുന്നു. അപ്പോള്‍ നിങ്ങള്‍ അതിശയപ്പെട്ടു പറഞ്ഞുകൊണേ്ടയിരിക്കുമായിരന്നു;"}, {"ayahNumber": 66, "quranText": "إِنَّا لَمُغۡرَمُونَ\n", "jalalayn": "«إنّا لَمُغْرَمُونَ» نَفَقَة زَرْعنا", "malayalam": "«ഞങ്ങൾ നഷ്ടത്തിലായിപ്പോയല്ലോ എന്ന് പറഞ്ഞുകൊണ്ട്».", "malayalamMatn": "തീര്‍ച്ചയായും ഞങ്ങള്‍ കടബാധിതര്‍ തന്നെയാകുന്നു."}, {"ayahNumber": 67, "quranText": "بَلۡ نَحۡنُ مَحۡرُومُونَ\n", "jalalayn": "«بَلْ نَحْنُ مَحْرُومُونَ» مَمْنُوعُونَ رِزْقنا", "malayalam": "«അല്ല, ഞങ്ങൾ ഉപജീവനമാർഗ്ഗം തടയപ്പെട്ടവരാകുന്നു എന്ന് വിലപിച്ചുകൊണ്ട്».", "malayalamMatn": "അല്ല, ഞങ്ങള്‍ (ഉപജീവന മാര്‍ഗം) തടയപ്പെട്ടവരാകുന്നു എന്ന്‌."}, {"ayahNumber": 68, "quranText": "أَفَرَءَیۡتُمُ ٱلۡمَاۤءَ ٱلَّذِی تَشۡرَبُونَ\n", "jalalayn": "«أَفَرَءَیۡتُمُ ٱلۡمَاۤءَ ٱلَّذِی تَشۡرَبُونَ».", "malayalam": "«നിങ്ങൾ കുടിക്കുന്ന ശുദ്ധജലത്തെപ്പറ്റി നിങ്ങൾ ചിന്തിച്ചു നോക്കിയിട്ടുണ്ടോ?»", "malayalamMatn": "ഇനി, നിങ്ങള്‍ കുടിക്കുന്ന വെള്ളത്തെപ്പറ്റി നിങ്ങള്‍ ചിന്തിച്ചു നോക്കിയിട്ടുണ്ടോ?"}, {"ayahNumber": 69, "quranText": "ءَأَنتُمۡ أَنزَلۡتُمُوهُ مِنَ ٱلۡمُزۡنِ أَمۡ نَحۡنُ ٱلۡمُنزِلُونَ\n", "jalalayn": "«أأَنْتُمْ أنَزَلْتُمُوهُ مِن المُزْن» السَّحاب جَمْع مُزْنَة", "malayalam": "«നിങ്ങളാണോ മേഘങ്ങളിൽ നിന്ന് അത് ഇറക്കിയത്, അതോ നാമാണോ ഇറക്കിയത്?»", "malayalamMatn": "നിങ്ങളാണോ അത് മേഘത്തിന്‍ നിന്ന് ഇറക്കിയത്‌? അതല്ല, നാമാണോ ഇറക്കിയവന്‍?."}, {"ayahNumber": 70, "quranText": "لَوۡ نَشَاۤءُ جَعَلۡنَـٰهُ أُجَاجࣰا فَلَوۡلَا تَشۡكُرُونَ\n", "jalalayn": "«لَوْ نَشاء جَعَلْناهُ أُجاجًا» مِلْحًا لا يُمْكِن شُرْبه «فَلَوْلا» هَلّا", "malayalam": "«നാം ഉദ്ദേശിച്ചിരുന്നുവെങ്കിൽ അതിനെ നാം കഠിനമായ ഉപ്പുരസമുള്ളതാക്കി മാറ്റുമായിരുന്നു; എന്നിട്ടും നിങ്ങൾ നന്ദി കാണിക്കാത്തതെന്താണ്?»", "malayalamMatn": "നാം ഉദ്ദേശിച്ചിരുന്നെങ്കില്‍ അത് നാം ദുസ്സ്വാദുള്ള ഉപ്പുവെള്ളമാക്കുമായിരുന്നു. എന്നിരിക്കെ നിങ്ങള്‍ നന്ദികാണിക്കാത്തതെന്താണ്‌?"}, {"ayahNumber": 71, "quranText": "أَفَرَءَیۡتُمُ ٱلنَّارَ ٱلَّتِی تُورُونَ\n", "jalalayn": "«أفَرَأَيْتُمْ النّار الَّتِي تُورُونَ» تُخْرِجُونَ مِن الشَّجَر الأَخْضَر", "malayalam": "«നിങ്ങൾ ഉരച്ചു കത്തിക്കുന്ന തീയ്യെപ്പറ്റി നിങ്ങൾ ചിന്തിച്ചു നോക്കിയിട്ടുണ്ടോ?»", "malayalamMatn": "നിങ്ങള്‍ ഉരസികത്തിക്കുന്നതായ തീയിനെ പറ്റി നിങ്ങള്‍ ചിന്തിച്ചു നോക്കിയിട്ടുണ്ടോ?"}, {"ayahNumber": 72, "quranText": "ءَأَنتُمۡ أَنشَأۡتُمۡ شَجَرَتَهَاۤ أَمۡ نَحۡنُ ٱلۡمُنشِـُٔونَ\n", "jalalayn": "«أأَنْتُمْ أنْشَأْتُمْ شَجَرَتها» كالمَرْخِ والعَفار والكلخ", "malayalam": "«നിങ്ങളാണോ അതിന്റെ മരം സൃഷ്ടിച്ചുണ്ടാക്കിയത്, അതോ നാമാണോ സൃഷ്ടിച്ചവൻ?»", "malayalamMatn": "നിങ്ങളാണോ അതിന്‍റെ മരം സൃഷ്ടിച്ചുണ്ടാക്കിയത്‌? അതല്ല നാമാണോ സൃഷ്ടിച്ചുണ്ടാക്കിയവന്‍?"}, {"ayahNumber": 73, "quranText": "نَحۡنُ جَعَلۡنَـٰهَا تَذۡكِرَةࣰ وَمَتَـٰعࣰا لِّلۡمُقۡوِینَ\n", "jalalayn": "«نَحْنُ جَعَلْناها تَذْكِرَة» لِنارِ جَهَنَّم «ومَتاعًا» بِلُغَةٍ «لِلْمُقْوِينَ» لِلْمُسافِرِينَ مِن أقْوى القَوْم: أيْ صارُوا بالقوا بِالقَصْرِ والمَدّ أيْ القَفْر وهُوَ مَفازَة لا نَبات فِيها ولا ماء", "malayalam": "«അതിനെ നാം ഒരു ഉൽബോധനവും യാത്രക്കാർക്ക് ഉപകാരപ്രദമായ ഒന്നാക്കി മാറ്റിയിരിക്കുന്നു».", "malayalamMatn": "നാം അതിനെ ഒരു ചിന്താവിഷയമാക്കിയിരിക്കുന്നു. ദരിദ്രരായ സഞ്ചാരികള്‍ക്ക് ഒരു ജീവിതസൌകര്യവും."}, {"ayahNumber": 74, "quranText": "فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِیمِ\n", "jalalayn": "«فَسَبِّحْ» نَزِّهْ «بِاسْمِ» زائِدَة «رَبّك العَظِيم» اللَّه", "malayalam": "«ആകയാൽ മഹാനായ നിന്റെ രക്ഷിതാവിന്റെ നാമത്തെ നീ പ്രകീർത്തിക്കുക».", "malayalamMatn": "ആകയാല്‍ നിന്‍റെ മഹാനായ രക്ഷിതാവിന്‍റെ നാമത്തെ നീ പ്രകീര്‍ത്തിക്കുക."}, {"ayahNumber": 75, "quranText": "۞ فَلَاۤ أُقۡسِمُ بِمَوَ ٰ⁠قِعِ ٱلنُّجُومِ\n", "jalalayn": "«فَلا أُقْسِم» لا زائِدَة «بِمَواقِع النُّجُوم» بِمَساقِطِها لِغُرُوبِها", "malayalam": "«നക്ഷത്രങ്ങളുടെ അസ്തമയ സ്ഥാനങ്ങളെക്കൊണ്ട് ഞാൻ സത്യം ചെയ്തു പറയുന്നു».", "malayalamMatn": "അല്ല, നക്ഷത്രങ്ങളുടെ അസ്തമന സ്ഥാനങ്ങളെകൊണ്ട് ഞാന്‍ സത്യം ചെയ്തു പറയുന്നു."}, {"ayahNumber": 76, "quranText": "وَإِنَّهُۥ لَقَسَمࣱ لَّوۡ تَعۡلَمُونَ عَظِیمٌ\n", "jalalayn": "«وإنَّهُ» أيْ القَسَم بِها «لَقَسَم لَوْ تَعْلَمُونَ عَظِيم» لَوْ كُنْتُمْ مِن ذَوِي العِلْم لَعَلِمْتُمْ عِظَم هَذا القَسَم", "malayalam": "«നിങ്ങൾ മനസ്സിലാക്കുന്നുവെങ്കിൽ തീർച്ചയായും അതൊരു മഹത്തായ സത്യം തന്നെയാണ്».", "malayalamMatn": "തീര്‍ച്ചയായും, നിങ്ങള്‍ക്കറിയാമെങ്കില്‍, അതൊരു വമ്പിച്ച സത്യം തന്നെയാണ്‌."}, {"ayahNumber": 77, "quranText": "إِنَّهُۥ لَقُرۡءَانࣱ كَرِیمࣱ\n", "jalalayn": "«إنّهُ» أيْ المَتْلُوّ عَلَيْكُمْ", "malayalam": "«തീർച്ചയായും ഇത് ആദരണീയമായ ഒരു ഖുർആൻ തന്നെയാകുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും ഇത് ആദരണീയമായ ഒരു ഖുര്‍ആന്‍ തന്നെയാകുന്നു."}, {"ayahNumber": 78, "quranText": "فِی كِتَـٰبࣲ مَّكۡنُونࣲ\n", "jalalayn": "«فِي كِتاب» مَكْتُوب «مَكْنُون» مَصُون وهُوَ المُصْحَف", "malayalam": "«ഭദ്രമായി സംരക്ഷിക്കപ്പെട്ട ഒരു ഗ്രന്ഥത്തിലാകുന്നു അത്» (ലൗഹുൽ മഹ്ഫൂളിൽ).", "malayalamMatn": "ഭദ്രമായി സൂക്ഷിക്കപ്പെട്ട ഒരു രേഖയിലാകുന്നു അത്‌."}, {"ayahNumber": 79, "quranText": "لَّا یَمَسُّهُۥۤ إِلَّا ٱلۡمُطَهَّرُونَ\n", "jalalayn": "«لا يَمَسّهُ» خَبَر بِمَعْنى النَّهْي «إلّا المُطَهَّرُونَ» الَّذِينَ طَهَّرُوا أنْفُسهمْ مِن الأَحْداث", "malayalam": "«പരിശുദ്ധി നൽകപ്പെട്ടവരല്ലാതെ» (മലക്കുകളല്ലാതെ) «അതിനെ സ്പർശിക്കുകയില്ല».", "malayalamMatn": "പരിശുദ്ധി നല്‍കപ്പെട്ടവരല്ലാതെ അത് സ്പര്‍ശിക്കുകയില്ല."}, {"ayahNumber": 80, "quranText": "تَنزِیلࣱ مِّن رَّبِّ ٱلۡعَـٰلَمِینَ\n", "jalalayn": "«تَنْزِيل» مُنَزَّل", "malayalam": "«സർവ്വലോക രക്ഷിതാവിങ്കൽ നിന്ന് അവതരിപ്പിക്കപ്പെട്ടതാകുന്നു അത്».", "malayalamMatn": "ലോകരക്ഷിതാവിങ്കല്‍ നിന്ന് അവതരിപ്പിക്കപ്പെട്ടതത്രെ അത്‌."}, {"ayahNumber": 81, "quranText": "أَفَبِهَـٰذَا ٱلۡحَدِیثِ أَنتُم مُّدۡهِنُونَ\n", "jalalayn": "«أفَبِهَذا الحَدِيث» القُرْآن «أنْتُمْ مُدْهِنُونَ» مُتَهاوِنُونَ مُكَذِّبُونَ", "malayalam": "«എന്നിരിക്കെ ഈ വർത്തമാനത്തോടാണോ നിങ്ങൾ നിസ്സംഗത പുലർത്തുന്നത്?»", "malayalamMatn": "അപ്പോള്‍ ഈ വര്‍ത്തമാനത്തിന്‍റെ കാര്യത്തിലാണോ നിങ്ങള്‍ പുറംപൂച്ച് കാണിക്കുന്നത്‌?"}, {"ayahNumber": 82, "quranText": "وَتَجۡعَلُونَ رِزۡقَكُمۡ أَنَّكُمۡ تُكَذِّبُونَ\n", "jalalayn": "«وتَجْعَلُونَ رِزْقكُمْ» مِن المَطَر أيْ شُكْره «أنَّكُمْ تُكَذِّبُونَ» بِسُقْيا اللَّه حَيْثُ قُلْتُمْ مُطِرْنا بِنَوْءِ كَذا", "malayalam": "«അതിനെ നിഷേധിച്ചു തള്ളുക എന്നതാണോ നിങ്ങൾക്ക് നൽകപ്പെട്ട വിഹിതത്തോടുള്ള നിങ്ങളുടെ നന്ദി?»", "malayalamMatn": "സത്യത്തെ നിഷേധിക്കുക എന്നത് നിങ്ങള്‍ നിങ്ങളുടെ വിഹിതമാക്കുകയാണോ?"}, {"ayahNumber": 83, "quranText": "فَلَوۡلَاۤ إِذَا بَلَغَتِ ٱلۡحُلۡقُومَ\n", "jalalayn": "«فَلَوْلا» فَهَلّا «إذا بَلَغَتْ» الرُّوح وقْت النَّزْع «الحُلْقُوم» هُوَ مَجْرى الطَّعام", "malayalam": "«എന്നാൽ പ്രാണൻ തൊണ്ടക്കുഴിയിൽ എത്തുമ്പോൾ എന്തുകൊണ്ട് നിങ്ങൾക്ക് സാധിക്കുന്നില്ല?»", "malayalamMatn": "എന്നാല്‍ അത് (ജീവന്‍) തൊണ്ടക്കുഴിയില്‍ എത്തുമ്പോള്‍ എന്തുകൊണ്ടാണ് (നിങ്ങള്‍ക്കത് പിടിച്ചു നിര്‍ത്താനാകാത്തത്‌?)"}, {"ayahNumber": 84, "quranText": "وَأَنتُمۡ حِینَىِٕذࣲ تَنظُرُونَ\n", "jalalayn": "«وأَنْتُمْ» يا حاضِرِي المَيِّت «حِينَئِذٍ تَنْظُرُونَ» تَنْظُرُونَ إلَيْهِ", "malayalam": "«ആ സമയത്ത് നിങ്ങൾ നോക്കിനിൽക്കുക മാത്രമായിരിക്കും».", "malayalamMatn": "നിങ്ങള്‍ അന്നേരത്ത് നോക്കിക്കൊണ്ടിരിക്കുമല്ലോ."}, {"ayahNumber": 85, "quranText": "وَنَحۡنُ أَقۡرَبُ إِلَیۡهِ مِنكُمۡ وَلَـٰكِن لَّا تُبۡصِرُونَ\n", "jalalayn": "«ونَحْنُ أقْرَب إلَيْهِ مِنكُمْ» بِالعِلْمِ «ولَكِنْ لا تُبْصِرُونَ» مِن البَصِيرَة أيْ لا تَعْلَمُونَ ذَلِكَ", "malayalam": "«നിങ്ങളേക്കാൾ അവനോട് ഏറ്റവും അടുത്തവൻ നാമാകുന്നു» (നമ്മുടെ മലക്കുകൾ വഴിയായി); «എന്നാൽ നിങ്ങൾ അത് കാണുന്നില്ല».", "malayalamMatn": "നാമാണ് ആ വ്യക്തിയെ സംബന്ധിച്ചിടത്തോളം നിങ്ങളെക്കാളും അടുത്തവന്‍. പക്ഷെ നിങ്ങള്‍ കണ്ടറിയുന്നില്ല."}, {"ayahNumber": 86, "quranText": "فَلَوۡلَاۤ إِن كُنتُمۡ غَیۡرَ مَدِینِینَ\n", "jalalayn": "«فَلَوْلا» فَهَلّا «إنْ كُنْتُمْ غَيْر مَدِينِينَ» مَجْزِيِّينَ بِأَنْ تُبْعَثُوا أيْ غَيْر مَبْعُوثِينَ بِزَعْمِكُمْ", "malayalam": "«നിങ്ങൾ വിചാരണക്ക് വിധേയരല്ലെന്ന നിങ്ങളുടെ വാദം സത്യമാണെങ്കിൽ».", "malayalamMatn": "അപ്പോള്‍ നിങ്ങള്‍ (ദൈവിക നിയമത്തിന്‌) വിധേയരല്ലാത്തവരാണെങ്കില്‍"}, {"ayahNumber": 87, "quranText": "تَرۡجِعُونَهَاۤ إِن كُنتُمۡ صَـٰدِقِینَ\n", "jalalayn": "«تَرْجِعُونَها» تَرُدُّونَ الرُّوح إلى الجَسَد بَعْد بُلُوغ الحُلْقُوم «إنْ كُنْتُمْ صادِقِينَ» فِيما زَعَمْتُمْ فَلَوْلا الثّانِيَة تَأْكِيد لِلْأُولى وإذا ظَرْف لِتَرْجِعُونَ المُتَعَلِّق بِهِ الشَّرْطانِ والمَعْنى: هَلّا تَرْجِعُونَها إنْ نَفَيْتُمْ البَعْث صادِقِينَ فِي نَفْيه أيْ لِيَنْتَفِيَ عَنْ مَحِلّها المَوْت كالبَعْثِ", "malayalam": "«നിങ്ങൾ സത്യവാന്മാരാണെങ്കിൽ ആ പ്രാണനെ നിങ്ങൾക്ക് തിരിച്ചുകൊണ്ടുവരാൻ സാധിക്കുമോ?» (ഒരിക്കലും സാധിക്കില്ല).", "malayalamMatn": "നിങ്ങള്‍ക്കെന്തുകൊണ്ട് അത് (ജീവന്‍) മടക്കി എടുക്കാനാവുന്നില്ല; നിങ്ങള്‍ സത്യവാദികളാണെങ്കില്‍."}, {"ayahNumber": 88, "quranText": "فَأَمَّاۤ إِن كَانَ مِنَ ٱلۡمُقَرَّبِینَ\n", "jalalayn": "«فَأَمّا إنْ كانَ» المَيِّت", "malayalam": "«ഇനി അവൻ അല്ലാഹുവിലേക്ക് സാമീപ്യം സിദ്ധിച്ചവരിൽ പെട്ടവനാണെങ്കിൽ».", "malayalamMatn": "അപ്പോള്‍ അവന്‍ (മരിച്ചവന്‍) സാമീപ്യം സിദ്ധിച്ചവരില്‍ പെട്ടവനാണെങ്കില്‍-"}, {"ayahNumber": 89, "quranText": "فَرَوۡحࣱ وَرَیۡحَانࣱ وَجَنَّتُ نَعِیمࣲ\n", "jalalayn": "«فَرَوْح» أيْ فَلَهُ اسْتِراحَة «ورَيْحان» أيْ رِزْق حَسَن «وجَنَّة نَعِيم» وهَلْ الجَواب لِأَمّا أوْ لإنْ أوْ لَهُما ؟ أقْوال.", "malayalam": "«അവന് ആശ്വാസവും വിശിഷ്ടമായ വിഭവങ്ങളും അനുഗ്രഹങ്ങളുടെ സ്വർഗ്ഗവുമുണ്ട്».", "malayalamMatn": "(അവന്ന്‌) ആശ്വാസവും വിശിഷ്ടമായ ഉപജീവനവും സുഖാനുഭൂതിയുടെ സ്വര്‍ഗത്തോപ്പും ഉണ്ടായിരിക്കും."}, {"ayahNumber": 90, "quranText": "وَأَمَّاۤ إِن كَانَ مِنۡ أَصۡحَـٰبِ ٱلۡیَمِینِ\n", "jalalayn": "«وَأَمَّاۤ إِن كَانَ مِنۡ أَصۡحَـٰبِ ٱلۡیَمِینِ».", "malayalam": "«ഇനി അവൻ വലതുപക്ഷക്കാരിൽ പെട്ടവനാണെങ്കിലോ».", "malayalamMatn": "എന്നാല്‍ അവന്‍ വലതുപക്ഷക്കാരില്‍ പെട്ടവനാണെങ്കിലോ,"}, {"ayahNumber": 91, "quranText": "فَسَلَـٰمࣱ لَّكَ مِنۡ أَصۡحَـٰبِ ٱلۡیَمِینِ\n", "jalalayn": "«فَسَلام لَك» أيْ لَهُ السَّلامَة مِن العَذاب «مِن أصْحاب اليَمِين» مِن جِهَة أنَّهُ مِنهُمْ", "malayalam": "«വലതുപക്ഷക്കാരിൽ നിന്നുള്ള ശാന്തിയും അഭിവാദനങ്ങളും നിനക്കുണ്ടായിരിക്കും».", "malayalamMatn": "വലതുപക്ഷക്കാരില്‍പെട്ട നിനക്ക് സമാധാനം എന്നായിരിക്കും (അവന്നു ലഭിക്കുന്ന അഭിവാദ്യം)"}, {"ayahNumber": 92, "quranText": "وَأَمَّاۤ إِن كَانَ مِنَ ٱلۡمُكَذِّبِینَ ٱلضَّاۤلِّینَ\n", "jalalayn": "«وَأَمَّاۤ إِن كَانَ مِنَ ٱلۡمُكَذِّبِینَ ٱلضَّاۤلِّینَ».", "malayalam": "«എന്നാൽ അവൻ സത്യനിഷേധികളായ ദുർമാർഗ്ഗികളിൽ പെട്ടവനാണെങ്കിലോ».", "malayalamMatn": "ഇനി അവന്‍ ദുര്‍മാര്‍ഗികളായ സത്യനിഷേധികളില്‍ പെട്ടവനാണെങ്കിലോ,"}, {"ayahNumber": 93, "quranText": "فَنُزُلࣱ مِّنۡ حَمِیمࣲ\n", "jalalayn": "«فَنُزُلٌ مِّنۡ حَمِیمࣲ» مِن إضافَة المَوْصُوف إلى صِفَته.", "malayalam": "«തിളച്ചുമറിയുന്ന വെള്ളം കൊണ്ടുള്ള സൽക്കാരമായിരിക്കും അവന്».", "malayalamMatn": "ചുട്ടുതിളക്കുന്ന വെള്ളം കൊണ്ടുള്ള സല്‍ക്കാരവും"}, {"ayahNumber": 94, "quranText": "وَتَصۡلِیَةُ جَحِیمٍ\n", "jalalayn": "«وَتَصۡلِیَةُ جَحِیمٍ» مِن إضافَة المَوْصُوف إلى صِفَته.", "malayalam": "«ജ്വലിക്കുന്ന നരകാഗ്നിയിലെ എരിച്ചിലും».", "malayalamMatn": "നരകത്തില്‍ വെച്ചുള്ള ചുട്ടെരിക്കലുമാണ്‌. (അവന്നുള്ളത്‌.)"}, {"ayahNumber": 95, "quranText": "إِنَّ هَـٰذَا لَهُوَ حَقُّ ٱلۡیَقِینِ\n", "jalalayn": "«إنّ هَذا لَهُوَ حَقّ اليَقِين» مِن إضافَة المَوْصُوف إلى صِفَته", "malayalam": "«തീർച്ചയായും ഇത് സംശയരഹിതമായ പരമയാഥാർത്ഥ്യം തന്നെയാണ്».", "malayalamMatn": "തീര്‍ച്ചയായും ഇതു തന്നെയാണ് ഉറപ്പുള്ള യാഥാര്‍ത്ഥ്യം."}, {"ayahNumber": 96, "quranText": "فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِیمِ\n", "jalalayn": "«فَسَبِّحْ بِاسْمِ رَبّك العَظِيم» تَقَّدَمَ", "malayalam": "«ആകയാൽ മഹാനായ നിന്റെ രക്ഷിതാവിന്റെ നാമത്തെ നീ വാഴ്ത്തി പ്രകീർത്തിക്കുക».", "malayalamMatn": "ആകയാല്‍ നീ നിന്‍റെ മഹാനായ രക്ഷിതാവിന്‍റെ നാമം പ്രകീര്‍ത്തിക്കുക."}], "topPoints": ["അന്ത്യനാളിന്റെ ഭീകരതയും അനിവാര്യതയും (خلاصة السورة)", "മനുഷ്യരെ മൂന്ന് വിഭാഗങ്ങളായി തിരിക്കുന്നത് (മുൻകടന്നവർ, വലത്തുകാർ, ഇടത്തുകാർ)"], "topQuestions": [{"q": "സൂറത്തുൽ വാഖിഅയിൽ മനുഷ്യരെ എത്ര വിഭാഗങ്ങളായി തിരിച്ചിരിക്കുന്നു?", "a": "മൂന്ന് വിഭാഗങ്ങളായി: അല്ലാഹുവിന്റെ സാമീപ്യം സിദ്ധിച്ചവർ, വലതുപക്ഷക്കാർ, ഇടതുപക്ഷക്കാർ."}], "asbabAlNuzul": []}, {"surahNumber": 57, "surahNameArabic": "سُورَةُ الحَدِيدِ", "surahNameMalayalam": "സൂറത്തുൽ ഹദീദ് (ഇരുമ്പ്)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ سَبَّحَ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n", "jalalayn": "«سَبَّحَ لِلَّهِ ما فِي السَّماوات والأَرْض» أيْ نَزَّهَهُ كُلّ شَيْء فاللّام مَزِيدَة وجِيءَ بِما دُون مِن تَغْلِيبًا لِلْأَكْثَرِ «وهُوَ العَزِيز» فِي مُلْكه «الحَكِيم» فِي صُنْعه", "malayalam": "«ആകാശങ്ങളിലും ഭൂമിയിലുമുള്ള സർവ്വ വസ്തുക്കളും അല്ലാഹുവിന്റെ പരിശുദ്ധിയെ പ്രകീർത്തിച്ചിരിക്കുന്നു; അവൻ പ്രതാപിയും പരമയുക്തിമാനുമാകുന്നു» (തന്റെ ഭരണത്തിലും സൃഷ്ടിപ്പിലും).", "malayalamMatn": "ആകാശങ്ങളിലും ഭൂമിയിലുമുള്ളതെല്ലാം അല്ലാഹുവിന് പ്രകീര്‍ത്തനം ചെയ്തിരിക്കുന്നു. അവന്‍ പ്രതാപിയും യുക്തിമാനുമത്രെ."}, {"ayahNumber": 2, "quranText": "لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ یُحۡیِۦ وَیُمِیتُۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ\n", "jalalayn": "«لَهُ مُلْك السَّمَوات والأَرْض يُحْيِي» بِالإنْشاءِ «ويُمِيت» بَعْده", "malayalam": "«ആകാശങ്ങളുടെയും ഭൂമിയുടെയും ആധിപത്യം അവന്നുള്ളതാകുന്നു; അവൻ ജീവിപ്പിക്കുകയും അവൻ മരിപ്പിക്കുകയും ചെയ്യുന്നു; അവൻ സർവ്വകാര്യങ്ങൾക്കും കഴിവുള്ളവനത്രെ».", "malayalamMatn": "അവന്നാകുന്നു ആകാശങ്ങളുടെയും ഭൂമിയുടെയും ആധിപത്യം. അവന്‍ ജീവിപ്പിക്കുകയും മരിപ്പിക്കുകയും ചെയ്യുന്നു. അവന്‍ സര്‍വ്വകാര്യത്തിനും കഴിവുള്ളവനുമാണ്‌."}, {"ayahNumber": 3, "quranText": "هُوَ ٱلۡأَوَّلُ وَٱلۡـَٔاخِرُ وَٱلظَّـٰهِرُ وَٱلۡبَاطِنُۖ وَهُوَ بِكُلِّ شَیۡءٍ عَلِیمٌ\n", "jalalayn": "«هُوَ الأَوَّل» قَبْل كُلّ شَيْء بِلا بِدايَةٍ «والآخِر» بَعْد كُلّ شَيْء بِلا نِهايَة «والظّاهِر» بِالأَدِلَّةِ عَلَيْهِ «والباطِن» عَنْ إدْراك الحَواسّ", "malayalam": "«അവൻ ആദിയാകുന്നു» (തുടക്കമില്ലാത്തവൻ), «അന്ത്യനാകുന്നു» (അവസാനമില്ലാത്തവൻ), «പ്രത്യക്ഷനാകുന്നു» (തന്റെ ദൃഷ്ടാന്തങ്ങളിലൂടെ വ്യക്തമായവൻ), «പരോക്ഷനാകുന്നു» (ഭൗതിക ഇന്ദ്രിയങ്ങൾക്ക് അതീതനായവൻ); «അവൻ സർവ്വകാര്യങ്ങളെക്കുറിച്ചും സൂക്ഷ്മമായി അറിയുന്നവനത്രെ».", "malayalamMatn": "അവന്‍ ആദിയും അന്തിമനും പ്രത്യക്ഷമായവനും പരോക്ഷമായവനുമാണ്‌. അവന്‍ സര്‍വ്വകാര്യങ്ങളെക്കുറിച്ചും അറിവുള്ളവനുമാണ്‌."}, {"ayahNumber": 4, "quranText": "هُوَ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ فِی سِتَّةِ أَیَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ یَعۡلَمُ مَا یَلِجُ فِی ٱلۡأَرۡضِ وَمَا یَخۡرُجُ مِنۡهَا وَمَا یَنزِلُ مِنَ ٱلسَّمَاۤءِ وَمَا یَعۡرُجُ فِیهَاۖ وَهُوَ مَعَكُمۡ أَیۡنَ مَا كُنتُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرࣱ\n", "jalalayn": "«هُوَ الَّذِي خَلَقَ السَّماوات والأَرْض فِي سِتَّة أيّام» مِن أيّام الدُّنْيا أوَّلها الأَحَد وآخِرها الجُمُعَة «ثُمَّ اسْتَوى عَلى العَرْش» الكُرْسِيّ اسْتِواء يَلِيق بِهِ «يَعْلَم ما يَلِج» يَدْخُل «فِي الأَرْض» كالمَطَرِ والأَمْوات «وما يَخْرُج مِنها» كالنَّباتِ والمَعادِن «وما يَنْزِل مِن السَّماء» كالرَّحْمَةِ والعَذاب «وما يَعْرُج» يَصْعَد «فِيها» كالأَعْمالِ الصّالِحَة والسَّيِّئَة «وهُوَ مَعَكُمْ» بِعِلْمِهِ", "malayalam": "«ആകാശങ്ങളെയും ഭൂമിയെയും ആറു ദിവസങ്ങളിലായി സൃഷ്ടിക്കുകയും പിന്നീട് അർശിന്മേൽ അധികാരാരോഹണം നടത്തുകയും ചെയ്തവൻ അവനത്രെ; ഭൂമിയിലേക്ക് പ്രവേശിക്കുന്നതും അതിൽ നിന്ന് പുറത്തുവരുന്നതും ആകാശത്ത് നിന്ന് ഇറങ്ങുന്നതും അതിലേക്ക് കയറിപ്പോകുന്നതുമെല്ലാം അവൻ അറിയുന്നു; നിങ്ങൾ എവിടെയായിരുന്നാലും അവൻ നിങ്ങളുടെ കൂടെയുണ്ട്; നിങ്ങൾ പ്രവർത്തിക്കുന്നതെല്ലാം അല്ലാഹു കണ്ടറിയുന്നവനത്രെ».", "malayalamMatn": "ആകാശങ്ങളും ഭൂമിയും ആറുദിവസങ്ങളിലായി സൃഷ്ടിച്ചവനാണ് അവന്‍. പിന്നീട് അവന്‍ സിംഹാസനസ്ഥനായി. ഭൂമിയില്‍ പ്രവേശിക്കുന്നതും അതില്‍ നിന്ന് പുറത്തു വരുന്നതും, ആകാശത്ത് നിന്ന് ഇറങ്ങുന്നതും അതിലേക്ക് കയറിച്ചെല്ലുന്നതും അവന്‍ അറിഞ്ഞ് കൊണ്ടിരിക്കുന്നു. നിങ്ങള്‍ എവിടെയായിരുന്നാലും അവന്‍ നിങ്ങളുടെ കൂടെയുണ്ട് താനും. അല്ലാഹു നിങ്ങള്‍ പ്രവര്‍ത്തിക്കുന്നതിനെപ്പറ്റി കണ്ടറിയുന്നവനാകുന്നു."}, {"ayahNumber": 5, "quranText": "لَّهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ\n", "jalalayn": "«لَهُ مُلْك السَّماوات والأَرْض وإلى اللَّه تُرْجَع الأُمُور» المَوْجُودات جَمِيعها", "malayalam": "«ആകാശങ്ങളുടെയും ഭൂമിയുടെയും ആധിപത്യം അവന്നുള്ളതാകുന്നു; അല്ലാഹുവിങ്കലേക്കാണ് സർവ്വ കാര്യങ്ങളും മടക്കപ്പെടുന്നത്».", "malayalamMatn": "അവന്നാണ് ആകാശങ്ങളുടെയും ഭൂമിയുടെയും ആധിപത്യം. അല്ലാഹുവിങ്കലേക്ക് തന്നെ കാര്യങ്ങള്‍ മടക്കപ്പെടുകയും ചെയ്യുന്നു."}, {"ayahNumber": 6, "quranText": "یُولِجُ ٱلَّیۡلَ فِی ٱلنَّهَارِ وَیُولِجُ ٱلنَّهَارَ فِی ٱلَّیۡلِۚ وَهُوَ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ\n", "jalalayn": "«يُولِج اللَّيْل» يُدْخِلهُ «فِي النَّهار» فَيَزِيد ويَنْقُص اللَّيْل «ويُولِج النَّهار فِي اللَّيْل» فَيَزِيد ويَنْقُص النَّهار «وهُوَ عَلِيم بِذاتِ الصُّدُور» بِما فِيها مِن الأَسْرار والمُعْتَقَدات", "malayalam": "«അവൻ രാത്രിയെ പകലിലേക്ക് പ്രവേശിപ്പിക്കുന്നു; പകലിനെ രാത്രിയിലേക്കും പ്രവേശിപ്പിക്കുന്നു; ഹൃദയങ്ങളിലുള്ള രഹസ്യങ്ങളെക്കുറിച്ച് അവൻ ഏറ്റവും നന്നായി അറിയുന്നവനത്രെ».", "malayalamMatn": "അവന്‍ രാത്രിയെ പകലില്‍ പ്രവേശിപ്പിക്കുന്നു. അവന്‍ പകലിനെ രാത്രിയില്‍ പ്രവേശിപ്പിക്കുകയും ചെയ്യുന്നു. അവന്‍ ഹൃദയങ്ങളിലുള്ളവയെപ്പറ്റി അറിയുന്നവനുമാകുന്നു."}, {"ayahNumber": 7, "quranText": "ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُوا۟ مِمَّا جَعَلَكُم مُّسۡتَخۡلَفِینَ فِیهِۖ فَٱلَّذِینَ ءَامَنُوا۟ مِنكُمۡ وَأَنفَقُوا۟ لَهُمۡ أَجۡرࣱ كَبِیرࣱ\n", "jalalayn": "«آمِنُوا» داوَمُوا عَلى الإيمان «بِاللَّهِ ورَسُوله وأَنْفَقُوا» فِي سَبِيل اللَّه «مِمّا جَعَلَكُمْ مُسْتَخْلَفِينَ فِيهِ» مِن مال مَن تَقَدَّمَكُمْ وسَيَخْلُفُكُمْ فِيهِ مَن بَعْدكُمْ نَزَلَ فِي غَزْوَة العُسْرَة وهِيَ غَزْوَة تَبُوك «فالَّذِينَ آمَنُوا مِنكُمْ وأَنْفَقُوا» إشارَة إلى عُثْمان رَضِيَ اللَّه عَنْهُ", "malayalam": "«നിങ്ങൾ അല്ലാഹുവിലും അവന്റെ റസൂലിലും ഉറച്ചു വിശ്വസിക്കുവിൻ; അവൻ നിങ്ങളെ പ്രതിനിധികളാക്കി ഭരമേൽപ്പിച്ച സമ്പത്തിൽ നിന്ന് നിങ്ങൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ചെലവഴിക്കുകയും ചെയ്യുവിൻ; നിങ്ങളിൽ നിന്ന് വിശ്വസിക്കുകയും ധർമ്മം ചെയ്യുകയും ചെയ്തവർക്ക് വലിയ പ്രതിഫലമുണ്ട്» (തബൂക്ക് വേളയിൽ ഉസ്മാൻ (റ) സൈന്യത്തിനായി സമ്പത്ത് ചെലവഴിച്ചപ്പോൾ ഇത് അവതരിച്ചു).", "malayalamMatn": "നിങ്ങള്‍ അല്ലാഹുവിലും അവന്‍റെ ദൂതനിലും വിശ്വസിക്കുകയും, അവന്‍ നിങ്ങളെ ഏതൊരു സ്വത്തില്‍ പിന്തുടര്‍ച്ച നല്‍കപ്പെട്ടവരാക്കിയിരിക്കുന്നോ അതില്‍ നിന്നു ചെലവഴിക്കുകയും ചെയ്യുക. അങ്ങനെ നിങ്ങളുടെ കൂട്ടത്തില്‍ നിന്ന് വിശ്വസിക്കുകയും ചെലവഴിക്കുകയും ചെയ്തവരാരോ അവര്‍ക്ക് വലിയ പ്രതിഫലമുണ്ടായിരിക്കുന്നതാണ്‌."}, {"ayahNumber": 8, "quranText": "وَمَا لَكُمۡ لَا تُؤۡمِنُونَ بِٱللَّهِ وَٱلرَّسُولُ یَدۡعُوكُمۡ لِتُؤۡمِنُوا۟ بِرَبِّكُمۡ وَقَدۡ أَخَذَ مِیثَـٰقَكُمۡ إِن كُنتُم مُّؤۡمِنِینَ\n", "jalalayn": "«وما لَكُمْ لا تُؤْمِنُونَ» خِطاب لِلْكُفّارِ أيْ لا مانِع لَكُمْ مِن الإيمان «بِاللَّهِ والرَّسُول يَدْعُوكُمْ لِتُؤْمِنُوا بِرَبِّكُمْ وقَدْ أُخِذَ» بِضَمِّ الهَمْزَة وكَسْر الخاء وبِفَتْحِها ونَصْب ما بَعْده «مِيثاقكُمْ» عَلَيْهِ أيْ أخَذَهُ اللَّه فِي عالَم الذَّرّ حِين أشْهَدَهُمْ عَلى أنْفُسهمْ «إنْ كُنْتُمْ مُؤْمِنِينَ» أيْ مُرِيدِينَ الإيمان بِهِ فَبادِرُوا إلَيْهِ", "malayalam": "«നിങ്ങളുടെ രക്ഷിതാവിൽ വിശ്വസിക്കുവാൻ റസൂൽ നിങ്ങളെ ക്ഷണിച്ചുകൊണ്ടിരിക്കെ നിങ്ങൾക്കെന്തു പറ്റി, നിങ്ങൾ അല്ലാഹുവിൽ വിശ്വസിക്കാതിരിക്കാൻ? അവൻ നിങ്ങളുടെ പക്കൽ നിന്ന് ഉടമ്പടി വാങ്ങിയിട്ടുമുണ്ട്; നിങ്ങൾ യഥാർത്ഥ വിശ്വാസികളാകാൻ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ വേഗത്തിൽ വിശ്വസിക്കുവിൻ».", "malayalamMatn": "അല്ലാഹുവില്‍ വിശ്വസിക്കാതിരിക്കാന്‍ നിങ്ങള്‍ക്കെന്താണ് ന്യായം? ഈ ദൂതനാകട്ടെ നിങ്ങളുടെ രക്ഷിതാവില്‍ വിശ്വസിക്കാന്‍ വേണ്ടി നിങ്ങളെ ക്ഷണിച്ചു കൊണ്ടിരിക്കുകയുമാണ്‌. അല്ലാഹു നിങ്ങളുടെ ഉറപ്പ് വാങ്ങിയിട്ടുമുണ്ട്‌. നിങ്ങള്‍ വിശ്വസിക്കുന്നവരാണെങ്കില്‍!"}, {"ayahNumber": 9, "quranText": "هُوَ ٱلَّذِی یُنَزِّلُ عَلَىٰ عَبۡدِهِۦۤ ءَایَـٰتِۭ بَیِّنَـٰتࣲ لِّیُخۡرِجَكُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِۚ وَإِنَّ ٱللَّهَ بِكُمۡ لَرَءُوفࣱ رَّحِیمࣱ\n", "jalalayn": "«هُوَ الَّذِي يُنَزِّل عَلى عَبْده آيات بَيِّنات» آيات القُرْآن «لِيُخْرِجكُمْ مِن الظُّلُمات» الكُفْر «إلى النُّور» الإيمان «وإنَّ اللَّه بِكُمْ» أيْ فِي إخْراجكُمْ مِن الكُفْر إلى الإيمان", "malayalam": "«നിങ്ങളെ അന്ധകാരങ്ങളിൽ നിന്ന് വെളിച്ചത്തിലേക്ക് നയിക്കുവാനായി തന്റെ ദാസന് സുവ്യക്തമായ ദൃഷ്ടാന്തങ്ങൾ ഇറക്കിക്കൊടുക്കുന്നത് അവനത്രെ; തീർച്ചയായും അല്ലാഹു നിങ്ങളോട് അത്യധികം ദയയുള്ളവനും പരമകാരുണികനുമാകുന്നു».", "malayalamMatn": "നിങ്ങളെ ഇരുട്ടില്‍ നിന്ന് പ്രകാശത്തിലേക്ക് കൊണ്ടുവരാന്‍ വേണ്ടി തന്‍റെ ദാസന്‍റെ മേല്‍ വ്യക്തമായ ദൃഷ്ടാന്തങ്ങള്‍ ഇറക്കികൊടുക്കുന്നവനാണ് അവന്‍. തീര്‍ച്ചയായും അല്ലാഹു നിങ്ങളോട് വളരെയധികം ദയാലുവും കാരുണ്യവാനും തന്നെയാണ്‌."}, {"ayahNumber": 10, "quranText": "وَمَا لَكُمۡ أَلَّا تُنفِقُوا۟ فِی سَبِیلِ ٱللَّهِ وَلِلَّهِ مِیرَ ٰ⁠ثُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ لَا یَسۡتَوِی مِنكُم مَّنۡ أَنفَقَ مِن قَبۡلِ ٱلۡفَتۡحِ وَقَـٰتَلَۚ أُو۟لَـٰۤىِٕكَ أَعۡظَمُ دَرَجَةࣰ مِّنَ ٱلَّذِینَ أَنفَقُوا۟ مِنۢ بَعۡدُ وَقَـٰتَلُوا۟ۚ وَكُلࣰّا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ\n", "jalalayn": "«وما لَكُمْ» وما حالكُمْ بَعْد إيمانكُمْ «ألّا» فِيهِ إدْغام نُون أنْ فِي لام لا «تُنْفِقُوا فِي سَبِيل اللَّه ولِلَّهِ مِيراث السَّماوات والأَرْض» بِما فِيهِما فَتَصِل إلَيْهِ أمْوالكُمْ مِن غَيْر أجْر الإنْفاق بِخِلافِ ما لَوْ أنْفَقْتُمْ فَتُؤْجَرُونَ «لا يَسْتَوِي مِنكُمْ مَن أنْفَقَ مِن قَبْل الفَتْح» لِمَكَّة «وقاتَلَ أُولَئِكَ أعْظَم دَرَجَة مِن الَّذِينَ أنْفَقُوا مِن بَعْد وقاتَلُوا وكُلًّا» مِن الفَرِيقَيْنِ وفِي قِراءَة بِالرَّفْعِ مُبْتَدَأ «وعَدَ اللَّه الحُسْنى» الجَنَّة «واللَّه بِما تَعْمَلُونَ خَبِير» فَيُجازِيكُمْ بِهِ", "malayalam": "«ആകാശങ്ങളുടെയും ഭൂമിയുടെയും അനന്തരാവകാശം അല്ലാഹുവിനായിരിക്കെ അവന്റെ മാർഗ്ഗത്തിൽ ചെലവഴിക്കാതിരിക്കാൻ നിങ്ങൾക്കെന്തു ന്യായമാണുള്ളത്? മക്കാവിജയത്തിന് മുമ്പ് ധർമ്മം ചെയ്യുകയും പോരാടുകയും ചെയ്തവരും മറ്റുള്ളവരും സമമാകുകയില്ല; അവർക്ക് ശേഷമുള്ളവരേക്കാൾ പദവിയിൽ എത്രയോ ഉന്നതരാണവർ; എന്നാൽ എല്ലാവർക്കും അല്ലാഹു ഏറ്റവും ഉത്തമമായ പ്രതിഫലം വാഗ്ദാനം ചെയ്തിരിക്കുന്നു; നിങ്ങൾ പ്രവർത്തിക്കുന്നതിനെക്കുറിച്ച് അല്ലാഹു സൂക്ഷ്മമായി അറിയുന്നവനത്രെ».", "malayalamMatn": "ആകാശങ്ങളുടെയും ഭൂമിയുടെയും അനന്തരാവകാശം അല്ലാഹുവിനുള്ളതായിരിക്കെ അല്ലാഹുവിന്‍റെ മാര്‍ഗത്തില്‍ ചെലവഴിക്കാതിരിക്കാന്‍ നിങ്ങള്‍ക്കെന്താണ് ന്യായം? നിങ്ങളുടെ കൂട്ടത്തില്‍ നിന്നു (മക്കാ) വിജയത്തിനു മുമ്പുള്ള കാലത്ത് ചെലവഴിക്കുകയും യുദ്ധത്തില്‍ പങ്കെടുക്കുകയും ചെയ്തവരും (അല്ലാത്തവരും) സമമാകുകയില്ല. അക്കൂട്ടര്‍ പിന്നീടു ചെലവഴിക്കുകയും യുദ്ധത്തില്‍ പങ്കുവഹിക്കുകയും ചെയ്തവരെക്കാള്‍ മഹത്തായ പദവിയുള്ളവരാകുന്നു. എല്ലാവര്‍ക്കും ഏറ്റവും നല്ല പ്രതിഫലം അല്ലാഹു വാഗ്ദാനം ചെയ്തിരിക്കുന്നു. നിങ്ങള്‍ പ്രവര്‍ത്തിക്കുന്നതിനെപ്പറ്റി സൂക്ഷ്മജ്ഞാനമുള്ളവനാണ് അല്ലാഹു."}, {"ayahNumber": 11, "quranText": "مَّن ذَا ٱلَّذِی یُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنࣰا فَیُضَـٰعِفَهُۥ لَهُۥ وَلَهُۥۤ أَجۡرࣱ كَرِیمࣱ\n", "jalalayn": "«مَن ذا الَّذِي يُقْرِض اللَّه» بِإنْفاقِ ماله فِي سَبِيل اللَّه «قَرْضًا حَسَنًا» بِأَنْ يُنْفِقهُ لِلَّهِ «فَيُضاعِفهُ» وفِي قِراءَة فَيُضَعِّفهُ بِالتَّشْدِيدِ «لَهُ» مِن عَشْر إلى أكْثَر مِن سَبْعمِائَةٍ كَما ذُكِرَ فِي البَقَرَة «ولَهُ» مَعَ المُضاعَفَة «أجْر كَرِيم» مُقْتَرِن بِهِ رِضا وإقْبال", "malayalam": "«അല്ലാഹുവിന് ഉത്തമമായ കടം നൽകുവാൻ ആരാണുള്ളത്? എങ്കിൽ അവനത് ഇരട്ടിയാക്കി നൽകുന്നതാണ്; അവന് മാന്യമായ പ്രതിഫലവുമുണ്ട്».", "malayalamMatn": "ആരുണ്ട് അല്ലാഹുവിന് ഒരു നല്ല കടം കൊടുക്കുവാന്‍? എങ്കില്‍ അവനത് അയാള്‍ക്ക് വേണ്ടി ഇരട്ടിപ്പിക്കുന്നതാണ്‌. അയാള്‍ക്കാണ് മാന്യമായ പ്രതിഫലമുള്ളത്‌."}, {"ayahNumber": 12, "quranText": "یَوۡمَ تَرَى ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ یَسۡعَىٰ نُورُهُم بَیۡنَ أَیۡدِیهِمۡ وَبِأَیۡمَـٰنِهِمۖ بُشۡرَىٰكُمُ ٱلۡیَوۡمَ جَنَّـٰتࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ ذَ ٰ⁠لِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ\n", "jalalayn": "اُذْكُرْ «يَوْم تَرى المُؤْمِنِينَ والمُؤْمِنات يَسْعى نُورهمْ بَيْن أيْدِيهمْ» أمامهمْ «و» يَكُون «بِأَيْمانِهِمْ» ويُقال لَهُمْ: «بُشْراكُمْ اليَوْم جَنّات» أيْ اُدْخُلُوها", "malayalam": "«സത്യവിശ്വാസികളെയും സത്യവിശ്വാസിനികളെയും അവരുടെ പ്രകാശം അവരുടെ മുന്നിലും വലതുഭാഗങ്ങളിലും പ്രസരിച്ചുകൊണ്ടിരിക്കുന്നതായി നീ കാണുന്ന ദിവസം! ഇന്ന് നിങ്ങൾക്ക് താഴെ അരുവികൾ ഒഴുകുന്ന സ്വർഗ്ഗത്തോപ്പുകളാണ് സന്തോഷവാർത്ത; അതിൽ അവർ ശാശ്വതരായിരിക്കും; അതത്രെ മഹത്തായ വിജയം!».", "malayalamMatn": "സത്യവിശ്വാസികളെയും സത്യവിശ്വാസിനികളെയും, അവരുടെ പ്രകാശം അവരുടെ മുന്‍ഭാഗങ്ങളിലൂടെയും വലതുഭാഗങ്ങളിലൂടെയും സഞ്ചരിക്കുന്ന നിലയില്‍ നീ കാണുന്ന ദിവസം! (അന്നവരോട് പറയപ്പെടും:) ഇന്നു നിങ്ങള്‍ക്കുള്ള സന്തോഷവാര്‍ത്ത ചില സ്വര്‍ഗത്തോപ്പുകളെ പറ്റിയാകുന്നു. അവയുടെ താഴ്ഭാഗത്തു കൂടി അരുവികള്‍ ഒഴുകികൊണ്ടിരിക്കും. നിങ്ങള്‍ അതില്‍ നിത്യവാസികളായിരിക്കും. അത് മഹത്തായ ഭാഗ്യം തന്നെയാണ്‌."}, {"ayahNumber": 13, "quranText": "یَوۡمَ یَقُولُ ٱلۡمُنَـٰفِقُونَ وَٱلۡمُنَـٰفِقَـٰتُ لِلَّذِینَ ءَامَنُوا۟ ٱنظُرُونَا نَقۡتَبِسۡ مِن نُّورِكُمۡ قِیلَ ٱرۡجِعُوا۟ وَرَاۤءَكُمۡ فَٱلۡتَمِسُوا۟ نُورࣰاۖ فَضُرِبَ بَیۡنَهُم بِسُورࣲ لَّهُۥ بَابُۢ بَاطِنُهُۥ فِیهِ ٱلرَّحۡمَةُ وَظَـٰهِرُهُۥ مِن قِبَلِهِ ٱلۡعَذَابُ\n", "jalalayn": "«يَوْم يَقُول المُنافِقُونَ والمُنافِقات لِلَّذِينَ آمَنُوا اُنْظُرُونا» أبْصِرُونا وفِي قِراءَة بِفَتْحِ الهَمْزَة وكَسْر الظّاء: أمْهِلُونا «نَقْتَبِس» نَأْخُذ القَبَس والإضاءَة «مِن نُوركُمْ قِيلَ» \"لَهُمْ اسْتِهْزاء بِهِمْ «رْجِعُوا وراءَكُمْ فالتَمِسُوا نُورًا» فَرَجَعُوا «فَضُرِبَ بَيْنهمْ» وبَيْن المُؤْمِنِينَ «بِسُورٍ» قِيلَ هُوَ سُور الأَعْراف «لَهُ باب باطِنه فِيهِ الرَّحْمَة» مِن جِهَة المُؤْمِنِينَ «وظاهِره» مِن جِهَة المُنافِقِينَ", "malayalam": "«കപടവിശ്വാസികളും കപടവിശ്വാസിനികളും സത്യവിശ്വാസികളോട് പറയും: നിങ്ങൾ ഞങ്ങളെയൊന്ന് കാത്തുനിൽക്കൂ, നിങ്ങളുടെ പ്രകാശത്തിൽ നിന്ന് ഞങ്ങൾ അല്പം വെളിച്ചമെടുക്കട്ടെ! അപ്പോൾ അവരോട് പറയപ്പെടും: നിങ്ങൾ നിങ്ങളുടെ പിന്നിലേക്ക് തന്നെ മടങ്ങിപ്പോയി പ്രകാശം അന്വേഷിച്ചുകൊള്ളുക! അങ്ങനെ അവർക്കിടയിൽ ഒരു മതിൽ സ്ഥാപിക്കപ്പെടും; അതിനൊരു വാതിലുണ്ടായിരിക്കും; അതിന്റെ ഉൾഭാഗത്ത് കാരുണ്യവും പുറംഭാഗത്ത് ശിക്ഷയുമായിരിക്കും».", "malayalamMatn": "കപടവിശ്വാസികളും കപടവിശ്വാസിനികളും സത്യവിശ്വാസികളോട് (ഇങ്ങനെ) പറയുന്ന ദിവസം: നിങ്ങള്‍ ഞങ്ങളെ നോക്കണേ! നിങ്ങളുടെ പ്രകാശത്തില്‍ നിന്ന് ഞങ്ങള്‍ പകര്‍ത്തി എടുക്കട്ടെ. (അപ്പോള്‍ അവരോട്‌) പറയപ്പെടും: നിങ്ങള്‍ നിങ്ങളുടെ പിന്‍ഭാഗത്തേക്കു തന്നെ മടങ്ങിപ്പോകുക. എന്നിട്ട് പ്രകാശം അന്വേഷിച്ചു കൊള്ളുക! അപ്പോള്‍ അവര്‍ക്കിടയില്‍ ഒരു മതില്‍ കൊണ്ട് മറയുണ്ടാക്കപ്പെടുന്നതാണ്‌. അതിന് ഒരു വാതിലുണ്ടായിരിക്കും. അതിന്‍റെ ഉള്‍ഭാഗത്താണ് കാരുണ്യമുള്ളത്‌. അതിന്‍റെ പുറഭാഗത്താകട്ടെ ശിക്ഷയും."}, {"ayahNumber": 14, "quranText": "یُنَادُونَهُمۡ أَلَمۡ نَكُن مَّعَكُمۡۖ قَالُوا۟ بَلَىٰ وَلَـٰكِنَّكُمۡ فَتَنتُمۡ أَنفُسَكُمۡ وَتَرَبَّصۡتُمۡ وَٱرۡتَبۡتُمۡ وَغَرَّتۡكُمُ ٱلۡأَمَانِیُّ حَتَّىٰ جَاۤءَ أَمۡرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلۡغَرُورُ\n", "jalalayn": "«يُنادُونَهُمْ ألَمْ نَكُنْ مَعَكُمْ» عَلى الطّاعَة «قالُوا بَلى ولَكِنَّكُمْ فَتَنْتُمْ أنْفُسكُمْ» بِالنِّفاقِ «وتَرَبَّصْتُمْ» بِالمُؤْمِنِينَ الدَّوائِر «وارْتَبْتُمْ» شَكَكْتُمْ فِي دِين الإسْلام «وغَرَّتْكُمْ الأَمانِيّ» الأَطْماع «حَتّى جاءَ أمْر اللَّه» المَوْت «وغَرَّكُمْ بِاللَّهِ الغَرُور» الشَّيْطان", "malayalam": "«കപടവിശ്വാസികൾ അവരെ വിളിച്ച് ചോദിക്കും: ഞങ്ങൾ നിങ്ങളുടെ കൂടെത്തന്നെയല്ലായിരുന്നോ? വിശ്വാസികൾ പറയും: അതെ, എന്നാൽ നിങ്ങൾ സ്വന്തം ശരീരങ്ങളെ സ്വയം കുഴപ്പത്തിലാക്കി; നിങ്ങൾ സത്യവിശ്വാസികൾക്ക് നാശം കാത്തിരുന്നു, നിങ്ങൾ സംശയിച്ചു; വ്യാമോഹങ്ങൾ നിങ്ങളെ വഞ്ചിച്ചു; അങ്ങനെ അല്ലാഹുവിന്റെ കൽപന വന്നെത്തി; ആ വഞ്ചകൻ (പിശാച്) അല്ലാഹുവിന്റെ കാര്യത്തിൽ നിങ്ങളെ വഞ്ചിച്ചുകളഞ്ഞു».", "malayalamMatn": "അവരെ (സത്യവിശ്വാസികളെ) വിളിച്ച് അവര്‍ (കപടന്‍മാര്‍) പറയും: ഞങ്ങള്‍ നിങ്ങളോടൊപ്പമായിരുന്നില്ലേ? അവര്‍ (സത്യവിശ്വാസികള്‍) പറയും: അതെ; പക്ഷെ, നിങ്ങള്‍ നിങ്ങളെ തന്നെ കുഴപ്പത്തിലാക്കുകയും (മറ്റുള്ളവര്‍ക്ക് നാശം വരുന്നത്‌) പാര്‍ത്തുകൊണ്ടിരിക്കുകയും (മതത്തില്‍) സംശയിക്കുകയും അല്ലാഹുവിന്‍റെ ആജ്ഞ വന്നെത്തുന്നത് വരെ വ്യാമോഹങ്ങള്‍ നിങ്ങളെ വഞ്ചിക്കുകയും ചെയ്തു. അല്ലാഹുവിന്‍റെ കാര്യത്തില്‍ പരമവഞ്ചകനായ പിശാച് നിങ്ങളെ വഞ്ചിച്ചു കളഞ്ഞു."}, {"ayahNumber": 15, "quranText": "فَٱلۡیَوۡمَ لَا یُؤۡخَذُ مِنكُمۡ فِدۡیَةࣱ وَلَا مِنَ ٱلَّذِینَ كَفَرُوا۟ۚ مَأۡوَىٰكُمُ ٱلنَّارُۖ هِیَ مَوۡلَىٰكُمۡۖ وَبِئۡسَ ٱلۡمَصِیرُ\n", "jalalayn": "«فاليَوْم لا يُؤْخَذ» بِالياءِ والتّاء «مِنكُمْ فِدْيَة ولا مِن الَّذِينَ كَفَرُوا مَأْواكُمْ النّار هِيَ مَوْلاكُمْ» أوْلى بِكُمْ «وبِئْسَ المَصِير» هِيَ", "malayalam": "«അതിനാൽ ഇന്ന് നിങ്ങളുടെ പക്കൽ നിന്നോ അവിശ്വാസികളുടെ പക്കൽ നിന്നോ യാതൊരു പ്രായശ്ചിത്തവും സ്വീകരിക്കപ്പെടുന്നതല്ല; നിങ്ങളുടെ സങ്കേതം നരകമാകുന്നു; അതത്രെ നിങ്ങളുടെ മിത്രം; അത് എത്രയോ ചീത്തയായ തിരിച്ചുവരവ്!».", "malayalamMatn": "അതുകൊണ്ട് ഇന്ന് നിങ്ങളുടെ പക്കല്‍ നിന്നോ സത്യനിഷേധികളുടെ പക്കല്‍ നിന്നോ യാതൊരു പ്രായശ്ചിത്തവും സ്വീകരിക്കപ്പെടുന്നതല്ല. നിങ്ങളുടെ വാസസ്ഥലം നരകമാകുന്നു. അതത്രെ നിങ്ങളുടെ ബന്ധു തിരിച്ചുചെല്ലാനുള്ള ആ സ്ഥലം വളരെ ചീത്ത തന്നെ."}, {"ayahNumber": 16, "quranText": "۞ أَلَمۡ یَأۡنِ لِلَّذِینَ ءَامَنُوۤا۟ أَن تَخۡشَعَ قُلُوبُهُمۡ لِذِكۡرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلۡحَقِّ وَلَا یَكُونُوا۟ كَٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ مِن قَبۡلُ فَطَالَ عَلَیۡهِمُ ٱلۡأَمَدُ فَقَسَتۡ قُلُوبُهُمۡۖ وَكَثِیرࣱ مِّنۡهُمۡ فَـٰسِقُونَ\n", "jalalayn": "«ألَمْ يَأْنِ» يَحِنْ «لِلَّذِينَ آمَنُوا» نَزَلَتْ فِي شَأْن الصَّحابَة لَمّا أكْثَرُوا المِزاح «أنْ تَخْشَع قُلُوبهمْ لِذِكْرِ اللَّه وما نَزَّلَ» بِالتَّشْدِيدِ والتَّخْفِيف «مِن الحَقّ» القُرْآن «ولا يَكُونُوا» مَعْطُوف عَلى تَخْشَع «كالَّذِينَ أُوتُوا الكِتاب مِن قَبْل» هُمْ اليَهُود والنَّصارى «فَطالَ عَلَيْهِمْ الأَمَد» الزَّمَن بَيْنهمْ وبَيْن أنْبِيائِهِمْ «فَقَسَتْ قُلُوبهمْ» لَمْ تَلِنْ لِذِكْرِ اللَّه", "malayalam": "«സത്യവിശ്വാസികൾക്ക് അവരുടെ ഹൃദയങ്ങൾ അല്ലാഹുവിന്റെ സ്മരണയിലേക്കും അവതരിച്ച സത്യത്തിലേക്കും ഭയഭക്തിയോടെ വഴങ്ങാൻ സമയമായില്ലേ? (സ്വഹാബികൾ പരസ്പരം തമാശകൾ വർദ്ധിപ്പിച്ച സന്ദർഭത്തിൽ ഇത് അവതരിച്ചു). മുമ്പ് വേദഗ്രന്ഥം നൽകപ്പെട്ടവരെപ്പോലെ അവർ ആകരുത്; അങ്ങനെ അവർക്ക് കാലം ദീർഘിച്ചുപോയപ്പോൾ അവരുടെ ഹൃദയങ്ങൾ കടുത്തുപോയി; അവരിൽ അധികപേരും അധർമ്മകാരികളാകുന്നു».", "malayalamMatn": "വിശ്വാസികള്‍ക്ക് അവരുടെ ഹൃദയങ്ങള്‍ അല്ലാഹുവിനെ പറ്റിയുള്ള സ്മരണയിലേക്കും, അവതരിച്ചു കിട്ടിയ സത്യത്തിലേക്കും കീഴൊതുങ്ങുവാനും തങ്ങള്‍ക്ക് മുമ്പ് വേദഗ്രന്ഥം നല്‍കപ്പെട്ടവരെപ്പോലെ ആകാതിരിക്കുവാനും സമയമായില്ലേ? അങ്ങനെ ആ വേദക്കാര്‍ക്ക് കാലം ദീര്‍ഘിച്ച് പോകുകയും തന്‍മൂലം അവരുടെ ഹൃദയങ്ങള്‍ കടുത്തുപോകുകയും ചെയ്തു. അവരില്‍ അധികമാളുകളും ദുര്‍മാര്‍ഗികളാകുന്നു."}, {"ayahNumber": 17, "quranText": "ٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ یُحۡیِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ قَدۡ بَیَّنَّا لَكُمُ ٱلۡـَٔایَـٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ\n", "jalalayn": "«اعْلَمُوا» خِطاب لِلْمُؤْمِنِينَ المَذْكُورِينَ «أنَّ اللَّه يُحْيِي الأَرْض بَعْد مَوْتها» بِالنَّباتِ فَكَذَلِكَ يَفْعَل بِقُلُوبِكُمْ يَرُدّها إلى الخُشُوع «قَدْ بَيَّنّا لَكُمْ الآيات» الدّالَّة عَلى قُدْرَتنا بِهَذا وغَيْره", "malayalam": "«ഭൂമി നിർജ്ജീവമായതിന് ശേഷം അല്ലാഹു അതിനെ ജീവിപ്പിക്കുന്നു എന്ന് നിങ്ങൾ അറിഞ്ഞുകൊള്ളുക; നിങ്ങൾ ചിന്തിച്ചു ഗ്രഹിക്കുവാൻ വേണ്ടി നാം ദൃഷ്ടാന്തങ്ങൾ വിശദീകരിച്ചു തന്നിരിക്കുന്നു».", "malayalamMatn": "നിങ്ങള്‍ അറിഞ്ഞു കൊള്ളുക: തീര്‍ച്ചയായും അല്ലാഹു ഭൂമിയെ അത് നിര്‍ജീവമായതിനു ശേഷം സജീവമാക്കുന്നു. തീര്‍ച്ചയായും നാം നിങ്ങള്‍ക്ക് ദൃഷ്ടാന്തങ്ങള്‍ വിവരിച്ചുതന്നിരിക്കുന്നു. നിങ്ങള്‍ ചിന്തിക്കുവാന്‍ വേണ്ടി."}, {"ayahNumber": 18, "quranText": "إِنَّ ٱلۡمُصَّدِّقِینَ وَٱلۡمُصَّدِّقَـٰتِ وَأَقۡرَضُوا۟ ٱللَّهَ قَرۡضًا حَسَنࣰا یُضَـٰعَفُ لَهُمۡ وَلَهُمۡ أَجۡرࣱ كَرِیمࣱ\n", "jalalayn": "«إنّ المُصَّدِّقِينَ» مِن التَّصَدُّق أُدْغِمَتْ التّاء فِي الصّاد أيْ الَّذِينَ تَصَدَّقُوا «والمُصَّدِّقات» اللّاتِي تَصَدَّقْنَ وفِي قِراءَة بِتَخْفِيفِ الصّاد فِيهِما مِن التَّصْدِيق والإيمان «وأَقْرَضُوا اللَّه قَرْضًا حَسَنًا» راجِع إلى الذُّكُور والإناث بِالتَّغْلِيبِ وعَطَفَ الفِعْل عَلى الِاسْم فِي صِلَة ألْ لِأَنَّهُ فِيها حَلَّ مَحَلّ الفِعْل وذَكَرَ القَرْض بِوَصْفِهِ بَعْد التَّصَدُّق تَقْيِيد لَهُ «يُضاعَف» وفِي قِراءَة يُضَعِّف بِالتَّشْدِيدِ أيْ قَرْضهمْ", "malayalam": "«തീർച്ചയായും ദാനധർമ്മങ്ങൾ ചെയ്യുന്ന പുരുഷന്മാർക്കും സ്ത്രീകൾക്കും, അല്ലാഹുവിന് ഉത്തമമായ കടം നൽകിയവർക്കും അത് ഇരട്ടിയാക്കപ്പെടും; അവർക്ക് മാന്യമായ പ്രതിഫലവുമുണ്ട്».", "malayalamMatn": "തീര്‍ച്ചയായും ധര്‍മ്മിഷ്ഠരായ പുരുഷന്‍മാരും സ്ത്രീകളും അല്ലാഹുവിന് നല്ല കടം കൊടുത്തവരും ആരോ അവര്‍ക്കത് ഇരട്ടിയായി നല്‍കപ്പെടുന്നതാണ്‌. അവര്‍ക്കത്രെ മാന്യമായ പ്രതിഫലമുള്ളത്‌."}, {"ayahNumber": 19, "quranText": "وَٱلَّذِینَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦۤ أُو۟لَـٰۤىِٕكَ هُمُ ٱلصِّدِّیقُونَۖ وَٱلشُّهَدَاۤءُ عِندَ رَبِّهِمۡ لَهُمۡ أَجۡرُهُمۡ وَنُورُهُمۡۖ وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَحِیمِ\n", "jalalayn": "«والَّذِينَ آمَنُوا بِاللَّهِ ورُسُله أُولَئِكَ هُمْ الصِّدِّيقُونَ» المُبالِغُونَ فِي التَّصْدِيق «والشُّهَداء عِنْد رَبّهمْ» عَلى المُكَذِّبِينَ مِن الأُمَم «لَهُمْ أجْرهمْ ونُورهمْ والَّذِينَ كَفَرُوا وكَذَّبُوا بِآياتِنا» الدّالَّة عَلى وحْدانِيّتنا «أُولَئِكَ أصْحاب الجَحِيم» النّار", "malayalam": "«അല്ലാഹുവിലും അവന്റെ റസൂലിലും വിശ്വസിച്ചവരാരോ അവരത്രെ തങ്ങളുടെ രക്ഷിതാവിങ്കൽ സിദ്ദീഖീങ്ങളും (സത്യസന്ധരും) ശുഹദാക്കളും (രക്തസാക്ഷികളും); അവർക്ക് അവരുടെ പ്രതിഫലവും അവരുടെ പ്രകാശവുമുണ്ട്; എന്നാൽ അവിശ്വസിക്കുകയും നമ്മുടെ ദൃഷ്ടാന്തങ്ങളെ നിഷേധിക്കുകയും ചെയ്തവർ നരകാവകാശികളാകുന്നു».", "malayalamMatn": "എന്നാല്‍ അല്ലാഹുവിലും അവന്‍റെ ദൂതന്‍മാരിലും വിശ്വസിച്ചവരാരോ അവര്‍ തന്നെയാണ് തങ്ങളുടെ രക്ഷിതാവിങ്കല്‍ സത്യസന്ധന്‍മാരും സത്യസാക്ഷികളും. അവര്‍ക്ക് അവരുടെ പ്രതിഫലവും അവരുടെ പ്രകാശവുമുണ്ടായിരിക്കും. സത്യനിഷേധം കൈക്കൊള്ളുകയും നമ്മുടെ ദൃഷ്ടാന്തങ്ങളെ നിഷേധിച്ചു തള്ളുകയും ചെയ്തവരാരോ അവര്‍ തന്നെയാണ് നരകക്കാര്‍."}, {"ayahNumber": 20, "quranText": "ٱعۡلَمُوۤا۟ أَنَّمَا ٱلۡحَیَوٰةُ ٱلدُّنۡیَا لَعِبࣱ وَلَهۡوࣱ وَزِینَةࣱ وَتَفَاخُرُۢ بَیۡنَكُمۡ وَتَكَاثُرࣱ فِی ٱلۡأَمۡوَ ٰ⁠لِ وَٱلۡأَوۡلَـٰدِۖ كَمَثَلِ غَیۡثٍ أَعۡجَبَ ٱلۡكُفَّارَ نَبَاتُهُۥ ثُمَّ یَهِیجُ فَتَرَىٰهُ مُصۡفَرࣰّا ثُمَّ یَكُونُ حُطَـٰمࣰاۖ وَفِی ٱلۡـَٔاخِرَةِ عَذَابࣱ شَدِیدࣱ وَمَغۡفِرَةࣱ مِّنَ ٱللَّهِ وَرِضۡوَ ٰ⁠نࣱۚ وَمَا ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۤ إِلَّا مَتَـٰعُ ٱلۡغُرُورِ\n", "jalalayn": "«اعْلَمُوا أنَّما الحَياة الدُّنْيا لَعِب ولَهْو وزِينَة» تَزْيِين «وتَفاخُر بَيْنكُمْ وتَكاثُر فِي الأَمْوال والأَوْلاد» أيْ الِاشْتِغال فِيها وأَمّا الطّاعات وما يُعِين عَلَيْها فَمِن أُمُور الآخِرَة «كَمَثَلِ» أيْ هِيَ فِي إعْجابها لَكُمْ واضْمِحْلالها كَمَثَلِ «غَيْث» مَطَر «أعْجَبَ الكُفّار» الزُّرّاع «نَباته» النّاشِئ عَنْهُ «ثُمَّ يَهِيج» يَيْبَس «فَتَراهُ مُصْفَرًّا ثُمَّ يَكُون حُطامًا» فُتاتًا يَضْمَحِلّ بِالرِّياحِ «وفِي الآخِرَة عَذاب شَدِيد» لِمَن آثَرَ عَلَيْها الدُّنْيا «ومَغْفِرَة مِن اللَّه ورِضْوان» لِمَن لَمْ يُؤْثِر عَلَيْها الدُّنْيا «وما الحَياة الدُّنْيا» ما التَّمَتُّع فِيها", "malayalam": "«ഐഹികജീവിതം കേവലം കളിയും വിനോദവും അലങ്കാരവും നിങ്ങൾ പരസ്പരം അഹങ്കരിക്കുന്നതും സ്വത്തിലും സന്താനങ്ങളിലും പെരുപ്പം കാണിച്ച് മത്സരിക്കുന്നതും മാത്രമാണെന്ന് നിങ്ങൾ അറിഞ്ഞുകൊള്ളുക; ഒരു മഴ പെയ്ത് മുളച്ചുവന്ന ചെടികൾ കർഷകരെ സന്തോഷിപ്പിച്ചു; പിന്നീട് അത് ഉണങ്ങി മഞ്ഞനിറമായി വൈക്കോൽത്തുണ്ടുകളായി മാറുന്നതുപോലെയാണത്; എന്നാൽ പരലോകത്തിൽ കഠിനമായ ശിക്ഷയും, അല്ലാഹുവിങ്കൽ നിന്നുള്ള പാപമോചനവും പ്രീതിയും ഉണ്ട്; ഐഹികജീവിതം ചതിക്കുന്ന വിഭവമല്ലാതെ മറ്റൊന്നുമല്ല».", "malayalamMatn": "നിങ്ങള്‍ അറിയുക: ഇഹലോകജീവിതമെന്നാല്‍ കളിയും വിനോദവും അലങ്കാരവും നിങ്ങള്‍ പരസ്പരം ദുരഭിമാനം നടിക്കലും സ്വത്തുകളിലും സന്താനങ്ങളിലും പെരുപ്പം കാണിക്കലും മാത്രമാണ്‌- ഒരു മഴ പോലെ. അതു മൂലമുണ്ടായ ചെടികള്‍ കര്‍ഷകരെ ആശ്ചര്യപ്പെടുത്തി. പിന്നീടതിന് ഉണക്കം ബാധിക്കുന്നു. അപ്പോള്‍ അത് മഞ്ഞനിറം പൂണ്ടതായി നിനക്ക് കാണാം. പിന്നീടതു തുരുമ്പായിപ്പോകുന്നു. എന്നാല്‍ പരലോകത്ത് (ദുര്‍വൃത്തര്‍ക്ക്‌) കഠിനമായ ശിക്ഷയും (സദ്‌വൃത്തര്‍ക്ക്‌) അല്ലാഹുവിങ്കല്‍ നിന്നുള്ള പാപമോചനവും പ്രീതിയും ഉണ്ട്‌. ഐഹികജീവിതം വഞ്ചനയുടെ വിഭവമല്ലാതെ മറ്റൊന്നുമല്ല."}, {"ayahNumber": 21, "quranText": "سَابِقُوۤا۟ إِلَىٰ مَغۡفِرَةࣲ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا كَعَرۡضِ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِ أُعِدَّتۡ لِلَّذِینَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦۚ ذَ ٰ⁠لِكَ فَضۡلُ ٱللَّهِ یُؤۡتِیهِ مَن یَشَاۤءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ\n", "jalalayn": "«سابِقُوا إلى مَغْفِرَة مِن رَبّكُمْ وجَنَّة عَرْضها كَعَرْضِ السَّماء والأَرْض» لَوْ وُصِلَتْ إحْداهُما بِالأُخْرى والعَرْض: السَّعَة", "malayalam": "«നിങ്ങളുടെ രക്ഷിതാവിങ്കൽ നിന്നുള്ള പാപമോചനത്തിലേക്കും ആകാശഭൂമികളോളം വിശാലമായ സ്വർഗ്ഗത്തിലേക്കും നിങ്ങൾ മുൻകടന്നു മത്സരിക്കുവിൻ; അല്ലാഹുവിലും അവന്റെ റസൂലിലും വിശ്വസിച്ചവർക്കായി അത് ഒരുക്കിവെക്കപ്പെട്ടിരിക്കുന്നു; അത് അല്ലാഹുവിന്റെ ഔദാര്യമാകുന്നു, അവൻ ഉദ്ദേശിക്കുന്നവർക്ക് അവൻ അത് നൽകുന്നു; അല്ലാഹു മഹത്തായ ഔദാര്യത്തിന്റെ ഉടമയാകുന്നു».", "malayalamMatn": "നിങ്ങളുടെ രക്ഷിതാവിങ്കല്‍ നിന്നുള്ള പാപമോചനത്തിലേക്കും സ്വര്‍ഗത്തിലേക്കും നിങ്ങള്‍ മുങ്കടന്നു വരുവിന്‍. അതിന്‍റെ വിസ്താരം ആകാശത്തിന്‍റെയും ഭൂമിയുടെയും വിസ്താരം പോലെയാണ്‌. അല്ലാഹുവിലും അവന്‍റെ ദൂതന്‍മാരിലും വിശ്വസിച്ചവര്‍ക്കു വേണ്ടി അത് സജ്ജീകരിക്കപ്പെട്ടിരിക്കുന്നു. അത് അല്ലാഹുവിന്‍റെ അനുഗ്രഹമത്രെ. അവന്‍ ഉദ്ദേശിക്കുന്നവര്‍ക്ക് അതവന്‍ നല്‍കുന്നു. അല്ലാഹു മഹത്തായ അനുഗ്രഹമുള്ളവനാകുന്നു."}, {"ayahNumber": 22, "quranText": "مَاۤ أَصَابَ مِن مُّصِیبَةࣲ فِی ٱلۡأَرۡضِ وَلَا فِیۤ أَنفُسِكُمۡ إِلَّا فِی كِتَـٰبࣲ مِّن قَبۡلِ أَن نَّبۡرَأَهَاۤۚ إِنَّ ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣱ\n", "jalalayn": "«ما أصابَ مِن مُصِيبَة فِي الأَرْض» بِالجَدْبِ «ولا فِي أنْفُسكُمْ» كالمَرَضِ وفَقْد الوَلَد «إلّا فِي كِتاب» يَعْنِي اللَّوْح المَحْفُوظ «مِن قَبْل أنْ نَبْرَأها» نَخْلُقها ويُقال فِي النِّعْمَة كَذَلِكَ", "malayalam": "«ഭൂമിയിലോ നിങ്ങളുടെ സ്വന്തം ശരീരങ്ങളിലോ യാതൊരു വിപത്തും ബാധിക്കുകയുണ്ടായിട്ടില്ല, നാം അതിനെ സൃഷ്ടിക്കുന്നതിന് മുമ്പ് തന്നെ ഒരു രേഖയിൽ അത് കുറിക്കപ്പെട്ടിട്ടല്ലാതെ; തീർച്ചയായും അത് അല്ലാഹുവിന് വളരെ എളുപ്പമുള്ള കാര്യമാകുന്നു».", "malayalamMatn": "ഭൂമിയിലോ നിങ്ങളുടെ ദേഹങ്ങളില്‍ തന്നെയോ യാതൊരു ആപത്തും ബാധിക്കുകയുണ്ടായിട്ടില്ല; അതിനെ നാം ഉണ്ടാക്കുന്നതിന് മുമ്പ് തന്നെ ഒരു രേഖയില്‍ ഉള്‍പെട്ടുകഴിഞ്ഞതായിട്ടല്ലാതെ. തീര്‍ച്ചയായും അത് അല്ലാഹുവെ സംബന്ധിച്ചേടത്തോളം എളുപ്പമുള്ളതാകുന്നു."}, {"ayahNumber": 23, "quranText": "لِّكَیۡلَا تَأۡسَوۡا۟ عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُوا۟ بِمَاۤ ءَاتَىٰكُمۡۗ وَٱللَّهُ لَا یُحِبُّ كُلَّ مُخۡتَالࣲ فَخُورٍ\n", "jalalayn": "«لِكَيْلا» كَيْ ناصِبَة لِلْفِعْلِ بِمَعْنى أنْ أيْ أخْبَرَ تَعالى بِذَلِكَ لِئَلّا «تَأْسَوْا» تَحْزَنُوا «عَلى ما فاتَكُمْ ولا تَفْرَحُوا» فَرَح بَطَر بَلْ فَرَح شُكْر عَلى النِّعْمَة «بِما آتاكُمْ» بِالمَدِّ أعْطاكُمْ وبِالقَصْرِ جاءَكُمْ مِنهُ «واللَّه لا يُحِبّ كُلّ مُخْتال» مُتَكَبِّر بِما أُوتِيَ «فَخُور» بِهِ عَلى النّاس", "malayalam": "«നിങ്ങൾക്ക് നഷ്ടപ്പെട്ടുപോയ കാര്യത്തിൽ നിങ്ങൾ ദുഃഖിക്കാതിരിക്കുവാനും അവൻ നൽകിയ സൗഭാഗ്യങ്ങളിൽ നിങ്ങൾ അഹങ്കരിക്കാതിരിക്കുവാനും വേണ്ടിയത്രെ അത്; അഹങ്കാരിയായ ദുരഭിമാനികളെ ആരെയും അല്ലാഹു ഇഷ്ടപ്പെടുന്നില്ല».", "malayalamMatn": "(ഇങ്ങനെ നാം ചെയ്തത്‌,) നിങ്ങള്‍ക്കു നഷ്ടപ്പെട്ടതിന്‍റെ പേരില്‍ നിങ്ങള്‍ ദുഃഖിക്കാതിരിക്കുവാനും, നിങ്ങള്‍ക്ക് അവന്‍ നല്‍കിയതിന്‍റെ പേരില്‍ നിങ്ങള്‍ ആഹ്ലാദിക്കാതിരിക്കുവാനും വേണ്ടിയാണ്‌. അല്ലാഹു യാതൊരു അഹങ്കാരിയെയും ദുരഭിമാനിയെയും ഇഷ്ടപ്പെടുകയില്ല."}, {"ayahNumber": 24, "quranText": "ٱلَّذِینَ یَبۡخَلُونَ وَیَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِۗ وَمَن یَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ\n", "jalalayn": "«الَّذِينَ يَبْخَلُونَ» بِما يَجِب عَلَيْهِمْ «ويَأْمُرُونَ النّاس بِالبُخْلِ» بِهِ لَهُمْ وعِيد شَدِيد «ومَن يَتَوَلَّ» عَمّا يَجِب عَلَيْهِ «فَإنَّ اللَّه هُوَ» ضَمِير فَصْل وفِي قِراءَة بِسُقُوطِهِ «الغَنِيّ» عَنْ غَيْره «الحَمِيد» لِأَوْلِيائِهِ", "malayalam": "«പിശുക്ക് കാണിക്കുകയും ജനങ്ങളോട് പിശുക്ക് കാണിക്കാൻ കൽപിക്കുകയും ചെയ്യുന്നവരാണവർ; ആരെങ്കിലും തിരിഞ്ഞുകളയുകയാണെങ്കിൽ തീർച്ചയായും അല്ലാഹു സർവ്വരുടെയും ആശ്രയങ്ങളിൽ നിന്ന് മുക്തനും സ്തുത്യർഹനുമാകുന്നു».", "malayalamMatn": "അതായത് പിശുക്ക് കാണിക്കുകയും, പിശുക്ക് കാണിക്കാന്‍ ജനങ്ങളോട് കല്‍പിക്കുകയും ചെയ്യുന്നവരെ. വല്ലവനും പിന്‍തിരിഞ്ഞ് പോകുകയാണെങ്കില്‍ തീര്‍ച്ചയായും അല്ലാഹു പരാശ്രയമുക്തനും സ്തുത്യര്‍ഹനുമത്രെ."}, {"ayahNumber": 25, "quranText": "لَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَیِّنَـٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَـٰبَ وَٱلۡمِیزَانَ لِیَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِیدَ فِیهِ بَأۡسࣱ شَدِیدࣱ وَمَنَـٰفِعُ لِلنَّاسِ وَلِیَعۡلَمَ ٱللَّهُ مَن یَنصُرُهُۥ وَرُسُلَهُۥ بِٱلۡغَیۡبِۚ إِنَّ ٱللَّهَ قَوِیٌّ عَزِیزࣱ\n", "jalalayn": "«لَقَدْ أرْسَلْنا رُسُلنا» المَلائِكَة إلى الأَنْبِياء «بِالبَيِّناتِ» بِالحِجَجِ القَواطِع «وأَنْزَلْنا مَعَهُمْ الكِتاب» بِمَعْنى الكُتُب «والمِيزان» العَدْل «لِيَقُومَ النّاس بِالقِسْطِ وأَنْزَلْنا الحَدِيد» أخَرَجْناهُ مِن المَعادِن «فِيهِ بَأْس شَدِيد» يُقاتِل بِهِ «ومَنافِع لِلنّاسِ ولِيَعْلَم اللَّه» عِلْم مُشاهَدَة مَعْطُوف عَلى لِيَقُومَ النّاس «مَن يَنْصُرهُ» بِأَنْ يَنْصُر دِينه بِآلاتِ الحَرْب مِن الحَدِيد وغَيْره «ورُسُله بِالغَيْبِ» حال مِن هاء يَنْصُرهُ أيْ غائِبًا عَنْهُمْ فِي الدُّنْيا قالَ ابْن عَبّاس: يَنْصُرُونَهُ ولا يُبْصِرُونَهُ «إنّ اللَّه قَوِيّ عَزِيز» لا حاجَة لَهُ إلى النُّصْرَة لَكِنَّها تَنْفَع مَن يَأْتِي بِها", "malayalam": "«തീർച്ചയായും നമ്മുടെ റസൂലുകളെ വ്യക്തമായ തെളിവുകളോടെ നാം അയക്കുകയുണ്ടായി; മനുഷ്യർ നീതിപൂർവ്വം നിലകൊള്ളുവാനായി വേദഗ്രന്ഥവും തുലാസ്സും നാം അവർക്കൊപ്പം ഇറക്കിക്കൊടുത്തു; നാം ഇരുമ്പും ഇറക്കിക്കൊടുത്തു, അതിൽ വലിയ ആയുധബലവും മനുഷ്യർക്ക് ഉപകാരങ്ങളുമുണ്ട്; അല്ലാഹുവിനെയും അവന്റെ റസൂലുകളെയും അദൃശ്യമായ നിലയിൽ സഹായിക്കുന്നത് ആരാണെന്ന് അല്ലാഹു അറിയുവാൻ വേണ്ടിയുമാണത്; തീർച്ചയായും അല്ലാഹു ശക്തനും പ്രതാപിയുമാകുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും നാം നമ്മുടെ ദൂതന്‍മാരെ വ്യക്തമായ ദൃഷ്ടാന്തങ്ങളും കൊണ്ട് അയക്കുകയുണ്ടായി. ജനങ്ങള്‍ നീതിപൂര്‍വ്വം നിലകൊള്ളുവാന്‍ വേണ്ടി അവരോടൊപ്പം വേദഗ്രന്ഥവും തുലാസും ഇറക്കികൊടുക്കുകയും ചെയ്തു. ഇരുമ്പും നാം ഇറക്കി കൊടുത്തു. അതില്‍ കഠിനമായ ആയോധന ശക്തിയും ജനങ്ങള്‍ക്ക് ഉപകാരങ്ങളുമുണ്ട്‌. അല്ലാഹുവിനെയും അവന്‍റെ ദൂതന്‍മാരെയും അദൃശ്യമായ നിലയില്‍ സഹായിക്കുന്നവരെ അവന്ന് അറിയാന്‍ വേണ്ടിയുമാണ് ഇതെല്ലാം. തീര്‍ച്ചയായും അല്ലാഹു ശക്തനും പ്രതാപിയുമാകുന്നു."}, {"ayahNumber": 26, "quranText": "وَلَقَدۡ أَرۡسَلۡنَا نُوحࣰا وَإِبۡرَ ٰ⁠هِیمَ وَجَعَلۡنَا فِی ذُرِّیَّتِهِمَا ٱلنُّبُوَّةَ وَٱلۡكِتَـٰبَۖ فَمِنۡهُم مُّهۡتَدࣲۖ وَكَثِیرࣱ مِّنۡهُمۡ فَـٰسِقُونَ\n", "jalalayn": "«ولَقَدْ أرْسَلْنا نُوحًا وإبْراهِيم وجَعَلْنا فِي ذُرِّيَّتهما النُّبُوَّة والكِتاب» يَعْنِي الكُتُب الأَرْبَعَة: التَّوْراة والإنْجِيل والزَّبُور والفُرْقان فَإنَّها فِي ذُرِّيَّة إبْراهِيم", "malayalam": "«തീർച്ചയായും നൂഹിനെയും ഇബ്രാഹീമിനെയും നാം ദൂതന്മാരായി അയച്ചു; അവരുടെ സന്തതികളിൽ നാം പ്രവാചകത്വവും വേദഗ്രന്ഥവും നിശ്ചയിച്ചു; അവരിൽ ചിലർ സന്മാർഗ്ഗം പ്രാപിച്ചവരാണ്; എന്നാൽ അവരിൽ ഭൂരിഭാഗവും അധർമ്മകാരികളാകുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും നാം നൂഹിനെയും ഇബ്രാഹീമിനെയും (ദൂതന്‍മാരായി) നിയോഗിച്ചു. അവര്‍ ഇരുവരുടെയും സന്തതികളില്‍ പ്രവാചകത്വവും വേദഗ്രന്ഥവും നാം ഏര്‍പെടുത്തുകയും ചെയ്തു. അങ്ങനെ അവരുടെ കൂട്ടത്തില്‍ സന്‍മാര്‍ഗം പ്രാപിച്ചവരുണ്ട്‌. അവരില്‍ അധികപേരും ദുര്‍മാര്‍ഗികളാകുന്നു."}, {"ayahNumber": 27, "quranText": "ثُمَّ قَفَّیۡنَا عَلَىٰۤ ءَاثَـٰرِهِم بِرُسُلِنَا وَقَفَّیۡنَا بِعِیسَى ٱبۡنِ مَرۡیَمَ وَءَاتَیۡنَـٰهُ ٱلۡإِنجِیلَۖ وَجَعَلۡنَا فِی قُلُوبِ ٱلَّذِینَ ٱتَّبَعُوهُ رَأۡفَةࣰ وَرَحۡمَةࣰۚ وَرَهۡبَانِیَّةً ٱبۡتَدَعُوهَا مَا كَتَبۡنَـٰهَا عَلَیۡهِمۡ إِلَّا ٱبۡتِغَاۤءَ رِضۡوَ ٰ⁠نِ ٱللَّهِ فَمَا رَعَوۡهَا حَقَّ رِعَایَتِهَاۖ فَـَٔاتَیۡنَا ٱلَّذِینَ ءَامَنُوا۟ مِنۡهُمۡ أَجۡرَهُمۡۖ وَكَثِیرࣱ مِّنۡهُمۡ فَـٰسِقُونَ\n", "jalalayn": "«ثُمَّ قَفَّيْنا عَلى آثارهمْ بِرُسُلِنا وقَفَّيْنا بِعِيسى ابْن مَرْيَم وآتَيْناهُ الإنْجِيل وجَعَلْنا فِي قُلُوب الَّذِينَ اتَّبَعُوهُ رَأْفَة ورَحْمَة ورَهْبانِيَّة» هِيَ رَفْض النِّساء واِتِّخاذ الصَّوامِع «ابْتَدَعُوها» مِن قِبَل أنْفُسهمْ «ما كَتَبْناها عَلَيْهِمْ» ما أمَرْناهُمْ بِها «إلّا» لَكِنْ فَعَلُوها «ابْتِغاء رِضْوان» مَرْضاة «اللَّه فَما رَعَوْها حَقّ رِعايَتها» إذْ تَرَكَها كَثِير مِنهُمْ وكَفَرُوا بِدِينِ عِيسى ودَخَلُوا فِي دِين مَلِكهمْ وبَقِيَ عَلى دِين عِيسى كَثِير مِنهُمْ فَآمَنُوا بِنَبِيِّنا «فَآتَيْنا الَّذِينَ آمَنُوا» بِهِ", "malayalam": "«പിന്നീട് അവരുടെ കാൽപ്പാടുകളെ തുടർന്ന് നമ്മുടെ ദൂതന്മാരെ നാം അയച്ചു; മർയമിന്റെ മകൻ ഈസായെയും നാം അയച്ചു, അദ്ദേഹത്തിന് നാം ഇഞ്ചീൽ നൽകി; അദ്ദേഹത്തെ പിന്തുടർന്നവരുടെ ഹൃദയങ്ങളിൽ നാം ദയയും കാരുണ്യവും നിശ്ചയിച്ചു; സന്യാസജീവിതം അവർ സ്വയം പുതുതായി ഉണ്ടാക്കിയതായിരുന്നു, അല്ലാഹുവിന്റെ പ്രീതി കാംക്ഷിക്കാനല്ലാതെ നാം അവർക്ക് അത് നിർബന്ധമാക്കിയിരുന്നില്ല; എന്നിട്ട് അവർ അത് പാലിക്കേണ്ട മുറപ്രകാരം പാലിച്ചതുമില്ല; എന്നാൽ അവരിൽ നിന്ന് വിശ്വസിച്ചവർക്ക് നാം പ്രതിഫലം നൽകി; അവരിൽ അധികപേരും തെമ്മാടികളാകുന്നു».", "malayalamMatn": "പിന്നീട് അവരുടെ പിന്നിലായി നാം നമ്മുടെ ദൂതന്‍മാരെ തുടര്‍ന്നയച്ചു. മര്‍യമിന്‍റെ മകന്‍ ഈസായെയും നാം തുടര്‍ന്നയച്ചു. അദ്ദേഹത്തിന് നാം ഇന്‍ജീല്‍ നല്‍കുകയും ചെയ്തു. അദ്ദേഹത്തെ പിന്‍പറ്റിയവരുടെ ഹൃദയങ്ങളില്‍ നാം കൃപയും കരുണയും ഉണ്ടാക്കി. സന്യാസജീവിതത്തെ അവര്‍ സ്വയം പുതുതായി നിര്‍മിച്ചു. അല്ലാഹുവിന്‍റെ പ്രീതി തേടേണ്ടതിന് (വേണ്ടി അവരതു ചെയ്തു) എന്നല്ലാതെ, നാം അവര്‍ക്കത് നിയമമാക്കിയിട്ടുണ്ടായിരുന്നില്ല. എന്നിട്ട് അവരത് പാലിക്കേണ്ട മുറപ്രകാരം പാലിച്ചതുമില്ല. അപ്പോള്‍ അവരുടെ കൂട്ടത്തില്‍ നിന്ന് വിശ്വസിച്ചവര്‍ക്ക് അവരുടെ പ്രതിഫലം നാം നല്‍കി. അവരില്‍ അധികപേരും ദുര്‍മാര്‍ഗികളാകുന്നു."}, {"ayahNumber": 28, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَءَامِنُوا۟ بِرَسُولِهِۦ یُؤۡتِكُمۡ كِفۡلَیۡنِ مِن رَّحۡمَتِهِۦ وَیَجۡعَل لَّكُمۡ نُورࣰا تَمۡشُونَ بِهِۦ وَیَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا» بِعِيسى «اتَّقُوا اللَّه وآمِنُوا بِرَسُولِهِ» مُحَمَّد ﷺ وعِيسى «يُؤْتِكُمْ كِفْلَيْنِ» نَصِيبَيْنِ «مِن رَحْمَته» لِإيمانِكُمْ بِالنَّبِيِّينَ «ويَجْعَل لَكُمْ نُورًا تَمْشُونَ بِهِ» عَلى الصِّراط", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുകയും അവന്റെ റസൂലിൽ വിശ്വസിക്കുകയും ചെയ്യുവിൻ; അവൻ തന്റെ കാരുണ്യത്തിൽ നിന്ന് നിങ്ങൾക്ക് ഇരട്ടി വിഹിതം നൽകും; നിങ്ങൾക്ക് നടക്കുവാനുതകുന്ന ഒരു പ്രകാശം അവൻ ഉണ്ടാക്കിത്തരികയും നിങ്ങൾക്ക് പാപങ്ങൾ പൊറുത്തുതരികയും ചെയ്യും; അല്ലാഹു ഏറെ പൊറുക്കുന്നവനും ദയാപരനുമാകുന്നു».", "malayalamMatn": "സത്യവിശ്വാസികളേ, നിങ്ങള്‍ അല്ലാഹുവെ സൂക്ഷിക്കുകയും അവന്‍റെ ദൂതനില്‍ വിശ്വസിക്കുകയും ചെയ്യുക. എന്നാല്‍ അവന്‍റെ കാരുണ്യത്തില്‍ നിന്നു രണ്ട് ഓഹരി അവന്‍ നിങ്ങള്‍ക്കു നല്‍കുന്നതാണ്‌. ഒരു പ്രകാശം അവന്‍ നിങ്ങള്‍ക്ക് ഏര്‍പെടുത്തിത്തരികയും ചെയ്യും. അതുകൊണ്ട് നിങ്ങള്‍ക്ക് (ശരിയായ പാതയിലൂടെ) നടന്നു പോകാം. നിങ്ങള്‍ക്കവന്‍ പൊറുത്തുതരികയും ചെയ്യും. അല്ലാഹു വളരെയധികം പൊറുക്കുന്നവനും കരുണാനിധിയുമാണ്‌."}, {"ayahNumber": 29, "quranText": "لِّئَلَّا یَعۡلَمَ أَهۡلُ ٱلۡكِتَـٰبِ أَلَّا یَقۡدِرُونَ عَلَىٰ شَیۡءࣲ مِّن فَضۡلِ ٱللَّهِ وَأَنَّ ٱلۡفَضۡلَ بِیَدِ ٱللَّهِ یُؤۡتِیهِ مَن یَشَاۤءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ\n", "jalalayn": "«لِئَلّا يَعْلَم» أيْ أعْلَمَكُمْ بِذَلِكَ لِيَعْلَم «أهْل الكِتاب» التَّوْراة الَّذِينَ لَمْ يُؤْمِنُوا بِمُحَمَّدٍ ﷺ «أنْ» مُخَفَّفَة مِن الثَّقِيلَة واسْمها ضَمِير الشَّأْن والمَعْنى أنَّهُمْ «لا يَقْدِرُونَ عَلى شَيْء مِن فَضْل اللَّه» خِلاف ما فِي زَعْمهمْ أنَّهُمْ أحِبّاء اللَّه وأَهْل رِضْوانه «وأَنَّ الفَضْل بِيَدِ اللَّه يُؤْتِيه» يُعْطِيه «مَن يَشاء» فَآتى المُؤْمِنِينَ مِنهُمْ أجْرهمْ مَرَّتَيْنِ كَما تَقَدَّمَ", "malayalam": "«വേദക്കാർ മനസ്സിലാക്കുവാൻ വേണ്ടിയത്രെ ഇത്; അല്ലാഹുവിന്റെ ഔദാര്യത്തിൽ നിന്ന് യാതൊന്നിന്റെ മേലും തങ്ങൾക്ക് അധികാരമില്ലെന്നും, ഔദാര്യം അല്ലാഹുവിന്റെ കയ്യിലാണെന്നും, അവൻ ഉദ്ദേശിക്കുന്നവർക്ക് അവൻ അത് നൽകുന്നുവെന്നും; അല്ലാഹു മഹത്തായ ഔദാര്യത്തിന്റെ ഉടമയാകുന്നു».", "malayalamMatn": "അല്ലാഹുവിന്‍റെ അനുഗ്രഹത്തില്‍ നിന്ന് യാതൊന്നും അധീനപ്പെടുത്തുവാന്‍ തങ്ങള്‍ക്ക് കഴിവില്ലെന്നും തീര്‍ച്ചയായും അനുഗ്രഹം അല്ലാഹുവിന്‍റെ കയ്യിലാണെന്നും അത് അവന്‍ ഉദ്ദേശിക്കുന്നവര്‍ക്ക് അവന്‍ നല്‍കുമെന്നും വേദക്കാര്‍ അറിയാന്‍ വേണ്ടിയാണ് ഇത്‌. അല്ലാഹു മഹത്തായ അനുഗ്രഹമുള്ളവനാകുന്നു."}], "topPoints": ["അല്ലാഹുവിന്റെ പ്രതാപവും സമ്പൂർണ്ണ അധികാരവും (خلاصة السورة)", "ദാനധർമ്മങ്ങളുടെ പ്രാധാന്യവും പ്രതിഫലവും"], "topQuestions": [{"q": "ഈ സൂറത്തിന്റെ പേര് ഇരുമ്പ് (ഹദീദ്) എന്നാകാൻ കാരണം?", "a": "ഇരുമ്പിലെ വലിയ ശക്തിയെയും മനുഷ്യർക്കുള്ള ഉപകാരങ്ങളെയും കുറിച്ച് ഇതിൽ പരാമർശിക്കുന്നു."}], "asbabAlNuzul": [{"ayahNumber": 7, "quranText": "ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُوا۟ مِمَّا جَعَلَكُم مُّسۡتَخۡلَفِینَ فِیهِۖ فَالَّذِینَ ءَامَنُوا۟ مِنكُمۡ وَأَنفَقُوا۟ لَهُمۡ أَجۡرࣱ كَبِیرࣱ", "arabicSnippet": "«آمِنُوا» داوَمُوا عَلى الإيمان «بِاللَّهِ ورَسُوله وأَنْفَقُوا» فِي سَبِيل اللَّه... نزل في غزوة العسرة وهي غزوة تبوك «فالذين آمنوا منكم وأنفقوا» إشارة إلى عثمان رضي الله عنه «لهم أجر كبير».", "malayalamExplanation": "തബൂക്ക് യുദ്ധവേളയിൽ (ഗസ്‌വത്തുൽ ഉസ്‌റ - പ്രയാസകരമായ ഘട്ടത്തിൽ) മുസ്‌ലിം സൈന്യത്തിന് വലിയ സാമ്പത്തിക സഹായം ആവശ്യമായി വന്നപ്പോൾ, ഉസ്മാൻ (റ) സൈന്യത്തിന്റെ മൂന്നിലൊന്ന് ഭാഗത്തിന് ആവശ്യമായ ഒട്ടകങ്ങളും കുതിരകളും വലിയ തോതിൽ സ്വർണ്ണനാണയങ്ങളും ധർമ്മം നൽകി സഹായിച്ചു. ഉസ്മാൻ (റ) വിന്റെ ഈ നിസ്വാർത്ഥ ത്യാഗത്തെ പ്രശംസിച്ചുകൊണ്ടും അല്ലാഹുവിങ്കൽ വലിയ പ്രതിഫലമുണ്ടെന്ന് വാഗ്ദാനം ചെയ്തുകൊണ്ടുമാണ് ഈ സൂക്തം അവതരിച്ചത്."}, {"ayahNumber": 16, "quranText": "۞ أَلَمۡ یَأۡنِ لِلَّذِینَ ءَامَنُوۤا۟ أَن تَخۡشَعَ قُلُوبُهُمۡ لِذِكۡرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلۡحَقِّ", "arabicSnippet": "«ألم يَأنِ» يَحِن «للذين آمنوا» نزلت في شأن الصحابة لما أكثروا المزاح «أن تخشع قلوبهم لذكر الله وما نزَّل من الحق...».", "malayalamExplanation": "മദീനയിലെ ജീവിതസൗകര്യങ്ങൾ വർദ്ധിച്ചപ്പോൾ ചില സ്വഹാബികൾക്കിടയിൽ തമാശകളും നേരമ്പോക്കുകളും അല്പം കൂടിയ സന്ദർഭമുണ്ടായി. ആ ഘട്ടത്തിൽ അവരുടെ ആത്മീയ ഉണർവിനായി, \"അല്ലാഹുവിന്റെ സ്മരണയിലേക്കും അവതരിച്ച സത്യത്തിലേക്കും സത്യവിശ്വാസികളുടെ ഹൃദയങ്ങൾ ഭയഭക്തിയോടെ അടിയറവ് വെക്കാൻ ഇനിയും സമയമായില്ലേ?\" എന്ന് ഗൗരവപൂർവ്വം ഉണർത്തിക്കൊണ്ട് ഈ സൂക്തം അവതരിച്ചു."}]}, {"surahNumber": 58, "surahNameArabic": "سُورَةُ المُجَادلَةِ", "surahNameMalayalam": "സൂറത്തുൽ മുജാദല (തർക്കിക്കുന്നവൾ)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ قَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّتِی تُجَـٰدِلُكَ فِی زَوۡجِهَا وَتَشۡتَكِیۤ إِلَى ٱللَّهِ وَٱللَّهُ یَسۡمَعُ تَحَاوُرَكُمَاۤۚ إِنَّ ٱللَّهَ سَمِیعُۢ بَصِیرٌ\n", "jalalayn": "«قَدْ سَمِعَ اللَّه قَوْل الَّتِي تُجادِلك» تُراجِعك أيّها النَّبِيّ «فِي زَوْجها» فِي زَوْجها المُظاهِر مِنها وكانَ قالَ لَها: أنْتِ عَلَيَّ كَظَهْرِ أُمِّي وقَدْ سَأَلَتْ النَّبِيّ ﷺ عَنْ ذَلِكَ فَأَجابَها بِأَنَّها حَرُمَتْ عَلَيْهِ عَلى ما هُوَ المَعْهُود عِنْدهمْ مِن أنَّ الظِّهار مُوجِبه فِرْقَة مُؤَبَّدَة وهِيَ خَوْلَة بِنْت ثَعْلَبَة وهُوَ أوْس بْن الصّامِت «وتَشْتَكِي إلى اللَّه» وحْدتها وفاقَتها وصَبِيَّة صِغارًا إنْ ضَمَّتْهُمْ إلَيْهِ ضاعُوا أوْ إلَيْها جاعُوا «واللَّه يَسْمَع تَحاوُركُما» تُراجِعكُما «إنّ اللَّه سَمِيع بَصِير» عالِم", "malayalam": "«തന്റെ ഭർത്താവിന്റെ കാര്യത്തിൽ നിന്നോട് തർക്കിക്കുകയും അല്ലാഹുവോട് സങ്കടം ബോധിപ്പിക്കുകയും ചെയ്യുന്ന സ്ത്രീയുടെ വാക്ക് അല്ലാഹു കേൾക്കുക തന്നെ ചെയ്തിരിക്കുന്നു» (ഖൗല ബിൻത് സഅ്‌ലബ തന്റെ ഭർത്താവ് ഔസ് ബിൻ സ്വാമിത് ളിഹാർ ചെയ്തതിനെപ്പറ്റി പരാതിപ്പെട്ടപ്പോൾ ഇത് അവതരിച്ചു). «നിങ്ങൾ തമ്മിലുള്ള സംഭാഷണം അല്ലാഹു കേൾക്കുന്നുണ്ടായിരുന്നു; തീർച്ചയായും അല്ലാഹു സർവ്വവും കേൾക്കുന്നവനും കാണുന്നവനുമാകുന്നു».", "malayalamMatn": "(നബിയേ,) തന്‍റെ ഭര്‍ത്താവിന്‍റെ കാര്യത്തില്‍ നിന്നോട് തര്‍ക്കിക്കുകയും അല്ലാഹുവിങ്കലേക്ക് സങ്കടം ബോധിപ്പിക്കുകയും ചെയ്യുന്നവളുടെ വാക്ക് അല്ലാഹു കേട്ടിട്ടുണ്ട്‌. അല്ലാഹു നിങ്ങള്‍ രണ്ടു പേരുടെയും സംഭാഷണം കേട്ടുകൊണ്ടിരിക്കുകയാണ്‌. തീര്‍ച്ചയായും അല്ലാഹു എല്ലാം കേള്‍ക്കുന്നവനും കാണുന്നവനുമാണ്‌."}, {"ayahNumber": 2, "quranText": "ٱلَّذِینَ یُظَـٰهِرُونَ مِنكُم مِّن نِّسَاۤىِٕهِم مَّا هُنَّ أُمَّهَـٰتِهِمۡۖ إِنۡ أُمَّهَـٰتُهُمۡ إِلَّا ٱلَّـٰۤـِٔی وَلَدۡنَهُمۡۚ وَإِنَّهُمۡ لَیَقُولُونَ مُنكَرࣰا مِّنَ ٱلۡقَوۡلِ وَزُورࣰاۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورࣱ\n", "jalalayn": "«الَّذِينَ يُظاهِرُونَ» أصْله يَتَظَهَّرُونَ أُدْغِمَتْ التّاء فِي الظّاء وفِي قِراءَة بِأَلِفٍ بَيْن الظّاء والهاء الخَفِيفَة وفِي أُخْرى كَيُقاتِلُونَ والمَوْضِع الثّانِي كَذَلِكَ «مِنكُمْ مِن نِسائِهِمْ ما هُنَّ أُمَّهاتهمْ إنْ أُمَّهاتهمْ إلّا اللّائِي» بِهَمْزَةٍ وياء وبِلا ياء «ولَدْنَهُمْ وإنَّهُمْ» بِالظِّهارِ «لَيَقُولُونَ مُنْكَرًا مِن القَوْل وزُورًا» كَذِبًا «وإنَّ اللَّه لَعَفُوّ غَفُور» لِلْمُظاهِرِ بِالكَفّارَةِ", "malayalam": "«നിങ്ങളിൽ നിന്ന് തങ്ങളുടെ ഭാര്യമാരോട് 'ളിഹാർ' ചെയ്യുന്നവർ (നീ എനിക്ക് എന്റെ മാതാവിന്റെ മുതുകിനെപ്പോലെയാണെന്ന് പറയുന്നവർ) അറിയുക: അവർ അവരുടെ മാതാക്കളല്ല; അവരെ പ്രസവിച്ചവർ മാത്രമാണ് അവരുടെ മാതാക്കൾ; തീർച്ചയായും അവർ പറയുന്നത് വെറുക്കപ്പെട്ടതും കളവുമായ വാക്കാണ്; തീർച്ചയായും അല്ലാഹു ഏറെ മാപ്പുനൽകുന്നവനും പൊറുക്കുന്നവനുമാകുന്നു».", "malayalamMatn": "നിങ്ങളുടെ കൂട്ടത്തില്‍ തങ്ങളുടെ ഭാര്യമാരെ മാതാക്കള്‍ക്ക് തുല്യമായി പ്രഖ്യാപിക്കുന്നവര്‍ (അബദ്ധമാകുന്നു ചെയ്യുന്നത്‌.) അവര്‍ (ഭാര്യമാര്‍) അവരുടെ മാതാക്കളല്ല. അവരുടെ മാതാക്കള്‍ അവരെ പ്രസവിച്ച സ്ത്രീകള്‍ അല്ലാതെ മറ്റാരുമല്ല. തീര്‍ച്ചയായും അവര്‍ നിഷിദ്ധമായ വാക്കും അസത്യവുമാണ് പറയുന്നത്‌. തീര്‍ച്ചയായും അല്ലാഹു അധികം മാപ്പുനല്‍കുന്നവനും പൊറുക്കുന്നവനുമാണ്‌."}, {"ayahNumber": 3, "quranText": "وَٱلَّذِینَ یُظَـٰهِرُونَ مِن نِّسَاۤىِٕهِمۡ ثُمَّ یَعُودُونَ لِمَا قَالُوا۟ فَتَحۡرِیرُ رَقَبَةࣲ مِّن قَبۡلِ أَن یَتَمَاۤسَّاۚ ذَ ٰ⁠لِكُمۡ تُوعَظُونَ بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ\n", "jalalayn": "«والَّذِينَ يُظاهِرُونَ مِن نِسائِهِمْ ثُمَّ يَعُودُونَ لِما قالُوا» أيْ فِيهِ بِأَنْ يُخالِفُوهُ بِإمْساكِ المُظاهِر مِنها الَّذِي هُوَ خِلاف مَقْصُود الظِّهار مِن وصْف المَرْأَة بِالتَّحْرِيمِ «فَتَحْرِير رِقْبَة» أيْ إعْتاقها عَلَيْهِ «مِن قَبْل أنْ يَتَماسّا» بِالوَطْءِ", "malayalam": "«ഭാര്യമാരോട് ളിഹാർ ചെയ്യുകയും പിന്നീട് പറഞ്ഞതിൽ നിന്ന് മടങ്ങുകയും ചെയ്യുന്നവർ പരസ്പരം സ്പർശിക്കുന്നതിന് മുമ്പായി ഒരു അടിമയെ മോചിപ്പിക്കേണ്ടതാണ്; നിങ്ങളോട് ഉപദേശിക്കപ്പെടുന്നത് അതത്രെ; നിങ്ങൾ പ്രവർത്തിക്കുന്നതിനെപ്പറ്റി അല്ലാഹു സൂക്ഷ്മമായി അറിയുന്നവനത്രെ».", "malayalamMatn": "തങ്ങളുടെ ഭാര്യമാരെ മാതാക്കള്‍ക്ക് തുല്യമായി പ്രഖ്യാപിക്കുകയും, പിന്നീട് തങ്ങള്‍ പറഞ്ഞതില്‍ നിന്ന് മടങ്ങുകയും ചെയ്യുന്നവര്‍, അവര്‍ പരസ്പരം സ്പര്‍ശിക്കുന്നതിനു മുമ്പായി ഒരു അടിമയെ മോചിപ്പിക്കേണ്ടതാണ്‌. അത് നിങ്ങള്‍ക്കു നല്‍കപ്പെടുന്ന ഉപദേശമാണ്‌. അല്ലാഹു നിങ്ങള്‍ പ്രവര്‍ത്തിക്കുന്നതിനെപ്പറ്റി സൂക്ഷ്മജ്ഞാനമുള്ളവനാകുന്നു."}, {"ayahNumber": 4, "quranText": "فَمَن لَّمۡ یَجِدۡ فَصِیَامُ شَهۡرَیۡنِ مُتَتَابِعَیۡنِ مِن قَبۡلِ أَن یَتَمَاۤسَّاۖ فَمَن لَّمۡ یَسۡتَطِعۡ فَإِطۡعَامُ سِتِّینَ مِسۡكِینࣰاۚ ذَ ٰ⁠لِكَ لِتُؤۡمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ وَلِلۡكَـٰفِرِینَ عَذَابٌ أَلِیمٌ\n", "jalalayn": "«فَمَن لَمْ يَجِد» رَقَبَة «فَصِيام شَهْرَيْنِ مُتَتابِعَيْنِ مِن قَبْل أنْ يَتَماسّا فَمَن لَمْ يَسْتَطِعْ» أيْ الصِّيام «فَإطْعام سِتِّينَ مِسْكِينًا» عَلَيْهِ: أيْ مِن قَبْل أنْ يَتَماسّا حَمْلًا لِلْمُطْلَقِ عَلى المُقَيَّد لِكُلِّ مِسْكِين مُدّ مِن غالِب قُوت البَلَد «ذَلِكَ» أيْ التَّخْفِيف فِي الكَفّارَة «لِتُؤْمِنُوا بِاللَّهِ ورَسُوله وتِلْكَ» أيْ الأَحْكام المَذْكُورَة «حُدُود اللَّه ولِلْكافِرِينَ» أيْ ولِلْكافِرِينَ بِها «عَذاب ألِيم» مُؤْلِم", "malayalam": "«അതിന് സാധിക്കാത്തവൻ പരസ്പരം സ്പർശിക്കുന്നതിന് മുമ്പായി തുടർച്ചയായി രണ്ടു മാസം നോമ്പനുഷ്ഠിക്കേണ്ടതാണ്; അതിനും സാധിക്കാത്തവൻ അറുപത് അഗതികൾക്ക് ഭക്ഷണം നൽകേണ്ടതാണ്; നിങ്ങൾ അല്ലാഹുവിലും അവന്റെ റസൂലിലും വിശ്വസിക്കുവാൻ വേണ്ടിയത്രെ അത്; അവ അല്ലാഹുവിന്റെ അതിർവരമ്പുകളാകുന്നു; സത്യനിഷേധികൾക്ക് വേദനാജനകമായ ശിക്ഷയുണ്ട്».", "malayalamMatn": "ഇനി വല്ലവന്നും (അടിമയെ) ലഭിക്കാത്ത പക്ഷം, അവര്‍ പരസ്പരം സ്പര്‍ശിക്കുന്നതിന് മുമ്പായി തുടര്‍ച്ചയായി രണ്ടുമാസക്കാലം നോമ്പനുഷ്ഠിക്കേണ്ടതാണ്‌. വല്ലവന്നും (അത്‌) സാധ്യമാകാത്ത പക്ഷം അറുപതു അഗതികള്‍ക്ക് ആഹാരം നല്‍കേണ്ടതാണ്‌. അത് അല്ലാഹുവിലും അവന്‍റെ ദൂതനിലും നിങ്ങള്‍ വിശ്വസിക്കാന്‍ വേണ്ടിയത്രെ. അവ അല്ലാഹുവിന്‍റെ പരിധികളാകുന്നു. സത്യനിഷേധികള്‍ക്ക് വേദനയേറിയ ശിക്ഷയുണ്ട്‌."}, {"ayahNumber": 5, "quranText": "إِنَّ ٱلَّذِینَ یُحَاۤدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُوا۟ كَمَا كُبِتَ ٱلَّذِینَ مِن قَبۡلِهِمۡۚ وَقَدۡ أَنزَلۡنَاۤ ءَایَـٰتِۭ بَیِّنَـٰتࣲۚ وَلِلۡكَـٰفِرِینَ عَذَابࣱ مُّهِینࣱ\n", "jalalayn": "«إنّ الَّذِينَ يُحادُّونَ» يُخالِفُونَ «اللَّه ورَسُوله كُبِتُوا» أُذِلُّوا «كَما كُبِتَ الَّذِينَ مِن قَبْلهمْ» فِي مُخالَفَتهمْ رُسُلهمْ «وقَدْ أنْزَلْنا آيات بَيِّنات» دالَّة عَلى صِدْق الرَّسُول «ولِلْكافِرِينَ» بِالآياتِ «عَذاب مُهِين» ذُو إهانَة", "malayalam": "«തീർച്ചയായും അല്ലാഹുവോടും അവന്റെ റസൂലിനോടും എതിർത്തുനിൽക്കുന്നവർ, മുൻഗാമികൾ അപമാനിതരായതുപോലെ അപമാനിതരാക്കപ്പെടും; തീർച്ചയായും നാം സുവ്യക്തമായ ദൃഷ്ടാന്തങ്ങൾ അവതരിപ്പിച്ചിരിക്കുന്നു; സത്യനിഷേധികൾക്ക് നിന്ദ്യമായ ശിക്ഷയുണ്ട്».", "malayalamMatn": "തീര്‍ച്ചയായും അല്ലാഹുവെയും അവന്‍റെ ദൂതനെയും എതിര്‍ത്തു കൊണ്ടിരിക്കുന്നവര്‍ അവരുടെ മുമ്പുള്ളവര്‍ വഷളാക്കപ്പെട്ടത് പോലെ വഷളാക്കപ്പെടുന്നതാണ്‌. സുവ്യക്തമായ പല തെളിവുകളും നാം അവതരിപ്പിച്ചിട്ടുണ്ട്‌. സത്യനിഷേധികള്‍ക്ക് അപമാനകരമായ ശിക്ഷയുമുണ്ട്‌."}, {"ayahNumber": 6, "quranText": "یَوۡمَ یَبۡعَثُهُمُ ٱللَّهُ جَمِیعࣰا فَیُنَبِّئُهُم بِمَا عَمِلُوۤا۟ۚ أَحۡصَىٰهُ ٱللَّهُ وَنَسُوهُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدٌ\n", "jalalayn": "«یَوۡمَ یَبۡعَثُهُمُ ٱللَّهُ جَمِیعࣰا فَیُنَبِّئُهُم بِمَا عَمِلُوۤا۟ۚ أَحۡصَىٰهُ ٱللَّهُ وَنَسُوهُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدٌ».", "malayalam": "«അല്ലാഹു അവരെയെല്ലാം ഒരുമിച്ചു കൂട്ടുന്ന ദിവസം! അവർ പ്രവർത്തിച്ചതിനെക്കുറിച്ച് അവൻ അവർക്ക് വിവരമറിയിക്കും; അല്ലാഹു അത് കൃത്യമായി എണ്ണിത്തിട്ടപ്പെടുത്തിയിരിക്കുന്നു, അവരത് മറന്നുപോയിരിക്കുന്നു; അല്ലാഹു സർവ്വകാര്യങ്ങൾക്കും സാക്ഷിയാകുന്നു».", "malayalamMatn": "അല്ലാഹു അവരെയെല്ലാം ഉയിര്‍ത്തെഴുന്നേല്‍പിക്കുകയും, എന്നിട്ട് അവര്‍ പ്രവര്‍ത്തിച്ചതിനെപ്പറ്റി അവരെ വിവരമറിയിക്കുകയും ചെയ്യുന്ന ദിവസം. അല്ലാഹു അത് തിട്ടപ്പെടുത്തുകയും അവരത് മറന്നുപോകുകയും ചെയ്തു. അല്ലാഹു ഏത് കാര്യത്തിനും സാക്ഷിയാകുന്നു."}, {"ayahNumber": 7, "quranText": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ یَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۖ مَا یَكُونُ مِن نَّجۡوَىٰ ثَلَـٰثَةٍ إِلَّا هُوَ رَابِعُهُمۡ وَلَا خَمۡسَةٍ إِلَّا هُوَ سَادِسُهُمۡ وَلَاۤ أَدۡنَىٰ مِن ذَ ٰ⁠لِكَ وَلَاۤ أَكۡثَرَ إِلَّا هُوَ مَعَهُمۡ أَیۡنَ مَا كَانُوا۟ۖ ثُمَّ یُنَبِّئُهُم بِمَا عَمِلُوا۟ یَوۡمَ ٱلۡقِیَـٰمَةِۚ إِنَّ ٱللَّهَ بِكُلِّ شَیۡءٍ عَلِیمٌ\n", "jalalayn": "«ألَمْ تَرَ» تَعْلَم «أنَّ اللَّه يَعْلَم ما فِي السَّمَوات وما فِي الأَرْض ما يَكُون مِن نَجْوى ثَلاثَة إلّا هُوَ رابِعهمْ» أيْ بِعِلْمِهِ", "malayalam": "«ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതും അല്ലാഹു അറിയുന്നുണ്ടെന്ന് നീ കണ്ടില്ലയോ? മൂന്നുപേരുടെ രഹസ്യ സംഭാഷണമുണ്ടായാൽ അവൻ അവരിൽ നാലാമനായി ഉണ്ടാകാതിരിക്കില്ല; അഞ്ചുപേരുടേതായാൽ അവൻ ആറാമനായി ഉണ്ടാകാതിരിക്കില്ല; അതിൽ കുറഞ്ഞവരോ കൂടിയവരോ ആകട്ടെ, അവർ എവിടെയായിരുന്നാലും അവൻ അവരോടൊപ്പമുണ്ടാകും; പിന്നീട് അവർ പ്രവർത്തിച്ചതിനെക്കുറിച്ച് അന്ത്യനാളിൽ അവൻ അവർക്ക് വിവരമറിയിക്കും; തീർച്ചയായും അല്ലാഹു സർവ്വകാര്യങ്ങളെക്കുറിച്ചും പൂർണ്ണ അറിവുള്ളവനത്രെ».", "malayalamMatn": "ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതും അല്ലാഹു അറിയുന്നുണ്ടെന്ന് നീ കാണുന്നില്ലേ? മൂന്നു പേര്‍ തമ്മിലുള്ള യാതൊരു രഹസ്യസംഭാഷണവും അവന്‍ (അല്ലാഹു) അവര്‍ക്കു നാലാമനായികൊണ്ടല്ലാതെ ഉണ്ടാവുകയില്ല. അഞ്ചുപേരുടെ സംഭാഷണമാണെങ്കില്‍ അവന്‍ അവര്‍ക്കു ആറാമനായികൊണ്ടുമല്ലാതെ. അതിനെക്കാള്‍ കുറഞ്ഞവരുടെയോ, കൂടിയവരുടെയോ (സംഭാഷണം) ആണെങ്കില്‍ അവര്‍ എവിടെയായിരുന്നാലും അവന്‍ അവരോടൊപ്പമുണ്ടായിട്ടല്ലാതെ. പിന്നീട് ഉയിര്‍ത്തെഴുന്നേല്‍പിന്‍റെ നാളില്‍, അവര്‍ പ്രവര്‍ത്തിച്ചതിനെപ്പറ്റി അവരെ അവന്‍ വിവരമറിയിക്കുന്നതാണ്‌. തീര്‍ച്ചയായും അല്ലാഹു ഏത് കാര്യത്തെ പറ്റിയും അറിവുള്ളവനാകുന്നു."}, {"ayahNumber": 8, "quranText": "أَلَمۡ تَرَ إِلَى ٱلَّذِینَ نُهُوا۟ عَنِ ٱلنَّجۡوَىٰ ثُمَّ یَعُودُونَ لِمَا نُهُوا۟ عَنۡهُ وَیَتَنَـٰجَوۡنَ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَ ٰ⁠نِ وَمَعۡصِیَتِ ٱلرَّسُولِۖ وَإِذَا جَاۤءُوكَ حَیَّوۡكَ بِمَا لَمۡ یُحَیِّكَ بِهِ ٱللَّهُ وَیَقُولُونَ فِیۤ أَنفُسِهِمۡ لَوۡلَا یُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُۚ حَسۡبُهُمۡ جَهَنَّمُ یَصۡلَوۡنَهَاۖ فَبِئۡسَ ٱلۡمَصِیرُ\n", "jalalayn": "«ألَمْ تَرَ» تَنْظُر «إلى الَّذِينَ نُهُوا عَنْ النَّجْوى ثُمَّ يَعُودُونَ لِما نُهُوا عَنْهُ ويَتَناجَوْنَ بِالإثْمِ والعُدْوان ومَعْصِيَة الرَّسُول» هُمْ اليَهُود نَهاهُمْ النَّبِيّ ﷺ عَمّا كانُوا يَفْعَلُونَ مِن تَناجِيهمْ أيْ تَحَدُّثهمْ سِرًّا ناظِرِينَ إلى المُؤْمِنِينَ لِيُوقِعُوا فِي قُلُوبهمْ الرِّيبَة «وإذا جاءُوك» أيّها النَّبِيّ «حَيَّوْك بِما لَمْ يُحَيِّك بِهِ اللَّه» وهُوَ قَوْلهمْ: السّام عَلَيْك أيْ المَوْت «ويَقُولُونَ فِي أنْفُسهمْ لَوْلا» هَلّا «يُعَذِّبنا اللَّه بِما نَقُول» أيْ بِما نَقُول مِن التَّحِيَّة وأَنَّهُ لَيْسَ بِنَبِيٍّ إنْ كانَ نَبِيًّا «حَسْبهمْ جَهَنَّم يَصْلَوْنَها فَبِئْسَ المَصِير» هِيَ", "malayalam": "«രഹസ്യാലോചന നടത്തുന്നതിൽ നിന്ന് വിരോധിക്കപ്പെട്ടവരെ നീ കണ്ടില്ലയോ? എന്നിട്ട് അവർ വിരോധിക്കപ്പെട്ടതിലേക്ക് തന്നെ മടങ്ങുകയും, പാപത്തിനും അതിക്രമത്തിനും റസൂലിനെതിരെയുള്ള അനുസരണക്കേടിനുമായി അവർ പരസ്പരം രഹസ്യാലോചന നടത്തുകയും ചെയ്യുന്നു; അവർ നിന്റെ അടുക്കൽ വന്നാൽ അല്ലാഹു നിനക്ക് അഭിവാദ്യം ചെയ്യാത്ത രീതിയിൽ അവർ നിനക്ക് അഭിവാദ്യം ചെയ്യുന്നു (അസ്സാമു അലൈക്ക - മരണം ഭവിക്കട്ടെ എന്ന് പറഞ്ഞുകൊണ്ട്); അവർ തങ്ങളുടെ മനസ്സിൽ പറയും: നാം പറയുന്നതിന് അല്ലാഹു നമ്മെ ശിക്ഷിക്കാത്തതെന്താണ്? അവർക്ക് നരകം മതിയാകും; അവരതിൽ വെന്തുരുകും, അത് എത്രയോ ചീത്തയായ സങ്കേതം!».", "malayalamMatn": "രഹസ്യസംഭാഷണം നടത്തുന്നതില്‍ നിന്ന് വിലക്കപ്പെട്ടിട്ടുള്ളവരെ നീ കണ്ടില്ലേ? അവര്‍ ഏതൊന്നില്‍ നിന്നു വിലക്കപ്പെട്ടുവോ അതിലേക്കവര്‍ പിന്നീട് മടങ്ങുന്നു.പാപത്തിനും അതിക്രമത്തിനും റസൂലിനെ ധിക്കരിക്കുന്നതിനും അവര്‍ പരസ്പരം രഹസ്യഉപദേശം നടത്തുകയും ചെയ്യുന്നു. അവര്‍ നിന്‍റെ അടുത്ത് വന്നാല്‍ നിന്നെ അല്ലാഹു അഭിവാദ്യം ചെയ്തിട്ടില്ലാത്ത രീതിയില്‍ അവര്‍ നിനക്ക് അഭിവാദ്യമര്‍പ്പിക്കുകയും ചെയ്യും. ഞങ്ങള്‍ ഈ പറയുന്നതിന്‍റെ പേരില്‍ അല്ലാഹു ഞങ്ങളെ ശിക്ഷിക്കാതിരിക്കുന്നത് എന്തുകൊണ്ടാണെന്ന് അവര്‍ അന്യോന്യം പറയുകയും ചെയ്യും. അവര്‍ക്കു നരകം മതി. അവര്‍ അതില്‍ എരിയുന്നതാണ്‌. ആ പര്യവസാനം എത്ര ചീത്ത."}, {"ayahNumber": 9, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا تَنَـٰجَیۡتُمۡ فَلَا تَتَنَـٰجَوۡا۟ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَ ٰ⁠نِ وَمَعۡصِیَتِ ٱلرَّسُولِ وَتَنَـٰجَوۡا۟ بِٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِیۤ إِلَیۡهِ تُحۡشَرُونَ\n", "jalalayn": "«یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا تَنَـٰجَیۡتُمۡ فَلَا تَتَنَـٰجَوۡا۟ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَ ٰ⁠نِ وَمَعۡصِیَتِ ٱلرَّسُولِ وَتَنَـٰجَوۡا۟ بِٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِیۤ إِلَیۡهِ تُحۡشَرُونَ».", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, നിങ്ങൾ പരസ്പരം രഹസ്യാലോചന നടത്തുകയാണെങ്കിൽ പാപത്തിനും അതിക്രമത്തിനും റസൂലിനോടുള്ള അനുസരണക്കേടിനുമായി നിങ്ങൾ രഹസ്യാലോചന നടത്തരുത്; മറിച്ച് പുണ്യത്തിലും ഭയഭക്തിയിലും നിങ്ങൾ പരസ്പരം കൂടിയാലോചിക്കുക; ഏതൊരുവനിലേക്കാണോ നിങ്ങൾ ഒരുമിച്ചുകൂട്ടപ്പെടുന്നത് ആ അല്ലാഹുവിനെ നിങ്ങൾ സൂക്ഷിക്കുകയും ചെയ്യുവിൻ».", "malayalamMatn": "സത്യവിശ്വാസികളേ, നിങ്ങള്‍ രഹസ്യസംഭാഷണം നടത്തുകയാണെങ്കില്‍ അധര്‍മ്മത്തിനും അതിക്രമത്തിനും റസൂലിനെ ധിക്കരിക്കുന്നതിനും നിങ്ങള്‍ രഹസ്യസംഭാഷണം നടത്തരുത്‌. പുണ്യത്തിന്‍റെയും ഭയഭക്തിയുടെയും കാര്യത്തില്‍ നിങ്ങള്‍ രഹസ്യഉപദേശം നടത്തുക. ഏതൊരു അല്ലാഹുവിങ്കലേക്ക് നിങ്ങള്‍ ഒരുമിച്ചുകൂട്ടപ്പെടുമോ അവനെ നിങ്ങള്‍ സൂക്ഷിക്കുകയും ചെയ്യുക."}, {"ayahNumber": 10, "quranText": "إِنَّمَا ٱلنَّجۡوَىٰ مِنَ ٱلشَّیۡطَـٰنِ لِیَحۡزُنَ ٱلَّذِینَ ءَامَنُوا۟ وَلَیۡسَ بِضَاۤرِّهِمۡ شَیۡـًٔا إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ\n", "jalalayn": "«إنّما النَّجْوى» بِالإثْمِ ونَحْوه أيْ النَّجْوى بِالإثْمِ ونَحْوه «مِن الشَّيْطان» بِغُرُورِهِ «لِيَحْزُن الَّذِينَ آمَنُوا ولَيْسَ» هُوَ «بِضارِّهِمْ شَيْئًا إلّا بِإذْنِ اللَّه» أيْ إرادَته", "malayalam": "«സത്യവിശ്വാസികളെ ദുഃഖിപ്പിക്കുവാനായി പിശാചിന്റെ പ്രേരണയാൽ മാത്രമാണ് ആ ദുഷിച്ച രഹസ്യാലോചനകൾ ഉണ്ടാകുന്നത്; എന്നാൽ അല്ലാഹുവിന്റെ അനുവാദമില്ലാതെ അവർക്ക് വിശ്വാസികൾക്ക് യാതൊരു ഉപദ്രവവും ചെയ്യാനാകില്ല; സത്യവിശ്വാസികൾ അല്ലാഹുവിൽ മാത്രം ഭരമേൽപിക്കട്ടെ».", "malayalamMatn": "ആ രഹസ്യസംസാരം പിശാചില്‍ നിന്നുള്ളത് മാത്രമാകുന്നു. സത്യവിശ്വാസികളെ ദുഃഖിപ്പിക്കാന്‍ വേണ്ടിയാകുന്നു അത്‌. എന്നാല്‍ അല്ലാഹുവിന്‍റെ അനുമതികൂടാതെ അതവര്‍ക്ക് യാതൊരു ഉപദ്രവവും ചെയ്യുന്നതല്ല. സത്യവിശ്വാസികള്‍ അല്ലാഹുവിന്‍റെ മേല്‍ ഭരമേല്‍പിച്ചുകൊള്ളട്ടെ."}, {"ayahNumber": 11, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا قِیلَ لَكُمۡ تَفَسَّحُوا۟ فِی ٱلۡمَجَـٰلِسِ فَٱفۡسَحُوا۟ یَفۡسَحِ ٱللَّهُ لَكُمۡۖ وَإِذَا قِیلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ یَرۡفَعِ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ مِنكُمۡ وَٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ دَرَجَـٰتࣲۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا إذا قِيلَ لَكُمْ تَفَسَّحُوا» تَوَسَّعُوا «فِي المَجْلِس» مَجْلِس النَّبِيّ ﷺ والذِّكْر حَتّى يَجْلِس مَن جاءَكُمْ وفِي قِراءَة المَجالِس «فافْسَحُوا يَفْسَح اللَّه لَكُمْ» فِي الجَنَّة «وإذا قِيلَ اُنْشُزُوا» قُومُوا إلى الصَّلاة وغَيْرها مِن الخَيْرات «فانْشُزُوا» وفِي قِراءَة بِضَمِّ الشِّين فِيهِما «يَرْفَع اللَّه الَّذِينَ آمَنُوا مِنكُمْ» بِالطّاعَةِ فِي ذَلِكَ «و» يَرْفَع «الَّذِينَ أُوتُوا العِلْم دَرَجات» فِي الجَنَّة", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, സദസ്സുകളിൽ സൗകര്യപ്പെടുത്തിക്കൊടുക്കുവിൻ എന്ന് നിങ്ങളോട് പറയപ്പെട്ടാൽ നിങ്ങൾ സൗകര്യപ്പെടുത്തിക്കൊടുക്കുക; എങ്കിൽ അല്ലാഹു നിങ്ങൾക്ക് സൗകര്യം ചെയ്തുതരും; എഴുന്നേറ്റു നിൽക്കുവിൻ എന്ന് പറയപ്പെട്ടാൽ നിങ്ങൾ എഴുന്നേറ്റു നിൽക്കുക; നിങ്ങളിൽ നിന്ന് വിശ്വസിച്ചവരെയും അറിവ് നൽകപ്പെട്ടവരെയും അല്ലാഹു പല പദവികളാൽ ഉയർത്തുന്നതാണ്; നിങ്ങൾ പ്രവർത്തിക്കുന്നതിനെപ്പറ്റി അല്ലാഹു സൂക്ഷ്മമായി അറിയുന്നവനത്രെ».", "malayalamMatn": "സത്യവിശ്വാസികളേ, നിങ്ങള്‍ സദസ്സുകളില്‍ സൌകര്യപ്പെടുത്തി കൊടുക്കുക എന്ന് നിങ്ങളോടു പറയപ്പെട്ടാല്‍ നിങ്ങള്‍ സൌകര്യപ്പെടുത്തികൊടുക്കണം. എങ്കില്‍ അല്ലാഹു നിങ്ങള്‍ക്കും സൌകര്യപ്പെടുത്തിത്തരുന്നതാണ്‌. നിങ്ങള്‍ എഴുന്നേറ്റ് പോകണമെന്ന് പറയപ്പെട്ടാല്‍ നിങ്ങള്‍ എഴുന്നേറ്റ് പോകണം. നിങ്ങളില്‍ നിന്ന് വിശ്വസിച്ചവരെയും വിജ്ഞാനം നല്‍കപ്പെട്ടവരെയും അല്ലാഹു പല പടികള്‍ ഉയര്‍ത്തുന്നതാണ്‌. അല്ലാഹു നിങ്ങള്‍ പ്രവര്‍ത്തിക്കുന്നതിനെ പറ്റി സൂക്ഷ്മമായി അറിയുന്നവനാകുന്നു."}, {"ayahNumber": 12, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا نَـٰجَیۡتُمُ ٱلرَّسُولَ فَقَدِّمُوا۟ بَیۡنَ یَدَیۡ نَجۡوَىٰكُمۡ صَدَقَةࣰۚ ذَ ٰ⁠لِكَ خَیۡرࣱ لَّكُمۡ وَأَطۡهَرُۚ فَإِن لَّمۡ تَجِدُوا۟ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا إذا ناجَيْتُمْ الرَّسُول» أرَدْتُمْ مُناجاته «فَقَدِّمُوا بَيْن يَدَيْ نَجْواكُمْ» قَبْلها «وأَطْهَر» لِذُنُوبِكُمْ «فَإنْ لَمْ تَجِدُوا» ما تَتَصَدَّقُونَ بِهِ «فَإنَّ اللَّه غَفُور» لِمُناجاتِكُمْ «رَحِيم» بِكُمْ يَعْنِي فَلا عَلَيْكُمْ فِي المُناجاة مِن غَيْر صَدَقَة ثُمَّ نَسَخَ ذَلِكَ بِقَوْلِهِ:", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, നിങ്ങൾ റസൂലുമായി രഹസ്യസംഭാഷണം നടത്തുവാൻ ഉദ്ദേശിക്കുകയാണെങ്കിൽ നിങ്ങളുടെ ആ സംഭാഷണത്തിന് മുമ്പായി വല്ല ദാനധർമ്മവും മുൻകൂട്ടി നൽകുക; അതത്രെ നിങ്ങൾക്ക് ഏറ്റവും ഉത്തമവും ഏറ്റവും പരിശുദ്ധവുമായിട്ടുള്ളത്; ഇനി നിങ്ങൾക്ക് അതിനുള്ള വക ലഭിച്ചില്ലെങ്കിലോ, തീർച്ചയായും അല്ലാഹു ഏറെ പൊറുക്കുന്നവനും ദയാപരനുമാകുന്നു».", "malayalamMatn": "സത്യവിശ്വാസികളേ, നിങ്ങള്‍ റസൂലുമായി രഹസ്യസംഭാഷണം നടത്തുകയാണെങ്കില്‍ നിങ്ങളുടെ രഹസ്യസംഭാഷണത്തിന്‍റെ മുമ്പായി ഏതെങ്കിലുമൊരു ദാനം നിങ്ങള്‍ അര്‍പ്പിക്കുക. അതാണു നിങ്ങള്‍ക്കു ഉത്തമവും കൂടുതല്‍ പരിശുദ്ധവുമായിട്ടുള്ളത്‌. ഇനി നിങ്ങള്‍ക്ക് (ദാനം ചെയ്യാന്‍) ഒന്നും കിട്ടിയില്ലെങ്കില്‍ തീര്‍ച്ചയായും അല്ലാഹു എറെ പൊറുക്കുന്നവനും കരുണാനിധിയുമാകുന്നു."}, {"ayahNumber": 13, "quranText": "ءَأَشۡفَقۡتُمۡ أَن تُقَدِّمُوا۟ بَیۡنَ یَدَیۡ نَجۡوَىٰكُمۡ صَدَقَـٰتࣲۚ فَإِذۡ لَمۡ تَفۡعَلُوا۟ وَتَابَ ٱللَّهُ عَلَیۡكُمۡ فَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِیعُوا۟ ٱللَّهَ وَرَسُولَهُۥۚ وَٱللَّهُ خَبِیرُۢ بِمَا تَعۡمَلُونَ\n", "jalalayn": "«أأَشْفَقْتُمْ» بِتَحْقِيقِ الهَمْزَتَيْنِ وإبْدال الثّانِيَة ألِفًا وتَسْهِيلها وإدْخال ألِف بَيْن المُسَهَّلَة والأُخْرى وتَرَكَهُ أيْ خِفْتُمْ مِن «أنْ تُقَدِّمُوا بَيْن يَدَيْ نَجْواكُمْ صَدَقات» لِفَقْرٍ «فَإذْ لَمْ تَفْعَلُوا» الصَّدَقَة «وتابَ اللَّه عَلَيْكُمْ» رَجَعَ بِكُمْ عَنْها «فَأَقِيمُوا الصَّلاة وآتُوا الزَّكاة وأَطِيعُوا اللَّه ورَسُوله» أيْ داوِمُوا عَلى ذَلِكَ", "malayalam": "«നിങ്ങളുടെ രഹസ്യസംഭാഷണത്തിന് മുമ്പായി ദാനധർമ്മങ്ങൾ മുൻകൂട്ടി നൽകുന്നതിൽ നിങ്ങൾ ഭയപ്പെട്ടുപോയോ? എന്നാൽ നിങ്ങളത് ചെയ്തില്ലെങ്കിലും അല്ലാഹു നിങ്ങളുടെ പശ്ചാത്താപം സ്വീകരിച്ചിരിക്കുന്നു; അതിനാൽ നിങ്ങൾ നമസ്കാരം മുറപ്രകാരം നിലനിർത്തുകയും സകാത്ത് നൽകുകയും അല്ലാഹുവെയും അവന്റെ റസൂലിനെയും അനുസരിക്കുകയും ചെയ്യുവിൻ; നിങ്ങൾ പ്രവർത്തിക്കുന്നതിനെപ്പറ്റി അല്ലാഹു സൂക്ഷ്മമായി അറിയുന്നവനത്രെ».", "malayalamMatn": "നിങ്ങളുടെ രഹസ്യസംഭാഷണത്തിനു മുമ്പായി നിങ്ങള്‍ ദാനധര്‍മ്മങ്ങള്‍ അര്‍പ്പിക്കുന്നതിനെപ്പറ്റി നിങ്ങള്‍ ഭയപ്പെട്ടിരിക്കുകയാണോ? എന്നാല്‍ നിങ്ങളത് ചെയ്യാതിരിക്കുകയും അല്ലാഹു നിങ്ങളുടെ നേരെ മടങ്ങുകയും ചെയ്തിരിക്കയാല്‍ നിങ്ങള്‍ നമസ്കാരം മുറപോലെ നിര്‍വഹിക്കുകയും സകാത്ത് നല്‍കുകയും അല്ലാഹുവെയും അവന്‍റെ റസൂലിനെയും നിങ്ങള്‍ അനുസരിക്കുകയും ചെയ്യുക. അല്ലാഹു നിങ്ങള്‍ പ്രവര്‍ത്തിക്കുന്നതിനെപ്പറ്റി സൂക്ഷ്മമായി അറിയുന്നവനാകുന്നു."}, {"ayahNumber": 14, "quranText": "۞ أَلَمۡ تَرَ إِلَى ٱلَّذِینَ تَوَلَّوۡا۟ قَوۡمًا غَضِبَ ٱللَّهُ عَلَیۡهِم مَّا هُم مِّنكُمۡ وَلَا مِنۡهُمۡ وَیَحۡلِفُونَ عَلَى ٱلۡكَذِبِ وَهُمۡ یَعۡلَمُونَ\n", "jalalayn": "«ألَمْ تَرَ» تَنْظُر «إلى الَّذِينَ تَوَلَّوْا» هُمْ المُنافِقُونَ «قَوْمًا» هُمْ اليَهُود «غَضِبَ اللَّه عَلَيْهِمْ ما هُمْ» أيْ المُنافِقُونَ «مِنكُمْ» مِن المُؤْمِنِينَ «ولا مِنهُمْ» مِن اليَهُود بَلْ هُمْ مُذَبْذَبُونَ «ويَحْلِفُونَ عَلى الكَذِب» أيْ قَوْلهمْ إنّهُمْ مُؤْمِنُونَ «وهُمْ يَعْلَمُونَ» أنَّهُمْ كاذِبُونَ فِيهِ", "malayalam": "«അല്ലാഹു കോപിച്ച ഒരു ജനതയെ (യഹൂദരെ) മിത്രങ്ങളാക്കിയ കപടവിശ്വാസികളെ നീ കണ്ടില്ലയോ? അവർ നിങ്ങളിൽ പെട്ടവരുമല്ല, അവരിൽ പെട്ടവരുമല്ല; അവർ അറിഞ്ഞുകൊണ്ടുതന്നെ കളവിൻമേൽ സത്യം ചെയ്തു പറയുന്നു».", "malayalamMatn": "അല്ലാഹു കോപിച്ച ഒരു വിഭാഗ (യഹൂദര്‍) വുമായി മൈത്രിയില്‍ ഏര്‍പെട്ടവരെ (മുനാഫിഖുകളെ) നീ കണ്ടില്ലേ? അവര്‍ നിങ്ങളില്‍ പെട്ടവരല്ല. അവരില്‍ (യഹൂദരില്‍) പെട്ടവരുമല്ല. അവര്‍ അറിഞ്ഞു കൊണ്ട് കള്ള സത്യം ചെയ്യുന്നു."}, {"ayahNumber": 15, "quranText": "أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابࣰا شَدِیدًاۖ إِنَّهُمۡ سَاۤءَ مَا كَانُوا۟ یَعۡمَلُونَ\n", "jalalayn": "«أعَدَّ اللَّه لَهُمْ عَذابًا شَدِيدًا إنّهُمْ ساءَ ما كانُوا يَعْمَلُونَ» مِن المَعاصِي", "malayalam": "«അല്ലാഹു അവർക്കായി കഠിനമായ ശിക്ഷ ഒരുക്കിവെച്ചിരിക്കുന്നു; തീർച്ചയായും അവർ പ്രവർത്തിച്ചുകൊണ്ടിരുന്നത് എത്രയോ മോശമായ കാര്യമാകുന്നു!».", "malayalamMatn": "അല്ലാഹു അവര്‍ക്ക് കഠിനമായ ശിക്ഷ ഒരുക്കിവെച്ചിരിക്കുന്നു. തീര്‍ച്ചയായും അവര്‍ ചെയ്തുകൊണ്ടിരിക്കുന്ന കാര്യം എത്രയോ ദുഷിച്ചതായിരിക്കുന്നു."}, {"ayahNumber": 16, "quranText": "ٱتَّخَذُوۤا۟ أَیۡمَـٰنَهُمۡ جُنَّةࣰ فَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِ فَلَهُمۡ عَذَابࣱ مُّهِینࣱ\n", "jalalayn": "«اتَّخَذُوا أيْمانهمْ جُنَّة» سَتْرًا عَلى أنْفُسهمْ وأَمْوالهمْ «فَصَدُّوا» بِها المُؤْمِنِينَ «عَنْ سَبِيل اللَّه» أيْ الجِهاد فِيهِمْ بِقَتْلِهِمْ وأَخْذ أمْوالهمْ «فَلَهُمْ عَذاب مُهِين» ذُو إهانَة", "malayalam": "«അവർ തങ്ങളുടെ സത്യങ്ങളെ ഒരു പരിചയാക്കി വെച്ചിരിക്കുന്നു; അങ്ങനെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ നിന്ന് അവർ ജനങ്ങളെ തടഞ്ഞു; അതിനാൽ അവർക്ക് നിന്ദ്യമായ ശിക്ഷയുണ്ട്».", "malayalamMatn": "അവരുടെ ശപഥങ്ങളെ അവര്‍ ഒരു പരിചയാക്കിത്തീര്‍ത്തിരിക്കുന്നു. അങ്ങനെ അവര്‍ അല്ലാഹുവിന്‍റെ മാര്‍ഗത്തില്‍ നിന്ന് (ജനങ്ങളെ) തടഞ്ഞു. അതിനാല്‍ അവര്‍ക്ക് അപമാനകരമായ ശിക്ഷയുണ്ട്‌."}, {"ayahNumber": 17, "quranText": "لَّن تُغۡنِیَ عَنۡهُمۡ أَمۡوَ ٰ⁠لُهُمۡ وَلَاۤ أَوۡلَـٰدُهُم مِّنَ ٱللَّهِ شَیۡـًٔاۚ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ\n", "jalalayn": "«لَنْ تُغْنِي عَنْهُمْ أمْوالهمْ ولا أوْلادهمْ مِن اللَّه» مِن عَذابه «شَيْئًا» مِن الإغْناء", "malayalam": "«അവരുടെ സമ്പത്തോ അവരുടെ മക്കളോ അല്ലാഹുവിൽ നിന്ന് അവരെ ഒട്ടും രക്ഷിക്കുകയില്ല; അവരത്രെ നരകാവകാശികൾ, അവരതിൽ ശാശ്വതരായിരിക്കും».", "malayalamMatn": "അവരുടെ സമ്പത്തുകളോ സന്താനങ്ങളോ അല്ലാഹുവിങ്കല്‍ അവര്‍ക്ക് ഒട്ടും പ്രയോജനപ്പെടുകയില്ല. അത്തരക്കാരാകുന്നു നരകാവകാശികള്‍. അവര്‍ അതില്‍ നിത്യവാസികളായിരിക്കും."}, {"ayahNumber": 18, "quranText": "یَوۡمَ یَبۡعَثُهُمُ ٱللَّهُ جَمِیعࣰا فَیَحۡلِفُونَ لَهُۥ كَمَا یَحۡلِفُونَ لَكُمۡ وَیَحۡسَبُونَ أَنَّهُمۡ عَلَىٰ شَیۡءٍۚ أَلَاۤ إِنَّهُمۡ هُمُ ٱلۡكَـٰذِبُونَ\n", "jalalayn": "«يَوْم يَبْعَثهُمْ اللَّه جَمِيعًا فَيَحْلِفُونَ لَهُ» أنَّهُمْ مُؤْمِنُونَ «كَما يَحْلِفُونَ لَكُمْ ويَحْسَبُونَ أنَّهُمْ عَلى شَيْء» مِن نَفْع حَلِفهمْ فِي الآخِرَة كالدُّنْيا", "malayalam": "«അല്ലാഹു അവരെയെല്ലാം ഉയിർത്തെഴുന്നേൽപിക്കുന്ന ദിവസം! അവർ നിങ്ങളുടെ മുമ്പിൽ സത്യം ചെയ്തു പറയുന്നതുപോലെ അവന്റെ മുമ്പിലും അവർ കള്ളസത്യം ചെയ്യും; തങ്ങൾക്ക് വല്ല നിലനില്പുമുണ്ടെന്ന് അവർ കരുതുകയും ചെയ്യും; അറിയുക! തീർച്ചയായും അവരത്രെ പെരുംകള്ളന്മാർ!».", "malayalamMatn": "അല്ലാഹു അവരെയെല്ലാം ഉയിര്‍ത്തെഴുന്നേല്‍പിക്കുന്ന ദിവസം. നിങ്ങളോടവര്‍ ശപഥം ചെയ്യുന്നത് പോലെ അവനോടും അവര്‍ ശപഥം ചെയ്യും. തങ്ങള്‍ (ഈ കള്ള സത്യം മൂലം) എന്തോ ഒന്ന് നേടിയതായി അവര്‍ വിചാരിക്കുകയും ചെയ്യും. അറിയുക: തീര്‍ച്ചയായും അവര്‍ തന്നെയാകുന്നു കള്ളം പറയുന്നവര്‍"}, {"ayahNumber": 19, "quranText": "ٱسۡتَحۡوَذَ عَلَیۡهِمُ ٱلشَّیۡطَـٰنُ فَأَنسَىٰهُمۡ ذِكۡرَ ٱللَّهِۚ أُو۟لَـٰۤىِٕكَ حِزۡبُ ٱلشَّیۡطَـٰنِۚ أَلَاۤ إِنَّ حِزۡبَ ٱلشَّیۡطَـٰنِ هُمُ ٱلۡخَـٰسِرُونَ\n", "jalalayn": "«اسْتَحْوَذَ» اسْتَوْلى «عَلَيْهِمْ الشَّيْطان» بِطاعَتِهِمْ لَهُ «فَأَنْساهُمْ ذِكْر اللَّه أُولَئِكَ حِزْب الشَّيْطان» أتْباعه", "malayalam": "«പിശാച് അവരുടെ മേൽ ആധിപത്യം സ്ഥാപിച്ചിരിക്കുന്നു; അങ്ങനെ അല്ലാഹുവിനെക്കുറിച്ചുള്ള സ്മരണ അവൻ അവരെ മറപ്പിച്ചു കളഞ്ഞു; അവരത്രെ പിശാചിന്റെ കക്ഷി; അറിയുക! തീർച്ചയായും പിശാചിന്റെ കക്ഷി തന്നെയാണ് പരാജിതർ!».", "malayalamMatn": "പിശാച് അവരെ കീഴടക്കി വെക്കുകയും അങ്ങനെ അല്ലാഹുവെ പറ്റിയുള്ള ഉല്‍ബോധനം അവര്‍ക്ക് വിസ്മരിപ്പിച്ചു കളയുകയും ചെയ്തിരിക്കുന്നു. അക്കൂട്ടരാകുന്നു പിശാചിന്‍റെ കക്ഷി. അറിയുക; തീര്‍ച്ചയായും പിശാചിന്‍റെ കക്ഷി തന്നെയാകുന്നു നഷ്ടക്കാര്‍ ."}, {"ayahNumber": 20, "quranText": "إِنَّ ٱلَّذِینَ یُحَاۤدُّونَ ٱللَّهَ وَرَسُولَهُۥۤ أُو۟لَـٰۤىِٕكَ فِی ٱلۡأَذَلِّینَ\n", "jalalayn": "«إنّ الَّذِينَ يُحادُّونَ» يُخالِفُونَ «اللَّه ورَسُوله أُولَئِكَ فِي الأَذَلِّينَ» المَغْلُوبِينَ", "malayalam": "«തീർച്ചയായും അല്ലാഹുവോടും അവന്റെ റസൂലിനോടും എതിർത്തുനിൽക്കുന്നവർ ഏറ്റവും നിന്ദ്യന്മാരുടെ കൂട്ടത്തിലായിരിക്കും».", "malayalamMatn": "തീര്‍ച്ചയായും അല്ലാഹുവോടും അവന്‍റെ റസൂലിനോടും എതിര്‍ത്തുനില്‍ക്കുന്നവരാരോ അക്കൂട്ടര്‍ ഏറ്റവും നിന്ദ്യന്‍മാരായവരുടെ കൂട്ടത്തിലാകുന്നു."}, {"ayahNumber": 21, "quranText": "كَتَبَ ٱللَّهُ لَأَغۡلِبَنَّ أَنَا۠ وَرُسُلِیۤۚ إِنَّ ٱللَّهَ قَوِیٌّ عَزِیزࣱ\n", "jalalayn": "«كَتَبَ اللَّه» فِي اللَّوْح المَحْفُوظ أوْ قَضى «لَأَغْلِبَن أنا ورُسُلِي» بِالحُجَّةِ أوْ السَّيْف", "malayalam": "«ഞാനും എന്റെ റസൂലുകളും തന്നെ വിജയം വരിക്കുമെന്ന് അല്ലാഹു രേഖപ്പെടുത്തിയിരിക്കുന്നു; തീർച്ചയായും അല്ലാഹു ശക്തനും പ്രതാപിയുമാകുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും ഞാനും എന്‍റെ ദൂതന്‍മാരും തന്നെയാണ് വിജയം നേടുക. എന്ന് അല്ലാഹു രേഖപ്പെടുത്തിയിരിക്കുന്നു. തീര്‍ച്ചയായും അല്ലാഹു ശക്തനും പ്രതാപിയുമാകുന്നു."}, {"ayahNumber": 22, "quranText": "لَّا تَجِدُ قَوۡمࣰا یُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ یُوَاۤدُّونَ مَنۡ حَاۤدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوۡ كَانُوۤا۟ ءَابَاۤءَهُمۡ أَوۡ أَبۡنَاۤءَهُمۡ أَوۡ إِخۡوَ ٰ⁠نَهُمۡ أَوۡ عَشِیرَتَهُمۡۚ أُو۟لَـٰۤىِٕكَ كَتَبَ فِی قُلُوبِهِمُ ٱلۡإِیمَـٰنَ وَأَیَّدَهُم بِرُوحࣲ مِّنۡهُۖ وَیُدۡخِلُهُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ رَضِیَ ٱللَّهُ عَنۡهُمۡ وَرَضُوا۟ عَنۡهُۚ أُو۟لَـٰۤىِٕكَ حِزۡبُ ٱللَّهِۚ أَلَاۤ إِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡمُفۡلِحُونَ\n", "jalalayn": "«لا تَجِد قَوْمًا يُؤْمِنُونَ بِاللَّهِ واليَوْم الآخِر يُوادُّونَ» يُصادِقُونَ «مَن حادَّ اللَّه ورَسُوله ولَوْ كانُوا» أيْ المُحادُّونَ «آباءَهُمْ» أيْ المُؤْمِنِينَ «أوْ أبْناءَهُمْ أوْ إخْوانهمْ أوْ عَشِيرَتهمْ» بَلْ يَقْصِدُونَهُمْ بِالسُّوءِ ويُقاتِلُونَهُمْ عَلى الإيمان كَما وقَعَ لِجَماعَةٍ مِن الصَّحابَة رَضِيَ اللَّه عَنْهُمْ «أُولَئِكَ» الَّذِينَ لا يُوادُّونَهُمْ «كَتَبَ» أثْبَتَ «فِي قُلُوبهمْ الإيمان وأَيَّدَهُمْ بِرُوحٍ» بِنُورٍ «مِنهُ» تَعالى «ويُدْخِلُهُمْ جَنّات تَجْرِي مِن تَحْتها الأَنْهار خالِدِينَ فِيها رَضِيَ اللَّه عَنْهُمْ» بِطاعَتِهِ «ورَضُوا عَنْهُ» بِثَوابِهِ «أُولَئِكَ حِزْب اللَّه» يَتَّبِعُونَ أمْره ويَجْتَنِبُونَ نَهْيه «ألا إنّ حِزْب اللَّه هُمْ المُفْلِحُونَ» الفائِزُونَ", "malayalam": "«അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്ന ഒരു ജനത, അല്ലാഹുവോടും അവന്റെ റസൂലിനോടും എതിർത്തുനിൽക്കുന്നവരുമായി സ്നേഹബന്ധം പുലർത്തുന്നത് നീ കാണുകയില്ല; അവർ തങ്ങളുടെ പിതാക്കളോ മക്കളോ സഹോദരങ്ങളോ കുടുംബക്കാരോ ആയിരുന്നാൽ പോലും; അങ്ങനെയുള്ളവരുടെ ഹൃദയങ്ങളിൽ അല്ലാഹു വിശ്വാസം രേഖപ്പെടുത്തുകയും തന്റെ പക്കൽ നിന്നുള്ള ആത്മീയബലം കൊണ്ട് അവരെ ശക്തിപ്പെടുത്തുകയും ചെയ്തിരിക്കുന്നു; താഴെ അരുവികൾ ഒഴുകുന്ന സ്വർഗ്ഗത്തോപ്പുകളിൽ അവൻ അവരെ പ്രവേശിപ്പിക്കും, അവരതിൽ ശാശ്വതരായിരിക്കും; അല്ലാഹു അവരെപ്പറ്റി തൃപ്തിപ്പെട്ടിരിക്കുന്നു, അവർ അവനെപ്പറ്റിയും തൃപ്തിപ്പെട്ടിരിക്കുന്നു; അവരത്രെ അല്ലാഹുവിന്റെ കക്ഷി; അറിയുക! തീർച്ചയായും അല്ലാഹുവിന്റെ കക്ഷി തന്നെയാണ് വിജയം വരിക്കുന്നവർ!».", "malayalamMatn": "അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്ന ഒരു ജനത അല്ലാഹുവോടും അവന്‍റെ റസൂലിനോടും എതിര്‍ത്തു നില്‍ക്കുന്നവരുമായി സ്നേഹബന്ധം പുലര്‍ത്തുന്നത് നീ കണ്ടെത്തുകയില്ല. അവര്‍ (എതിര്‍പ്പുകാര്‍) അവരുടെ പിതാക്കളോ, പുത്രന്‍മാരോ, സഹോദരന്‍മാരോ ബന്ധുക്കളോ ആയിരുന്നാല്‍ പോലും. അത്തരക്കാരുടെ ഹൃദയങ്ങളില്‍ അല്ലാഹു വിശ്വാസം രേഖപ്പെടുത്തുകയും അവന്‍റെ പക്കല്‍ നിന്നുള്ള ഒരു ആത്മചൈതന്യം കൊണ്ട് അവന്‍ അവര്‍ക്ക് പിന്‍ബലം നല്‍കുകയും ചെയ്തിരിക്കുന്നു. താഴ്ഭാഗത്തു കൂടി അരുവികള്‍ ഒഴുകുന്ന സ്വര്‍ഗത്തോപ്പുകളില്‍ അവന്‍ അവരെ പ്രവേശിപ്പിക്കുകയും ചെയ്യും. അവരതില്‍ നിത്യവാസികളായിരിക്കും. അല്ലാഹു അവരെ പറ്റി തൃപ്തിപ്പെട്ടിരിക്കുന്നു. അവര്‍ അവനെ പറ്റിയും തൃപ്തിപ്പെട്ടിരിക്കുന്നു. അത്തരക്കാരാകുന്നു അല്ലാഹുവിന്‍റെ കക്ഷി. അറിയുക: തീര്‍ച്ചയായും അല്ലാഹുവിന്‍റെ കക്ഷിയാകുന്നു വിജയം പ്രാപിക്കുന്നവര്‍."}], "topPoints": ["സ്ത്രീകളുടെ അവകാശങ്ങളും സംരക്ഷണവും (خلاصة السورة)", "രഹസ്യ സംഭാഷണങ്ങളിലെ മര്യാദകൾ"], "topQuestions": [{"q": "സൂറത്തുൽ മുജാദല എന്തിനെക്കുറിച്ച് സംസാരിക്കുന്നു?", "a": "ഭർത്താവുമായി തർക്കിച്ച ഒരു സ്ത്രീയുടെ പരാതി അല്ലാഹു കേട്ടതിനെക്കുറിച്ചാണ് പ്രധാന പ്രതിപാദ്യം."}], "asbabAlNuzul": [{"ayahNumber": 1, "quranText": "قَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّتِی تُجَـٰدِلُكَ فِی زَوۡجِهَا وَتَشۡتَكِیۤ إِلَى ٱللَّهِ وَٱللَّهُ یَسۡمَعُ تَحَاوُرَكُمَاۤۚ", "arabicSnippet": "«قد سمع الله قول التي تجادلك» تراجعك أيها النبي «في زوجها» المظاهر منها وكان قال لها: أنت عليَّ كظهر أمي... وهي خولة بنت ثعلبة، وهو أوس بن الصامت «وتشتكي إلى الله» فنزل بيان كفارة الظهار.", "malayalamExplanation": "ഖൗല ബിൻത് സഅ്‌ലബ (റ) എന്ന സ്വഹാബി വനിതയുടെ വൃദ്ധനായ ഭർത്താവ് ഔസ് ബിൻ സ്വാമിത് (റ) ദേഷ്യം വന്ന് 'നീ എനിക്ക് എന്റെ ഉമ്മയുടെ മുതുകിനെപ്പോലെയാണ്' എന്ന് പറഞ്ഞ് ളിഹാർ ചെയ്തു. ജാഹിലിയ്യ കാലത്ത് ഇത് സ്ഥിരമായ വിവാഹമോചനമായിരുന്നു. കുട്ടികളുടെ ഭാവിയോർത്ത് വിഷമിച്ച ഖൗല (റ) നബി ﷺ യുടെ അടുക്കൽ വന്ന് പരാതിപ്പെടുകയും ആവർത്തിച്ച് തർക്കിക്കുകയും അല്ലാഹുവിനോട് കരഞ്ഞു പ്രാർത്ഥിക്കുകയും ചെയ്തു. അവരുടെ കണ്ണീരിന് ഉത്തരമായി ളിഹാറിന് കഫാറത്ത് നൽകി ദാമ്പത്യം തുടരാമെന്ന വിധി പ്രഖ്യാപിച്ചുകൊണ്ട് സൂറത്തുൽ മുജാദലയുടെ ആദ്യ വചനങ്ങൾ അവതരിച്ചു."}]}, {"surahNumber": 59, "surahNameArabic": "سُورَةُ الحَشۡرِ", "surahNameMalayalam": "സൂറത്തുൽ ഹശ്ർ (സംഗമം)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ سَبَّحَ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n", "jalalayn": "«سَبَّحَ لِلَّهِ ما فِي السَّماوات وما فِي الأَرْض» أيْ نَزَّهَهُ فاللّام مَزِيدَة وفِي الإتْيان بِما تَغْلِيب لِلْأَكْثَرِ «وهُوَ العَزِيز الحَكِيم» فِي مُلْكه وصُنْعه", "malayalam": "«ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതുമെല്ലാം അല്ലാഹുവിന്റെ പരിശുദ്ധിയെ പ്രകീർത്തിച്ചിരിക്കുന്നു; അവൻ പ്രതാപിയും പരമയുക്തിമാനുമാകുന്നു».", "malayalamMatn": "ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതും അല്ലാഹുവെ പ്രകീര്‍ത്തനം ചെയ്തിരിക്കുന്നു. അവന്‍ പ്രതാപിയും യുക്തിമാനുമാകുന്നു."}, {"ayahNumber": 2, "quranText": "هُوَ ٱلَّذِیۤ أَخۡرَجَ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ مِن دِیَـٰرِهِمۡ لِأَوَّلِ ٱلۡحَشۡرِۚ مَا ظَنَنتُمۡ أَن یَخۡرُجُوا۟ۖ وَظَنُّوۤا۟ أَنَّهُم مَّانِعَتُهُمۡ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَیۡثُ لَمۡ یَحۡتَسِبُوا۟ۖ وَقَذَفَ فِی قُلُوبِهِمُ ٱلرُّعۡبَۚ یُخۡرِبُونَ بُیُوتَهُم بِأَیۡدِیهِمۡ وَأَیۡدِی ٱلۡمُؤۡمِنِینَ فَٱعۡتَبِرُوا۟ یَـٰۤأُو۟لِی ٱلۡأَبۡصَـٰرِ\n", "jalalayn": "«هُوَ الَّذِي أخَرَجَ الَّذِينَ كَفَرُوا مِن أهْل الكِتاب» هُمْ بَنُو النَّضِير مِن اليَهُود «مِن دِيارهمْ» مَساكِنهمْ بِالمَدِينَةِ «لِأَوَّلِ الحَشْر» هُوَ حَشْرهمْ إلى الشّام وآخِره أنْ أجْلاهُمْ عُمَر فِي خِلافَته إلى خَيْبَر «ما ظَنَنْتُمْ» أيّها المُؤْمِنُونَ «أنْ يَخْرُجُوا وظَنُّوا أنَّهُمْ مانِعَتهمْ» خَبَر أنْ «حُصُونهمْ» فاعِله تَمَّ بِهِ الخَبَر «مِن اللَّه» مِن عَذابه «فَأَتاهُمْ اللَّه» أمْره وعَذابه «مِن حَيْثُ لَمْ يَحْتَسِبُوا» لَمْ يَخْطِر بِبالِهِمْ مِن جِهَة المُؤْمِنِينَ «وقَذَفَ» ألْقى «فِي قُلُوبهمْ الرُّعْب» بِسُكُونِ العَيْن وضَمّها الخَوْف بِقَتْلِ سَيِّدهمْ كَعْب بْن الأَشْرَف «يُخْرِبُونَ» بِالتَّشْدِيدِ والتَّخْفِيف مِن أخْرَبَ «بُيُوتهمْ» لِيَنْقُلُوا ما اسْتَحْسَنُوهُ مِنها مِن خَشَب وغَيْره", "malayalam": "«വേദക്കാരിൽപ്പെട്ട അവിശ്വാസികളെ» (ബനൂ നദീർ ജൂതന്മാരെ) «അവരുടെ ഭവനങ്ങളിൽ നിന്ന് ആദ്യത്തെ നാടുകടത്തലിൽ പുറത്താക്കിയവൻ അവനത്രെ; അവർ പുറത്തുപോകുമെന്ന് നിങ്ങൾ കരുതിയിരുന്നില്ല; തങ്ങളുടെ കോട്ടകൾ അല്ലാഹുവിൽ നിന്ന് തങ്ങളെ സംരക്ഷിക്കുമെന്ന് അവരും വിചാരിച്ചു; എന്നാൽ അവർ കണക്കുകൂട്ടാത്ത ഭാഗത്ത് നിന്ന് അല്ലാഹുവിന്റെ കൽപന അവരുടെ അടുക്കൽ വന്നുചേർന്നു; അവൻ അവരുടെ ഹൃദയങ്ങളിൽ ഭയം ഇട്ടുകൊടുത്തു; അങ്ങനെ അവർ സ്വന്തം കൈകൾ കൊണ്ടും സത്യവിശ്വാസികളുടെ കൈകൾ കൊണ്ടും തങ്ങളുടെ വീടുകൾ പൊളിച്ചു നശിപ്പിക്കുവാൻ തുടങ്ങി; ആകയാൽ ഉൾക്കാഴ്ചയുള്ളവരേ, നിങ്ങൾ ഗുണപാഠം ഉൾക്കൊള്ളുവിൻ!».", "malayalamMatn": "വേദക്കാരില്‍ പെട്ട സത്യനിഷേധികളെ ഒന്നാമത്തെ തുരത്തിയോടിക്കലില്‍ തന്നെ അവരുടെ വീടുകളില്‍ നിന്നു പുറത്തിറക്കിയവന്‍ അവനാകുന്നു. അവര്‍ പുറത്തിറങ്ങുമെന്ന് നിങ്ങള്‍ വിചാരിച്ചിരുന്നില്ല. തങ്ങളുടെ കോട്ടകള്‍ അല്ലാഹുവില്‍ നിന്ന് തങ്ങളെ പ്രതിരോധിക്കുമെന്ന് അവര്‍ വിചാരിച്ചിരുന്നു. എന്നാല്‍ അവര്‍ കണക്കാക്കാത്ത വിധത്തില്‍ അല്ലാഹു അവരുടെ അടുക്കല്‍ ചെല്ലുകയും അവരുടെ മനസ്സുകളില്‍ ഭയം ഇടുകയും ചെയ്തു. അവര്‍ സ്വന്തം കൈകള്‍കൊണ്ടും സത്യവിശ്വാസികളുടെ കൈകള്‍കൊണ്ടും അവരുടെ വീടുകള്‍ നശിപ്പിച്ചിരുന്നു. ആകയാല്‍ കണ്ണുകളുള്ളവരേ, നിങ്ങള്‍ ഗുണപാഠം ഉള്‍കൊള്ളുക."}, {"ayahNumber": 3, "quranText": "وَلَوۡلَاۤ أَن كَتَبَ ٱللَّهُ عَلَیۡهِمُ ٱلۡجَلَاۤءَ لَعَذَّبَهُمۡ فِی ٱلدُّنۡیَاۖ وَلَهُمۡ فِی ٱلۡـَٔاخِرَةِ عَذَابُ ٱلنَّارِ\n", "jalalayn": "«ولَوْلا أنْ كَتَبَ اللَّه» قَضى «عَلَيْهِمْ الجَلاء» الخُرُوج مِن الوَطَن «لَعَذَّبَهُمْ فِي الدُّنْيا» بِالقَتْلِ والسَّبْي كَما فَعَلَ بِقُرَيْظَةَ مِن اليَهُود", "malayalam": "«അവരുടെ മേൽ നാടുകടത്തൽ അല്ലാഹു രേഖപ്പെടുത്തിയിരുന്നില്ലെങ്കിൽ ഇഹലോകത്ത് വെച്ചുതന്നെ അവൻ അവരെ ശിക്ഷിക്കുമായിരുന്നു; പരലോകത്തിലാകട്ടെ അവർക്ക് നരകശിക്ഷയുമുണ്ട്».", "malayalamMatn": "അല്ലാഹു അവരുടെ മേല്‍ നാടുവിട്ടുപോക്ക് വിധിച്ചിട്ടില്ലായിരുന്നുവെങ്കില്‍ ഇഹലോകത്ത് വെച്ച് അവന്‍ അവരെ ശിക്ഷിക്കുമായിരുന്നു.പരലോകത്ത് അവര്‍ക്കു നരകശിക്ഷയുമുണ്ട്‌."}, {"ayahNumber": 4, "quranText": "ذَ ٰ⁠لِكَ بِأَنَّهُمۡ شَاۤقُّوا۟ ٱللَّهَ وَرَسُولَهُۥۖ وَمَن یُشَاۤقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ\n", "jalalayn": "«ذَلِكَ بِأَنَّهُمْ شاقُّوا» خالَفُوا «اللَّه ورَسُوله ومَن يُشاقّ اللَّه فَإنَّ اللَّه شَدِيد العِقاب» لَهُ", "malayalam": "«അവർ അല്ലാഹുവോടും അവന്റെ റസൂലിനോടും എതിർത്തുനിന്നതു കൊണ്ടാകുന്നു അത്; ആരെങ്കിലും അല്ലാഹുവോട് എതിർത്തുനിൽക്കുന്ന പക്ഷം തീർച്ചയായും അല്ലാഹു കഠിനമായി ശിക്ഷിക്കുന്നവനത്രെ».", "malayalamMatn": "അത് അല്ലാഹുവോടും അവന്‍റെ റസൂലിനോടും അവര്‍ മത്സരിച്ചു നിന്നതിന്‍റെ ഫലമത്രെ. വല്ലവനും അല്ലാഹുവുമായി മത്സരിക്കുന്ന പക്ഷം തീര്‍ച്ചയായും അല്ലാഹു കഠിനമായി ശിക്ഷിക്കുന്നവനാകുന്നു."}, {"ayahNumber": 5, "quranText": "مَا قَطَعۡتُم مِّن لِّینَةٍ أَوۡ تَرَكۡتُمُوهَا قَاۤىِٕمَةً عَلَىٰۤ أُصُولِهَا فَبِإِذۡنِ ٱللَّهِ وَلِیُخۡزِیَ ٱلۡفَـٰسِقِینَ\n", "jalalayn": "«ما قَطَعْتُمْ» يا مُسْلِمُونَ «مِن لِينَة» نَخْلَة «أوْ تَرَكْتُمُوها قائِمَة عَلى أُصُولها فَبِإذْنِ اللَّه» أيْ خَيَّرَكُمْ فِي ذَلِكَ «ولِيُخْزِيَ» بِالإذْنِ فِي القَطْع «الفاسِقِينَ» اليَهُود فِي اعْتِراضهمْ أنَّ قَطْع الشَّجَر المُثْمِر فَساد", "malayalam": "«നിങ്ങൾ ഏതൊരു ഈത്തപ്പന വെട്ടിമാറ്റുകയോ, അല്ലെങ്കിൽ അതിന്റെ തായ്ത്തടികളിൽ നിൽക്കാൻ വിടുകയോ ചെയ്തിട്ടുണ്ടെങ്കിൽ അതെല്ലാം അല്ലാഹുവിന്റെ അനുമതി പ്രകാരമാണ്; അധർമ്മകാരികളെ അപമാനിക്കുവാൻ വേണ്ടിയുമത്രെ അത്».", "malayalamMatn": "നിങ്ങള്‍ വല്ല ഈന്തപ്പനയും മുറിക്കുകയോ അല്ലെങ്കില്‍ അവയെ അവയുടെ മുരടുകളില്‍ നില്‍ക്കാന്‍ വിടുകയോ ചെയ്യുന്ന പക്ഷം അത് അല്ലാഹുവിന്‍റെ അനുമതി പ്രകാരമാണ്‌. അധര്‍മ്മകാരികളെ അപമാനപ്പെടുത്തുവാന്‍ വേണ്ടിയുമാണ്‌."}, {"ayahNumber": 6, "quranText": "وَمَاۤ أَفَاۤءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡهُمۡ فَمَاۤ أَوۡجَفۡتُمۡ عَلَیۡهِ مِنۡ خَیۡلࣲ وَلَا رِكَابࣲ وَلَـٰكِنَّ ٱللَّهَ یُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن یَشَاۤءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ\n", "jalalayn": "«وما أفاءَ» رَدَّ «اللَّه عَلى رَسُوله مِنهُمْ فَما أوْجَفْتُمْ» أسْرَعْتُمْ يا مُسْلِمُونَ «عَلَيْهِ مِن» زائِدَة «خَيْل ولا رِكاب» إبِل أيْ لَمْ تُقاسُوا فِيهِ مَشَقَّة «ولَكِنَّ اللَّه يُسَلِّط رُسُله عَلى مَن يَشاء واللَّه عَلى كُلّ شَيْء قَدِير» فَلا حَقّ لَكُمْ فِيهِ ويَخْتَصّ بِهِ النَّبِيّ ﷺ ومَن ذُكِرَ مَعَهُ فِي الآيَة الثّانِيَة مِن الأَصْناف الأَرْبَعَة عَلى ما كانَ يَقْسِمهُ مِن أنَّ لِكُلٍّ مِنهُمْ خُمُس الخُمُس ولَهُ ﷺ الباقِي يَفْعَل فِيهِ ما يَشاء فَأَعْطى مِنهُ المُهاجِرِينَ وثَلاثَة مِن الأَنْصار لِفَقْرِهِمْ", "malayalam": "«അവരിൽ നിന്ന് തന്റെ റസൂലിന് അല്ലാഹു മടക്കിക്കൊടുത്ത ധനത്തിലേക്ക് (ഫൈഅ്) നിങ്ങൾ കുതിരകളെയോ ഒട്ടകങ്ങളെയോ ഓടിച്ചു ചെന്നിട്ടില്ല; എന്നാൽ അല്ലാഹു തന്റെ റസൂലുകൾക്ക് താൻ ഉദ്ദേശിക്കുന്നവരുടെ മേൽ ആധിപത്യം നൽകുന്നു; അല്ലാഹു സർവ്വകാര്യങ്ങൾക്കും കഴിവുള്ളവനത്രെ».", "malayalamMatn": "അവരില്‍ നിന്ന് (യഹൂദരില്‍ നിന്ന്‌) അല്ലാഹു അവന്‍റെ റസൂലിന് കൈവരുത്തി കൊടുത്തതെന്തോ അതിനായി നിങ്ങള്‍ കുതിരകളെയോ ഒട്ടകങ്ങളെയോ ഓടിക്കുകയുണ്ടായിട്ടില്ല.പക്ഷെ, അല്ലാഹു അവന്‍റെ ദൂതന്‍മാരെ അവന്‍ ഉദ്ദേശിക്കുന്നവരുടെ നേര്‍ക്ക് അധികാരപ്പെടുത്തി അയക്കുന്നു. അല്ലാഹു ഏതു കാര്യത്തിനും കഴിവുള്ളവനാകുന്നു."}, {"ayahNumber": 7, "quranText": "مَّاۤ أَفَاۤءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡ أَهۡلِ ٱلۡقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِی ٱلۡقُرۡبَىٰ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینِ وَٱبۡنِ ٱلسَّبِیلِ كَیۡ لَا یَكُونَ دُولَةَۢ بَیۡنَ ٱلۡأَغۡنِیَاۤءِ مِنكُمۡۚ وَمَاۤ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمۡ عَنۡهُ فَٱنتَهُوا۟ۚ وَٱتَّقُوا۟ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ\n", "jalalayn": "«ما أفاءَ اللَّه عَلى رَسُوله مِن أهْل القُرى» كالصَّفْراءِ ووادِي القُرى ويَنْبُع «فَلِلَّهِ» يَأْمُر فِيهِ بِما يَشاء «ولِذِي» صاحِب «القُرْبى» قَرابَة النَّبِيّ مِن بَنِي هاشِم وبَنِي المُطَّلِب «واليَتامى» أطْفال المُسْلِمِينَ الَّذِينَ هَلَكَتْ آباؤُهُمْ وهُمْ فُقَراء «والمَساكِين» ذَوِي الحاجَة مِن المُسْلِمِينَ «وابْن السَّبِيل» المُنْقَطِع فِي سَفَره مِن المُسْلِمِينَ أيْ يَسْتَحِقّهُ النَّبِيّ ﷺ والأَصْناف الأَرْبَعَة. عَلى ما كانَ يَقْسِمهُ مِن أنَّ لِكُلٍّ مِن الأَرْبَعَة خُمُس الخُمُس ولَهُ الباقِي «كَيْ لا» كَيْ بِمَعْنى اللّام وأَنْ مُقَدَّرَة بَعْدها «يَكُون» الفَيْء عِلَّة لِقَسْمِهِ كَذَلِكَ «دُولَة» مُتَداوَلًا «بَيْن الأَغْنِياء مِنكُمْ وما آتاكُمْ الرَّسُول» أعْطاكُمْ مِن الفَيْء وغَيْره", "malayalam": "«വിവിധ നാടുകളിലെ ആളുകളിൽ നിന്ന് അല്ലാഹു തന്റെ റസൂലിന് മടക്കിക്കൊടുത്ത ധനം അല്ലാഹുവിനും അവന്റെ റസൂലിനും അവന്റെ കുടുംബക്കാർക്കും അനാഥകൾക്കും അഗതികൾക്കും വഴിപോക്കർക്കും ഉള്ളതാകുന്നു; നിങ്ങളിലെ സമ്പന്നന്മാർക്കിടയിൽ മാത്രം കറങ്ങിത്തിരിയുന്ന ഒന്നാകാതിരിക്കാൻ വേണ്ടിയത്രെ അത്; റസൂൽ നിങ്ങൾക്ക് നൽകിയതൊക്കെ നിങ്ങൾ സ്വീകരിക്കുക; അവൻ നിങ്ങളോട് വിരോധിച്ചതിൽ നിന്ന് നിങ്ങൾ വിട്ടുനിൽക്കുകയും ചെയ്യുക; നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുവിൻ, തീർച്ചയായും അല്ലാഹു കഠിനമായി ശിക്ഷിക്കുന്നവനത്രെ».", "malayalamMatn": "അല്ലാഹു അവന്‍റെ റസൂലിന് വിവിധ രാജ്യക്കാരില്‍ നിന്ന് കൈവരുത്തി കൊടുത്തതെന്തോ അത് അല്ലാഹുവിനും റസൂലിനും അടുത്ത കുടുംബങ്ങള്‍ക്കും അനാഥകള്‍ക്കും അഗതികള്‍ക്കും വഴിപോക്കര്‍ക്കുമുള്ളതാകുന്നു. അത് (ധനം) നിങ്ങളില്‍ നിന്നുള്ള ധനികന്‍മാര്‍ക്കിടയില്‍ മാത്രം കൈമാറ്റം ചെയ്യപ്പെടുന്ന ഒന്നാവാതിരിക്കാന്‍ വേണ്ടിയാണത്‌. നിങ്ങള്‍ക്കു റസൂല്‍ നല്‍കിയതെന്തോ അത് നിങ്ങള്‍ സ്വീകരിക്കുക. എന്തൊന്നില്‍ നിന്ന് അദ്ദേഹം നിങ്ങളെ വിലക്കിയോ അതില്‍ നിന്ന് നിങ്ങള്‍ ഒഴിഞ്ഞ് നില്‍ക്കുകയും ചെയ്യുക. നിങ്ങള്‍ അല്ലാഹുവെ സൂക്ഷിക്കുകയും ചെയ്യുക. തീര്‍ച്ചയായും അല്ലാഹു കഠിനമായി ശിക്ഷിക്കുന്നവനാണ്‌."}, {"ayahNumber": 8, "quranText": "لِلۡفُقَرَاۤءِ ٱلۡمُهَـٰجِرِینَ ٱلَّذِینَ أُخۡرِجُوا۟ مِن دِیَـٰرِهِمۡ وَأَمۡوَ ٰ⁠لِهِمۡ یَبۡتَغُونَ فَضۡلࣰا مِّنَ ٱللَّهِ وَرِضۡوَ ٰ⁠نࣰا وَیَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥۤۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلصَّـٰدِقُونَ\n", "jalalayn": "«لِلْفُقَراءِ» مُتَعَلِّق بِمَحْذُوفٍ أيْ اعْجَبُوا «المُهاجِرِينَ الَّذِينَ أُخْرِجُوا مِن دِيارهمْ وأَمْوالهمْ يَبْتَغُونَ فَضْلًا مِن اللَّه ورِضْوانًا ويَنْصُرُونَ اللَّه ورَسُوله أُولَئِكَ هُمْ الصّادِقُونَ» فِي إيمانهمْ", "malayalam": "«സ്വന്തം വീടുകളിൽ നിന്നും സ്വത്തുക്കളിൽ നിന്നും പുറന്തള്ളപ്പെട്ട ദരിദ്രരായ മുഹാജിറുകൾക്ക് വേണ്ടിയുള്ളതാകുന്നു അത്; അവർ അല്ലാഹുവിങ്കൽ നിന്നുള്ള ഔദാര്യവും പ്രീതിയും കാംക്ഷിക്കുകയും അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും സഹായിക്കുകയും ചെയ്യുന്നു; അവരത്രെ സത്യസന്ധന്മാർ!».", "malayalamMatn": "അതായത് സ്വന്തം വീടുകളില്‍ നിന്നും സ്വത്തുക്കളില്‍ നിന്നും കുടിയൊഴിപ്പിക്കപ്പെട്ട മുഹാജിറുകളായ ദരിദ്രന്‍മാര്‍ക്ക് (അവകാശപ്പെട്ടതാകുന്നു ആ ധനം.) അവര്‍ അല്ലാഹുവിങ്കല്‍ നിന്നുള്ള അനുഗ്രഹവും പ്രീതിയും തേടുകയും അല്ലാഹുവെയും അവന്‍റെ റസൂലിനെയും സഹായിക്കുകയും ചെയ്യുന്നു. അവര്‍ തന്നെയാകുന്നു സത്യവാന്‍മാര്‍."}, {"ayahNumber": 9, "quranText": "وَٱلَّذِینَ تَبَوَّءُو ٱلدَّارَ وَٱلۡإِیمَـٰنَ مِن قَبۡلِهِمۡ یُحِبُّونَ مَنۡ هَاجَرَ إِلَیۡهِمۡ وَلَا یَجِدُونَ فِی صُدُورِهِمۡ حَاجَةࣰ مِّمَّاۤ أُوتُوا۟ وَیُؤۡثِرُونَ عَلَىٰۤ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةࣱۚ وَمَن یُوقَ شُحَّ نَفۡسِهِۦ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ\n", "jalalayn": "«والَّذِينَ تَبَوَّءُوا الدّار» أيْ المَدِينَة «والإيمان» أيْ ألِفُوهُ وهُمْ الأَنْصار «مِن قَبْلهمْ يُحِبُّونَ مَن هاجَرَ إلَيْهِمْ ولا يَجِدُونَ فِي صُدُورهمْ حاجَة» حَسَدًا «مِمّا أُوتُوا» أيْ آتى النَّبِيّ ﷺ المُهاجِرِينَ مِن أمْوال بَنِي النَّضِير المُخْتَصَّة بِهِمْ «ويُؤْثِرُونَ عَلى أنْفُسهمْ ولَوْ كانَ بِهِمْ خَصاصَة» حاجَة إلى ما يُؤْثِرُونَ بِهِ «ومَن يُوقَ شُحّ نَفْسه» حِرْصها عَلى المال", "malayalam": "«അവർക്ക് മുമ്പായിത്തന്നെ മദീനയിൽ പാർപ്പുറപ്പിക്കുകയും വിശ്വാസം സ്വീകരിക്കുകയും ചെയ്ത അൻസാറുകൾക്കും; തങ്ങളുടെ അടുക്കലേക്ക് പലായനം ചെയ്തു വന്നവരെ അവർ സ്നേഹിക്കുന്നു; അവർക്ക് നൽകപ്പെട്ട ധനത്തെക്കുറിച്ച് തങ്ങളുടെ മനസ്സുകളിൽ യാതൊരു അസൂയയും അവർ കാണുന്നില്ല; തങ്ങൾക്ക് ദാരിദ്ര്യമുണ്ടായാൽ പോലും തങ്ങളേക്കാൾ മറ്റുള്ളവർക്ക് അവർ മുൻഗണന നൽകുന്നു; ആരെങ്കിലും സ്വന്തം മനസ്സിന്റെ പിശുക്കിൽ നിന്ന് കാത്തുരക്ഷിക്കപ്പെടുന്നുവോ അവരത്രെ വിജയം വരിച്ചവർ!».", "malayalamMatn": "അവരുടെ (മുഹാജിറുകളുടെ) വരവിനു മുമ്പായി വാസസ്ഥലവും വിശ്വാസവും സ്വീകരിച്ചുവെച്ചവര്‍ക്കും (അന്‍സാറുകള്‍ക്ക്‌). തങ്ങളുടെ അടുത്തേക്ക് സ്വദേശം വെടിഞ്ഞു വന്നവരെ അവര്‍ സ്നേഹിക്കുന്നു. അവര്‍ക്ക് (മുഹാജിറുകള്‍ക്ക്‌) നല്‍കപ്പെട്ട ധനം സംബന്ധിച്ചു തങ്ങളുടെ മനസ്സുകളില്‍ ഒരു ആവശ്യവും അവര്‍ (അന്‍സാറുകള്‍) കണ്ടെത്തുന്നുമില്ല. തങ്ങള്‍ക്ക് ദാരിദ്യ്‌രമുണ്ടായാല്‍ പോലും സ്വദേഹങ്ങളെക്കാള്‍ മറ്റുള്ളവര്‍ക്ക് അവര്‍ പ്രാധാന്യം നല്‍കുകയും ചെയ്യും. ഏതൊരാള്‍ തന്‍റെ മനസ്സിന്‍റെ പിശുക്കില്‍ നിന്ന് കാത്തുരക്ഷിക്കപ്പെടുന്നുവോ അത്തരക്കാര്‍ തന്നെയാകുന്നു വിജയം പ്രാപിച്ചവര്‍."}, {"ayahNumber": 10, "quranText": "وَٱلَّذِینَ جَاۤءُو مِنۢ بَعۡدِهِمۡ یَقُولُونَ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَ ٰ⁠نِنَا ٱلَّذِینَ سَبَقُونَا بِٱلۡإِیمَـٰنِ وَلَا تَجۡعَلۡ فِی قُلُوبِنَا غِلࣰّا لِّلَّذِینَ ءَامَنُوا۟ رَبَّنَاۤ إِنَّكَ رَءُوفࣱ رَّحِیمٌ\n", "jalalayn": "«والَّذِينَ جاءُوا مِن بَعْدهمْ» مِن بَعْد المُهاجِرِينَ والأَنْصار إلى يَوْم القِيامَة «يَقُولُونَ رَبّنا اغْفِرْ لَنا ولِإخْوانِنا الَّذِينَ سِبْقُونا بِالإيمانِ ولا يَجِدُونَ فِي قُلُوبهمْ غِلًّا» حِقْدًا", "malayalam": "«അവർക്ക് ശേഷം വന്നവർ പറയും: ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾക്കും വിശ്വാസത്തോടെ ഞങ്ങൾക്ക് മുമ്പ് കഴിഞ്ഞുപോയ ഞങ്ങളുടെ സഹോദരങ്ങൾക്കും നീ പൊറുത്തുതരേണമേ! വിശ്വസിച്ചവരോട് ഞങ്ങളുടെ ഹൃദയങ്ങളിൽ യാതൊരു വിദ്വേഷവും നീ ഉണ്ടാക്കരുതേ! ഞങ്ങളുടെ രക്ഷിതാവേ, തീർച്ചയായും നീ അത്യധികം ദയയുള്ളവനും പരമകാരുണികനുമാകുന്നു!».", "malayalamMatn": "അവരുടെ ശേഷം വന്നവര്‍ക്കും. അവര്‍ പറയും: ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങള്‍ക്കും വിശ്വാസത്തോടെ ഞങ്ങള്‍ക്ക് മുമ്പ് കഴിഞ്ഞുപോയിട്ടുള്ള ഞങ്ങളുടെ സഹോദരങ്ങള്‍ക്കും നീ പൊറുത്തുതരേണമേ, സത്യവിശ്വാസം സ്വീകരിച്ചവരോട് ഞങ്ങളുടെ മനസ്സുകളില്‍ നീ ഒരു വിദ്വേഷവും ഉണ്ടാക്കരുതേ. ഞങ്ങളുടെ രക്ഷിതാവേ, തീര്‍ച്ചയായും നീ ഏറെ ദയയുള്ളവനും കരുണാനിധിയുമാകുന്നു"}, {"ayahNumber": 11, "quranText": "۞ أَلَمۡ تَرَ إِلَى ٱلَّذِینَ نَافَقُوا۟ یَقُولُونَ لِإِخۡوَ ٰ⁠نِهِمُ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ لَىِٕنۡ أُخۡرِجۡتُمۡ لَنَخۡرُجَنَّ مَعَكُمۡ وَلَا نُطِیعُ فِیكُمۡ أَحَدًا أَبَدࣰا وَإِن قُوتِلۡتُمۡ لَنَنصُرَنَّكُمۡ وَٱللَّهُ یَشۡهَدُ إِنَّهُمۡ لَكَـٰذِبُونَ\n", "jalalayn": "«ألَمْ تَرَ» تَنْظُر «إلى الَّذِينَ نافَقُوا يَقُولُونَ لِإخْوانِهِمْ الَّذِينَ كَفَرُوا مِن أهْل الكِتاب» وهُمْ بَنُو النَّضِير وإخْوانهمْ فِي الكُفْر «لَئِنْ» لام قَسَم فِي الأَرْبَعَة «أُخْرِجْتُمْ» مِن المَدِينَة «لَنَخْرُجَنَّ مَعَكُمْ ولا نُطِيع فِيكُمْ» فِي خِذْلانكُمْ «أحَدًا أبَدًا وإنْ قُوتِلْتُمْ» حُذِفَتْ مِنهُ اللّام المُوَطِّئَة", "malayalam": "«കപടവിശ്വാസികളെ നീ കണ്ടില്ലയോ? വേദക്കാരിൽപ്പെട്ട തങ്ങളുടെ അവിശ്വാസികളായ സഹോദരങ്ങളോട് അവർ പറയുന്നു: നിങ്ങൾ പുറത്താക്കപ്പെടുകയാണെങ്കിൽ തീർച്ചയായും ഞങ്ങളും നിങ്ങളുടെ കൂടെ പുറപ്പെടും; നിങ്ങളുടെ കാര്യത്തിൽ ഞങ്ങൾ ഒരിക്കലും ഒരാളെയും അനുസരിക്കില്ല; നിങ്ങൾക്കെതിരെ യുദ്ധമുണ്ടായാൽ തീർച്ചയായും ഞങ്ങൾ നിങ്ങളെ സഹായിക്കും; എന്നാൽ അവർ പെരുംകള്ളന്മാരാണെന്ന് അല്ലാഹു സാക്ഷ്യം വഹിക്കുന്നു».", "malayalamMatn": "ആ കാപട്യം കാണിച്ചവരെ നീ കണ്ടില്ലേ? വേദക്കാരില്‍ പെട്ട സത്യനിഷേധികളായ അവരുടെ സഹോദരന്‍മാരോട് അവര്‍ പറയുന്നു: തീര്‍ച്ചയായും നിങ്ങള്‍ പുറത്താക്കപ്പെട്ടാല്‍ ഞങ്ങളും നിങ്ങളുടെ കൂടെ പുറത്ത് പോകുന്നതാണ്‌. നിങ്ങളുടെ കാര്യത്തില്‍ ഞങ്ങള്‍ ഒരിക്കലും ഒരാളെയും അനുസരിക്കുകയില്ല. നിങ്ങള്‍ക്കെതിരില്‍ യുദ്ധമുണ്ടായാല്‍ തീര്‍ച്ചയായും ഞങ്ങള്‍ നിങ്ങളെ സഹായിക്കുന്നതാണ്‌. എന്നാല്‍ തീര്‍ച്ചയായും അവര്‍ കള്ളം പറയുന്നവരാണ് എന്നതിന് അല്ലാഹു സാക്ഷ്യം വഹിക്കുന്നു."}, {"ayahNumber": 12, "quranText": "لَىِٕنۡ أُخۡرِجُوا۟ لَا یَخۡرُجُونَ مَعَهُمۡ وَلَىِٕن قُوتِلُوا۟ لَا یَنصُرُونَهُمۡ وَلَىِٕن نَّصَرُوهُمۡ لَیُوَلُّنَّ ٱلۡأَدۡبَـٰرَ ثُمَّ لَا یُنصَرُونَ\n", "jalalayn": "«لَئِنْ أُخْرِجُوا لا يَخْرُجُونَ مَعَهُمْ ولَئِنْ قُوتِلُوا لا يَنْصُرُونَهُمْ ولَئِنْ نَصَرُوهُمْ» أيْ جاءُوا لِنَصْرِهِمْ «لَيُوَلُّنَّ الأَدْبار» واسْتُغْنِيَ بِجَوابِ القَسَم المُقَدَّر عَنْ جَواب الشَّرْط فِي المَواضِع الخَمْسَة «ثُمَّ لا يُنْصَرُونَ» أيْ اليَهُود", "malayalam": "«അവർ പുറത്താക്കപ്പെട്ടാൽ ഇവർ അവരുടെ കൂടെ പുറപ്പെടുകയില്ല; അവർക്കെതിരെ യുദ്ധമുണ്ടായാൽ ഇവർ അവരെ സഹായിക്കുകയുമില്ല; ഇനി സഹായിക്കാൻ ചെന്നാൽത്തന്നെ അവർ പിന്തിരിഞ്ഞോടും; പിന്നീട് അവർക്ക് യാതൊരു സഹായവും ലഭിക്കുകയുമില്ല».", "malayalamMatn": "അവര്‍ യഹൂദന്‍മാര്‍ പുറത്താക്കപ്പെടുന്ന പക്ഷം ഇവര്‍ (കപടവിശ്വാസികള്‍) അവരോടൊപ്പം പുറത്തുപോകുകയില്ല തന്നെ. അവര്‍ ഒരു യുദ്ധത്തെ നേരിട്ടാല്‍ ഇവര്‍ അവരെ സഹായിക്കുകയുമില്ല. ഇനി ഇവര്‍ അവരെ സഹായിച്ചാല്‍ തന്നെ ഇവര്‍ പിന്തിരിഞ്ഞോടും തീര്‍ച്ച. പിന്നീട് അവര്‍ക്ക് ഒരു സഹായവും ലഭിക്കുകയില്ല."}, {"ayahNumber": 13, "quranText": "لَأَنتُمۡ أَشَدُّ رَهۡبَةࣰ فِی صُدُورِهِم مِّنَ ٱللَّهِۚ ذَ ٰ⁠لِكَ بِأَنَّهُمۡ قَوۡمࣱ لَّا یَفۡقَهُونَ\n", "jalalayn": "«لَأَنْتُمْ أشَدّ رَهْبَة» خَوْفًا «فِي صُدُورهمْ» أيْ المُنافِقِينَ «مِن اللَّه» لِتَأْخِيرِ عَذابه", "malayalam": "«തീർച്ചയായും അവരുടെ ഹൃദയങ്ങളിൽ അല്ലാഹുവെക്കാൾ കൂടുതൽ ഭയം നിങ്ങളോടാണുള്ളത്; അവർ കാര്യം ഗ്രഹിക്കാത്ത ഒരു ജനതയായതുകൊണ്ടാകുന്നു അത്».", "malayalamMatn": "തീര്‍ച്ചയായും അവരുടെ മനസ്സുകളില്‍ അല്ലാഹുവെക്കാള്‍ കൂടുതല്‍ ഭയമുള്ളത് നിങ്ങളെ പറ്റിയാകുന്നു. അവര്‍ കാര്യം ഗ്രഹിക്കാത്ത ഒരു ജനതയായത് കൊണ്ടാകുന്നു അത്‌."}, {"ayahNumber": 14, "quranText": "لَا یُقَـٰتِلُونَكُمۡ جَمِیعًا إِلَّا فِی قُرࣰى مُّحَصَّنَةٍ أَوۡ مِن وَرَاۤءِ جُدُرِۭۚ بَأۡسُهُم بَیۡنَهُمۡ شَدِیدࣱۚ تَحۡسَبُهُمۡ جَمِیعࣰا وَقُلُوبُهُمۡ شَتَّىٰۚ ذَ ٰ⁠لِكَ بِأَنَّهُمۡ قَوۡمࣱ لَّا یَعۡقِلُونَ\n", "jalalayn": "«لا يُقاتِلُونَكُمْ» أيْ اليَهُود «جَمِيعًا» مُجْتَمِعِينَ «إلّا فِي قُرًى مُحَصَّنَة أوْ مِن وراء جِدار» سُور وفِي قِراءَة جُدُر «بَأْسهمْ» حَرْبهمْ «بَيْنهمْ شَدِيد تَحْسَبهُمْ جَمِيعًا» مُجْتَمِعِينَ «وقُلُوبهمْ شَتّى» مُتَفَرِّقَة خِلاف الحُسْبان", "malayalam": "«ഭദ്രമായ കോട്ടകളുള്ള ഗ്രാമങ്ങളിൽ വെച്ചോ മതിലുകൾക്ക് പിന്നിൽ നിന്നോ അല്ലാതെ അവർ ഒന്നിച്ച് നിങ്ങളോട് യുദ്ധം ചെയ്യുകയില്ല; അവർക്കിടയിലുള്ള പോരാട്ടം വളരെ കഠിനമാണ്; അവർ ഒന്നിച്ചുനിൽക്കുന്നവരാണെന്ന് നീ വിചാരിക്കും, എന്നാൽ അവരുടെ ഹൃദയങ്ങൾ ഭിന്നിച്ചതാകുന്നു; അവർ ചിന്തിച്ചു മനസ്സിലാക്കാത്ത ഒരു ജനതയായതുകൊണ്ടാകുന്നു അത്».", "malayalamMatn": "കോട്ടകെട്ടിയ പട്ടണങ്ങളില്‍ വെച്ചോ മതിലുകളുടെ പിന്നില്‍ നിന്നോ അല്ലാതെ അവര്‍ ഒരുമിച്ച് നിങ്ങളോട് യുദ്ധം ചെയ്യുകയില്ല. അവര്‍ തമ്മില്‍ തന്നെയുള്ള പോരാട്ടം കടുത്തതാകുന്നു. അവര്‍ ഒരുമിച്ചാണെന്ന് നീ വിചാരിക്കുന്നു. അവരുടെ ഹൃദയങ്ങള്‍ ഭിന്നിപ്പിലാകുന്നു. അവര്‍ ചിന്തിച്ചു മനസ്സിലാക്കാത്ത ഒരു ജനതയായത് കൊണ്ടത്രെ അത്‌."}, {"ayahNumber": 15, "quranText": "كَمَثَلِ ٱلَّذِینَ مِن قَبۡلِهِمۡ قَرِیبࣰاۖ ذَاقُوا۟ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِیمࣱ\n", "jalalayn": "مَثَلهمْ فِي تَرْك الإيمان «كَمَثَلِ الَّذِينَ مِن قَبْلهمْ قَرِيبًا» بِزَمَنٍ قَرِيب وهُمْ أهْل بَدْر مِن المُشْرِكِينَ «ذاقُوا وبال أمْرهمْ» عُقُوبَته فِي الدُّنْيا مِن القَتْل وغَيْره «ولَهُمْ عَذاب ألِيم» مُؤْلِم فِي الآخِرَة", "malayalam": "«അവർക്ക് തൊട്ടുമുമ്പ് കഴിഞ്ഞുപോയവരെപ്പോലെയാകുന്നു ഇവർ (ബദ്റിലെ മുശ്‌രിക്കുകളെയും ബനൂ ഖൈനുഖാഇനെയും പോലെ); അവർ തങ്ങളുടെ ചെയ്തികളുടെ ദുഷ്ഫലം രുചിച്ചു കഴിഞ്ഞു; അവർക്ക് വേദനാജനകമായ ശിക്ഷയുമുണ്ട്».", "malayalamMatn": "അവര്‍ക്കു മുമ്പ് അടുത്ത് തന്നെ കഴിഞ്ഞുപോയവരുടെ സ്ഥിതി പോലെത്തന്നെ. അവര്‍ ചെയ്തിരുന്ന കാര്യങ്ങളുടെ ദുഷ്ഫലം അവര്‍ ആസ്വദിച്ചു കഴിഞ്ഞു. അവര്‍ക്ക് വേദനയേറിയ ശിക്ഷയുമുണ്ട്‌."}, {"ayahNumber": 16, "quranText": "كَمَثَلِ ٱلشَّیۡطَـٰنِ إِذۡ قَالَ لِلۡإِنسَـٰنِ ٱكۡفُرۡ فَلَمَّا كَفَرَ قَالَ إِنِّی بَرِیۤءࣱ مِّنكَ إِنِّیۤ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَـٰلَمِینَ\n", "jalalayn": "مَثَلهمْ أيْضًا فِي سَماعهمْ مِن المُنافِقِينَ وتَخَلُّفهمْ عَنْهُمْ «كَمَثَلِ الشَّيْطان إذْ قالَ لِلْإنْسانِ اُكْفُرْ فَلَمّا كَفَرَ قالَ إنِّي بَرِيء مِنك إنِّي أخاف اللَّه رَبّ العالَمِينَ» كَذِبًا مِنهُ ورِياء", "malayalam": "«പിശാചിന്റെ ഉപമ പോലെയാകുന്നു ഇത്; അവൻ മനുഷ്യനോട് പറഞ്ഞു: നീ അവിശ്വസിക്കുക! അങ്ങനെ അവൻ അവിശ്വസിച്ചപ്പോൾ പിശാച് പറഞ്ഞു: എനിക്ക് നിന്നോട് യാതൊരു ബാധ്യതയുമില്ല; സർവ്വലോക രക്ഷിതാവായ അല്ലാഹുവിനെ ഞാൻ ഭയപ്പെടുന്നു!».", "malayalamMatn": "പിശാചിന്‍റെ അവസ്ഥ പോലെ തന്നെ. മനുഷ്യനോട്‌, നീ അവിശ്വാസിയാകൂ എന്ന് അവന്‍ പറഞ്ഞ സന്ദര്‍ഭം. അങ്ങനെ അവന്‍ അവിശ്വസിച്ചു കഴിഞ്ഞപ്പോള്‍ അവന്‍ (പിശാച്‌) പറഞ്ഞു: തീര്‍ച്ചയായും ഞാന്‍ നീയുമായുള്ള ബന്ധത്തില്‍ നിന്ന് വിമുക്തനാകുന്നു. തീര്‍ച്ചയായും ലോകരക്ഷിതാവായ അല്ലാഹുവെ ഞാന്‍ ഭയപ്പെടുന്നു."}, {"ayahNumber": 17, "quranText": "فَكَانَ عَـٰقِبَتَهُمَاۤ أَنَّهُمَا فِی ٱلنَّارِ خَـٰلِدَیۡنِ فِیهَاۚ وَذَ ٰ⁠لِكَ جَزَ ٰ⁠ۤؤُا۟ ٱلظَّـٰلِمِینَ\n", "jalalayn": "«فَكانَ عاقِبَتهما» أيْ الغاوِي والمُغْوِي وقُرِئَ بِالرَّفْعِ اسْم كانَ «أنَّهُما فِي النّار خالِدَيْنِ فِيها وذَلِكَ جَزاء الظّالِمِينَ» أيْ الكافِرِينَ", "malayalam": "«അങ്ങനെ അവർ രണ്ടുപേരുടെയും പര്യവസാനം നരകത്തിലാകുക എന്നതായിത്തീർന്നു; അവരതിൽ ശാശ്വതരായിരിക്കും; അതത്രെ അക്രമികൾക്കുള്ള പ്രതിഫലം».", "malayalamMatn": "അങ്ങനെ അവര്‍ ഇരുവരുടെയും പര്യവസാനം അവര്‍ നരകത്തില്‍ നിത്യവാസികളായി കഴിയുക എന്നതായിത്തീര്‍ന്നു. അതത്രെ അക്രമകാരികള്‍ക്കുള്ള പ്രതിഫലം."}, {"ayahNumber": 18, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلۡتَنظُرۡ نَفۡسࣱ مَّا قَدَّمَتۡ لِغَدࣲۖ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِیرُۢ بِمَا تَعۡمَلُونَ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا اتَّقُوا اللَّه ولْتَنْظُرْ نَفْس ما قَدَّمَتْ لِغَدٍ» لِيَوْمِ القِيامَة", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുവിൻ; ഓരോ വ്യക്തിയും താൻ നാളേക്ക് വേണ്ടി എന്താണ് മുൻകൂട്ടി ചെയ്തുവെച്ചിട്ടുള്ളതെന്ന് ചിന്തിച്ചു നോക്കട്ടെ! നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുവിൻ, തീർച്ചയായും നിങ്ങൾ പ്രവർത്തിക്കുന്നതിനെപ്പറ്റി അല്ലാഹു സൂക്ഷ്മമായി അറിയുന്നവനത്രെ».", "malayalamMatn": "സത്യവിശ്വാസികളേ, നിങ്ങള്‍ അല്ലാഹുവെ സൂക്ഷിക്കുക. ഓരോ വ്യക്തിയും താന്‍ നാളെക്ക് വേണ്ടി എന്തൊരു മുന്നൊരുക്കമാണ് ചെയ്തു വെച്ചിട്ടുള്ളതെന്ന് നോക്കിക്കൊള്ളട്ടെ. നിങ്ങള്‍ അല്ലാഹുവെ സൂക്ഷിക്കുക. തീര്‍ച്ചയായും അല്ലാഹു നിങ്ങള്‍ പ്രവര്‍ത്തിക്കുന്നതിനെ പറ്റി സൂക്ഷ്മജ്ഞാനമുള്ളവനാകുന്നു."}, {"ayahNumber": 19, "quranText": "وَلَا تَكُونُوا۟ كَٱلَّذِینَ نَسُوا۟ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَـٰسِقُونَ\n", "jalalayn": "«ولا تَكُونُوا كالَّذِينَ نَسُوا اللَّه» تَرَكُوا طاعَته «فَأَنْساهُمْ أنْفُسهمْ» أنْ يُقَدِّمُوا لَها خَيْرًا", "malayalam": "«അല്ലാഹുവിനെ മറന്നുകളഞ്ഞ ഒരു ജനതയെപ്പോലെ നിങ്ങൾ ആകരുത്; അങ്ങനെ അവൻ അവർക്ക് അവരുടെ സ്വന്തം ശരീരങ്ങളെത്തന്നെ മറപ്പിച്ചു കളഞ്ഞു; അവരത്രെ അധർമ്മകാരികൾ!».", "malayalamMatn": "അല്ലാഹുവെ മറന്നുകളഞ്ഞ ഒരു വിഭാഗത്തെ പോലെ നിങ്ങളാകരുത്‌. തന്‍മൂലം അല്ലാഹു അവര്‍ക്ക് അവരെ പറ്റി തന്നെ ഓര്‍മയില്ലാതാക്കി. അക്കൂട്ടര്‍ തന്നെയാകുന്നു ദുര്‍മാര്‍ഗികള്‍."}, {"ayahNumber": 20, "quranText": "لَا یَسۡتَوِیۤ أَصۡحَـٰبُ ٱلنَّارِ وَأَصۡحَـٰبُ ٱلۡجَنَّةِۚ أَصۡحَـٰبُ ٱلۡجَنَّةِ هُمُ ٱلۡفَاۤىِٕزُونَ\n", "jalalayn": "«لَا یَسۡتَوِیۤ أَصۡحَـٰبُ ٱلنَّارِ وَأَصۡحَـٰبُ ٱلۡجَنَّةِۚ أَصۡحَـٰبُ ٱلۡجَنَّةِ هُمُ ٱلۡفَاۤىِٕزُونَ».", "malayalam": "«നരകാവകാശികളും സ്വർഗ്ഗാവകാശികളും സമമാകുകയില്ല; സ്വർഗ്ഗാവകാശികൾ തന്നെയാണ് വിജയം വരിച്ചവർ».", "malayalamMatn": "നരകാവകാശികളും സ്വര്‍ഗാവകാശികളും സമമാകുകയില്ല. സ്വര്‍ഗാവകാശികള്‍ തന്നെയാകുന്നു വിജയം നേടിയവര്‍."}, {"ayahNumber": 21, "quranText": "لَوۡ أَنزَلۡنَا هَـٰذَا ٱلۡقُرۡءَانَ عَلَىٰ جَبَلࣲ لَّرَأَیۡتَهُۥ خَـٰشِعࣰا مُّتَصَدِّعࣰا مِّنۡ خَشۡیَةِ ٱللَّهِۚ وَتِلۡكَ ٱلۡأَمۡثَـٰلُ نَضۡرِبُهَا لِلنَّاسِ لَعَلَّهُمۡ یَتَفَكَّرُونَ\n", "jalalayn": "«لَوْ أنَزَلْنا هَذا القُرْآن عَلى جَبَل» وجُعِلَ فِيهِ تَمْيِيز كالإنْسانِ «لَرَأَيْته خاشِعًا مُتَصَدِّعًا» مُتَشَقِّقًا «مِن خَشْيَة اللَّه وتِلْكَ الأَمْثال» المَذْكُورَة «نَضْرِبها لِلنّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ» فَيُؤْمِنُونَ", "malayalam": "«ഈ ഖുർആനെ നാം ഒരു പർവ്വതത്തിന്മേലായിരുന്നു അവതരിപ്പിച്ചിരുന്നതെങ്കിൽ, അല്ലാഹുവെക്കുറിച്ചുള്ള ഭയത്താൽ അത് വിനീതമാകുന്നതും പൊട്ടിപ്പിളരുന്നതും നിനക്ക് കാണാമായിരുന്നു; മനുഷ്യർക്ക് ചിന്തിക്കുവാൻ വേണ്ടി നാം ഇത്തരം ഉപമകൾ വിശദീകരിച്ചു കൊടുക്കുന്നു».", "malayalamMatn": "ഈ ഖുര്‍ആനിനെ നാം ഒരു പര്‍വ്വതത്തിന്മേല്‍ അവതരിപ്പിച്ചിരുന്നുവെങ്കില്‍ അത് (പര്‍വ്വതം) വിനീതമാകുന്നതും അല്ലാഹുവെപ്പറ്റിയുള്ള ഭയത്താല്‍ പൊട്ടിപ്പിളരുന്നതും നിനക്കു കാണാമായിരുന്നു. ആ ഉദാഹരണങ്ങള്‍ നാം ജനങ്ങള്‍ക്ക് വേണ്ടി വിവരിക്കുന്നു. അവര്‍ ചിന്തിക്കുവാന്‍ വേണ്ടി."}, {"ayahNumber": 22, "quranText": "هُوَ ٱللَّهُ ٱلَّذِی لَاۤ إِلَـٰهَ إِلَّا هُوَۖ عَـٰلِمُ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِۖ هُوَ ٱلرَّحۡمَـٰنُ ٱلرَّحِیمُ\n", "jalalayn": "«هُوَ اللَّه الَّذِي لا إلَه إلّا هُوَ عالِم الغَيْب والشَّهادَة» السِّرّ والعَلانِيَة", "malayalam": "«അവനത്രെ അല്ലാഹു; അവനല്ലാതെ യാതൊരു ദൈവവുമില്ല; അദൃശ്യവും ദൃശ്യവും അറിയുന്നവനാകുന്നു അവൻ; അവൻ പരമകാരുണികനും കരുണാനിധിയുമാകുന്നു».", "malayalamMatn": "താനല്ലാതെ യാതൊരു ആരാധ്യനുമില്ലാത്തവനായ അല്ലാഹുവാണവന്‍. അദൃശ്യവും ദൃശ്യവും അറിയുന്നവനാകുന്നു അവന്‍. അവന്‍ പരമകാരുണികനും കരുണാനിധിയുമാകുന്നു."}, {"ayahNumber": 23, "quranText": "هُوَ ٱللَّهُ ٱلَّذِی لَاۤ إِلَـٰهَ إِلَّا هُوَ ٱلۡمَلِكُ ٱلۡقُدُّوسُ ٱلسَّلَـٰمُ ٱلۡمُؤۡمِنُ ٱلۡمُهَیۡمِنُ ٱلۡعَزِیزُ ٱلۡجَبَّارُ ٱلۡمُتَكَبِّرُۚ سُبۡحَـٰنَ ٱللَّهِ عَمَّا یُشۡرِكُونَ\n", "jalalayn": "«هُوَ اللَّه الَّذِي لا إلَه إلّا هُوَ المَلِك القُدُّوس» الطّاهِر عَمّا لا يَلِيق بِهِ «السَّلام» ذُو السَّلامَة مِن النَّقائِص «المُؤْمِن» المُصَدِّق رُسُله بِخَلْقِ المُعْجِزَة لَهُمْ «المُهَيْمِن» مِن هَيْمَنَ يُهَيْمِن إذا كانَ رَقِيبًا عَلى الشَّيْء أيْ الشَّهِيد عَلى عِباده بِأَعْمالِهِمْ «العَزِيز» القَوِيّ «الجَبّار» جَبَرَ خَلْقه عَلى ما أرادَ «المُتَكَبِّر» عَمّا لا يَلِيق بِهِ «سُبْحان اللَّه» نَزَّهَ نَفْسه «عَمّا يُشْرِكُونَ» بِهِ", "malayalam": "«അവനത്രെ അല്ലാഹു; അവനല്ലാതെ യാതൊരു ദൈവവുമില്ല; അവൻ സർവ്വാധിപനായ രാജാവും പരിശുദ്ധനും രക്ഷ നൽകുന്നവനും നിർഭയത്വം നൽകുന്നവനും സർവ്വത്തേയും നിരീക്ഷിക്കുന്നവനും പ്രതാപിയും പരമാധികാരമുള്ളവനും മഹത്വമുള്ളവനുമാകുന്നു; അവർ പങ്കുചേർക്കുന്നതിൽ നിന്നെല്ലാം അല്ലാഹു എത്രയോ പരിശുദ്ധൻ!».", "malayalamMatn": "താനല്ലാതെ യാതൊരു ആരാധ്യനുമില്ലാത്തവനായ അല്ലാഹുവാണവന്‍. രാജാധികാരമുള്ളവനും പരമപരിശുദ്ധനും സമാധാനം നല്‍കുന്നവനും അഭയം നല്‍കുന്നവനും മേല്‍നോട്ടം വഹിക്കുന്നവനും പ്രതാപിയും പരമാധികാരിയും മഹത്വമുള്ളവനും ആകുന്നു അവന്‍. അവര്‍ പങ്കുചേര്‍ക്കുന്നതില്‍ നിന്നെല്ലാം അല്ലാഹു എത്രയോ പരിശുദ്ധന്‍!"}, {"ayahNumber": 24, "quranText": "هُوَ ٱللَّهُ ٱلۡخَـٰلِقُ ٱلۡبَارِئُ ٱلۡمُصَوِّرُۖ لَهُ ٱلۡأَسۡمَاۤءُ ٱلۡحُسۡنَىٰۚ یُسَبِّحُ لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n", "jalalayn": "«هُوَ اللَّه الخالِق البارِئ» المُنْشِئ مِن العَدِم «المُصَوِّر لَهُ الأَسْماء الحُسْنى» التِّسْعَة والتِّسْعُونَ الوارِد بِها الحَدِيث والحُسْنى مُؤَنَّث الأَحْسَن «يُسَبِّح لَهُ ما فِي السَّمَوات والأَرْض وهُوَ العَزِيز الحَكِيم» تَقَدَّمَ أوَّلها", "malayalam": "«അവനത്രെ സ്രഷ്ടാവും രൂപകൽപ്പന ചെയ്യുന്നവനും രൂപം നൽകുന്നവനുമായ അല്ലാഹു; അവന്ന് ഏറ്റവും ഉത്തമമായ നാമങ്ങളുണ്ട് (അസ്മാഉൽ ഹുസ്നാ); ആകാശങ്ങളിലും ഭൂമിയിലുമുള്ള സർവ്വ വസ്തുക്കളും അവന്റെ പരിശുദ്ധിയെ പ്രകീർത്തിക്കുന്നു; അവൻ പ്രതാപിയും പരമയുക്തിമാനുമാകുന്നു».", "malayalamMatn": "സ്രഷ്ടാവും നിര്‍മാതാവും രൂപം നല്‍കുന്നവനുമായ അല്ലാഹുവത്രെ അവന്‍. അവന് ഏറ്റവും ഉത്തമമായ നാമങ്ങളുണ്ട്‌. ആകാശങ്ങളിലും ഭൂമിയിലുള്ളവ അവന്‍റെ മഹത്വത്തെ പ്രകീര്‍ത്തിക്കുന്നു. അവനത്രെ പ്രതാപിയും യുക്തിമാനും."}], "topPoints": ["ബനൂ നദീർ ഗോത്രത്തിന്റെ നാടുകടത്തൽ (خلاصة السورة)", "അല്ലാഹുവിന്റെ മനോഹരമായ നാമങ്ങളുടെ (അസ്മാഉൽ ഹുസ്ന) വിവരണം"], "topQuestions": [{"q": "ഈ സൂറത്തിന്റെ അവസാനം എന്തിനെക്കുറിച്ചാണ് പറയുന്നത്?", "a": "അല്ലാഹുവിന്റെ മഹത്തായ നാമങ്ങളെയും ഗുണങ്ങളെയും കുറിച്ച്."}], "asbabAlNuzul": [{"ayahNumber": 2, "quranText": "هُوَ ٱلَّذِیۤ أَخۡرَجَ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ مِن دِیَـٰرِهِمۡ لِأَوَّلِ ٱلۡحَشۡرِۚ", "arabicSnippet": "نزلت سورة الحشر في يهود بني النضير حين نقضوا العهد وظاهروا قريشا فأجلاهم النبي ﷺ من ديارهم بالمدينة إلى الشام... ولذلك سميت سورة بني النضير.", "malayalamExplanation": "മദീനയിലെ യഹൂദ ഗോത്രമായ ബനൂ നദീർ നബി ﷺ യുമായുണ്ടാക്കിയ സമാധാന ഉടമ്പടി ലംഘിക്കുകയും, നബിയെ വധിക്കാൻ രഹസ്യ ഗൂഢാലോചന നടത്തുകയും, മക്കയിലെ മുശ്‌രിക്കുകളുമായി കൈകോർക്കുകയും ചെയ്തപ്പോൾ അവരെ കോട്ടകളിൽ നിന്ന് ഉപരോധിച്ച് മദീനയിൽ നിന്ന് നാടുകടത്താൻ കൽപിച്ചു. ഈ ചരിത്ര പശ്ചാത്തലത്തിലാണ് സൂറത്തുൽ ഹശ്ർ മുഴുവനായി അവതരിച്ചത്. അതിനാൽ ഇബ്നു അബ്ബാസ് (റ) ഇതിനെ 'സൂറത്തു ബനീ നദീർ' എന്ന് വിളിച്ചു."}]}, {"surahNumber": 60, "surahNameArabic": "سُورَةُ المُمۡتَحنَةِ", "surahNameMalayalam": "സൂറത്തുൽ മുംതഹിന (പരീക്ഷിക്കപ്പെടുന്നവൾ)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّی وَعَدُوَّكُمۡ أَوۡلِیَاۤءَ تُلۡقُونَ إِلَیۡهِم بِٱلۡمَوَدَّةِ وَقَدۡ كَفَرُوا۟ بِمَا جَاۤءَكُم مِّنَ ٱلۡحَقِّ یُخۡرِجُونَ ٱلرَّسُولَ وَإِیَّاكُمۡ أَن تُؤۡمِنُوا۟ بِٱللَّهِ رَبِّكُمۡ إِن كُنتُمۡ خَرَجۡتُمۡ جِهَـٰدࣰا فِی سَبِیلِی وَٱبۡتِغَاۤءَ مَرۡضَاتِیۚ تُسِرُّونَ إِلَیۡهِم بِٱلۡمَوَدَّةِ وَأَنَا۠ أَعۡلَمُ بِمَاۤ أَخۡفَیۡتُمۡ وَمَاۤ أَعۡلَنتُمۡۚ وَمَن یَفۡعَلۡهُ مِنكُمۡ فَقَدۡ ضَلَّ سَوَاۤءَ ٱلسَّبِیلِ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا لا تَتَّخِذُوا عَدُوِّي وعَدُوّكُمْ» أيْ كُفّار مَكَّة «أوْلِياء تُلْقُونَ» تُوَصِّلُونَ «إلَيْهِمْ» قَصْد النَّبِيّ ﷺ غَزْوهمْ الَّذِي أسَرَّهُ إلَيْكُمْ ووَرّى بِحَنِينٍ «بِالمَوَدَّةِ» بَيْنكُمْ وبَيْنهمْ كَتَبَ حاطِب بْن أبِي بَلْتَعَةَ إلَيْهِمْ كِتابًا بِذَلِكَ لِما لَهُ عِنْدهمْ مِن الأَوْلاد والأَهْل المُشْرِكِينَ فاسْتَرَدَّهُ النَّبِيّ ﷺ مِمَّنْ أرْسَلَهُ مَعَهُ بِإعْلامِ اللَّه تَعالى لَهُ بِذَلِكَ وقَبِلَ عُذْر حاطِب فِيهِ «وقَدْ كَفَرُوا بِما جاءَكُمْ مِن الحَقّ» أيْ دِين الإسْلام والقُرْآن «يُخْرِجُونَ الرَّسُول وإيّاكُمْ» مِن مَكَّة بِتَضْيِيقِهِمْ عَلَيْكُمْ «أنْ تُؤْمِنُوا» أيْ لِأَجْلِ أنْ آمَنتُمْ «بِاللَّهِ رَبّكُمْ إنْ كُنْتُمْ خَرَجْتُمْ جِهادًا» لِلْجِهادِ «فِي سَبِيلِي وابْتِغاء مَرْضاتِي» وجَواب الشَّرْط دَلَّ عَلَيْهِ ما قَبْله أيْ فَلا تَتَّخِذُوهُمْ أوْلِياء «تُسِرُّونَ إلَيْهِمْ بِالمَوَدَّةِ وأَنا أعْلَم بِما أخْفَيْتُمْ وما أعْلَنْتُمْ ومَن يَفْعَلهُ مِنكُمْ» أيْ إسْرار خَبَر النَّبِيّ إلَيْهِمْ «فَقَدْ ضَلَّ سَواء السَّبِيل» أخْطَأَ طَرِيق الهُدى والسَّواء فِي الأَصْل الوَسَط", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, എന്റെ ശത്രുവിനെയും നിങ്ങളുടെ ശത്രുവിനെയും നിങ്ങൾ മിത്രങ്ങളാക്കരുത്; നിങ്ങൾ അവരിലേക്ക് സ്നേഹസന്ദേശം എത്തിച്ചുകൊടുക്കുന്നു (ഹാതിബ് ബ്നു അബീ ബൽതഅ മക്കയിലെ മുശ്‌രിക്കുകൾക്ക് കത്തെഴുതിയ സംഭവത്തിൽ ഇത് അവതരിച്ചു); നിങ്ങളിലേക്ക് വന്നെത്തിയ സത്യത്തിൽ അവർ അവിശ്വസിച്ചിരിക്കെ! നിങ്ങൾ നിങ്ങളുടെ രക്ഷിതാവായ അല്ലാഹുവിൽ വിശ്വസിച്ചതിന്റെ പേരിൽ റസൂലിനെയും നിങ്ങളെയും അവർ പുറത്താക്കുന്നു; എന്റെ മാർഗ്ഗത്തിലുള്ള പോരാട്ടത്തിനും എന്റെ പ്രീതി തേടുന്നതിനുമായി നിങ്ങൾ പുറപ്പെട്ടിട്ടുള്ളതാണെങ്കിൽ അവരെ നിങ്ങൾ മിത്രങ്ങളാക്കരുത്; നിങ്ങൾ അവരിലേക്ക് സ്നേഹം രഹസ്യമാക്കുന്നു, എന്നാൽ നിങ്ങൾ മറച്ചുവെച്ചതും പരസ്യമാക്കിയതുമെല്ലാം ഞാൻ ഏറ്റവും നന്നായി അറിയുന്നവനാകുന്നു; നിങ്ങളിൽ നിന്ന് ആരെങ്കിലും അത് ചെയ്യുകയാണെങ്കിൽ തീർച്ചയായും അവൻ നേർവഴിയിൽ നിന്ന് വ്യതിചലിച്ചു കഴിഞ്ഞു».", "malayalamMatn": "ഹേ; സത്യവിശ്വാസികളേ, എന്‍റെ ശത്രുവും നിങ്ങളുടെ ശത്രുവും ആയിട്ടുള്ളവരോട് സ്നേഹബന്ധം സ്ഥാപിച്ച് കൊണ്ട് നിങ്ങള്‍ അവരെ മിത്രങ്ങളാക്കി വെക്കരുത്‌. നിങ്ങള്‍ക്കു വന്നുകിട്ടിയിട്ടുള്ള സത്യത്തില്‍ അവര്‍ അവിശ്വസിച്ചിരിക്കുകയാണ്‌. നിങ്ങള്‍ നിങ്ങളുടെ രക്ഷിതാവായ അല്ലാഹുവില്‍ വിശ്വസിക്കുന്നതിനാല്‍ റസൂലിനെയും നിങ്ങളെയും അവര്‍ നാട്ടില്‍ നിന്നു പുറത്താക്കുന്നു. എന്‍റെ മാര്‍ഗത്തില്‍ സമരം ചെയ്യുവാനും എന്‍റെ പ്രീതിതേടുവാനും നിങ്ങള്‍ പുറപ്പെട്ടിരിക്കുകയാണെങ്കില്‍ (നിങ്ങള്‍ അപ്രകാരം മൈത്രീ ബന്ധം സ്ഥാപിക്കരുത്‌.) നിങ്ങള്‍ അവരുമായി രഹസ്യമായി സ്നേഹബന്ധം സ്ഥാപിക്കുന്നു. നിങ്ങള്‍ രഹസ്യമാക്കിയതും പരസ്യമാക്കിയതും ഞാന്‍ നല്ലവണ്ണം അറിയുന്നവനാണ്‌. നിങ്ങളില്‍ നിന്ന് വല്ലവനും അപ്രകാരം പ്രവര്‍ത്തിക്കുന്ന പക്ഷം അവന്‍ നേര്‍മാര്‍ഗത്തില്‍ നിന്ന് പിഴച്ചു പോയിരിക്കുന്നു."}, {"ayahNumber": 2, "quranText": "إِن یَثۡقَفُوكُمۡ یَكُونُوا۟ لَكُمۡ أَعۡدَاۤءࣰ وَیَبۡسُطُوۤا۟ إِلَیۡكُمۡ أَیۡدِیَهُمۡ وَأَلۡسِنَتَهُم بِٱلسُّوۤءِ وَوَدُّوا۟ لَوۡ تَكۡفُرُونَ\n", "jalalayn": "«إنْ يَثْقَفُوكُمْ» يَظْفَرُوا بِكُمْ «يَكُونُوا لَكُمْ أعْداء ويَبْسُطُوا إلَيْكُمْ أيْدِيهمْ» بِالقَتْلِ والضَّرْب «وأَلْسِنَتهمْ بِالسُّوءِ» بِالسَّبِّ والشَّتْم «ووَدُّوا» تَمَنَّوْا", "malayalam": "«അവർ നിങ്ങളെ കണ്ടുമുട്ടുകയാണെങ്കിൽ അവർ നിങ്ങൾക്ക് ശത്രുക്കളായിത്തീരും; ദ്രോഹബുദ്ധ്യാ അവർ തങ്ങളുടെ കൈകളും നാവുകളും നിങ്ങളുടെ നേരെ നീട്ടും; നിങ്ങൾ അവിശ്വാസികളായിത്തീരണമെന്ന് അവർ അത്യധികം കൊതിക്കുകയും ചെയ്യും».", "malayalamMatn": "അവര്‍ നിങ്ങളെ കണ്ടുമുട്ടുന്ന പക്ഷം അവര്‍ നിങ്ങള്‍ക്ക് ശത്രുക്കളായിരിക്കും. നിങ്ങളുടെ നേര്‍ക്ക് ദുഷ്ടതയും കൊണ്ട് അവരുടെ കൈകളും നാവുകളും അവര്‍ നീട്ടുകയും നിങ്ങള്‍ അവിശ്വസിച്ചിരുന്നെങ്കില്‍ എന്ന് അവര്‍ ആഗ്രഹിക്കുകയും ചെയ്യും."}, {"ayahNumber": 3, "quranText": "لَن تَنفَعَكُمۡ أَرۡحَامُكُمۡ وَلَاۤ أَوۡلَـٰدُكُمۡۚ یَوۡمَ ٱلۡقِیَـٰمَةِ یَفۡصِلُ بَیۡنَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرࣱ\n", "jalalayn": "«لَنْ تَنْفَعكُمْ أرْحامكُمْ» قَراباتكُمْ «ولا أوْلادكُمْ» المُشْرِكُونَ الَّذِينَ لِأَجْلِهِمْ أسْرَرْتُمْ الخَبَر مِن العَذاب فِي الآخِرَة «يَوْم القِيامَة يَفْصِل» بِالبِناءِ لِلْمَفْعُولِ والفاعِل «بَيْنكُمْ» بَيْنكُمْ وبَيْنهمْ فَتَكُونُونَ فِي الجَنَّة وهُمْ فِي جُمْلَة الكُفّار فِي النّار", "malayalam": "«നിങ്ങളുടെ കുടുംബബന്ധങ്ങളോ നിങ്ങളുടെ സന്താനങ്ങളോ അന്ത്യദിനത്തിൽ നിങ്ങൾക്ക് ഒട്ടും ഉപകരിക്കുകയില്ല; അവൻ നിങ്ങൾക്കിടയിൽ വേർതിരിവ് ഉണ്ടാക്കും; നിങ്ങൾ പ്രവർത്തിക്കുന്നതെല്ലാം അല്ലാഹു കണ്ടറിയുന്നവനത്രെ».", "malayalamMatn": "ഉയിര്‍ത്തെഴുന്നേല്‍പിന്‍റെ നാളില്‍ നിങ്ങളുടെ രക്ത ബന്ധങ്ങളോ നിങ്ങളുടെ സന്താനങ്ങളോ നിങ്ങള്‍ക്ക് പ്രയോജനപ്പെടുകയില്ല തന്നെ. അല്ലാഹു നിങ്ങളെ തമ്മില്‍ വേര്‍പിരിക്കും. അല്ലാഹു നിങ്ങള്‍ പ്രവര്‍ത്തിക്കുന്നത് കണ്ടറിയുന്നവനാകുന്നു."}, {"ayahNumber": 4, "quranText": "قَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةࣱ فِیۤ إِبۡرَ ٰ⁠هِیمَ وَٱلَّذِینَ مَعَهُۥۤ إِذۡ قَالُوا۟ لِقَوۡمِهِمۡ إِنَّا بُرَءَ ٰۤ⁠ ؤُا۟ مِنكُمۡ وَمِمَّا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ كَفَرۡنَا بِكُمۡ وَبَدَا بَیۡنَنَا وَبَیۡنَكُمُ ٱلۡعَدَ ٰ⁠وَةُ وَٱلۡبَغۡضَاۤءُ أَبَدًا حَتَّىٰ تُؤۡمِنُوا۟ بِٱللَّهِ وَحۡدَهُۥۤ إِلَّا قَوۡلَ إِبۡرَ ٰ⁠هِیمَ لِأَبِیهِ لَأَسۡتَغۡفِرَنَّ لَكَ وَمَاۤ أَمۡلِكُ لَكَ مِنَ ٱللَّهِ مِن شَیۡءࣲۖ رَّبَّنَا عَلَیۡكَ تَوَكَّلۡنَا وَإِلَیۡكَ أَنَبۡنَا وَإِلَیۡكَ ٱلۡمَصِیرُ\n", "jalalayn": "«قَدْ كانَتْ لَكُمْ إسْوَة» بِكَسْرِ الهَمْزَة وضَمّها فِي المَوْضِعَيْنِ قُدْوَة «حَسَنَة فِي إبْراهِيم» أيْ بِهِ قَوْلًا وفِعْلًا «والَّذِينَ مَعَهُ» مِن المُؤْمِنِينَ «إذْ قالُوا لِقَوْمِهِمْ إنّا بُرَآء» جَمْع بَرِيء كَظَرِيفٍ «مِنكُمْ ومِمّا تَعْبُدُونَ مِن دُون اللَّه كَفَرْنا بِكُمْ» أنْكَرْناكُمْ «وبَدا بَيْننا وبَيْنكُمْ العَداوَة والبَغْضاء أبَدًا» بِتَحْقِيقِ الهَمْزَتَيْنِ وإبْدال الثّانِيَة واوًا «حَتّى تُؤْمِنُوا بِاللَّهِ وحْده إلّا قَوْل إبْراهِيم لِأَبِيهِ لَأَسْتَغْفِرَن لَك» مُسْتَثْنى مِن أُسْوَة فَلَيْسَ لَكُمْ التَّأَسِّي بِهِ فِي ذَلِكَ بِأَنْ تَسْتَغْفِرُوا لِلْكُفّارِ وقَوْله «وما أمْلِك لَك مِن اللَّه» أيْ مِن عَذابه وثَوابه «مِن شَيْء» كَنّى بِهِ عَنْ أنَّهُ لا يَمْلِك لَهُ غَيْر الِاسْتِغْفار فَهُوَ مَبْنِيّ عَلَيْهِ مُسْتَثْنى مِن حَيْثُ المُراد مِنهُ وإنْ كانَ مِن حَيْثُ ظاهِره مِمّا يُتَأَسّى فِيهِ «قُلْ فَمَن يَمْلِك لَكُمْ مِن اللَّه شَيْئًا» واسْتِغْفاره لَهُ قَبْل أنْ يَتَبَيَّن لَهُ أنَّهُ عَدُوّ لِلَّهِ كَما ذَكَرَهُ فِي \"بَراءَة\" «رَبّنا عَلَيْك تَوَكَّلْنا وإلَيْك أنَبْنا وإلَيْك المَصِير» مِن مَقُول الخَلِيل ومَن مَعَهُ أيْ قالُوا:", "malayalam": "«തീർച്ചയായും നിങ്ങൾക്ക് ഇബ്രാഹീമിലും അദ്ദേഹത്തോടൊപ്പമുള്ളവരിലും ഉത്തമമായ ഒരു മാതൃകയുണ്ടായിരുന്നു; അവർ തങ്ങളുടെ ജനതയോട് പറഞ്ഞ സന്ദർഭം: നിങ്ങളിൽ നിന്നും അല്ലാഹുവിന് പുറമെ നിങ്ങൾ ആരാധിക്കുന്നവയിൽ നിന്നും തീർച്ചയായും ഞങ്ങൾ പൂർണ്ണമായി ഒഴിഞ്ഞുമാറിയിരിക്കുന്നു; നിങ്ങളിൽ ഞങ്ങൾ അവിശ്വസിച്ചിരിക്കുന്നു; നിങ്ങൾ അല്ലാഹുവിൽ മാത്രം വിശ്വസിക്കുന്നതുവരെ ഞങ്ങൾക്കും നിങ്ങൾക്കുമിടയിൽ ശത്രുതയും വിദ്വേഷവും എന്നെന്നേക്കുമായി പ്രത്യക്ഷപ്പെട്ടിരിക്കുന്നു; തന്റെ പിതാവിനോട് ഇബ്രാഹീം പറഞ്ഞ വാക്കഴികെ: ഞാൻ താങ്കൾക്കായി പാപമോചനം തേടാം (ഇത് വിശ്വാസികൾ മാതൃകയാക്കേണ്ടതില്ല). ഞങ്ങളുടെ രക്ഷിതാവേ, നിന്നിൽ ഞങ്ങൾ ഭരമേൽപിക്കുകയും നിങ്കലേക്ക് ഞങ്ങൾ ഖേദിച്ചു മടങ്ങുകയും ചെയ്തിരിക്കുന്നു; നിങ്കലേക്ക് തന്നെയാണ് തിരിച്ചുവരവ്!».", "malayalamMatn": "നിങ്ങള്‍ക്ക് ഇബ്രാഹീമിലും അദ്ദേഹത്തിന്‍റെ കൂടെയുള്ളവരിലും ഉത്തമമായ ഒരു മാതൃക ഉണ്ടായിട്ടുണ്ട്‌. അവര്‍ തങ്ങളുടെ ജനതയോട് ഇപ്രകാരം പറഞ്ഞ സന്ദര്‍ഭം: നിങ്ങളുമായും അല്ലാഹുവിന് പുറമെ നിങ്ങള്‍ ആരാധിക്കുന്നവയുമായുള്ള ബന്ധത്തില്‍ നിന്നു തീര്‍ച്ചയായും ഞങ്ങള്‍ ഒഴിവായവരാകുന്നു. നിങ്ങളില്‍ ഞങ്ങള്‍ അവിശ്വസിച്ചിരിക്കുന്നു. നിങ്ങള്‍ അല്ലാഹുവില്‍ മാത്രം വിശ്വസിക്കുന്നത് വരെ എന്നെന്നേക്കുമായി ഞങ്ങളും നിങ്ങളും തമ്മില്‍ ശത്രുതയും വിദ്വേഷവും പ്രകടമാവുകയും ചെയ്തിരിക്കുന്നു. തീര്‍ച്ചയായും ഞാന്‍ താങ്കള്‍ക്ക് വേണ്ടി പാപമോചനം തേടാം, താങ്കള്‍ക്ക് വേണ്ടി അല്ലാഹുവിങ്കല്‍ നിന്ന് യാതൊന്നും എനിക്ക് അധീനപ്പെടുത്താനാവില്ല എന്ന് ഇബ്രാഹീം തന്‍റെ പിതാവിനോട് പറഞ്ഞ വാക്കൊഴികെ. (അവര്‍ ഇപ്രകാരം പ്രാര്‍ത്ഥിച്ചിരുന്നു:) ഞങ്ങളുടെ രക്ഷിതാവേ, നിന്‍റെ മേല്‍ ഞങ്ങള്‍ ഭരമേല്‍പിക്കുകയും, നിങ്കലേക്ക് ഞങ്ങള്‍ മടങ്ങുകയും ചെയ്തിരിക്കുന്നു. നിങ്കലേക്ക് തന്നെയാണ് തിരിച്ചുവരവ്‌."}, {"ayahNumber": 5, "quranText": "رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةࣰ لِّلَّذِینَ كَفَرُوا۟ وَٱغۡفِرۡ لَنَا رَبَّنَاۤۖ إِنَّكَ أَنتَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n", "jalalayn": "«رَبّنا لا تَجْعَلنا فِتْنَة لِلَّذِينَ كَفَرُوا» أيْ لا تُظْهِرهُمْ عَلَيْنا فَيَظُنُّوا أنَّهُمْ عَلى الحَقّ فَيُفْتَنُوا أيْ تَذْهَب عُقُولهمْ بِنا «واغْفِرْ لَنا رَبّنا إنّك أنْتَ العَزِيز الحَكِيم» فِي مُلْكك وصُنْعك", "malayalam": "«ഞങ്ങളുടെ രക്ഷിതാവേ, അവിശ്വാസികൾക്ക് നീ ഞങ്ങളെ ഒരു പരീക്ഷണമാക്കരുതേ! ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾക്ക് നീ പൊറുത്തുതരേണമേ! തീർച്ചയായും നീ തന്നെയാണ് പ്രതാപിയും പരമയുക്തിമാനും!».", "malayalamMatn": "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങളെ സത്യനിഷേധികളുടെ പരീക്ഷണത്തിന് ഇരയാക്കരുതേ. ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങള്‍ക്ക് നീ പൊറുത്തുതരികയും ചെയ്യേണമേ. തീര്‍ച്ചയായും നീ തന്നെയാണ് പ്രതാപിയും യുക്തിമാനും"}, {"ayahNumber": 6, "quranText": "لَقَدۡ كَانَ لَكُمۡ فِیهِمۡ أُسۡوَةٌ حَسَنَةࣱ لِّمَن كَانَ یَرۡجُوا۟ ٱللَّهَ وَٱلۡیَوۡمَ ٱلۡـَٔاخِرَۚ وَمَن یَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ\n", "jalalayn": "«لَقَدْ كانَ لَكُمْ» يا أُمَّة مُحَمَّد جَواب قَسَم مُقَدَّر «فِيهِمْ أُسْوَة حَسَنَة لِمَن كانَ» بَدَل اشْتِمال مِن كَمْ بِإعادَةِ الجار «يَرْجُوا اللَّه واليَوْم الآخِر» أيْ يَخافهُما أوْ يَظُنّ الثَّواب والعِقاب «ومَن يَتَوَلَّ» بِأَنْ يُوالِي الكُفّار «فَإنَّ اللَّه هُوَ الغَنِيّ» عَنْ خَلْقه «الحَمِيد» لِأَهْلِ طاعَته", "malayalam": "«തീർച്ചയായും നിങ്ങൾക്ക് അവരിൽ ഉത്തമമായ മാതൃകയുണ്ടായിരുന്നു; അല്ലാഹുവെയും അന്ത്യദിനത്തെയും പ്രതീക്ഷിക്കുന്നവർക്ക്; ആരെങ്കിലും തിരിഞ്ഞുകളയുകയാണെങ്കിൽ തീർച്ചയായും അല്ലാഹു സർവ്വ ആശ്രയങ്ങളിൽ നിന്നും മുക്തനും സ്തുത്യർഹനുമാകുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും നിങ്ങള്‍ക്ക് -അല്ലാഹുവെയും അന്ത്യദിനത്തെയും പ്രതീക്ഷിക്കുന്നവര്‍ക്ക് -അവരില്‍ ഉത്തമ മാതൃകയുണ്ടായിട്ടുണ്ട്‌. ആരെങ്കിലും തിരിഞ്ഞുകളയുന്ന പക്ഷം തീര്‍ച്ചയായും അല്ലാഹു തന്നെയാകുന്നു പരാശ്രയമുക്തനും സ്തുത്യര്‍ഹനുമായിട്ടുള്ളവന്‍."}, {"ayahNumber": 7, "quranText": "۞ عَسَى ٱللَّهُ أَن یَجۡعَلَ بَیۡنَكُمۡ وَبَیۡنَ ٱلَّذِینَ عَادَیۡتُم مِّنۡهُم مَّوَدَّةࣰۚ وَٱللَّهُ قَدِیرࣱۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ\n", "jalalayn": "«عَسى اللَّه أنْ يَجْعَل بَيْنكُمْ وبَيْن الَّذِينَ عادَيْتُمْ مِنهُمْ» مِن كُفّار مَكَّة طاعَة لِلَّهِ تَعالى «مَوَدَّة» بِأَنْ يَهْدِيهِمْ لِلْإيمانِ فَيَصِيرُوا لَكُمْ أوْلِياء «واللَّه قَدِير» عَلى ذَلِكَ وقَدْ فَعَلَهُ بَعْد فَتْح مَكَّة «واللَّه غَفُور» لَهُمْ ما سَلَفَ «رَحِيم» بِهِمْ", "malayalam": "«നിങ്ങൾക്കും അവരിൽ നിന്ന് നിങ്ങൾ ശത്രുത പുലർത്തിയവർക്കുമിടയിൽ അല്ലാഹു സൗഹൃദം ഉണ്ടാക്കിയേക്കാം (മക്കാ വിജയത്തിൽ അവർ ഇസ്ലാം സ്വീകരിച്ചതുപോലെ); അല്ലാഹു സർവ്വശക്തനാകുന്നു; അല്ലാഹു ഏറെ പൊറുക്കുന്നവനും ദയാപരനുമാകുന്നു».", "malayalamMatn": "നിങ്ങള്‍ക്കും അവരില്‍ നിന്ന് നിങ്ങള്‍ ശത്രുത പുലര്‍ത്തിയവര്‍ക്കുമിടയില്‍ അല്ലാഹു സ്നേഹബന്ധമുണ്ടാക്കിയേക്കാം. അല്ലാഹു കഴിവുള്ളവനാണ്‌. അല്ലാഹു ഏറെ പൊറുക്കുന്നവനും കരുണാനിധിയുമാകുന്നു."}, {"ayahNumber": 8, "quranText": "لَّا یَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِینَ لَمۡ یُقَـٰتِلُوكُمۡ فِی ٱلدِّینِ وَلَمۡ یُخۡرِجُوكُم مِّن دِیَـٰرِكُمۡ أَن تَبَرُّوهُمۡ وَتُقۡسِطُوۤا۟ إِلَیۡهِمۡۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُقۡسِطِینَ\n", "jalalayn": "«لا يَنْهاكُمْ اللَّه عَنْ الَّذِينَ لَمْ يُقاتِلُوكُمْ» مِن الكُفّار «فِي الدِّين ولَمْ يُخْرِجُوكُمْ مِن دِياركُمْ أنْ تَبَرُّوهُمْ» بَدَل اشْتِمال مِن الَّذِينَ «وتُقْسِطُوا» تَقْضُوا «إلَيْهِمْ» بِالقِسْطِ أيْ بِالعَدْلِ وهَذا قَبْل الأَمْر بِجِهادِهِمْ «إنّ اللَّه يُحِبّ المُقْسِطِينَ» العادِلِينَ", "malayalam": "«മതകാര്യത്തിൽ നിങ്ങളോട് യുദ്ധം ചെയ്യാതിരിക്കുകയും നിങ്ങളുടെ വീടുകളിൽ നിന്ന് നിങ്ങളെ പുറത്താക്കാതിരിക്കുകയും ചെയ്തവരോട് നന്മ ചെയ്യുന്നതിലും നീതി കാണിക്കുന്നതിലും അല്ലാഹു നിങ്ങളെ വിലക്കുന്നില്ല; തീർച്ചയായും നീതി കാണിക്കുന്നവരെ അല്ലാഹു ഇഷ്ടപ്പെടുന്നു».", "malayalamMatn": "മതകാര്യത്തില്‍ നിങ്ങളോട് യുദ്ധം ചെയ്യാതിരിക്കുകയും, നിങ്ങളുടെ വീടുകളില്‍ നിന്ന് നിങ്ങളെ പുറത്താക്കാതിരിക്കുകയും ചെയ്യുന്നവരെ സംബന്ധിച്ചിടത്തോളം നിങ്ങളവര്‍ക്ക് നന്‍മ ചെയ്യുന്നതും നിങ്ങളവരോട് നീതി കാണിക്കുന്നതും അല്ലാഹു നിങ്ങളോട് നിരോധിക്കുന്നില്ല. തീര്‍ച്ചയായും അല്ലാഹു നീതി പാലിക്കുന്നവരെ ഇഷ്ടപ്പെടുന്നു."}, {"ayahNumber": 9, "quranText": "إِنَّمَا یَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِینَ قَـٰتَلُوكُمۡ فِی ٱلدِّینِ وَأَخۡرَجُوكُم مِّن دِیَـٰرِكُمۡ وَظَـٰهَرُوا۟ عَلَىٰۤ إِخۡرَاجِكُمۡ أَن تَوَلَّوۡهُمۡۚ وَمَن یَتَوَلَّهُمۡ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ\n", "jalalayn": "«إنّما يَنْهاكُمْ اللَّه عَنْ الَّذِينَ قاتَلُوكُمْ فِي الدِّين وأَخْرَجُوكُمْ مِن دِياركُمْ وظاهَرُوا» عاوَنُوا «عَلى إخْراجكُمْ أنْ تُوَلُّوهُمْ» بَدَل اشْتِمال مِن الَّذِينَ أيْ تَتَّخِذُوهُمْ أوْلِياء", "malayalam": "«മതകാര്യത്തിൽ നിങ്ങളോട് യുദ്ധം ചെയ്യുകയും നിങ്ങളുടെ വീടുകളിൽ നിന്ന് നിങ്ങളെ പുറത്താക്കുകയും നിങ്ങളെ പുറത്താക്കാൻ പരസ്പരം സഹായിക്കുകയും ചെയ്തവരെ മിത്രങ്ങളാക്കുന്നതിനെ മാത്രമാണ് അല്ലാഹു നിങ്ങളോട് വിലക്കുന്നത്; ആരെങ്കിലും അവരെ മിത്രങ്ങളാക്കുന്ന പക്ഷം അവരത്രെ അക്രമികൾ!».", "malayalamMatn": "മതകാര്യത്തില്‍ നിങ്ങളോട് യുദ്ധം ചെയ്യുകയും നിങ്ങളുടെ വീടുകളില്‍ നിന്ന് നിങ്ങളെ പുറത്താക്കുകയും നിങ്ങളെ പുറത്താക്കുന്നതില്‍ പരസ്പരം സഹകരിക്കുകയും ചെയ്തവരെ സംബന്ധിച്ചുമാത്രമാണ് -അവരോട് മൈത്രികാണിക്കുന്നത് - അല്ലാഹു നിരോധിക്കുന്നത്‌. വല്ലവരും അവരോട് മൈത്രീ ബന്ധം പുലര്‍ത്തുന്ന പക്ഷം അവര്‍ തന്നെയാകുന്നു അക്രമകാരികള്‍."}, {"ayahNumber": 10, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا جَاۤءَكُمُ ٱلۡمُؤۡمِنَـٰتُ مُهَـٰجِرَ ٰ⁠تࣲ فَٱمۡتَحِنُوهُنَّۖ ٱللَّهُ أَعۡلَمُ بِإِیمَـٰنِهِنَّۖ فَإِنۡ عَلِمۡتُمُوهُنَّ مُؤۡمِنَـٰتࣲ فَلَا تَرۡجِعُوهُنَّ إِلَى ٱلۡكُفَّارِۖ لَا هُنَّ حِلࣱّ لَّهُمۡ وَلَا هُمۡ یَحِلُّونَ لَهُنَّۖ وَءَاتُوهُم مَّاۤ أَنفَقُوا۟ۚ وَلَا جُنَاحَ عَلَیۡكُمۡ أَن تَنكِحُوهُنَّ إِذَاۤ ءَاتَیۡتُمُوهُنَّ أُجُورَهُنَّۚ وَلَا تُمۡسِكُوا۟ بِعِصَمِ ٱلۡكَوَافِرِ وَسۡـَٔلُوا۟ مَاۤ أَنفَقۡتُمۡ وَلۡیَسۡـَٔلُوا۟ مَاۤ أَنفَقُوا۟ۚ ذَ ٰ⁠لِكُمۡ حُكۡمُ ٱللَّهِ یَحۡكُمُ بَیۡنَكُمۡۖ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا إذا جاءَكُمْ المُؤْمِنات» بِأَلْسِنَتِهِنَّ «مُهاجِرات» مِن الكُفّار بَعْد الصُّلْح مَعَهُمْ فِي الحُدَيْبِيَة عَلى أنَّ مَن جاءَ مِنهُمْ إلى المُؤْمِنِينَ يُرَدّ «فامْتَحِنُوهُنَّ» بِالحَلِفِ عَلى أنَّهُنَّ ما خَرَجْنَ إلّا رَغْبَة فِي الإسْلام لا بُغْضًا لِأَزْواجِهِنَّ الكُفّار ولا عِشْقًا لِرِجالٍ مِن المُسْلِمِينَ كَذا كانَ النَّبِيّ ﷺ يُحَلِّفهُنَّ «اللَّه أعْلَم بِإيمانِهِنَّ فَإنْ عَلِمْتُمُوهُنَّ» ظَنَنْتُمُوهُنَّ بِالحَلِفِ «مُؤْمِنات فَلا تَرْجِعُوهُنَّ» تَرُدُّوهُنَّ «إلى الكُفّار لا هُنَّ حِلّ لَهُمْ ولا هُمْ يَحِلُّونَ لَهُنَّ وآتُوهُمْ» أيْ أعْطُوا الكُفّار أزْواجهنَّ «ما أنْفَقُوا» عَلَيْهِنَّ مِن المُهُور «ولا جُناح عَلَيْكُمْ أنْ تَنْكِحُوهُنَّ» بِشَرْطِهِ «إذا آتَيْتُمُوهُنَّ أُجُورهنَّ» مُهُورهنَّ «ولا تَمَسَّكُوا» بِالتَّشْدِيدِ والتَّخْفِيف «بِعِصَمِ الكَوافِر» زَوْجاتكُمْ لِقَطْعِ إسْلامكُمْ لَها بِشَرْطِهِ أوْ الحِقّات بِالمُشْرِكِينَ مُرْتَدّات لِقَطْعِ ارْتِدادهنَّ نِكاحكُمْ بِشَرْطِهِ «واسْأَلُوا» اُطْلُبُوا «ما أنْفَقْتُمْ» عَلَيْهِنَّ مِن المُهُور فِي صُورَة الِارْتِداد مِمَّنْ تَزَوَّجْهُنَّ مِن الكُفّار «ولْيَسْأَلُوا ما أنْفَقُوا» عَلى المُهاجِرات كَما تَقَدَّمَ أنَّهُمْ يُؤْتُونَهُ «ذَلِكُمْ حُكْم اللَّه يَحْكُم بَيْنكُمْ» بِهِ", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, സത്യവിശ്വാസിനികളായ സ്ത്രീകൾ ഹിജ്‌റ വന്നവരായി നിങ്ങളുടെ അടുക്കൽ വന്നാൽ നിങ്ങൾ അവരെ പരീക്ഷിച്ചു നോക്കുക; അവരുടെ വിശ്വാസത്തെക്കുറിച്ച് അല്ലാഹു ഏറ്റവും നന്നായി അറിയുന്നവനാണ്; അവർ സത്യവിശ്വാസിനികളാണെന്ന് നിങ്ങൾക്ക് ബോധ്യപ്പെട്ടാൽ അവരെ നിങ്ങൾ അവിശ്വാസികളിലേക്ക് തിരിച്ചയക്കരുത്; ഇവർ അവർക്ക് അനുവദനീയമല്ല, അവർ ഇവർക്കും അനുവദനീയമല്ല; അവർ ചെലവഴിച്ച മഹ്ര് അവർക്ക് നിങ്ങൾ നൽകുകയും ചെയ്യുക; അവർക്ക് നിങ്ങൾ മഹ്ര് നൽകുകയാണെങ്കിൽ അവരെ വിവാഹം ചെയ്യുന്നതിൽ നിങ്ങൾക്ക് യാതൊരു തെറ്റുമില്ല; അവിശ്വാസിനികളായ സ്ത്രീകളുമായുള്ള ദാമ്പത്യബന്ധം നിങ്ങൾ നിലനിർത്തരുത്; നിങ്ങൾ ചെലവഴിച്ചത് തിരിച്ചു ചോദിച്ചുകൊള്ളുക, അവർ ചെലവഴിച്ചതും അവർ തിരിച്ചു ചോദിക്കട്ടെ; അതത്രെ അല്ലാഹുവിന്റെ വിധി; അവൻ നിങ്ങൾക്കിടയിൽ വിധി കൽപിക്കുന്നു; അല്ലാഹു സർവ്വജ്ഞനും പരമയുക്തിമാനുമാകുന്നു».", "malayalamMatn": "സത്യവിശ്വാസികളേ, വിശ്വാസിനികളായ സ്ത്രീകള്‍ അഭയാര്‍ത്ഥികളായി കൊണ്ട് നിങ്ങളുടെ അടുത്ത് വന്നാല്‍ നിങ്ങള്‍ അവരെ പരീക്ഷിച്ച് നോക്കണം. അവരുടെ വിശ്വാസത്തെ പറ്റി അല്ലാഹു ഏറ്റവും അറിയുന്നവനാണ്‌. എന്നിട്ട് അവര്‍ വിശ്വാസിനികളാണെന്ന് അറിഞ്ഞ് കഴിഞ്ഞാല്‍ അവരെ നിങ്ങള്‍ സത്യനിഷേധികളുടെ അടുത്തേക്ക് മടക്കി അയക്കരുത്‌. ആ സ്ത്രീകള്‍ അവര്‍ക്ക് അനുവദനീയമല്ല. അവര്‍ക്ക് അവര്‍ ചെലവഴിച്ചത് നിങ്ങള്‍ നല്‍കുകയും വേണം. ആ സ്ത്രീകള്‍ക്ക് അവരുടെ പ്രതിഫലങ്ങള്‍ നിങ്ങള്‍ കൊടുത്താല്‍ അവരെ നിങ്ങള്‍ വിവാഹം കഴിക്കുന്നതിന് നിങ്ങള്‍ക്ക് വിരോധമില്ല. അവിശ്വാസിനികളുമായുള്ള ബന്ധം നിങ്ങള്‍ മുറുകെപിടിച്ചു കൊണ്ടിരിക്കുകയും ചെയ്യരുത്‌. നിങ്ങള്‍ ചെലവഴിച്ചതെന്തോ, അത് നിങ്ങള്‍ ചോദിച്ചു കൊള്ളുക. അവര്‍ ചെലവഴിച്ചതെന്തോ അത് അവരും ചോദിച്ച് കൊള്ളട്ടെ. അതാണ് അല്ലാഹുവിന്‍റെ വിധി. അവന്‍ നിങ്ങള്‍ക്കിടയില്‍ വിധികല്‍പിക്കുന്നു. അല്ലാഹു സര്‍വ്വജ്ഞനും യുക്തിമാനുമാകുന്നു."}, {"ayahNumber": 11, "quranText": "وَإِن فَاتَكُمۡ شَیۡءࣱ مِّنۡ أَزۡوَ ٰ⁠جِكُمۡ إِلَى ٱلۡكُفَّارِ فَعَاقَبۡتُمۡ فَـَٔاتُوا۟ ٱلَّذِینَ ذَهَبَتۡ أَزۡوَ ٰ⁠جُهُم مِّثۡلَ مَاۤ أَنفَقُوا۟ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِیۤ أَنتُم بِهِۦ مُؤۡمِنُونَ\n", "jalalayn": "«وإنْ فاتَكُمْ شَيْء مِن أزْواجكُمْ» أيْ واحِدَة فَأَكْثَر مِنهُنَّ أوْ شَيْء مِن مُهُورهنَّ بِالذَّهابِ «إلى الكُفّار» مُرْتَدّات «فَعاقَبْتُمْ» فَغَزَوْتُمْ وغَنِمْتُمْ «فَآتُوا الَّذِينَ ذَهَبَتْ أزْواجهمْ» مِن الغَنِيمَة «مِثْل ما أنْفَقُوا» لِفَواتِهِ عَلَيْهِمْ مِن جِهَة الكُفّار «واتَّقُوا اللَّه الَّذِي أنْتُمْ بِهِ مُؤْمِنُونَ» وقَدْ فَعَلَ المُؤْمِنُونَ ما أُمِرُوا بِهِ مِن الإيتاء لِلْكُفّارِ والمُؤْمِنِينَ ثُمَّ ارْتَفَعَ هَذا الحُكْم", "malayalam": "«നിങ്ങളുടെ ഭാര്യമാരിൽ നിന്ന് ആരെങ്കിലും അവിശ്വാസികളിലേക്ക് പോയിട്ട് നിങ്ങൾക്ക് വല്ല നഷ്ടവും വരികയും, പിന്നീട് നിങ്ങൾക്ക് യുദ്ധവിഹിതം ലഭിക്കുകയും ചെയ്താൽ, ഭാര്യമാർ പോയിപ്പോയവർക്ക് അവർ ചെലവഴിച്ചതിന് തുല്യമായത് നിങ്ങൾ നൽകുക; ഏതൊരുവനിലാണോ നിങ്ങൾ വിശ്വസിക്കുന്നത് ആ അല്ലാഹുവിനെ നിങ്ങൾ സൂക്ഷിക്കുകയും ചെയ്യുവിൻ».", "malayalamMatn": "നിങ്ങളുടെ ഭാര്യമാരില്‍ നിന്ന് വല്ലവരും അവിശ്വാസികളുടെ കൂട്ടത്തിലേക്ക് (പോയിട്ട് നിങ്ങള്‍ക്ക്‌) നഷ്ടപ്പെടുകയും എന്നിട്ട് നിങ്ങള്‍ അനന്തര നടപടിയെടുക്കുകയും ചെയ്യുകയാണെങ്കില്‍ ആരുടെ ഭാര്യമാരാണോ നഷ്ടപ്പെട്ട് പോയത്‌, അവര്‍ക്ക് അവര്‍ ചെലവഴിച്ച തുക (മഹ്ര്) പോലുള്ളത് നിങ്ങള്‍ നല്‍കുക. ഏതൊരു അല്ലാഹുവില്‍ നിങ്ങള്‍ വിശ്വസിക്കുന്നുവോ അവനെ നിങ്ങള്‍ സൂക്ഷിക്കുകയും ചെയ്യുക."}, {"ayahNumber": 12, "quranText": "یَـٰۤأَیُّهَا ٱلنَّبِیُّ إِذَا جَاۤءَكَ ٱلۡمُؤۡمِنَـٰتُ یُبَایِعۡنَكَ عَلَىٰۤ أَن لَّا یُشۡرِكۡنَ بِٱللَّهِ شَیۡـࣰٔا وَلَا یَسۡرِقۡنَ وَلَا یَزۡنِینَ وَلَا یَقۡتُلۡنَ أَوۡلَـٰدَهُنَّ وَلَا یَأۡتِینَ بِبُهۡتَـٰنࣲ یَفۡتَرِینَهُۥ بَیۡنَ أَیۡدِیهِنَّ وَأَرۡجُلِهِنَّ وَلَا یَعۡصِینَكَ فِی مَعۡرُوفࣲ فَبَایِعۡهُنَّ وَٱسۡتَغۡفِرۡ لَهُنَّ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ\n", "jalalayn": "«يا أيّها النَّبِيّ إذا جاءَك المُؤْمِنات يُبايِعْنَك عَلى أنْ لا يُشْرِكْنَ بِاللَّهِ شَيْئًا ولا يَسْرِقْنَ ولا يَزْنِينَ ولا يَقْتُلْنَ أوْلادهنَّ» كَما كانَ يَفْعَل فِي الجاهِلِيَّة مِن وأْد البَنات أيْ دَفْنهنَّ أحْياء خَوْف العار والفَقْر «ولا يَأْتِينَ بِبُهْتانٍ يَفْتَرِينَهُ بَيْن أيْدِيهنَّ وأَرْجُلهنَّ» أيْ بِوَلَدٍ مَلْقُوط يَنْسُبْنَهُ إلى الزَّوْج ووُصِفَ بِصِفَةِ الوَلَد الحَقِيقِيّ فَإنَّ الأُمّ إذا وضَعَتْهُ سَقَطَ بَيْن يَدَيْها ورِجْلَيْها «ولا يَعْصِينَك فِي» فِعْل «مَعْرُوف» هُوَ ما وافَقَ طاعَة اللَّه كَتَرْكِ النِّياحَة وتَمْزِيق الثِّياب وجَزّ الشُّعُور وشَقّ الجَيْب وخَمْش الوَجْه «فَبايِعْهُنَّ» فَعَلَ ذَلِكَ ﷺ بِالقَوْلِ ولَمْ يُصافِح واحِدَة مِنهُنَّ", "malayalam": "«നബിയേ, സത്യവിശ്വാസിനികളായ സ്ത്രീകൾ അല്ലാഹുവോട് യാതൊന്നിനെയും പങ്കുചേർക്കില്ലെന്നും, മോഷ്ടിക്കില്ലെന്നും, വ്യഭിചരിക്കില്ലെന്നും, തങ്ങളുടെ മക്കളെ കൊന്നുകളയില്ലെന്നും, തങ്ങളുടെ കൈകാലുകൾക്കിടയിൽ വ്യാജവാർത്ത കെട്ടിച്ചമച്ചുണ്ടാക്കില്ലെന്നും, യാതൊരു നല്ല കാര്യത്തിലും താങ്കളോട് അനുസരണക്കേട് കാണിക്കില്ലെന്നും ഉറപ്പുനൽകിക്കൊണ്ട് താങ്കളോട് ബൈഅത്ത് (പ്രതിജ്ഞ) ചെയ്യുവാൻ വന്നാൽ താങ്കൾ അവരുമായി പ്രതിജ്ഞ ചെയ്യുക; അവർക്കായി അല്ലാഹുവോട് പാപമോചനം തേടുകയും ചെയ്യുക; തീർച്ചയായും അല്ലാഹു ഏറെ പൊറുക്കുന്നവനും ദയാപരനുമാകുന്നു».", "malayalamMatn": "ഓ; നബീ, അല്ലാഹുവോട് യാതൊന്നിനെയും പങ്കുചേര്‍ക്കുകയില്ലെന്നും, മോഷ്ടിക്കുകയില്ലെന്നും, വ്യഭിചരിക്കുകയില്ലെന്നും, തങ്ങളുടെ മക്കളെ കൊന്നുകളയുകയില്ലെന്നും, തങ്ങളുടെ കൈകാലുകള്‍ക്കിടയില്‍ വ്യാജവാദം കെട്ടിച്ചമച്ചു കൊണ്ടുവരികയില്ലെന്നും, യാതൊരു നല്ലകാര്യത്തിലും നിന്നോട് അനുസരണക്കേട് കാണിക്കുകയില്ലെന്നും നിന്നോട് പ്രതിജ്ഞ ചെയ്തുകൊണ്ട് സത്യവിശ്വാസിനികള്‍ നിന്‍റെ അടുത്ത് വന്നാല്‍ നീ അവരുടെ പ്രതിജ്ഞ സ്വീകരിക്കുകയും, അവര്‍ക്കു വേണ്ടി പാപമോചനം തേടുകയും ചെയ്യുക. തീര്‍ച്ചയായും അല്ലാഹു ഏറെ പൊറുക്കുന്നവനും കരുണാനിധിയുമാകുന്നു."}, {"ayahNumber": 13, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَوَلَّوۡا۟ قَوۡمًا غَضِبَ ٱللَّهُ عَلَیۡهِمۡ قَدۡ یَىِٕسُوا۟ مِنَ ٱلۡـَٔاخِرَةِ كَمَا یَىِٕسَ ٱلۡكُفَّارُ مِنۡ أَصۡحَـٰبِ ٱلۡقُبُورِ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا لا تَتَوَلَّوْا قَوْمًا غَضِبَ اللَّه عَلَيْهِمْ» هُمْ اليَهُود «قَدْ يَئِسُوا مِن الآخِرَة» مِن ثَوابها مَعَ إيقانهمْ بِها لِعِنادِهِمْ النَّبِيّ مَعَ عِلْمهمْ بِصِدْقِهِ «كَما يَئِسَ الكُفّار» الكائِنُونَ «مِن أصْحاب القُبُور» أيْ المَقْبُورِينَ مِن خَبَر الآخِرَة إذْ تُعْرَض عَلَيْهِمْ مَقاعِدهمْ مِن الجَنَّة لَوْ كانُوا آمَنُوا وما يَصِيرُونَ إلَيْهِ مِن النّار", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, അല്ലാഹു കോപിച്ച ഒരു ജനതയെ നിങ്ങൾ മിത്രങ്ങളാക്കരുത്; ഖബറുകളിലുള്ളവരെപ്പറ്റി അവിശ്വാസികൾ നിരാശരായതുപോലെ പരലോകത്തെപ്പറ്റി അവർ നിരാശരായിക്കഴിഞ്ഞിരിക്കുന്നു».", "malayalamMatn": "സത്യവിശ്വാസികളേ, അല്ലാഹു കോപിച്ചിട്ടുള്ള ഒരു ജനതയോട് നിങ്ങള്‍ മൈത്രിയില്‍ ഏര്‍പെടരുത്‌. ഖബ്‌റുകളിലുള്ളവരെ സംബന്ധിച്ച് അവിശ്വാസികള്‍ നിരാശപ്പെട്ടത് പോലെ പരലോകത്തെപ്പറ്റി അവര്‍ നിരാശപ്പെട്ടുകഴിഞ്ഞിരിക്കുന്നു."}], "topPoints": ["ശത്രുക്കളുമായുള്ള ബന്ധത്തിലെ അതിരുകൾ (خلاصة السورة)", "വിശ്വാസികളായ സ്ത്രീകളുടെ പരീക്ഷണം"], "topQuestions": [{"q": "ഈ സൂറത്തിൽ വിശ്വാസികൾക്ക് നൽകുന്ന പ്രധാന മുന്നറിയിപ്പ് എന്താണ്?", "a": "അല്ലാഹുവിന്റെയും വിശ്വാസികളുടെയും ശത്രുക്കളെ മിത്രങ്ങളാക്കരുത് എന്നത്."}], "asbabAlNuzul": [{"ayahNumber": 1, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّی وَعَدُوَّكُمۡ أَوۡلِیَاۤءَ تُلۡقُونَ إِلَیۡهِم بِٱلۡمَوَدَّةِ", "arabicSnippet": "«يا أيها الذين آمنوا لا تتخذوا عدوي وعدوَّكم أولياء تلقون إليهم بالمودة» كتب حاطب بن أبي بلتعة إليهم كتابا بذلك لما له عندهم من الأولاد والأهل المشركين فاسترده النبي صلى الله عليه وسلم...", "malayalamExplanation": "മക്കാ വിജയത്തിന് മുന്നോടിയായി റസൂലുല്ലാഹി ﷺ നടത്തിയ രഹസ്യ നീക്കങ്ങളെക്കുറിച്ച് ഹാതിബ് ബ്നു അബീ ബൽതഅ (റ) മക്കയിലെ മുശ്‌രിക്കുകൾക്ക് രഹസ്യമായി കത്തെഴുതി അയച്ചു. മക്കയിലുള്ള തന്റെ ദുർബലരായ ഭാര്യയെയും മക്കളെയും മുശ്‌രിക്കുകൾ ഉപദ്രവിക്കാതിരിക്കാൻ ഒരു ഉപകാരം ചെയ്തുവെക്കാം എന്ന ചിന്തയിലായിരുന്നു അത്. അല്ലാഹു വഹ്‌യ് വഴി വിവരമറിയിക്കുകയും അലി (റ) വിന്റെ നേതൃത്വത്തിൽ കത്ത് പിടിച്ചെടുക്കുകയും ചെയ്തു. സത്യവിശ്വാസികൾ അല്ലാഹുവിന്റെ ശത്രുക്കളുമായി രഹസ്യബന്ധം പുലർത്തരുതെന്ന് താക്കീത് ചെയ്തുകൊണ്ട് ഈ സൂക്തം അവതരിച്ചു."}]}, {"surahNumber": 61, "surahNameArabic": "سُورَةُ الصَّفِّ", "surahNameMalayalam": "സൂറത്തുസ്സ്വഫ്ഫ് (അണി)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ سَبَّحَ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n", "jalalayn": "«سَبَّحَ لِلَّهِ ما فِي السَّماوات وما فِي الأَرْض» أيْ نَزَّهَهُ فاللّام مَزِيدَة وجِيءَ بِما دُون مِن تَغْلِيبًا لِلْأَكْثَرِ «وهُوَ العَزِيز» فِي مُلْكه «الحَكِيم» فِي صُنْعه", "malayalam": "«ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതുമെല്ലാം അല്ലാഹുവിന്റെ പരിശുദ്ധിയെ പ്രകീർത്തിച്ചിരിക്കുന്നു; അവൻ പ്രതാപിയും പരമയുക്തിമാനുമാകുന്നു».", "malayalamMatn": "ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതും അല്ലാഹുവിന്‍റെ മഹത്വം പ്രകീര്‍ത്തിച്ചിരിക്കുന്നു. അവനാകുന്നു പ്രതാപിയും യുക്തിമാനും."}, {"ayahNumber": 2, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا لِمَ تَقُولُونَ» فِي طَلَب الجِهاد «ما لا تَفْعَلُونَ» إذْ انْهَزَمْتُمْ بِأُحُدٍ", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, നിങ്ങൾ പ്രവർത്തിക്കാത്ത കാര്യം നിങ്ങൾ എന്തിനാണ് പറയുന്നത്?».", "malayalamMatn": "സത്യവിശ്വാസികളേ, നിങ്ങള്‍ ചെയ്യാത്തതെന്തിന് നിങ്ങള്‍ പറയുന്നു?"}, {"ayahNumber": 3, "quranText": "كَبُرَ مَقۡتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفۡعَلُونَ\n", "jalalayn": "«كَبُرَ» عَظُمَ «مَقْتًا» تَمْيِيز «عِنْد اللَّه أنْ تَقُولُوا» فاعِل كَبُرَ", "malayalam": "«നിങ്ങൾ പ്രവർത്തിക്കാത്ത കാര്യം നിങ്ങൾ പറയുക എന്നത് അല്ലാഹുവിങ്കൽ വലിയ കോപത്തിന് കാരണമായിരിക്കുന്നു».", "malayalamMatn": "നിങ്ങള്‍ ചെയ്യാത്തത് നിങ്ങള്‍ പറയുക എന്നുള്ളത് അല്ലാഹുവിങ്കല്‍ വലിയ ക്രോധത്തിന് കാരണമായിരിക്കുന്നു."}, {"ayahNumber": 4, "quranText": "إِنَّ ٱللَّهَ یُحِبُّ ٱلَّذِینَ یُقَـٰتِلُونَ فِی سَبِیلِهِۦ صَفࣰّا كَأَنَّهُم بُنۡیَـٰنࣱ مَّرۡصُوصࣱ\n", "jalalayn": "«إنّ اللَّه يُحِبّ» يَنْصُر ويُكْرِم «الَّذِينَ يُقاتِلُونَ فِي سَبِيله صَفًّا» حال أيْ صافِّينَ «كَأَنَّهُمْ بُنْيان مَرْصُوص» مُلْزَق بَعْضه إلى بَعْض ثابِت", "malayalam": "«ഈയ്യം ഉരുക്കി ഒഴിച്ച ഭദ്രമായ മതിൽ പോലെ അണിനിരന്നുകൊണ്ട് തന്റെ മാർഗ്ഗത്തിൽ പോരാടുന്നവരെ തീർച്ചയായും അല്ലാഹു ഇഷ്ടപ്പെടുന്നു».", "malayalamMatn": "(കല്ലുകള്‍) സുദൃഢമായി സംയോജിപ്പിച്ച ഒരു മതില്‍ പോലെ അണിചേര്‍ന്നുകൊണ്ട് തന്‍റെ മാര്‍ഗത്തില്‍ യുദ്ധം ചെയ്യുന്നവരെ തീര്‍ച്ചയായും അല്ലാഹു ഇഷ്ടപ്പെടുന്നു."}, {"ayahNumber": 5, "quranText": "وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ یَـٰقَوۡمِ لِمَ تُؤۡذُونَنِی وَقَد تَّعۡلَمُونَ أَنِّی رَسُولُ ٱللَّهِ إِلَیۡكُمۡۖ فَلَمَّا زَاغُوۤا۟ أَزَاغَ ٱللَّهُ قُلُوبَهُمۡۚ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡفَـٰسِقِینَ\n", "jalalayn": "«و» اذْكُرْ «إذْ قالَ مُوسى لِقَوْمِهِ يا قَوْم لِمَ تُؤْذُونَنِي» قالُوا: إنّهُ آدَر أيْ مُنْتَفِخ الخُصْيَة ولَيْسَ كَذَلِكَ وكَذَّبُوهُ «وقَدْ» لِلتَّحْقِيقِ «تَعْلَمُونَ أنِّي رَسُول اللَّه إلَيْكُمْ» الجُمْلَة حال والرَّسُول يُحْتَرَم «فَلَمّا زاغُوا» عَدَلُوا عَنْ الحَقّ بِإيذائِهِ «أزاغَ اللَّه قُلُوبهمْ» أمالَها عَنْ الهُدى عَلى وفْق ما قَدَّرَهُ فِي الأَزَل «واللَّه لا يَهْدِي القَوْم الفاسِقِينَ» الكافِرِينَ فِي عِلْمه", "malayalam": "«മൂസാ തന്റെ ജനതയോട് പറഞ്ഞ സന്ദർഭം: എന്റെ ജനങ്ങളേ, ഞാൻ നിങ്ങളിലേക്ക് അയക്കപ്പെട്ട അല്ലാഹുവിന്റെ റസൂലാണെന്ന് നിങ്ങൾക്കറിവുണ്ടായിരിക്കെ നിങ്ങളെന്തിനാണ് എന്നെ ശല്യപ്പെടുത്തുന്നത്? അങ്ങനെ അവർ വ്യതിചലിച്ചപ്പോൾ അല്ലാഹു അവരുടെ ഹൃദയങ്ങളെയും തെറ്റിച്ചു കളഞ്ഞു; അധർമ്മകാരികളായ ജനങ്ങളെ അല്ലാഹു നേർവഴിയിലാക്കുകയില്ല».", "malayalamMatn": "മൂസാ തന്‍റെ ജനതയോട് ഇപ്രകാരം പറഞ്ഞ സന്ദര്‍ഭം (ശ്രദ്ധേയമാകുന്നു:) എന്‍റെ ജനങ്ങളേ, നിങ്ങള്‍ എന്തിനാണ് എന്നെ ഉപദ്രവിക്കുന്നത്‌? ഞാന്‍ നിങ്ങളിലേക്കുള്ള അല്ലാഹുവിന്‍റെ ദൂതനാണെന്ന് നിങ്ങള്‍ക്കറിയാമല്ലോ. അങ്ങനെ അവര്‍ തെറ്റിയപ്പോള്‍ അല്ലാഹു അവരുടെ ഹൃദയങ്ങളെ തെറ്റിച്ചുകളഞ്ഞു. അല്ലാഹു ദുര്‍മാര്‍ഗികളായ ജനങ്ങളെ നേര്‍വഴിയിലാക്കുകയില്ല."}, {"ayahNumber": 6, "quranText": "وَإِذۡ قَالَ عِیسَى ٱبۡنُ مَرۡیَمَ یَـٰبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ إِنِّی رَسُولُ ٱللَّهِ إِلَیۡكُم مُّصَدِّقࣰا لِّمَا بَیۡنَ یَدَیَّ مِنَ ٱلتَّوۡرَىٰةِ وَمُبَشِّرَۢا بِرَسُولࣲ یَأۡتِی مِنۢ بَعۡدِی ٱسۡمُهُۥۤ أَحۡمَدُۖ فَلَمَّا جَاۤءَهُم بِٱلۡبَیِّنَـٰتِ قَالُوا۟ هَـٰذَا سِحۡرࣱ مُّبِینࣱ\n", "jalalayn": "«و» اذْكُرْ «إذْ قالَ عِيسى ابْن مَرْيَم يا بَنِي إسْرائِيل» لَمْ يَقُلْ: يا قَوْم لِأَنَّهُ لَمْ يَكُنْ لَهُ فِيهِمْ قَرابَة «إنِّي رَسُول اللَّه إلَيْكُمْ مُصَدِّقًا لِما بَيْن يَدَيَّ» قَبْلِي «مِن التَّوْراة ومُبَشِّرًا بِرَسُولٍ يَأْتِي مِن بَعْدِي اسْمه أحْمَد» قالَ تَعالى «فَلَمّا جاءَهُمْ» جاءَ أحْمَد الكُفّار «بِالبَيِّناتِ» الآيات والعَلامات «قالُوا هَذا» أيْ المَجِيء بِهِ «سِحْر» وفِي قِراءَة ساحِر أيْ الجائِي بِهِ «مُبِين» بَيِّن", "malayalam": "«മർയമിന്റെ മകൻ ഈസാ പറഞ്ഞ സന്ദർഭം: ഇസ്രാഈൽ സന്തതികളേ, എനിക്ക് മുമ്പുള്ള തൗറാത്തിനെ സത്യപ്പെടുത്തുന്നവനായും, എനിക്ക് ശേഷം വരാനിരിക്കുന്ന 'അഹ്‌മദ്' എന്ന് പേരുള്ള റസൂലിനെക്കുറിച്ച് സന്തോഷവാർത്ത അറിയിക്കുന്നവനായും നിങ്ങളിലേക്ക് നിയോഗിക്കപ്പെട്ട അല്ലാഹുവിന്റെ റസൂലാകുന്നു ഞാൻ; അങ്ങനെ അദ്ദേഹം വ്യക്തമായ തെളിവുകളുമായി അവരുടെ അടുക്കൽ വന്നപ്പോൾ അവർ പറഞ്ഞു: ഇത് വ്യക്തമായ ജാലവിദ്യയാകുന്നു!».", "malayalamMatn": "മര്‍യമിന്‍റെ മകന്‍ ഈസാ പറഞ്ഞ സന്ദര്‍ഭവും (ശ്രദ്ധേയമാകുന്നു:) ഇസ്രായീല്‍ സന്തതികളേ, എനിക്കു മുമ്പുള്ള തൌറാത്തിനെ സത്യപ്പെടുത്തുന്നവനായിക്കൊണ്ടും, എനിക്ക് ശേഷം വരുന്ന അഹ്മദ് എന്നുപേരുള്ള ഒരു ദൂതനെപ്പറ്റി സന്തോഷവാര്‍ത്ത അറിയിക്കുന്നവനായിക്കൊണ്ടും നിങ്ങളിലേക്ക് അല്ലാഹുവിന്‍റെ ദൂതനായി നിയോഗിക്കപ്പെട്ടവനാകുന്നു ഞാന്‍. അങ്ങനെ അദ്ദേഹം വ്യക്തമായ തെളിവുകളും കൊണ്ട് അവരുടെ അടുത്ത് ചെന്നപ്പോള്‍ അവര്‍ പറഞ്ഞു: ഇത് വ്യക്തമായ ജാലവിദ്യയാകുന്നു."}, {"ayahNumber": 7, "quranText": "وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُوَ یُدۡعَىٰۤ إِلَى ٱلۡإِسۡلَـٰمِۚ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ\n", "jalalayn": "«ومَن» أيْ لا أحَد «أظْلَم» أشَدّ ظُلْمًا «مِمَّنْ افْتَرى عَلى اللَّه الكَذِب» بِنِسْبَةِ الشَّرِيك والوَلَد إلَيْهِ ووَصْف آياته بِالسِّحْرِ «وهُوَ يُدْعى إلى الإسْلام واللَّه لا يَهْدِي القَوْم الظّالِمِينَ» الكافِرِينَ", "malayalam": "«ഇസ്ലാമിലേക്ക് ക്ഷണിക്കപ്പെടുമ്പോൾ അല്ലാഹുവിന്റെ മേൽ കളവ് കെട്ടിച്ചമച്ചുണ്ടാക്കിയവനേക്കാൾ വലിയ അക്രമി ആരാണുള്ളത്? അക്രമികളായ ജനങ്ങളെ അല്ലാഹു നേർവഴിയിലാക്കുകയില്ല».", "malayalamMatn": "താന്‍ ഇസ്ലാമിലേക്ക് ക്ഷണിക്കപ്പെടുമ്പോള്‍ അല്ലാഹുവിന്‍റെ പേരില്‍ കള്ളം കെട്ടിച്ചമച്ചവനേക്കാള്‍ വലിയ അക്രമി ആരുണ്ട്‌? അല്ലാഹു അക്രമികളായ ജനങ്ങളെ നേര്‍വഴിയിലാക്കുകയില്ല."}, {"ayahNumber": 8, "quranText": "یُرِیدُونَ لِیُطۡفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفۡوَ ٰ⁠هِهِمۡ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوۡ كَرِهَ ٱلۡكَـٰفِرُونَ\n", "jalalayn": "«يُرِيدُونَ لِيُطْفِئُوا» مَنصُوب بِأَنْ مُقَدَّرَة واللّام مَزِيدَة «نُور اللَّه» شَرْعه وبَراهِينه «بِأَفْواهِهِمْ» بِأَقْوالِهِمْ إنّهُ سِحْر وشِعْر وكِهانَة «واللَّه مُتِمّ» مُظْهِر «نُوره» وفِي قِراءَة بِالإضافَةِ «ولَوْ كَرِهَ الكافِرُونَ» ذَلِكَ", "malayalam": "«തങ്ങളുടെ വായകൾ കൊണ്ട് അല്ലാഹുവിന്റെ പ്രകാശം കെടുത്തിക്കളയാനാണ് അവർ ഉദ്ദേശിക്കുന്നത്; സത്യനിഷേധികൾ വെറുത്താലും അല്ലാഹു തന്റെ പ്രകാശത്തെ പൂർണ്ണമാക്കുക തന്നെ ചെയ്യും».", "malayalamMatn": "അവര്‍ അവരുടെ വായ്കൊണ്ട് അല്ലാഹുവിന്‍റെ പ്രകാശം കെടുത്തിക്കളയാനാണ് ഉദ്ദേശിക്കുന്നത്‌. സത്യനിഷേധികള്‍ക്ക് അനിഷ്ടകരമായാലും അല്ലാഹു അവന്‍റെ പ്രകാശം പൂര്‍ത്തിയാക്കുന്നവനാകുന്നു."}, {"ayahNumber": 9, "quranText": "هُوَ ٱلَّذِیۤ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِینِ ٱلۡحَقِّ لِیُظۡهِرَهُۥ عَلَى ٱلدِّینِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ\n", "jalalayn": "«هُوَ الَّذِي أرْسَلَ رَسُوله بِالهُدى ودِين الحَقّ لِيُظْهِرهُ» يُعْلِيه «عَلى الدِّين كُلّه» جَمِيع الأَدْيان المُخالِفَة لَهُ «ولَوْ كَرِهَ المُشْرِكُونَ» ذَلِكَ", "malayalam": "«ബഹുദൈവവിശ്വാസികൾ വെറുത്താലും, സർവ്വ മതങ്ങൾക്കും മീതെ അതിനെ വിജയിപ്പിക്കുവാനായി സന്മാർഗ്ഗവും സത്യമതവുമായി തന്റെ റസൂലിനെ നിയോഗിച്ചത് അവനത്രെ».", "malayalamMatn": "സന്‍മാര്‍ഗവും സത്യമതവും കൊണ്ട് -എല്ലാ മതങ്ങള്‍ക്കും മീതെ അതിനെ തെളിയിച്ചു കാണിക്കുവാന്‍ വേണ്ടി-തന്‍റെ ദൂതനെ നിയോഗിച്ചവനാകുന്നു അവന്‍. ബഹുദൈവാരാധകര്‍ക്ക് (അത്‌) അനിഷ്ടകരമായാലും ശരി."}, {"ayahNumber": 10, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ هَلۡ أَدُلُّكُمۡ عَلَىٰ تِجَـٰرَةࣲ تُنجِیكُم مِّنۡ عَذَابٍ أَلِیمࣲ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا هَلْ أدُلّكُمْ عَلى تِجارَة تُنْجِيكُمْ» بِالتَّخْفِيفِ والتَّشْدِيد «مِن عَذاب ألِيم» مُؤْلِم فَكَأَنَّهُمْ قالُوا نَعَمْ", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, വേദനാജനകമായ ശിക്ഷയിൽ നിന്ന് നിങ്ങളെ രക്ഷിക്കുന്ന ഒരു കച്ചവടത്തെക്കുറിച്ച് ഞാൻ നിങ്ങൾക്ക് അറിയിച്ചു തരട്ടെയോ?».", "malayalamMatn": "സത്യവിശ്വാസികളേ, വേദനാജനകമായ ശിക്ഷയില്‍ നിന്ന് നിങ്ങളെ രക്ഷിക്കുന്ന ഒരു കച്ചവടത്തെപ്പറ്റി ഞാന്‍ നിങ്ങള്‍ക്ക് അറിയിച്ച് തരട്ടെയോ?"}, {"ayahNumber": 11, "quranText": "تُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَـٰهِدُونَ فِی سَبِیلِ ٱللَّهِ بِأَمۡوَ ٰ⁠لِكُمۡ وَأَنفُسِكُمۡۚ ذَ ٰ⁠لِكُمۡ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ\n", "jalalayn": "«تُؤْمِنُونَ» تَدُومُونَ عَلى الإيمان «بِاللَّهِ ورَسُوله وتُجاهِدُونَ فِي سَبِيل اللَّه بِأَمْوالِكُمْ وأَنْفُسكُمْ ذَلِكُمْ خَيْر لَكُمْ إنْ كُنْتُمْ تَعْلَمُونَ» أنَّهُ خَيْر لَكُمْ فافْعَلُوهُ", "malayalam": "«നിങ്ങൾ അല്ലാഹുവിലും അവന്റെ റസൂലിലും വിശ്വസിക്കുക; നിങ്ങളുടെ സമ്പത്തുകൾ കൊണ്ടും ശരീരങ്ങൾ കൊണ്ടും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ നിങ്ങൾ സമരം ചെയ്യുക; അതാണ് നിങ്ങൾക്ക് ഏറ്റവും ഉത്തമം, നിങ്ങൾ അറിയുന്നവരാണെങ്കിൽ!».", "malayalamMatn": "നിങ്ങള്‍ അല്ലാഹുവിലും അവന്‍റെ ദൂതനിലും വിശ്വസിക്കണം.അല്ലാഹുവിന്‍റെ മാര്‍ഗത്തില്‍ നിങ്ങളുടെ സ്വത്തുക്കള്‍ കൊണ്ടും ശരീരങ്ങള്‍ കൊണ്ടും നിങ്ങള്‍ സമരം ചെയ്യുകയും വേണം. അതാണ് നിങ്ങള്‍ക്ക് ഗുണകരമായിട്ടുള്ളത്‌. നിങ്ങള്‍ അറിവുള്ളവരാണെങ്കില്‍."}, {"ayahNumber": 12, "quranText": "یَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡ وَیُدۡخِلۡكُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ وَمَسَـٰكِنَ طَیِّبَةࣰ فِی جَنَّـٰتِ عَدۡنࣲۚ ذَ ٰ⁠لِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ\n", "jalalayn": "«يَغْفِر» جَواب شَرْط مُقَدَّر أيْ إنْ تَفْعَلُوهُ يَغْفِر «لَكُمْ ذُنُوبكُمْ ويُدْخِلكُمْ جَنّات تَجْرِي مِن تَحْتها الأَنْهار ومَساكِن طَيِّبَة فِي جَنّات عَدْن» إقامَة", "malayalam": "«അവൻ നിങ്ങൾക്ക് നിങ്ങളുടെ പാപങ്ങൾ പൊറുത്തുതരികയും, താഴെ അരുവികൾ ഒഴുകുന്ന സ്വർഗ്ഗത്തോപ്പുകളിലും ശാശ്വതമായ സ്വർഗ്ഗങ്ങളിലെ ഉത്തമമായ ഭവനങ്ങളിലും നിങ്ങളെ പ്രവേശിപ്പിക്കുകയും ചെയ്യും; അതത്രെ മഹത്തായ വിജയം!».", "malayalamMatn": "എങ്കില്‍ അവന്‍ നിങ്ങള്‍ക്ക് നിങ്ങളുടെ പാപങ്ങള്‍ പൊറുത്തുതരികയും താഴ്ഭാഗത്ത്കൂടി അരുവികള്‍ ഒഴുകുന്ന സ്വര്‍ഗത്തോപ്പുകളിലും, സ്ഥിരവാസത്തിനുള്ള സ്വര്‍ഗത്തോപ്പുകളിലെ വിശിഷ്ടമായ വസതികളിലും അവന്‍ നിങ്ങളെ പ്രവേശിപ്പിക്കുകയും ചെയ്യുന്നതാണ്‌. അതത്രെ മഹത്തായ ഭാഗ്യം."}, {"ayahNumber": 13, "quranText": "وَأُخۡرَىٰ تُحِبُّونَهَاۖ نَصۡرࣱ مِّنَ ٱللَّهِ وَفَتۡحࣱ قَرِیبࣱۗ وَبَشِّرِ ٱلۡمُؤۡمِنِینَ\n", "jalalayn": "«و» ويُؤْتِكُمْ نِعْمَة «أُخْرى تُحِبُّونَها نَصْر مِن اللَّه وفَتْح قَرِيب وبَشِّرْ المُؤْمِنِينَ» بِالنَّصْرِ والفَتْح", "malayalam": "«നിങ്ങൾ ഇഷ്ടപ്പെടുന്ന മറ്റൊരു കാര്യവും അവൻ നൽകും; അല്ലാഹുവിങ്കൽ നിന്നുള്ള സഹായവും ആസന്നമായ വിജയവും! സത്യവിശ്വാസികൾക്ക് നീ സന്തോഷവാർത്ത അറിയിക്കുക!».", "malayalamMatn": "നിങ്ങള്‍ ഇഷ്ടപ്പെടുന്ന മറ്റൊരു കാര്യവും (അവന്‍ നല്‍കുന്നതാണ്‌.) അതെ, അല്ലാഹുവിങ്കല്‍ നിന്നുള്ള സഹായവും ആസന്നമായ വിജയവും. (നബിയേ,) സത്യവിശ്വാസികള്‍ക്ക് നീ സന്തോഷവാര്‍ത്ത അറിയിക്കുക."}, {"ayahNumber": 14, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ كُونُوۤا۟ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِیسَى ٱبۡنُ مَرۡیَمَ لِلۡحَوَارِیِّـۧنَ مَنۡ أَنصَارِیۤ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِیُّونَ نَحۡنُ أَنصَارُ ٱللَّهِۖ فَـَٔامَنَت طَّاۤىِٕفَةࣱ مِّنۢ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ وَكَفَرَت طَّاۤىِٕفَةࣱۖ فَأَیَّدۡنَا ٱلَّذِینَ ءَامَنُوا۟ عَلَىٰ عَدُوِّهِمۡ فَأَصۡبَحُوا۟ ظَـٰهِرِینَ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا كُونُوا أنْصار اللَّه» لِدِينِهِ وفِي قِراءَة بِالإضافَةِ «كَما قالَ» إلَخْ المَعْنى: كَما كانَ الحَوارِيُّونَ كَذَلِكَ الدّالّ عَلَيْهِ قالَ «عِيسى ابْن مَرْيَم لِلْحَوارِيِّينَ مَن أنْصارِي إلى اللَّه» أيْ مَن الأَنْصار الَّذِينَ يَكُونُونَ مَعِي مُتَوَجِّهًا إلى نُصْرَة اللَّه «قالَ الحَوارِيُّونَ نَحْنُ أنْصار اللَّه» والحَوارِيُّونَ أصْفِياء عِيسى وهُمْ أوَّل مَن آمَنَ بِهِ وكانُوا اثْنَيْ عَشَر رَجُلًا مِن الحُور وهُوَ البَياض الخالِص وقِيلَ كانُوا قَصّارِينَ يُحَوِّرُونَ الثِّياب أيْ يُبَيِّضُونَها «فَآمَنَتْ طائِفَة مِن بَنِي إسْرائِيل» بِعِيسى وقالُوا إنّهُ عَبْد اللَّه رُفِعَ إلى السَّماء «وكَفَرَتْ طائِفَة» لِقَوْلِهِمْ إنّهُ ابْن اللَّه رَفَعَهُ إلَيْهِ فاقْتَتَلَتْ الطّائِفَتانِ «فَأَيَّدْنا» قَوَّيْنا «الَّذِينَ آمَنُوا» مِن الطّائِفَتَيْنِ «عَلى عَدُوّهُمْ» الطّائِفَة الكافِرَة «فَأَصْبَحُوا ظاهِرِينَ» غالِبِينَ", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, നിങ്ങൾ അല്ലാഹുവിന്റെ സഹായികളാകുവിൻ; മർയമിന്റെ മകൻ ഈസാ ഹവാരിയ്യുകളോട് (ശിഷ്യന്മാരോട്) ചോദിച്ചതുപോലെ: അല്ലാഹുവിലേക്ക് എന്നെ സഹായിക്കാൻ ആരാണുള്ളത്? ഹവാരിയ്യുകൾ പറഞ്ഞു: ഞങ്ങൾ അല്ലാഹുവിന്റെ സഹായികളാകുന്നു! അങ്ങനെ ഇസ്രാഈൽ സന്തതികളിൽ നിന്നൊരു വിഭാഗം വിശ്വസിക്കുകയും മറ്റൊരു വിഭാഗം അവിശ്വസിക്കുകയും ചെയ്തു; അപ്പോൾ വിശ്വസിച്ചവർക്ക് അവരുടെ ശത്രുക്കൾക്കെതിരെ നാം ശക്തി പകർന്നു; അങ്ങനെ അവർ വിജയികളായിത്തീർന്നു».", "malayalamMatn": "സത്യവിശ്വാസികളേ, നിങ്ങള്‍ അല്ലാഹുവിന്‍റെ സഹായികളായിരിക്കുക. മര്‍യമിന്‍റെ മകന്‍ ഈസാ അല്ലാഹുവിങ്കലേക്കുള്ള മാര്‍ഗത്തില്‍ എന്‍റെ സഹായികളായി ആരുണ്ട് എന്ന് ഹവാരികളോട് ചോദിച്ചതു പോലെ. ഹവാരികള്‍ പറഞ്ഞു: ഞങ്ങള്‍ അല്ലാഹുവിന്‍റെ സഹായികളാകുന്നു. അപ്പോള്‍ ഇസ്രായീല്‍ സന്തതികളില്‍ പെട്ട ഒരു വിഭാഗം വിശ്വസിക്കുകയും മറ്റൊരു വിഭാഗം അവിശ്വസിക്കുകയും ചെയ്തു. എന്നിട്ട് വിശ്വസിച്ചവര്‍ക്ക് അവരുടെ ശത്രുവിനെതിരില്‍ നാം പിന്‍ബലം നല്‍കുകയും അങ്ങനെ അവന്‍ മികവുറ്റവരായിത്തീരുകയും ചെയ്തു."}], "topPoints": ["പറയുന്നതും പ്രവർത്തിക്കുന്നതും തമ്മിലുള്ള പൊരുത്തം (خلاصة السورة)", "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള പോരാട്ടം"], "topQuestions": [{"q": "ഏറ്റവും മികച്ച കച്ചവടമായി ഈ സൂറത്ത് വിശേഷിപ്പിക്കുന്നത് എന്തിനെയാണ്?", "a": "അല്ലാഹുവിലും റസൂലിലും വിശ്വസിക്കുകയും അവന്റെ മാർഗ്ഗത്തിൽ പോരാടുകയും ചെയ്യുന്നതിനെ."}], "asbabAlNuzul": []}, {"surahNumber": 62, "surahNameArabic": "سُورَةُ الجُمُعَةِ", "surahNameMalayalam": "സൂറത്തുൽ ജുമുഅ (വെള്ളിയാഴ്ച)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ یُسَبِّحُ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِ ٱلۡمَلِكِ ٱلۡقُدُّوسِ ٱلۡعَزِیزِ ٱلۡحَكِیمِ\n", "jalalayn": "«يُسَبِّح اللَّه» يُنَزِّههُ فاللّام زائِدَة «ما فِي السَّماوات وما فِي الأَرْض» فِي ذِكْر ما تَغْلِيب لِلْأَكْثَرِ «المَلِك القُدُّوس» المُنَزَّه عَمّا لا يَلِيق بِهِ «العَزِيز الحَكِيم» فِي مُلْكه وصُنْعه", "malayalam": "«ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതുമെല്ലാം അല്ലാഹുവിന്റെ പരിശുദ്ധിയെ പ്രകീർത്തിക്കുന്നു; അവൻ സർവ്വാധിപനായ രാജാവും പരമപരിശുദ്ധനും പ്രതാപിയും പരമയുക്തിമാനുമാകുന്നു».", "malayalamMatn": "രാജാവും പരമപരിശുദ്ധനും പ്രതാപശാലിയും യുക്തിമാനുമായ അല്ലാഹുവെ ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതുമെല്ലാം പ്രകീര്‍ത്തിച്ചു കൊണ്ടിരിക്കുന്നു."}, {"ayahNumber": 2, "quranText": "هُوَ ٱلَّذِی بَعَثَ فِی ٱلۡأُمِّیِّـۧنَ رَسُولࣰا مِّنۡهُمۡ یَتۡلُوا۟ عَلَیۡهِمۡ ءَایَـٰتِهِۦ وَیُزَكِّیهِمۡ وَیُعَلِّمُهُمُ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُوا۟ مِن قَبۡلُ لَفِی ضَلَـٰلࣲ مُّبِینࣲ\n", "jalalayn": "«هُوَ الَّذِي بَعَثَ فِي الأُمِّيِّينَ» العَرَب والأُمِّيّ: مَن لا يَكْتُب ولا يَقْرَأ كِتابًا «رَسُولًا مِنهُمْ» هُوَ مُحَمَّد ﷺ «يَتْلُو عَلَيْهِمْ آياته» القُرْآن «ويُزَكِّيهِمْ» يُطَهِّرهُمْ مِن الشِّرْك «ويُعَلِّمهُمْ الكِتاب» القُرْآن «والحِكْمَة» ما فِيهِ مِن الأَحْكام «وإنْ» مُخَفَّفَة مِن الثَّقِيلَة واسْمها مَحْذُوف أيْ وإنَّهُمْ «كانُوا مِن قَبْل» قَبْل مَجِيئِهِ «لَفِي ضَلال مُبِين» بَيِّن", "malayalam": "«അക്ഷരജ്ഞാനമില്ലാത്ത ജനങ്ങൾക്കിടയിലേക്ക് അവരിൽ നിന്നുതന്നെയുള്ള ഒരു റസൂലിനെ നിയോഗിച്ചത് അവനത്രെ; അവൻ അവർക്ക് അവന്റെ സൂക്തങ്ങൾ ഓതിക്കേൾപിക്കുകയും അവരെ സംസ്കരിക്കുകയും വേദഗ്രന്ഥവും വിജ്ഞാനവും അവർക്ക് പഠിപ്പിക്കുകയും ചെയ്യുന്നു; തീർച്ചയായും അവർ ഇതിന് മുമ്പ് വ്യക്തമായ ദുർമാർഗ്ഗത്തിലായിരുന്നു».", "malayalamMatn": "അക്ഷരജ്ഞാനമില്ലാത്തവര്‍ക്കിടയില്‍, തന്‍റെ ദൃഷ്ടാന്തങ്ങള്‍ അവര്‍ക്ക് വായിച്ചുകേള്‍പിക്കുകയും അവരെ സംസ്കരിക്കുകയും അവര്‍ക്ക് വേദഗ്രന്ഥവും തത്വജ്ഞാനവും പഠിപ്പിക്കുകയും ചെയ്യാന്‍ അവരില്‍ നിന്നുതന്നെയുള്ള ഒരു ദൂതനെ നിയോഗിച്ചവനാകുന്നു അവന്‍. തീര്‍ച്ചയായും അവര്‍ മുമ്പ് വ്യക്തമായ വഴികേടിലായിരുന്നു."}, {"ayahNumber": 3, "quranText": "وَءَاخَرِینَ مِنۡهُمۡ لَمَّا یَلۡحَقُوا۟ بِهِمۡۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n", "jalalayn": "«وآخَرِينَ» عَطْف عَلى الأُمِّيِّينَ أيْ المَوْجُودِينَ «مِنهُمْ» والآتِينَ مِنهُمْ بَعْدهمْ «لَمّا» لَمْ «يَلْحَقُوا بِهِمْ» فِي السّابِقَة والفَضْل «وهُوَ العَزِيز الحَكِيم» فِي مُلْكه وصُنْعه وهُمْ التّابِعُونَ والِاقْتِصار عَلَيْهِمْ كاف فِي بَيان فَضْل الصَّحابَة المَبْعُوث فِيهِمْ النَّبِيّ ﷺ عَلى مَن عَداهُمْ مِمَّنْ بَعَثَ إلَيْهِمْ وآمَنُوا بِهِ مِن جَمِيع الإنْس والجِنّ إلى يَوْم القِيامَة لِأَنَّ كُلّ قَرْن خَيْر مِمَّنْ يَلِيه", "malayalam": "«അവരിൽ നിന്ന് ഇതുവരെ അവരോടൊപ്പം വന്നെത്തിയിട്ടില്ലാത്ത മറ്റുള്ളവർക്കും വേണ്ടിയത്രെ അത്; അവൻ പ്രതാപിയും പരമയുക്തിമാനുമാകുന്നു».", "malayalamMatn": "അവരില്‍പെട്ട ഇനിയും അവരോടൊപ്പം വന്നുചേര്‍ന്നിട്ടില്ലാത്ത മറ്റുള്ളവരിലേക്കും (അദ്ദേഹത്തെ നിയോഗിച്ചിരിക്കുന്നു.) അവനാകുന്നു പ്രതാപിയും യുക്തിമാനും."}, {"ayahNumber": 4, "quranText": "ذَ ٰ⁠لِكَ فَضۡلُ ٱللَّهِ یُؤۡتِیهِ مَن یَشَاۤءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ\n", "jalalayn": "«ذَلِكَ فَضْل اللَّه يُؤْتِيه مَن يَشاء» النَّبِيّ ومَن ذُكِرَ مَعَهُ", "malayalam": "«അത് അല്ലാഹുവിന്റെ ഔദാര്യമാകുന്നു; അവൻ ഉദ്ദേശിക്കുന്നവർക്ക് അവൻ അത് നൽകുന്നു; അല്ലാഹു മഹത്തായ ഔദാര്യത്തിന്റെ ഉടമയാകുന്നു».", "malayalamMatn": "അത് അല്ലാഹുവിന്‍റെ അനുഗ്രഹമാകുന്നു. അവന്‍ ഉദ്ദേശിക്കുന്നവര്‍ക്ക് അവന്‍ അത് നല്‍കുന്നു. അല്ലാഹു മഹത്തായ പ്രതിഫലം നല്‍കുന്നവനത്രെ."}, {"ayahNumber": 5, "quranText": "مَثَلُ ٱلَّذِینَ حُمِّلُوا۟ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ یَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ یَحۡمِلُ أَسۡفَارَۢاۚ بِئۡسَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِ ٱللَّهِۚ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ\n", "jalalayn": "«مَثَل الَّذِينَ حَمِّلُوا التَّوْراة» كُلِّفُوا العَمَل بِها «ثُمَّ لَمْ يَحْمِلُوها» لَمْ يَعْمَلُوا بِما فِيها مِن نَعْته ﷺ فَلَمْ يُؤْمِنُوا بِهِ «كَمَثَلِ الحِمار يَحْمِل أسْفارًا» أيْ كُتُبًا فِي عَدَم انْتِفاعه بِها «بِئْسَ مَثَل القَوْم الَّذِينَ كَذَّبُوا بِآياتِ اللَّه» المُصَدِّقَة لِلنَّبِيِّ ﷺ والمَخْصُوص بِالذَّمِّ مَحْذُوف تَقْدِيره هَذا المَثَل «واللَّه لا يَهْدِي القَوْم الظّالِمِينَ» الكافِرِينَ", "malayalam": "«തൗറാത്ത് ചുമതലപ്പെടുത്തപ്പെടുകയും പിന്നീട് അത് വേണ്ടവിധം ഉൾക്കൊള്ളാതിരിക്കുകയും ചെയ്തവരുടെ ഉപമ ഗ്രന്ഥങ്ങൾ ചുമക്കുന്ന കഴുതയുടെ ഉപമ പോലെയാകുന്നു; അല്ലാഹുവിന്റെ ദൃഷ്ടാന്തങ്ങളെ നിഷേധിച്ചു തള്ളിയ ജനതയുടെ ഉപമ എത്രയോ ചീത്ത! അക്രമികളായ ജനങ്ങളെ അല്ലാഹു നേർവഴിയിലാക്കുകയില്ല».", "malayalamMatn": "തൌറാത്ത് സ്വീകരിക്കാന്‍ ചുമതല ഏല്‍പിക്കപ്പെടുകയും, എന്നിട്ട് അത് ഏറ്റെടുക്കാതിരിക്കുകയും ചെയ്തവരുടെ (യഹൂദരുടെ) ഉദാഹരണം ഗ്രന്ഥങ്ങള്‍ ചുമക്കുന്ന കഴുതയുടേത് പോലെയാകുന്നു. അല്ലാഹുവിന്‍റെ ദൃഷ്ടാന്തങ്ങള്‍ നിഷേധിച്ചു കളഞ്ഞ ജനങ്ങളുടെ ഉപമ എത്രയോ ചീത്ത! അക്രമികളായ ജനങ്ങളെ അല്ലാഹു സന്‍മാര്‍ഗത്തിലാക്കുകയില്ല."}, {"ayahNumber": 6, "quranText": "قُلۡ یَـٰۤأَیُّهَا ٱلَّذِینَ هَادُوۤا۟ إِن زَعَمۡتُمۡ أَنَّكُمۡ أَوۡلِیَاۤءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلۡمَوۡتَ إِن كُنتُمۡ صَـٰدِقِینَ\n", "jalalayn": "«قُلْ يا أيّها الَّذِينَ هادُوا إنْ زَعَمْتُمْ أنَّكُمْ أوْلِياء لِلَّهِ مِن دُون النّاس فَتَمَنَّوْا المَوْت إنْ كُنْتُمْ صادِقِينَ» تَعَلَّقَ بِتَمَنَّوْا الشَّرْطانِ عَلى أنَّ الأَوَّل قَيْد فِي الثّانِي أيْ إنْ صَدَقْتُمْ فِي زَعْمكُمْ أنَّكُمْ أوْلِياء اللَّه والوَلِيّ يُؤْثِر الآخِرَة ومَبْدَؤُها المَوْت فَتَمَنَّوْهُ", "malayalam": "«പറയുക: ഹേ യഹൂദരേ, മറ്റുള്ള ജനങ്ങളെക്കൂടാതെ നിങ്ങൾ മാത്രമാണ് അല്ലാഹുവിന്റെ മിത്രങ്ങളെന്ന് നിങ്ങൾ വാദിക്കുകയാണെങ്കിൽ നിങ്ങൾ മരണത്തെ കൊതിച്ചു നോക്കൂ, നിങ്ങൾ സത്യവാന്മാരാണെങ്കിൽ!».", "malayalamMatn": "(നബിയേ,) പറയുക: തീര്‍ച്ചയായും യഹൂദികളായുള്ളവരേ, മറ്റു മനുഷ്യരെ കൂടാതെ നിങ്ങള്‍ മാത്രം അല്ലാഹുവിന്‍റെ മിത്രങ്ങളാണെന്ന് നിങ്ങള്‍ വാദിക്കുകയാണെങ്കില്‍ നിങ്ങള്‍ മരണം കൊതിക്കുക. നിങ്ങള്‍ സത്യവാന്‍മാരാണെങ്കില്‍."}, {"ayahNumber": 7, "quranText": "وَلَا یَتَمَنَّوۡنَهُۥۤ أَبَدَۢا بِمَا قَدَّمَتۡ أَیۡدِیهِمۡۚ وَٱللَّهُ عَلِیمُۢ بِٱلظَّـٰلِمِینَ\n", "jalalayn": "«ولا يَتَمَنَّوْنَهُ أبَدًا بِما قَدَّمَتْ أيْدِيهمْ» مِن كُفْرهمْ بِالنَّبِيِّ المُسْتَلْزِم لِكَذِبِهِمْ «واللَّه عَلِيم بِالظّالِمِينَ» الكافِرِينَ", "malayalam": "«എന്നാൽ തങ്ങളുടെ കൈകൾ മുൻകൂട്ടി ചെയ്തുവെച്ച ദുഷ്കർമ്മങ്ങൾ കാരണം അവർ ഒരിക്കലും മരണം കൊതിക്കുകയില്ല; അല്ലാഹു അക്രമികളെക്കുറിച്ച് സൂക്ഷ്മമായി അറിയുന്നവനത്രെ».", "malayalamMatn": "എന്നാല്‍ അവരുടെ കൈകള്‍ മുന്‍കൂട്ടി ചെയ്തുവെച്ചതിന്‍റെ ഫലമായി അവര്‍ ഒരിക്കലും അത് കൊതിക്കുകയില്ല. അല്ലാഹു അക്രമകാരികളെപ്പറ്റി അറിവുള്ളവനാകുന്നു."}, {"ayahNumber": 8, "quranText": "قُلۡ إِنَّ ٱلۡمَوۡتَ ٱلَّذِی تَفِرُّونَ مِنۡهُ فَإِنَّهُۥ مُلَـٰقِیكُمۡۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ فَیُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ\n", "jalalayn": "«قُلْ إنّ المَوْت الَّذِي تَفِرُّونَ مِنهُ فَإنَّهُ» الفاء زائِدَة «مُلاقِيكُمْ ثُمَّ تُرَدُّونَ إلى عالِم الغَيْب والشَّهادَة» السِّرّ والعَلانِيَة «فَيُنَبِّئكُمْ بِما كُنْتُمْ تَعْمَلُونَ» فَيُجازِيكُمْ بِهِ", "malayalam": "«പറയുക: നിങ്ങൾ ഏതൊരു മരണത്തിൽ നിന്ന് ഓടിയകലുന്നുവോ തീർച്ചയായും അത് നിങ്ങളെ കണ്ടുമുട്ടുക തന്നെ ചെയ്യും; പിന്നീട് അദൃശ്യവും ദൃശ്യവും അറിയുന്നവനിലേക്ക് നിങ്ങൾ മടക്കപ്പെടും; അപ്പോൾ നിങ്ങൾ പ്രവർത്തിച്ചുകൊണ്ടിരുന്നതിനെപ്പറ്റി അവൻ നിങ്ങൾക്ക് വിവരമറിയിക്കുന്നതാണ്».", "malayalamMatn": "(നബിയേ,) പറയുക: തീര്‍ച്ചയായും ഏതൊരു മരണത്തില്‍ നിന്ന് നിങ്ങള്‍ ഓടി അകലുന്നുവോ അത് തീര്‍ച്ചയായും നിങ്ങളുമായി കണ്ടുമുട്ടുന്നതാണ്‌. പിന്നീട് അദൃശ്യവും, ദൃശ്യവും അറിയുന്നവന്‍റെ അടുക്കലേക്ക് നിങ്ങള്‍ മടക്കപ്പെടുകയും ചെയ്യും. അപ്പോള്‍ നിങ്ങള്‍ പ്രവര്‍ത്തിച്ചുകൊണ്ടിരിക്കുന്നതിനെ പറ്റി അവന്‍ നിങ്ങളെ വിവരമറിയിക്കുന്നതാണ്‌."}, {"ayahNumber": 9, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا نُودِیَ لِلصَّلَوٰةِ مِن یَوۡمِ ٱلۡجُمُعَةِ فَٱسۡعَوۡا۟ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُوا۟ ٱلۡبَیۡعَۚ ذَ ٰ⁠لِكُمۡ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا إذا نُودِيَ لِلصَّلاةِ مِن» بِمَعْنى فِي «يَوْم الجُمُعَة فاسْعَوْا» فامْضُوا «إلى ذِكْر اللَّه» لِلصَّلاةِ «وذَرُوا البَيْع» اُتْرُكُوا عَقْده «ذَلِكُمْ خَيْر لَكُمْ إنْ كُنْتُمْ تَعْلَمُونَ» أنَّهُ خَيْر فافْعَلُوا", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, വെള്ളിയാഴ്ച നമസ്കാരത്തിനായി ബാങ്ക് വിളിക്കപ്പെട്ടാൽ അല്ലാഹുവിനെക്കുറിച്ചുള്ള സ്മരണയിലേക്ക് നിങ്ങൾ ധൃതിപ്പെട്ട് വരികയും വ്യാപാരം ഒഴിവാക്കുകയും ചെയ്യുവിൻ; അതാണ് നിങ്ങൾക്ക് ഏറ്റവും ഉത്തമം, നിങ്ങൾ അറിയുന്നവരാണെങ്കിൽ!».", "malayalamMatn": "സത്യവിശ്വാസികളേ, വെള്ളിയാഴ്ച നമസ്കാരത്തിന് വിളിക്കപ്പെട്ടാല്‍ അല്ലാഹുവെ പറ്റിയുള്ള സ്മരണയിലേക്ക് നിങ്ങള്‍ വേഗത്തില്‍ വരികയും, വ്യാപാരം ഒഴിവാക്കുകയും ചെയ്യുക. അതാണ് നിങ്ങള്‍ക്ക് ഉത്തമം; നിങ്ങള്‍ കാര്യം മനസ്സിലാക്കുന്നുവെങ്കില്‍."}, {"ayahNumber": 10, "quranText": "فَإِذَا قُضِیَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِی ٱلۡأَرۡضِ وَٱبۡتَغُوا۟ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُوا۟ ٱللَّهَ كَثِیرࣰا لَّعَلَّكُمۡ تُفۡلِحُونَ\n", "jalalayn": "«فَإذا قُضِيَتْ الصَّلاة فانْتَشِرُوا فِي الأَرْض» أمْر إباحَة «وابْتَغُوا» اُطْلُبُوا الرِّزْق «مِن فَضْل اللَّه واذْكُرُوا اللَّه» ذِكْرًا «كَثِيرًا لَعَلَّكُمْ تُفْلِحُونَ» تَفُوزُونَ كانَ ﷺ يَخْطُب يَوْم الجُمُعَة فَقَدِمَتْ عِير وضُرِبَ لِقُدُومِها الطَّبْل عَلى العادَة فَخَرَجَ لَها النّاس مِن المَسْجِد غَيْر اثْنَيْ عَشَر رَجُلًا فَنَزَلَتْ", "malayalam": "«അങ്ങനെ നമസ്കാരം നിർവ്വഹിച്ചു കഴിഞ്ഞാൽ നിങ്ങൾ ഭൂമിയിൽ വ്യാപിക്കുകയും അല്ലാഹുവിന്റെ ഔദാര്യത്തിൽ നിന്ന് ഉപജീവനം തേടുകയും ചെയ്യുവിൻ; നിങ്ങൾ അല്ലാഹുവെ ധാരാളമായി സ്മരിക്കുകയും ചെയ്യുക; നിങ്ങൾ വിജയം വരിച്ചേക്കാം».", "malayalamMatn": "അങ്ങനെ നമസ്കാരം നിര്‍വഹിക്കപ്പെട്ടു കഴിഞ്ഞാല്‍ നിങ്ങള്‍ ഭൂമിയില്‍ വ്യാപിച്ചു കൊള്ളുകയും, അല്ലാഹുവിന്‍റെ അനുഗ്രഹത്തില്‍ നിന്ന് തേടിക്കൊള്ളുകയും ചെയ്യുക. നിങ്ങള്‍ അല്ലാഹുവെ ധാരാളമായി ഓര്‍ക്കുകയും ചെയ്യുക. നിങ്ങള്‍ വിജയം പ്രാപിച്ചേക്കാം."}, {"ayahNumber": 11, "quranText": "وَإِذَا رَأَوۡا۟ تِجَـٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوۤا۟ إِلَیۡهَا وَتَرَكُوكَ قَاۤىِٕمࣰاۚ قُلۡ مَا عِندَ ٱللَّهِ خَیۡرࣱ مِّنَ ٱللَّهۡوِ وَمِنَ ٱلتِّجَـٰرَةِۚ وَٱللَّهُ خَیۡرُ ٱلرَّ ٰ⁠زِقِینَ\n", "jalalayn": "«وإذا رَأَوْا تِجارَة أوْ لَهْوًا انْفَضُّوا إلَيْها» أيْ التِّجارَة لِأَنَّها مَطْلُوبهمْ دُون اللَّهْو «وتَرَكُوك» فِي الخُطْبَة «قائِمًا قُلْ ما عِنْد اللَّه» مِن الثَّواب «خَيْر» لِلَّذِينَ آمَنُوا «مِن اللَّهْو ومِن التِّجارَة واللَّه خَيْر الرّازِقِينَ» يُقال: كُلّ إنْسان يَرْزُق عائِلَته أيْ مِن رِزْق اللَّه تَعالى", "malayalam": "«ഒരു കച്ചവടമോ വിനോദമോ കണ്ടപ്പോൾ അവർ അതിലേക്ക് പിരിഞ്ഞുപോവുകയും താങ്കളെ നിന്ന നിലയിൽ ഉപേക്ഷിക്കുകയും ചെയ്തു (ജുമുഅ ഖുതുബക്കിടയിൽ കച്ചവടസംഘം വന്നപ്പോൾ പന്ത്രണ്ട് പേരൊഴികെ പുറത്തേക്ക് പോയ പശ്ചാത്തലത്തിൽ ഇത് അവതരിച്ചു). പറയുക: അല്ലാഹുവിങ്കലുള്ളത് വിനോദത്തേക്കാളും കച്ചവടത്തേക്കാളും എത്രയോ ഉത്തമമാകുന്നു; അല്ലാഹു ഉപജീവനം നൽകുന്നവരിൽ ഏറ്റവും ഉത്തമനത്രെ!».", "malayalamMatn": "അവര്‍ ഒരു കച്ചവടമോ വിനോദമോ കണ്ടാല്‍ അവയുടെ അടുത്തേക്ക് പിരിഞ്ഞ് പോകുകയും നിന്നനില്‍പില്‍ നിന്നെ വിട്ടേക്കുകയും ചെയ്യുന്നതാണ്‌. നീ പറയുക: അല്ലാഹുവിന്‍റെ അടുക്കലുള്ളത് വിനോദത്തെക്കാളും കച്ചവടത്തെക്കാളും ഉത്തമമാകുന്നു. അല്ലാഹു ഉപജീവനം നല്‍കുന്നവരില്‍ ഏറ്റവും ഉത്തമനാകുന്നു."}], "topPoints": ["ജുമുഅ നമസ്കാരത്തിന്റെ പ്രാധാന്യം (خلاصة السورة)", "ഭൗതിക വ്യാപാരങ്ങളേക്കാൾ പ്രധാനം അല്ലാഹുവിനെ സ്മരിക്കുന്നതാണ്"], "topQuestions": [{"q": "ജുമുഅ ബാങ്ക് വിളിച്ചാൽ എന്ത് ചെയ്യാനാണ് അല്ലാഹു കൽപ്പിക്കുന്നത്?", "a": "കച്ചവടവും മറ്റും ഉപേക്ഷിച്ച് അല്ലാഹുവിനെ സ്മരിക്കാൻ ധൃതിപ്പെട്ട് പോകാൻ."}], "asbabAlNuzul": [{"ayahNumber": 11, "quranText": "وَإِذَا رَأَوۡا۟ تِجَـٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوۤا۟ إِلَیۡهَا وَتَرَكُوكَ قَاۤىِٕمࣰاۚ", "arabicSnippet": "كان صلى الله عليه وسلم يخطب يوم الجمعة فقدمت عير وضرب لقدومها الطبل على العادة فخرج لها الناس من المسجد إلا اثني عشر رجلا فنزلت: «وإذا رأوا تجارة أو لهوا انفضوا إليها وتركوك قائما...».", "malayalamExplanation": "മദീനയിൽ വലിയ ക്ഷാമമുണ്ടായിരുന്ന ഒരു ഘട്ടത്തിൽ, വെള്ളിയാഴ്ച നബി ﷺ ജുമുഅ ഖുതുബ നിർവ്വഹിച്ചുകൊണ്ടിരിക്കെ ദഹ്‌യതുൽ കൽബിയുടെ നേതൃത്വത്തിൽ ശാമിൽ നിന്നുള്ള ഭക്ഷ്യധാന്യങ്ങളുമായി കച്ചവടസംഘം വന്നെത്തി. വരവറിയിച്ച് ചെണ്ട കൊട്ടിയപ്പോൾ സാധനങ്ങൾ തീർന്നുപോകുമോ എന്ന് ഭയന്ന് പള്ളിയിലുണ്ടായിരുന്ന ആളുകൾ പന്ത്രണ്ട് പേരൊഴികെ (അബൂബക്കർ, ഉമർ തുടങ്ങിയവർ മാത്രം ബാക്കിയായി) പുറത്തേക്ക് ഓടിപ്പോയി. തിരുനബിയെ ഒറ്റക്ക് നിർത്തി കച്ചവടത്തിലേക്ക് ഓടിയതിനെ ഗൗരവമായി ഉണർത്തിയും അല്ലാഹുവിന്റെ പ്രതിഫലമാണ് ഉത്തമമെന്ന് വ്യക്തമാക്കിയും ഈ വചനം അവതരിച്ചു."}]}, {"surahNumber": 63, "surahNameArabic": "سُورَةُ المُنَافِقُونَ", "surahNameMalayalam": "സൂറത്തുൽ മുനാഫിഖൂൻ (കപടവിശ്വാസികൾ)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ إِذَا جَاۤءَكَ ٱلۡمُنَـٰفِقُونَ قَالُوا۟ نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ وَٱللَّهُ یَعۡلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ یَشۡهَدُ إِنَّ ٱلۡمُنَـٰفِقِینَ لَكَـٰذِبُونَ\n", "jalalayn": "«إذا جاءَك المُنافِقُونَ قالُوا» بِأَلْسِنَتِهِمْ عَلى خِلاف ما فِي قُلُوبهمْ «نَشْهَد إنّك لَرَسُول اللَّه واللَّه يَعْلَم إنّك لَرَسُوله واللَّه يَشْهَد» يَعْلَم «إنّ المُنافِقِينَ لَكاذِبُونَ» فِيما أضْمَرُوهُ مُخالِفًا لِما قالُوهُ", "malayalam": "«കപടവിശ്വാസികൾ നിന്റെ അടുക്കൽ വന്നാൽ അവർ പറയും: താങ്കൾ തീർച്ചയായും അല്ലാഹുവിന്റെ റസൂലാണെന്ന് ഞങ്ങൾ സാക്ഷ്യം വഹിക്കുന്നു; താങ്കൾ തന്റെ റസൂൽ തന്നെയാണെന്ന് അല്ലാഹുവിനറിയാം; എന്നാൽ കപടവിശ്വാസികൾ തീർച്ചയായും പെരുംകള്ളന്മാരാണെന്ന് അല്ലാഹു സാക്ഷ്യം വഹിക്കുന്നു» (കാരണം ഉള്ളിലില്ലാത്തതാണ് അവർ നാവുകൊണ്ട് പറയുന്നത്).", "malayalamMatn": "കപട വിശ്വാസികള്‍ നിന്‍റെ അടുത്ത് വന്നാല്‍ അവര്‍ പറയും: തീര്‍ച്ചയായും താങ്കള്‍ അല്ലാഹുവിന്‍റെ ദൂതനാണെന്ന് ഞങ്ങള്‍ സാക്ഷ്യം വഹിക്കുന്നു. അല്ലാഹുവിന്നറിയാം തീര്‍ച്ചയായും നീ അവന്‍റെ ദൂതനാണെന്ന്‌. തീര്‍ച്ചയായും മുനാഫിഖുകള്‍ (കപടന്‍മാര്‍) കള്ളം പറയുന്നവരാണ് എന്ന് അല്ലാഹു സാക്ഷ്യം വഹിക്കുന്നു."}, {"ayahNumber": 2, "quranText": "ٱتَّخَذُوۤا۟ أَیۡمَـٰنَهُمۡ جُنَّةࣰ فَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِۚ إِنَّهُمۡ سَاۤءَ مَا كَانُوا۟ یَعۡمَلُونَ\n", "jalalayn": "«اتَّخَذُوا أيْمانهمْ جُنَّة» سُتْرَة عَلى أمْوالهمْ ودِمائِهِمْ «فَصَدُّوا» بِها «عَنْ سَبِيل اللَّه» أيْ عَنْ الجِهاد فِيهِمْ", "malayalam": "«അവർ തങ്ങളുടെ കള്ളസത്യങ്ങളെ ഒരു പരിചയാക്കി വെച്ചിരിക്കുന്നു; അങ്ങനെ അവർ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ നിന്ന് ആളുകളെ തടഞ്ഞു; തീർച്ചയായും അവർ പ്രവർത്തിച്ചുകൊണ്ടിരിക്കുന്നത് എത്രയോ മോശമായ കാര്യമാകുന്നു!».", "malayalamMatn": "അവര്‍ അവരുടെ ശപഥങ്ങളെ ഒരു പരിചയാക്കിയിരിക്കയാണ്‌. അങ്ങനെ അവര്‍ അല്ലാഹുവിന്‍റെ മാര്‍ഗത്തില്‍ നിന്ന് (ജനങ്ങളെ) തടഞ്ഞിരിക്കുന്നു. തീര്‍ച്ചയായും അവര്‍ പ്രവര്‍ത്തിക്കുന്നത് എത്രയോ ചീത്ത തന്നെ."}, {"ayahNumber": 3, "quranText": "ذَ ٰ⁠لِكَ بِأَنَّهُمۡ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا یَفۡقَهُونَ\n", "jalalayn": "«ذَلِكَ» أيْ سُوء عَمَلهمْ «بِأَنَّهُمْ آمَنُوا» بِاللِّسانِ «ثُمَّ كَفَرُوا» بِالقَلْبِ أيْ اسْتَمَرُّوا عَلى كُفْرهمْ بِهِ «فَطُبِعَ» خُتِمَ «عَلى قُلُوبهمْ» بِالكُفْرِ «فَهُمْ لا يَفْقُهُونَ» الإيمان", "malayalam": "«അവർ ആദ്യം വിശ്വസിക്കുകയും പിന്നീട് അവിശ്വസിക്കുകയും ചെയ്തതുകൊണ്ടാകുന്നു അത്; അങ്ങനെ അവരുടെ ഹൃദയങ്ങളിൽ മുദ്രവെക്കപ്പെട്ടു; അതിനാൽ അവർ കാര്യം ഗ്രഹിക്കുകയില്ല».", "malayalamMatn": "അത്‌, അവര്‍ ആദ്യം വിശ്വസിക്കുകയും പിന്നീട് അവിശ്വസിക്കുകയും ചെയ്തതിന്‍റെ ഫലമത്രെ. അങ്ങനെ അവരുടെ ഹൃദയങ്ങളിന്‍മേല്‍ മുദ്രവെക്കപ്പെട്ടിരിക്കുന്നു. അതിനാല്‍ അവര്‍ (കാര്യം) ഗ്രഹിക്കുകയില്ല."}, {"ayahNumber": 4, "quranText": "۞ وَإِذَا رَأَیۡتَهُمۡ تُعۡجِبُكَ أَجۡسَامُهُمۡۖ وَإِن یَقُولُوا۟ تَسۡمَعۡ لِقَوۡلِهِمۡۖ كَأَنَّهُمۡ خُشُبࣱ مُّسَنَّدَةࣱۖ یَحۡسَبُونَ كُلَّ صَیۡحَةٍ عَلَیۡهِمۡۚ هُمُ ٱلۡعَدُوُّ فَٱحۡذَرۡهُمۡۚ قَـٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ یُؤۡفَكُونَ\n", "jalalayn": "«وإذا رَأَيْتهمْ تُعْجِبك أجْسامهمْ» لِجَمالِها «وإنْ يَقُولُوا تَسْمَع لِقَوْلِهِمْ» لِفَصاحَتِهِ «كَأَنَّهُمْ» مِن عِظَم أجْسامهمْ فِي تَرْك التَّفَهُّم «خُشْب» بِسُكُونِ الشِّين وضَمّها «مُسَنَّدَة» مُمالَة إلى الجِدار «يَحْسَبُونَ كُلّ صَيْحَة» تُصاح كَنِداءٍ فِي العَسْكَر وإنْشاد ضالَّة «عَلَيْهِمْ» لِما فِي قُلُوبهمْ مِن الرُّعْب أنْ يَنْزِل فِيهِمْ ما يُبِيح دِماءَهُمْ «هُمْ العَدُوّ فاحْذَرْهُمْ» فَإنَّهُمْ يُفْشُونَ سِرّك لِلْكُفّارِ «قاتَلَهُمْ اللَّه» أهْلَكَهُمْ «أنّى يُؤْفَكُونَ» كَيْفَ يُصْرَفُونَ عَنْ الإيمان بَعْد قِيام البُرْهان", "malayalam": "«നീ അവരെ കാണുകയാണെങ്കിൽ അവരുടെ ശരീരങ്ങൾ നിന്നെ അത്ഭുതപ്പെടുത്തും (അവരുടെ ബാഹ്യഭംഗിയും വലിപ്പവും കൊണ്ട്); അവർ സംസാരിക്കുകയാണെങ്കിൽ (വാക്ചാതുരി കാരണം) അവരുടെ വാക്ക് നീ കേട്ടിരുന്നുപോകും; എന്നാൽ അവർ ചുവരോട് ചാരിവെച്ച മരത്തടികൾ പോലെയാകുന്നു (ഉൾക്കാമ്പില്ലാത്തവർ); സൈന്യത്തിന്റെ വിളിയോ നഷ്ടപ്പെട്ടതിനായുള്ള തിരച്ചിലോ പോലുള്ള ഏതൊരു ഒച്ചയും തങ്ങൾക്കെതിരാണെന്ന് അവർ ഭയപ്പെടുന്നു; അവരത്രെ ശത്രുക്കൾ, അതിനാൽ അവരെ സൂക്ഷിക്കുക; അല്ലാഹു അവരെ നശിപ്പിക്കട്ടെ! എങ്ങനെയാണവർ സത്യത്തിൽ നിന്ന് തെറ്റിക്കപ്പെടുന്നത്!».", "malayalamMatn": "നീ അവരെ കാണുകയാണെങ്കില്‍ അവരുടെ ശരീരങ്ങള്‍ നിന്നെ അത്ഭുതപ്പെടുത്തും. അവര്‍ സംസാരിക്കുന്ന പക്ഷം നീ അവരുടെ വാക്ക് കേട്ടിരുന്നു പോകും. അവര്‍ ചാരിവെച്ച മരത്തടികള്‍ പോലെയാകുന്നു. എല്ലാ ഒച്ചയും തങ്ങള്‍ക്കെതിരാണെന്ന് അവര്‍ വിചാരിക്കും. അവരാകുന്നു ശത്രു. അവരെ സൂക്ഷിച്ചു കൊള്ളുക. അല്ലാഹു അവരെ നശിപ്പിക്കട്ടെ. എങ്ങനെയാണവര്‍ വഴിതെറ്റിക്കപ്പെടുന്നത്‌?"}, {"ayahNumber": 5, "quranText": "وَإِذَا قِیلَ لَهُمۡ تَعَالَوۡا۟ یَسۡتَغۡفِرۡ لَكُمۡ رَسُولُ ٱللَّهِ لَوَّوۡا۟ رُءُوسَهُمۡ وَرَأَیۡتَهُمۡ یَصُدُّونَ وَهُم مُّسۡتَكۡبِرُونَ\n", "jalalayn": "«وإذا قِيلَ لَهُمْ تَعالَوْا» مُعْتَذِرِينَ «يَسْتَغْفِر لَكُمْ رَسُول اللَّه لَوَّوْا» بِالتَّشْدِيدِ والتَّخْفِيف عَطَفُوا «رُءُوسهمْ ورَأَيْتهمْ يَصُدُّونَ» يُعْرِضُونَ عَنْ ذَلِكَ", "malayalam": "«നിങ്ങൾ വരൂ, അല്ലാഹുവിന്റെ റസൂൽ നിങ്ങൾക്കായി പാപമോചനം തേടിത്തരും എന്ന് അവരോട് പറയപ്പെട്ടാൽ അവർ തങ്ങളുടെ തലകൾ തിരിച്ചു കളയും; അവർ അഹങ്കാരം നടിച്ചുകൊണ്ട് പിന്തിരിഞ്ഞു പോകുന്നത് നിനക്ക് കാണാം».", "malayalamMatn": "നിങ്ങള്‍ വരൂ. അല്ലാഹുവിന്‍റെ ദൂതന്‍ നിങ്ങള്‍ക്ക് വേണ്ടി പാപമോചനത്തിന് പ്രാര്‍ത്ഥിച്ചുകൊള്ളും എന്ന് അവരോട് പറയപ്പെട്ടാല്‍ അവര്‍ അവരുടെ തല തിരിച്ചുകളയും. അവര്‍ അഹങ്കാരം നടിച്ചു കൊണ്ട് തിരിഞ്ഞുപോകുന്നതായി നിനക്ക് കാണുകയും ചെയ്യാം."}, {"ayahNumber": 6, "quranText": "سَوَاۤءٌ عَلَیۡهِمۡ أَسۡتَغۡفَرۡتَ لَهُمۡ أَمۡ لَمۡ تَسۡتَغۡفِرۡ لَهُمۡ لَن یَغۡفِرَ ٱللَّهُ لَهُمۡۚ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡفَـٰسِقِینَ\n", "jalalayn": "«سَواء عَلَيْهِمْ أسْتَغْفَرْت لَهُمْ» اُسْتُغْنِيَ بِهَمْزَةِ الِاسْتِفْهام عَنْ هَمْزَة الوَصْل", "malayalam": "«നീ അവർക്കായി പാപമോചനം തേടിയാലും അവർക്കായി പാപമോചനം തേടാതിരുന്നാലും അവരെ സംബന്ധിച്ചിടത്തോളം സമമാകുന്നു; അല്ലാഹു ഒരിക്കലും അവർക്ക് പൊറുത്തുകൊടുക്കുകയില്ല; തീർച്ചയായും അധർമ്മകാരികളായ ജനങ്ങളെ അല്ലാഹു നേർവഴിയിലാക്കുകയില്ല».", "malayalamMatn": "നീ അവര്‍ക്ക് വേണ്ടി പാപമോചനത്തിന് പ്രാര്‍ത്ഥിച്ചാലും പ്രാര്‍ത്ഥിച്ചിട്ടില്ലെങ്കിലും അവരെ സംബന്ധിച്ചിടത്തോളം സമമാകുന്നു. അല്ലാഹു ഒരിക്കലും അവര്‍ക്കു പൊറുത്തുകൊടുക്കുകയില്ല. തീര്‍ച്ചയായും അല്ലാഹു ദുര്‍മാര്‍ഗികളായ ജനങ്ങളെ നേര്‍വഴിയിലാക്കുകയില്ല."}, {"ayahNumber": 7, "quranText": "هُمُ ٱلَّذِینَ یَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنۡ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ یَنفَضُّوا۟ۗ وَلِلَّهِ خَزَاۤىِٕنُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَلَـٰكِنَّ ٱلۡمُنَـٰفِقِینَ لَا یَفۡقَهُونَ\n", "jalalayn": "«هُمْ الَّذِينَ يَقُولُونَ» لِأَصْحابِهِمْ مِن الأَنْصار «لا تُنْفِقُوا عَلى مَن عِنْد رَسُول اللَّه» مِن المُهاجِرِينَ «حَتّى يَنْفَضُّوا» يَتَفَرَّقُوا عَنْهُ «ولِلَّهِ خَزائِن السَّماوات والأَرْض» بِالرِّزْقِ فَهُوَ الرّازِق لِلْمُهاجِرِينَ وغَيْرهمْ", "malayalam": "«അല്ലാഹുവിന്റെ റസൂലിന്റെ കൂടെയുള്ളവർക്കായി അവർ പിരിഞ്ഞുപോകുന്നത് വരെ നിങ്ങൾ യാതൊന്നും ചെലവഴിക്കരുത് എന്ന് പറയുന്നവരാകുന്നു അവർ (അബ്ദുല്ലാഹിബ്നു ഉബയ്യും കൂട്ടുകാരും); ആകാശങ്ങളുടെയും ഭൂമിയുടെയും ഖജനാവുകൾ അല്ലാഹുവിന്നുള്ളതാകുന്നു; എന്നാൽ കപടവിശ്വാസികൾ അത് ഗ്രഹിക്കുന്നില്ല».", "malayalamMatn": "അല്ലാഹുവിന്‍റെ ദൂതന്‍റെ അടുക്കലുള്ളവര്‍ക്ക് വേണ്ടി, അവര്‍ (അവിടെ നിന്ന്‌) പിരിഞ്ഞു പോകുന്നത് വരെ നിങ്ങള്‍ ഒന്നും ചെലവ് ചെയ്യരുത് എന്ന് പറയുന്നവരാകുന്നു അവര്‍. അല്ലാഹുവിന്‍റെതാകുന്നു ആകാശങ്ങളിലെയും ഭൂമിയിലെയും ഖജനാവുകള്‍. പക്ഷെ കപടന്‍മാര്‍ കാര്യം ഗ്രഹിക്കുന്നില്ല."}, {"ayahNumber": 8, "quranText": "یَقُولُونَ لَىِٕن رَّجَعۡنَاۤ إِلَى ٱلۡمَدِینَةِ لَیُخۡرِجَنَّ ٱلۡأَعَزُّ مِنۡهَا ٱلۡأَذَلَّۚ وَلِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِینَ وَلَـٰكِنَّ ٱلۡمُنَـٰفِقِینَ لَا یَعۡلَمُونَ\n", "jalalayn": "«يَقُولُونَ لَئِنْ رَجَعْنا» أيْ مِن غَزْوَة بَنِي المُصْطَلِق «إلى المَدِينَة لَيُخْرِجَن الأَعَزّ» عَنَوْا بِهِ أنْفُسهمْ «مِنها الأَذَلّ» عَنَوْا بِهِ المُؤْمِنِينَ «ولِلَّهِ العِزَّة» الغَلَبَة «ولِرَسُولِهِ ولِلْمُؤْمِنِينَ ولَكِنَّ المُنافِقِينَ لا يَعْلَمُونَ» ذَلِكَ", "malayalam": "«അവർ പറയുന്നു: നാം മദീനയിലേക്ക് തിരിച്ചെത്തിയാൽ പ്രതാപമുള്ളവൻ നിന്ദ്യനായവനെ അവിടെനിന്ന് പുറത്താക്കുക തന്നെ ചെയ്യും! എന്നാൽ അല്ലാഹുവിനും അവന്റെ റസൂലിനും സത്യവിശ്വാസികൾക്കുമാകുന്നു പ്രതാപം; പക്ഷേ കപടവിശ്വാസികൾ അത് മനസ്സിലാക്കുന്നില്ല».", "malayalamMatn": "അവര്‍ പറയുന്നു; ഞങ്ങള്‍ മദീനയിലേക്ക് മടങ്ങിച്ചെന്നാല്‍ കൂടുതല്‍ പ്രതാപമുള്ളവര്‍ നിന്ദ്യരായുള്ളവരെ പുറത്താക്കുക തന്നെ ചെയ്യുമെന്ന്‌. അല്ലാഹുവിനും അവന്‍റെ ദൂതന്നും സത്യവിശ്വാസികള്‍ക്കുമാകുന്നു പ്രതാപം. പക്ഷെ, കപടവിശ്വാസികള്‍ (കാര്യം) മനസ്സിലാക്കുന്നില്ല."}, {"ayahNumber": 9, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تُلۡهِكُمۡ أَمۡوَ ٰ⁠لُكُمۡ وَلَاۤ أَوۡلَـٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ وَمَن یَفۡعَلۡ ذَ ٰ⁠لِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا لا تُلْهِكُمْ» تَشْغَلكُمْ «أمْوالكُمْ ولا أوْلادكُمْ عَنْ ذِكْر اللَّه» الصَّلَوات الخَمْس", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, നിങ്ങളുടെ സ്വത്തുക്കളും നിങ്ങളുടെ സന്താനങ്ങളും അല്ലാഹുവെക്കുറിച്ചുള്ള സ്മരണയിൽ നിന്ന് നിങ്ങളുടെ ശ്രദ്ധ തിരിച്ചുവിടാതിരിക്കട്ടെ; ആരെങ്കിലും അപ്രകാരം ചെയ്യുകയാണെങ്കിൽ അവരത്രെ നഷ്ടം പറ്റിയവർ!».", "malayalamMatn": "സത്യവിശ്വാസികളേ, നിങ്ങളുടെ സ്വത്തുക്കളും സന്താനങ്ങളും അല്ലാഹുവെപ്പറ്റിയുള്ള സ്മരണയില്‍ നിന്ന് നിങ്ങളുടെ ശ്രദ്ധതിരിച്ചുവിടാതിരിക്കട്ടെ. ആര്‍ അങ്ങനെ ചെയ്യുന്നുവോ അവര്‍ തന്നെയാണ് നഷ്ടക്കാര്‍."}, {"ayahNumber": 10, "quranText": "وَأَنفِقُوا۟ مِن مَّا رَزَقۡنَـٰكُم مِّن قَبۡلِ أَن یَأۡتِیَ أَحَدَكُمُ ٱلۡمَوۡتُ فَیَقُولَ رَبِّ لَوۡلَاۤ أَخَّرۡتَنِیۤ إِلَىٰۤ أَجَلࣲ قَرِیبࣲ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّـٰلِحِینَ\n", "jalalayn": "«وأَنْفِقُوا» فِي الزَّكاة «مِمّا رَزَقْناكُمْ مِن قَبْل أنْ يَأْتِي أحَدكُمْ المَوْت فَيَقُول رَبّ لَوْلا» بِمَعْنى هَلّا أوْ لا زائِدَة ولَوْ لِلتَّمَنِّي «أخَّرْتنِي إلى أجَل قَرِيب فَأَصَّدَّق» بِإدْغامِ التّاء فِي الأَصْل فِي الصّاد أتَصَدَّق بِالزَّكاةِ «وأَكُنْ مِن الصّالِحِينَ» بِأَنْ أحُجّ قالَ ابْن عَبّاس رَضِيَ اللَّه عَنْهُما: ما قَصَّرَ أحَد فِي الزَّكاة والحَجّ إلّا سَأَلَ الرَّجْعَة عِنْد المَوْت", "malayalam": "«നിങ്ങളിൽ ഒരാൾക്ക് മരണം വന്നെത്തുന്നതിന് മുമ്പായി, നിങ്ങൾക്ക് നാം നൽകിയതിൽ നിന്ന് നിങ്ങൾ ചെലവഴിക്കുവിൻ; അപ്പോൾ അവൻ പറയും: എന്റെ രക്ഷിതാവേ, അടുത്ത ഒരു അവധി വരെ നീ എനിക്ക് സമയം നീട്ടിത്തന്നുകൂടായിരുന്നോ? എങ്കിൽ ഞാൻ ദാനം ചെയ്യുകയും സജ്ജനങ്ങളിൽ പെട്ടവനായിത്തീരുകയും ചെയ്യുമായിരുന്നു!».", "malayalamMatn": "നിങ്ങളില്‍ ഓരോരുത്തര്‍ക്കും മരണം വരുന്നതിനു മുമ്പായി നിങ്ങള്‍ക്ക് നാം നല്‍കിയതില്‍ നിന്ന് നിങ്ങള്‍ ചെലവഴിക്കുകയും ചെയ്യുക. അന്നേരത്ത് അവന്‍ ഇപ്രകാരം പറഞ്ഞേക്കും. എന്‍റെ രക്ഷിതാവേ, അടുത്ത ഒരു അവധിവരെ നീ എനിക്ക് എന്താണ് നീട്ടിത്തരാത്തത്‌? എങ്കില്‍ ഞാന്‍ ദാനം നല്‍കുകയും, സജ്ജനങ്ങളുടെ കൂട്ടത്തിലാവുകയും ചെയ്യുന്നതാണ്‌."}, {"ayahNumber": 11, "quranText": "وَلَن یُؤَخِّرَ ٱللَّهُ نَفۡسًا إِذَا جَاۤءَ أَجَلُهَاۚ وَٱللَّهُ خَبِیرُۢ بِمَا تَعۡمَلُونَ\n", "jalalayn": "«ولَنْ يُؤَخِّر اللَّه نَفْسًا إذا جاءَ أجَلها واللَّه خَبِير بِما تَعْمَلُونَ» بِالتّاءِ والياء", "malayalam": "«എന്നാൽ ഒരാൾക്കും അയാളുടെ അവധി വന്നെത്തിയാൽ അല്ലാഹു സമയം നീട്ടിക്കൊടുക്കുകയേ ഇല്ല; നിങ്ങൾ പ്രവർത്തിക്കുന്നതിനെപ്പറ്റി അല്ലാഹു സൂക്ഷ്മമായി അറിയുന്നവനത്രെ».", "malayalamMatn": "ഒരാള്‍ക്കും അയാളുടെ അവധി വന്നെത്തിയാല്‍ അല്ലാഹു നീട്ടികൊടുക്കുകയേ ഇല്ല. അല്ലാഹു നിങ്ങള്‍ പ്രവര്‍ത്തിക്കുന്നതിനെപ്പറ്റി സൂക്ഷ്മമായി അറിയുന്നവനാകുന്നു."}], "topPoints": ["കപടവിശ്വാസികളുടെ സ്വഭാവങ്ങൾ (خلاصة السورة)", "സമ്പത്തും മക്കളും അല്ലാഹുവിനെ സ്മരിക്കുന്നതിൽ നിന്ന് തടയാതിരിക്കുക"], "topQuestions": [{"q": "കപടവിശ്വാസികളുടെ പ്രധാന ലക്ഷണം എന്താണ്?", "a": "പുറമെ വിശ്വാസം പ്രകടിപ്പിക്കുകയും ഉള്ളിൽ അവിശ്വാസം മറച്ചുവെക്കുകയും ചെയ്യുക."}], "asbabAlNuzul": [{"ayahNumber": 8, "quranText": "یَقُولُونَ لَىِٕن رَّجَعۡنَاۤ إِلَى ٱلۡمَدِینَةِ لَیُخۡرِجَنَّ ٱلۡأَعَزُّ مِنۡهَا ٱلۡأَذَلَّۚ", "arabicSnippet": "نزلت في عبد الله بن أبي بن سلول رأس المنافقين لما قال في غزوة بني المصطلق: لئن رجعنا إلى المدينة ليخرجن الأعز منها الأذل، فرد الله عليه: «ولله العزة ولرسوله وللمؤمنين ولكن المنافقين لا يعلمون».", "malayalamExplanation": "ബനൂ മുസ്ത്വലിഖ് യുദ്ധവേളയിൽ മുഹാജിറുകളും അൻസാറുകളും തമ്മിൽ ചെറിയൊരു വാക്കുതർക്കമുണ്ടായപ്പോൾ, കപടവിശ്വാസികളുടെ നേതാവായ അബ്ദുല്ലാഹി ബ്നു ഉബയ്യ് ബ്നു സലൂൽ 'നമ്മൾ മദീനയിലേക്ക് മടങ്ങിയെത്തിയാൽ പ്രതാപശാലികൾ (കപടവിശ്വാസികൾ) നിന്ദ്യരെ (നബിയെയും മുഹാജിറുകളെയും) പുറത്താക്കുക തന്നെ ചെയ്യും' എന്ന് അഹങ്കാരത്തോടെ പറഞ്ഞു. സൈദ് ബിൻ അർഖം (റ) ഈ വിവരം നബി ﷺ യെ അറിയിച്ചപ്പോൾ ഇബ്‌നു ഉബയ്യ് കള്ളസത്യം ചെയ്ത് രക്ഷപ്പെടാൻ ശ്രമിച്ചു. എന്നാൽ സൈദ് (റ) പറഞ്ഞത് സത്യമാണെന്ന് സ്ഥിരീകരിച്ചും യഥാർത്ഥ പ്രതാപം അല്ലാഹുവിനും റസൂലിനും വിശ്വാസികൾക്കുമാണെന്ന് പ്രഖ്യാപിച്ചും ഈ വചനം അവതരിച്ചു."}]}, {"surahNumber": 64, "surahNameArabic": "سُورَةُ التَّغَابُنِ", "surahNameMalayalam": "സൂറത്തുത്തഗാബുൻ (നഷ്ടം വെളിപ്പെടൽ)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ یُسَبِّحُ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۖ لَهُ ٱلۡمُلۡكُ وَلَهُ ٱلۡحَمۡدُۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ\n", "jalalayn": "«يُسَبِّح لِلَّهِ ما فِي السَّماوات وما فِي الأَرْض» يُنَزِّههُ فاللّام زائِدَة وأَتى بِما دُون مِن تَغْلِيبًا لِلْأَكْثَرِ", "malayalam": "«ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതുമെല്ലാം അല്ലാഹുവിന്റെ പരിശുദ്ധിയെ പ്രകീർത്തിക്കുന്നു; അവന്നത്രെ ആധിപത്യം, അവന്നത്രെ സർവ്വസ്തുതിയും; അവൻ സർവ്വകാര്യങ്ങൾക്കും കഴിവുള്ളവനത്രെ».", "malayalamMatn": "ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതും അല്ലാഹുവെ പ്രകീര്‍ത്തിക്കുന്നു. അവന്നാണ് ആധിപത്യം. അവന്നാണ് സ്തുതി. അവന്‍ ഏതുകാര്യത്തിനും കഴിവുള്ളവനാകുന്നു."}, {"ayahNumber": 2, "quranText": "هُوَ ٱلَّذِی خَلَقَكُمۡ فَمِنكُمۡ كَافِرࣱ وَمِنكُم مُّؤۡمِنࣱۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرٌ\n", "jalalayn": "«هُوَ الَّذِي خَلَقَكُمْ فَمِنكُمْ كافِر ومِنكُمْ مُؤْمِن» فِي أصْلِ الخِلْقَة ثُمَّ يُمِيتكُمْ ويُعِيدكُمْ عَلى ذَلِكَ", "malayalam": "«നിങ്ങളെ സൃഷ്ടിച്ചവൻ അവനത്രെ; എന്നിട്ട് നിങ്ങളിൽ അവിശ്വാസികളുമുണ്ട്, നിങ്ങളിൽ വിശ്വാസികളുമുണ്ട്; നിങ്ങൾ പ്രവർത്തിക്കുന്നതെല്ലാം അല്ലാഹു കണ്ടറിയുന്നവനത്രെ».", "malayalamMatn": "അവനാണ് നിങ്ങളെ സൃഷ്ടിച്ചവന്‍. എന്നിട്ട് നിങ്ങളുടെ കൂട്ടത്തില്‍ സത്യനിഷേധിയുണ്ട്‌. നിങ്ങളുടെ കൂട്ടത്തില്‍ വിശ്വാസിയുമുണ്ട്‌. അല്ലാഹു നിങ്ങള്‍ പ്രവര്‍ത്തിക്കുന്നതിനെ പറ്റി കണ്ടറിയുന്നവനാകുന്നു."}, {"ayahNumber": 3, "quranText": "خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡۖ وَإِلَیۡهِ ٱلۡمَصِیرُ\n", "jalalayn": "«خَلَقَ السَّمَوات والأَرْض بِالحَقِّ وصَوَّرَكُمْ فَأَحْسَنَ صُوَركُمْ» إذْ جَعَلَ شَكْل الآدَمِيّ أحْسَن الأَشْكال", "malayalam": "«ആകാശങ്ങളെയും ഭൂമിയെയും യഥാർത്ഥ ലക്ഷ്യത്തോടെ അവൻ സൃഷ്ടിച്ചു; അവൻ നിങ്ങൾക്ക് രൂപം നൽകുകയും നിങ്ങളുടെ രൂപങ്ങൾ ഏറ്റവും മനോഹരമാക്കുകയും ചെയ്തു; അവങ്കലേക്ക് തന്നെയാണ് തിരിച്ചുവരവ്».", "malayalamMatn": "ആകാശങ്ങളും, ഭൂമിയും അവന്‍ മുറപ്രകാരം സൃഷ്ടിച്ചിരിക്കുന്നു. നിങ്ങള്‍ക്കവന്‍ രൂപം നല്‍കുകയും, നിങ്ങളുടെ രൂപങ്ങള്‍ അവന്‍ നന്നാക്കുകയും ചെയ്തിരിക്കുന്നു. അവങ്കലേക്കാകുന്നു തിരിച്ചുപോക്ക്‌."}, {"ayahNumber": 4, "quranText": "یَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَیَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَۚ وَٱللَّهُ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ\n", "jalalayn": "«يَعْلَم ما فِي السَّمَوات والأَرْض ويَعْلَم ما تُسِرُّونَ وما تُعْلِنُونَ واللَّه عَلِيم بِذاتِ الصُّدُور» بِما فِيها مِن الأَسْرار والمُعْتَقَدات", "malayalam": "«ആകാശങ്ങളിലും ഭൂമിയിലുമുള്ളതെല്ലാം അവൻ അറിയുന്നു; നിങ്ങൾ രഹസ്യമാക്കുന്നതും നിങ്ങൾ പരസ്യമാക്കുന്നതും അവൻ അറിയുന്നു; ഹൃദയങ്ങളിലുള്ള രഹസ്യങ്ങളെക്കുറിച്ച് അല്ലാഹു ഏറ്റവും നന്നായി അറിയുന്നവനത്രെ».", "malayalamMatn": "ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതും അവന്‍ അറിയുന്നു. നിങ്ങള്‍ രഹസ്യമാക്കുന്നതും പരസ്യമാക്കുന്നതും അവന്‍ അറിയുന്നു. അല്ലാഹു ഹൃദയങ്ങളിലുള്ളത് അറിയുന്നവനാകുന്നു."}, {"ayahNumber": 5, "quranText": "أَلَمۡ یَأۡتِكُمۡ نَبَؤُا۟ ٱلَّذِینَ كَفَرُوا۟ مِن قَبۡلُ فَذَاقُوا۟ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِیمࣱ\n", "jalalayn": "«ألَمْ يَأْتِكُمْ» يا كُفّار مَكَّة «نَبَأ» خَبَر «الَّذِينَ كَفَرُوا مِن قَبْل فَذاقُوا وبال أمْرهمْ» عُقُوبَة الكُفْر فِي الدُّنْيا «ولَهُمْ» فِي الآخِرَة «عَذاب ألِيم» مُؤْلِم", "malayalam": "«മുമ്പ് അവിശ്വസിച്ചവരുടെ വൃത്താന്തം നിങ്ങൾക്ക് വന്നെത്തിയില്ലയോ? അങ്ങനെ അവർ തങ്ങളുടെ ചെയ്തികളുടെ ദുഷ്ഫലം ഇഹലോകത്ത് അനുഭവിച്ചു; അവർക്ക് പരലോകത്ത് വേദനാജനകമായ ശിക്ഷയുമുണ്ട്».", "malayalamMatn": "മുമ്പ് അവിശ്വസിച്ചവരുടെ വൃത്താന്തം നിങ്ങള്‍ക്കു വന്നുകിട്ടിയിട്ടില്ലേ? അങ്ങനെ അവരുടെ നിലപാടിന്‍റെ ഭവിഷ്യത്ത് അവര്‍ അനുഭവിച്ചു. അവര്‍ക്കു (പരലോകത്ത്‌) വേദനയേറിയ ശിക്ഷയുമുണ്ട്‌."}, {"ayahNumber": 6, "quranText": "ذَ ٰ⁠لِكَ بِأَنَّهُۥ كَانَت تَّأۡتِیهِمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ فَقَالُوۤا۟ أَبَشَرࣱ یَهۡدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ۖ وَّٱسۡتَغۡنَى ٱللَّهُۚ وَٱللَّهُ غَنِیٌّ حَمِیدࣱ\n", "jalalayn": "«ذَلِكَ» أيْ عَذاب الدُّنْيا «بِأَنَّهُ» ضَمِير الشَّأْن «كانَتْ تَأْتِيهِمْ رُسُلهمْ بِالبَيِّناتِ» الحُجَج الظّاهِرات عَلى الإيمان «فَقالُوا أبَشَر» أُرِيدَ بِهِ الجِنْس «يَهْدُونَنا فَكَفَرُوا وتَوَلَّوْا» عَنْ الإيمان «واسْتَغْنى اللَّه» عَنْ إيمانهمْ «واللَّه غَنِيّ» عَنْ خَلْقه «حَمِيد» مَحْمُود فِي أفْعاله", "malayalam": "«അവരുടെ റസൂലുകൾ വ്യക്തമായ തെളിവുകളുമായി അവരുടെ അടുക്കൽ വരികയും, അപ്പോൾ അവർ: നമ്മെ ഒരു മനുഷ്യനാണോ നേർവഴിയിലാക്കുന്നത് എന്ന് പറഞ്ഞ് നിഷേധിക്കുകയും പിന്തിരിഞ്ഞു കളയുകയും ചെയ്തതുകൊണ്ടാകുന്നു അത്; അല്ലാഹു അവരുടെ ആശ്രയങ്ങളിൽ നിന്ന് സ്വയം മതിയായവനായിരിക്കുന്നു; അല്ലാഹു പരാശ്രയമുക്തനും സ്തുത്യർഹനുമാകുന്നു».", "malayalamMatn": "അതെന്തുകൊണ്ടെന്നാല്‍ അവരിലേക്കുള്ള ദൂതന്‍മാര്‍ വ്യക്തമായ തെളിവുകളും കൊണ്ട് അവരുടെ അടുക്കല്‍ ചെല്ലാറുണ്ടായിരുന്നു. അപ്പോള്‍ അവര്‍ പറഞ്ഞു: ഒരു മനുഷ്യന്‍ നമുക്ക് മാര്‍ഗദര്‍ശനം നല്‍കുകയോ? അങ്ങനെ അവര്‍ അവിശ്വസിക്കുകയും പിന്തിരിഞ്ഞു കളയുകയും ചെയ്തു. അല്ലാഹു സ്വയം പര്യാപ്തനായിരിക്കുന്നു. അല്ലാഹു പരാശ്രയമുക്തനും സ്തുത്യര്‍ഹനുമാകുന്നു."}, {"ayahNumber": 7, "quranText": "زَعَمَ ٱلَّذِینَ كَفَرُوۤا۟ أَن لَّن یُبۡعَثُوا۟ۚ قُلۡ بَلَىٰ وَرَبِّی لَتُبۡعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلۡتُمۡۚ وَذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣱ\n", "jalalayn": "«زَعَمَ الَّذِينَ كَفَرُوا أنْ» مُخَفَّفَة واسْمها مَحْذُوف أيْ أنَّهُمْ", "malayalam": "«തങ്ങൾ ഒരിക്കലും ഉയിർത്തെഴുന്നേൽപിക്കപ്പെടുകയില്ലെന്ന് അവിശ്വാസികൾ വാദിച്ചു; പറയുക: അങ്ങനെയല്ല, എന്റെ രക്ഷിതാവിനെത്തന്നെയാണ് സത്യം! നിങ്ങൾ തീർച്ചയായും ഉയിർത്തെഴുന്നേൽപിക്കപ്പെടും; പിന്നീട് നിങ്ങൾ പ്രവർത്തിച്ചതിനെക്കുറിച്ച് നിങ്ങൾക്ക് വിവരമറിയിക്കപ്പെടുക തന്നെ ചെയ്യും; അത് അല്ലാഹുവിന് വളരെ എളുപ്പമുള്ള കാര്യമാകുന്നു!».", "malayalamMatn": "തങ്ങള്‍ ഉയിര്‍ത്തെഴുന്നേല്‍പിക്കപ്പെടുകയില്ലെന്ന് ആ അവിശ്വാസികള്‍ ജല്‍പിച്ചു.(നബിയേ,)പറയുക: അതെ; എന്‍റെ രക്ഷിതാവിനെ തന്നെയാണ, നിങ്ങള്‍ ഉയിര്‍ത്തെഴുന്നേല്‍പിക്കപ്പെടും. പിന്നീട് നിങ്ങള്‍ പ്രവര്‍ത്തിച്ചതിനെപ്പറ്റി നിങ്ങള്‍ക്ക് വിവരമറിയിക്കപ്പെടുകയും ചെയ്യും. അത് അല്ലാഹുവെ സംബന്ധിച്ചിടത്തോളം എളുപ്പമുള്ളതാകുന്നു."}, {"ayahNumber": 8, "quranText": "فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِیۤ أَنزَلۡنَاۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ\n", "jalalayn": "«فَآمِنُوا بِاللَّهِ ورَسُوله والنُّور» القُرْآن", "malayalam": "«ആകയാൽ നിങ്ങൾ അല്ലാഹുവിലും അവന്റെ റസൂലിലും നാം അവതരിപ്പിച്ച പ്രകാശത്തിലും (ഖുർആനിലും) വിശ്വസിക്കുവിൻ; നിങ്ങൾ പ്രവർത്തിക്കുന്നതിനെപ്പറ്റി അല്ലാഹു സൂക്ഷ്മമായി അറിയുന്നവനത്രെ».", "malayalamMatn": "അതിനാല്‍ നിങ്ങള്‍ അല്ലാഹുവിലും അവന്‍റെ ദൂതനിലും നാം അവതരിപ്പിച്ച പ്രകാശത്തിലും വിശ്വസിച്ചുകൊള്ളുക. അല്ലാഹു നിങ്ങള്‍ പ്രവര്‍ത്തിക്കുന്നതിനെപ്പറ്റി സൂക്ഷ്മമായി അറിയുന്നവനാണ്‌."}, {"ayahNumber": 9, "quranText": "یَوۡمَ یَجۡمَعُكُمۡ لِیَوۡمِ ٱلۡجَمۡعِۖ ذَ ٰ⁠لِكَ یَوۡمُ ٱلتَّغَابُنِۗ وَمَن یُؤۡمِنۢ بِٱللَّهِ وَیَعۡمَلۡ صَـٰلِحࣰا یُكَفِّرۡ عَنۡهُ سَیِّـَٔاتِهِۦ وَیُدۡخِلۡهُ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۚ ذَ ٰ⁠لِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ\n", "jalalayn": "«يَوْم يَجْمَعكُمْ لِيَوْمِ الجَمْع» يَوْم القِيامَة «ذَلِكَ يَوْم التَّغابُن» يَغْبِن المُؤْمِنُونَ الكافِرِينَ بِأَخْذِ مَنازِلهمْ وأَهْلِيهِمْ فِي الجَنَّة لَوْ آمَنُوا «ومَن يُؤْمِن بِاللَّهِ ويَعْمَل صالِحًا يُكَفَّر عَنْهُ سَيِّئاته ويُدْخِلهُ» وفِي قِراءَة بِالنُّونِ فِي الفِعْلَيْنِ", "malayalam": "«സംഗമത്തിന്റെ ദിവസത്തിനായി (ഖിയാമത്ത് നാളിൽ) അവൻ നിങ്ങളെ ഒരുമിച്ചുകൂട്ടുന്ന ദിവസം! അതത്രെ നഷ്ടം വെളിപ്പെടുന്ന ദിവസം (തഗാബുൻ - അവിശ്വാസികൾക്ക് നഷ്ടവും വിശ്വാസികൾക്ക് വിജയവും വെളിപ്പെടുന്ന നാൾ); അല്ലാഹുവിൽ വിശ്വസിക്കുകയും സൽകർമ്മങ്ങൾ പ്രവർത്തിക്കുകയും ചെയ്യുന്നവന്റെ പാപങ്ങൾ അവൻ പൊറുത്തുനൽകുകയും, താഴെ അരുവികൾ ഒഴുകുന്ന സ്വർഗ്ഗത്തോപ്പുകളിൽ അവനെ പ്രവേശിപ്പിക്കുകയും ചെയ്യും; അവരതിൽ ശാശ്വതരായിരിക്കും; അതത്രെ മഹത്തായ വിജയം!».", "malayalamMatn": "ആ സമ്മേളനദിനത്തിന് നിങ്ങളെ അവന്‍ ഒരുമിച്ചുകൂട്ടുന്ന ദിവസം (ശ്രദ്ധേയമാകുന്നു.) അതാണ് നഷ്ടം വെളിപ്പെടുന്ന ദിവസം. ആര്‍ അല്ലാഹുവില്‍ വിശ്വസിക്കുകയും സല്‍കര്‍മ്മം പ്രവര്‍ത്തിക്കുകയും ചെയ്യുന്നുവോ അവന്‍റെ പാപങ്ങള്‍ അല്ലാഹു മായ്ച്ചുകളയുകയും താഴ്ഭാഗത്തു കൂടി അരുവികള്‍ ഒഴുകുന്ന സ്വര്‍ഗത്തോപ്പുകളില്‍ അവനെ പ്രവേശിപ്പിക്കുകയും ചെയ്യുന്നതാണ്‌. അതില്‍ (സ്വര്‍ഗത്തില്‍) അവര്‍ നിത്യവാസികളായിരിക്കും. അതത്രെ മഹത്തായ ഭാഗ്യം."}, {"ayahNumber": 10, "quranText": "وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِ خَـٰلِدِینَ فِیهَاۖ وَبِئۡسَ ٱلۡمَصِیرُ\n", "jalalayn": "«والَّذِينَ كَفَرُوا وكَذَّبُوا بِآياتِنا» القُرْآن «أُولَئِكَ أصْحاب النّار خالِدِينَ فِيها وبِئْسَ المَصِير» هِيَ", "malayalam": "«എന്നാൽ അവിശ്വസിക്കുകയും നമ്മുടെ ദൃഷ്ടാന്തങ്ങളെ തള്ളിക്കളയുകയും ചെയ്തവർ നരകാവകാശികളാകുന്നു; അവരതിൽ ശാശ്വതരായിരിക്കും; അത് എത്രയോ ചീത്തയായ തിരിച്ചുവരവ്!».", "malayalamMatn": "അവിശ്വസിക്കുകയും നമ്മുടെ ദൃഷ്ടാന്തങ്ങള്‍ നിഷേധിച്ചു തള്ളുകയും ചെയ്തവരാകട്ടെ അവരാണ് നരകാവകാശികള്‍. അവരതില്‍ നിത്യവാസികളായിരിക്കും. (അവര്‍) ചെന്നെത്തുന്ന ആ സ്ഥലം വളരെ ചീത്ത തന്നെ."}, {"ayahNumber": 11, "quranText": "مَاۤ أَصَابَ مِن مُّصِیبَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ وَمَن یُؤۡمِنۢ بِٱللَّهِ یَهۡدِ قَلۡبَهُۥۚ وَٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣱ\n", "jalalayn": "«ما أصابَ مِن مُصِيبَة إلّا بِإذْنِ اللَّه» بِقَضائِهِ «ومَن يُؤْمِن بِاللَّهِ» فِي قَوْله إنّ المُصِيبَة بِقَضائِهِ «يَهْدِ قَلْبه» لِلصَّبْرِ عَلَيْها", "malayalam": "«അല്ലാഹുവിന്റെ അനുമതിയില്ലാതെ യാതൊരു വിപത്തും ബാധിക്കുകയില്ല; ആരെങ്കിലും അല്ലാഹുവിൽ വിശ്വസിക്കുന്ന പക്ഷം അവന്റെ ഹൃദയത്തിന് അവൻ നേർവഴി നൽകുന്നതാണ്; അല്ലാഹു സർവ്വകാര്യങ്ങളെക്കുറിച്ചും പൂർണ്ണ അറിവുള്ളവനത്രെ».", "malayalamMatn": "അല്ലാഹുവിന്‍റെ അനുമതി പ്രകാരമല്ലാതെ യാതൊരു വിപത്തും ബാധിച്ചിട്ടില്ല. വല്ലവനും അല്ലാഹുവില്‍ വിശ്വസിക്കുന്ന പക്ഷം അവന്‍റെ ഹൃദയത്തെ അവന്‍ നേര്‍വഴിയിലാക്കുന്നതാണ്‌. അല്ലാഹു ഏതു കാര്യത്തെപ്പറ്റിയും അറിവുള്ളവനാകുന്നു."}, {"ayahNumber": 12, "quranText": "وَأَطِیعُوا۟ ٱللَّهَ وَأَطِیعُوا۟ ٱلرَّسُولَۚ فَإِن تَوَلَّیۡتُمۡ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ\n", "jalalayn": "«وأَطِيعُوا اللَّه وأَطِيعُوا الرَّسُول فَإنْ تَوَلَّيْتُمْ فَإنَّما عَلى رَسُولنا البَلاغ المُبِين» البَيِّن", "malayalam": "«നിങ്ങൾ അല്ലാഹുവെ അനുസരിക്കുവിൻ, റസൂലിനെയും അനുസരിക്കുവിൻ; ഇനി നിങ്ങൾ തിരിഞ്ഞുകളയുകയാണെങ്കിൽ നമ്മുടെ റസൂലിന്റെ ബാധ്യത വ്യക്തമായി എത്തിച്ചുകൊടുക്കുക മാത്രമാകുന്നു».", "malayalamMatn": "അല്ലാഹുവെ നിങ്ങള്‍ അനുസരിക്കുക. റസൂലിനെയും നിങ്ങള്‍ അനുസരിക്കുക. ഇനി നിങ്ങള്‍ പിന്തിരിയുന്ന പക്ഷം നമ്മുടെ റസൂലിന്‍റെ ബാധ്യത വ്യക്തമായ പ്രബോധനം മാത്രമാകുന്നു."}, {"ayahNumber": 13, "quranText": "ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ\n", "jalalayn": "«ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ».", "malayalam": "«അല്ലാഹു, അവനല്ലാതെ യാതൊരു ദൈവവുമില്ല; സത്യവിശ്വാസികൾ അല്ലാഹുവിൽ മാത്രം ഭരമേൽപിക്കട്ടെ!».", "malayalamMatn": "അല്ലാഹു- അവനല്ലാതെ യാതൊരു ദൈവവുമില്ല. അല്ലാഹുവിന്‍റെ മേലായിരിക്കട്ടെ സത്യവിശ്വാസികള്‍ ഭരമേല്‍പിക്കുന്നത്‌."}, {"ayahNumber": 14, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّ مِنۡ أَزۡوَ ٰ⁠جِكُمۡ وَأَوۡلَـٰدِكُمۡ عَدُوࣰّا لَّكُمۡ فَٱحۡذَرُوهُمۡۚ وَإِن تَعۡفُوا۟ وَتَصۡفَحُوا۟ وَتَغۡفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا إنّ مِن أزْواجكُمْ وأَوْلادكُمْ عَدُوًّا لَكُمْ فاحْذَرُوهُمْ» أنْ تُطِيعُوهُمْ فِي التَّخَلُّف عَنْ الخَيْر كالجِهادِ والهِجْرَة فَإنَّ سَبَب نُزُول الآيَة الإطاعَة فِي ذَلِكَ «وإنْ تَعْفُوا» عَنْهُمْ فِي تَثْبِيطهمْ إيّاكُمْ عَنْ ذَلِكَ الخَيْر مُعْتَلِّينَ بِمَشَقَّةِ فِراقكُمْ عَلَيْهِمْ", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, നിങ്ങളുടെ ഭാര്യമാരിലും നിങ്ങളുടെ മക്കളിലും നിങ്ങൾക്ക് ശത്രുക്കളുണ്ട്, അതിനാൽ അവരെ സൂക്ഷിക്കുക (ഹിജ്‌റ പോകാനൊരുങ്ങിയ വിശ്വാസികളെ വേർപാട് സഹിക്കാതെ തടഞ്ഞ ഭാര്യമാരുടെയും മക്കളുടെയും പശ്ചാത്തലത്തിൽ ഇത് അവതരിച്ചു); എന്നാൽ നിങ്ങൾ അവർക്ക് മാപ്പുനൽകുകയും വിട്ടുവീഴ്ച കാണിക്കുകയും പൊറുത്തുകൊടുക്കുകയും ചെയ്യുകയാണെങ്കിൽ തീർച്ചയായും അല്ലാഹു ഏറെ പൊറുക്കുന്നവനും ദയാപരനുമാകുന്നു».", "malayalamMatn": "സത്യവിശ്വാസികളേ, തീര്‍ച്ചയായും നിങ്ങളുടെ ഭാര്യമാരിലും നിങ്ങളുടെ മക്കളിലും നിങ്ങള്‍ക്ക് ശത്രുവുണ്ട്‌. അതിനാല്‍ അവരെ നിങ്ങള്‍ സൂക്ഷിച്ചു കൊള്ളുക. നിങ്ങള്‍ മാപ്പുനല്‍കുകയും, വിട്ടുവീഴ്ച കാണിക്കുകയും പൊറുത്തുകൊടുക്കുകയും ചെയ്യുന്ന പക്ഷം തീര്‍ച്ചയായും അല്ലാഹു ഏറെ പൊറുക്കുന്നവനും കരുണാനിധിയുമാകുന്നു."}, {"ayahNumber": 15, "quranText": "إِنَّمَاۤ أَمۡوَ ٰ⁠لُكُمۡ وَأَوۡلَـٰدُكُمۡ فِتۡنَةࣱۚ وَٱللَّهُ عِندَهُۥۤ أَجۡرٌ عَظِیمࣱ\n", "jalalayn": "«إنّما أمْوالكُمْ وأَوْلادكُمْ فِتْنَة» لَكُمْ شاغِلَة عَنْ أُمُور الآخِرَة «واللَّه عِنْده أجْر عَظِيم» فَلا تَفُوتُوهُ بِاشْتِغالِكُمْ بِالأَمْوالِ والأَوْلاد", "malayalam": "«നിങ്ങളുടെ സമ്പത്തും നിങ്ങളുടെ സന്താനങ്ങളും ഒരു പരീക്ഷണം മാത്രമാകുന്നു; അല്ലാഹുവിങ്കലാകുന്നു മഹത്തായ പ്രതിഫലമുള്ളത്».", "malayalamMatn": "നിങ്ങളുടെ സ്വത്തുക്കളും നിങ്ങളുടെ സന്താനങ്ങളും ഒരു പരീക്ഷണം മാത്രമാകുന്നു. അല്ലാഹുവിങ്കലാകുന്നു മഹത്തായ പ്രതിഫലമുള്ളത്‌."}, {"ayahNumber": 16, "quranText": "فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ وَٱسۡمَعُوا۟ وَأَطِیعُوا۟ وَأَنفِقُوا۟ خَیۡرࣰا لِّأَنفُسِكُمۡۗ وَمَن یُوقَ شُحَّ نَفۡسِهِۦ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ\n", "jalalayn": "«فاتَّقُوا اللَّه ما اسْتَطَعْتُمْ» ناسِخَة لِقَوْلِهِ «اتَّقُوا اللَّه حَقّ تُقاته» «واسْمَعُوا» ما أُمِرْتُمْ بِهِ سَماع قَبُول «وأَطِيعُوا وأَنْفِقُوا» فِي الطّاعَة «خَيْرًا لِأَنْفُسِكُمْ» خَبَر يَكُنْ مُقَدَّرَة جَواب الأَمْر «ومَن يُوقَ شُحّ نَفْسه فَأُولَئِكَ هُمْ المُفْلِحُونَ» الفائِزُونَ", "malayalam": "«ആകയാൽ നിങ്ങൾക്ക് സാധ്യമാകുംവിധം നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുവിൻ; നിങ്ങൾ കേൾക്കുകയും അനുസരിക്കുകയും നിങ്ങൾക്ക് ഉത്തമമാകുംവിധം ദാനം ചെയ്യുകയും ചെയ്യുവിൻ; ആരെങ്കിലും സ്വന്തം മനസ്സിന്റെ പിശുക്കിൽ നിന്ന് കാത്തുരക്ഷിക്കപ്പെടുന്നുവോ അവരത്രെ വിജയം വരിച്ചവർ!».", "malayalamMatn": "അതിനാല്‍ നിങ്ങള്‍ക്ക് സാധ്യമായ വിധം അല്ലാഹുവെ നിങ്ങള്‍ സൂക്ഷിക്കുക. നിങ്ങള്‍ കേള്‍ക്കുകയും അനുസരിക്കുകയും നിങ്ങള്‍ക്കു തന്നെ ഗുണകരമായ നിലയില്‍ ചെലവഴിക്കുകയും ചെയ്യുക. ആര്‍ മനസ്സിന്‍റെ പിശുക്കില്‍ നിന്ന് കാത്തുരക്ഷിക്കപ്പെടുന്നുവോ അവര്‍ തന്നെയാകുന്നു വിജയം പ്രാപിച്ചവര്‍."}, {"ayahNumber": 17, "quranText": "إِن تُقۡرِضُوا۟ ٱللَّهَ قَرۡضًا حَسَنࣰا یُضَـٰعِفۡهُ لَكُمۡ وَیَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ شَكُورٌ حَلِیمٌ\n", "jalalayn": "«إنْ تُقْرِضُوا اللَّه قَرْضًا حَسَنًا» بِأَنْ تَتَصَدَّقُوا عَنْ طِيب قَلْب «يُضاعِفهُ لَكُمْ» وفِي قِراءَة يُضَعِّفهُ بِالتَّشْدِيدِ بِالواحِدَةِ عَشْرًا إلى سَبْعمِائَةٍ وأَكْثَر «ويَغْفِر لَكُمْ» ما يَشاء «واللَّه شَكُور» مُجازٍ عَلى الطّاعَة «حَلِيم» فِي العِقاب عَلى المَعْصِيَة", "malayalam": "«നിങ്ങൾ അല്ലാഹുവിന് ഉത്തമമായ കടം നൽകുകയാണെങ്കിൽ അവൻ നിങ്ങൾക്കത് ഇരട്ടിയാക്കി നൽകും, നിങ്ങൾക്ക് പൊറുത്തുതരികയും ചെയ്യും; അല്ലാഹു നന്ദിയുള്ളവനും ക്ഷമാശീലനുമാകുന്നു».", "malayalamMatn": "നിങ്ങള്‍ അല്ലാഹുവിന് ഉത്തമമായ കടം കൊടുക്കുന്ന പക്ഷം അവനത് നിങ്ങള്‍ക്ക് ഇരട്ടിയാക്കിത്തരികയും നിങ്ങള്‍ക്ക് പൊറുത്തുതരികയും ചെയ്യുന്നതാണ്‌. അല്ലാഹു ഏറ്റവും അധികം നന്ദിയുള്ളവനും സഹനശീലനുമാകുന്നു."}, {"ayahNumber": 18, "quranText": "عَـٰلِمُ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n", "jalalayn": "«عالِم الغَيْب» السِّرّ «والشَّهادَة» العَلانِيَة «العَزِيز» فِي مُلْكه «الحَكِيم» فِي صُنْعه", "malayalam": "«അദൃശ്യവും ദൃശ്യവും അറിയുന്നവനും പ്രതാപിയും പരമയുക്തിമാനുമാകുന്നു അവൻ».", "malayalamMatn": "അദൃശ്യവും ദൃശ്യവും അറിയുന്നവനും പ്രതാപിയും യുക്തിമാനുമാകുന്നു അവന്‍."}], "topPoints": ["അല്ലാഹുവിന്റെ പൂർണ്ണമായ അറിവ് (خلاصة السورة)", "കുടുംബവും സമ്പത്തും ഒരു പരീക്ഷണമാണ്"], "topQuestions": [{"q": "തഗാബുൻ എന്ന പേരിന്റെ അർത്ഥം?", "a": "നഷ്ടം വെളിപ്പെടുന്ന ദിവസം (അന്ത്യനാൾ) എന്നാണ്."}], "asbabAlNuzul": [{"ayahNumber": 14, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّ مِنۡ أَزۡوَ ٰ⁠جِكُمۡ وَأَوۡلَـٰدِكُمۡ عَدُوࣰّا لَّكُمۡ فَٱحۡذَرُوهُمۡۚ", "arabicSnippet": "«يا أيها الذين آمنوا إن من أزواجكم وأولادكم عدوّا لكم فاحذروهم»... فإن سبب نزول الآية أن بعض المسلمين أرادوا الهجرة فمنعهم أزواجهم وأولادهم بكاءً وتخوفا من فراقهم، فقعدوا عن الهجرة.", "malayalamExplanation": "മക്കയിൽ നിന്ന് മദീനയിലേക്ക് ഹിജ്‌റ പോകാൻ ചില സ്വഹാബികൾ ഒരുങ്ങിയപ്പോൾ, അവരുടെ ഭാര്യമാരും കുട്ടികളും കരഞ്ഞുകൊണ്ട് 'ഞങ്ങളെ ആർക്കാണ് നിങ്ങൾ വിട്ടുപോകുന്നത്' എന്ന് പറഞ്ഞ് അവരുടെ കാലുകളിൽ പിടിച്ച് തടഞ്ഞു. കുടുംബസ്നേഹം കാരണം അവർ ഹിജ്‌റ പോകാതെ മക്കയിൽ തന്നെ തങ്ങിപ്പോയി. അല്ലാഹുവിന്റെ കൽപ്പന നിർവ്വഹിക്കുന്നതിൽ നിന്ന് തടസ്സമാകുന്ന കുടുംബബന്ധങ്ങൾ യഥാർത്ഥത്തിൽ ശത്രുതക്ക് തുല്യമാണെന്നും അവരെ സൂക്ഷിക്കണമെന്നും ഉണർത്തിക്കൊണ്ട് ഈ സൂക്തം അവതരിച്ചു."}]}, {"surahNumber": 65, "surahNameArabic": "سُورَةُ الطَّلَاقِ", "surahNameMalayalam": "സൂറത്തുത്ത്വലാഖ് (വിവാഹമോചനം)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ یَـٰۤأَیُّهَا ٱلنَّبِیُّ إِذَا طَلَّقۡتُمُ ٱلنِّسَاۤءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحۡصُوا۟ ٱلۡعِدَّةَۖ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمۡۖ لَا تُخۡرِجُوهُنَّ مِنۢ بُیُوتِهِنَّ وَلَا یَخۡرُجۡنَ إِلَّاۤ أَن یَأۡتِینَ بِفَـٰحِشَةࣲ مُّبَیِّنَةࣲۚ وَتِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن یَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ لَا تَدۡرِی لَعَلَّ ٱللَّهَ یُحۡدِثُ بَعۡدَ ذَ ٰ⁠لِكَ أَمۡرࣰا\n", "jalalayn": "«يا أيّها النَّبِيّ» المُراد أُمَّته بِقَرِينَةِ ما بَعْده أوْ قُلْ لَهُمْ «إذا طَلَّقْتُمْ النِّساء» أيْ أرَدْتُمْ الطَّلاق «فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ» لِأَوَّلِها بِأَنْ يَكُون الطَّلاق فِي طُهْر لَمْ تُمَسَّ فِيهِ لِتَفْسِيرِهِ ﷺ بِذَلِكَ رَواهُ الشَّيْخانِ «وأَحْصُوا العِدَّة» احْفَظُوها لِتُراجِعُوا قَبْل فَراغها «واتَّقُوا اللَّه رَبّكُمْ» أطِيعُوهُ فِي أمْره ونَهْيه «لا تُخْرِجُوهُنَّ مِن بُيُوتهنَّ ولا يَخْرُجْنَ» مِنها حَتّى تَنْقَضِي عِدَّتهنَّ «إلّا أنْ يَأْتِينَ بِفاحِشَةٍ» زِنا «مُبَيَّنَة» بِفَتْحِ الياء وكَسْرها بُيِّنَتْ أوْ بَيِّنَة فَيَخْرُجْنَ لِإقامَةِ الحَدّ عَلَيْهِنَّ «وتِلْكَ» المَذْكُورات «حُدُود اللَّه ومَن يَتَعَدَّ حُدُود اللَّه فَقَدْ ظَلَمَ نَفْسه لا تَدْرِي لَعَلَّ اللَّه يُحْدِث بَعْد ذَلِكَ» الطَّلاق «أمْرًا» مُراجَعَة فِيما إذا كانَ واحِدَة أوْ اثْنَتَيْنِ", "malayalam": "«നബിയേ, നിങ്ങൾ സ്ത്രീകളെ വിവാഹമോചനം ചെയ്യുകയാണെങ്കിൽ അവരുടെ ഇദ്ദ കാലയളവിലേക്ക് നിങ്ങൾ അവരെ ത്വലാഖ് ചൊല്ലുക (അവർ ശുദ്ധിയുള്ളവരായിരിക്കെ ബന്ധപ്പെടാത്ത അവസ്ഥയിൽ); ഇദ്ദ കാലയളവ് നിങ്ങൾ കൃത്യമായി എണ്ണിക്കണക്കാക്കുക; നിങ്ങളുടെ രക്ഷിതാവായ അല്ലാഹുവിനെ നിങ്ങൾ സൂക്ഷിക്കുകയും ചെയ്യുക; വ്യക്തമായ വല്ല നീചവൃത്തിയും അവർ ചെയ്യുന്ന പക്ഷമല്ലാതെ അവരുടെ വീടുകളിൽ നിന്ന് അവരെ നിങ്ങൾ പുറത്താക്കരുത്, അവർ സ്വയം ഇറങ്ങിപ്പോകാനും പാടില്ല; അവ അല്ലാഹുവിന്റെ അതിർവരമ്പുകളാകുന്നു; ആരെങ്കിലും അല്ലാഹുവിന്റെ അതിർവരമ്പുകളെ ലംഘിക്കുന്ന പക്ഷം അവൻ തനിക്ക് തന്നെയാണ് അക്രമം ചെയ്യുന്നത്; അതിന് ശേഷം അല്ലാഹു പുതിയൊരു കാര്യം ഉണ്ടാക്കിയേക്കുമോ എന്ന് നിനക്കറിയില്ലല്ലോ (മനസ്സുമാറി ഇണങ്ങിചേരാൻ അവൻ വഴിയൊരുക്കിയേക്കാം)».", "malayalamMatn": "നബിയേ, നിങ്ങള്‍ (വിശ്വാസികള്‍) സ്ത്രീകളെ വിവാഹമോചനം ചെയ്യുകയാണെങ്കില്‍ അവരെ നിങ്ങള്‍ അവരുടെ ഇദ്ദഃ കാലത്തിന് (കണക്കാക്കി) വിവാഹമോചനം ചെയ്യുകയും ഇദ്ദഃ കാലം നിങ്ങള്‍ എണ്ണികണക്കാക്കുകയും ചെയ്യുക. നിങ്ങളുടെ രക്ഷിതാവായ അല്ലാഹുവെ നിങ്ങള്‍ സൂക്ഷിക്കുകയും ചെയ്യുക. അവരുടെ വീടുകളില്‍ നിന്ന് അവരെ നിങ്ങള്‍ പുറത്താക്കരുത്‌. അവര്‍ പുറത്തു പോകുകയും ചെയ്യരുത്‌. പ്രത്യക്ഷമായ വല്ല നീചവൃത്തിയും അവര്‍ ചെയ്യുകയാണെങ്കിലല്ലാതെ. അവ അല്ലാഹുവിന്‍റെ നിയമപരിധികളാകാകുന്നു. അല്ലാഹുവിന്‍റെ നിയമപരിധികളെ വല്ലവനും അതിലംഘിക്കുന്ന പക്ഷം, അവന്‍ അവനോട് തന്നെ അന്യായം ചെയ്തിരിക്കുന്നു. അതിന് ശേഷം അല്ലാഹു പുതുതായി വല്ലകാര്യവും കൊണ്ടു വന്നേക്കുമോ എന്ന് നിനക്ക് അറിയില്ല."}, {"ayahNumber": 2, "quranText": "فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفࣲ وَأَشۡهِدُوا۟ ذَوَیۡ عَدۡلࣲ مِّنكُمۡ وَأَقِیمُوا۟ ٱلشَّهَـٰدَةَ لِلَّهِۚ ذَ ٰ⁠لِكُمۡ یُوعَظُ بِهِۦ مَن كَانَ یُؤۡمِنُ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۚ وَمَن یَتَّقِ ٱللَّهَ یَجۡعَل لَّهُۥ مَخۡرَجࣰا\n", "jalalayn": "«فَإذا بَلَغْنَ أجَلهنَّ» قارَبْنَ انْقِضاء عِدَّتهنَّ «فَأَمْسِكُوهُنَّ» بِأَنْ تُراجِعُوهُنَّ «بِمَعْرُوفٍ» مِن غَيْر ضِرار «أوْ فارِقُوهُنَّ بِمَعْرُوفٍ» اُتْرُكُوهُنَّ حَتّى تَنْقَضِي عِدَّتهنَّ ولا تُضارُّوهُنَّ بِالمُراجَعَةِ «وأَشْهِدُوا ذَوَيْ عَدْل مِنكُمْ» عَلى المُراجَعَة أوْ الفِراق «وأَقِيمُوا الشَّهادَة لِلَّهِ» لا لِلْمَشْهُودِ عَلَيْهِ أوْ لَهُ «ذَلِكُمْ يُوعَظ بِهِ مَن كانَ يُؤْمِن بِاللَّهِ واليَوْم الآخِر ومَن يَتَّقِ اللَّه يَجْعَل لَهُ مَخْرَجًا» مِن كَرْب الدُّنْيا والآخِرَة", "malayalam": "«അങ്ങനെ അവർ തങ്ങളുടെ ഇദ്ദ അവധിയിലെത്തിയാൽ ഉചിതമായ രീതിയിൽ അവരെ നിങ്ങൾ തിരിച്ചെടുക്കുക, അല്ലെങ്കിൽ ഉചിതമായ രീതിയിൽ അവരെ വേർപെടുത്തുക; നിങ്ങളിൽ നിന്നുള്ള നീതിമാന്മാരായ രണ്ടുപേരെ നിങ്ങൾ സാക്ഷികളാക്കുകയും ചെയ്യുക; അല്ലാഹുവിന് വേണ്ടി സാക്ഷ്യം നേരാംവണ്ണം നിലനിർത്തുക; അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്നവർക്ക് നൽകപ്പെടുന്ന ഉപദേശമത്രെ അത്; ആരെങ്കിലും അല്ലാഹുവിനെ സൂക്ഷിക്കുന്ന പക്ഷം അവൻ അവനൊരു പോംവഴി ഉണ്ടാക്കിക്കൊടുക്കുന്നതാണ്».", "malayalamMatn": "അങ്ങനെ അവര്‍ (വിവാഹമുക്തകള്‍) അവരുടെ അവധിയില്‍ എത്തുമ്പോള്‍ നിങ്ങള്‍ ന്യായമായ നിലയില്‍ അവരെ പിടിച്ച് നിര്‍ത്തുകയോ, ന്യായമായ നിലയില്‍ അവരുമായി വേര്‍പിരിയുകയോ ചെയ്യുക. നിങ്ങളില്‍ നിന്നുള്ള രണ്ടു നീതിമാന്‍മാരെ നിങ്ങള്‍ സാക്ഷി നിര്‍ത്തുകയും അല്ലാഹുവിന് വേണ്ടി സാക്ഷ്യം നേരാംവണ്ണം നിലനിര്‍ത്തുകയും ചെയ്യുക. അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിച്ചു കൊണ്ടിരിക്കുന്നവര്‍ക്ക് ഉപദേശം നല്‍കപ്പെടുന്നതത്രെ അത്‌. അല്ലാഹുവെ വല്ലവനും സൂക്ഷിക്കുന്ന പക്ഷം അല്ലാഹു അവന്നൊരു പോംവഴി ഉണ്ടാക്കികൊടുക്കുകയും,"}, {"ayahNumber": 3, "quranText": "وَیَرۡزُقۡهُ مِنۡ حَیۡثُ لَا یَحۡتَسِبُۚ وَمَن یَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥۤۚ إِنَّ ٱللَّهَ بَـٰلِغُ أَمۡرِهِۦۚ قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَیۡءࣲ قَدۡرࣰا\n", "jalalayn": "«ويَرْزُقهُ مِن حَيْثُ لا يَحْتَسِب» يَخْطِر بِبالِهِ «ومَن يَتَوَكَّل عَلى اللَّه» فِي أُمُوره «فَهُوَ حَسْبه» كافِيه «إنّ اللَّه بالِغ أمْره» مُراده «قَدْ جَعَلَ اللَّه لِكُلِّ شَيْء» كَرِخاءٍ وشِدَّة «قَدَرًا» مِيقاتًا", "malayalam": "«അവൻ കണക്കുകൂട്ടാത്ത വിധത്തിൽ അവൻ അവന് ഉപജീവനം നൽകുകയും ചെയ്യും; ആരെങ്കിലും അല്ലാഹുവിൽ ഭരമേൽപിക്കുന്ന പക്ഷം അവന് അല്ലാഹു തന്നെ മതിയാകുന്നതാണ്; തീർച്ചയായും അല്ലാഹു തന്റെ കാര്യം നിറവേറ്റുക തന്നെ ചെയ്യും; ഏതൊരു കാര്യത്തിനും അല്ലാഹു ഒരു നിശ്ചിത കണക്ക് ഏർപ്പെടുത്തിയിരിക്കുന്നു».", "malayalamMatn": "അവന്‍ കണക്കാക്കാത്ത വിധത്തില്‍ അവന്ന് ഉപജീവനം നല്‍കുകയും ചെയ്യുന്നതാണ്‌. വല്ലവനും അല്ലാഹുവില്‍ ഭരമേല്‍പിക്കുന്ന പക്ഷം അവന്ന് അല്ലാഹു തന്നെ മതിയാകുന്നതാണ്‌. തീര്‍ച്ചയായും അല്ലാഹു തന്‍റെ കാര്യം പ്രാപിക്കുന്നവനാകുന്നു. ഓരോ കാര്യത്തിനും അല്ലാഹു ഒരു ക്രമം ഏര്‍പെടുത്തിയിട്ടുണ്ട്‌."}, {"ayahNumber": 4, "quranText": "وَٱلَّـٰۤـِٔی یَىِٕسۡنَ مِنَ ٱلۡمَحِیضِ مِن نِّسَاۤىِٕكُمۡ إِنِ ٱرۡتَبۡتُمۡ فَعِدَّتُهُنَّ ثَلَـٰثَةُ أَشۡهُرࣲ وَٱلَّـٰۤـِٔی لَمۡ یَحِضۡنَۚ وَأُو۟لَـٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن یَضَعۡنَ حَمۡلَهُنَّۚ وَمَن یَتَّقِ ٱللَّهَ یَجۡعَل لَّهُۥ مِنۡ أَمۡرِهِۦ یُسۡرࣰا\n", "jalalayn": "«واللّائِي» بِهَمْزَةٍ وياء وبِلا ياء فِي المَوْضِعَيْنِ «يَئِسْنَ مِن المَحِيض» بِمَعْنى الحَيْض «مِن نِسائِكُمْ إنْ ارْتَبْتُمْ» شَكَكْتُمْ فِي عِدَّتهنَّ «فَعِدَّتهنَّ ثَلاثَة أشْهُر واللّائِي لَمْ يَحِضْنَ» لِصِغَرِهِنَّ فَعِدَّتهنَّ ثَلاثَة أشْهُر والمَسْأَلَتانِ فِي غَيْر المُتَوَفّى عَنْهُنَّ أزْواجهنَّ أمّا هُنَّ فَعِدَّتهنَّ ما فِي آيَة «يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ أرْبَعَة أشْهُر وعَشْرًا» «وأُولات الأَحْمال أجَلهنَّ» انْقِضاء عِدَّتهنَّ مُطَلَّقات أوْ مُتَوَفّى عَنْهُنَّ أزْواجهنَّ «أنْ يَضَعْنَ حَمْلهنَّ ومَن يَتَّقِ اللَّه يَجْعَل لَهُ مِن أمْره يُسْرًا» فِي الدُّنْيا والآخِرَة", "malayalam": "«നിങ്ങളുടെ സ്ത്രീകളിൽ നിന്ന് ആർത്തവം നിലച്ചുപോയവർ (പ്രായമായവർ), അവരുടെ ഇദ്ദയുടെ കാര്യത്തിൽ നിങ്ങൾക്ക് സംശയമുണ്ടെങ്കിൽ അവരുടെ ഇദ്ദ മൂന്ന് മാസമാകുന്നു; ഇതുവരെ ആർത്തവമുണ്ടായിട്ടില്ലാത്ത പെൺകുട്ടികളുടെയും ഇദ്ദ അപ്രകാരം തന്നെ; ഗർഭിണികളായ സ്ത്രീകളുടെ അവധി അവർ പ്രസവിക്കുന്നതോടു കൂടിയാകുന്നു; ആരെങ്കിലും അല്ലാഹുവിനെ സൂക്ഷിക്കുന്ന പക്ഷം അവൻ അവന്റെ കാര്യത്തിൽ എളുപ്പമുണ്ടാക്കിക്കൊടുക്കുന്നതാണ്».", "malayalamMatn": "നിങ്ങളുടെ സ്ത്രീകളില്‍ നിന്നും ആര്‍ത്തവത്തെ സംബന്ധിച്ച് നിരാശപ്പെട്ടിട്ടുള്ളവരെ സംബന്ധിച്ചിടത്തോളം നിങ്ങള്‍ അവരുടെ ഇദ്ദഃ യുടെ കാര്യത്തില്‍ സംശയത്തിലാണെങ്കില്‍ അത് മൂന്ന് മാസമാകുന്നു. ആര്‍ത്തവമുണ്ടായിട്ടില്ലാത്തവരുടേതും അങ്ങനെ തന്നെ. ഗര്‍ഭവതികളായ സ്ത്രീകളാകട്ടെ അവരുടെ അവധി അവര്‍ തങ്ങളുടെ ഗര്‍ഭം പ്രസവിക്കലാകുന്നു. വല്ലവനും അല്ലാഹുവെ സൂക്ഷിക്കുന്ന പക്ഷം അവന്ന് അവന്‍റെ കാര്യത്തില്‍ അല്ലാഹു എളുപ്പമുണ്ടാക്കി കൊടുക്കുന്നതാണ്‌."}, {"ayahNumber": 5, "quranText": "ذَ ٰ⁠لِكَ أَمۡرُ ٱللَّهِ أَنزَلَهُۥۤ إِلَیۡكُمۡۚ وَمَن یَتَّقِ ٱللَّهَ یُكَفِّرۡ عَنۡهُ سَیِّـَٔاتِهِۦ وَیُعۡظِمۡ لَهُۥۤ أَجۡرًا\n", "jalalayn": "«ذَلِكَ» المَذْكُور فِي العِدَّة «أمْر اللَّه» حُكْمه", "malayalam": "«അത് അല്ലാഹു നിങ്ങൾക്ക് അവതരിപ്പിച്ചുതന്ന കൽപനയാകുന്നു; ആരെങ്കിലും അല്ലാഹുവിനെ സൂക്ഷിക്കുന്ന പക്ഷം അവൻ അവന്റെ തിന്മകളെ മായ്ച്ചുകളയുകയും അവന് മഹത്തായ പ്രതിഫലം നൽകുകയും ചെയ്യും».", "malayalamMatn": "അത് അല്ലാഹുവിന്‍റെ കല്‍പനയാകുന്നു. അവനത് നിങ്ങള്‍ക്ക് അവതരിപ്പിച്ചു തന്നിരിക്കുന്നു. വല്ലവനും അല്ലാഹുവെ സൂക്ഷിക്കുന്ന പക്ഷം അവന്‍റെ തിന്‍മകളെ അവന്‍ മായ്ച്ചുകളയുകയും അവന്നുള്ള പ്രതിഫലം അവന്‍ വലുതാക്കി കൊടുക്കുകയും ചെയ്യുന്നതാണ്‌."}, {"ayahNumber": 6, "quranText": "أَسۡكِنُوهُنَّ مِنۡ حَیۡثُ سَكَنتُم مِّن وُجۡدِكُمۡ وَلَا تُضَاۤرُّوهُنَّ لِتُضَیِّقُوا۟ عَلَیۡهِنَّۚ وَإِن كُنَّ أُو۟لَـٰتِ حَمۡلࣲ فَأَنفِقُوا۟ عَلَیۡهِنَّ حَتَّىٰ یَضَعۡنَ حَمۡلَهُنَّۚ فَإِنۡ أَرۡضَعۡنَ لَكُمۡ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأۡتَمِرُوا۟ بَیۡنَكُم بِمَعۡرُوفࣲۖ وَإِن تَعَاسَرۡتُمۡ فَسَتُرۡضِعُ لَهُۥۤ أُخۡرَىٰ\n", "jalalayn": "«أسْكِنُوهُنَّ» أيْ المُطَلَّقات «مِن حَيْثُ سَكَنْتُمْ» أيْ بَعْض مَساكِنكُمْ «مِن وُجْدكُمْ» أيْ سِعَتكُمْ عَطْف بَيان أوْ بَدَل مِمّا قَبْله بِإعادَةِ الجار وتَقْدِير مُضاف أيْ أمْكِنَة سَعَتكُمْ لا ما دُونها «ولا تُضارُّوهُنَّ لِتُضَيِّقُوا عَلَيْهِنَّ» المَساكِن فَيَحْتَجْنَ إلى الخُرُوج أوْ النَّفَقَة فَيَفْتَدِينَ مِنكُمْ «وإنْ كُنَّ أُولات حَمْل فَأَنْفِقُوا عَلَيْهِنَّ حَتّى يَضَعْنَ حَمْلهنَّ فَإنْ أرْضَعْنَ لَكُمْ» أوْلادكُمْ مِنهُنَّ «فَآتُوهُنَّ أُجُورهنَّ» عَلى الإرْضاع «وأَتْمِرُوا بَيْنكُمْ» وبَيْنهنَّ «بِمَعْرُوفٍ» بِجَمِيلٍ فِي حَقّ الأَوْلاد بِالتَّوافُقِ عَلى أجْر مَعْلُوم عَلى الإرْضاع «وإنْ تَعاسَرْتُمْ» تَضايَقْتُمْ فِي الإرْضاع فامْتَنَعَ الأَب مِن الأُجْرَة والأُمّ مِن فِعْله «فَسَتُرْضِعُ لَهُ» لِلْأَبِ «أُخْرى» ولا تُكْرَه الأُمّ عَلى إرْضاعه", "malayalam": "«നിങ്ങളുടെ കഴിവനുസരിച്ച് നിങ്ങൾ താമസിക്കുന്നിടത്ത് അവരെയും താമസിപ്പിക്കുക; അവരെ ഞെരുക്കാനായി നിങ്ങൾ അവരെ ഉപദ്രവിക്കരുത്; അവർ ഗർഭിണികളാണെങ്കിൽ അവർ പ്രസവിക്കുന്നത് വരെ അവർക്ക് നിങ്ങൾ ചെലവിന് കൊടുക്കുക; ഇനി അവർ നിങ്ങൾക്ക് വേണ്ടി മുലകൊടുക്കുകയാണെങ്കിൽ അവർക്കുള്ള പ്രതിഫലം അവർക്ക് നൽകുക; പരസ്പരം ഉചിതമായ രീതിയിൽ നിങ്ങൾ കൂടിയാലോചിക്കുക; ഇനി നിങ്ങൾക്കിടയിൽ പ്രയാസമുണ്ടാകുകയാണെങ്കിൽ മറ്റൊര സ്ത്രീ അവന് വേണ്ടി മുലകൊടുത്തുകൊള്ളട്ടെ».", "malayalamMatn": "നിങ്ങളുടെ കഴിവില്‍ പെട്ട, നിങ്ങള്‍ താമസിക്കുന്ന സ്ഥലത്ത് നിങ്ങള്‍ അവരെ താമസിപ്പിക്കണം. അവര്‍ക്കു ഞെരുക്കമുണ്ടാക്കാന്‍ വേണ്ടി നിങ്ങള്‍ അവരെ ദ്രോഹിക്കരുത്‌. അവര്‍ ഗര്‍ഭിണികളാണെങ്കില്‍ അവര്‍ പ്രസവിക്കുന്നത് വരെ നിങ്ങള്‍ അവര്‍ക്കു ചെലവുകൊടുക്കുകയും ചെയ്യുക. ഇനി അവര്‍ നിങ്ങള്‍ക്കു വേണ്ടി (കുഞ്ഞിന്‌) മുലകൊടുക്കുന്ന പക്ഷം അവര്‍ക്കു നിങ്ങള്‍ അവരുടെ പ്രതിഫലം കൊടുക്കുക. നിങ്ങള്‍ തമ്മില്‍ മര്യാദപ്രകാരം കൂടിയാലോചിക്കുകയും ചെയ്യുക. ഇനി നിങ്ങള്‍ ഇരു വിഭാഗത്തിനും ഞെരുക്കമാവുകയാണെങ്കില്‍ അയാള്‍ക്കു വേണ്ടി മറ്റൊരു സ്ത്രീ മുലകൊടുത്തു കൊള്ളട്ടെ."}, {"ayahNumber": 7, "quranText": "لِیُنفِقۡ ذُو سَعَةࣲ مِّن سَعَتِهِۦۖ وَمَن قُدِرَ عَلَیۡهِ رِزۡقُهُۥ فَلۡیُنفِقۡ مِمَّاۤ ءَاتَىٰهُ ٱللَّهُۚ لَا یُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا مَاۤ ءَاتَىٰهَاۚ سَیَجۡعَلُ ٱللَّهُ بَعۡدَ عُسۡرࣲ یُسۡرࣰا\n", "jalalayn": "«لِيُنْفِق» عَلى المُطَلَّقات والمُرْضِعات «ذُو سَعَة مِن سَعَته ومَن قُدِرَ» ضُيِّقَ «عَلَيْهِ رِزْقه فَلْيُنْفِقْ مِمّا آتاهُ» أعْطاهُ «اللَّه» عَلى قَدْره «لا يُكَلِّف اللَّه نَفْسًا إلّا ما آتاها سَيَجْعَلُ اللَّه بَعْد عُسْر يُسْرًا» وقَدْ جَعَلَهُ بِالفُتُوحِ", "malayalam": "«കഴിവുള്ളവൻ തന്റെ കഴിവിൽ നിന്ന് ചെലവഴിക്കട്ടെ; ആർക്കെങ്കിലും ഉപജീവനം ഇടുങ്ങിയതാക്കപ്പെട്ടാൽ അല്ലാഹു അവന് നൽകിയതിൽ നിന്ന് അവൻ ചെലവഴിക്കട്ടെ; അല്ലാഹു ഒരാളോടും അവൻ അയാൾക്ക് നൽകിയതിലപ്പുറം നിർബന്ധിക്കുകയില്ല; അല്ലാഹു ഞെരുക്കത്തിന് ശേഷം ഉടൻ എളുപ്പമുണ്ടാക്കിക്കൊടുക്കുന്നതാണ്».", "malayalamMatn": "കഴിവുള്ളവന്‍ തന്‍റെ കഴിവില്‍ നിന്ന് ചെലവിനു കൊടുക്കട്ടെ. വല്ലവന്നും തന്‍റെ ഉപജീവനം ഇടുങ്ങിയതായാല്‍ അല്ലാഹു അവന്നു കൊടുത്തതില്‍ നിന്ന് അവന്‍ ചെലവിന് കൊടുക്കട്ടെ. ഒരാളോടും അല്ലാഹു അയാള്‍ക്ക് കൊടുത്തതല്ലാതെ (നല്‍കാന്‍) നിര്‍ബന്ധിക്കുകയില്ല. അല്ലാഹു ഞെരുക്കത്തിനു ശേഷം സൌകര്യം ഏര്‍പെടുത്തികൊടുക്കുന്നതാണ്‌."}, {"ayahNumber": 8, "quranText": "وَكَأَیِّن مِّن قَرۡیَةٍ عَتَتۡ عَنۡ أَمۡرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبۡنَـٰهَا حِسَابࣰا شَدِیدࣰا وَعَذَّبۡنَـٰهَا عَذَابࣰا نُّكۡرࣰا\n", "jalalayn": "«وكَأَيِّنْ» هِيَ كاف الجَرّ دَخَلَتْ عَلى أيْ بِمَعْنى كَمْ «مِن قَرْيَة» أيْ وكَثِير مِن القُرى «عَتَتْ» عَصَتْ يَعْنِي أهْلها «عَنْ أمْر رَبّها ورُسُله فَحاسَبْناها» فِي الآخِرَة وإنْ لَمْ تَجِئْ لِتَحَقُّقِ وُقُوعها «حِسابًا شَدِيدًا وعَذَّبْناها عَذابًا نُكْرًا» بِسُكُونِ الكاف وضَمّها فَظِيعًا وهُوَ عَذاب النّار", "malayalam": "«തങ്ങളുടെ രക്ഷിതാവിന്റെയും അവന്റെ റസൂലുകളുടെയും കൽപനയോട് ധിക്കാരം കാണിച്ച എത്രയെത്ര നാടുകൾ! അപ്പോൾ നാം അവരോട് കഠിനമായ വിചാരണ നടത്തുകയും ഭയാനകമായ ശിക്ഷ നാം അവർക്ക് നൽകുകയും ചെയ്തു».", "malayalamMatn": "എത്രയെത്ര രാജ്യക്കാര്‍ അവരുടെ രക്ഷിതാവിന്‍റെയും അവന്‍റെ ദൂതന്‍മാരുടെയും കല്‍പന വിട്ട് ധിക്കാരം പ്രവര്‍ത്തിച്ചിട്ടുണ്ട്‌. അതിനാല്‍ നാം അവരോട് കര്‍ക്കശമായ നിലയില്‍ കണക്കു ചോദിക്കുകയും അവരെ നാം ഹീനമായ വിധത്തില്‍ ശിക്ഷിക്കുകയും ചെയ്തു."}, {"ayahNumber": 9, "quranText": "فَذَاقَتۡ وَبَالَ أَمۡرِهَا وَكَانَ عَـٰقِبَةُ أَمۡرِهَا خُسۡرًا\n", "jalalayn": "«فَذاقَتْ وبال أمْرها» عُقُوبَته «وكانَ عاقِبَة أمْرها خُسْرًا» خَسارًا وهَلاكًا", "malayalam": "«അങ്ങനെ അവർ തങ്ങളുടെ ചെയ്തികളുടെ ദുഷ്ഫലം ആസ്വദിച്ചു; അവരുടെ കാര്യത്തിന്റെ പര്യവസാനം വൻ നഷ്ടമായിരുന്നു».", "malayalamMatn": "അങ്ങനെ അവര്‍ അവരുടെ നിലപാടിന്‍റെ ദുഷ്ഫലം ആസ്വദിച്ചു. അവരുടെ നിലപാടിന്‍റെ പര്യവസാനം നഷ്ടം തന്നെയായിരുന്നു."}, {"ayahNumber": 10, "quranText": "أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابࣰا شَدِیدࣰاۖ فَٱتَّقُوا۟ ٱللَّهَ یَـٰۤأُو۟لِی ٱلۡأَلۡبَـٰبِ ٱلَّذِینَ ءَامَنُوا۟ۚ قَدۡ أَنزَلَ ٱللَّهُ إِلَیۡكُمۡ ذِكۡرࣰا\n", "jalalayn": "«أعَدَّ اللَّه لَهُمْ عَذابًا شَدِيدًا» تَكْرِير الوَعِيد تَوْكِيد «فاتَّقُوا اللَّه يا أُولِي الأَلْباب» أصْحاب العُقُول «الَّذِينَ آمَنُوا» نَعْت لِلْمُنادى أوْ بَيان لَهُ «قَدْ أنَزَلَ اللَّه إلَيْكُمْ ذِكْرًا» هُوَ القُرْآن", "malayalam": "«അല്ലാഹു അവർക്കായി കഠിനമായ ശിക്ഷ ഒരുക്കിവെച്ചിരിക്കുന്നു; അതിനാൽ വിശ്വസിച്ച ബുദ്ധിമാന്മാരേ, നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുവിൻ! അല്ലാഹു നിങ്ങൾക്കായി ഉൽബോധനം ഇറക്കിത്തന്നിരിക്കുന്നു».", "malayalamMatn": "അല്ലാഹു അവര്‍ക്കു കഠിനമായ ശിക്ഷ ഒരുക്കിവെച്ചിരിക്കുന്നു. അതിനാല്‍ സത്യവിശ്വാസികളായ ബുദ്ധിമാന്‍മാരേ, നിങ്ങള്‍ അല്ലാഹുവെ സൂക്ഷിക്കുക. തീര്‍ച്ചയായും അല്ലാഹു നിങ്ങള്‍ക്ക് ഒരു ഉല്‍ബോധകനെ"}, {"ayahNumber": 11, "quranText": "رَّسُولࣰا یَتۡلُوا۟ عَلَیۡكُمۡ ءَایَـٰتِ ٱللَّهِ مُبَیِّنَـٰتࣲ لِّیُخۡرِجَ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِۚ وَمَن یُؤۡمِنۢ بِٱللَّهِ وَیَعۡمَلۡ صَـٰلِحࣰا یُدۡخِلۡهُ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ قَدۡ أَحۡسَنَ ٱللَّهُ لَهُۥ رِزۡقًا\n", "jalalayn": "«رَسُولًا» أيْ مُحَمَّدًا ﷺ مَنصُوب بِفِعْلٍ مُقَدَّر أيْ وأَرْسَلَ «يَتْلُو عَلَيْكُمْ آيات اللَّه مُبَيَّنات» بِفَتْحِ الياء وكَسْرها كَما تَقَدَّمَ «لِيُخْرِج الَّذِينَ آمَنُوا وعَمِلُوا الصّالِحات» بَعْد مَجِيء الذِّكْر والرَّسُول «مِن الظُّلُمات» الكُفْر الَّذِي كانُوا عَلَيْهِ «إلى النُّور» الإيمان الَّذِي قامَ بِهِمْ بَعْد الكُفْر «ومَن يُؤْمِن بِاللَّهِ ويَعْمَل صالِحًا يُدْخِلهُ» وفِي قِراءَة بِالنُّونِ «جَنّات تَجْرِي مِن تَحْتها الأَنْهار خالِدِينَ فِيها أبَدًا قَدْ أحْسَنَ اللَّه لَهُ رِزْقًا» هُوَ رِزْق الجَنَّة الَّتِي لا يَنْقَطِع نَعِيمها", "malayalam": "«സത്യവിശ്വാസം സ്വീകരിക്കുകയും സൽകർമ്മങ്ങൾ പ്രവർത്തിക്കുകയും ചെയ്തവരെ അന്ധകാരങ്ങളിൽ നിന്ന് വെളിച്ചത്തിലേക്ക് ആനയിക്കുവാനായി, അല്ലാഹുവിന്റെ സുവ്യക്തമായ സൂക്തങ്ങൾ നിങ്ങൾക്ക് ഓതിക്കേൾപിക്കുന്ന ഒരു റസൂലിനെയും അവൻ നിയോഗിച്ചിരിക്കുന്നു; ആരെങ്കിലും അല്ലാഹുവിൽ വിശ്വസിക്കുകയും സൽകർമ്മങ്ങൾ പ്രവർത്തിക്കുകയും ചെയ്യുന്ന പക്ഷം താഴെ അരുവികൾ ഒഴുകുന്ന സ്വർഗ്ഗത്തോപ്പുകളിൽ അവൻ അവനെ പ്രവേശിപ്പിക്കും; അവരതിൽ എന്നെന്നേക്കുമായി ശാശ്വതരായിരിക്കും; അല്ലാഹു അവന് എത്രയോ ഉത്തമമായ ഉപജീവനമാണ് നൽകിയിരിക്കുന്നത്!».", "malayalamMatn": "അഥവാ അല്ലാഹുവിന്‍റെ വ്യക്തമായ ദൃഷ്ടാന്തങ്ങള്‍ നിങ്ങള്‍ക്ക് ഓതികേള്‍പിച്ചു തരുന്ന ഒരു ദൂതനെ നിങ്ങളുടെ അടുത്തേക്കിറക്കിത്തന്നിരിക്കുന്നു; വിശ്വസിക്കുകയും സല്‍കര്‍മ്മങ്ങള്‍ പ്രവര്‍ത്തിക്കുകയും ചെയ്തവരെ അന്ധകാരങ്ങളില്‍ നിന്ന് പ്രകാശത്തിലേക്ക് ആനയിക്കുവാന്‍ വേണ്ടി. വല്ലവനും അല്ലാഹുവില്‍ വിശ്വസിക്കുകയും സല്‍കര്‍മ്മം പ്രവര്‍ത്തിക്കുകയും ചെയ്യുന്ന പക്ഷം താഴ്ഭാഗത്തു കൂടി അരുവികള്‍ ഒഴുകുന്ന സ്വര്‍ഗത്തോപ്പുകളില്‍ അവനെ പ്രവേശിപ്പിക്കുന്നതാണ്‌. അവര്‍ അതില്‍ നിത്യവാസികളായിരിക്കും. അങ്ങനെയുള്ളവന്ന് അല്ലാഹു ഉപജീവനം മെച്ചപ്പെടുത്തിയിരിക്കുന്നു."}, {"ayahNumber": 12, "quranText": "ٱللَّهُ ٱلَّذِی خَلَقَ سَبۡعَ سَمَـٰوَ ٰ⁠تࣲ وَمِنَ ٱلۡأَرۡضِ مِثۡلَهُنَّۖ یَتَنَزَّلُ ٱلۡأَمۡرُ بَیۡنَهُنَّ لِتَعۡلَمُوۤا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ وَأَنَّ ٱللَّهَ قَدۡ أَحَاطَ بِكُلِّ شَیۡءٍ عِلۡمَۢا\n", "jalalayn": "«اللَّه الَّذِي خَلَقَ سَبْع سَماوات ومِن الأَرْض مِثْلهنَّ» يَعْنِي سَبْع أرَضِينَ «يَتَنَزَّل الأَمْر» الوَحْي «بَيْنهنَّ» بَيْن السَّماوات والأَرْض يَنْزِل بِهِ جِبْرِيل مِن السَّماء السّابِعَة إلى الأَرْض السّابِعَة «لِتَعْلَمُوا» مُتَعَلِّق بِمَحْذُوفٍ أيْ أعْلَمَكُمْ بِذَلِكَ الخَلْق والتَّنْزِيل", "malayalam": "«ഏഴ് ആകാശങ്ങളെയും ഭൂമിയിൽ നിന്ന് അവയ്ക്ക് സമാനമായതിനെയും സൃഷ്ടിച്ചവൻ അല്ലാഹുവാകുന്നു; അവയ്ക്കിടയിലൂടെ അവന്റെ കൽപന ഇറങ്ങിക്കൊണ്ടിരിക്കുന്നു; അല്ലാഹു സർവ്വകാര്യങ്ങൾക്കും കഴിവുള്ളവനാണെന്നും, അല്ലാഹു സർവ്വകാര്യങ്ങളെക്കുറിച്ചും അറിവ് കൊണ്ട് വലയം ചെയ്തിരിക്കുന്നുവെന്നും നിങ്ങൾ മനസ്സിലാക്കുവാൻ വേണ്ടിയത്രെ അത്».", "malayalamMatn": "അല്ലാഹുവാകുന്നു ഏഴ് ആകാശങ്ങളും ഭൂമിയില്‍ നിന്ന് അവയ്ക്ക് തുല്യമായതും സൃഷ്ടിച്ചവന്‍. അവയ്ക്കിടയില്‍ (അവന്‍റെ) കല്‍പന ഇറങ്ങുന്നു. അല്ലാഹു ഏത് കാര്യത്തിനും കഴിവുള്ളവനാകുന്നു എന്നും ഏതു വസ്തുവെയും ചൂഴ്ന്ന് അറിയുന്നവനായിരിക്കുന്നു എന്നും നിങ്ങള്‍ മനസ്സിലാക്കുവാന്‍ വേണ്ടി."}], "topPoints": ["വിവാഹമോചനത്തിന്റെ ഇസ്ലാമിക നിയമങ്ങൾ (خلاصة السورة)", "അല്ലാഹുവിനെ സൂക്ഷിക്കുന്നവർക്ക് അവൻ വഴിയൊരുക്കും"], "topQuestions": [{"q": "വിവാഹമോചന സമയത്ത് ശ്രദ്ധിക്കേണ്ട പ്രധാന കാര്യം?", "a": "ഇദ്ദ കാലയളവ് കൃത്യമായി പാലിക്കുകയും അല്ലാഹുവിനെ സൂക്ഷിക്കുകയും ചെയ്യുക."}], "asbabAlNuzul": []}, {"surahNumber": 66, "surahNameArabic": "سُورَةُ التَّحۡرِيمِ", "surahNameMalayalam": "സൂറത്തുത്തഹ്‌രീം (നിഷിദ്ധമാക്കൽ)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ یَـٰۤأَیُّهَا ٱلنَّبِیُّ لِمَ تُحَرِّمُ مَاۤ أَحَلَّ ٱللَّهُ لَكَۖ تَبۡتَغِی مَرۡضَاتَ أَزۡوَ ٰ⁠جِكَۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ\n", "jalalayn": "«يا أيّها النَّبِيّ لِمَ تُحَرِّم ما أحَلَّ اللَّه لَك» مِن أمَتك مارِيَة القِبْطِيَّة لَمّا واقَعَها فِي بَيْت حَفْصَة وكانَتْ غائِبَة فَجاءَتْ وشَقَّ عَلَيْها كَوْن ذَلِكَ فِي بَيْتها وعَلى فِراشها حَيْثُ قُلْت: هِيَ حَرام عَلَيَّ «تَبْتَغِي» بِتَحْرِيمِها «مَرْضاة أزْواجك» أيْ رِضاهُنَّ «واللَّه غَفُور رَحِيم» غَفَرَ لَك هَذا التَّحْرِيم", "malayalam": "«നബിയേ, താങ്കളുടെ ഭാര്യമാരുടെ തൃപ്തി കാംക്ഷിച്ചുകൊണ്ട് അല്ലാഹു താങ്കൾക്ക് അനുവദിച്ചു തന്നതിനെ താങ്കൾ എന്തിനാണ് നിഷിദ്ധമാക്കുന്നത്? (മാരിയത്തുൽ ഖിബ്ത്വിയ്യയെ തനിക്ക് നിഷിദ്ധമാക്കി പ്രഖ്യാപിച്ച പശ്ചാത്തലത്തിൽ ഇത് അവതരിച്ചു); അല്ലാഹു ഏറെ പൊറുക്കുന്നവനും ദയാപരനുമാകുന്നു».", "malayalamMatn": "ഓ; നബീ, നീയെന്തിനാണ് നിന്‍റെ ഭാര്യമാരുടെ പ്രീതിതേടിക്കൊണ്ട്‌, അല്ലാഹു അനുവദിച്ചു തന്നത് നിഷിദ്ധമാക്കുന്നത്‌? അല്ലാഹു ഏറെ പൊറുക്കുന്നവനും കരുണാനിധിയുമാകുന്നു."}, {"ayahNumber": 2, "quranText": "قَدۡ فَرَضَ ٱللَّهُ لَكُمۡ تَحِلَّةَ أَیۡمَـٰنِكُمۡۚ وَٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ ٱلۡعَلِیمُ ٱلۡحَكِیمُ\n", "jalalayn": "«قَدْ فَرَضَ اللَّه» شَرَعَ «لَكُمْ تَحِلَّة أيْمانكُمْ» تَحْلِيلها بِالكَفّارَةِ المَذْكُورَة فِي سُورَة \"المائِدَة\" ومِن الأَيْمان تَحْرِيم الأَمَة وهَلْ كَفَّرَ ﷺ ؟ قالَ مُقاتِل: أعْتَقَ رَقَبَة فِي تَحْرِيم مارِيَة وقالَ الحَسَن: لَمْ يُكَفِّر لِأَنَّهُ ﷺ مَغْفُور لَهُ «واللَّه مَوْلاكُمْ» ناصِركُمْ", "malayalam": "«നിങ്ങളുടെ ശപഥങ്ങൾ ഒഴിവാക്കാനുള്ള പ്രായശ്ചിത്തം അല്ലാഹു നിങ്ങൾക്ക് നിശ്ചയിച്ചു തന്നിട്ടുണ്ട്; അല്ലാഹു നിങ്ങളുടെ സംരക്ഷകനാകുന്നു; അവൻ സർവ്വജ്ഞനും പരമയുക്തിമാനുമാകുന്നു».", "malayalamMatn": "നിങ്ങളുടെ ശപഥങ്ങള്‍ക്കുള്ള പരിഹാരം അല്ലാഹു നിങ്ങള്‍ക്ക് നിയമമാക്കിത്തന്നിരിക്കുന്നു. അല്ലാഹു നിങ്ങളുടെ യജമാനനാകുന്നു. അവനത്രെ സര്‍വ്വജ്ഞനും യുക്തിമാനും."}, {"ayahNumber": 3, "quranText": "وَإِذۡ أَسَرَّ ٱلنَّبِیُّ إِلَىٰ بَعۡضِ أَزۡوَ ٰ⁠جِهِۦ حَدِیثࣰا فَلَمَّا نَبَّأَتۡ بِهِۦ وَأَظۡهَرَهُ ٱللَّهُ عَلَیۡهِ عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضࣲۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتۡ مَنۡ أَنۢبَأَكَ هَـٰذَاۖ قَالَ نَبَّأَنِیَ ٱلۡعَلِیمُ ٱلۡخَبِیرُ\n", "jalalayn": "«و» اذْكُرْ «إذْ أسَرَّ النَّبِيّ إلى بَعْض أزْواجه» هِيَ حَفْصَة «حَدِيثًا» هُوَ تَحْرِيم مارِيَة وقالَ لَها لا تُفْشِيه «فَلَمّا نَبَّأَتْ بِهِ» عائِشَة ظَنًّا مِنها أنْ لا حَرَج فِي ذَلِكَ «وأَظْهَرَهُ اللَّه» أطْلَعَهُ «عَلَيْهِ» عَلى المُنَبَّأ بِهِ «عَرَّفَ بَعْضه» لِحَفْصَةَ «وأَعْرَضَ عَنْ بَعْض» تَكَرُّمًا مِنهُ «فَلَمّا نَبَّأَها بِهِ قالَتْ مَن أنْبَأَك هَذا قالَ نَبَّأَنِي العَلِيم الخَبِير» أيْ اللَّه", "malayalam": "«നബി തന്റെ ഭാര്യമാരിൽ ഒരാളോട് (ഹഫ്സയോട്) ഒരു രഹസ്യം പറഞ്ഞ സന്ദർഭം! എന്നിട്ട് അവരത് (ആയിശയോട്) വെളിപ്പെടുത്തുകയും അല്ലാഹു അത് നബിക്ക് വെളിപ്പെടുത്തിക്കൊടുക്കുകയും ചെയ്തപ്പോൾ, നബി അതിൽ ചിലത് അവർക്ക് അറിയിച്ചുകൊടുക്കുകയും ചിലതിൽ നിന്ന് ഒഴിഞ്ഞുമാറുകയും ചെയ്തു; അങ്ങനെ നബി അവരോട് അത് അറിയിച്ചപ്പോൾ അവർ ചോദിച്ചു: ആരാണ് താങ്കൾക്കിത് അറിയിച്ചുതന്നത്? നബി പറഞ്ഞു: സർവ്വജ്ഞനും സൂക്ഷ്മജ്ഞാനിയുമായ അല്ലാഹുവാണ് എന്നെ വിവരമറിയിച്ചത്!».", "malayalamMatn": "നബി അദ്ദേഹത്തിന്‍റെ ഭാര്യമാരില്‍ ഒരാളോട് ഒരു വര്‍ത്തമാനം രഹസ്യമായി പറഞ്ഞ സന്ദര്‍ഭം (ശ്രദ്ധേയമാകുന്നു.) എന്നിട്ട് ആ ഭാര്യ അത് (മറ്റൊരാളെ) അറിയിക്കുകയും, നബിക്ക് അല്ലാഹു അത് വെളിപ്പെടുത്തി കൊടുക്കുകയും ചെയ്തപ്പോള്‍ അതിന്‍റെ ചില ഭാഗം അദ്ദേഹം (ആ ഭാര്യയ്ക്ക്‌) അറിയിച്ചുകൊടുക്കുകയും ചില ഭാഗം വിട്ടുകളയുകയും ചെയ്തു. അങ്ങനെ അവളോട് (ആ ഭാര്യയോട്‌) അദ്ദേഹം അതിനെ പറ്റി വിവരം അറിയിച്ചപ്പോള്‍ അവള്‍ പറഞ്ഞു: താങ്കള്‍ക്ക് ആരാണ് ഈ വിവരം അറിയിച്ചു തന്നത് ? നബി (സ) പറഞ്ഞു: സര്‍വ്വജ്ഞനും സൂക്ഷ്മജ്ഞാനിയുമായിട്ടുള്ളവനാണ് എനിക്ക് വിവരമറിയിച്ചു തന്നത്‌."}, {"ayahNumber": 4, "quranText": "إِن تَتُوبَاۤ إِلَى ٱللَّهِ فَقَدۡ صَغَتۡ قُلُوبُكُمَاۖ وَإِن تَظَـٰهَرَا عَلَیۡهِ فَإِنَّ ٱللَّهَ هُوَ مَوۡلَىٰهُ وَجِبۡرِیلُ وَصَـٰلِحُ ٱلۡمُؤۡمِنِینَۖ وَٱلۡمَلَـٰۤىِٕكَةُ بَعۡدَ ذَ ٰ⁠لِكَ ظَهِیرٌ\n", "jalalayn": "«إنْ تَتُوبا» أيْ حَفْصَة وعائِشَة «إلى اللَّه فَقَدْ صَغَتْ قُلُوبكُما» مالَتْ إلى تَحْرِيم مارِيَة أيْ سَرَّكُما ذَلِكَ مَعَ كَراهَة النَّبِيّ ﷺ لَهُ وذَلِكَ ذَنْب وجَواب الشَّرْط مَحْذُوف أيْ تَقَبُّلًا وأَطْلَقَ قُلُوب عَلى قَلْبَيْنِ ولَمْ يُعَبِّر بِهِ لِاسْتِثْقالِ الجَمْع بَيْن تَثْنِيَتَيْنِ فِيما هُوَ كالكَلِمَةِ الواحِدَة «وإنْ تَظاهَرا» بِإدْغامِ التّاء الثّانِيَة فِي الأَصْل فِي الظّاء وفِي قِراءَة بِدُونِها تَتَعاوَنا «عَلَيْهِ» أيْ النَّبِيّ فِيما يَكْرَههُ «فَإنَّ اللَّه هُوَ» فَصْل «مَوْلاهُ» ناصِره «وجِبْرِيل وصالِح المُؤْمِنِينَ» أبُو بَكْر وعُمَر رَضِيَ اللَّه عَنْهُما مَعْطُوف عَلى مَحَلّ اسْم إنْ فَيَكُونُونَ ناصِرِيهِ «والمَلائِكَة بَعْد ذَلِكَ» بَعْد نَصْر اللَّه والمَذْكُورِينَ «ظَهِير» ظُهَراء أعْوان لَهُ فِي نَصْره عَلَيْكُما", "malayalam": "«നിങ്ങൾ രണ്ടുപേരും (ഹഫ്സയും ആയിശയും) അല്ലാഹുവിലേക്ക് പശ്ചാത്തപിച്ചു മടങ്ങുകയാണെങ്കിൽ (അത് നിങ്ങൾക്ക് ഉത്തമമാണ്); കാരണം നിങ്ങളുടെ ഹൃദയങ്ങൾ തെറ്റിപ്പോയിരിക്കുന്നു; ഇനി നിങ്ങൾ ഇരുവരും പ്രവാചകനെതിരെ ഒത്തുചേരുകയാണെങ്കിൽ തീർച്ചയായും അല്ലാഹു തന്നെയാകുന്നു അവന്റെ സഹായി; ജിബ്‌രീലും സജ്ജനങ്ങളായ സത്യവിശ്വാസികളും അതിന് പുറമെ മലക്കുകളും അവന് തുണയായിരിക്കുന്നതാണ്».", "malayalamMatn": "നിങ്ങള്‍ രണ്ടു പേരും അല്ലാഹുവിങ്കലേക്ക് പശ്ചാത്തപിച്ചു മടങ്ങുന്നുവെങ്കില്‍ (അങ്ങനെ ചെയ്യുക.) കാരണം നിങ്ങളുടെ രണ്ടുപേരുടെയും ഹൃദയങ്ങള്‍ (തിന്‍മയിലേക്ക്‌) ചാഞ്ഞുപോയിരിക്കുന്നു. ഇനി നിങ്ങള്‍ ഇരുവരും അദ്ദേഹത്തിനെതിരില്‍ (റസൂലിനെതിരില്‍) പരസ്പരം സഹകരിക്കുന്ന പക്ഷം തീര്‍ച്ചയായും അല്ലാഹുവാകുന്നു അദ്ദേഹത്തിന്‍റെ യജമാനന്‍. ജിബ്‌രീലും സദ്‌വൃത്തരായ സത്യവിശ്വാസികളും അതിനു പുറമെ മലക്കുകളും അദ്ദേഹത്തിന് സഹായികളായിരിക്കുന്നതാണ്‌."}, {"ayahNumber": 5, "quranText": "عَسَىٰ رَبُّهُۥۤ إِن طَلَّقَكُنَّ أَن یُبۡدِلَهُۥۤ أَزۡوَ ٰ⁠جًا خَیۡرࣰا مِّنكُنَّ مُسۡلِمَـٰتࣲ مُّؤۡمِنَـٰتࣲ قَـٰنِتَـٰتࣲ تَـٰۤىِٕبَـٰتٍ عَـٰبِدَ ٰ⁠تࣲ سَـٰۤىِٕحَـٰتࣲ ثَیِّبَـٰتࣲ وَأَبۡكَارࣰا\n", "jalalayn": "«عَسى رَبّه إنْ طَلَّقَكُنَّ» أيْ طَلَّقَ النَّبِيّ أزْواجه «أنْ يُبَدِّلهُ» بِالتَّشْدِيدِ والتَّخْفِيف «أزْواجًا خَيْرًا مِنكُنَّ» خَبَر عَسى والجُمْلَة جَواب الشَّرْط ولَمْ يَقَع التَّبْدِيل لِعَدَمِ وُقُوع الشَّرْط «مُسْلِمات» مُقِرّات بِالإسْلامِ «مُؤْمِنات» مُخْلِصات «قانِتات» مُطِيعات «تائِبات عابِدات سائِحات» صائِمات أوْ مُهاجِرات", "malayalam": "«നബി നിങ്ങളെ വിവാഹമോചനം ചെയ്യുന്ന പക്ഷം, നിങ്ങളേക്കാൾ ഉത്തമരായ ഭാര്യമാരെ അദ്ദേഹത്തിന്റെ രക്ഷിതാവ് അദ്ദേഹത്തിന് പകരം നൽകിയേക്കാം; മുസ്ലിംകളും സത്യവിശ്വാസിനികളും ഭയഭക്തിയുള്ളവരും പശ്ചാത്തപിക്കുന്നവരും ആരാധനകളിൽ മുഴുകുന്നവരും നോമ്പനുഷ്ഠിക്കുന്നവരുമായ വിധവകളെയും കന്യകകളെയും!».", "malayalamMatn": "(പ്രവാചകപത്നിമാരേ,) നിങ്ങളെ അദ്ദേഹം വിവാഹമോചനം ചെയ്യുന്ന പക്ഷം, നിങ്ങളെക്കാള്‍ നല്ലവരായ ഭാര്യമാരെ അദ്ദേഹത്തിന് അദ്ദേഹത്തിന്‍റെ രക്ഷിതാവ് പകരം നല്‍കിയേക്കാം. മുസ്ലിംകളും സത്യവിശ്വാസിനികളും ഭയഭക്തിയുള്ളവരും പശ്ചാത്താപമുള്ളവരും ആരാധനാനിരതരും വ്രതമനുഷ്ഠിക്കുന്നവരും വിധവകളും കന്യകകളുമായിട്ടുള്ള സ്ത്രീകളെ."}, {"ayahNumber": 6, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ قُوۤا۟ أَنفُسَكُمۡ وَأَهۡلِیكُمۡ نَارࣰا وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُ عَلَیۡهَا مَلَـٰۤىِٕكَةٌ غِلَاظࣱ شِدَادࣱ لَّا یَعۡصُونَ ٱللَّهَ مَاۤ أَمَرَهُمۡ وَیَفۡعَلُونَ مَا یُؤۡمَرُونَ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا قُوا أنْفُسكُمْ وأَهْلِيكُمْ» بِالحَمْلِ عَلى طاعَة اللَّه «نارًا وقُودها النّاس» الكُفّار «والحِجارَة» كَأَصْنامِهِمْ مِنها يَعْنِي أنَّها مُفْرِطَة الحَرارَة تَتَّقِد بِما ذُكِرَ لا كَنارِ الدُّنْيا تَتَّقِد بِالحَطَبِ ونَحْوه «عَلَيْها مَلائِكَة» خَزَنَتها عُدَّتهمْ تِسْعَة عَشَر كَما سَيَأْتِي فِي \"المُدَّثِّر\" «غِلاظ» مِن غِلَظ القَلْب «شِداد» فِي البَطْش «لا يَعْصُونَ اللَّه ما أمَرَهُمْ» بَدَل مِن الجَلالَة أيْ لا يَعْصُونَ أمْر اللَّه «ويَفْعَلُونَ ما يُؤْمَرُونَ» تَأْكِيد والآيَة تَخْوِيف لِلْمُؤْمِنِينَ عَنْ الِارْتِداد ولِلْمُنافِقِينَ المُؤْمِنِينَ بِأَلْسِنَتِهِمْ دُون قُلُوبهمْ", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, നിങ്ങളുടെ സ്വന്തം ശരീരങ്ങളെയും നിങ്ങളുടെ കുടുംബങ്ങളെയും നിങ്ങൾ നരകാഗ്നിയിൽ നിന്ന് കാത്തുരക്ഷിക്കുവിൻ; മനുഷ്യരും കല്ലുകളുമാകുന്നു അതിന്റെ ഇന്ധനം; കഠിനഹൃദയരും ശക്തരുമായ മലക്കുകൾ അതിന് കാവൽക്കാരായുണ്ട്; അല്ലാഹു അവരോട് കൽപിച്ചതിൽ അവർ അവനോട് അനുസരണക്കേട് കാണിക്കുകയില്ല; കൽപിക്കപ്പെടുന്നതെന്തും അവർ കൃത്യമായി പ്രവർത്തിക്കുകയും ചെയ്യും».", "malayalamMatn": "സത്യവിശ്വാസികളേ, സ്വദേഹങ്ങളെയും നിങ്ങളുടെ ബന്ധുക്കളെയും മനുഷ്യരും കല്ലുകളും ഇന്ധനമായിട്ടുള്ള നരകാഗ്നിയില്‍ നിന്ന് നിങ്ങള്‍ കാത്തുരക്ഷിക്കുക. അതിന്‍റെ മേല്‍നോട്ടത്തിന് പരുഷസ്വഭാവമുള്ളവരും അതിശക്തന്‍മാരുമായ മലക്കുകളുണ്ടായിരിക്കും. അല്ലാഹു അവരോട് കല്‍പിച്ചകാര്യത്തില്‍ അവനോടവര്‍ അനുസരണക്കേട് കാണിക്കുകയില്ല. അവരോട് കല്‍പിക്കപ്പെടുന്നത് എന്തും അവര്‍ പ്രവര്‍ത്തിക്കുകയും ചെയ്യും."}, {"ayahNumber": 7, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ كَفَرُوا۟ لَا تَعۡتَذِرُوا۟ ٱلۡیَوۡمَۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ\n", "jalalayn": "«يا أيّها الَّذِينَ كَفَرُوا لا تَعْتَذِرُوا اليَوْم» يُقال لَهُمْ ذَلِكَ عِنْد دُخُولهمْ النّار أيْ لِأَنَّهُ لا يَنْفَعكُمْ «إنّما تُجْزَوْنَ ما كُنْتُمْ تَعْمَلُونَ» أيْ جَزاءَهُ", "malayalam": "«ഹേ അവിശ്വാസികളേ, ഇന്ന് നിങ്ങൾ ഒഴികഴിവുകൾ പറയേണ്ടതില്ല; നിങ്ങൾ പ്രവർത്തിച്ചുകൊണ്ടിരുന്നതിന് മാത്രമാണ് നിങ്ങൾക്ക് പ്രതിഫലം നൽകപ്പെടുന്നത്!».", "malayalamMatn": "സത്യനിഷേധികളേ, നിങ്ങള്‍ ഇന്ന് ഒഴികഴിവ് പറയേണ്ട. നിങ്ങള്‍ ചെയ്തുകൊണ്ടിരുന്നതിനു മാത്രമാണ് നിങ്ങള്‍ക്ക് പ്രതിഫലം നല്‍കപ്പെടുന്നത്‌."}, {"ayahNumber": 8, "quranText": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ تُوبُوۤا۟ إِلَى ٱللَّهِ تَوۡبَةࣰ نَّصُوحًا عَسَىٰ رَبُّكُمۡ أَن یُكَفِّرَ عَنكُمۡ سَیِّـَٔاتِكُمۡ وَیُدۡخِلَكُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ یَوۡمَ لَا یُخۡزِی ٱللَّهُ ٱلنَّبِیَّ وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥۖ نُورُهُمۡ یَسۡعَىٰ بَیۡنَ أَیۡدِیهِمۡ وَبِأَیۡمَـٰنِهِمۡ یَقُولُونَ رَبَّنَاۤ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَاۤۖ إِنَّكَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ\n", "jalalayn": "«يا أيّها الَّذِينَ آمَنُوا تُوبُوا إلى اللَّه تَوْبَة نَصُوحًا» بِفَتْحِ النُّون وضَمّها: صادِقَة بِأَنْ لا يُعاد إلى الذَّنْب ولا يُراد العَوْد إلَيْهِ «عَسى رَبّكُمْ» تَرْجِيَة تَقَع «أنْ يُكَفِّر عَنْكُمْ سَيِّئاتكُمْ ويُدْخِلكُمْ جَنّات» بَساتِين «تَجْرِي مِن تَحْتها الأَنْهار يَوْم لا يُخْزِي اللَّه» بِإدْخالِ النّار «النَّبِيّ والَّذِينَ آمَنُوا مَعَهُ نُورهمْ يَسْعى بَيْن أيْدِيهمْ» أمامهمْ «و» يَكُون «بِأَيْمانِهِمْ يَقُولُونَ» مُسْتَأْنَف «رَبّنا أتْمِمْ لَنا نُورنا» إلى الجَنَّة والمُنافِقُونَ يُطْفَأ نُورهمْ «واغْفِرْ لَنا» رَبّنا", "malayalam": "«ഹേ വിശ്വസിച്ചവരേ, നിഷ്കളങ്കമായ പശ്ചാത്താപത്തോടെ (തൗബതുൻ നസ്വൂഹ്) നിങ്ങൾ അല്ലാഹുവിലേക്ക് ഖേദിച്ചു മടങ്ങുവിൻ; നിങ്ങളുടെ രക്ഷിതാവ് നിങ്ങളുടെ പാപങ്ങൾ പൊറുത്തുതരികയും താഴെ അരുവികൾ ഒഴുകുന്ന സ്വർഗ്ഗത്തോപ്പുകളിൽ നിങ്ങളെ പ്രവേശിപ്പിക്കുകയും ചെയ്തേക്കാം; നബിയെയും അദ്ദേഹത്തോടൊപ്പം വിശ്വസിച്ചവരെയും അല്ലാഹു അപമാനിക്കാത്ത ആ ദിവസം! അവരുടെ പ്രകാശം അവരുടെ മുന്നിലും വലതുഭാഗങ്ങളിലും പ്രസരിച്ചുകൊണ്ടിരിക്കും; അവർ പറയും: ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾക്ക് ഞങ്ങളുടെ പ്രകാശം നീ പൂർണ്ണമാക്കിത്തരേണമേ! ഞങ്ങൾക്ക് നീ പൊറുത്തുതരേണമേ! തീർച്ചയായും നീ സർവ്വകാര്യങ്ങൾക്കും കഴിവുള്ളവനത്രെ!».", "malayalamMatn": "സത്യവിശ്വാസികളേ, നിങ്ങള്‍ അല്ലാഹുവിങ്കലേക്ക് നിഷ്കളങ്കമായ പശ്ചാത്താപം കൈക്കൊണ്ട് മടങ്ങുക. നിങ്ങളുടെ രക്ഷിതാവ് നിങ്ങളുടെ പാപങ്ങള്‍ മായ്ച്ചുകളയുകയും താഴ്ഭാഗത്തു കൂടി അരുവികള്‍ ഒഴുകുന്ന സ്വര്‍ഗത്തോപ്പുകളില്‍ നിങ്ങളെ പ്രവേശിപ്പിക്കുകയും ചെയ്തേക്കാം. അല്ലാഹു പ്രവാചകനെയും അദ്ദേഹത്തോടൊപ്പം വിശ്വസിച്ചവരെയും അപമാനിക്കാത്ത ദിവസത്തില്‍. അവരുടെ പ്രകാശം അവരുടെ മുന്നിലൂടെയും വലതുവശങ്ങളിലൂടെയും സഞ്ചരിക്കും. അവര്‍ പറയും: ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങളുടെ പ്രകാശം ഞങ്ങള്‍ക്കു നീ പൂര്‍ത്തീകരിച്ച് തരികയും, ഞങ്ങള്‍ക്കു നീ പൊറുത്തുതരികയും ചെയ്യേണമേ. തീര്‍ച്ചയായും നീ ഏതു കാര്യത്തിനും കഴിവുള്ളവനാകുന്നു."}, {"ayahNumber": 9, "quranText": "یَـٰۤأَیُّهَا ٱلنَّبِیُّ جَـٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَـٰفِقِینَ وَٱغۡلُظۡ عَلَیۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِیرُ\n", "jalalayn": "«يا أيّها النَّبِيّ جاهِدْ الكُفّار» بِالسَّيْفِ «والمُنافِقِينَ» بِاللِّسانِ والحُجَّة «واغْلُظْ عَلَيْهِمْ» بِالِانْتِهاءِ والمَقْت «ومَأْواهُمْ جَهَنَّم وبِئْسَ المَصِير» هِيَ", "malayalam": "«നബിയേ, സത്യനിഷേധികളോടും കപടവിശ്വാസികളോടും താങ്കൾ സമരം ചെയ്യുക; അവരോട് കാർക്കശ്യം കാണിക്കുകയും ചെയ്യുക; അവരുടെ സങ്കേതം നരകമാകുന്നു; അത് എത്രയോ ചീത്തയായ തിരിച്ചുവരവ്!».", "malayalamMatn": "ഓ; നബീ, സത്യനിഷേധികളോടും കപടവിശ്വാസികളോടും നീ സമരം ചെയ്യുകയും അവരോട് പരുഷമായി പെരുമാറുകയും ചെയ്യുക. അവരുടെ സങ്കേതം നരകമാകുന്നു. എത്തിച്ചേരാനുള്ള ആ സ്ഥലം എത്രയോ ചീത്ത!"}, {"ayahNumber": 10, "quranText": "ضَرَبَ ٱللَّهُ مَثَلࣰا لِّلَّذِینَ كَفَرُوا۟ ٱمۡرَأَتَ نُوحࣲ وَٱمۡرَأَتَ لُوطࣲۖ كَانَتَا تَحۡتَ عَبۡدَیۡنِ مِنۡ عِبَادِنَا صَـٰلِحَیۡنِ فَخَانَتَاهُمَا فَلَمۡ یُغۡنِیَا عَنۡهُمَا مِنَ ٱللَّهِ شَیۡـࣰٔا وَقِیلَ ٱدۡخُلَا ٱلنَّارَ مَعَ ٱلدَّ ٰ⁠خِلِینَ\n", "jalalayn": "«ضَرَبَ اللَّه مَثَلًا لِلَّذِينَ كَفَرُوا امْرَأَة نُوح وامْرَأَة لُوط كانَتا تَحْت عَبْدَيْنِ مِن عِبادنا صالِحَيْنِ فَخانَتاهُما» أيْ فَخانَتاهُما فِي الدِّين إذْ كَفَرَتا وكانَتْ امْرَأَة نُوح واسْمها واهِلَة تَقُول لِقَوْمِهِ: إنّهُ مَجْنُون وامْرَأَة لُوط واسْمها واعِلَة تَدُلّ قَوْمه عَلى أضْيافه إذا نَزَلُوا بِهِ لَيْلًا بِإيقادِ النّار ونَهارًا بِالتَّدْخِينِ «فَلَمْ يُغْنِيا» أيْ نُوح ولُوط «عَنْهُما مِن اللَّه» مِن عَذابه «شَيْئًا وقِيلَ» أيْ وقِيلَ لَهُما «اُدْخُلا النّار مَعَ الدّاخِلِينَ» مِن كُفّار قَوْم نُوح وقَوْم لُوط", "malayalam": "«സത്യനിഷേധികൾക്ക് അല്ലാഹു നൂഹിന്റെ ഭാര്യയെയും ലൂത്വിന്റെ ഭാര്യയെയും മാതൃകയായി കാണിച്ചിരിക്കുന്നു; അവർ നമ്മുടെ സജ്ജനങ്ങളായ രണ്ടു ദാസന്മാരുടെ കീഴിലായിരുന്നു; എന്നിട്ട് അവർ രണ്ടുപേരും ആ പ്രവാചകന്മാരെ വഞ്ചിച്ചു; എന്നാൽ അല്ലാഹുവിന്റെ ശിക്ഷയിൽ നിന്ന് ആ രണ്ടുപേർക്കും അവരെ ഒട്ടും രക്ഷിക്കാനായില്ല; പ്രവേശിക്കുന്നവരോടൊപ്പം നിങ്ങളിരുവരും നരകത്തിൽ പ്രവേശിച്ചുകൊള്ളുക എന്ന് അവരോട് പറയപ്പെടുകയും ചെയ്തു».", "malayalamMatn": "സത്യനിഷേധികള്‍ക്ക് ഉദാഹരണമായി നൂഹിന്‍റെ ഭാര്യയെയും, ലൂത്വിന്‍റെ ഭാര്യയെയും അല്ലാഹു ഇതാ എടുത്തുകാണിച്ചിരിക്കുന്നു. അവര്‍ രണ്ടുപേരും നമ്മുടെ ദാസന്‍മാരില്‍ പെട്ട സദ്‌വൃത്തരായ രണ്ട് ദാസന്‍മാരുടെ കീഴിലായിരുന്നു. എന്നിട്ട് അവരെ രണ്ടുപേരെയും ഇവര്‍ വഞ്ചിച്ചു കളഞ്ഞു. അപ്പോള്‍ അല്ലാഹുവിന്‍റെ ശിക്ഷയില്‍ നിന്ന് യാതൊന്നും അവര്‍ രണ്ടുപേരും ഇവര്‍ക്ക് ഒഴിവാക്കികൊടുത്തില്ല. നിങ്ങള്‍ രണ്ടുപേരും നരകത്തില്‍ കടക്കുന്നവരോടൊപ്പം കടന്നുകൊള്ളുക എന്ന് പറയപ്പെടുകയും ചെയ്തു."}, {"ayahNumber": 11, "quranText": "وَضَرَبَ ٱللَّهُ مَثَلࣰا لِّلَّذِینَ ءَامَنُوا۟ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ ٱبۡنِ لِی عِندَكَ بَیۡتࣰا فِی ٱلۡجَنَّةِ وَنَجِّنِی مِن فِرۡعَوۡنَ وَعَمَلِهِۦ وَنَجِّنِی مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ\n", "jalalayn": "«وضَرَبَ اللَّه مَثَلًا لِلَّذِينَ آمَنُوا امْرَأَة فِرْعَوْن» آمَنَتْ بِمُوسى واسْمها آسِيَة فَعَذَّبَها فِرْعَوْن بِأَنْ أوْتَدَ يَدَيْها ورِجْلَيْها وأَلْقى عَلى صَدْرها رَحًى عَظِيمَة واسْتَقْبَلَ بِها الشَّمْس فَكانَتْ إذا تَفَرَّقَ عَنْها مَن وُكِلَ بِها ظَلَّلَتْها المَلائِكَة «إذْ قالَتْ» فِي حال التَّعْذِيب «رَبّ ابْن لِي عِنْدك بَيْتًا فِي الجَنَّة» فَكُشِفَ لَها فَرَأَتْهُ فَسَهُلَ عَلَيْها التَّعْذِيب «ونَجِّنِي مِن فِرْعَوْن وعَمَله» وتَعْذِيبه «ونَجِّنِي مِن القَوْم الظّالِمِينَ» أهْل دِينه فَقَبَضَ اللَّه رُوحها وقالَ ابْن كَيْسان: رُفِعَتْ إلى الجَنَّة حَيَّة فَهِيَ تَأْكُل وتَشْرَب", "malayalam": "«സത്യവിശ്വാസികൾക്ക് അല്ലാഹു ഫിർഔന്റെ ഭാര്യയെ (ആസിയയെ) മാതൃകയായി കാണിച്ചിരിക്കുന്നു; അവർ പ്രാർത്ഥിച്ച സന്ദർഭം: എന്റെ രക്ഷിതാവേ, എനിക്ക് നിന്റെയടുക്കൽ സ്വർഗ്ഗത്തിൽ ഒരു ഭവനം നിർമ്മിച്ച് തരേണമേ! ഫിർഔനിൽ നിന്നും അവന്റെ ദുഷ്ചെയ്തികളിൽ നിന്നും എന്നെ നീ രക്ഷിക്കേണമേ! അക്രമികളായ ജനങ്ങളിൽ നിന്നും എന്നെ നീ രക്ഷിക്കേണമേ!».", "malayalamMatn": "സത്യവിശ്വാസികള്‍ക്ക് ഒരു ഉപമയായി അല്ലാഹു ഫിര്‍ഔന്‍റെ ഭാര്യയെ എടുത്തുകാണിച്ചിരിക്കുന്നു. അവള്‍ പറഞ്ഞ സന്ദര്‍ഭം: എന്‍റെ രക്ഷിതാവേ, എനിക്ക് നീ നിന്‍റെ അടുക്കല്‍ സ്വര്‍ഗത്തില്‍ ഒരു ഭവനം ഉണ്ടാക്കിത്തരികയും, ഫിര്‍ഔനില്‍ നിന്നും അവന്‍റെ പ്രവര്‍ത്തനത്തില്‍ നിന്നും എന്നെ നീ രക്ഷിക്കേണമേ. അക്രമികളായ ജനങ്ങളില്‍ നിന്നും എന്നെ നീ രക്ഷിക്കുകയും ചെയ്യേണമേ."}, {"ayahNumber": 12, "quranText": "وَمَرۡیَمَ ٱبۡنَتَ عِمۡرَ ٰ⁠نَ ٱلَّتِیۤ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِیهِ مِن رُّوحِنَا وَصَدَّقَتۡ بِكَلِمَـٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتۡ مِنَ ٱلۡقَـٰنِتِینَ\n", "jalalayn": "«ومَرْيَم» عَطْف عَلى امْرَأَة فِرْعَوْن «ابْنَت عِمْران الَّتِي أحْصَنَتْ فَرْجها» حَفِظَتْهُ «فَنَفَخْنا فِيهِ مِن رُوحنا» أيْ جِبْرِيل حَيْثُ نَفَخَ فِي جَيْب دِرْعها بِخَلْقِ اللَّه تَعالى فَعَلَهُ الواصِل إلى فَرْجها فَحَمَلَتْ بِعِيسى «وصَدَّقَتْ بِكَلِماتِ رَبّها» شَرائِعه «وكُتُبه» أيْ وكُتُبه المُنَزَّلَة «وكانَتْ مِن القانِتِينَ» مِن القَوْم المُطِيعِينَ", "malayalam": "«തന്റെ ഗുഹ്യസ്ഥാനം കാത്തുസൂക്ഷിച്ച ഇംറാന്റെ മകൾ മർയമിനെയും (അല്ലാഹു മാതൃകയാക്കി); അപ്പോൾ നാം നമ്മുടെ ആത്മാവിൽ നിന്ന് (ജിബ്‌രീൽ മുഖേന) അതിൽ ഊതി; അവർ തന്റെ രക്ഷിതാവിന്റെ കൽപനകളെയും അവന്റെ വേദഗ്രന്ഥങ്ങളെയും സത്യപ്പെടുത്തി; അവർ അനുസരണമുള്ളവരുടെ കൂട്ടത്തിലുമായിരുന്നു».", "malayalamMatn": "തന്‍റെ ഗുഹ്യസ്ഥാനം കാത്തുസൂക്ഷിച്ച ഇംറാന്‍റെ മകളായ മര്‍യമിനെയും (ഉപമയായി എടുത്ത് കാണിച്ചിരിക്കുന്നു.) അപ്പോള്‍ നമ്മുടെ ആത്മചൈതന്യത്തില്‍ നിന്നു നാം അതില്‍ ഊതുകയുണ്ടായി. തന്‍റെ രക്ഷിതാവിന്‍റെ വചനങ്ങളിലും ഗ്രന്ഥങ്ങളിലും അവള്‍ വിശ്വസിക്കുകയും അവള്‍ ഭയഭക്തിയുള്ളവരുടെ കൂട്ടത്തിലാവുകയും ചെയ്തു."}], "topPoints": ["അനുവദനീയമായത് നിഷിദ്ധമാക്കാതിരിക്കുക (خلاصة السورة)", "കുടുംബത്തെ നരകാഗ്നിയിൽ നിന്ന് രക്ഷിക്കുക"], "topQuestions": [{"q": "സത്യവിശ്വാസികൾക്ക് മാതൃകയായി ഈ സൂറത്തിൽ ആരെയാണ് പറയുന്നത്?", "a": "ഫിർഔന്റെ ഭാര്യ ആസിയയെയും മർയമിനെയും."}], "asbabAlNuzul": [{"ayahNumber": 1, "quranText": "یَـٰۤأَیُّهَا ٱلنَّبِیُّ لِمَ تُحَرِّمُ مَاۤ أَحَلَّ ٱللَّهُ لَكَۖ تَبۡتَغِی مَرۡضَاتَ أَزۡوَ ٰ⁠جِكَۚ", "arabicSnippet": "«يا أيها النبي لم تحرم ما أحل الله لك» نزل في تحريم النبي ﷺ مارية القبطية رعاية لخاطر أزواجه، أو في قصة تحريمه شرب العسل عند زينب بنت جحش بعد تواطؤ عائشة وحفصة رضي الله عنهما.", "malayalamExplanation": "ജലാലൈനിയിൽ രണ്ട് പ്രബല കാരണങ്ങൾ വ്യക്തമാക്കുന്നു: (1) നബി ﷺ സൈനബ് ബിൻത് ജഹ്ശിന്റെ (റ) വീട്ടിൽ വെച്ച് തേൻ കുടിക്കാറുണ്ടായിരുന്നു. ഇതിൽ സപത്നി അസൂയ പൂണ്ട ആഇശയും ഹഫ്സ്വയും (റ) നബി ﷺ വരുമ്പോൾ 'താങ്കളിൽ നിന്ന് മഗാഫീറിന്റെ ദുർഗന്ധം വരുന്നുണ്ടോ' എന്ന് ചോദിക്കാൻ ധാരണയായി. ദുർഗന്ധം വെറുത്തിരുന്ന തിരുനബി ﷺ ഇനി മേൽ തേൻ കുടിക്കില്ലെന്ന് സ്വയം സത്യം ചെയ്തു. (2) മറ്റൊന്ന് മാരിയത്തുൽ ഖിബ്ത്വിയ്യയെ സംബന്ധിച്ച് ഭാര്യമാരുടെ തൃപ്തിക്കായി സ്വയം നിഷിദ്ധമാക്കിയതാണ്. അല്ലാഹു അനുവദിച്ചതിനെ ആരുടെയും പ്രീതിക്കായി നിഷിദ്ധമാക്കരുതെന്നും സത്യത്തിന് കഫാറത്ത് നൽകണമെന്നും കൽപിച്ചുകൊണ്ട് ഈ വചനം അവതരിച്ചു."}]}, {"surahNumber": 67, "surahNameArabic": "سُورَةُ المُلۡكِ", "surahNameMalayalam": "സൂറത്തുൽ മുൽക് (ആധിപത്യം)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ تَبَـٰرَكَ ٱلَّذِی بِیَدِهِ ٱلۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ\n", "jalalayn": "«تَبارَكَ» تَنَزَّهَ عَنْ صِفات المُحَدِّثِينَ «الَّذِي بِيَدِهِ» فِي تَصَرُّفه «المُلْك» السُّلْطان والقُدْرَة", "malayalam": "«സർവ്വാധിപത്യം ഏതൊരുവന്റെ കയ്യിലാണോ അവൻ എത്രയോ അനുഗ്രഹപൂർണ്ണനായിരിക്കുന്നു; അവൻ സർവ്വകാര്യങ്ങൾക്കും കഴിവുള്ളവനത്രെ».", "malayalamMatn": "ആധിപത്യം ഏതൊരുവന്‍റെ കയ്യിലാണോ അവന്‍ അനുഗ്രഹപൂര്‍ണ്ണനായിരിക്കുന്നു. അവന്‍ ഏതു കാര്യത്തിനും കഴിവുള്ളവനാകുന്നു."}, {"ayahNumber": 2, "quranText": "ٱلَّذِی خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَیَوٰةَ لِیَبۡلُوَكُمۡ أَیُّكُمۡ أَحۡسَنُ عَمَلࣰاۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡغَفُورُ\n", "jalalayn": "«الَّذِي خَلَقَ المَوْت» فِي الدُّنْيا «والحَياة» فِي الآخِرَة أوْ هُما فِي الدُّنْيا فالنُّطْفَة تَعْرِض لَها الحَياة وهِيَ ما بِهِ الإحْساس والمَوْت ضِدّها أوْ عَدَمها قَوْلانِ والخَلْق عَلى الثّانِي بِمَعْنى التَّقْدِير «لِيَبْلُوكُمْ» لِيَخْتَبِركُمْ فِي الحَياة «أيّكُمْ أحْسَن عَمَلًا» أطْوَع لِلَّهِ «وهُوَ العَزِيز» فِي انْتِقامه مِمَّنْ عَصاهُ «الغَفُور» لِمَن تابَ إلَيْهِ", "malayalam": "«നിങ്ങളിൽ ആരാണ് ഏറ്റവും നല്ല കർമ്മം പ്രവർത്തിക്കുന്നവൻ എന്ന് പരീക്ഷിക്കുവാൻ വേണ്ടി മരണത്തെയും ജീവിതത്തെയും സൃഷ്ടിച്ചവൻ അവനത്രെ; അവൻ പ്രതാപിയും ഏറെ പൊറുക്കുന്നവനുമാകുന്നു».", "malayalamMatn": "നിങ്ങളില്‍ ആരാണ് കൂടുതല്‍ നന്നായി പ്രവര്‍ത്തിക്കുന്നവന്‍ എന്ന് പരീക്ഷിക്കുവാന്‍ വേണ്ടി മരണവും ജീവിതവും സൃഷ്ടിച്ചവനാകുന്നു അവന്‍. അവന്‍ പ്രതാപിയും ഏറെ പൊറുക്കുന്നവനുമാകുന്നു."}, {"ayahNumber": 3, "quranText": "ٱلَّذِی خَلَقَ سَبۡعَ سَمَـٰوَ ٰ⁠تࣲ طِبَاقࣰاۖ مَّا تَرَىٰ فِی خَلۡقِ ٱلرَّحۡمَـٰنِ مِن تَفَـٰوُتࣲۖ فَٱرۡجِعِ ٱلۡبَصَرَ هَلۡ تَرَىٰ مِن فُطُورࣲ\n", "jalalayn": "«الَّذِي خَلَقَ سَبْع سَماوات طِباقًا» بَعْضها فَوْق بَعْض مِن غَيْر مُماسَّة «ما تَرى فِي خَلْق الرَّحْمانِ» لَهُنَّ أوْ لِغَيْرِهِنَّ «مِن تَفاوُت» تَبايُن وعَدَم تَناسُب «فارْجِعْ البَصَر» أعِدْهُ إلى السَّماء «هَلْ تَرى» فِيها «مِن فُطُور» صُدُوع وشُقُوق", "malayalam": "«അടുക്കടുക്കായി ഏഴ് ആകാശങ്ങളെ സൃഷ്ടിച്ചവൻ അവനത്രെ; പരമകാരുണികന്റെ സൃഷ്ടിപ്പിൽ യാതൊരു പൊരുത്തക്കേടും നീ കാണുകയില്ല; ആകയാൽ നീ വീണ്ടും ദൃഷ്ടി തിരിച്ചു നോക്കൂ, വല്ല വിള്ളലുകളും നീ കാണുന്നുണ്ടോ?».", "malayalamMatn": "ഏഴു ആകാശങ്ങളെ അടുക്കുകളായി സൃഷ്ടിച്ചവനാകുന്നു അവന്‍. പരമകാരുണികന്‍റെ സൃഷ്ടിപ്പില്‍ യാതൊരു ഏറ്റക്കുറവും നീ കാണുകയില്ല. എന്നാല്‍ നീ ദൃഷ്ടി ഒന്നുകൂടി തിരിച്ചു കൊണ്ട് വരൂ. വല്ല വിടവും നീ കാണുന്നുണ്ടോ?"}, {"ayahNumber": 4, "quranText": "ثُمَّ ٱرۡجِعِ ٱلۡبَصَرَ كَرَّتَیۡنِ یَنقَلِبۡ إِلَیۡكَ ٱلۡبَصَرُ خَاسِئࣰا وَهُوَ حَسِیرࣱ\n", "jalalayn": "«ثُمَّ ارْجِعْ البَصَر كَرَّتَيْنِ» كَرَّة بَعْد كَرَّة «يَنْقَلِب» يَرْجِع «إلَيْك البَصَر خاسِئًا» ذَلِيلًا لِعَدَمِ إدْراك خَلَل «وهُوَ حَسِير» مُنْقَطِع عَنْ رُؤْيَة خَلَل", "malayalam": "«പിന്നീട് നീ വീണ്ടും വീണ്ടും ദൃഷ്ടി പായിക്കുക; ആ ദൃഷ്ടി തളർന്നും പരാജയപ്പെട്ടും നിന്നിലേക്ക് തന്നെ തിരിച്ചുപോരും».", "malayalamMatn": "പിന്നീട് രണ്ടു തവണ നീ കണ്ണിനെ തിരിച്ച് കൊണ്ട് വരൂ. നിന്‍റെ അടുത്തേക്ക് ആ കണ്ണ് പരാജയപ്പെട്ട നിലയിലും പരവശമായികൊണ്ടും മടങ്ങി വരും."}, {"ayahNumber": 5, "quranText": "وَلَقَدۡ زَیَّنَّا ٱلسَّمَاۤءَ ٱلدُّنۡیَا بِمَصَـٰبِیحَ وَجَعَلۡنَـٰهَا رُجُومࣰا لِّلشَّیَـٰطِینِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِیرِ\n", "jalalayn": "«ولَقَدْ زَيَّنّا السَّماء الدُّنْيا» القُرْبى إلى الأَرْض «بِمَصابِيح» بِنُجُومٍ «وجَعَلْناها رُجُومًا» مَراجِم «لِلشَّياطِينِ» إذا اسْتَرِقُوا السَّمْع بِأَنْ يَنْفَصِل شِهاب عَنْ الكَوْكَب كالقَبَسِ يُؤْخَذ مِن النّار فَيَقْتُل الجِنِّيّ أوْ يَخْبِلهُ لا أنَّ الكَوْكَب يَزُول عَنْ مَكانه «وأَعْتَدْنا لَهُمْ عَذاب السَّعِير» النّار المُوقِدَة", "malayalam": "«ഏറ്റവും അടുത്ത ആകാശത്തെ നാം വിളക്കുകൾ (നക്ഷത്രങ്ങൾ) കൊണ്ട് അലങ്കരിച്ചിരിക്കുന്നു; അവയെ നാം പിശാചുക്കൾക്കെതിരെയുള്ള എറിയുപകരണങ്ങളാക്കുകയും ചെയ്തിരിക്കുന്നു; അവർക്കായി നാം ജ്വലിക്കുന്ന നരകാഗ്നിയുടെ ശിക്ഷ ഒരുക്കിവെക്കുകയും ചെയ്തിരിക്കുന്നു».", "malayalamMatn": "ഏറ്റവും അടുത്ത ആകാശത്തെ നാം ചില വിളക്കുകള്‍ കൊണ്ട് അലങ്കരിച്ചിരിക്കുന്നു. അവയെ നാം പിശാചുകളെ എറിഞ്ഞോടിക്കാനുള്ളവയുമാക്കിയിരിക്കുന്നു. അവര്‍ക്കു നാം ജ്വലിക്കുന്ന നരകശിക്ഷ ഒരുക്കിവെക്കുകയും ചെയ്തിരിക്കുന്നു."}, {"ayahNumber": 6, "quranText": "وَلِلَّذِینَ كَفَرُوا۟ بِرَبِّهِمۡ عَذَابُ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمَصِیرُ\n", "jalalayn": "«ولِلَّذِينَ كَفَرُوا بِرَبِّهِمْ عَذاب جَهَنَّم وبِئْسَ المَصِير» هِيَ", "malayalam": "«തങ്ങളുടെ രക്ഷിതാവിൽ അവിശ്വസിച്ചവർക്ക് നരകശിക്ഷയുണ്ട്; അത് എത്രയോ ചീത്തയായ തിരിച്ചുവരവ്!».", "malayalamMatn": "തങ്ങളുടെ രക്ഷിതാവില്‍ അവിശ്വസിച്ചവര്‍ക്കാണ് നരക ശിക്ഷയുള്ളത്‌. തിരിച്ചെത്തുന്ന ആ സ്ഥലം വളരെ ചീത്ത തന്നെ."}, {"ayahNumber": 7, "quranText": "إِذَاۤ أُلۡقُوا۟ فِیهَا سَمِعُوا۟ لَهَا شَهِیقࣰا وَهِیَ تَفُورُ\n", "jalalayn": "«إذا أُلْقُوا فِيها سَمِعُوا لَها شَهِيقًا» صَوْتًا مُنْكَرًا كَصَوْتِ الحِمار «وهِيَ تَفُور» تَغْلِي", "malayalam": "«അതിൽ അവർ എറിയപ്പെടുമ്പോൾ, അത് തിളച്ചുപൊങ്ങിക്കൊണ്ടിരിക്കെ കഴുതയുടെ കരച്ചിൽ പോലെയുള്ള ഒരു ഭീകരശബ്ദം അവർ അതിൽ നിന്ന് കേൾക്കും».", "malayalamMatn": "അവര്‍ അതില്‍ (നരകത്തില്‍) എറിയപ്പെട്ടാല്‍ അതിന്നവര്‍ ഒരു ഗര്‍ജ്ജനം കേള്‍ക്കുന്നതാണ്‌. അത് തിളച്ചു മറിഞ്ഞു കൊണ്ടിരിക്കുകയും ചെയ്യും."}, {"ayahNumber": 8, "quranText": "تَكَادُ تَمَیَّزُ مِنَ ٱلۡغَیۡظِۖ كُلَّمَاۤ أُلۡقِیَ فِیهَا فَوۡجࣱ سَأَلَهُمۡ خَزَنَتُهَاۤ أَلَمۡ یَأۡتِكُمۡ نَذِیرࣱ\n", "jalalayn": "«تَكاد تَمَيَّز» وقُرِئَ تَتَمَيَّز عَلى الأَصْل تَتَقَطَّع «مِن الغَيْظ» غَضَبًا عَلى الكافِر «كُلَّما أُلْقِيَ فِيها فَوْج» جَماعَة مِنهُمْ «سَأَلَهُمْ خَزَنَتها» سُؤال تَوْبِيخ «ألَمْ يَأْتِكُمْ نَذِير» رَسُول يُنْذِركُمْ عَذاب اللَّه تَعالى", "malayalam": "«കോപത്താൽ അത് പൊട്ടിപ്പിളരാറാകും; ഓരോ സംഘവും അതിലേക്ക് എറിയപ്പെടുമ്പോഴെല്ലാം അതിന്റെ കാവൽക്കാർ അവരോട് ചോദിക്കും: നിങ്ങളുടെ അടുക്കൽ ഒരു താക്കീതുകാരൻ വന്നിരുന്നില്ലയോ?».", "malayalamMatn": "കോപം നിമിത്തം അത് പൊട്ടിപ്പിളര്‍ന്ന് പോകുമാറാകും. അതില്‍ (നരകത്തില്‍) ഓരോ സംഘവും എറിയപ്പെടുമ്പോഴൊക്കെ അതിന്‍റെ കാവല്‍ക്കാര്‍ അവരോട് ചോദിക്കും. നിങ്ങളുടെ അടുത്ത് മുന്നറിയിപ്പുകാരന്‍ വന്നിരുന്നില്ലേ?"}, {"ayahNumber": 9, "quranText": "قَالُوا۟ بَلَىٰ قَدۡ جَاۤءَنَا نَذِیرࣱ فَكَذَّبۡنَا وَقُلۡنَا مَا نَزَّلَ ٱللَّهُ مِن شَیۡءٍ إِنۡ أَنتُمۡ إِلَّا فِی ضَلَـٰلࣲ كَبِیرࣲ\n", "jalalayn": "«قالُوا بَلى قَدْ جاءَنا نَذِير فَكَذَّبْنا وقُلْنا ما نَزَّلَ اللَّه مِن شَيْء إنْ» ما «أنْتُمْ إلّا فِي ضَلال كَبِير» يَحْتَمِل أنْ يَكُون مِن كَلام المَلائِكَة لِلْكُفّارِ حِين أُخْبِرُوا بِالتَّكْذِيبِ ويَحْتَمِل أنْ يَكُون مِن كَلام الكُفّار لِلنَّذْرِ", "malayalam": "«അവർ പറയും: അതെ, തീർച്ചയായും ഞങ്ങളുടെ അടുക്കൽ താക്കീതുകാരൻ വന്നിരുന്നു; എന്നാൽ ഞങ്ങൾ നിഷേധിച്ചു തള്ളുകയും അല്ലാഹു യാതൊന്നും അവതരിപ്പിച്ചിട്ടില്ല, നിങ്ങൾ വലിയ ദുർമാർഗ്ഗത്തിൽ തന്നെയാണ് എന്ന് പറയുകയുമാണ് ചെയ്തത്!».", "malayalamMatn": "അവര്‍ പറയും: അതെ ഞങ്ങള്‍ക്ക് മുന്നറിയിപ്പുകാരന്‍ വന്നിരുന്നു. അപ്പോള്‍ ഞങ്ങള്‍ നിഷേധിച്ചു തള്ളുകയും അല്ലാഹു യാതൊന്നും ഇറക്കിയിട്ടില്ല. നിങ്ങള്‍ വലിയ വഴികേടില്‍ തന്നെയാകുന്നു എന്ന് ഞങ്ങള്‍ പറയുകയുമാണ് ചെയ്തത്‌."}, {"ayahNumber": 10, "quranText": "وَقَالُوا۟ لَوۡ كُنَّا نَسۡمَعُ أَوۡ نَعۡقِلُ مَا كُنَّا فِیۤ أَصۡحَـٰبِ ٱلسَّعِیرِ\n", "jalalayn": "«وقالُوا لَوْ كُنّا نَسْمَع» أيْ سَماع تَفَهُّم «أوْ نَعْقِل» أيْ عَقْل تَفَكُّر", "malayalam": "«അവർ പറയും: ഞങ്ങൾ കേൾക്കുകയോ ചിന്തിക്കുകയോ ചെയ്തിരുന്നുവെങ്കിൽ ഞങ്ങൾ ജ്വലിക്കുന്ന നരകാവകാശികളിൽ പെട്ടവരാകുമായിരുന്നില്ല!».", "malayalamMatn": "ഞങ്ങള്‍ കേള്‍ക്കുകയോ ചിന്തിക്കുകയോ ചെയ്തിരുന്നെങ്കില്‍ ഞങ്ങള്‍ ജ്വലിക്കുന്ന നരകാഗ്നിയുടെ അവകാശികളുടെ കൂട്ടത്തിലാകുമായിരുന്നില്ല എന്നും അവര്‍ പറയും."}, {"ayahNumber": 11, "quranText": "فَٱعۡتَرَفُوا۟ بِذَنۢبِهِمۡ فَسُحۡقࣰا لِّأَصۡحَـٰبِ ٱلسَّعِیرِ\n", "jalalayn": "«فاعْتَرَفُوا» حَيْثُ لا يَنْفَع الِاعْتِراف «بِذَنْبِهِمْ» وهُوَ تَكْذِيب النَّذْر «فَسُحْقًا» بِسُكُونِ الحاء وضَمّها «لِأَصْحابِ السَّعِير» فَبُعْدًا لَهُمْ عَنْ رَحْمَة اللَّه", "malayalam": "«അങ്ങനെ അവർ തങ്ങളുടെ പാപങ്ങൾ സ്വയം ഏറ്റുപറയും; ആകയാൽ ജ്വലിക്കുന്ന നരകാവകാശികൾക്ക് ശാപം!».", "malayalamMatn": "അങ്ങനെ അവര്‍ തങ്ങളുടെ കുറ്റം ഏറ്റുപറയും. അപ്പോള്‍ നരകാഗ്നിയുടെ ആള്‍ക്കാര്‍ക്കു ശാപം."}, {"ayahNumber": 12, "quranText": "إِنَّ ٱلَّذِینَ یَخۡشَوۡنَ رَبَّهُم بِٱلۡغَیۡبِ لَهُم مَّغۡفِرَةࣱ وَأَجۡرࣱ كَبِیرࣱ\n", "jalalayn": "«إنّ الَّذِينَ يَخْشَوْنَ رَبّهمْ» يَخافُونَهُ «بِالغَيْبِ» فِي غَيْبَتهمْ عَنْ أعْيُن النّاس فَيُطِيعُونَهُ سِرًّا فَيَكُون عَلانِيَة أوْلى «لَهُمْ مَغْفِرَة وأَجْر كَبِير» أيْ الجَنَّة", "malayalam": "«തങ്ങളുടെ രക്ഷിതാവിനെ അദൃശ്യമായ നിലയിൽ ഭയപ്പെടുന്നവരാരോ തീർച്ചയായും അവർക്ക് പാപമോചനവും വലിയ പ്രതിഫലവുമുണ്ട്».", "malayalamMatn": "തീര്‍ച്ചയായും തങ്ങളുടെ രക്ഷിതാവിനെ അദൃശ്യനിലയില്‍ ഭയപ്പെടുന്നവരാരോ അവര്‍ക്ക് പാപമോചനവും വലിയ പ്രതിഫലവുമുണ്ട്‌."}, {"ayahNumber": 13, "quranText": "وَأَسِرُّوا۟ قَوۡلَكُمۡ أَوِ ٱجۡهَرُوا۟ بِهِۦۤۖ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ\n", "jalalayn": "«وأَسِرُّوا» أيّها النّاس «قَوْلكُمْ أوْ اجْهَرُوا بِهِ إنّهُ» تَعالى «عَلِيم بِذاتِ الصُّدُور» بِما فِيها فَكَيْفَ بِما نَطَقْتُمْ بِهِ وسَبَب نُزُول ذَلِكَ أنَّ المُشْرِكِينَ قالَ بَعْضهمْ لِبَعْضٍ: أسِرُّوا قَوْلكُمْ لا يَسْمَعكُمْ إلَه مُحَمَّد", "malayalam": "«നിങ്ങൾ നിങ്ങളുടെ വാക്ക് രഹസ്യമാക്കുകയോ പരസ്യമാക്കുകയോ ചെയ്യുക (മുശ്‌രിക്കുകൾ നബി കേൾക്കാതിരിക്കാൻ ശബ്ദം താഴ്ത്തി സംസാരിക്കാമെന്ന് പറഞ്ഞ പശ്ചാത്തലത്തിൽ ഇത് അവതരിച്ചു); തീർച്ചയായും അവൻ ഹൃദയങ്ങളിലുള്ളതിനെക്കുറിച്ച് സൂക്ഷ്മമായി അറിയുന്നവനത്രെ».", "malayalamMatn": "നിങ്ങളുടെ വാക്ക് നിങ്ങള്‍ രഹസ്യമാക്കുക. അല്ലെങ്കില്‍ പരസ്യമാക്കിക്കൊള്ളുക. തീര്‍ച്ചയായും അവന്‍ (അല്ലാഹു) ഹൃദയങ്ങളിലുള്ളത് അറിയുന്നവനാകുന്നു."}, {"ayahNumber": 14, "quranText": "أَلَا یَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِیفُ ٱلۡخَبِیرُ\n", "jalalayn": "«ألا يَعْلَم مَن خَلَقَ» ما تُسِرُّونَ أيْ أيَنْتَفِي عِلْمه بِذَلِكَ «وهُوَ اللَّطِيف» فِي عِلْمه «الخَبِير» فِيهِ", "malayalam": "«സൃഷ്ടിച്ചവൻ അറിയുകയില്ലയോ? അവൻ അതിസൂക്ഷ്മജ്ഞാനിയും സർവ്വകാര്യങ്ങളും അറിയുന്നവനുമാകുന്നു».", "malayalamMatn": "സൃഷ്ടിച്ചുണ്ടാക്കിയവന്‍ (എല്ലാം) അറിയുകയില്ലേ? അവന്‍ നിഗൂഢരഹസ്യങ്ങള്‍ അറിയുന്നവനും സൂക്ഷ്മജ്ഞാനിയുമാകുന്നു."}, {"ayahNumber": 15, "quranText": "هُوَ ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولࣰا فَٱمۡشُوا۟ فِی مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزۡقِهِۦۖ وَإِلَیۡهِ ٱلنُّشُورُ\n", "jalalayn": "«هُوَ الَّذِي جَعَلَ لَكُمْ الأَرْض ذَلُولًا» سَهْلَة لِلْمَشْيِ فِيها «فامْشُوا فِي مَناكِبها» جَوانِبها «وكُلُوا مِن رِزْقه» المَخْلُوق لِأَجَلِكُمْ «وإلَيْهِ النُّشُور» مِن القُبُور لِلْجَزاءِ", "malayalam": "«ഭൂമിയെ നിങ്ങൾക്ക് മെരുക്കിത്തന്നവൻ അവനത്രെ; അതിനാൽ അതിന്റെ വഴികളിലൂടെ നിങ്ങൾ സഞ്ചരിക്കുകയും അവന്റെ ഉപജീവനത്തിൽ നിന്ന് ഭക്ഷിക്കുകയും ചെയ്യുവിൻ; അവങ്കലേക്ക് തന്നെയാണ് പുനരുത്ഥാനം».", "malayalamMatn": "അവനാകുന്നു നിങ്ങള്‍ക്ക് വേണ്ടി ഭൂമിയെ വിധേയമാക്കി തന്നവന്‍. അതിനാല്‍ അതിന്‍റെ ചുമലുകളിലൂടെ നിങ്ങള്‍ നടക്കുകയും അവന്‍റെ ഉപജീവനത്തില്‍ നിന്ന് ഭക്ഷിക്കുകയും ചെയ്തു കൊള്ളുക. അവങ്കലേക്ക് തന്നെയാണ് ഉയിര്‍ത്തെഴുന്നേല്‍പ്‌."}, {"ayahNumber": 16, "quranText": "ءَأَمِنتُم مَّن فِی ٱلسَّمَاۤءِ أَن یَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِیَ تَمُورُ\n", "jalalayn": "«أأَمِنتُمْ» بِتَحْقِيقِ الهَمْزَتَيْنِ وتَسْهِيل الثّانِيَة وإدْخال ألِف بَيْنهما وبَيْن الأُخْرى وتَرْكه وإبْدالها ألِفًا «مِن فِي السَّماء» سُلْطانه وقُدْرَته «أنْ يَخْسِف» بَدَل مِن مَن «بِكُمْ الأَرْض فَإذا هِيَ تَمُور» تَتَحَرَّك بِكُمْ وتَرْتَفِع فَوْقكُمْ", "malayalam": "«ആകാശത്തിലുള്ളവൻ നിങ്ങളെ ഭൂമിയിൽ ആഴ്ത്തിക്കളയുന്നതിനെക്കുറിച്ച് നിങ്ങൾ നിർഭയരായിരിക്കുകയാണോ? അപ്പോൾ അത് ഇളകിമറിഞ്ഞുകൊണ്ടിരിക്കും!».", "malayalamMatn": "ആകാശത്തുള്ളവന്‍ നിങ്ങളെ ഭൂമിയില്‍ ആഴ്ത്തിക്കളയുന്നതിനെപ്പറ്റി നിങ്ങള്‍ നിര്‍ഭയരായിരിക്കുകയാണോ? അപ്പോള്‍ അത് (ഭൂമി) ഇളകിമറിഞ്ഞു കൊണ്ടിരിക്കും."}, {"ayahNumber": 17, "quranText": "أَمۡ أَمِنتُم مَّن فِی ٱلسَّمَاۤءِ أَن یُرۡسِلَ عَلَیۡكُمۡ حَاصِبࣰاۖ فَسَتَعۡلَمُونَ كَیۡفَ نَذِیرِ\n", "jalalayn": "«أمْ أمِنتُمْ مَن فِي السَّماء أنْ يُرْسِل» بَدَل مِن مَن «عَلَيْكُمْ حاصِبًا» رِيحًا تَرْمِيكُمْ بِالحَصْباءِ «فَسَتَعْلَمُونَ» عِنْد مُعايَنَة العَذاب «كَيْفَ نَذِير» إنْذارِي بِالعَذابِ أيْ أنَّهُ حَقّ", "malayalam": "«അതല്ല, ആകാശത്തിലുള്ളവൻ നിങ്ങളുടെ നേരെ ചരൽക്കാറ്റ് അയക്കുന്നതിനെപ്പറ്റി നിങ്ങൾ നിർഭയരായിരിക്കുകയാണോ? എന്റെ താക്കീത് എങ്ങനെയുണ്ടെന്ന് വഴിയെ നിങ്ങൾ അറിഞ്ഞുകൊള്ളും!».", "malayalamMatn": "അതല്ല, ആകാശത്തുള്ളവന്‍ നിങ്ങളുടെ നേരെ ഒരു ചരല്‍ വര്‍ഷം അയക്കുന്നതിനെപ്പറ്റി നിങ്ങള്‍ നിര്‍ഭയരായിരിക്കുകയാണോ? എന്‍റെ താക്കീത് എങ്ങനെയുണ്ടെന്ന് നിങ്ങള്‍ വഴിയെ അറിഞ്ഞു കൊള്ളും."}, {"ayahNumber": 18, "quranText": "وَلَقَدۡ كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ فَكَیۡفَ كَانَ نَكِیرِ\n", "jalalayn": "«ولَقَدْ كَذَّبَ الَّذِينَ مِن قَبْلهمْ» مِن الأُمَم «فَكَيْفَ كانَ نَكِير» فَكَيْفَ كانَ إنْكارِي عَلَيْهِمْ بِالتَّكْذِيبِ عِنْد إهْلاكهمْ أيْ أنَّهُ حَقّ", "malayalam": "«തീർച്ചയായും ഇവർക്ക് മുമ്പുള്ളവരും നിഷേധിച്ചു കളഞ്ഞിട്ടുണ്ട്; അപ്പോൾ എന്റെ രോഷം എങ്ങനെയുണ്ടായിരുന്നു?».", "malayalamMatn": "തീര്‍ച്ചയായും അവര്‍ക്ക് മുമ്പുള്ളവരും നിഷേധിച്ചു തള്ളിയിട്ടുണ്ട്‌. അപ്പോള്‍ എന്‍റെ പ്രതിഷേധം എങ്ങനെയായിരുന്നു."}, {"ayahNumber": 19, "quranText": "أَوَلَمۡ یَرَوۡا۟ إِلَى ٱلطَّیۡرِ فَوۡقَهُمۡ صَـٰۤفَّـٰتࣲ وَیَقۡبِضۡنَۚ مَا یُمۡسِكُهُنَّ إِلَّا ٱلرَّحۡمَـٰنُۚ إِنَّهُۥ بِكُلِّ شَیۡءِۭ بَصِیرٌ\n", "jalalayn": "«أوَلَمْ يَرَوْا» يَنْظُرُوا «إلى الطَّيْر فَوْقهمْ» فِي الهَواء «صافّات» باسِطات أجْنِحَتهنَّ «ويَقْبِضْنَ» أجْنِحَتهنَّ بَعْد البَسْط أيْ وقابِضات «ما يُمْسِكهُنَّ» عَنْ الوُقُوع فِي حال البَسْط والقَبْض «إلّا الرَّحْمانِ» بِقُدْرَتِهِ «إنّهُ بِكُلِّ شَيْء بَصِير» المَعْنى: ألَمْ يَسْتَدِلُّوا بِثُبُوتِ الطَّيْر فِي الهَواء عَلى قُدْرَتنا أنْ نَفْعَل بِهِمْ ما تَقَدَّمَ وغَيْره مِن العَذاب", "malayalam": "«തങ്ങൾക്ക് മീതെ ചിറകുകൾ വിടർത്തിയും മടക്കിയും പറക്കുന്ന പക്ഷികളെ അവർ കണ്ടില്ലയോ? പരമകാരുണികനല്ലാതെ അവയെ പിടിച്ചുനിർത്തുന്നില്ല; തീർച്ചയായും അവൻ സർവ്വകാര്യങ്ങളും കണ്ടറിയുന്നവനത്രെ».", "malayalamMatn": "അവര്‍ക്കു മുകളില്‍ ചിറക് വിടര്‍ത്തിക്കൊണ്ടും ചിറകു കൂട്ടിപ്പിടിച്ചു കൊണ്ടും പറക്കുന്ന പക്ഷികളുടെ നേര്‍ക്ക് അവര്‍ നോക്കിയില്ലേ? പരമകാരുണികനല്ലാതെ (മറ്റാരും) അവയെ താങ്ങി നിറുത്തുന്നില്ല. തീര്‍ച്ചയായും അവന്‍ എല്ലാകാര്യവും കണ്ടറിയുന്നവനാകുന്നു."}, {"ayahNumber": 20, "quranText": "أَمَّنۡ هَـٰذَا ٱلَّذِی هُوَ جُندࣱ لَّكُمۡ یَنصُرُكُم مِّن دُونِ ٱلرَّحۡمَـٰنِۚ إِنِ ٱلۡكَـٰفِرُونَ إِلَّا فِی غُرُورٍ\n", "jalalayn": "«أمَّنْ» مُبْتَدَأ «هَذا» خَبَره «الَّذِي» بَدَل مِن هَذا «هُوَ جُنْد» أعْوان «لَكُمْ» صِلَة الَّذِي «يَنْصُركُمْ» صِفَة الجُنْد «مِن دُون الرَّحْمانِ» أيْ غَيْره يَدْفَع عَنْكُمْ عَذابه أيْ لا ناصِر لَكُمْ «إنْ» ما «الكافِرُونَ إلّا فِي غُرُور» غَرَّهُمْ الشَّيْطان بِأَنَّ العَذاب لا يَنْزِل بِهِمْ", "malayalam": "«പരമകാരുണികന് പുറമെ നിങ്ങളെ സഹായിക്കാനുള്ള നിങ്ങളുടെ സൈന്യം ഏതാണ്? അവിശ്വാസികൾ വഞ്ചനയിൽ മാത്രമാകുന്നു».", "malayalamMatn": "അതല്ല പരമകാരുണികന് പുറമെ നിങ്ങളെ സഹായിക്കുവാന്‍ ഒരു പട്ടാളമായിട്ടുള്ളവന്‍ ആരുണ്ട്‌? സത്യനിഷേധികള്‍ വഞ്ചനയില്‍ അകപ്പെട്ടിരിക്കുക മാത്രമാകുന്നു."}, {"ayahNumber": 21, "quranText": "أَمَّنۡ هَـٰذَا ٱلَّذِی یَرۡزُقُكُمۡ إِنۡ أَمۡسَكَ رِزۡقَهُۥۚ بَل لَّجُّوا۟ فِی عُتُوࣲّ وَنُفُورٍ\n", "jalalayn": "«أمَّنْ هَذا الَّذِي يَرْزُقكُمْ إنْ أمْسَكَ» الرَّحْمَن «رِزْقه» أيْ المَطَر عَنْكُمْ وجَواب الشَّرْط مَحْذُوف دَلَّ عَلَيْهِ ما قَبْله أيْ فَمَن يَرْزُقكُمْ أيْ لا رازِق لَكُمْ غَيْره «بَلْ لَجُّوا» تَمادَوْا «فِي عُتُوّ» تَكَبُّر «ونُفُور» تَباعُد فِي الحَقّ", "malayalam": "«അവൻ തന്റെ ഉപജീവനം തടഞ്ഞുവെച്ചാൽ നിങ്ങൾക്ക് ഉപജീവനം നൽകുന്നവൻ ആരാണുള്ളത്? അല്ല, ധിക്കാരത്തിലും വിദ്വേഷത്തിലും അവർ ഉറച്ചുനിൽക്കുകയാണ് ചെയ്യുന്നത്».", "malayalamMatn": "അതല്ലെങ്കില്‍ അല്ലാഹു തന്‍റെ ഉപജീവനം നിര്‍ത്തിവെച്ചാല്‍ നിങ്ങള്‍ക്ക് ഉപജീവനം നല്‍കുന്നവനായി ആരുണ്ട്‌? എങ്കിലും അവര്‍ ധിക്കാരത്തിലും വെറുപ്പിലും മുഴുകിയിരിക്കയാകുന്നു."}, {"ayahNumber": 22, "quranText": "أَفَمَن یَمۡشِی مُكِبًّا عَلَىٰ وَجۡهِهِۦۤ أَهۡدَىٰۤ أَمَّن یَمۡشِی سَوِیًّا عَلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ\n", "jalalayn": "«أفَمَن يَمْشِي مُكِبًّا» واقِعًا «عَلى وجْهه أهْدى أمَّنْ يَمْشِي سَوِيًّا» مُعْتَدِلًا «عَلى صِراط» طَرِيق «مُسْتَقِيم» وخَبَر مِن الثّانِيَة مَحْذُوف دَلَّ عَلَيْهِ خَبَر الأُولى أيْ أهْدى والمَثَل فِي المُؤْمِن والكافِر أيّهما عَلى هُدى", "malayalam": "«മുഖം നിലത്തു കുത്തി നടക്കുന്നവനാണോ നേർവഴി പ്രാപിച്ചവൻ, അതോ നേരായ പാതയിലൂടെ നിവർന്നു നടക്കുന്നവനാണോ?».", "malayalamMatn": "അപ്പോള്‍, മുഖം നിലത്തു കുത്തിക്കൊണ്ട് നടക്കുന്നവനാണോ സന്‍മാര്‍ഗം പ്രാപിക്കുന്നവന്‍? അതല്ല നേരെയുള്ള പാതയിലൂടെ ശരിക്ക് നടക്കുന്നവനോ?"}, {"ayahNumber": 23, "quranText": "قُلۡ هُوَ ٱلَّذِیۤ أَنشَأَكُمۡ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِیلࣰا مَّا تَشۡكُرُونَ\n", "jalalayn": "«قُلْ هُوَ الَّذِي أنْشَأَكُمْ» خَلَقَكُمْ «وجَعَلَ لَكُمْ السَّمْع والأَبْصار والأَفْئِدَة» القُلُوب «قَلِيلًا ما تَشْكُرُونَ» ما مَزِيدَة والجُمْلَة مُسْتَأْنَفَة مُخْبِرَة بِقِلَّةِ شُكْرهمْ جِدًّا عَلى هَذِهِ النِّعَم", "malayalam": "«പറയുക: നിങ്ങളെ സൃഷ്ടിച്ചുണ്ടാക്കുകയും നിങ്ങൾക്ക് കേൾവിയും കാഴ്ചകളും ഹൃദയങ്ങളും ഉണ്ടാക്കിത്തരികയും ചെയ്തവൻ അവനത്രെ; വളരെ കുറഞ്ഞ തോതിൽ മാത്രമേ നിങ്ങൾ നന്ദി കാണിക്കുന്നുള്ളൂ!».", "malayalamMatn": "പറയുക: അവനാണ് നിങ്ങളെ സൃഷ്ടിച്ചുണ്ടാക്കുകയും നിങ്ങള്‍ക്ക് കേള്‍വിയും കാഴ്ചകളും ഹൃദയങ്ങളും ഏര്‍പെടുത്തിത്തരികയും ചെയ്തവന്‍. കുറച്ചു മാത്രമേ നിങ്ങള്‍ നന്ദികാണിക്കുന്നുള്ളൂ."}, {"ayahNumber": 24, "quranText": "قُلۡ هُوَ ٱلَّذِی ذَرَأَكُمۡ فِی ٱلۡأَرۡضِ وَإِلَیۡهِ تُحۡشَرُونَ\n", "jalalayn": "«قُلْ هُوَ الَّذِي ذَرَأَكُمْ» خَلَقَكُمْ «فِي الأَرْض وإلَيْهِ تُحْشَرُونَ» لِلْحِسابِ", "malayalam": "«പറയുക: അവനാണ് ഭൂമിയിൽ നിങ്ങളെ പെരുപ്പിച്ചത്; അവങ്കലേക്ക് തന്നെയാണ് നിങ്ങൾ ഒരുമിച്ചുകൂട്ടപ്പെടുന്നത്».", "malayalamMatn": "പറയുക: അവനാണ് നിങ്ങളെ ഭൂമിയില്‍ സൃഷ്ടിച്ച് വളര്‍ത്തിയവന്‍. അവങ്കലേക്കാണ് നിങ്ങള്‍ ഒരുമിച്ചുകൂട്ടപ്പെടുന്നത്‌."}, {"ayahNumber": 25, "quranText": "وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ\n", "jalalayn": "«ويَقُولُونَ» لِلْمُؤْمِنِينَ «مَتى هَذا الوَعْد» وعْد الحَشْر «إنْ كُنْتُمْ صادِقِينَ» فِيهِ", "malayalam": "«അവർ ചോദിക്കുന്നു: നിങ്ങൾ സത്യവാന്മാരാണെങ്കിൽ ഈ വാഗ്ദത്തം എപ്പോഴാണ് പുലരുക?».", "malayalamMatn": "അവര്‍ പറയുന്നു: എപ്പോഴാണ് ഈ വാഗ്ദാനം (പുലരുന്നത്‌?) നിങ്ങള്‍ സത്യവാന്‍മാരാണെങ്കില്‍ (അതൊന്ന് പറഞ്ഞുതരൂ)"}, {"ayahNumber": 26, "quranText": "قُلۡ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَإِنَّمَاۤ أَنَا۠ نَذِیرࣱ مُّبِینࣱ\n", "jalalayn": "«قُلْ إنّما العِلْم» بِمَجِيئِهِ «عِنْد اللَّه وإنَّما أنا نَذِير مُبِين» بَيِّن الإنْذار", "malayalam": "«പറയുക: ആ അറിവ് അല്ലാഹുവിങ്കൽ മാത്രമാകുന്നു; ഞാൻ വ്യക്തമായ ഒരു താക്കീതുകാരൻ മാത്രമത്രെ».", "malayalamMatn": "പറയുക: ആ അറിവ് അല്ലാഹുവിന്‍റെ പക്കല്‍ മാത്രമാകുന്നു. ഞാന്‍ വ്യക്തമായ താക്കീതുകാരന്‍ മാത്രമാകുന്നു."}, {"ayahNumber": 27, "quranText": "فَلَمَّا رَأَوۡهُ زُلۡفَةࣰ سِیۤـَٔتۡ وُجُوهُ ٱلَّذِینَ كَفَرُوا۟ وَقِیلَ هَـٰذَا ٱلَّذِی كُنتُم بِهِۦ تَدَّعُونَ\n", "jalalayn": "«فَلَمّا رَأَوْهُ» أيْ العَذاب بَعْد الحَشْر «زُلْفَة» قَرِيبًا «سِيئَتْ» اسْوَدَّتْ «وُجُوه الَّذِينَ كَفَرُوا وقِيلَ» أيْ قالَ الخَزَنَة لَهُمْ «هَذا» أيْ العَذاب «الَّذِي كُنْتُمْ بِهِ» بِإنْذارِهِ «تَدَّعُونَ» أنَّكُمْ لا تُبْعَثُونَ وهَذِهِ حِكايَة حال تَأْتِي عَبَّرَ عَنْها بِطَرِيقِ المُضِيّ لِتَحَقُّقِ وُقُوعها", "malayalam": "«അങ്ങനെ അത് ആസന്നമായതായി അവർ കാണുമ്പോൾ സത്യനിഷേധികളുടെ മുഖങ്ങൾ വികൃതമായിത്തീരും; നിങ്ങൾ കൊതിച്ചിരുന്ന കാര്യം ഇതാകുന്നു എന്ന് അവരോട് പറയപ്പെടുകയും ചെയ്യും».", "malayalamMatn": "അത് (താക്കീത് നല്‍കപ്പെട്ട കാര്യം) സമീപസ്ഥമായി അവര്‍ കാണുമ്പോള്‍ സത്യനിഷേധികളുടെ മുഖങ്ങള്‍ക്ക് മ്ലാനത ബാധിക്കുന്നതാണ്‌. നിങ്ങള്‍ ഏതൊന്നിനെപ്പറ്റി വാദിച്ച് കൊണ്ടിരുന്നുവോ അതാകുന്നു ഇത് എന്ന് (അവരോട്‌) പറയപ്പെടുകയും ചെയ്യും."}, {"ayahNumber": 28, "quranText": "قُلۡ أَرَءَیۡتُمۡ إِنۡ أَهۡلَكَنِیَ ٱللَّهُ وَمَن مَّعِیَ أَوۡ رَحِمَنَا فَمَن یُجِیرُ ٱلۡكَـٰفِرِینَ مِنۡ عَذَابٍ أَلِیمࣲ\n", "jalalayn": "«قُلْ أرَأَيْتُمْ إنْ أهْلَكَنِيَ اللَّه ومَن مَعِيَ» مِن المُؤْمِنِينَ بِعَذابِهِ كَما تُقْصَدُونَ «أوْ رَحِمَنا» فَلَمْ يُعَذِّبنا «فَمَن يُجِير الكافِرِينَ مِن عَذاب ألِيم» أيْ لا مُجِير لَهُمْ مِنهُ", "malayalam": "«പറയുക: എന്നെയും എന്റെ കൂടെയുള്ളവരെയും അല്ലാഹു നശിപ്പിക്കുകയോ ഞങ്ങളോട് കരുണ കാണിക്കുകയോ ചെയ്യട്ടെ, എങ്കിൽ വേദനാജനകമായ ശിക്ഷയിൽ നിന്ന് അവിശ്വാസികളെ രക്ഷിക്കാൻ ആരുണ്ട് എന്ന് നിങ്ങൾ ചിന്തിച്ചിട്ടുണ്ടോ?».", "malayalamMatn": "പറയുക: നിങ്ങള്‍ ചിന്തിച്ച് നോക്കിയിട്ടുണ്ടോ? എന്നെയും എന്നോടൊപ്പമുള്ളവരെയും അല്ലാഹു നശിപ്പിക്കുകയോ അല്ലെങ്കില്‍ ഞങ്ങളോടവന്‍ കരുണ കാണിക്കുകയോ ചെയ്താല്‍ വേദനയേറിയ ശിക്ഷയില്‍ നിന്ന് സത്യനിഷേധികളെ രക്ഷിക്കാനാരുണ്ട്‌?"}, {"ayahNumber": 29, "quranText": "قُلۡ هُوَ ٱلرَّحۡمَـٰنُ ءَامَنَّا بِهِۦ وَعَلَیۡهِ تَوَكَّلۡنَاۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِی ضَلَـٰلࣲ مُّبِینࣲ\n", "jalalayn": "«قُلْ هُوَ الرَّحْمانِ آمَنّا بِهِ وعَلَيْهِ تَوَكَّلْنا فَسَتَعْلَمُونَ» بِالتّاءِ والياء عِنْد مُعايَنَة العَذاب «مَن هُوَ فِي ضَلال مُبِين» بَيِّن أنَحْنُ أمْ أنْتُمْ أمْ هُمْ", "malayalam": "«പറയുക: അവൻ പരമകാരുണികനാകുന്നു; അവനിൽ ഞങ്ങൾ വിശ്വസിക്കുകയും അവനിൽ ഞങ്ങൾ ഭരമേൽപിക്കുകയും ചെയ്തിരിക്കുന്നു; വ്യക്തമായ ദുർമാർഗ്ഗത്തിൽ ആരാണെന്ന് വഴിയെ നിങ്ങൾ അറിഞ്ഞുകൊള്ളും».", "malayalamMatn": "പറയുക: അവനാകുന്നു പരമകാരുണികന്‍. അവനില്‍ ഞങ്ങള്‍ വിശ്വസിച്ചിരിക്കുന്നു. അവന്‍റെ മേല്‍ ഞങ്ങള്‍ ഭരമേല്‍പിക്കുകയും ചെയ്തിരിക്കുന്നു. എന്നാല്‍ വഴിയെ നിങ്ങള്‍ക്കറിയാം; ആരാണ് വ്യക്തമായ വഴികേടിലെന്ന്‌."}, {"ayahNumber": 30, "quranText": "قُلۡ أَرَءَیۡتُمۡ إِنۡ أَصۡبَحَ مَاۤؤُكُمۡ غَوۡرࣰا فَمَن یَأۡتِیكُم بِمَاۤءࣲ مَّعِینِۭ\n", "jalalayn": "«قُلْ أرَأَيْتُمْ إنْ أصْبَح ماؤُكُمْ غَوْرًا» غائِرًا فِي الأَرْض «فَمَن يَأْتِيكُمْ بِماءٍ مَعِين» جارٍ تَنالهُ الأَيْدِي والدِّلاء كَمائِكُمْ أيْ لا يَأْتِي بِهِ إلّا اللَّه تَعالى فَكَيْفَ تُنْكِرُونَ أنْ يَبْعَثكُمْ ؟ ويُسْتَحَبّ أنْ يَقُول القارِئ عَقِب «مَعِين»: اللَّه رَبّ العالَمِينَ كَما ورَدَ فِي الحَدِيث وتُلِيَتْ هَذِهِ الآيَة عِنْد بَعْض المُتَجَبِّرِينَ فَقالَ: تَأْتِي بِهِ الفُؤُوس والمَعاوِل فَذَهَبَ ماء عَيْنه وعَمِيَ نَعُوذ بِاللَّهِ مِن الجَراءَة عَلى اللَّه وعَلى آياته", "malayalam": "«പറയുക: നിങ്ങളുടെ വെള്ളം ഭൂമിയിലേക്ക് വറ്റിപ്പോയാൽ ആരാണ് നിങ്ങൾക്ക് ഒഴുകുന്ന ശുദ്ധജലം കൊണ്ടുവന്നു തരിക എന്ന് നിങ്ങൾ ചിന്തിച്ചു നോക്കിയിട്ടുണ്ടോ? (അല്ലാഹുവല്ലാതെ മറ്റാരുമില്ല!)».", "malayalamMatn": "പറയുക: നിങ്ങള്‍ ചിന്തിച്ച് നോക്കിയിട്ടുണ്ടോ? നിങ്ങളുടെ വെള്ളം വറ്റിപ്പോയാല്‍ ആരാണ് നിങ്ങള്‍ക്ക് ഒഴുകുന്ന ഉറവു വെള്ളം കൊണ്ട് വന്നു തരിക?"}], "topPoints": ["അല്ലാഹുവിന്റെ സൃഷ്ടിപ്പിലെ പൂർണ്ണത (خلاصة السورة)", "മരണവും ജീവിതവും ഒരു പരീക്ഷണമാണ്"], "topQuestions": [{"q": "സൂറത്തുൽ മുൽക്കിന്റെ പ്രധാന ആശയം?", "a": "പ്രപഞ്ചത്തിന്റെ മുഴുവൻ ആധിപത്യവും അല്ലാഹുവിനാണെന്ന് ഓർമ്മിപ്പിക്കുന്നു."}], "asbabAlNuzul": [{"ayahNumber": 13, "quranText": "وَأَسِرُّوا۟ قَوۡلَكُمۡ أَوِ ٱجۡهَرُوا۟ بِهِۦۤۖ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ", "arabicSnippet": "«وأَسِرُّوا قَوْلكم أو اجهروا به إنه عليم بذات الصدور» وسبب نزول ذلك أن المشركين قال بعضهم لبعض: أسرّوا قولكم لا يسمعكم إله محمد.", "malayalamExplanation": "മക്കയിലെ മുശ്‌രിക്കുകൾ നബി ﷺ ക്കെതിരെ കുതന്ത്രങ്ങൾ മെനയുമ്പോൾ പരസ്പരം രഹസ്യമായി പറഞ്ഞു: \"നിങ്ങൾ ശബ്ദം താഴ്ത്തി സംസാരിക്കുവിൻ, മുഹമ്മദിന്റെ ദൈവം അത് കേൾക്കാതിരിക്കട്ടെ!\". മനുഷ്യന്റെ രഹസ്യവും പരസ്യവും മാത്രമല്ല, അവരുടെ ഹൃദയങ്ങളിലെ അന്തർഗതങ്ങൾ പോലും സൂക്ഷ്മമായി അറിയുന്നവനാണ് സർവ്വശക്തനായ അല്ലാഹുവെന്ന് പ്രഖ്യാപിച്ചുകൊണ്ട് ഈ വചനം അവതരിച്ചു."}]}, {"surahNumber": 68, "surahNameArabic": "سُورَةُ القَلَمِ", "surahNameMalayalam": "സൂറത്തുൽ ഖലം (പേന)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ نۤۚ وَٱلۡقَلَمِ وَمَا یَسۡطُرُونَ\n", "jalalayn": "«ن» أحَد حُرُوف الهِجاء اللَّه أعْلَم بِمُرادِهِ بِهِ «والقَلَم» الَّذِي كَتَبَ بِهِ الكائِنات فِي اللَّوْح المَحْفُوظ «وما يَسْطُرُونَ» أيْ المَلائِكَة مِن الخَيْر والصَّلاح", "malayalam": "«നൂൻ. പേനയും അവർ എഴുതുന്നതുമായ കാര്യങ്ങളെക്കൊണ്ട് സത്യം!».", "malayalamMatn": "നൂന്‍- പേനയും അവര്‍ എഴുതുന്നതും തന്നെയാണ സത്യം."}, {"ayahNumber": 2, "quranText": "مَاۤ أَنتَ بِنِعۡمَةِ رَبِّكَ بِمَجۡنُونࣲ\n", "jalalayn": "«ما أنْتَ» يا مُحَمَّد «بِنِعْمَةِ رَبّك بِمَجْنُونٍ» أيْ انْتَفى الجُنُون عَنْك بِسَبَبِ إنْعام رَبّك عَلَيْك بِالنُّبُوَّةِ وغَيْرها وهَذا رَدّ لِقَوْلِهِمْ إنّهُ مَجْنُون", "malayalam": "«നിന്റെ രക്ഷിതാവിന്റെ അനുഗ്രഹത്താൽ നീ ഭ്രാന്തനല്ല!» (നബി ﷺ ക്കെതിരെ ഭ്രാന്താരോപിച്ച അവിശ്വാസികളുടെ വാദം തള്ളിക്കളഞ്ഞുകൊണ്ട്).", "malayalamMatn": "നിന്‍റെ രക്ഷിതാവിന്‍റെ അനുഗ്രഹം കൊണ്ട് നീ ഒരു ഭ്രാന്തനല്ല."}, {"ayahNumber": 3, "quranText": "وَإِنَّ لَكَ لَأَجۡرًا غَیۡرَ مَمۡنُونࣲ\n", "jalalayn": "«وإنَّ لَك لَأَجْرًا غَيْر مَمْنُون» أيْ أجْرًا غَيْر مَقْطُوع", "malayalam": "«തീർച്ചയായും നിനക്ക് നിലച്ചുപോകാത്ത പ്രതിഫലമുണ്ട്».", "malayalamMatn": "തീര്‍ച്ചയായും നിനക്ക് മുറിഞ്ഞ് പോകാത്ത പ്രതിഫലമുണ്ട്‌."}, {"ayahNumber": 4, "quranText": "وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِیمࣲ\n", "jalalayn": "«خُلُق» دِين", "malayalam": "«തീർച്ചയായും നീ മഹത്തായ സ്വഭാവത്തിലാകുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും നീ മഹത്തായ സ്വഭാവത്തിലാകുന്നു."}, {"ayahNumber": 5, "quranText": "فَسَتُبۡصِرُ وَیُبۡصِرُونَ\n", "jalalayn": "«فَسَتُبۡصِرُ وَیُبۡصِرُونَ».", "malayalam": "«വഴിയെ നീ കാണും, അവരും കാണും».", "malayalamMatn": "ആകയാല്‍ വഴിയെ നീ കണ്ടറിയും; അവരും കണ്ടറിയും;"}, {"ayahNumber": 6, "quranText": "بِأَییِّكُمُ ٱلۡمَفۡتُونُ\n", "jalalayn": "«بِأَيِيِّكُمْ المَفْتُون» مَصْدَر كالمَعْقُولِ أيْ الفُتُون بِمَعْنى الجُنُون أيْ أبِك أمْ بِهِمْ", "malayalam": "«നിങ്ങളിൽ ആരാണ് ഭ്രാന്തനെന്ന്!».", "malayalamMatn": "നിങ്ങളില്‍ ആരാണ് കുഴപ്പത്തിലകപ്പെട്ടവനെന്ന്‌"}, {"ayahNumber": 7, "quranText": "إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِیلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِینَ\n", "jalalayn": "«إنّ رَبّك أعْلَم بِمَن ضَلَّ عَنْ سَبِيله وهُوَ أعْلَم بِالمُهْتَدِينَ» لَهُ وأَعْلَم بِمَعْنى عالِم", "malayalam": "«തീർച്ചയായും നിന്റെ രക്ഷിതാവ് തന്റെ മാർഗ്ഗത്തിൽ നിന്ന് പിഴച്ചുപോയവനെപ്പറ്റി ഏറ്റവും നന്നായി അറിയുന്നവനാണ്; സന്മാർഗ്ഗം പ്രാപിച്ചവരെപ്പറ്റിയും അവൻ ഏറ്റവും നന്നായി അറിയുന്നവനാണ്».", "malayalamMatn": "തീര്‍ച്ചയായും നിന്‍റെ രക്ഷിതാവ് അവന്‍റെ മാര്‍ഗം വിട്ടു പിഴച്ചുപോയവരെപ്പറ്റി നല്ലവണ്ണം അറിയുന്നവനാകുന്നു. സന്‍മാര്‍ഗം പ്രാപിച്ചവരെപ്പറ്റിയും അവന്‍ നല്ലവണ്ണം അറിയുന്നവനാകുന്നു."}, {"ayahNumber": 8, "quranText": "فَلَا تُطِعِ ٱلۡمُكَذِّبِینَ\n", "jalalayn": "«فَلَا تُطِعِ ٱلۡمُكَذِّبِینَ».", "malayalam": "«ആകയാൽ സത്യനിഷേധികളെ നീ അനുസരിക്കരുത്».", "malayalamMatn": "അതിനാല്‍ സത്യനിഷേധികളെ നീ അനുസരിക്കരുത്‌?"}, {"ayahNumber": 9, "quranText": "وَدُّوا۟ لَوۡ تُدۡهِنُ فَیُدۡهِنُونَ\n", "jalalayn": "«ودُّوا» تَمَنَّوْا «لَوْ» مَصْدَرِيَّة «تُدْهِن» تَلِينَ لَهُمْ «فَيُدْهِنُونَ» يَلِينُونَ لَك وهُوَ مَعْطُوف عَلى تُدْهِن وإنْ جَعَلَ جَواب التَّمَنِّي المَفْهُوم مِن ودُّوا قَدْر قَبْله بَعْد الفاء هُمْ", "malayalam": "«നീ വഴങ്ങിക്കൊടുത്തിരുന്നെങ്കിൽ തങ്ങൾക്കും വഴങ്ങിക്കൊടുക്കാമായിരുന്നു എന്ന് അവർ കൊതിക്കുകയാണ്».", "malayalamMatn": "നീ വഴങ്ങികൊടുത്തിരുന്നെങ്കില്‍ അവര്‍ക്കും വഴങ്ങിത്തരാമായിരുന്നു എന്നവര്‍ ആഗ്രഹിക്കുന്നു."}, {"ayahNumber": 10, "quranText": "وَلَا تُطِعۡ كُلَّ حَلَّافࣲ مَّهِینٍ\n", "jalalayn": "«ولا تُطِعْ كُلّ حَلّاف» كَثِير الحَلِف بِالباطِلِ «مَهِين» حَقِير", "malayalam": "«കൂടുതലായി കള്ളസത്യം ചെയ്യുന്ന, നിന്ദ്യനായ യാതൊരുത്തനെയും നീ അനുസരിക്കരുത്».", "malayalamMatn": "അധികമായി സത്യം ചെയ്യുന്നവനും, നീചനുമായിട്ടുള്ള യാതൊരാളെയും നീ അനുസരിച്ചു പോകരുത്‌."}, {"ayahNumber": 11, "quranText": "هَمَّازࣲ مَّشَّاۤءِۭ بِنَمِیمࣲ\n", "jalalayn": "«هَمّاز» عَيّاب أيْ مُغْتاب «مَشّاء بِنَمِيمٍ» أيْ ساعٍ بِالكَلامِ بَيْن النّاس عَلى وجْه الإفْساد بَيْنهمْ", "malayalam": "«കുത്തുവാക്ക് പറയുന്നവനും ഏഷണി പറഞ്ഞു നടക്കുന്നവനുമായ».", "malayalamMatn": "കുത്തുവാക്ക് പറയുന്നവനും ഏഷണിയുമായി നടക്കുന്നവനുമായ"}, {"ayahNumber": 12, "quranText": "مَّنَّاعࣲ لِّلۡخَیۡرِ مُعۡتَدٍ أَثِیمٍ\n", "jalalayn": "«مَنّاع لِلْخَيْرِ» بَخِيل بِالمالِ عَنْ الحُقُوق «مُعْتَدٍ» ظالِم «أثِيم» آثِم", "malayalam": "«നന്മയെ തടയുന്നവനും അതിക്രമിയും മഹാപാപിയുമായ».", "malayalamMatn": "നന്‍മക്ക് തടസ്സം നില്‍ക്കുന്നവനും, അതിക്രമിയും മഹാപാപിയുമായ"}, {"ayahNumber": 13, "quranText": "عُتُلِّۭ بَعۡدَ ذَ ٰ⁠لِكَ زَنِیمٍ\n", "jalalayn": "«عُتُلّ» غَلِيظ جافٍ «بَعْد ذَلِكَ زَنِيم» دُعِيَ فِي قُرَيْش وهُوَ الوَلِيد بْن المُغِيرَة ادَّعاهُ أبُوهُ بَعْد ثَمانِي عَشْرَة سَنَة قالَ ابْن عَبّاس: لا نَعْلَم أنَّ اللَّه وصَفَ أحَدًا بِما وصَفَهُ بِهِ مِن العُيُوب فَأَلْحَقَ بِهِ عارًا لا يُفارِقهُ أبَدًا وتَعَلَّقَ بِزَنِيمٍ الظَّرْف قَبْله", "malayalam": "«ക്രൂരനും അതിനുപുറമെ തന്തയില്ലാത്തവനുമായ (വ്യഭിചാരത്തിൽ പിറന്ന വലീദ് ബിൻ മുഗീറയെപ്പോലുള്ളവനെ)».", "malayalamMatn": "ക്രൂരനും അതിനു പുറമെ ദുഷ്കീര്‍ത്തി നേടിയവനുമായ"}, {"ayahNumber": 14, "quranText": "أَن كَانَ ذَا مَالࣲ وَبَنِینَ\n", "jalalayn": "«أنْ كانَ ذا مال وبَنِينَ» أيْ لِأَنَّ وهُوَ مُتَعَلِّق بِما دَلَّ عَلَيْهِ", "malayalam": "«അവൻ സ്വത്തും മക്കളുമുള്ളവനായി എന്നതുകൊണ്ടാണോ (അവൻ ധിക്കാരം കാണിക്കുന്നത്?)».", "malayalamMatn": "അവന്‍ സ്വത്തും സന്താനങ്ങളും ഉള്ളവനായി എന്നതിനാല്‍ (അവന്‍ അത്തരം നിലപാട് സ്വീകരിച്ചു.)"}, {"ayahNumber": 15, "quranText": "إِذَا تُتۡلَىٰ عَلَیۡهِ ءَایَـٰتُنَا قَالَ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ\n", "jalalayn": "«إذا تُتْلى عَلَيْهِ آياتنا» القُرْآن «قالَ» هِيَ «أساطِير الأَوَّلِينَ» أيْ كَذَّبَ بِها لِإنْعامِنا عَلَيْهِ بِما ذُكِرَ وفِي قِراءَة أأَنْ بِهَمْزَتَيْنِ مَفْتُوحَتَيْنِ", "malayalam": "«നമ്മുടെ സൂക്തങ്ങൾ അവന് ഓതിക്കേൾപിക്കപ്പെട്ടാൽ അവൻ പറയും: പൂർവ്വികരുടെ കെട്ടുകഥകൾ!».", "malayalamMatn": "നമ്മുടെ ദൃഷ്ടാന്തങ്ങള്‍ അവന്ന് വായിച്ചുകേള്‍പിക്കപ്പെട്ടാല്‍ അവന്‍ പറയും; പൂര്‍വ്വികന്‍മാരുടെ പുരാണകഥകള്‍ എന്ന്‌."}, {"ayahNumber": 16, "quranText": "سَنَسِمُهُۥ عَلَى ٱلۡخُرۡطُومِ\n", "jalalayn": "«سَنَسِمُهُ عَلى الخُرْطُوم» سَنَجْعَلُ عَلى أنْفه عَلامَة يُعَيَّر بِها ما عاشَ فَخُطِمَ أنْفه بِالسَّيْفِ يَوْم بَدْر", "malayalam": "«വഴിയെ അവന്റെ തുമ്പിക്കൈമേൽ (മൂക്കിന്മേൽ) നാം അടയാളം വെക്കുന്നതാണ്!».", "malayalamMatn": "വഴിയെ (അവന്‍റെ) തുമ്പിക്കൈ മേല്‍ നാം അവന്ന് അടയാളം വെക്കുന്നതാണ്‌."}, {"ayahNumber": 17, "quranText": "إِنَّا بَلَوۡنَـٰهُمۡ كَمَا بَلَوۡنَاۤ أَصۡحَـٰبَ ٱلۡجَنَّةِ إِذۡ أَقۡسَمُوا۟ لَیَصۡرِمُنَّهَا مُصۡبِحِینَ\n", "jalalayn": "«إنّا بَلَوْناهُمْ» امْتَحَنّا أهْل مَكَّة بِالقَحْطِ والجُوع «كَما بَلَوْنا أصْحاب الجَنَّة» أيْ أصْحاب البُسْتان «إذْ أقَسَمُوا لِيَصْرِمُنَّها» يَقْطَعُونَ ثَمَرَتها «مُصْبِحِينَ» وقْت الصَّباح كَيْ لا يَشْعُر بِهِمْ المَساكِين فَلا يُعْطُونَهُمْ مِنها ما كانَ أبُوهُمْ يَتَصَدَّق بِهِ عَلَيْهِمْ مِنها", "malayalam": "«തീർച്ചയായും ആ തോട്ടക്കാരെ നാം പരീക്ഷിച്ചതുപോലെ ഇവരെയും നാം പരീക്ഷിച്ചിരിക്കുന്നു; പ്രഭാതവേളയിൽ ആ തോട്ടത്തിലെ പഴങ്ങൾ പറിച്ചെടുക്കുമെന്ന് അവർ ശപഥം ചെയ്ത സന്ദർഭം!».", "malayalamMatn": "ആ തോട്ടക്കാരെ നാം പരീക്ഷിച്ചത് പോലെ തീര്‍ച്ചയായും അവരെയും നാം പരീക്ഷിച്ചിരിക്കുകയാണ്‌. പ്രഭാതവേളയില്‍ ആ തോട്ടത്തിലെ പഴങ്ങള്‍ അവര്‍ പറിച്ചെടുക്കുമെന്ന് അവര്‍ സത്യം ചെയ്ത സന്ദര്‍ഭം."}, {"ayahNumber": 18, "quranText": "وَلَا یَسۡتَثۡنُونَ\n", "jalalayn": "«ولا يَسْتَثْنُونَ» فِي يَمِينهمْ بِمَشِيئَةِ اللَّه تَعالى والجُمْلَة مُسْتَأْنَفَة أيْ وشَأْنهمْ ذَلِكَ", "malayalam": "«ഇൻശാ അല്ലാഹ് എന്ന് അവർ ഒഴിവാക്കിപ്പറഞ്ഞതുമില്ല (പാവങ്ങൾക്ക് വിഹിതം നൽകാൻ അവർ ഉദ്ദേശിച്ചതുമില്ല)».", "malayalamMatn": "അവര്‍ (യാതൊന്നും) ഒഴിവാക്കി പറഞ്ഞിരുന്നില്ല."}, {"ayahNumber": 19, "quranText": "فَطَافَ عَلَیۡهَا طَاۤىِٕفࣱ مِّن رَّبِّكَ وَهُمۡ نَاۤىِٕمُونَ\n", "jalalayn": "«فَطافَ عَلَيْها طائِف مِن رَبّك» نار أحْرَقَتْها لَيْلًا", "malayalam": "«അങ്ങനെ അവർ ഉറങ്ങിക്കിടക്കവേ നിന്റെ രക്ഷിതാവിങ്കൽ നിന്നുള്ള ഒരു വിപത്ത് അതിന്മേൽ ചുറ്റിത്തിരിഞ്ഞു».", "malayalamMatn": "എന്നിട്ട് അവര്‍ ഉറങ്ങിക്കൊണ്ടിരിക്കെ നിന്‍റെ രക്ഷിതാവിങ്കല്‍ നിന്നുള്ള ഒരു ശിക്ഷ ആ തോട്ടത്തെ ബാധിച്ചു."}, {"ayahNumber": 20, "quranText": "فَأَصۡبَحَتۡ كَٱلصَّرِیمِ\n", "jalalayn": "«فَأَصْبَحَتْ كالصَّرِيمِ» كاللَّيْلِ الشَّدِيد الظُّلْمَة أيْ سَوْداء", "malayalam": "«അങ്ങനെ അത് പറിച്ചെടുക്കപ്പെട്ട കറുത്ത തോട്ടം പോലെയായിത്തീർന്നു (ചാരക്കൂമ്പാരമായി മാറ്റി)».", "malayalamMatn": "അങ്ങനെ അത് മുറിച്ചെടുക്കപ്പെട്ടത് പോലെ ആയിത്തീര്‍ന്നു."}, {"ayahNumber": 21, "quranText": "فَتَنَادَوۡا۟ مُصۡبِحِینَ\n", "jalalayn": "«فَتَنَادَوۡا۟ مُصۡبِحِینَ».", "malayalam": "«പ്രഭാതത്തിൽ അവർ പരസ്പരം വിളിച്ചുപറഞ്ഞു:».", "malayalamMatn": "അങ്ങനെ പ്രഭാതവേളയില്‍ അവര്‍ പരസ്പരം വിളിച്ചുപറഞ്ഞു:"}, {"ayahNumber": 22, "quranText": "أَنِ ٱغۡدُوا۟ عَلَىٰ حَرۡثِكُمۡ إِن كُنتُمۡ صَـٰرِمِینَ\n", "jalalayn": "«أنْ اُغْدُوا عَلى حَرْثكُمْ» غَلَّتْكُمْ تَفْسِير لِتَنادَوْا أوْ أنْ مَصْدَرِيَّة أيْ بِأَنْ «إنْ كُنْتُمْ صارِمِينَ» مُرِيدِينَ القَطْع وجَواب الشَّرْط دَلَّ عَلَيْهِ ما قَبْله", "malayalam": "«നിങ്ങൾ പറിച്ചെടുക്കാൻ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ നിങ്ങളുടെ കൃഷിയിടത്തിലേക്ക് അതിരാവിലെ പുറപ്പെടുവിൻ!».", "malayalamMatn": "നിങ്ങള്‍ പറിച്ചെടുക്കാന്‍ പോകുകയാണെങ്കില്‍ നിങ്ങളുടെ കൃഷിസ്ഥലത്തേക്ക് നിങ്ങള്‍ കാലത്തുതന്നെ പുറപ്പെടുക."}, {"ayahNumber": 23, "quranText": "فَٱنطَلَقُوا۟ وَهُمۡ یَتَخَـٰفَتُونَ\n", "jalalayn": "«فانْطَلَقُوا وهُمْ يَتَخافَتُونَ» يَتَسارُّونَ", "malayalam": "«അങ്ങനെ അവർ പരസ്പരം പതുക്കെ സംസാരിച്ചുകൊണ്ട് നടന്നു:».", "malayalamMatn": "അവര്‍ അന്യോന്യം മന്ത്രിച്ചു കൊണ്ടു പോയി."}, {"ayahNumber": 24, "quranText": "أَن لَّا یَدۡخُلَنَّهَا ٱلۡیَوۡمَ عَلَیۡكُم مِّسۡكِینࣱ\n", "jalalayn": "«أنْ لا يَدْخُلَنها اليَوْم عَلَيْكُمْ مِسْكِين» تَفْسِير لِما قَبْله أوْ أنْ مَصْدَرِيَّة أيْ بِأَنْ", "malayalam": "«ഇന്ന് യാതൊരു ദരിദ്രനും നിങ്ങളുടെ സമ്മതമില്ലാതെ ഇതിലേക്ക് പ്രവേശിക്കരുത് എന്ന് പറഞ്ഞുകൊണ്ട്!».", "malayalamMatn": "ഇന്ന് ആ തോട്ടത്തില്‍ നിങ്ങളുടെ അടുത്ത് ഒരു സാധുവും കടന്നു വരാന്‍ ഇടയാവരുത് എന്ന്‌."}, {"ayahNumber": 25, "quranText": "وَغَدَوۡا۟ عَلَىٰ حَرۡدࣲ قَـٰدِرِینَ\n", "jalalayn": "«وغَدَوْا عَلى حَرْد» مَنع لِلْفُقَراءِ «قادِرِينَ» عَلَيْهِ فِي ظَنّهمْ", "malayalam": "«തങ്ങൾക്ക് തടയാൻ സാധിക്കുമെന്ന ധാരണയിൽ അവർ അതിരാവിലെ പുറപ്പെട്ടു».", "malayalamMatn": "അവര്‍ (സാധുക്കളെ) തടസ്സപ്പെടുത്താന്‍ കഴിവുള്ളവരായിക്കൊണ്ടു തന്നെ കാലത്ത് പുറപ്പെടുകയും ചെയ്തു."}, {"ayahNumber": 26, "quranText": "فَلَمَّا رَأَوۡهَا قَالُوۤا۟ إِنَّا لَضَاۤلُّونَ\n", "jalalayn": "«فَلَمّا رَأَوْها» سَوْداء مُحْتَرِقَة «قالُوا إنّا لَضالُّونَ» عَنْها أيْ لَيْسَتْ هَذِهِ ثُمَّ قالُوا لَمّا عَلِمُوها", "malayalam": "«അങ്ങനെ അത് കണ്ടപ്പോൾ അവർ പറഞ്ഞു: തീർച്ചയായും നമ്മൾ വഴിതെറ്റിപ്പോയിരിക്കുന്നു!».", "malayalamMatn": "അങ്ങനെ അത് (തോട്ടം) കണ്ടപ്പോള്‍ അവര്‍ പറഞ്ഞു: തീര്‍ച്ചയായും നാം പിഴവു പറ്റിയവരാകുന്നു."}, {"ayahNumber": 27, "quranText": "بَلۡ نَحۡنُ مَحۡرُومُونَ\n", "jalalayn": "«بَلْ نَحْنُ مَحْرُومُونَ» ثَمَرَتها بِمَنعِنا الفُقَراء مِنها", "malayalam": "«അല്ല, നാം ഉപജീവനം തടയപ്പെട്ടവരായിരിക്കുന്നു!».", "malayalamMatn": "അല്ല, നാം നഷ്ടം നേരിട്ടവരാകുന്നു."}, {"ayahNumber": 28, "quranText": "قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا تُسَبِّحُونَ\n", "jalalayn": "«قالَ أوْسَطهمْ» خَيْرهمْ «ألَمْ أقُلْ لَكُمْ لَوْلا» هَلّا «تُسَبِّحُونَ» اللَّه تائِبِينَ", "malayalam": "«അവരിലെ മിതവാദിയായ ആൾ പറഞ്ഞു: നിങ്ങൾ അല്ലാഹുവിന്റെ പരിശുദ്ധിയെ പ്രകീർത്തിക്കാത്തതെന്താണ് എന്ന് ഞാൻ നിങ്ങളോട് പറഞ്ഞിരുന്നില്ലയോ?».", "malayalamMatn": "അവരുടെ കൂട്ടത്തില്‍ മദ്ധ്യനിലപാടുകാരനായ ഒരാള്‍ പറഞ്ഞു: ഞാന്‍ നിങ്ങളോട് പറഞ്ഞില്ലേ? എന്താണ് നിങ്ങള്‍ അല്ലാഹുവെ പ്രകീര്‍ത്തിക്കാതിരുന്നത്‌?"}, {"ayahNumber": 29, "quranText": "قَالُوا۟ سُبۡحَـٰنَ رَبِّنَاۤ إِنَّا كُنَّا ظَـٰلِمِینَ\n", "jalalayn": "«قالُوا سُبْحان رَبّنا إنّا كُنّا ظالِمِينَ» بِمَنعِ الفُقَراء حَقّهمْ", "malayalam": "«അവർ പറഞ്ഞു: ഞങ്ങളുടെ രക്ഷിതാവ് എത്രയോ പരിശുദ്ധൻ! തീർച്ചയായും ഞങ്ങൾ അക്രമികളായിരുന്നു!».", "malayalamMatn": "അവര്‍ പറഞ്ഞു: നമ്മുടെ രക്ഷിതാവ് എത്രയോ പരിശുദ്ധന്‍! തീര്‍ച്ചയായും നാം അക്രമികളായിരിക്കുന്നു."}, {"ayahNumber": 30, "quranText": "فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضࣲ یَتَلَـٰوَمُونَ\n", "jalalayn": "«فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضࣲ یَتَلَـٰوَمُونَ».", "malayalam": "«എന്നിട്ട് അവർ പരസ്പരം കുറ്റപ്പെടുത്തിക്കൊണ്ട് മുന്നോട്ടുവന്നു».", "malayalamMatn": "അങ്ങനെ പരസ്പരം കുറ്റപ്പെടുത്തിക്കൊണ്ട് അവരില്‍ ചിലര്‍ ചിലരുടെ നേര്‍ക്ക് തിരിഞ്ഞു."}, {"ayahNumber": 31, "quranText": "قَالُوا۟ یَـٰوَیۡلَنَاۤ إِنَّا كُنَّا طَـٰغِینَ\n", "jalalayn": "«قالُوا يا» لِلتَّنْبِيهِ «ويْلنا» هَلاكنا", "malayalam": "«അവർ പറഞ്ഞു: അയ്യോ കഷ്ടം! തീർച്ചയായും നമ്മൾ അതിക്രമികളായിരുന്നു!».", "malayalamMatn": "അവര്‍ പറഞ്ഞു: നമ്മുടെ നാശമേ! തീര്‍ച്ചയായും നാം അതിക്രമകാരികളായിരിക്കുന്നു."}, {"ayahNumber": 32, "quranText": "عَسَىٰ رَبُّنَاۤ أَن یُبۡدِلَنَا خَیۡرࣰا مِّنۡهَاۤ إِنَّاۤ إِلَىٰ رَبِّنَا رَ ٰ⁠غِبُونَ\n", "jalalayn": "«يُبْدِلنا» بِالتَّشْدِيدِ والتَّخْفِيف «خَيْرًا مِنها إنّا إلى رَبّنا راغِبُونَ» لِيَقْبَل تَوْبَتنا ويَرُدّ عَلَيْنا خَيْرًا مِن جَنَّتنا رُوِيَ أنَّهُمْ أُبْدِلُوا خَيْرًا مِنها", "malayalam": "«നമ്മുടെ രക്ഷിതാവ് ഇതിനേക്കാൾ ഉത്തമമായതിനെ നമുക്ക് പകരം നൽകിയേക്കാം; തീർച്ചയായും ഞങ്ങൾ ഞങ്ങളുടെ രക്ഷിതാവിലേക്ക് ആഗ്രഹിക്കുന്നവരാകുന്നു!».", "malayalamMatn": "നമ്മുടെ രക്ഷിതാവ് അതിനെക്കാള്‍ ഉത്തമമായത് നമുക്ക് പകരം തന്നേക്കാം. തീര്‍ച്ചയായും നാം നമ്മുടെ രക്ഷിതാവിങ്കലേക്ക് ആഗ്രഹിച്ചു ചെല്ലുന്നവരാകുന്നു."}, {"ayahNumber": 33, "quranText": "كَذَ ٰ⁠لِكَ ٱلۡعَذَابُۖ وَلَعَذَابُ ٱلۡـَٔاخِرَةِ أَكۡبَرُۚ لَوۡ كَانُوا۟ یَعۡلَمُونَ\n", "jalalayn": "«كَذَلِكَ» أيْ مِثْل العَذاب لِهَؤُلاءِ «العَذاب» لِمَن خالَفَ أمْرنا مِن كُفّار مَكَّة وغَيْرهمْ «ولَعَذاب الآخِرَة أكْبَر لَوْ كانُوا يَعْلَمُونَ» عَذابها ما خالَفُوا أمْرنا ونَزَلَ لَمّا قالُوا إنْ بَعَثَنا نُعْطى أفَضْل مِنكُمْ", "malayalam": "«അപ്രകാരമാകുന്നു ശിക്ഷ; പരലോകശിക്ഷയാകട്ടെ ഏറ്റവും വലുതാകുന്നു, അവർ അറിയുന്നവരായിരുന്നുവെങ്കിൽ! (ഞങ്ങൾ ഉയിർത്തെഴുന്നേൽപിക്കപ്പെട്ടാൽ നിങ്ങളേക്കാൾ മികച്ചത് ലഭിക്കുമെന്ന് അവിശ്വാസികൾ പറഞ്ഞപ്പോൾ ഇത് അവതരിച്ചു)».", "malayalamMatn": "അപ്രകാരമാകുന്നു ശിക്ഷ. പരലോകശിക്ഷയാവട്ടെ കൂടുതല്‍ ഗൌരവമുള്ളതാകുന്നു. അവര്‍ അറിഞ്ഞിരുന്നെങ്കില്‍!"}, {"ayahNumber": 34, "quranText": "إِنَّ لِلۡمُتَّقِینَ عِندَ رَبِّهِمۡ جَنَّـٰتِ ٱلنَّعِیمِ\n", "jalalayn": "«إِنَّ لِلۡمُتَّقِینَ عِندَ رَبِّهِمۡ جَنَّـٰتِ ٱلنَّعِیمِ».", "malayalam": "«തീർച്ചയായും ഭയഭക്തിയുള്ളവർക്ക് തങ്ങളുടെ രക്ഷിതാവിങ്കൽ അനുഗ്രഹങ്ങളുടെ സ്വർഗ്ഗത്തോപ്പുകളുണ്ട്».", "malayalamMatn": "തീര്‍ച്ചയായും സൂക്ഷ്മത പാലിക്കുന്നവര്‍ക്ക് അവരുടെ രക്ഷിതാവിങ്കല്‍ അനുഗ്രഹങ്ങളുടെ സ്വര്‍ഗത്തോപ്പുകളുണ്ട്‌."}, {"ayahNumber": 35, "quranText": "أَفَنَجۡعَلُ ٱلۡمُسۡلِمِینَ كَٱلۡمُجۡرِمِینَ\n", "jalalayn": "«أفَنَجْعَل المُسْلِمِينَ كالمُجْرِمِينَ» أيْ تابِعِينَ لَهُمْ فِي العَطاء", "malayalam": "«അപ്പോൾ മുസ്ലിംകളെ നാം കുറ്റവാളികളെപ്പോലെ ആക്കുമോ?».", "malayalamMatn": "അപ്പോള്‍ മുസ്ലിംകളെ നാം കുറ്റവാളികളെപോലെ ആക്കുമോ?"}, {"ayahNumber": 36, "quranText": "مَا لَكُمۡ كَیۡفَ تَحۡكُمُونَ\n", "jalalayn": "«ما لَكُمْ كَيْفَ تَحْكُمُونَ» هَذا الحُكْم الفاسِد", "malayalam": "«നിങ്ങൾക്കെന്തു പറ്റി, നിങ്ങൾ എങ്ങനെയാണ് വിധി കൽപിക്കുന്നത്?».", "malayalamMatn": "നിങ്ങള്‍ക്കെന്തു പറ്റി? നിങ്ങള്‍ എങ്ങനെയാണ് വിധികല്‍പിക്കുന്നത്‌?"}, {"ayahNumber": 37, "quranText": "أَمۡ لَكُمۡ كِتَـٰبࣱ فِیهِ تَدۡرُسُونَ\n", "jalalayn": "«أمْ» أيْ بَلْ أ «لَكُمْ كِتاب» مُنَزَّل «فِيهِ تَدْرُسُونَ» أيْ تَقْرَءُونَ", "malayalam": "«അതല്ല, നിങ്ങൾ വായിച്ചുപഠിക്കുന്ന വല്ല വേദഗ്രന്ഥവും നിങ്ങളുടെ പക്കലുണ്ടോ?».", "malayalamMatn": "അതല്ല, നിങ്ങള്‍ക്കു വല്ല ഗ്രന്ഥവും കിട്ടിയിട്ട് നിങ്ങളതില്‍ പഠനം നടത്തിക്കൊണ്ടിരിക്കുകയാണോ?"}, {"ayahNumber": 38, "quranText": "إِنَّ لَكُمۡ فِیهِ لَمَا تَخَیَّرُونَ\n", "jalalayn": "«إنّ لَكُمْ فِيهِ لَما تَخَيَّرُونَ» تَخْتارُونَ", "malayalam": "«നിങ്ങൾ ഇഷ്ടപ്പെടുന്നതെല്ലാം അതിലുണ്ടെന്ന് വ്യക്തമാക്കുന്ന ഗ്രന്ഥം?».", "malayalamMatn": "നിങ്ങള്‍ (യഥേഷ്ടം) തെരഞ്ഞെടുക്കുന്ന കാര്യങ്ങള്‍ നിങ്ങള്‍ക്ക് അതില്‍ (ആ ഗ്രന്ഥത്തില്‍) വന്നിട്ടുണ്ടോ?"}, {"ayahNumber": 39, "quranText": "أَمۡ لَكُمۡ أَیۡمَـٰنٌ عَلَیۡنَا بَـٰلِغَةٌ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ إِنَّ لَكُمۡ لَمَا تَحۡكُمُونَ\n", "jalalayn": "«أمْ لَكُمْ أيْمان» عُهُود «عَلَيْنا بالِغَة» واثِقَة «إلى يَوْم القِيامَة» مُتَعَلِّق مَعْنى بِعَلَيْنا وفِي هَذا الكَلام مَعْنى القَسَم أيْ أقْسَمْنا لَكُمْ وجَوابه «إنّ لَكُمْ لَما تَحْكُمُونَ» بِهِ لِأَنْفُسِكُمْ", "malayalam": "«അതല്ല, നിങ്ങൾ വിധിക്കുന്നതൊക്കെ നിങ്ങൾക്ക് ലഭിക്കുമെന്ന് ഖിയാമത്ത് നാൾ വരെയുള്ള വല്ല പ്രതിജ്ഞകളും നമ്മുടെ ബാധ്യതയിലായി നിങ്ങൾക്കുണ്ടോ?».", "malayalamMatn": "അതല്ല, ഉയിര്‍ത്തെഴുന്നേല്‍പിന്‍റെ നാളുവരെ എത്തുന്ന - നിങ്ങള്‍ വിധിക്കുന്നതെല്ലാം നിങ്ങള്‍ക്കായിരിക്കുമെന്നതിനുള്ള-വല്ല കരാറുകളും നിങ്ങളോട് നാം ബാധ്യതയേറ്റതായി ഉണ്ടോ?"}, {"ayahNumber": 40, "quranText": "سَلۡهُمۡ أَیُّهُم بِذَ ٰ⁠لِكَ زَعِیمٌ\n", "jalalayn": "«سَلْهُمْ أيّهمْ بِذَلِكَ» الحُكْم الَّذِي يَحْكُمُونَ بِهِ لِأَنْفُسِهِمْ مِن أنَّهُمْ يُعْطُونَ فِي الآخِرَة أفَضْل مِن المُؤْمِنِينَ «زَعِيم» كَفِيل لَهُمْ", "malayalam": "«അവരിൽ ആരാണ് അതിന് ഉത്തരവാദിയെന്ന് നീ അവരോട് ചോദിക്കുക».", "malayalamMatn": "അവരില്‍ ആരാണ് ആ കാര്യത്തിന് ഉത്തരവാദിത്തം ഏല്‍ക്കാനുള്ളത് എന്ന് അവരോട് ചോദിച്ചു നോക്കുക."}, {"ayahNumber": 41, "quranText": "أَمۡ لَهُمۡ شُرَكَاۤءُ فَلۡیَأۡتُوا۟ بِشُرَكَاۤىِٕهِمۡ إِن كَانُوا۟ صَـٰدِقِینَ\n", "jalalayn": "«أمْ لَهُمْ» أيْ عِنْدهمْ «شُرَكاء» مُوافِقُونَ لَهُمْ فِي هَذا القَوْل يَكْفُلُونَ بِهِ لَهُمْ فَإنْ كانَ كَذَلِكَ «فَلْيَأْتُوا بِشُرَكائِهِمْ» الكافِلِينَ لَهُمْ بِهِ", "malayalam": "«അതല്ല, അവർക്ക് വല്ല പങ്കാളികളുമുണ്ടോ? എങ്കിൽ അവർ തങ്ങളുടെ പങ്കാളികളെ കൊണ്ടുവരട്ടെ, അവർ സത്യവാന്മാരാണെങ്കിൽ!».", "malayalamMatn": "അതല്ല, അവര്‍ക്ക് വല്ല പങ്കുകാരുമുണ്ടോ? എങ്കില്‍ അവരുടെ ആ പങ്കുകാരെ അവര്‍ കൊണ്ടുവരട്ടെ. അവര്‍ സത്യവാന്‍മാരാണെങ്കില്‍."}, {"ayahNumber": 42, "quranText": "یَوۡمَ یُكۡشَفُ عَن سَاقࣲ وَیُدۡعَوۡنَ إِلَى ٱلسُّجُودِ فَلَا یَسۡتَطِیعُونَ\n", "jalalayn": "«يَوْم يُكْشَف عَنْ ساق» هُوَ عِبارَة عَنْ شِدَّة الأَمْر يَوْم القِيامَة لِلْحِسابِ والجَزاء يُقال: كَشَفَتْ الحَرْب عَنْ ساق: إذا اشْتَدَّ الأَمْر فِيها «ويُدْعَوْنَ إلى السُّجُود» امْتِحانًا لِإيمانِهِمْ «فَلا يَسْتَطِيعُونَ» تَصِير ظُهُورهمْ طَبَقًا واحِدًا", "malayalam": "«കണങ്കാൽ വെളിവാക്കപ്പെടുന്ന ആ ഭയാനകമായ ദിവസം! സാഷ്ടാംഗം ചെയ്യാൻ അവർ ക്ഷണിക്കപ്പെടും; എന്നാൽ അവർക്കതിന് സാധിക്കുകയില്ല».", "malayalamMatn": "കണങ്കാല്‍ വെളിവാക്കപ്പെടുന്ന (ഭയങ്കരമായ) ഒരു ദിവസത്തെ നിങ്ങള്‍ ഓര്‍ക്കുക. സുജൂദ് ചെയ്യാന്‍ (അന്ന്‌) അവര്‍ ക്ഷണിക്കപ്പെടും. അപ്പോള്‍ അവര്‍ക്കതിന് സാധിക്കുകയില്ല."}, {"ayahNumber": 43, "quranText": "خَـٰشِعَةً أَبۡصَـٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةࣱۖ وَقَدۡ كَانُوا۟ یُدۡعَوۡنَ إِلَى ٱلسُّجُودِ وَهُمۡ سَـٰلِمُونَ\n", "jalalayn": "«خاشِعَة» حال مِن ضَمِير يَدْعُونَ أيْ ذَلِيلَة «أبْصارهمْ» لا يَرْفَعُونَها «تَرْهَقهُمْ» تَغْشاهُمْ «ذِلَّة وقَدْ كانُوا يُدْعَوْنَ» فِي الدُّنْيا «إلى السُّجُود وهُمْ سالِمُونَ» فَلا يَأْتُونَ بِهِ بِأَنْ لا يُصَلُّوا", "malayalam": "«അവരുടെ കണ്ണുകൾ താഴ്ന്ന നിലയിലായിരിക്കും; നിന്ദ്യത അവരെ ആവരണം ചെയ്യും; അവർ സുരക്ഷിതരായിരുന്ന സന്ദർഭത്തിൽ സാഷ്ടാംഗത്തിലേക്ക് അവർ ക്ഷണിക്കപ്പെട്ടിരുന്നു (അന്നവർ അഹങ്കാരം നടിക്കുകയാണുണ്ടായത്)».", "malayalamMatn": "അവരുടെ കണ്ണുകള്‍ കീഴ്പോട്ട് താഴ്ന്നിരിക്കും. നിന്ദ്യത അവരെ ആവരണം ചെയ്യും. അവര്‍ സുരക്ഷിതരായിരുന്ന സമയത്ത് സുജൂദിനായി അവര്‍ ക്ഷണിക്കപ്പെട്ടിരുന്നു."}, {"ayahNumber": 44, "quranText": "فَذَرۡنِی وَمَن یُكَذِّبُ بِهَـٰذَا ٱلۡحَدِیثِۖ سَنَسۡتَدۡرِجُهُم مِّنۡ حَیۡثُ لَا یَعۡلَمُونَ\n", "jalalayn": "«فَذَرْنِي» دَعْنِي «ومَن يُكَذِّب بِهَذا الحَدِيث» القُرْآن «سَنَسْتَدْرِجُهُمْ» نَأْخُذهُمْ قَلِيلًا قَلِيلًا", "malayalam": "«ആകയാൽ ഈ വർത്തമാനത്തെ തള്ളിപ്പറയുന്നവനെയും എന്നെയും നീ വിട്ടേക്കുക; അവർ അറിയാത്ത ഭാഗത്ത് കൂടി ക്രമേണ നാം അവരെ പിടികൂടുന്നതാണ്».", "malayalamMatn": "ആകയാല്‍ എന്നെയും ഈ വര്‍ത്തമാനം നിഷേധിച്ചു കളയുന്നവരെയും കുടി വിട്ടേക്കുക. അവര്‍ അറിയാത്ത വിധത്തിലൂടെ നാം അവരെ പടിപടിയായി പിടികൂടിക്കൊള്ളാം."}, {"ayahNumber": 45, "quranText": "وَأُمۡلِی لَهُمۡۚ إِنَّ كَیۡدِی مَتِینٌ\n", "jalalayn": "«وأُمْلِي لَهُمْ» أمْهِلْهُمْ «إنّ كَيْدِي مَتِين» شَدِيد لا يُطاق", "malayalam": "«ഞാൻ അവർക്ക് സമയം നീട്ടിക്കൊടുക്കുകയാണ്; തീർച്ചയായും എന്റെ തന്ത്രം അതിശക്തമാകുന്നു».", "malayalamMatn": "ഞാന്‍ അവര്‍ക്ക് നീട്ടിയിട്ട് കൊടുക്കുകയും ചെയ്യും. തീര്‍ച്ചയായും എന്‍റെ തന്ത്രം ശക്തമാകുന്നു."}, {"ayahNumber": 46, "quranText": "أَمۡ تَسۡـَٔلُهُمۡ أَجۡرࣰا فَهُم مِّن مَّغۡرَمࣲ مُّثۡقَلُونَ\n", "jalalayn": "«أمْ» بَلْ أ «تَسْأَلُهُمْ» عَلى تَبْلِيغ الرِّسالَة «أجْرًا فَهُمْ مِن مَغْرَم» مِمّا يُعْطُونَكَهُ «مُثْقَلُونَ» فَلا يُؤْمِنُونَ لِذَلِكَ", "malayalam": "«അതല്ല, നീ അവരോട് വല്ല പ്രതിഫലവും ചോദിച്ചിട്ട് കടബാധ്യതയാൽ അവർ ഭാരപ്പെടുകയാണോ?».", "malayalamMatn": "അതല്ല, നീ അവരോട് വല്ല പ്രതിഫലവും ചോദിച്ചിട്ട് അവര്‍ കടബാധയാല്‍ ഞെരുങ്ങിയിരിക്കുകയാണോ?"}, {"ayahNumber": 47, "quranText": "أَمۡ عِندَهُمُ ٱلۡغَیۡبُ فَهُمۡ یَكۡتُبُونَ\n", "jalalayn": "«أمْ عِنْدهمْ الغَيْب» أيْ اللَّوْح المَحْفُوظ الَّذِي فِيهِ الغَيْب «فَهُمْ يَكْتُبُونَ» مِنهُ ما يَقُولُونَ", "malayalam": "«അതല്ല, അവരുടെ പക്കൽ അദൃശ്യജ്ഞാനമുണ്ടായിട്ട് അവരത് രേഖപ്പെടുത്തി വെക്കുകയാണോ?».", "malayalamMatn": "അതല്ല, അവരുടെ അടുക്കല്‍ അദൃശ്യജ്ഞാനമുണ്ടായിട്ട് അവര്‍ എഴുതി എടുത്തു കൊണ്ടിരിക്കുകയാണോ?"}, {"ayahNumber": 48, "quranText": "فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومࣱ\n", "jalalayn": "«فاصْبِرْ لِحُكْمِ رَبّك» فِيهِمْ بِما يَشاء «ولا تَكُنْ كَصاحِبِ الحُوت» فِي الضَّجَر والعَجَلَة وهُوَ يُونُس عَلَيْهِ السَّلام «إذْ نادى» دَعا رَبّه «وهُوَ مَكْظُوم» مَمْلُوء غَمًّا فِي بَطْن الحُوت", "malayalam": "«ആകയാൽ നിന്റെ രക്ഷിതാവിന്റെ കൽപനക്കായി നീ ക്ഷമയോടെ കാത്തിരിക്കുക; മത്സ്യത്തിന്റെ കൂട്ടുകാരനെപ്പോലെ (യൂനുസ് നബിയെപ്പോലെ) നീ ആകരുത്; അദ്ദേഹം ദുഃഖിതനായി പ്രാർത്ഥിച്ച സന്ദർഭം!».", "malayalamMatn": "അതുകൊണ്ട് നിന്‍റെ രക്ഷിതാവിന്‍റെ വിധി കാത്ത് നീ ക്ഷമിച്ചു കൊള്ളുക. നീ മത്സ്യത്തിന്‍റെ ആളെപ്പോലെ (യൂനുസ് നബിയെപ്പോലെ) ആകരുത്‌. അദ്ദേഹം ദുഃഖനിമഗ്നായികൊണ്ട് വിളിച്ചു പ്രാര്‍ത്ഥിച്ച സന്ദര്‍ഭം."}, {"ayahNumber": 49, "quranText": "لَّوۡلَاۤ أَن تَدَ ٰ⁠رَكَهُۥ نِعۡمَةࣱ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلۡعَرَاۤءِ وَهُوَ مَذۡمُومࣱ\n", "jalalayn": "«لَوْلا أنْ تَدارَكَهُ» لَوْلا أنْ أدْرَكَهُ «نِعْمَة» رَحْمَة «مِن رَبّه لَنُبِذَ» مِن بَطْن الحُوت «بِالعَراءِ» بِالأَرْضِ الفَضاء «وهُوَ مَذْمُوم» لَكِنَّهُ رُحِمَ فَنُبِذَ غَيْر مَذْمُوم", "malayalam": "«തന്റെ രക്ഷിതാവിങ്കൽ നിന്നുള്ള അനുഗ്രഹം അദ്ദേഹത്തെ തുണച്ചിരുന്നില്ലെങ്കിൽ, ആക്ഷേപാർഹനായിക്കൊണ്ട് അദ്ദേഹം തുറന്ന വെളിമ്പ്രദേശത്തേക്ക് വലിച്ചെറിയപ്പെടുമായിരുന്നു».", "malayalamMatn": "അദ്ദേഹത്തിന്‍റെ രക്ഷിതാവിങ്കല്‍ നിന്നുള്ള അനുഗ്രഹം അദ്ദേഹത്തെ വീണ്ടെടുത്തിട്ടില്ലായിരുന്നെങ്കില്‍ അദ്ദേഹം ആ പാഴ്ഭൂമിയില്‍ ആക്ഷേപാര്‍ഹനായിക്കൊണ്ട് പുറന്തള്ളപ്പെടുമായിരുന്നു."}, {"ayahNumber": 50, "quranText": "فَٱجۡتَبَـٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّـٰلِحِینَ\n", "jalalayn": "«فاجْتَباهُ رَبّه» بِالنُّبُوَّةِ «فَجَعَلَهُ مِن الصّالِحِينَ» أيْ مِن الأَنْبِياء", "malayalam": "«എന്നിട്ട് അദ്ദേഹത്തിന്റെ രക്ഷിതാവ് അദ്ദേഹത്തെ തെരഞ്ഞെടുക്കുകയും സജ്ജനങ്ങളിൽ ഉൾപ്പെടുത്തുകയും ചെയ്തു».", "malayalamMatn": "അപ്പോള്‍ അദ്ദേഹത്തിന്‍റെ രക്ഷിതാവ് അദ്ദേഹത്തെ തെരഞ്ഞെടുക്കുകയും എന്നിട്ട് അദ്ദേഹത്തെ സജ്ജനങ്ങളുടെ കൂട്ടത്തിലാക്കുകയും ചെയ്തു."}, {"ayahNumber": 51, "quranText": "وَإِن یَكَادُ ٱلَّذِینَ كَفَرُوا۟ لَیُزۡلِقُونَكَ بِأَبۡصَـٰرِهِمۡ لَمَّا سَمِعُوا۟ ٱلذِّكۡرَ وَیَقُولُونَ إِنَّهُۥ لَمَجۡنُونࣱ\n", "jalalayn": "«وإنْ يَكاد الَّذِينَ كَفَرُوا لَيُزْلِقُونَكَ» بِضَمِّ الياء وفَتْحها «بِأَبْصارِهِمْ» يَنْظُرُونَ إلَيْك نَظَرًا شَدِيدًا يَكاد أنْ يَصْرَعك ويُسْقِطك مِن مَكانك «لَمّا سَمِعُوا الذِّكْر» القُرْآن «ويَقُولُونَ» حَسَدًا «إنّهُ لَمَجْنُون» بِسَبَبِ القُرْآن الَّذِي جاءَ بِهِ", "malayalam": "«സത്യനിഷേധികൾ ആ ഉൽബോധനം (ഖുർആൻ) കേൾക്കുമ്പോൾ തങ്ങളുടെ കണ്ണുകൾ കൊണ്ട് നിന്നെ വീഴ്ത്തിക്കളയുമാറ് നോക്കുന്നു; അസൂയയോടെ അവർ പറയുന്നു: തീർച്ചയായും അവൻ ഭ്രാന്തൻ തന്നെയാകുന്നു!».", "malayalamMatn": "സത്യനിഷേധികള്‍ ഈ ഉല്‍ബോധനം കേള്‍ക്കുമ്പോള്‍ അവരുടെ കണ്ണുകള്‍കൊണ്ട് നോക്കിയിട്ട് നീ ഇടറി വീഴുമാറാക്കുക തന്നെ ചെയ്യും. തീര്‍ച്ചയായും ഇവന്‍ ഒരു ഭ്രാന്തന്‍ തന്നെയാണ് എന്നവര്‍ പറയും."}, {"ayahNumber": 52, "quranText": "وَمَا هُوَ إِلَّا ذِكۡرࣱ لِّلۡعَـٰلَمِینَ\n", "jalalayn": "«وما هُوَ» أيْ القُرْآن «إلّا ذِكْر» مَوْعِظَة «لِلْعالَمِينَ» الجِنّ والإنْس لا يَحْدُث بِسَبَبِ جُنُون", "malayalam": "«എന്നാൽ അത് ലോകർക്കുള്ള ഒരു ഉൽബോധനമല്ലാതെ മറ്റൊന്നുമല്ല».", "malayalamMatn": "ഇത് ലോകര്‍ക്കുള്ള ഒരു ഉല്‍ബോധനമല്ലാതെ മറ്റൊന്നുമല്ല."}], "topPoints": ["പ്രവാചകന്റെ ഉന്നതമായ സ്വഭാവം (خلاصة السورة)", "തോട്ടക്കാരുടെ കഥയും അഹങ്കാരത്തിന്റെ പരിണാമവും"], "topQuestions": [{"q": "നബി(സ)യെ കുറിച്ച് സൂറത്തുൽ ഖലം എന്ത് സാക്ഷ്യപ്പെടുത്തുന്നു?", "a": "തീർച്ചയായും താങ്കൾ മഹത്തായ സ്വഭാവത്തിലാകുന്നു എന്നത്."}], "asbabAlNuzul": [{"ayahNumber": 34, "quranText": "إِنَّ لِلۡمُتَّقِینَ عِندَ رَبِّهِمۡ جَنَّـٰتِ ٱلنَّعِیمِ", "arabicSnippet": "«ولعذاب الآخرة أكبر لو كانوا يعلمون» ونزل لما قال كفار مكة: إن بعثنا في الآخرة كما تزعمون فسنعطى أفضل منكم وأحسن حالا: «إن للمتقين عند ربهم جنات النعيم».", "malayalamExplanation": "മക്കയിലെ സമ്പന്നരായ അവിശ്വാസികൾ പരിഹാസത്തോടെ പറഞ്ഞു: \"ഇനി നിങ്ങൾ പറയുന്നതുപോലെ പരലോകത്ത് ഒരു പുനരുത്ഥാനം ഉണ്ടെങ്കിൽത്തന്നെ, ദുനിയാവിലെപ്പോലെ അവിടെയും ഞങ്ങൾക്കായിരിക്കും നിങ്ങളേക്കാൾ കൂടുതൽ സ്വത്തും പദവിയും നൽകപ്പെടുക!\". അവരുടെ ഈ അഹങ്കാരത്തിന് മറുപടിയായി, പരലോകത്തെ ശാശ്വത സ്വർഗ്ഗത്തോപ്പുകൾ യഥാർത്ഥ ഭയഭക്തിയുള്ള മുത്തഖീങ്ങൾക്ക് മാത്രമുള്ളതാണെന്ന് വ്യക്തമാക്കിക്കൊണ്ട് ഈ വചനം അവതരിച്ചു."}]}, {"surahNumber": 69, "surahNameArabic": "سُورَةُ الحَاقَّةِ", "surahNameMalayalam": "സൂറത്തുൽ ഹാഖ്ഖ (യാഥാർത്ഥ്യം)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ ٱلۡحَاۤقَّةُ\n", "jalalayn": "«الحاقَّة» القِيامَة الَّتِي يَحِقّ فِيها ما أُنْكِرَ مِن البَعْث والحِساب والجَزاء أوْ المُظْهِرَة لِذَلِكَ", "malayalam": "«ആ അനിവാര്യമായ യാഥാർത്ഥ്യം!» (അന്ത്യനാൾ).", "malayalamMatn": "ആ യഥാര്‍ത്ഥ സംഭവം!"}, {"ayahNumber": 2, "quranText": "مَا ٱلۡحَاۤقَّةُ\n", "jalalayn": "«ما الحاقَّة» تَعْظِيم لِشَأْنِها وهُوَ مُبْتَدَأ وخَبَر الحاقَّة", "malayalam": "«എന്താണ് ആ അനിവാര്യമായ യാഥാർത്ഥ്യം?».", "malayalamMatn": "എന്താണ് ആ യഥാര്‍ത്ഥ സംഭവം?"}, {"ayahNumber": 3, "quranText": "وَمَاۤ أَدۡرَىٰكَ مَا ٱلۡحَاۤقَّةُ\n", "jalalayn": "«وما أدْراك» أعْلَمَك «ما الحاقَّة» زِيادَة تَعْظِيم لِشَأْنِها فَما الأُولى مُبْتَدَأ وما بَعْدها خَبَره وما الثّانِيَة وخَبَرها فِي مَحَلّ المَفْعُول الثّانِي لِأَدْرى", "malayalam": "«ആ അനിവാര്യമായ യാഥാർത്ഥ്യം എന്താണെന്ന് നിനക്ക് എന്തറിയാം?».", "malayalamMatn": "ആ യഥാര്‍ത്ഥ സംഭവം എന്താണെന്ന് നിനക്കെന്തറിയാം?"}, {"ayahNumber": 4, "quranText": "كَذَّبَتۡ ثَمُودُ وَعَادُۢ بِٱلۡقَارِعَةِ\n", "jalalayn": "«كَذَّبَتْ ثَمُود وعاد بِالقارِعَةِ» القِيامَة لِأَنَّها تَقْرَع القُلُوب بِأَهْوالِها", "malayalam": "«ഥമൂദ് ജനതയും ആദ് ജനതയും ആ ഭയങ്കര സംഭവത്തെ നിഷേധിച്ചു കളഞ്ഞു».", "malayalamMatn": "ഥമൂദ് സമുദായവും ആദ് സമുദായവും ആ ഭയങ്കര സംഭവത്തെ നിഷേധിച്ചു കളഞ്ഞു."}, {"ayahNumber": 5, "quranText": "فَأَمَّا ثَمُودُ فَأُهۡلِكُوا۟ بِٱلطَّاغِیَةِ\n", "jalalayn": "«فَأَمّا ثَمُود فَأُهْلِكُوا بِالطّاغِيَةِ» بِالصَّيْحَةِ المُجاوِزَة لِلْحَدِّ فِي الشِّدَّة", "malayalam": "«എന്നാൽ ഥമൂദ് ജനത അതിഭയങ്കരമായ ഘോരശബ്ദത്താൽ നശിപ്പിക്കപ്പെട്ടു».", "malayalamMatn": "എന്നാല്‍ ഥമൂദ് സമുദായം അത്യന്തം ഭീകരമായ ഒരു ശിക്ഷ കൊണ്ട് നശിപ്പിക്കപ്പെട്ടു."}, {"ayahNumber": 6, "quranText": "وَأَمَّا عَادࣱ فَأُهۡلِكُوا۟ بِرِیحࣲ صَرۡصَرٍ عَاتِیَةࣲ\n", "jalalayn": "«وأَمّا عاد فَأُهْلِكُوا بِرِيحٍ صَرْصَر عاتِيَة» قَوِيَّة شَدِيدَة عَلى عادٍ مَعَ قُوَّتهمْ وشِدَّتهمْ", "malayalam": "«ആദ് ജനതയാകട്ടെ, അതിശക്തമായി ആഞ്ഞടിക്കുന്ന കൊടുംങ്കാറ്റുകൊണ്ട് നശിപ്പിക്കപ്പെട്ടു».", "malayalamMatn": "എന്നാല്‍ ആദ് സമുദായം, ആഞ്ഞു വീശുന്ന അത്യുഗ്രമായ കാറ്റ് കൊണ്ട് നശിപ്പിക്കപ്പെട്ടു."}, {"ayahNumber": 7, "quranText": "سَخَّرَهَا عَلَیۡهِمۡ سَبۡعَ لَیَالࣲ وَثَمَـٰنِیَةَ أَیَّامٍ حُسُومࣰاۖ فَتَرَى ٱلۡقَوۡمَ فِیهَا صَرۡعَىٰ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلٍ خَاوِیَةࣲ\n", "jalalayn": "«سَخَّرَها» أرْسَلَها بِالقَهْرِ «عَلَيْهِمْ سَبْع لَيالٍ وثَمانِيَة أيّام» أوَّلها مِن صُبْح يَوْم الأَرْبِعاء لِثَمانٍ بَقِينَ مِن شَوّال وكانَتْ فِي عَجُز الشِّتاء «حُسُومًا» مُتَتابِعات شُبِّهَتْ بِتَتابُعِ فِعْل الحاسِم فِي إعادَة الكَيّ عَلى الدّاء كَرَّة بَعْد أُخْرى حَتّى يَنْحَسِم «فَتَرى القَوْم فِيها صَرْعى» مَطْرُوحِينَ هالِكِينَ «كَأَنَّهُمْ أعْجاز» أُصُول «نَخْل خاوِيَة» ساقِطَة فارِغَة", "malayalam": "«തുടർച്ചയായി ഏഴ് രാത്രികളും എട്ട് പകലുകളും അവരുടെ മേൽ അല്ലാഹു അതിനെ അഴിച്ചുവിട്ടു; അപ്പോൾ ആ ജനത പൊള്ളയായ ഈത്തപ്പനത്തടികൾ പോലെ വീണുകിടക്കുന്നത് നിനക്ക് കാണാമായിരുന്നു».", "malayalamMatn": "തുടര്‍ച്ചയായ ഏഴു രാത്രിയും എട്ടു പകലും അത് (കാറ്റ്‌) അവരുടെ നേര്‍ക്ക് അവന്‍ തിരിച്ചുവിട്ടു. അപ്പോള്‍ കടപുഴകി വീണ ഈന്തപ്പനത്തടികള്‍ പോലെ ആ കാറ്റില്‍ ജനങ്ങള്‍ വീണുകിടക്കുന്നതായി നിനക്ക് കാണാം."}, {"ayahNumber": 8, "quranText": "فَهَلۡ تَرَىٰ لَهُم مِّنۢ بَاقِیَةࣲ\n", "jalalayn": "«فَهَلْ تَرى لَهُمْ مِن باقِيَة» لا تَرى لَهُمْ باقِيَة", "malayalam": "«അവരിൽ ആരെങ്കിലും അവശേഷിച്ചതായി നീ കാണുന്നുണ്ടോ?».", "malayalamMatn": "ഇനി അവരുടെതായി അവശേഷിക്കുന്ന വല്ലതും നീ കാണുന്നുണ്ടോ?"}, {"ayahNumber": 9, "quranText": "وَجَاۤءَ فِرۡعَوۡنُ وَمَن قَبۡلَهُۥ وَٱلۡمُؤۡتَفِكَـٰتُ بِٱلۡخَاطِئَةِ\n", "jalalayn": "«وجاءَ فِرْعَوْن ومَن قَبَله» أتْباعه وفِي قِراءَة بِفَتْحِ القاف وسُكُون الباء أيْ مَن تَقَدَّمَهُ مِن الأُمَم الكافِرَة «والمُؤْتَفِكات» أيْ أهْلها وهِيَ قُرى قَوْم لُوط «بِالخاطِئَةِ» بِالفِعْلاتِ ذات الخَطَأ", "malayalam": "«ഫിർഔനും അവന് മുമ്പുള്ളവരും കീഴ്മേൽ മറിഞ്ഞ നാട്ടുകാരും (ലൂത്വിന്റെ ജനതയും) മഹാപാപങ്ങളുമായി വന്നു».", "malayalamMatn": "ഫിര്‍ഔനും, അവന്‍റെ മുമ്പുള്ളവരും കീഴ്മേല്‍ മറിഞ്ഞ രാജ്യങ്ങളും (തെറ്റായ പ്രവര്‍ത്തനം കൊണ്ടു വന്നു."}, {"ayahNumber": 10, "quranText": "فَعَصَوۡا۟ رَسُولَ رَبِّهِمۡ فَأَخَذَهُمۡ أَخۡذَةࣰ رَّابِیَةً\n", "jalalayn": "«فَعَصَوْا رَسُول رَبّهمْ» أيْ لُوطًا وغَيْره «فَأَخَذَهُمْ أخْذَة رابِيَة» زائِدَة فِي الشِّدَّة عَلى غَيْرها", "malayalam": "«അങ്ങനെ അവർ തങ്ങളുടെ രക്ഷിതാവിന്റെ റസൂലിനോട് അനുസരണക്കേട് കാണിച്ചു; അപ്പോൾ അവൻ അവരെ അതിശക്തമായ പിടിത്തം കൊണ്ട് പിടികൂടി».", "malayalamMatn": "അവര്‍ അവരുടെ രക്ഷിതാവിന്‍റെ ദൂതനെ ധിക്കരിക്കുകയും, അപ്പോള്‍ അവന്‍ അവരെ ശക്തിയേറിയ ഒരു പിടുത്തം പിടിക്കുകയും ചെയ്തു."}, {"ayahNumber": 11, "quranText": "إِنَّا لَمَّا طَغَا ٱلۡمَاۤءُ حَمَلۡنَـٰكُمۡ فِی ٱلۡجَارِیَةِ\n", "jalalayn": "«إنّا لَمّا طَغى الماء» عَلا فَوْق كُلّ شَيْء مِن الجِبال وغَيْرها زَمَن الطُّوفان «حَمَلْناكُمْ» يَعْنِي آباءَكُمْ إذْ أنْتُمْ فِي أصْلابهمْ «فِي الجارِيَة» السَّفِينَة الَّتِي عَمِلَها نُوح ونَجا هُوَ ومَن كانَ مَعَهُ فِيها وغَرِقَ الآخَرُونَ", "malayalam": "«വെള്ളം അതിരുകവിഞ്ഞപ്പോൾ തീർച്ചയായും ആ കപ്പലിൽ നിങ്ങളെ നാമാണ് കയറ്റി വഹിച്ചത്».", "malayalamMatn": "തീര്‍ച്ചയായും നാം, വെള്ളം അതിരുകവിഞ്ഞ സമയത്ത് നിങ്ങളെ കപ്പലില്‍ കയറ്റി രക്ഷിക്കുകയുണ്ടായി."}, {"ayahNumber": 12, "quranText": "لِنَجۡعَلَهَا لَكُمۡ تَذۡكِرَةࣰ وَتَعِیَهَاۤ أُذُنࣱ وَ ٰ⁠عِیَةࣱ\n", "jalalayn": "«لِنَجْعَلها» أيْ هَذِهِ الفَعْلَة وهِيَ إنْجاء المُؤْمِنِينَ وإهْلاك الكافِرِينَ «لَكُمْ تَذْكِرَة» عِظَة «وتَعِيها» ولِتَحْفَظها «أُذُن واعِيَة» حافِظَة لِما تَسْمَع", "malayalam": "«അതിനെ നിങ്ങൾക്കൊരു ഉൽബോധനമാക്കുവാനും ശ്രദ്ധിച്ചു കേൾക്കുന്ന കാതുകൾ അത് ഓർത്തുവെക്കുവാനും വേണ്ടി».", "malayalamMatn": "നിങ്ങള്‍ക്ക് നാം അതൊരു സ്മരണയാക്കുവാനും ശ്രദ്ധിച്ചു മനസ്സിലാക്കുന്ന കാതുകള്‍ അത് ശ്രദ്ധിച്ചു മനസ്സിലാക്കുവാനും വേണ്ടി."}, {"ayahNumber": 13, "quranText": "فَإِذَا نُفِخَ فِی ٱلصُّورِ نَفۡخَةࣱ وَ ٰ⁠حِدَةࣱ\n", "jalalayn": "«فَإذا نُفِخَ فِي الصُّور نَفْخَة واحِدَة» لِلْفَصْلِ بَيْن الخَلائِق وهِيَ الثّانِيَة", "malayalam": "«എന്നിട്ട് കാഹളത്തിൽ ഒരൊറ്റ ഊത്ത് ഊതപ്പെട്ടാൽ!».", "malayalamMatn": "കാഹളത്തില്‍ ഒരു ഊത്ത് ഊതപ്പെട്ടാല്‍,"}, {"ayahNumber": 14, "quranText": "وَحُمِلَتِ ٱلۡأَرۡضُ وَٱلۡجِبَالُ فَدُكَّتَا دَكَّةࣰ وَ ٰ⁠حِدَةࣰ\n", "jalalayn": "«وحُمِلَتْ» رُفِعَتْ «الأَرْض والجِبال فَدُكَّتا» دُقَّتا", "malayalam": "«ഭൂമിയും പർവ്വതങ്ങളും ഉയർത്തപ്പെടുകയും ഒരൊറ്റ ഇടിയോടെ അവ രണ്ടും പൊടിപൊടിയാക്കപ്പെടുകയും ചെയ്താൽ!».", "malayalamMatn": "ഭൂമിയും പര്‍വ്വതങ്ങളും പൊക്കിയെടുക്കപ്പെടുകയും എന്നിട്ട് അവ രണ്ടും ഒരു ഇടിച്ചു തകര്‍ക്കലിന് വിധേയമാക്കപ്പെടുകയും ചെയ്താല്‍!"}, {"ayahNumber": 15, "quranText": "فَیَوۡمَىِٕذࣲ وَقَعَتِ ٱلۡوَاقِعَةُ\n", "jalalayn": "«فَيَوْمئِذٍ وقَعَتْ الواقِعَة» قامَتْ القِيامَة", "malayalam": "«അന്നേ ദിവസം ആ മഹത്സംഭവം സംഭവിക്കുകയായി!».", "malayalamMatn": "അന്നേ ദിവസം ആ സംഭവം സംഭവിക്കുകയായി."}, {"ayahNumber": 16, "quranText": "وَٱنشَقَّتِ ٱلسَّمَاۤءُ فَهِیَ یَوۡمَىِٕذࣲ وَاهِیَةࣱ\n", "jalalayn": "«وانْشَقَّتْ السَّماء فَهِيَ يَوْمئِذٍ واهِيَة» ضَعِيفَة", "malayalam": "«ആകാശം പൊട്ടിപ്പിളരുകയും ചെയ്യും; അന്നേ ദിവസം അത് തികച്ചും ദുർബലമായിരിക്കും».", "malayalamMatn": "ആകാശം പൊട്ടിപ്പിളരുകയും ചെയ്യും. അന്ന് അത് ദുര്‍ബലമായിരിക്കും."}, {"ayahNumber": 17, "quranText": "وَٱلۡمَلَكُ عَلَىٰۤ أَرۡجَاۤىِٕهَاۚ وَیَحۡمِلُ عَرۡشَ رَبِّكَ فَوۡقَهُمۡ یَوۡمَىِٕذࣲ ثَمَـٰنِیَةࣱ\n", "jalalayn": "«والمَلَك» يَعْنِي: المَلائِكَة «عَلى أرْجائِها» جَوانِب السَّماء «ويَحْمِل عَرْش رَبّك فَوْقهمْ» أيْ المَلائِكَة المَذْكُورِينَ «يَوْمئِذٍ ثَمانِيَة» مِن المَلائِكَة أوْ مِن صُفُوفهمْ", "malayalam": "«മലക്കുകൾ അതിന്റെ അതിരുകളിലുണ്ടായിരിക്കും; നിന്റെ രക്ഷിതാവിന്റെ അർശിനെ അന്നേ ദിവസം എട്ട് മലക്കുകൾ തങ്ങൾക്ക് മീതെ വഹിക്കുന്നതാണ്».", "malayalamMatn": "മലക്കുകള്‍ അതിന്‍റെ നാനാഭാഗങ്ങളിലുമുണ്ടായിരിക്കും. നിന്‍റെ രക്ഷിതാവിന്‍റെ സിംഹാസനത്തെ അവരുടെ മീതെ അന്നു എട്ടുകൂട്ടര്‍ വഹിക്കുന്നതാണ്‌."}, {"ayahNumber": 18, "quranText": "یَوۡمَىِٕذࣲ تُعۡرَضُونَ لَا تَخۡفَىٰ مِنكُمۡ خَافِیَةࣱ\n", "jalalayn": "«يَوْمئِذٍ تُعْرَضُونَ» لِلْحِسابِ «لا تَخْفى» بِالتّاءِ والياء «مِنكُمْ خافِيَة» مِن السَّرائِر", "malayalam": "«അന്നേ ദിവസം നിങ്ങൾ വിചാരണക്കായി ഹാജരാക്കപ്പെടും; നിങ്ങളുടെ യാതൊരു രഹസ്യവും മറഞ്ഞുകിടക്കുകയില്ല».", "malayalamMatn": "അന്നേ ദിവസം നിങ്ങള്‍ പ്രദര്‍ശിപ്പിക്കപ്പെടുന്നതാണ്‌. യാതൊരു മറഞ്ഞകാര്യവും നിങ്ങളില്‍ നിന്ന് മറഞ്ഞു പോകുന്നതകല്ല."}, {"ayahNumber": 19, "quranText": "فَأَمَّا مَنۡ أُوتِیَ كِتَـٰبَهُۥ بِیَمِینِهِۦ فَیَقُولُ هَاۤؤُمُ ٱقۡرَءُوا۟ كِتَـٰبِیَهۡ\n", "jalalayn": "«فَأَمّا مَن أُوتِيَ كِتابه بِيَمِينِهِ فَيَقُول» خِطابًا لِجَماعَتِهِ لِما سُرَّ بِهِ «هاؤُمُ» خُذُوا «اقْرَءُوا كِتابِي» تَنازَعَ فِيهِ هاؤُمُ واقْرَءُوا", "malayalam": "«അപ്പോൾ തന്റെ കർമ്മരേഖ വലതുകയ്യിൽ നൽകപ്പെട്ടവൻ പറയും: ഇതാ, നിങ്ങൾ എന്റെ രേഖ വായിച്ചു നോക്കൂ!».", "malayalamMatn": "എന്നാല്‍ വലതുകൈയില്‍ തന്‍റെ രേഖ നല്‍കപ്പെട്ടവന്‍ പറയും: ഇതാ എന്‍റെ ഗ്രന്ഥം വായിച്ചുനോക്കൂ."}, {"ayahNumber": 20, "quranText": "إِنِّی ظَنَنتُ أَنِّی مُلَـٰقٍ حِسَابِیَهۡ\n", "jalalayn": "«إنِّي ظَنَنْت» تَيَقَّنْت", "malayalam": "«തീർച്ചയായും ഞാൻ എന്റെ വിചാരണയെ അഭിമുഖീകരിക്കേണ്ടി വരുമെന്ന് ഉറച്ചു വിശ്വസിച്ചിരുന്നു!».", "malayalamMatn": "തീര്‍ച്ചയായും ഞാന്‍ വിചാരിച്ചിരുന്നു. ഞാന്‍ എന്‍റെ വിചാരണയെ നേരിടേണ്ടി വരുമെന്ന്‌."}, {"ayahNumber": 21, "quranText": "فَهُوَ فِی عِیشَةࣲ رَّاضِیَةࣲ\n", "jalalayn": "«فَهُوَ فِي عِيشَة راضِيَة» مَرْضِيَّة", "malayalam": "«അങ്ങനെ അവൻ സംതൃപ്തമായ ജീവിതത്തിലായിരിക്കും».", "malayalamMatn": "അതിനാല്‍ അവന്‍ തൃപ്തികരമായ ജീവിതത്തിലാകുന്നു."}, {"ayahNumber": 22, "quranText": "فِی جَنَّةٍ عَالِیَةࣲ\n", "jalalayn": "«فِی جَنَّةٍ عَالِیَةࣲ».", "malayalam": "«ഉന്നതമായ സ്വർഗ്ഗത്തിൽ».", "malayalamMatn": "ഉന്നതമായ സ്വര്‍ഗത്തില്‍."}, {"ayahNumber": 23, "quranText": "قُطُوفُهَا دَانِیَةࣱ\n", "jalalayn": "«قُطُوفها» ثِمارها «دانِيَة» قَرِيبَة يَتَناوَلها القائِم والقاعِد والمُضْطَجِع", "malayalam": "«അതിലെ പഴങ്ങൾ കൈയെത്തും ദൂരത്തുള്ളതായിരിക്കും».", "malayalamMatn": "അവയിലെ പഴങ്ങള്‍ അടുത്തു വരുന്നവയാകുന്നു."}, {"ayahNumber": 24, "quranText": "كُلُوا۟ وَٱشۡرَبُوا۟ هَنِیۤـَٔۢا بِمَاۤ أَسۡلَفۡتُمۡ فِی ٱلۡأَیَّامِ ٱلۡخَالِیَةِ\n", "jalalayn": "فَيُقال لَهُمْ «كُلُوا واشْرَبُوا هَنِيئًا» حال أيْ مُتَهَنِّئِينَ «بِما أسْلَفْتُمْ فِي الأَيّام الخالِيَة» الماضِيَة فِي الدُّنْيا", "malayalam": "«കഴിഞ്ഞുപോയ ദിനങ്ങളിൽ നിങ്ങൾ മുൻകൂട്ടി ചെയ്ത സൽകർമ്മങ്ങൾക്കായിക്കൊണ്ട് നിങ്ങൾ സന്തോഷത്തോടെ തിന്നുകയും കുടിക്കുകയും ചെയ്യുവിൻ!».", "malayalamMatn": "കഴിഞ്ഞുപോയ ദിവസങ്ങളില്‍ നിങ്ങള്‍ മുന്‍കൂട്ടി ചെയ്തതിന്‍റെ ഫലമായി നിങ്ങള്‍ ആനന്ദത്തോടെ തിന്നുകയും കുടിക്കുകയും ചെയ്തു കൊള്ളുക. (എന്ന് അവരോട് പറയപ്പെടും.)"}, {"ayahNumber": 25, "quranText": "وَأَمَّا مَنۡ أُوتِیَ كِتَـٰبَهُۥ بِشِمَالِهِۦ فَیَقُولُ یَـٰلَیۡتَنِی لَمۡ أُوتَ كِتَـٰبِیَهۡ\n", "jalalayn": "«وأَمّا مَن أُوتِيَ كِتابه بِشِمالِهِ فَيَقُول يا» لِلتَّنْبِيهِ", "malayalam": "«എന്നാൽ തന്റെ കർമ്മരേഖ ഇടതുകയ്യിൽ നൽകപ്പെട്ടവൻ പറയും: എന്റെ കഷ്ടമേ, എനിക്ക് എന്റെ രേഖ നൽകപ്പെടാതിരുന്നെങ്കിൽ എത്ര നന്നായിരുന്നു!».", "malayalamMatn": "എന്നാല്‍ ഇടതു കയ്യില്‍ ഗ്രന്ഥം നല്‍കപ്പെട്ടവനാകട്ടെ ഇപ്രകാരം പറയുന്നതാണ്‌. ഹാ! എന്‍റെ ഗ്രന്ഥം എനിക്ക് നല്‍കപ്പെടാതിരുന്നെങ്കില്‍,"}, {"ayahNumber": 26, "quranText": "وَلَمۡ أَدۡرِ مَا حِسَابِیَهۡ\n", "jalalayn": "«وَلَمۡ أَدۡرِ مَا حِسَابِیَهۡ».", "malayalam": "«എന്റെ വിചാരണ എന്താണെന്ന് ഞാൻ അറിയാതിരുന്നെങ്കിൽ!».", "malayalamMatn": "എന്‍റെ വിചാരണ എന്താണെന്ന് ഞാന്‍ അറിയാതിരുന്നെങ്കില്‍ (എത്ര നന്നായിരുന്നു.)"}, {"ayahNumber": 27, "quranText": "یَـٰلَیۡتَهَا كَانَتِ ٱلۡقَاضِیَةَ\n", "jalalayn": "«يا لَيْتَها» أيْ المَوْتَة فِي الدُّنْيا «كانَتْ القاضِيَهْ» القاطِعَة لِحَياتِي بِأَنْ لا أُبْعَث", "malayalam": "«മരണം തന്നെ എന്നെന്നേക്കുമായി എല്ലാം അവസാനിപ്പിച്ചിരുന്നെങ്കിൽ!».", "malayalamMatn": "അത് (മരണം) എല്ലാം അവസാനിപ്പിക്കുന്നതായിരുന്നെങ്കില്‍ (എത്ര നന്നായിരുന്നു!)"}, {"ayahNumber": 28, "quranText": "مَاۤ أَغۡنَىٰ عَنِّی مَالِیَهۡۜ\n", "jalalayn": "«مَاۤ أَغۡنَىٰ عَنِّی مَالِیَهۡۜ».", "malayalam": "«എന്റെ ധനം എനിക്ക് ഒട്ടും ഉപകരിച്ചില്ലല്ലോ!».", "malayalamMatn": "എന്‍റെ ധനം എനിക്ക് പ്രയോജനപ്പെട്ടില്ല."}, {"ayahNumber": 29, "quranText": "هَلَكَ عَنِّی سُلۡطَـٰنِیَهۡ\n", "jalalayn": "«هَلَكَ عَنِّي سُلْطانِيَهْ» قُوَّتِي وحُجَّتِي وهاء كِتابِيَهْ وحِسابِيَهْ ومالِيَهْ وسُلْطانِيَهْ لِلسَّكْتِ تَثْبُت وقْفًا ووَصْلًا اتِّباعًا لِلْمُصْحَفِ الإمام والنَّقْل ومِنهُمْ مَن حَذَفَها وصْلًا", "malayalam": "«എന്റെ സർവ്വ അധികാരങ്ങളും എന്നിൽ നിന്ന് നശിച്ചുപോയല്ലോ!».", "malayalamMatn": "എന്‍റെ അധികാരം എന്നില്‍ നിന്ന് നഷ്ടപ്പെട്ടുപോയി."}, {"ayahNumber": 30, "quranText": "خُذُوهُ فَغُلُّوهُ\n", "jalalayn": "«خُذُوهُ» خِطاب لِخَزَنَةِ جَهَنَّم «فَغُلُّوهُ» اجْمَعُوا يَدَيْهِ إلى عُنُقه فِي الغُلّ", "malayalam": "«അവനെ നിങ്ങൾ പിടികൂടൂ, എന്നിട്ട് അവനെ ബന്ധിക്കൂ! (എന്ന് നരകകാവൽക്കാരോട് അല്ലാഹു കൽപിക്കും)».", "malayalamMatn": "(അപ്പോള്‍ ഇപ്രകാരം കല്‍പനയുണ്ടാകും:) നിങ്ങള്‍ അവനെ പിടിച്ച് ബന്ധനത്തിലിടൂ."}, {"ayahNumber": 31, "quranText": "ثُمَّ ٱلۡجَحِیمَ صَلُّوهُ\n", "jalalayn": "«ثُمَّ الجَحِيم» النّار المُحْرِقَة «صَلُّوهُ» أدْخِلُوهُ", "malayalam": "«പിന്നീട് ജ്വലിക്കുന്ന നരകാഗ്നിയിൽ അവനെ എരിക്കൂ!».", "malayalamMatn": "പിന്നെ അവനെ നിങ്ങള്‍ ജ്വലിക്കുന്ന നരകത്തില്‍ പ്രവേശിപ്പിക്കൂ."}, {"ayahNumber": 32, "quranText": "ثُمَّ فِی سِلۡسِلَةࣲ ذَرۡعُهَا سَبۡعُونَ ذِرَاعࣰا فَٱسۡلُكُوهُ\n", "jalalayn": "«ثُمَّ فِي سَلْسَلَة ذَرْعها سَبْعُونَ ذِراعًا» بِذِراعِ المَلَك «فاسْلُكُوهُ» أدْخِلُوهُ فِيها بَعْد إدْخاله النّار ولَمْ تَمْنَع الفاء مِن تَعَلُّق الفِعْل بِالظَّرْفِ المُتَقَدِّم", "malayalam": "«പിന്നെ എഴുപത് മുഴം നീളമുള്ള ചങ്ങലയിൽ അവനെ കോർത്തു കെട്ടൂ!».", "malayalamMatn": "പിന്നെ, എഴുപത് മുഴം നീളമുള്ള ഒരു ചങ്ങലയില്‍ അവനെ നിങ്ങള്‍ പ്രവേശിപ്പിക്കൂ."}, {"ayahNumber": 33, "quranText": "إِنَّهُۥ كَانَ لَا یُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِیمِ\n", "jalalayn": "«إِنَّهُۥ كَانَ لَا یُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِیمِ».", "malayalam": "«കാരണം അവൻ മഹാനായ അല്ലാഹുവിൽ വിശ്വസിച്ചിരുന്നില്ല».", "malayalamMatn": "തീര്‍ച്ചയായും അവന്‍ മഹാനായ അല്ലാഹുവില്‍ വിശ്വസിച്ചിരുന്നില്ല."}, {"ayahNumber": 34, "quranText": "وَلَا یَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِینِ\n", "jalalayn": "«وَلَا یَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِینِ».", "malayalam": "«അഗതിക്ക് ഭക്ഷണം നൽകാൻ അവൻ പ്രേരിപ്പിച്ചിരുന്നുമില്ല».", "malayalamMatn": "സാധുവിന് ഭക്ഷണം കൊടുക്കുവാന്‍ അവന്‍ പ്രോത്സാഹിപ്പിച്ചിരുന്നുമില്ല."}, {"ayahNumber": 35, "quranText": "فَلَیۡسَ لَهُ ٱلۡیَوۡمَ هَـٰهُنَا حَمِیمࣱ\n", "jalalayn": "«فَلَيْسَ لَهُ اليَوْم هاهُنا حَمِيم» قَرِيب يَنْتَفِع بِهِ", "malayalam": "«ആകയാൽ ഇന്ന് അവനിവിടെ യാതൊരു ഉറ്റമിത്രവുമില്ല».", "malayalamMatn": "അതിനാല്‍ ഇന്ന് ഇവിടെ അവന്ന് ഒരു ഉറ്റബന്ധുവുമില്ല."}, {"ayahNumber": 36, "quranText": "وَلَا طَعَامٌ إِلَّا مِنۡ غِسۡلِینࣲ\n", "jalalayn": "«ولا طَعام إلّا مِن غِسْلِين» صَدِيد أهْل النّار أوْ شَجَر فِيها", "malayalam": "«നരകവാസികളുടെ വ്രണങ്ങളിൽ നിന്ന് ഒഴുകുന്ന ചലമല്ലാതെ യാതൊരു ഭക്ഷണവുമില്ല».", "malayalamMatn": "ദുര്‍നീരുകള്‍ ഒലിച്ചു കൂടിയതില്‍ നിന്നല്ലാതെ മറ്റു ആഹാരവുമില്ല."}, {"ayahNumber": 37, "quranText": "لَّا یَأۡكُلُهُۥۤ إِلَّا ٱلۡخَـٰطِـُٔونَ\n", "jalalayn": "«لا يَأْكُلهُ إلّا الخاطِئُونَ» الكافِرُونَ", "malayalam": "«മഹാപാപികളല്ലാതെ അത് ഭക്ഷിക്കുകയില്ല».", "malayalamMatn": "തെറ്റുകാരല്ലാതെ അതു ഭക്ഷിക്കുകയില്ല."}, {"ayahNumber": 38, "quranText": "فَلَاۤ أُقۡسِمُ بِمَا تُبۡصِرُونَ\n", "jalalayn": "«فَلا» زائِدَة «أُقْسِم بِما تُبْصِرُونَ» مِن المَخْلُوقات", "malayalam": "«നിങ്ങൾ കാണുന്നവയെക്കൊണ്ട് ഞാൻ സത്യം ചെയ്തു പറയുന്നു».", "malayalamMatn": "എന്നാല്‍ നിങ്ങള്‍ കാണുന്നവയെക്കൊണ്ട് ഞാന്‍ സത്യം ചെയ്ത് പറയുന്നു:"}, {"ayahNumber": 39, "quranText": "وَمَا لَا تُبۡصِرُونَ\n", "jalalayn": "«وما لا تُبْصِرُونَ» مِنها أيْ بِكُلِّ مَخْلُوق", "malayalam": "«നിങ്ങൾ കാണാത്തവയെക്കൊണ്ടും».", "malayalamMatn": "നിങ്ങള്‍ കാണാത്തവയെക്കൊണ്ടും"}, {"ayahNumber": 40, "quranText": "إِنَّهُۥ لَقَوۡلُ رَسُولࣲ كَرِیمࣲ\n", "jalalayn": "«إنّهُ» أيْ القُرْآن «لَقَوْل رَسُول كَرِيم» أيْ قالَهُ رِسالَة عَنْ اللَّه تَعالى", "malayalam": "«തീർച്ചയായും ഇത് ആദരണീയനായ ഒരു റസൂലിന്റെ വാക്ക് തന്നെയാകുന്നു» (ജിബ്‌രീൽ അല്ലാഹുവിങ്കൽ നിന്ന് കൊണ്ടുവന്നത്).", "malayalamMatn": "തീര്‍ച്ചയായും ഇത് മാന്യനായ ഒരു ദൂതന്‍റെ വാക്കു തന്നെയാകുന്നു."}, {"ayahNumber": 41, "quranText": "وَمَا هُوَ بِقَوۡلِ شَاعِرࣲۚ قَلِیلࣰا مَّا تُؤۡمِنُونَ\n", "jalalayn": "«وَمَا هُوَ بِقَوۡلِ شَاعِرࣲۚ قَلِیلࣰا مَّا تُؤۡمِنُونَ».", "malayalam": "«ഇതൊരു കവിയുടെ വാക്കല്ല; വളരെ കുറഞ്ഞ തോതിലേ നിങ്ങൾ വിശ്വസിക്കുന്നുള്ളൂ!».", "malayalamMatn": "ഇതൊരു കവിയുടെ വാക്കല്ല. വളരെ കുറച്ചേ നിങ്ങള്‍ വിശ്വസിക്കുന്നുള്ളൂ."}, {"ayahNumber": 42, "quranText": "وَلَا بِقَوۡلِ كَاهِنࣲۚ قَلِیلࣰا مَّا تَذَكَّرُونَ\n", "jalalayn": "«ولا بِقَوْلِ كاهِن قَلِيلًا ما تَذَكَّرُونَ» بِالتّاءِ والياء فِي الفِعْلَيْنِ وما مَزِيدَة مُؤَكَّدَة والمَعْنى أنَّهُمْ آمَنُوا بِأَشْياء يَسِيرَة وتَذْكُرُوها مِمّا أتى بِهِ النَّبِيّ ﷺ مِن الخَيْر والصِّلَة والعَفاف فَلَمْ تُغْنِ عَنْهُمْ شَيْئًا", "malayalam": "«ഒരു ജോത്സ്യന്റെ വാക്കുമല്ല; വളരെ കുറഞ്ഞ തോതിലേ നിങ്ങൾ ആലോചിക്കുന്നുള്ളൂ!».", "malayalamMatn": "ഒരു ജ്യോത്സ്യന്‍റെ വാക്കുമല്ല. വളരെക്കുറച്ചേ നിങ്ങള്‍ ആലോചിച്ചു മനസ്സിലാക്കുന്നുള്ളൂ."}, {"ayahNumber": 43, "quranText": "تَنزِیلࣱ مِّن رَّبِّ ٱلۡعَـٰلَمِینَ\n", "jalalayn": "بَلْ هُوَ «تَنْزِيل مِن رَبّ العالَمِينَ»", "malayalam": "«സർവ്വലോക രക്ഷിതാവിങ്കൽ നിന്ന് അവതരിപ്പിക്കപ്പെട്ടതാകുന്നു ഇത്».", "malayalamMatn": "ഇത് ലോകരക്ഷിതാവിങ്കല്‍ നിന്ന് അവതരിപ്പിക്കപ്പെട്ടതാകുന്നു."}, {"ayahNumber": 44, "quranText": "وَلَوۡ تَقَوَّلَ عَلَیۡنَا بَعۡضَ ٱلۡأَقَاوِیلِ\n", "jalalayn": "«ولَوْ تَقَوَّلَ» أيْ النَّبِيّ «عَلَيْنا بَعْض الأَقاوِيل» بِأَنْ قالَ عَنّا ما لَمْ نَقُلْهُ", "malayalam": "«നമ്മുടെ പേരിൽ അദ്ദേഹം വല്ല വാക്കും കെട്ടിച്ചമച്ചുണ്ടാക്കിയിരുന്നുവെങ്കിൽ».", "malayalamMatn": "നമ്മുടെ പേരില്‍ അദ്ദേഹം (പ്രവാചകന്‍) വല്ല വാക്കും കെട്ടിച്ചമച്ചു പറഞ്ഞിരുന്നെങ്കില്‍"}, {"ayahNumber": 45, "quranText": "لَأَخَذۡنَا مِنۡهُ بِٱلۡیَمِینِ\n", "jalalayn": "«لَأَخَذْنا» لِنَلِنا «مِنهُ» عِقابًا «بِاليَمِينِ» بِالقُوَّةِ والقُدْرَة", "malayalam": "«അദ്ദേഹത്തെ നാം വലതുകൈ കൊണ്ട് പിടികൂടുമായിരുന്നു».", "malayalamMatn": "അദ്ദേഹത്തെ നാം വലതുകൈ കൊണ്ട് പിടികൂടുകയും,"}, {"ayahNumber": 46, "quranText": "ثُمَّ لَقَطَعۡنَا مِنۡهُ ٱلۡوَتِینَ\n", "jalalayn": "«ثُمَّ لَقَطَعْنا مِنهُ الوَتِين» نِياط القَلْب وهُوَ عِرْق مُتَّصِل بِهِ إذا انْقَطَعَ ماتَ صاحِبه", "malayalam": "«പിന്നീട് അദ്ദേഹത്തിന്റെ ജീവനാഡിയെ നാം അറുത്തുകളയുമായിരുന്നു».", "malayalamMatn": "എന്നിട്ട് അദ്ദേഹത്തിന്‍റെ ജീവനാഡി നാം മുറിച്ചുകളയുകയും ചെയ്യുമായിരുന്നു."}, {"ayahNumber": 47, "quranText": "فَمَا مِنكُم مِّنۡ أَحَدٍ عَنۡهُ حَـٰجِزِینَ\n", "jalalayn": "«فَما مِنكُمْ مِن أحَد» هُوَ اسْم ما ومِن زائِدَة لِتَأْكِيدِ النَّفْي ومِنكُمْ حال مِن أحَد «عَنْهُ حاجِزِينَ» مانِعِينَ خَبَر ما وجُمِعَ لِأَنَّ أحَدًا فِي سِياق النَّفْي بِمَعْنى الجَمْع وضَمِير عَنْهُ لِلنَّبِيِّ ﷺ أيْ لا مانِع لَنا عَنْهُ مِن حَيْثُ العِقاب", "malayalam": "«അപ്പോൾ നിങ്ങളിൽ ഒരാൾക്കും അദ്ദേഹത്തിൽ നിന്ന് അതിനെ തടയാൻ സാധിക്കുമായിരുന്നില്ല».", "malayalamMatn": "അപ്പോള്‍ നിങ്ങളില്‍ ആര്‍ക്കും അദ്ദേഹത്തില്‍ നിന്ന് (ശിക്ഷയെ) തടയാനാവില്ല."}, {"ayahNumber": 48, "quranText": "وَإِنَّهُۥ لَتَذۡكِرَةࣱ لِّلۡمُتَّقِینَ\n", "jalalayn": "«وإنَّهُ» أيْ القُرْآن", "malayalam": "«തീർച്ചയായും ഇത് ഭയഭക്തിയുള്ളവർക്ക് ഒരു ഉൽബോധനമാകുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും ഇത് (ഖുര്‍ആന്‍) ഭയഭക്തിയുള്ളവര്‍ക്ക് ഒരു ഉല്‍ബോധനമാകുന്നു."}, {"ayahNumber": 49, "quranText": "وَإِنَّا لَنَعۡلَمُ أَنَّ مِنكُم مُّكَذِّبِینَ\n", "jalalayn": "«وإنّا لَنَعْلَم أنَّ مِنكُمْ» أيّها النّاس «مُكَذِّبِينَ» بِالقُرْآنِ ومُصَدِّقِينَ", "malayalam": "«നിങ്ങളിൽ ഇതിനെ തള്ളിപ്പറയുന്നവരുണ്ടെന്ന് തീർച്ചയായും നാം അറിയുന്നുണ്ട്».", "malayalamMatn": "തീര്‍ച്ചയായും നിങ്ങളുടെ കൂട്ടത്തില്‍ (ഇതിനെ) നിഷേധിച്ചു തള്ളുന്നവരുണ്ടെന്ന് നമുക്കറിയാം."}, {"ayahNumber": 50, "quranText": "وَإِنَّهُۥ لَحَسۡرَةٌ عَلَى ٱلۡكَـٰفِرِینَ\n", "jalalayn": "«وإنَّهُ» أيْ القُرْآن «لَحَسْرَة عَلى الكافِرِينَ» إذا رَأَوْا ثَواب المُصَدِّقِينَ وعِقاب المُكَذِّبِينَ بِهِ", "malayalam": "«തീർച്ചയായും ഇത് സത്യനിഷേധികൾക്ക് വലിയൊരു ഖേദമായിത്തീരും».", "malayalamMatn": "തീര്‍ച്ചയായും ഇത് സത്യനിഷേധികള്‍ക്ക് ഖേദത്തിന് കാരണവുമാകുന്നു."}, {"ayahNumber": 51, "quranText": "وَإِنَّهُۥ لَحَقُّ ٱلۡیَقِینِ\n", "jalalayn": "«وإنَّهُ» أيْ القُرْآن «لَحَقّ اليَقِين» أيْ اليَقِين الحَقّ", "malayalam": "«തീർച്ചയായും ഇത് സംശയരഹിതമായ പരമയാഥാർത്ഥ്യം തന്നെയാണ്».", "malayalamMatn": "തീര്‍ച്ചയായും ഇത് ദൃഢമായ യാഥാര്‍ത്ഥ്യമാകുന്നു."}, {"ayahNumber": 52, "quranText": "فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِیمِ\n", "jalalayn": "«فَسَبِّحْ» نَزِّهْ «بِاسْمِ» الباء زائِدَة «رَبّك العَظِيم» سُبْحانه", "malayalam": "«ആകയാൽ മഹാനായ നിന്റെ രക്ഷിതാവിന്റെ നാമത്തെ നീ പ്രകീർത്തിക്കുക».", "malayalamMatn": "അതിനാല്‍ നീ നിന്‍റെ മഹാനായ രക്ഷിതാവിന്‍റെ നാമത്തെ പ്രകീര്‍ത്തിക്കുക."}], "topPoints": ["അന്ത്യനാളിന്റെ ഭീകരത (خلاصة السورة)", "സൽക്കർമ്മികൾക്കും ദുഷ്കർമ്മികൾക്കുമുള്ള പ്രതിഫലം"], "topQuestions": [{"q": "ഹാഖ്ഖ എന്നാൽ എന്ത്?", "a": "അനിവാര്യമായും സംഭവിക്കുന്ന യാഥാർത്ഥ്യം (അന്ത്യനാൾ)."}], "asbabAlNuzul": []}, {"surahNumber": 70, "surahNameArabic": "سُورَةُ المَعَارِجِ", "surahNameMalayalam": "സൂറത്തുൽ മആരിജ് (കയറുപടികൾ)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ سَأَلَ سَاۤىِٕلُۢ بِعَذَابࣲ وَاقِعࣲ\n", "jalalayn": "«سَأَلَ سائِل» دَعا داعٍ", "malayalam": "«ഒരു ചോദകൻ സംഭവിക്കാൻ പോകുന്ന ശിക്ഷയെപ്പറ്റി ചോദിച്ചു» (നള്ർ ബിൻ ഹാരിസ് തങ്ങൾക്ക് ശിക്ഷ വരാൻ ആവശ്യപ്പെട്ട സംഭവം).", "malayalamMatn": "സംഭവിക്കാനിരിക്കുന്ന ഒരു ശിക്ഷയെ ഒരു ചോദ്യകര്‍ത്താവ് അതാ ആവശ്യപ്പെട്ടിരിക്കുന്നു."}, {"ayahNumber": 2, "quranText": "لِّلۡكَـٰفِرِینَ لَیۡسَ لَهُۥ دَافِعࣱ\n", "jalalayn": "«لِلْكافِرِينَ لَيْسَ لَهُ دافِع» هُوَ النَّضْر بْن الحارِث قالَ «اللَّهُمَّ إنْ كانَ هَذا هُوَ الحَقّ» الآيَة", "malayalam": "«സത്യനിഷേധികൾക്ക് ബാധിക്കുന്ന ശിക്ഷ; അതിനെ തടുക്കാൻ ആരുമില്ല».", "malayalamMatn": "സത്യനിഷേധികള്‍ക്ക് അത് തടുക്കുവാന്‍ ആരുമില്ല."}, {"ayahNumber": 3, "quranText": "مِّنَ ٱللَّهِ ذِی ٱلۡمَعَارِجِ\n", "jalalayn": "«مِن اللَّه» مُتَّصِل بِواقِعِ «ذِي المَعارِج» مَصاعِد المَلائِكَة وهِيَ السَّماوات", "malayalam": "«ഉന്നത പടവുകളുടെ ഉടമയായ അല്ലാഹുവിങ്കൽ നിന്നുള്ള ശിക്ഷ».", "malayalamMatn": "കയറിപ്പോകുന്ന വഴികളുടെ അധിപനായ അല്ലാഹുവിങ്കല്‍ നിന്ന് വരുന്ന (ശിക്ഷയെ)."}, {"ayahNumber": 4, "quranText": "تَعۡرُجُ ٱلۡمَلَـٰۤىِٕكَةُ وَٱلرُّوحُ إِلَیۡهِ فِی یَوۡمࣲ كَانَ مِقۡدَارُهُۥ خَمۡسِینَ أَلۡفَ سَنَةࣲ\n", "jalalayn": "«تَعْرُج» بِالتّاءِ والياء «المَلائِكَة والرُّوح» جِبْرِيل «إلَيْهِ» إلى مَهْبِط أمْره مِن السَّماء «فِي يَوْم» مُتَعَلِّق بِمَحْذُوفٍ أيْ يَقَع العَذاب بِهِمْ فِي يَوْم القِيامَة «كانَ مِقْداره خَمْسِينَ ألْف سَنَة» بِالنِّسْبَةِ إلى الكافِر لِما يَلْقى فِيهِ مِن الشَّدائِد وأَمّا المُؤْمِن فَيَكُون أخَفّ عَلَيْهِ مِن صَلاة مَكْتُوبَة يُصَلِّيها فِي الدُّنْيا كَما جاءَ فِي الحَدِيث", "malayalam": "«അമ്പതിനായിരം വർഷത്തിന്റെ ദൈർഘ്യമുള്ള ഒരു ദിവസത്തിൽ മലക്കുകളും റൂഹും (ജിബ്‌രീലും) അവങ്കലേക്ക് കയറിപ്പോകുന്നു».", "malayalamMatn": "അമ്പതിനായിരം കൊല്ലത്തിന്‍റെ അളവുള്ളതായ ഒരു ദിവസത്തില്‍ മലക്കുകളും ആത്മാവും അവങ്കലേക്ക് കയറിപ്പോകുന്നു."}, {"ayahNumber": 5, "quranText": "فَٱصۡبِرۡ صَبۡرࣰا جَمِیلًا\n", "jalalayn": "«فاصْبِرْ» وهَذا قَبْل أنْ يُؤْمَر بِالقِتالِ «صَبْرًا جَمِيلًا» أيْ لا جَزَع فِيهِ", "malayalam": "«ആകയാൽ നീ ഭംഗിയായ ക്ഷമയോടെ ക്ഷമിക്കുക».", "malayalamMatn": "എന്നാല്‍ (നബിയേ,) നീ ഭംഗിയായ ക്ഷമ കൈക്കൊള്ളുക."}, {"ayahNumber": 6, "quranText": "إِنَّهُمۡ یَرَوۡنَهُۥ بَعِیدࣰا\n", "jalalayn": "«إنّهُمْ يَرَوْنَهُ» أيْ العَذاب «بَعِيدًا» غَيْر واقِع", "malayalam": "«തീർച്ചയായും അവർ അതിനെ വിദൂരമായി കാണുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും അവര്‍ അതിനെ വിദൂരമായി കാണുന്നു."}, {"ayahNumber": 7, "quranText": "وَنَرَىٰهُ قَرِیبࣰا\n", "jalalayn": "«ونَراهُ قَرِيبًا» واقِعًا لا مَحالَة", "malayalam": "«നാമാകട്ടെ അതിനെ വളരെ അടുത്തായി കാണുന്നു».", "malayalamMatn": "നാം അതിനെ അടുത്തതായും കാണുന്നു."}, {"ayahNumber": 8, "quranText": "یَوۡمَ تَكُونُ ٱلسَّمَاۤءُ كَٱلۡمُهۡلِ\n", "jalalayn": "«يَوْم تَكُون السَّماء» مُتَعَلِّق بِمَحْذُوفٍ تَقْدِيره يَقَع «كالمُهْلِ» كَذائِبِ الفِضَّة", "malayalam": "«ആകാശം ഉരുകിയ ചെമ്പ് പോലെയായിത്തീരുന്ന ദിവസം!».", "malayalamMatn": "ആകാശം ഉരുകിയ ലോഹം പോലെ ആകുന്ന ദിവസം!"}, {"ayahNumber": 9, "quranText": "وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ\n", "jalalayn": "«وتَكُون الجِبال كالعِهْنِ» كالصُّوفِ فِي الخِفَّة والطَّيَران بِالرِّيحِ", "malayalam": "«പർവ്വതങ്ങൾ കടഞ്ഞെടുത്ത രോമം പോലെയായിത്തീരുന്ന ദിവസം!».", "malayalamMatn": "പര്‍വ്വതങ്ങള്‍ കടഞ്ഞരോമം പോലെയും."}, {"ayahNumber": 10, "quranText": "وَلَا یَسۡـَٔلُ حَمِیمٌ حَمِیمࣰا\n", "jalalayn": "«ولا يَسْأَل حَمِيم حَمِيمًا» قَرِيب قَرِيبه لِاشْتِغالِ كُلّ بِحالِهِ", "malayalam": "«യാതൊരു ഉറ്റമിത്രവും മറ്റൊരു മിത്രത്തോട് കുശലാന്വേഷണം നടത്താത്ത ദിവസം!».", "malayalamMatn": "ഒരുറ്റ ബന്ധുവും മറ്റൊരു ഉറ്റബന്ധുവിനോട് (അന്ന്‌) യാതൊന്നും ചോദിക്കുകയില്ല."}, {"ayahNumber": 11, "quranText": "یُبَصَّرُونَهُمۡۚ یَوَدُّ ٱلۡمُجۡرِمُ لَوۡ یَفۡتَدِی مِنۡ عَذَابِ یَوۡمِىِٕذِۭ بِبَنِیهِ\n", "jalalayn": "«يُبَصَّرُونَهُمْ» أيْ يُبْصِر الأَحْماء بَعْضهمْ بَعْضًا ويَتَعارَفُونَ ولا يَتَكَلَّمُونَ والجُمْلَة مُسْتَأْنَفَة «يَوَدّ المُجْرِم» يَتَمَنّى الكافِر «لَوْ» بِمَعْنى أنْ «يَفْتَدِي مِن عَذاب يَوْمئِذٍ» بِكَسْرِ المِيم وفَتْحها", "malayalam": "«അവർ പരസ്പരം കാണിക്കപ്പെടും; കുറ്റവാളി കൊതിക്കും: ആ ദിവസത്തിലെ ശിക്ഷയിൽ നിന്ന് രക്ഷപ്പെടാനായി തന്റെ മക്കളെ പ്രായശ്ചിത്തമായി നൽകാൻ കഴിഞ്ഞിരുന്നെങ്കിൽ!».", "malayalamMatn": "അവര്‍ക്ക് അന്യോന്യം കാണിക്കപ്പെടും. തന്‍റെ മക്കളെ പ്രായശ്ചിത്തമായി നല്‍കി കൊണ്ട് ആ ദിവസത്തെ ശിക്ഷയില്‍ നിന്ന് മോചനം നേടാന്‍ കഴിഞ്ഞിരുന്നെങ്കില്‍ എന്ന് കുറ്റവാളി ആഗ്രഹിക്കും."}, {"ayahNumber": 12, "quranText": "وَصَـٰحِبَتِهِۦ وَأَخِیهِ\n", "jalalayn": "«وصاحِبَته» زَوْجَته", "malayalam": "«തന്റെ ഭാര്യയെയും തന്റെ സഹോദരനെയും».", "malayalamMatn": "തന്‍റെ ഭാര്യയെയും സഹോദരനെയും"}, {"ayahNumber": 13, "quranText": "وَفَصِیلَتِهِ ٱلَّتِی تُـٔۡوِیهِ\n", "jalalayn": "«وفَصِيلَته» عَشِيرَته لِفَصْلِهِ مِنها «الَّتِي تُئْوِيهِ» تَضُمّهُ", "malayalam": "«തനിക്ക് അഭയം നൽകിയിരുന്ന കുടുംബത്തെയും».", "malayalamMatn": "തനിക്ക് അഭയം നല്‍കിയിരുന്ന തന്‍റെ ബന്ധുക്കളെയും"}, {"ayahNumber": 14, "quranText": "وَمَن فِی ٱلۡأَرۡضِ جَمِیعࣰا ثُمَّ یُنجِیهِ\n", "jalalayn": "«ومَن فِي الأَرْض جَمِيعًا ثُمَّ يُنْجِيه» ذَلِكَ الِافْتِداء والجُمْلَة عَطْف عَلى يَفْتَدِي", "malayalam": "«ഭൂമിയിലുള്ള സർവ്വ മനുഷ്യരെയും നൽകി സ്വയം രക്ഷപ്പെടാൻ സാധിച്ചിരുന്നെങ്കിൽ!».", "malayalamMatn": "ഭൂമിയിലുള്ള മുഴുവന്‍ ആളുകളെയും. എന്നിട്ട് അതവനെ രക്ഷപ്പെടുത്തുകയും ചെയ്തിരുന്നെങ്കില്‍ എന്ന്‌"}, {"ayahNumber": 15, "quranText": "كَلَّاۤۖ إِنَّهَا لَظَىٰ\n", "jalalayn": "«كَلّا» رَدّ لِما يَوَدّهُ «إنّها» أيْ النّار «لَظى» اسْم لِجَهَنَّم لِأَنَّها تَتَلَظّى أيْ تَتَلَهَّب عَلى الكُفّار", "malayalam": "«ഒരിക്കലുമില്ല! തീർച്ചയായും അത് ജ്വലിച്ചുയരുന്ന നരകാഗ്നിയാകുന്നു».", "malayalamMatn": "സംശയം വേണ്ട, തീര്‍ച്ചയായും അത് ആളിക്കത്തുന്ന നരകമാകുന്നു."}, {"ayahNumber": 16, "quranText": "نَزَّاعَةࣰ لِّلشَّوَىٰ\n", "jalalayn": "«نَزّاعَة لِلشَّوى» جَمْع شَواة وهِيَ جِلْدَة الرَّأْس", "malayalam": "«തലയോട്ടിയിലെ തൊലി വലിച്ചുരിയുന്ന നരകം!».", "malayalamMatn": "തലയുടെ തൊലിയുരിച്ചു കളയുന്ന നരകാഗ്നി."}, {"ayahNumber": 17, "quranText": "تَدۡعُوا۟ مَنۡ أَدۡبَرَ وَتَوَلَّىٰ\n", "jalalayn": "«تَدْعُوا مَن أدْبَرَ وتَوَلّى» عَنْ الإيمان بِأَنْ تَقُول: إلَيَّ إلَيَّ", "malayalam": "«പിന്തിരിയുകയും സത്യത്തെ വിട്ടുമാറുകയും ചെയ്തവനെ അത് മാടിവിളിക്കും».", "malayalamMatn": "പിന്നോക്കം മാറുകയും, തിരിഞ്ഞുകളയുകയും ചെയ്തവരെ അത് ക്ഷണിക്കും."}, {"ayahNumber": 18, "quranText": "وَجَمَعَ فَأَوۡعَىٰۤ\n", "jalalayn": "«وجَمَعَ» المال «فَأَوْعى» أمْسَكَهُ فِي وِعائِهِ ولَمْ يُؤَدِّ حَقَّ اللَّه مِنهُ", "malayalam": "«സമ്പത്ത് ശേഖരിച്ച് സൂക്ഷിച്ചുവെച്ചവനെയും».", "malayalamMatn": "ശേഖരിച്ചു സൂക്ഷിച്ചു വെച്ചവരെയും."}, {"ayahNumber": 19, "quranText": "۞ إِنَّ ٱلۡإِنسَـٰنَ خُلِقَ هَلُوعًا\n", "jalalayn": "«إنّ الإنْسان خُلِقَ هَلُوعًا» حال مُقَدَّره وتَفْسِيره", "malayalam": "«തീർച്ചയായും മനുഷ്യൻ അക്ഷമനായിക്കൊണ്ടാണ് സൃഷ്ടിക്കപ്പെട്ടിരിക്കുന്നത്».", "malayalamMatn": "തീര്‍ച്ചയായും മനുഷ്യന്‍ സൃഷ്ടിക്കപ്പെട്ടിരിക്കുന്നത് അങ്ങേ അറ്റം അക്ഷമനായിക്കൊണ്ടാണ്‌."}, {"ayahNumber": 20, "quranText": "إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعࣰا\n", "jalalayn": "«إذا مَسَّهُ الشَّرّ جَزُوعًا» وقْت مَسّ الشَّرّ", "malayalam": "«അവന് തിന്മ ബാധിച്ചാൽ അവൻ പരിഭ്രാന്തനാകുന്നു».", "malayalamMatn": "അതായത് തിന്‍മ ബാധിച്ചാല്‍ പൊറുതികേട് കാണിക്കുന്നവനായി കൊണ്ടും,"}, {"ayahNumber": 21, "quranText": "وَإِذَا مَسَّهُ ٱلۡخَیۡرُ مَنُوعًا\n", "jalalayn": "«وإذا مَسَّهُ الخَيْر مَنُوعًا» وقْت مَسّه الخَيْر أيْ المال لِحَقِّ اللَّه مِنهُ", "malayalam": "«അവന് നന്മ ലഭിച്ചാലോ അവൻ പിശുക്കനുമായി മാറുന്നു».", "malayalamMatn": "നന്‍മ കൈവന്നാല്‍ തടഞ്ഞു വെക്കുന്നവനായികൊണ്ടും."}, {"ayahNumber": 22, "quranText": "إِلَّا ٱلۡمُصَلِّینَ\n", "jalalayn": "«إلّا المُصَلِّينَ» أيْ المُؤْمِنِينَ", "malayalam": "«നമസ്കാരം നിർവ്വഹിക്കുന്നവരൊഴികെ!».", "malayalamMatn": "നമസ്കരിക്കുന്നവരൊഴികെ -"}, {"ayahNumber": 23, "quranText": "ٱلَّذِینَ هُمۡ عَلَىٰ صَلَاتِهِمۡ دَاۤىِٕمُونَ\n", "jalalayn": "«الَّذِينَ هُمْ عَلى صَلاتهمْ دائِمُونَ» مُواظِبُونَ", "malayalam": "«തങ്ങളുടെ നമസ്കാരത്തിൽ സദാ നിഷ്ഠ പുലർത്തുന്നവർ».", "malayalamMatn": "അതായത് തങ്ങളുടെ നമസ്കാരത്തില്‍ സ്ഥിരമായി നിഷ്ഠയുള്ളവര്‍"}, {"ayahNumber": 24, "quranText": "وَٱلَّذِینَ فِیۤ أَمۡوَ ٰ⁠لِهِمۡ حَقࣱّ مَّعۡلُومࣱ\n", "jalalayn": "«والَّذِينَ فِي أمْوالهمْ حَقّ مَعْلُوم» هُوَ الزَّكاة", "malayalam": "«തങ്ങളുടെ സമ്പത്തിൽ നിർണ്ണയിക്കപ്പെട്ട ഒരു വിഹിതമുള്ളവർ».", "malayalamMatn": "തങ്ങളുടെ സ്വത്തുക്കളില്‍ നിര്‍ണിതമായ അവകാശം നല്‍കുന്നവരും,"}, {"ayahNumber": 25, "quranText": "لِّلسَّاۤىِٕلِ وَٱلۡمَحۡرُومِ\n", "jalalayn": "«لِلسّائِلِ والمَحْرُوم» المُتَعَفِّف عَنْ السُّؤال فَيُحْرَم", "malayalam": "«ചോദിച്ചുവരുന്നവനും ഉപജീവനം തടയപ്പെട്ടവനുമായിട്ടുള്ളവർക്ക്».", "malayalamMatn": "ചോദിച്ചു വരുന്നവന്നും ഉപജീവനം തടയപ്പെട്ടവന്നും"}, {"ayahNumber": 26, "quranText": "وَٱلَّذِینَ یُصَدِّقُونَ بِیَوۡمِ ٱلدِّینِ\n", "jalalayn": "«والَّذِينَ يُصَدِّقُونَ بِيَوْمِ الدِّين» الجَزاء", "malayalam": "«പ്രതിഫലദിനത്തെ സത്യപ്പെടുത്തി വിശ്വസിക്കുന്നവർ».", "malayalamMatn": "പ്രതിഫലദിനത്തില്‍ വിശ്വസിക്കുന്നവരും,"}, {"ayahNumber": 27, "quranText": "وَٱلَّذِینَ هُم مِّنۡ عَذَابِ رَبِّهِم مُّشۡفِقُونَ\n", "jalalayn": "«والَّذِينَ هُمْ مِن عَذاب رَبّهمْ مُشْفِقُونَ» خائِفُونَ", "malayalam": "«തങ്ങളുടെ രക്ഷിതാവിന്റെ ശിക്ഷയെ ഭയപ്പെടുന്നവർ».", "malayalamMatn": "തങ്ങളുടെ രക്ഷിതാവിന്‍റെ ശിക്ഷയെപറ്റി ഭയമുള്ളവരുമൊഴികെ."}, {"ayahNumber": 28, "quranText": "إِنَّ عَذَابَ رَبِّهِمۡ غَیۡرُ مَأۡمُونࣲ\n", "jalalayn": "«إنّ عَذاب رَبّهمْ غَيْر مَأْمُون» نُزُوله غَيْر مَأْمُون", "malayalam": "«തീർച്ചയായും തങ്ങളുടെ രക്ഷിതാവിന്റെ ശിക്ഷ നിർഭയമായിരിക്കാൻ കഴിയാത്ത ഒന്നാകുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും അവരുടെ രക്ഷിതാവിന്‍റെ ശിക്ഷ (വരികയില്ലെന്ന്‌) സമാധാനപ്പെടാന്‍ പറ്റാത്തതാകുന്നു."}, {"ayahNumber": 29, "quranText": "وَٱلَّذِینَ هُمۡ لِفُرُوجِهِمۡ حَـٰفِظُونَ\n", "jalalayn": "«وَٱلَّذِینَ هُمۡ لِفُرُوجِهِمۡ حَـٰفِظُونَ».", "malayalam": "«തങ്ങളുടെ ഗുഹ്യസ്ഥാനങ്ങളെ കാത്തുസൂക്ഷിക്കുന്നവർ».", "malayalamMatn": "തങ്ങളുടെ ഗുഹ്യാവയവങ്ങള്‍ കാത്തുസൂക്ഷിക്കുന്നവരും (ഒഴികെ)"}, {"ayahNumber": 30, "quranText": "إِلَّا عَلَىٰۤ أَزۡوَ ٰ⁠جِهِمۡ أَوۡ مَا مَلَكَتۡ أَیۡمَـٰنُهُمۡ فَإِنَّهُمۡ غَیۡرُ مَلُومِینَ\n", "jalalayn": "«إلّا عَلى أزْواجهمْ أوْ ما مَلَكَتْ أيْمانهمْ» مِن الإماء", "malayalam": "«തങ്ങളുടെ ഭാര്യമാരിലോ തങ്ങളുടെ വലംകൈകൾ ഉടമപ്പെടുത്തിയ അടിമസ്ത്രീകളിലോ അല്ലാതെ; അപ്പോൾ അവർ ആക്ഷേപാർഹരല്ല».", "malayalamMatn": "തങ്ങളുടെ ഭാര്യമാരുടെയോ, വലം കൈകള്‍ ഉടമപ്പെടുത്തിയവരുടെയോ കാര്യത്തിലൊഴികെ. തീര്‍ച്ചയായും അവര്‍ ആക്ഷേപമുക്തരാകുന്നു."}, {"ayahNumber": 31, "quranText": "فَمَنِ ٱبۡتَغَىٰ وَرَاۤءَ ذَ ٰ⁠لِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡعَادُونَ\n", "jalalayn": "«فَمَن ابْتَغى وراء ذَلِكَ فَأُولَئِكَ هُمْ العادُونَ» المُتَجاوِزُونَ الحَلال إلى الحَرام", "malayalam": "«എന്നാൽ അതിനപ്പുറം ആരെങ്കിലും ആഗ്രഹിക്കുന്ന പക്ഷം അവരത്രെ അതിരുകവിഞ്ഞവർ!».", "malayalamMatn": "എന്നാല്‍ അതിലപ്പുറം ആരെങ്കിലും ആഗ്രഹിക്കുന്ന പക്ഷം അത്തരക്കാര്‍ തന്നെയാകുന്നു അതിരുകവിയുന്നവര്‍."}, {"ayahNumber": 32, "quranText": "وَٱلَّذِینَ هُمۡ لِأَمَـٰنَـٰتِهِمۡ وَعَهۡدِهِمۡ رَ ٰ⁠عُونَ\n", "jalalayn": "«والَّذِينَ هُمْ لِأَماناتِهِمْ» وفِي قِراءَة بِالإفْرادِ: ما ائْتَمَنُوا عَلَيْهِ مِن أمْر الدِّين والدُّنْيا «وعَهْدهمْ» المَأْخُوذ عَلَيْهِمْ فِي ذَلِكَ «راعُونَ» حافِظُونَ", "malayalam": "«തങ്ങളുടെ അമാനത്തുകളും കരാറുകളും പാലിക്കുന്നവർ».", "malayalamMatn": "തങ്ങളെ വിശ്വസിച്ചേല്‍പിച്ച കാര്യങ്ങളും തങ്ങളുടെ ഉടമ്പടികളും പാലിച്ചു പോരുന്നവരും,"}, {"ayahNumber": 33, "quranText": "وَٱلَّذِینَ هُم بِشَهَـٰدَ ٰ⁠تِهِمۡ قَاۤىِٕمُونَ\n", "jalalayn": "«والَّذِينَ هُمْ بِشَهاداتِهِمْ» وفِي قِراءَة بِالجَمْعِ «قائِمُونَ» يُقِيمُونَها ولا يَكْتُمُونَها", "malayalam": "«തങ്ങളുടെ സാക്ഷ്യങ്ങളിൽ നേരാംവണ്ണം നിലകൊള്ളുന്നവർ».", "malayalamMatn": "തങ്ങളുടെ സാക്ഷ്യങ്ങള്‍ മുറപ്രകാരം നിര്‍വഹിക്കുന്നവരും,"}, {"ayahNumber": 34, "quranText": "وَٱلَّذِینَ هُمۡ عَلَىٰ صَلَاتِهِمۡ یُحَافِظُونَ\n", "jalalayn": "«والَّذِينَ هُمْ عَلى صَلاتهمْ يُحافِظُونَ» بِأَدائِها فِي أوْقاتها", "malayalam": "«തങ്ങളുടെ നമസ്കാരങ്ങളെ കൃത്യമായി കാത്തുസൂക്ഷിക്കുന്നവർ».", "malayalamMatn": "തങ്ങളുടെ നമസ്കാരങ്ങള്‍ നിഷ്ഠയോടെ നിര്‍വഹിക്കുന്നവരും (ഒഴികെ)."}, {"ayahNumber": 35, "quranText": "أُو۟لَـٰۤىِٕكَ فِی جَنَّـٰتࣲ مُّكۡرَمُونَ\n", "jalalayn": "«أُو۟لَـٰۤىِٕكَ فِی جَنَّـٰتࣲ مُّكۡرَمُونَ».", "malayalam": "«അവരത്രെ സ്വർഗ്ഗത്തോപ്പുകളിൽ ആദരിക്കപ്പെടുന്നവർ!».", "malayalamMatn": "അത്തരക്കാര്‍ സ്വര്‍ഗത്തോപ്പുകളില്‍ ആദരിക്കപ്പെടുന്നവരാകുന്നു."}, {"ayahNumber": 36, "quranText": "فَمَالِ ٱلَّذِینَ كَفَرُوا۟ قِبَلَكَ مُهۡطِعِینَ\n", "jalalayn": "«فَمال الَّذِينَ كَفَرُوا قِبَلك» نَحْوك «مُهْطِعِينَ» حال أيْ مُدِيمِي النَّظَر", "malayalam": "«എന്നിരിക്കെ ആ സത്യനിഷേധികൾക്ക് എന്തു പറ്റി, നിന്റെ നേരെ കഴുത്തുനീട്ടി ധൃതിപ്പെട്ട് വരാൻ?».", "malayalamMatn": "അപ്പോള്‍ സത്യനിഷേധികള്‍ക്കെന്തു പറ്റി! അവര്‍ നിന്‍റെ നേരെ കഴുത്തു നീട്ടി വന്നിട്ട്‌"}, {"ayahNumber": 37, "quranText": "عَنِ ٱلۡیَمِینِ وَعَنِ ٱلشِّمَالِ عِزِینَ\n", "jalalayn": "«عَنْ اليَمِين وعَنْ الشِّمال» مِنك «عِزِينَ» حال أيْضًا أيْ جَماعات حِلَقًا حِلَقًا يَقُولُونَ اسْتِهْزاء بِالمُؤْمِنِينَ: لَئِنْ دَخَلَ هَؤُلاءِ الجَنَّة لَنَدْخُلَنَّها قَبْلهمْ", "malayalam": "«വലതുഭാഗത്തു നിന്നും ഇടതുഭാഗത്തു നിന്നും സംഘം സംഘമായിക്കൊണ്ട്?».", "malayalamMatn": "വലത്തോട്ടും ഇടത്തോട്ടും കൂട്ടങ്ങളായി ചിതറിപോകുന്നു."}, {"ayahNumber": 38, "quranText": "أَیَطۡمَعُ كُلُّ ٱمۡرِئࣲ مِّنۡهُمۡ أَن یُدۡخَلَ جَنَّةَ نَعِیمࣲ\n", "jalalayn": "«أَیَطۡمَعُ كُلُّ ٱمۡرِئࣲ مِّنۡهُمۡ أَن یُدۡخَلَ جَنَّةَ نَعِیمࣲ».", "malayalam": "«അവരിൽ ഓരോരുത്തരും അനുഗ്രഹങ്ങളുടെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കപ്പെടുമെന്ന് കൊതിക്കുകയാണോ?».", "malayalamMatn": "സുഖാനുഭൂതിയുടെ സ്വര്‍ഗത്തില്‍ താന്‍ പ്രവേശിപ്പിക്കപ്പെടണമെന്ന് അവരില്‍ ഓരോ മനുഷ്യനും മോഹിക്കുന്നുണ്ടോ?"}, {"ayahNumber": 39, "quranText": "كَلَّاۤۖ إِنَّا خَلَقۡنَـٰهُم مِّمَّا یَعۡلَمُونَ\n", "jalalayn": "«كَلّا» رَدْع لَهُمْ عَنْ طَمَعهمْ فِي الجَنَّة «إنّا خَلَقْناهُمْ» كَغَيْرِهِمْ «مِمّا يَعْلَمُونَ» مِن نُطَف فَلا يُطْمَع بِذَلِكَ فِي الجَنَّة وإنَّما يُطْمَع فِيها بِالتَّقْوى", "malayalam": "«ഒരിക്കലുമില്ല! അവർക്കറിയാവുന്നതിൽ നിന്നാണ് (നിസ്സാരമായ ശുക്ലത്തിൽ നിന്നാണ്) നാം അവരെ സൃഷ്ടിച്ചിരിക്കുന്നത്».", "malayalamMatn": "അതു വേണ്ട. തീര്‍ച്ചയായും അവര്‍ക്കറിയാവുന്നതില്‍ നിന്നാണ് അവരെ നാം സൃഷ്ടിച്ചിട്ടുള്ളത്‌"}, {"ayahNumber": 40, "quranText": "فَلَاۤ أُقۡسِمُ بِرَبِّ ٱلۡمَشَـٰرِقِ وَٱلۡمَغَـٰرِبِ إِنَّا لَقَـٰدِرُونَ\n", "jalalayn": "«فَلا» لا زائِدَة «أُقْسِم بِرَبِّ المَشارِق والمَغارِب» لِلشَّمْسِ والقَمَر وسائِر الكَواكِب", "malayalam": "«ഉദയസ്ഥാനങ്ങളുടെയും അസ്തമയസ്ഥാനങ്ങളുടെയും രക്ഷിതാവിനെക്കൊണ്ട് ഞാൻ സത്യം ചെയ്തു പറയുന്നു; തീർച്ചയായും നാം കഴിവുള്ളവൻ തന്നെയാകുന്നു».", "malayalamMatn": "എന്നാല്‍ ഉദയസ്ഥാനങ്ങളുടെയും അസ്തമയസ്ഥാനങ്ങളുടെയും രക്ഷിതാവിന്‍റെ പേരില്‍ ഞാന്‍ സത്യം ചെയ്തു പറയുന്നു: തീര്‍ച്ചയായും നാം കഴിവുള്ളനാണെന്ന്‌."}, {"ayahNumber": 41, "quranText": "عَلَىٰۤ أَن نُّبَدِّلَ خَیۡرࣰا مِّنۡهُمۡ وَمَا نَحۡنُ بِمَسۡبُوقِینَ\n", "jalalayn": "«عَلى أنْ نُبَدَّل» نَأْتِي بَدَلهمْ «خَيْرًا مِنهُمْ وما نَحْنُ بِمَسْبُوقِينَ» بِعاجِزِينَ عَنْ ذَلِكَ", "malayalam": "«അവർക്ക് പകരം അവരേക്കാൾ ഉത്തമന്മാരെ കൊണ്ടുവരുവാൻ; നമ്മെ ആർക്കും തോൽപിക്കാനാവില്ല».", "malayalamMatn": "അവരെക്കാള്‍ നല്ലവരെ പകരം കൊണ്ടു വരാന്‍. നാം തോല്‍പിക്കപ്പെടുന്നവനല്ല താനും."}, {"ayahNumber": 42, "quranText": "فَذَرۡهُمۡ یَخُوضُوا۟ وَیَلۡعَبُوا۟ حَتَّىٰ یُلَـٰقُوا۟ یَوۡمَهُمُ ٱلَّذِی یُوعَدُونَ\n", "jalalayn": "«فَذَرْهُمْ» اُتْرُكْهُمْ «يَخُوضُوا» فِي باطِلهمْ «ويَلْعَبُوا» فِي دُنْياهُمْ «حَتّى يُلاقُوا» يَلْقَوْا «يَوْمهمْ الَّذِي يُوعَدُونَ» فِيهِ العَذاب", "malayalam": "«ആകയാൽ അവർക്ക് താക്കീത് നൽകപ്പെടുന്ന ആ ദിവസത്തെ അവർ കണ്ടുമുട്ടുന്നത് വരെ വ്യർത്ഥവർത്തമാനങ്ങളിൽ ഏർപ്പെടാനും കളിച്ചുരസിക്കാനും നീ അവരെ വിട്ടേക്കുക».", "malayalamMatn": "ആകയാല്‍ അവര്‍ക്ക് താക്കീത് നല്‍കപ്പെടുന്ന അവരുടെ ആ ദിവസത്തെ അവര്‍ കണ്ടുമുട്ടുന്നത് വരെ അവര്‍ തോന്നിവാസത്തില്‍ മുഴുകുകയും കളിച്ചു കൊണ്ടിരിക്കുകയും ചെയ്യാന്‍ നീ അവരെ വിട്ടേക്കുക."}, {"ayahNumber": 43, "quranText": "یَوۡمَ یَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ سِرَاعࣰا كَأَنَّهُمۡ إِلَىٰ نُصُبࣲ یُوفِضُونَ\n", "jalalayn": "«يَوْم يَخْرُجُونَ مِن الأَجْداث» القُبُور «سِراعًا» إلى المَحْشَر «كَأَنَّهُمْ إلى نُصُب» وفِي قِراءَة بِضَمِّ الحَرْفَيْنِ شَيْء مَنصُوب كَعَلَمٍ أوْ رايَة «يُوفِضُونَ» يُسْرِعُونَ", "malayalam": "«ഒരു ലക്ഷ്യസ്ഥാനത്തേക്ക് ധൃതിപ്പെട്ട് ഓടുന്നതുപോലെ അവർ ഖബറുകളിൽ നിന്ന് പുറത്തുവരുന്ന ദിവസം!».", "malayalamMatn": "അതായത് അവര്‍ ഒരു നാട്ടക്കുറിയുടെ നേരെ ധൃതിപ്പെട്ട് പോകുന്നത് പോലെ ഖബ്‌റുകളില്‍ നിന്ന് പുറപ്പെട്ടു പോകുന്ന ദിവസം."}, {"ayahNumber": 44, "quranText": "خَـٰشِعَةً أَبۡصَـٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةࣱۚ ذَ ٰ⁠لِكَ ٱلۡیَوۡمُ ٱلَّذِی كَانُوا۟ یُوعَدُونَ\n", "jalalayn": "«خاشِعَة» ذَلِيلَة «أبْصارهمْ تَرْهَقهُمْ» تَغْشاهُمْ «ذِلَّة ذَلِكَ اليَوْم الَّذِي كانُوا يُوعَدُونَ» ذَلِكَ مُبْتَدَأ وما بَعْده خَبَر ومَعْناهُ يَوْم القِيامَة", "malayalam": "«അവരുടെ കണ്ണുകൾ താഴ്ന്ന നിലയിലായിരിക്കും; അപമാനം അവരെ ആവരണം ചെയ്യും; അവർക്ക് വാഗ്ദാനം ചെയ്യപ്പെട്ടിരുന്ന ദിവസം അതത്രെ!».", "malayalamMatn": "അവരുടെ കണ്ണുകള്‍ കീഴ്പോട്ട് താണിരിക്കും. അപമാനം അവരെ ആവരണം ചെയ്തിരിക്കും. അതാണ് അവര്‍ക്ക് താക്കീത് നല്‍കപ്പെട്ടിരുന്ന ദിവസം."}], "topPoints": ["മനുഷ്യന്റെ അക്ഷമയും സ്വാർത്ഥതയും (خلاصة السورة)", "നമസ്കാരം നിലനിർത്തുന്നവരുടെ പ്രത്യേകതകൾ"], "topQuestions": [{"q": "മനുഷ്യന്റെ സ്വാഭാവിക പ്രകൃതം എന്താണ്?", "a": "തിന്മ ബാധിച്ചാൽ അവൻ പരിഭ്രാന്തനാകും, നന്മ ലഭിച്ചാൽ അവൻ പിശുക്കനുമാകും."}], "asbabAlNuzul": []}, {"surahNumber": 71, "surahNameArabic": "سُورَةُ نُوحٍ", "surahNameMalayalam": "സൂറത്തു നൂഹ് (നൂഹ് നബി)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ إِنَّاۤ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦۤ أَنۡ أَنذِرۡ قَوۡمَكَ مِن قَبۡلِ أَن یَأۡتِیَهُمۡ عَذَابٌ أَلِیمࣱ\n", "jalalayn": "«أنْ أنْذِرْ» أيْ بِإنْذارِ «قَوْمك مِن قَبْل أنْ يَأْتِيهِمْ» إنْ لَمْ يُؤْمِنُوا «عَذاب ألِيم» مُؤْلِم فِي الدُّنْيا والآخِرَة", "malayalam": "«വേദനാജനകമായ ശിക്ഷ തങ്ങൾക്ക് വന്നെത്തുന്നതിന് മുമ്പായി താങ്കൾ താങ്കളുടെ ജനതക്ക് താക്കീത് നൽകുക എന്ന് നിർദ്ദേശിച്ചുകൊണ്ട് തീർച്ചയായും നൂഹിനെ നാം അദ്ദേഹത്തിന്റെ ജനതയിലേക്ക് അയക്കുകയുണ്ടായി».", "malayalamMatn": "തീര്‍ച്ചയായും നൂഹിനെ അദ്ദേഹത്തിന്‍റെ ജനതയിലേക്ക് നാം അയച്ചു. നിന്‍റെ ജനതയ്ക്ക് വേദനയേറിയ ശിക്ഷ വരുന്നതിന്‍റെ മുമ്പ് അവര്‍ക്ക് താക്കീത് നല്‍കുക എന്ന് നിര്‍ദേശിച്ചു കൊണ്ട്‌"}, {"ayahNumber": 2, "quranText": "قَالَ یَـٰقَوۡمِ إِنِّی لَكُمۡ نَذِیرࣱ مُّبِینٌ\n", "jalalayn": "«قالَ يا قَوْم إنِّي لَكُمْ نَذِير مُبِين» بَيِّن الإنْذار", "malayalam": "«അദ്ദേഹം പറഞ്ഞു: എന്റെ ജനങ്ങളേ, തീർച്ചയായും ഞാൻ നിങ്ങൾക്ക് വ്യക്തമായ ഒരു താക്കീതുകാരനാകുന്നു».", "malayalamMatn": "അദ്ദേഹം പറഞ്ഞു: എന്‍റെ ജനങ്ങളെ, തീര്‍ച്ചയായും ഞാന്‍ നിങ്ങള്‍ക്കു വ്യക്തമായ താക്കീതുകാരനാകുന്നു."}, {"ayahNumber": 3, "quranText": "أَنِ ٱعۡبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ وَأَطِیعُونِ\n", "jalalayn": "«أنْ» أيْ بِأَنْ أقُول لَكُمْ", "malayalam": "«നിങ്ങൾ അല്ലാഹുവെ ആരാധിക്കുകയും അവനെ സൂക്ഷിക്കുകയും എന്നെ അനുസരിക്കുകയും ചെയ്യുവിൻ!».", "malayalamMatn": "നിങ്ങള്‍ അല്ലാഹുവെ ആരാധിക്കുകയും അവനെ സൂക്ഷിക്കുകയും എന്നെ അനുസരിക്കുകയും ചെയ്യുവിന്‍."}, {"ayahNumber": 4, "quranText": "یَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَیُؤَخِّرۡكُمۡ إِلَىٰۤ أَجَلࣲ مُّسَمًّىۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَاۤءَ لَا یُؤَخَّرُۚ لَوۡ كُنتُمۡ تَعۡلَمُونَ\n", "jalalayn": "«يَغْفِر لَكُمْ مِن ذُنُوبكُمْ» مِن زائِدَة فَإنَّ الإسْلام يُغْفَر بِهِ ما قَبْله أوْ تَبْعِيضِيَّة لِإخْراجِ حُقُوق العِباد «ويُؤَخِّركُمْ» بِلا عَذاب «إلى أجَل مُسَمّى» أجَل المَوْت «إنّ أجَل اللَّه» بِعَذابِكُمْ إنْ لَمْ تُؤْمِنُوا «إذا جاءَ لا يُؤَخَّر لَوْ كُنْتُمْ تَعْلَمُونَ» ذَلِكَ لَآمَنتُمْ", "malayalam": "«എങ്കിൽ അവൻ നിങ്ങളുടെ പാപങ്ങൾ നിങ്ങൾക്ക് പൊറുത്തുതരികയും നിർണ്ണയിക്കപ്പെട്ട ഒരു അവധി വരെ നിങ്ങൾക്ക് സമയം നീട്ടിത്തരികയും ചെയ്യും; തീർച്ചയായും അല്ലാഹുവിന്റെ അവധി വന്നെത്തിയാൽ അത് നീട്ടിവെക്കപ്പെടുകയില്ല; നിങ്ങൾ അറിയുന്നവരായിരുന്നുവെങ്കിൽ!».", "malayalamMatn": "എങ്കില്‍ അവന്‍ നിങ്ങള്‍ക്കു നിങ്ങളുടെ പാപങ്ങളില്‍ ചിലത് പൊറുത്തുതരികയും, നിര്‍ണയിക്കപ്പെട്ട ഒരു അവധി വരെ നിങ്ങളെ നീട്ടിയിടുകയും ചെയ്യുന്നതാണ്‌. തീര്‍ച്ചയായും അല്ലാഹുവിന്‍റെ അവധി വന്നാല്‍ അത് നീട്ടി കൊടുക്കപ്പെടുകയില്ല. നിങ്ങള്‍ അറിഞ്ഞിരുന്നെങ്കില്‍."}, {"ayahNumber": 5, "quranText": "قَالَ رَبِّ إِنِّی دَعَوۡتُ قَوۡمِی لَیۡلࣰا وَنَهَارࣰا\n", "jalalayn": "«قالَ رَبّ إنِّي دَعَوْت قَوْمِي لَيْلًا ونَهارًا» أيْ دائِمًا مُتَّصِلًا", "malayalam": "«അദ്ദേഹം പറഞ്ഞു: എന്റെ രക്ഷിതാവേ, തീർച്ചയായും ഞാൻ എന്റെ ജനതയെ രാവും പകലും പ്രബോധനം ചെയ്തു».", "malayalamMatn": "അദ്ദേഹം പറഞ്ഞു: എന്‍റെ രക്ഷിതാവേ, തീര്‍ച്ചയായും എന്‍റെ ജനതയെ രാവും പകലും ഞാന്‍ വിളിച്ചു."}, {"ayahNumber": 6, "quranText": "فَلَمۡ یَزِدۡهُمۡ دُعَاۤءِیۤ إِلَّا فِرَارࣰا\n", "jalalayn": "«فَلَمْ يَزِدْهُمْ إلّا فِرارًا» عَنْ الإيمان", "malayalam": "«എന്നിട്ട് എന്റെ വിളി അവർക്ക് ഓടിയകലലിനെയല്ലാതെ മറ്റൊന്നിനെയും വർദ്ധിപ്പിച്ചില്ല».", "malayalamMatn": "എന്നിട്ട് എന്‍റെ വിളി അവരുടെ ഓടിപ്പോക്ക് വര്‍ദ്ധിപ്പിക്കുക മാത്രമേ ചെയ്തുള്ളു."}, {"ayahNumber": 7, "quranText": "وَإِنِّی كُلَّمَا دَعَوۡتُهُمۡ لِتَغۡفِرَ لَهُمۡ جَعَلُوۤا۟ أَصَـٰبِعَهُمۡ فِیۤ ءَاذَانِهِمۡ وَٱسۡتَغۡشَوۡا۟ ثِیَابَهُمۡ وَأَصَرُّوا۟ وَٱسۡتَكۡبَرُوا۟ ٱسۡتِكۡبَارࣰا\n", "jalalayn": "«وإنِّي كُلَّما دَعَوْتهمْ لِتَغْفِر لَهُمْ جَعَلُوا أصابِعهمْ فِي آذانهمْ» لِئَلّا يَسْمَعُوا كَلامِي «واسْتَغْشَوْا ثِيابهمْ» غَطَّوْا رُءُوسهمْ بِها لِئَلّا يُنْظِرُونِي «وأَصَرُّوا» عَلى كُفْرهمْ «واسْتَكْبَرُوا» تَكَبَّرُوا عَنْ الإيمان", "malayalam": "«നീ അവർക്ക് പൊറുത്തുകൊടുക്കുവാനായി ഞാൻ അവരെ ക്ഷണിച്ചപ്പോഴൊക്കെ അവർ തങ്ങളുടെ വിരലുകൾ കാതുകളിൽ തിരുകുകയും തങ്ങളുടെ വസ്ത്രങ്ങൾ മൂടിപ്പുതക്കുകയും ധിക്കാരത്തിൽ ഉറച്ചുനിൽക്കുകയും വലിയ അഹങ്കാരം നടിക്കുകയും ചെയ്തു».", "malayalamMatn": "തീര്‍ച്ചയായും, നീ അവര്‍ക്ക് പൊറുത്തുകൊടുക്കുവാന്‍ വേണ്ടി ഞാന്‍ അവരെ വിളിച്ചപ്പോഴൊക്കെയും അവര്‍ അവരുടെ വിരലുകള്‍ കാതുകളില്‍ വെക്കുകയും, അവരുടെ വസ്ത്രങ്ങള്‍ മൂടിപ്പുതക്കുകയും, അവര്‍ ശഠിച്ചു നില്‍ക്കുകയും, കടുത്ത അഹങ്കാരം നടിക്കുകയുമാണ് ചെയ്തത്‌."}, {"ayahNumber": 8, "quranText": "ثُمَّ إِنِّی دَعَوۡتُهُمۡ جِهَارࣰا\n", "jalalayn": "«ثُمَّ إنِّي دَعَوْتهمْ جِهارًا» أيْ بِأَعْلى صَوْتِي", "malayalam": "«പിന്നീട് ഞാൻ അവരെ ഉച്ചത്തിൽ വിളിച്ചു പ്രബോധനം ചെയ്തു».", "malayalamMatn": "പിന്നീട് അവരെ ഞാന്‍ ഉറക്കെ വിളിച്ചു."}, {"ayahNumber": 9, "quranText": "ثُمَّ إِنِّیۤ أَعۡلَنتُ لَهُمۡ وَأَسۡرَرۡتُ لَهُمۡ إِسۡرَارࣰا\n", "jalalayn": "«ثُمَّ إنِّي أعْلَنْت لَهُمْ» صَوْتِي «وأَسْرَرْت» الكَلام", "malayalam": "«പിന്നെ ഞാൻ അവരോട് പരസ്യമായി പ്രഖ്യാപിക്കുകയും അത്യധികം രഹസ്യമായി ഉപദേശിക്കുകയും ചെയ്തു».", "malayalamMatn": "പിന്നീട് ഞാന്‍ അവരോട് പരസ്യമായും വളരെ രഹസ്യമായും പ്രബോധനം നടത്തി."}, {"ayahNumber": 10, "quranText": "فَقُلۡتُ ٱسۡتَغۡفِرُوا۟ رَبَّكُمۡ إِنَّهُۥ كَانَ غَفَّارࣰا\n", "jalalayn": "«فَقُلْت اسْتَغْفِرُوا رَبّكُمْ» مِن الشِّرْك", "malayalam": "«അങ്ങനെ ഞാൻ പറഞ്ഞു: നിങ്ങൾ നിങ്ങളുടെ രക്ഷിതാവിനോട് പാപമോചനം തേടുവിൻ! തീർച്ചയായും അവൻ ഏറെ പൊറുക്കുന്നവനാകുന്നു».", "malayalamMatn": "അങ്ങനെ ഞാന്‍ പറഞ്ഞു: നിങ്ങള്‍ നിങ്ങളുടെ രക്ഷിതാവിനോട് പാപമോചനം തേടുക. തീര്‍ച്ചയായും അവന്‍ ഏറെ പൊറുക്കുന്നവനാകുന്നു."}, {"ayahNumber": 11, "quranText": "یُرۡسِلِ ٱلسَّمَاۤءَ عَلَیۡكُم مِّدۡرَارࣰا\n", "jalalayn": "«يُرْسِل السَّماء» المَطَر وكانُوا قَدْ مَنَعُوهُ «عَلَيْكُمْ مِدْرارًا» كَثِير الدُّرُور", "malayalam": "«അവൻ നിങ്ങളുടെ മേൽ സമൃദ്ധമായി മഴ വർഷിപ്പിച്ചു തരും».", "malayalamMatn": "അവന്‍ നിങ്ങള്‍ക്ക് മഴ സമൃദ്ധമായി അയച്ചുതരും."}, {"ayahNumber": 12, "quranText": "وَیُمۡدِدۡكُم بِأَمۡوَ ٰ⁠لࣲ وَبَنِینَ وَیَجۡعَل لَّكُمۡ جَنَّـٰتࣲ وَیَجۡعَل لَّكُمۡ أَنۡهَـٰرࣰا\n", "jalalayn": "«ويُمْدِدْكُمْ بِأَمْوالٍ وبَنِينَ ويَجْعَل لَكُمْ جَنّات» بَساتِين «ويَجْعَل لَكُمْ أنْهارًا» جارِيَة", "malayalam": "«സ്വത്തുക്കളും സന്താനങ്ങളും നൽകി അവൻ നിങ്ങളെ സഹായിക്കും; അവൻ നിങ്ങൾക്ക് തോട്ടങ്ങൾ ഉണ്ടാക്കിത്തരികയും നിങ്ങൾക്ക് നദികൾ ഒഴുക്കിത്തരികയും ചെയ്യും».", "malayalamMatn": "സ്വത്തുക്കളും സന്താനങ്ങളും കൊണ്ട് നിങ്ങളെ അവന്‍ പോഷിപ്പിക്കുകയും, നിങ്ങള്‍ക്കവന്‍ തോട്ടങ്ങള്‍ ഉണ്ടാക്കിത്തരികയും നിങ്ങള്‍ക്കവന്‍ അരുവികള്‍ ഉണ്ടാക്കിത്തരികയും ചെയ്യും."}, {"ayahNumber": 13, "quranText": "مَّا لَكُمۡ لَا تَرۡجُونَ لِلَّهِ وَقَارࣰا\n", "jalalayn": "«ما لَكُمْ لا تَرْجُونَ لِلَّهِ وقارًا» أيْ تَأْمُلُونَ وقار اللَّه إيّاكُمْ بِأَنْ تُؤْمِنُوا", "malayalam": "«നിങ്ങൾക്കെന്തു പറ്റി, അല്ലാഹുവിന്റെ മഹത്വത്തെ നിങ്ങൾ ഭയപ്പെടാതിരിക്കാൻ?».", "malayalamMatn": "നിങ്ങള്‍ക്കെന്തു പറ്റി? അല്ലാഹുവിന് ഒരു ഗാംഭീര്യവും നിങ്ങള്‍ പ്രതീക്ഷിക്കുന്നില്ല."}, {"ayahNumber": 14, "quranText": "وَقَدۡ خَلَقَكُمۡ أَطۡوَارًا\n", "jalalayn": "«وقَدْ خَلَقَكُمْ أطْوارًا» جَمْع طَوْر وهُوَ الحال فَطَوْرًا نُطْفَة وطَوْرًا عَلَقَة إلى تَمام خَلْق الإنْسان والنَّظَر فِي خَلْقه يُوجِب الإيمان بِخالِقِهِ", "malayalam": "«വിവിധ ഘട്ടങ്ങളിലായി അവനത്രെ നിങ്ങളെ സൃഷ്ടിച്ചത്!».", "malayalamMatn": "നിങ്ങളെ അവന്‍ പല ഘട്ടങ്ങളിലായി സൃഷ്ടിച്ചിരിക്കുകയാണല്ലോ."}, {"ayahNumber": 15, "quranText": "أَلَمۡ تَرَوۡا۟ كَیۡفَ خَلَقَ ٱللَّهُ سَبۡعَ سَمَـٰوَ ٰ⁠تࣲ طِبَاقࣰا\n", "jalalayn": "«ألَمْ تَرَوْا» تَنْظُرُوا «كَيْفَ خَلَقَ اللَّه سَبْع سَمَوات طِباقًا» بَعْضها فَوْق بَعْض", "malayalam": "«അടുക്കടുക്കായി ഏഴ് ആകാശങ്ങളെ അല്ലാഹു എങ്ങനെയാണ് സൃഷ്ടിച്ചതെന്ന് നിങ്ങൾ കണ്ടില്ലയോ?».", "malayalamMatn": "നിങ്ങള്‍ കണ്ടില്ലേ; എങ്ങനെയാണ് അല്ലാഹു അടുക്കുകളായിട്ട് ഏഴ് ആകാശങ്ങള്‍ സൃഷ്ടിച്ചിരിക്കുന്നത് എന്ന്‌."}, {"ayahNumber": 16, "quranText": "وَجَعَلَ ٱلۡقَمَرَ فِیهِنَّ نُورࣰا وَجَعَلَ ٱلشَّمۡسَ سِرَاجࣰا\n", "jalalayn": "«وجَعَلَ القَمَر فِيهِنَّ» أيْ فِي مَجْمُوعهنَّ الصّادِق بِالسَّماءِ الدُّنْيا «نُورًا وجَعَلَ الشَّمْس سِراجًا» مِصْباحًا مُضِيئًا وهُوَ أقْوى مِن نُور القَمَر", "malayalam": "«അവയിൽ ചന്ദ്രനെ അവൻ ഒരു പ്രകാശമാക്കുകയും സൂര്യനെ അവൻ ഒരു വിളക്കാക്കുകയും ചെയ്തിരിക്കുന്നു».", "malayalamMatn": "ചന്ദ്രനെ അവിടെ ഒരു പ്രകാശമാക്കിയിരിക്കുന്നു.സൂര്യനെ ഒരു വിളക്കുമാക്കിയിരിക്കുന്നു."}, {"ayahNumber": 17, "quranText": "وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلۡأَرۡضِ نَبَاتࣰا\n", "jalalayn": "«واللَّه أنْبَتَكُمْ» خَلَقَكُمْ «مِن الأَرْض» إذْ خَلَقَ أباكُمْ آدَم مِنها", "malayalam": "«അല്ലാഹു നിങ്ങളെ ഭൂമിയിൽ നിന്ന് ഒരു ചെടിയെപ്പോലെ മുളപ്പിച്ചു വളർത്തി».", "malayalamMatn": "അല്ലാഹു നിങ്ങളെ ഭൂമിയില്‍ നിന്ന് ഒരു മുളപ്പിക്കല്‍ മുളപ്പിച്ചിരിക്കുന്നു."}, {"ayahNumber": 18, "quranText": "ثُمَّ یُعِیدُكُمۡ فِیهَا وَیُخۡرِجُكُمۡ إِخۡرَاجࣰا\n", "jalalayn": "«ثُمَّ يُعِيدكُمْ فِيها» مَقْبُورِينَ «ويُخْرِجكُمْ» لِلْبَعْثِ", "malayalam": "«പിന്നീട് അതിലേക്ക് തന്നെ അവൻ നിങ്ങളെ മടക്കുന്നു; മറ്റൊരു വിധത്തിൽ അവൻ നിങ്ങളെ പുറത്തെടുക്കുകയും ചെയ്യും».", "malayalamMatn": "പിന്നെ അതില്‍ തന്നെ നിങ്ങളെ അവന്‍ മടക്കുകയും നിങ്ങളെ ഒരിക്കല്‍ അവന്‍ പുറത്തു കൊണ്ട് വരികയും ചെയ്യുന്നതാണ്‌."}, {"ayahNumber": 19, "quranText": "وَٱللَّهُ جَعَلَ لَكُمُ ٱلۡأَرۡضَ بِسَاطࣰا\n", "jalalayn": "«واللَّه جَعَلَ لَكُمْ الأَرْض بِساطًا» مَبْسُوطَة", "malayalam": "«അല്ലാഹു നിങ്ങൾക്ക് ഭൂമിയെ ഒരു വിരിപ്പാക്കിത്തന്നു».", "malayalamMatn": "അല്ലാഹു നിങ്ങള്‍ക്കു വേണ്ടി ഭൂമിയെ ഒരു വിരിപ്പാക്കുകയും ചെയ്തിരിക്കുന്നു."}, {"ayahNumber": 20, "quranText": "لِّتَسۡلُكُوا۟ مِنۡهَا سُبُلࣰا فِجَاجࣰا\n", "jalalayn": "«لِتَسْلُكُوا مِنها سُبُلًا» طُرُقًا «فِجاجًا» واسِعَة", "malayalam": "«അതിലെ വിശാലമായ പാതകളിലൂടെ നിങ്ങൾ സഞ്ചരിക്കുവാൻ വേണ്ടി».", "malayalamMatn": "അതിലെ വിസ്താരമുള്ള പാതകളില്‍ നിങ്ങള്‍ പ്രവേശിക്കുവാന്‍ വേണ്ടി."}, {"ayahNumber": 21, "quranText": "قَالَ نُوحࣱ رَّبِّ إِنَّهُمۡ عَصَوۡنِی وَٱتَّبَعُوا۟ مَن لَّمۡ یَزِدۡهُ مَالُهُۥ وَوَلَدُهُۥۤ إِلَّا خَسَارࣰا\n", "jalalayn": "«قالَ نُوح رَبّ إنّهُمْ عَصَوْنِي واتَّبَعُوا» أيْ السَّفَلَة والفُقَراء «مَن لَمْ يَزِدْهُ ماله ووُلْده» وهُمْ الرُّؤَساء المُنَعَّم عَلَيْهِمْ بِذَلِكَ ووُلْد بِضَمِّ الواو وسُكُون اللّام وبِفَتْحِهِما والأَوَّل قِيلَ جَمْع ولَد بِفَتْحِهِما كَخُشْبِ وخَشَب وقِيلَ بِمَعْناهُ كَبُخْلِ وبَخَل «إلّا خَسارًا» طُغْيانًا وكُفْرًا", "malayalam": "«നൂഹ് പറഞ്ഞു: എന്റെ രക്ഷിതാവേ, തീർച്ചയായും അവർ എന്നോട് അനുസരണക്കേട് കാണിച്ചു; ആരുടെ സ്വത്തും മക്കളുമാണോ അവന് നാശമല്ലാതെ മറ്റൊന്നും വർദ്ധിപ്പിക്കാത്തത് അങ്ങനെയുള്ളവരെയാണ് അവർ പിൻപറ്റിയത്!».", "malayalamMatn": "നൂഹ് പറഞ്ഞു: എന്‍റെ രക്ഷിതാവേ, തീര്‍ച്ചയായും ഇവര്‍ എന്നോട് അനുസരണക്കേട് കാണിക്കുകയും ഒരു വിഭാഗത്തെ പിന്തുടരുകയും ചെയ്തിരിക്കുന്നു; അവര്‍ക്ക് (പിന്തുടരപ്പെട്ട നേതൃവിഭാഗത്തിന്‌) സ്വത്തും സന്താനവും മൂലം (ആത്മീയവും പാരത്രികവുമായ) നഷ്ടം കൂടുക മാത്രമാണുണ്ടായത്‌."}, {"ayahNumber": 22, "quranText": "وَمَكَرُوا۟ مَكۡرࣰا كُبَّارࣰا\n", "jalalayn": "«ومَكَرُوا» أيْ الرُّؤَساء «مَكْرًا كُبّارًا» عَظِيمًا جِدًّا بِأَنْ كَذَّبُوا نُوحًا وآذَوْهُ ومَن اتَّبَعَهُ", "malayalam": "«അവർ വലിയൊരു കുതന്ത്രം തന്നെ പ്രയോഗിച്ചു».", "malayalamMatn": "(പുറമെ) അവര്‍ (നേതാക്കള്‍) വലിയ കുതന്ത്രം പ്രയോഗിക്കുകയും ചെയ്തിരിക്കുന്നു."}, {"ayahNumber": 23, "quranText": "وَقَالُوا۟ لَا تَذَرُنَّ ءَالِهَتَكُمۡ وَلَا تَذَرُنَّ وَدࣰّا وَلَا سُوَاعࣰا وَلَا یَغُوثَ وَیَعُوقَ وَنَسۡرࣰا\n", "jalalayn": "«وقالُوا» لِلسَّفَلَةِ «لا تَذَرُونَّ آلِهَتكُمْ ولا تَذَرُونَّ ودًّا» بِفَتْحِ الواو وضَمّها «ولا سُواعًا ولا يَغُوث ويَعُوق ونَسْرًا» هِيَ أسْماء أصْنامهمْ", "malayalam": "«അവർ പറഞ്ഞു: നിങ്ങൾ നിങ്ങളുടെ ദൈവങ്ങളെ ഉപേക്ഷിക്കരുത്; വദ്ദ്, സുവാഅ്, യഗൂസ്, യഊഖ്, നസ്റ് എന്നിവരെ നിങ്ങൾ ഒരിക്കലും ഉപേക്ഷിക്കരുത്!».", "malayalamMatn": "അവര്‍ പറഞ്ഞു: (ജനങ്ങളേ,) നിങ്ങള്‍ നിങ്ങളുടെ ദൈവങ്ങളെ ഉപേക്ഷിക്കരുത്‌. വദ്ദ്‌, സുവാഅ്‌, യഗൂഥ്‌, യഊഖ്‌, നസ്‌റ് എന്നിവരെ നിങ്ങള്‍ ഉപേക്ഷിക്കരുത്‌."}, {"ayahNumber": 24, "quranText": "وَقَدۡ أَضَلُّوا۟ كَثِیرࣰاۖ وَلَا تَزِدِ ٱلظَّـٰلِمِینَ إِلَّا ضَلَـٰلࣰا\n", "jalalayn": "«وقَدْ أضَلُّوا» بِها «كَثِيرًا» مِن النّاس بِأَنْ أمَرُوهُمْ بِعِبادَتِهِمْ «ولا تَزِدْ الظّالِمِينَ إلّا ضَلالًا» عَطْفًا عَلى قَدْ أضَلُّوا دَعا عَلَيْهِمْ لَمّا أُوحِيَ إلَيْهِ أنَّهُ لَنْ يُؤْمِن مِن قَوْمك إلّا مَن قَدْ آمَنَ", "malayalam": "«തീർച്ചയായും അവർ അനേകരെ വഴിപിഴപ്പിച്ചു കളഞ്ഞു; ആ അക്രമികൾക്ക് നാശമല്ലാതെ മറ്റൊന്നും നീ വർദ്ധിപ്പിക്കരുതേ!».", "malayalamMatn": "അങ്ങനെ അവര്‍ വളരെയധികം ആളുകളെ വഴിപിഴപ്പിച്ചു. (രക്ഷിതാവേ,) ആ അക്രമകാരികള്‍ക്ക് വഴിപിഴവല്ലാതെ മറ്റൊന്നും നീ വര്‍ദ്ധിപ്പിക്കരുതേ."}, {"ayahNumber": 25, "quranText": "مِّمَّا خَطِیۤـَٔـٰتِهِمۡ أُغۡرِقُوا۟ فَأُدۡخِلُوا۟ نَارࣰا فَلَمۡ یَجِدُوا۟ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارࣰا\n", "jalalayn": "«مِمّا» ما صِلَة «خَطَياهُمْ» وفِي قِراءَة خَطِيئَآتِهِمْ بِالهَمْزِ «أُغْرِقُوا» بِالطُّوفانِ «فَأُدْخِلُوا نارًا» عُوقِبُوا بِها عَقِب الإغْراق تَحْت الماء «فَلَمْ يَجِدُوا لَهُمْ مِن دُون» أيْ غَيْر «اللَّه أنْصارًا» يَمْنَعُونَ عَنْهُمْ العَذاب", "malayalam": "«തങ്ങളുടെ പാപങ്ങൾ കാരണത്താൽ അവർ മുക്കിക്കൊല്ലപ്പെടുകയും പിന്നീട് നരകാഗ്നിയിൽ പ്രവേശിപ്പിക്കപ്പെടുകയും ചെയ്തു; അപ്പോൾ അല്ലാഹുവിന് പുറമെ തങ്ങളെ സഹായിക്കുന്ന ആരെയും അവർ കണ്ടെത്തിയില്ല».", "malayalamMatn": "അവരുടെ പാപങ്ങള്‍ നിമിത്തം അവര്‍ മുക്കി നശിപ്പിക്കപ്പെട്ടു. എന്നിട്ടവര്‍ നരകാഗ്നിയില്‍ പ്രവേശിപ്പിക്കപ്പെട്ടു. അപ്പോള്‍ തങ്ങള്‍ക്ക് അല്ലാഹുവിനു പുറമെ സഹായികളാരെയും അവര്‍ കണ്ടെത്തിയില്ല."}, {"ayahNumber": 26, "quranText": "وَقَالَ نُوحࣱ رَّبِّ لَا تَذَرۡ عَلَى ٱلۡأَرۡضِ مِنَ ٱلۡكَـٰفِرِینَ دَیَّارًا\n", "jalalayn": "«وقالَ نُوح رَبّ لا تَذَر عَلى الأَرْض مِن الكافِرِينَ دَيّارًا» أيْ نازِل دار والمَعْنى أحَدًا", "malayalam": "«നൂഹ് പ്രാർത്ഥിച്ചു: എന്റെ രക്ഷിതാവേ, സത്യനിഷേധികളിൽ നിന്ന് ഭൂമിയിൽ വസിക്കുന്ന ഒരാളെപ്പോലും നീ ബാക്കിവെക്കരുതേ!».", "malayalamMatn": "നൂഹ് പറഞ്ഞു.: എന്‍റെ രക്ഷിതാവേ, ഭൂമുഖത്ത് സത്യനിഷേധികളില്‍ പെട്ട ഒരു പൌരനെയും നീ വിട്ടേക്കരുതേ."}, {"ayahNumber": 27, "quranText": "إِنَّكَ إِن تَذَرۡهُمۡ یُضِلُّوا۟ عِبَادَكَ وَلَا یَلِدُوۤا۟ إِلَّا فَاجِرࣰا كَفَّارࣰا\n", "jalalayn": "«إنّك إنْ تَذَرهُمْ يُضِلُّوا عِبادك ولا يَلِدُوا إلّا فاجِرًا كَفّارًا» مَن يَفْجُر ويَكْفُر قالَ ذَلِكَ لِما تَقَدَّمَ مِن الإيحاء إلَيْهِ", "malayalam": "«കാരണം നീ അവരെ വിട്ടേക്കുകയാണെങ്കിൽ അവർ നിന്റെ ദാസന്മാരെ വഴിപിഴപ്പിക്കും; ദുർനടപ്പുകാരനും കടുത്ത നന്ദികെട്ടവനുമായ കുഞ്ഞല്ലാതെ അവർ പ്രസവിക്കുകയുമില്ല».", "malayalamMatn": "തീര്‍ച്ചയായും നീ അവരെ വിട്ടേക്കുകയാണെങ്കില്‍ നിന്‍റെ ദാസന്‍മാരെ അവര്‍ പിഴപ്പിച്ചു കളയും. ദുര്‍വൃത്തന്നും സത്യനിഷേധിക്കുമല്ലാതെ അവര്‍ ജന്‍മം നല്‍കുകയുമില്ല."}, {"ayahNumber": 28, "quranText": "رَّبِّ ٱغۡفِرۡ لِی وَلِوَ ٰ⁠لِدَیَّ وَلِمَن دَخَلَ بَیۡتِیَ مُؤۡمِنࣰا وَلِلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِۖ وَلَا تَزِدِ ٱلظَّـٰلِمِینَ إِلَّا تَبَارَۢا\n", "jalalayn": "«رَبّ اغْفِرْ لِي ولِوالِدَيَّ» وكانا مُؤْمِنَيْنِ «ولِمَن دَخَلَ بَيْتِي» مَنزِلِي أوْ مَسْجِدِي «مُؤْمِنًا ولِلْمُؤْمِنِينَ والمُؤْمِنات» إلى يَوْم القِيامَة «ولا تَزِدْ الظّالِمِينَ إلّا تَبارًا» هَلاكًا فَأُهْلِكُوا", "malayalam": "«എന്റെ രക്ഷിതാവേ, എനിക്കും എന്റെ മാതാപിതാക്കൾക്കും വിശ്വാസിയായി എന്റെ വീട്ടിൽ പ്രവേശിച്ചവനും സത്യവിശ്വാസികൾക്കും സത്യവിശ്വാസിനികൾക്കും നീ പൊറുത്തുതരേണമേ! അക്രമികൾക്ക് നാശമല്ലാതെ മറ്റൊന്നും നീ വർദ്ധിപ്പിക്കരുതേ!».", "malayalamMatn": "എന്‍റെ രക്ഷിതാവേ, എന്‍റെ മാതാപിതാക്കള്‍ക്കും എന്‍റെ വീട്ടില്‍ വിശ്വാസിയായിക്കൊണ്ട് പ്രവേശിച്ചവന്നും സത്യവിശ്വാസികള്‍ക്കും സത്യവിശ്വാസിനികള്‍ക്കും സത്യവിശ്വാസിനികള്‍ക്കും നീ പൊറുത്തുതരേണമേ. അക്രമകാരികള്‍ക്ക് നാശമല്ലാതൊന്നും നീ വര്‍ദ്ധിപ്പിക്കരുതേ."}], "topPoints": ["നൂഹ് നബിയുടെ നീണ്ട പ്രബോധനം (خلاصة السورة)", "പാപമോചനം തേടുന്നതിന്റെ ഗുണങ്ങൾ"], "topQuestions": [{"q": "പാപമോചനം (ഇസ്തിഗ്ഫാർ) കൊണ്ടുള്ള ഗുണങ്ങളായി നൂഹ് നബി എന്ത് പറഞ്ഞു?", "a": "മഴ ലഭിക്കും, സമ്പത്തും സന്താനങ്ങളും വർദ്ധിക്കും."}], "asbabAlNuzul": []}, {"surahNumber": 72, "surahNameArabic": "سُورَةُ الجِنِّ", "surahNameMalayalam": "സൂറത്തുൽ ജിന്ന് (ജിന്ന്)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ قُلۡ أُوحِیَ إِلَیَّ أَنَّهُ ٱسۡتَمَعَ نَفَرࣱ مِّنَ ٱلۡجِنِّ فَقَالُوۤا۟ إِنَّا سَمِعۡنَا قُرۡءَانًا عَجَبࣰا\n", "jalalayn": "«قُلْ» يا مُحَمَّد لِلنّاسِ «أُوحِيَ إلَيَّ» أيْ أُخْبِرْت بِالوَحْيِ مِن اللَّه تَعالى «أنَّهُ» الضَّمِير لِلشَّأْنِ «اسْتَمَعَ» لِقِراءَتِي «نَفَر مِن الجِنّ» جِنّ نَصِيبِينَ وذَلِكَ فِي صَلاة الصُّبْح بِبَطْنِ نَخْل مَوْضِع بَيْن مَكَّة والطّائِف وهُمْ الَّذِينَ ذُكِرُوا فِي قَوْله تَعالى «وإذْ صَرَفْنا إلَيْك نَفَرًا مِن الجِنّ» الآيَة «فَقالُوا» لِقَوْمِهِمْ لَمّا رَجَعُوا إلَيْهِمْ «إنّا سَمِعْنا قُرْآنًا عَجَبًا» يُتَعَجَّب مِنهُ فِي فَصاحَته وغَزارَة مَعانِيه وغَيْر ذَلِكَ", "malayalam": "«പറയുക: ജിന്നുകളിൽ നിന്നൊരു സംഘം ശ്രദ്ധിച്ചു കേൾക്കുകയുണ്ടായി എന്ന് എനിക്ക് ദിവ്യസന്ദേശം നൽകപ്പെട്ടിരിക്കുന്നു; അങ്ങനെ അവർ പറഞ്ഞു: തീർച്ചയായും ഞങ്ങൾ അത്ഭുതകരമായ ഒരു ഖുർആൻ കേട്ടിരിക്കുന്നു!».", "malayalamMatn": "നബിയേ,) പറയുക: ജിന്നുകളില്‍ നിന്നുള്ള ഒരു സംഘം ഖുര്‍ആന്‍ ശ്രദ്ധിച്ചു കേള്‍ക്കുകയുണ്ടായി എന്ന് എനിക്ക് ദിവ്യബോധനം നല്‍കപ്പെട്ടിരിക്കുന്നു. എന്നിട്ടവര്‍ (സ്വന്തം സമൂഹത്തോട്‌) പറഞ്ഞു: തീര്‍ച്ചയായും അത്ഭുതകരമായ ഒരു ഖുര്‍ആന്‍ ഞങ്ങള്‍ കേട്ടിരിക്കുന്നു."}, {"ayahNumber": 2, "quranText": "یَهۡدِیۤ إِلَى ٱلرُّشۡدِ فَـَٔامَنَّا بِهِۦۖ وَلَن نُّشۡرِكَ بِرَبِّنَاۤ أَحَدࣰا\n", "jalalayn": "«يَهْدِي إلى الرُّشْد» الإيمان والصَّواب «فَآمَنّا بِهِ ولَنْ نُشْرِك» بَعْد اليَوْم", "malayalam": "«അത് സന്മാർഗ്ഗത്തിലേക്ക് വഴികാണിക്കുന്നു; അതിനാൽ ഞങ്ങൾ അതിൽ വിശ്വസിച്ചിരിക്കുന്നു; ഞങ്ങളുടെ രക്ഷിതാവിനോട് ഞങ്ങൾ യാതൊന്നിനെയും പങ്കുചേർക്കുകയേ ഇല്ല!».", "malayalamMatn": "അത് സന്‍മാര്‍ഗത്തിലേക്ക് വഴി കാണിക്കുന്നു. അതു കൊണ്ട് ഞങ്ങള്‍ അതില്‍ വിശ്വസിച്ചു. മേലില്‍ ഞങ്ങളുടെ രക്ഷിതാവിനോട് ആരെയും ഞങ്ങള്‍ പങ്കുചേര്‍ക്കുകയേ ഇല്ല."}, {"ayahNumber": 3, "quranText": "وَأَنَّهُۥ تَعَـٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَـٰحِبَةࣰ وَلَا وَلَدࣰا\n", "jalalayn": "«وأَنَّهُ» الضَّمِير لِلشَّأْنِ فِيهِ وفِي المَوْضِعَيْنِ بَعْده «تَعالى جَدّ رَبّنا» تَنَزَّهَ جَلاله وعَظَمَته عَمّا نُسِبَ إلَيْهِ «ما اتَّخَذَ صاحِبَة» زَوْجَة", "malayalam": "«ഞങ്ങളുടെ രക്ഷിതാവിന്റെ മഹത്വം എത്രയോ ഉന്നതമായിരിക്കുന്നു! അവൻ യാതൊരു ഭാര്യയെയോ സന്താനത്തെയോ സ്വീകരിച്ചിട്ടില്ല!».", "malayalamMatn": "നമ്മുടെ രക്ഷിതാവിന്‍റെ മഹത്വം ഉന്നതമാകുന്നു. അവന്‍ കൂട്ടുകാരിയെയോ, സന്താനത്തെയോ സ്വീകരിച്ചിട്ടില്ല."}, {"ayahNumber": 4, "quranText": "وَأَنَّهُۥ كَانَ یَقُولُ سَفِیهُنَا عَلَى ٱللَّهِ شَطَطࣰا\n", "jalalayn": "«سَفِيهنا» جاهِلنا «عَلى اللَّه شَطَطًا» غَلَوْا فِي الكَذِب بِوَصْفِهِ بِالصّاحِبَةِ والوَلَد", "malayalam": "«ഞങ്ങളിലെ വിഡ്ഢികൾ അല്ലാഹുവിന്റെ മേൽ അതിരുകടന്ന കളവ് പറയുമായിരുന്നു».", "malayalamMatn": "ഞങ്ങളിലുള്ള വിഡ്ഢികള്‍ അല്ലാഹുവെപറ്റി അതിക്രമപരമായ പരാമര്‍ശം നടത്തുമായിരുന്നു."}, {"ayahNumber": 5, "quranText": "وَأَنَّا ظَنَنَّاۤ أَن لَّن تَقُولَ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَى ٱللَّهِ كَذِبࣰا\n", "jalalayn": "«وأَنّا ظَنَنّا أنْ» مُخَفَّفَة أيْ أنَّهُ «لَنْ تَقُول الإنْس والجِنّ عَلى اللَّه كَذِبًا» بِوَصْفِهِ بِذَلِكَ حَتّى تَبَيَّنّا كَذِبهمْ بِذَلِكَ", "malayalam": "«മനുഷ്യരോ ജിന്നുകളോ അല്ലാഹുവിന്റെ മേൽ ഒരിക്കലും കളവ് പറയുകയില്ലെന്നാണ് ഞങ്ങൾ വിചാരിച്ചിരുന്നത്».", "malayalamMatn": "ഞങ്ങള്‍ വിചാരിച്ചു; മനുഷ്യരും ജിന്നുകളും അല്ലാഹുവിന്‍റെ പേരില്‍ ഒരിക്കലും കള്ളം പറയുകയില്ലെന്ന്‌. എന്നും (അവര്‍ പറഞ്ഞു.)"}, {"ayahNumber": 6, "quranText": "وَأَنَّهُۥ كَانَ رِجَالࣱ مِّنَ ٱلۡإِنسِ یَعُوذُونَ بِرِجَالࣲ مِّنَ ٱلۡجِنِّ فَزَادُوهُمۡ رَهَقࣰا\n", "jalalayn": "«وأَنَّهُ كانَ رِجال مِن الإنْس يَعُوذُونَ» يَسْتَعِيذُونَ «بِرِجالٍ مِن الجِنّ» حِين يَنْزِلُونَ فِي سَفَرهمْ بِمَخُوفٍ فَيَقُول كُلّ رَجُل أعُوذ بِسَيِّدِ هَذا المَكان مِن شَرّ سُفَهائِهِ «فَزادُوهُمْ» بِعَوْذِهِمْ بِهِمْ «رَهَقًا» فَقالُوا سُدْنا الجِنّ والإنْس", "malayalam": "«മനുഷ്യരിലെ ചില വ്യക്തികൾ ജിന്നുകളിലെ ചില വ്യക്തികളോട് ശരണം തേടാറുണ്ടായിരുന്നു; അങ്ങനെ അവർ ജിന്നുകൾക്ക് അഹങ്കാരം വർദ്ധിപ്പിച്ചു കൊടുത്തു».", "malayalamMatn": "മനുഷ്യരില്‍പെട്ട ചില വ്യക്തികള്‍ ജിന്നുകളില്‍ പെട്ട വ്യക്തികളോട് ശരണം തേടാറുണ്ടായിരുന്നു. അങ്ങനെ അതവര്‍ക്ക് (ജിന്നുകള്‍ക്ക്‌) ഗര്‍വ്വ് വര്‍ദ്ധിപ്പിച്ചു."}, {"ayahNumber": 7, "quranText": "وَأَنَّهُمۡ ظَنُّوا۟ كَمَا ظَنَنتُمۡ أَن لَّن یَبۡعَثَ ٱللَّهُ أَحَدࣰا\n", "jalalayn": "«وأَنَّهُمْ» أيْ الجِنّ «ظَنُّوا كَما ظَنَنْتُمْ» يا إنْس «أنْ» مُخَفَّفَة مِن الثَّقِيلَة أيْ أنَّهُ «لَنْ يَبْعَث اللَّه أحَدًا» بَعْد مَوْته", "malayalam": "«നിങ്ങൾ വിചാരിച്ചതുപോലെത്തന്നെ ഒരാളെയും അല്ലാഹു ഉയിർത്തെഴുന്നേൽപിക്കുകയില്ലെന്ന് അവരും വിചാരിച്ചു».", "malayalamMatn": "നിങ്ങള്‍ ധരിച്ചത് പോലെ അവരും ധരിച്ചു; അല്ലാഹു ആരെയും ഉയിര്‍ത്തെഴുന്നേല്‍പിക്കുകയില്ലെന്ന് എന്നും (അവര്‍ പറഞ്ഞു.)"}, {"ayahNumber": 8, "quranText": "وَأَنَّا لَمَسۡنَا ٱلسَّمَاۤءَ فَوَجَدۡنَـٰهَا مُلِئَتۡ حَرَسࣰا شَدِیدࣰا وَشُهُبࣰا\n", "jalalayn": "قالَ الجِنّ «وأَنّا لَمَسْنا السَّماء» رُمْنا اسْتِراق السَّمْع «فَوَجَدْناها مُلِئَتْ حَرَسًا» مِن المَلائِكَة «شَدِيدًا وشُهُبًا» نُجُومًا مُحَرِّقَة وذَلِكَ لَمّا بَعَثَ النَّبِيّ ﷺ", "malayalam": "«ഞങ്ങൾ ആകാശത്തെ തൊട്ടുനോക്കി; അപ്പോൾ ശക്തരായ കാവൽക്കാരെക്കൊണ്ടും തീപ്പന്തങ്ങളെക്കൊണ്ടും അത് നിറക്കപ്പെട്ടതായി ഞങ്ങൾ കണ്ടു».", "malayalamMatn": "ഞങ്ങള്‍ ആകാശത്തെ സ്പര്‍ശിച്ചു നോക്കി. അപ്പോള്‍ അത് ശക്തിമത്തായ പാറാവുകാരാലും തീജ്വാലകളാലും നിറക്കപ്പെട്ടതായി ഞങ്ങള്‍ കണ്ടെത്തി എന്നും (അവര്‍ പറഞ്ഞു.)"}, {"ayahNumber": 9, "quranText": "وَأَنَّا كُنَّا نَقۡعُدُ مِنۡهَا مَقَـٰعِدَ لِلسَّمۡعِۖ فَمَن یَسۡتَمِعِ ٱلۡـَٔانَ یَجِدۡ لَهُۥ شِهَابࣰا رَّصَدࣰا\n", "jalalayn": "«وأَنّا كُنّا» أيْ قَبْل مَبْعَثه «نَقْعُد مِنها مَقاعِد لِلسَّمْعِ» أيْ نَسْتَمِع «فَمَن يَسْتَمِع الآن يَجِد لَهُ شِهابًا رَصَدًا» أُرْصِدَ لَهُ لِيُرْمى بِهِ", "malayalam": "«വാർത്തകൾ ഒറ്റു കേൾക്കുവാനായി ഞങ്ങൾ അതിലെ ചില ഇരിപ്പിടങ്ങളിൽ ഇരിക്കാറുണ്ടായിരുന്നു; എന്നാൽ ഇപ്പോൾ ആരെങ്കിലും ശ്രദ്ധിച്ചു കേൾക്കാൻ തുനിഞ്ഞാൽ അവനെ പതിയിരുന്നു കാക്കുന്ന ഒരു തീപ്പന്തത്തെ അവൻ കണ്ടെത്തും!».", "malayalamMatn": "(ആകാശത്തിലെ) ചില ഇരിപ്പിടങ്ങളില്‍ ഞങ്ങള്‍ കേള്‍ക്കാന്‍ വേണ്ടി ഇരിക്കാറുണ്ടായിരുന്നു. എന്നാല്‍ ഇപ്പോള്‍ ആരെങ്കിലും ശ്രദ്ധിച്ചു കേള്‍ക്കുകയാണെങ്കില്‍ കാത്തിരിക്കുന്ന അഗ്നിജ്വാലയെ അവന്ന് കണ്ടെത്താനാവും. എന്നും (അവര്‍ പറഞ്ഞു.)"}, {"ayahNumber": 10, "quranText": "وَأَنَّا لَا نَدۡرِیۤ أَشَرٌّ أُرِیدَ بِمَن فِی ٱلۡأَرۡضِ أَمۡ أَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدࣰا\n", "jalalayn": "«وأَنّا لا نَدْرِي أشَرّ أُرِيدَ» بَعْد اسْتِراق السَّمْع «بِمَن فِي الأَرْض أمْ أرادَ بِهِمْ رَبّهمْ رَشَدًا» خَيْرًا", "malayalam": "«ഭൂമിയിലുള്ളവർക്ക് വല്ല നാശവുമാണോ ഉദ്ദേശിക്കപ്പെട്ടിട്ടുള്ളത്, അതല്ല അവരുടെ രക്ഷിതാവ് അവർക്ക് സന്മാർഗ്ഗമാണോ ഉദ്ദേശിച്ചിട്ടുള്ളത് എന്ന് ഞങ്ങൾക്ക് മനസ്സിലാകുന്നില്ല».", "malayalamMatn": "ഭൂമിയിലുള്ളവരുടെ കാര്യത്തില്‍ തിന്‍മയാണോ, ഉദ്ദേശിക്കപ്പെട്ടിട്ടുള്ളത്‌, അതല്ല അവരുടെ രക്ഷിതാവ് അവരെ നേര്‍വഴിയിലാക്കാന്‍ ഉദ്ദേശിച്ചിരിക്കുകയാണോ എന്ന് ഞങ്ങള്‍ക്ക് അറിഞ്ഞ് കൂടാ."}, {"ayahNumber": 11, "quranText": "وَأَنَّا مِنَّا ٱلصَّـٰلِحُونَ وَمِنَّا دُونَ ذَ ٰ⁠لِكَۖ كُنَّا طَرَاۤىِٕقَ قِدَدࣰا\n", "jalalayn": "«وأَنّا مِنّا الصّالِحُونَ» بَعْد اسْتِماع القُرْآن «ومِنّا دُون ذَلِكَ» أيْ قَوْم غَيْر صالِحِينَ «كُنّا طَرائِق قِدَدًا» فِرَقًا مُخْتَلِفِينَ مُسْلِمِينَ وكافِرِينَ", "malayalam": "«ഞങ്ങളിൽ സജ്ജനങ്ങളുമുണ്ട്; അതിന് താഴെയുള്ളവരുമുണ്ട്; ഞങ്ങൾ വിഭിന്ന മാർഗ്ഗങ്ങളിലുള്ളവരായിരുന്നു».", "malayalamMatn": "ഞങ്ങളാകട്ടെ, ഞങ്ങളുടെ കൂട്ടത്തില്‍ സദ്‌വൃത്തന്‍മാരുണ്ട്‌. അതില്‍ താഴെയുള്ളവരും ഞങ്ങളുടെ കൂട്ടത്തിലുണ്ട്‌. ഞങ്ങള്‍ വിഭിന്ന മാര്‍ഗങ്ങളായിതീര്‍ന്നിരിക്കുന്നു. എന്നും (അവര്‍ പറഞ്ഞു.)"}, {"ayahNumber": 12, "quranText": "وَأَنَّا ظَنَنَّاۤ أَن لَّن نُّعۡجِزَ ٱللَّهَ فِی ٱلۡأَرۡضِ وَلَن نُّعۡجِزَهُۥ هَرَبࣰا\n", "jalalayn": "«وأَنّا ظَنَنّا أنْ» مُخَفَّفَة مِن الثَّقِيلَة أيْ أنَّهُ «لَنْ نُعْجِز اللَّه فِي الأَرْض ولَنْ نَعْجِزهُ هَرَبًا» لا نُفَوِّتهُ كائِنِينَ فِي الأَرْض أوْ هارِبِينَ مِنها فِي السَّماء", "malayalam": "«ഭൂമിയിൽ വെച്ച് അല്ലാഹുവെ തോൽപിക്കാൻ നമുക്കാവില്ലെന്നും, ഓടിയൊളിച്ചുകൊണ്ട് അവനെ തോൽപിക്കാൻ സാധിക്കില്ലെന്നും ഞങ്ങൾ ഉറച്ചു വിശ്വസിച്ചിരിക്കുന്നു».", "malayalamMatn": "ഭൂമിയില്‍ വെച്ച് അല്ലാഹുവെ ഞങ്ങള്‍ക്ക് തോല്‍പിക്കാനാവില്ല എന്നും, ഓടി മാറിക്കളഞ്ഞിട്ട് അവനെ തോല്‍പിക്കാനാവില്ലെന്നും ഞങ്ങള്‍ ധരിച്ചിരിക്കുന്നു"}, {"ayahNumber": 13, "quranText": "وَأَنَّا لَمَّا سَمِعۡنَا ٱلۡهُدَىٰۤ ءَامَنَّا بِهِۦۖ فَمَن یُؤۡمِنۢ بِرَبِّهِۦ فَلَا یَخَافُ بَخۡسࣰا وَلَا رَهَقࣰا\n", "jalalayn": "«وأَنّا لَمّا سَمِعْنا الهُدى» القُرْآن «آمَنّا بِهِ فَمَن يُؤْمِن بِرَبِّهِ فَلا يَخاف» بِتَقْدِيرِ هُوَ «بَخْسًا» نَقْصًا مِن حَسَناته «ولا رَهَقًا» ظُلْمًا بِالزِّيادَةِ فِي سَيِّئاته", "malayalam": "«ഞങ്ങൾ സന്മാർഗ്ഗരേഖ കേട്ടപ്പോൾ ഞങ്ങൾ അതിൽ വിശ്വസിച്ചു; ആരെങ്കിലും തന്റെ രക്ഷിതാവിൽ വിശ്വസിക്കുന്ന പക്ഷം യാതൊരു നഷ്ടത്തെയോ അനീതിയെയോ അവൻ ഭയപ്പെടേണ്ടതില്ല».", "malayalamMatn": "സന്‍മാര്‍ഗം കേട്ടപ്പോള്‍ ഞങ്ങള്‍ അതില്‍ വിശ്വസിച്ചിരിക്കുന്നു. അപ്പോള്‍ ഏതൊരുത്തന്‍ തന്‍റെ രക്ഷിതാവില്‍ വിശ്വസിക്കുന്നുവോ അവന്‍ യാതൊരു നഷ്ടത്തെയും അനീതിയെയും പറ്റി ഭയപ്പെടേണ്ടി വരില്ല. എന്നും (അവര്‍ പറഞ്ഞു.)"}, {"ayahNumber": 14, "quranText": "وَأَنَّا مِنَّا ٱلۡمُسۡلِمُونَ وَمِنَّا ٱلۡقَـٰسِطُونَۖ فَمَنۡ أَسۡلَمَ فَأُو۟لَـٰۤىِٕكَ تَحَرَّوۡا۟ رَشَدࣰا\n", "jalalayn": "«وأَنّا مِنّا المُسْلِمُونَ ومِنّا القاسِطُونَ» الجائِرُونَ بِكُفْرِهِمْ «فَمَن أسْلَمَ فَأُولَئِكَ تَحَرَّوْا رَشَدًا» قَصَدُوا هِدايَة", "malayalam": "«ഞങ്ങളിൽ മുസ്ലിംകളുമുണ്ട്; അനീതി പ്രവർത്തിക്കുന്നവരുമുണ്ട്; ആരെങ്കിലും ഇസ്ലാം സ്വീകരിച്ചുവോ അവർ നേർവഴി തെരഞ്ഞെടുത്തു കഴിഞ്ഞു».", "malayalamMatn": "ഞങ്ങളുടെ കൂട്ടത്തില്‍ കീഴ്പെട്ടു ജീവിക്കുന്നവരുണ്ട്‌. അനീതി പ്രവര്‍ത്തിക്കുന്നവരും ഞങ്ങളുടെ കൂട്ടത്തിലുണ്ട്‌. എന്നാല്‍ ആര്‍ കീഴ്പെട്ടിരിക്കുന്നുവോ അത്തരക്കാര്‍ സന്‍മാര്‍ഗം അവലംബിച്ചിരിക്കുന്നു."}, {"ayahNumber": 15, "quranText": "وَأَمَّا ٱلۡقَـٰسِطُونَ فَكَانُوا۟ لِجَهَنَّمَ حَطَبࣰا\n", "jalalayn": "«وأَمّا القاسِطُونَ فَكانُوا لِجَهَنَّم حَطَبًا» وقُودًا وأَنّا وأَنَّهُمْ وأَنَّهُ فِي اثْنَيْ عَشَر مَوْضِعًا هِيَ وأَنَّهُ تَعالى وأَنّا مِنّا المُسْلِمُونَ وما بَيْنهما بِكَسْرِ الهَمْزَة اسْتِئْنافًا وبِفَتْحِها بِما يُوَجِّه بِهِ", "malayalam": "«എന്നാൽ അനീതി പ്രവർത്തിച്ചവരാകട്ടെ, അവർ നരകത്തിന് ഇന്ധനമായിത്തീർന്നു».", "malayalamMatn": "അനീതി പ്രവര്‍ത്തിച്ചകരാകട്ടെ നരകത്തിനുള്ള വിറക് ആയി തീരുന്നതാണ്‌. (എന്നും അവര്‍ പറഞ്ഞു.)"}, {"ayahNumber": 16, "quranText": "وَأَلَّوِ ٱسۡتَقَـٰمُوا۟ عَلَى ٱلطَّرِیقَةِ لَأَسۡقَیۡنَـٰهُم مَّاۤءً غَدَقࣰا\n", "jalalayn": "«وأَنْ» مُخَفَّفَة مِن الثَّقِيلَة واسْمها مَحْذُوف أيْ وأَنَّهُمْ وهُوَ مَعْطُوف عَلى أنَّهُ اسْتَمَعَ «لَوْ اسْتَقامُوا عَلى الطَّرِيقَة» أيْ طَرِيقَة الإسْلام «لَأَسْقَيْناهُمْ ماء غَدَقًا» كَثِيرًا مِن السَّماء وذَلِكَ بَعْدَما رُفِعَ المَطَر عَنْهُمْ سَبْع سِنِينَ", "malayalam": "«അവർ നേരായ പാതയിൽ ഉറച്ചുനിന്നിരുന്നുവെങ്കിൽ സമൃദ്ധമായ വെള്ളം നാം അവർക്ക് കുടിക്കാൻ നൽകുമായിരുന്നു».", "malayalamMatn": "ആ മാര്‍ഗത്തില്‍ (ഇസ്ലാമില്‍) അവര്‍ നേരെ നിലകൊള്ളുകയാണെങ്കില്‍ നാം അവര്‍ക്ക് ധാരാളമായി വെള്ളം കുടിക്കാന്‍ നല്‍കുന്നതാണ്‌."}, {"ayahNumber": 17, "quranText": "لِّنَفۡتِنَهُمۡ فِیهِۚ وَمَن یُعۡرِضۡ عَن ذِكۡرِ رَبِّهِۦ یَسۡلُكۡهُ عَذَابࣰا صَعَدࣰا\n", "jalalayn": "«لِنَفْتِنهُمْ» لِنَخْتَبِرهُمْ «فِيهِ» فَنَعْلَم كَيْفَ شُكْرهمْ عِلْم ظُهُور «ومَن يُعْرِض عَنْ ذِكْر رَبّه» القُرْآن «يَسْلُكهُ» بِالنُّونِ والياء نُدْخِلهُ «عَذابًا صَعَدًا» شاقًّا", "malayalam": "«അതിലൂടെ അവരെ പരീക്ഷിക്കുവാൻ വേണ്ടി; ആരെങ്കിലും തന്റെ രക്ഷിതാവിന്റെ സ്മരണയിൽ നിന്ന് തിരിഞ്ഞുകളയുന്ന പക്ഷം അവൻ അവനെ അതികഠിനമായ ശിക്ഷയിൽ പ്രവേശിപ്പിക്കുന്നതാണ്».", "malayalamMatn": "അതിലൂടെ നാം അവരെ പരീക്ഷിക്കുവാന്‍ വേണ്ടിയത്രെ അത്‌. തന്‍റെ രക്ഷിതാവിന്‍റെ ഉല്‍ബോധനത്തെ വിട്ട് ആര്‍ തിരിഞ്ഞുകളയുന്നുവോ അവനെ അവന്‍ (രക്ഷിതാവ്‌) പ്രയാസകരമായ ശിക്ഷയില്‍ പ്രവേശിപ്പിക്കുന്നതാണ്‌. (എന്നും എനിക്ക് ബോധനം നല്‍കപ്പെട്ടിരിക്കുന്നു.)"}, {"ayahNumber": 18, "quranText": "وَأَنَّ ٱلۡمَسَـٰجِدَ لِلَّهِ فَلَا تَدۡعُوا۟ مَعَ ٱللَّهِ أَحَدࣰا\n", "jalalayn": "«وأَنَّ المَساجِد» مَواضِع الصَّلاة «لِلَّهِ فَلا تَدْعُوا» فِيها «مَعَ اللَّه أحَدًا» بِأَنْ تُشْرِكُوا كَما كانَتْ اليَهُود والنَّصارى إذا دَخَلُوا كَنائِسهمْ وبِيعَهُمْ أشْرَكُوا", "malayalam": "«പള്ളികൾ അല്ലാഹുവിന്നുള്ളതാകുന്നു; അതിനാൽ അല്ലാഹുവോടൊപ്പം നിങ്ങൾ മറ്റാരെയും വിളിച്ചു പ്രാർത്ഥിക്കരുത്!».", "malayalamMatn": "പള്ളികള്‍ അല്ലാഹുവിന്നുള്ളതാകുന്നു. അതിനാല്‍ നിങ്ങള്‍ അല്ലാഹുവോടൊപ്പം ആരെയും വിളിച്ച് പ്രാര്‍ത്ഥിക്കരുത് എന്നും."}, {"ayahNumber": 19, "quranText": "وَأَنَّهُۥ لَمَّا قَامَ عَبۡدُ ٱللَّهِ یَدۡعُوهُ كَادُوا۟ یَكُونُونَ عَلَیۡهِ لِبَدࣰا\n", "jalalayn": "«وأَنَّهُ» بِالفَتْحِ والكَسْر اسْتِئْنافًا والضَّمِير لِلشَّأْنِ «لَمّا قامَ عَبْد اللَّه» مُحَمَّد النَّبِيّ ﷺ «يَدْعُوهُ» يَعْبُدهُ بِبَطْنِ نَخْل «كادُوا» أيْ الجِنّ المُسْتَمِعُونَ لِقِراءَتِهِ «يَكُونُونَ عَلَيْهِ لِبَدًا» بِكَسْرِ اللّام وضَمّها جَمْع لُبْدَة كاللُّبَدِ فِي رُكُوب بَعْضهمْ بَعْضًا ازْدِحامًا حِرْصًا عَلى سَماع القُرْآن", "malayalam": "«അല്ലാഹുവിന്റെ ദാസൻ (മുഹമ്മദ് നബി ﷺ) അവനെ വിളിച്ച് പ്രാർത്ഥിക്കാൻ എഴുന്നേറ്റു നിന്നപ്പോൾ അവർ അദ്ദേഹത്തിന് ചുറ്റും തിക്കിത്തിരക്കി കൂട്ടംകൂടാൻ തുടങ്ങി».", "malayalamMatn": "അല്ലാഹുവിന്‍റെ ദാസന്‍ (നബി) അവനോട് പ്രാര്‍ത്ഥിക്കുവാനായി എഴുന്നേറ്റ് നിന്നപ്പോള്‍ അവര്‍ അദ്ദേഹത്തിന് ചുറ്റും തിങ്ങിക്കൂടുവാനൊരുങ്ങി എന്നും."}, {"ayahNumber": 20, "quranText": "قُلۡ إِنَّمَاۤ أَدۡعُوا۟ رَبِّی وَلَاۤ أُشۡرِكُ بِهِۦۤ أَحَدࣰا\n", "jalalayn": "«قالَ» مُجِيبًا لِلْكُفّارِ فِي قَوْلهمْ ارْجِعْ عَمّا أنْتَ فِيهِ وفِي قِراءَة قُلْ «إنّما أدْعُو رَبِّي» إلَهًا", "malayalam": "«പറയുക: ഞാൻ എന്റെ രക്ഷിതാവിനെ മാത്രമേ വിളിച്ചു പ്രാർത്ഥിക്കുന്നുള്ളൂ; അവനോട് യാതൊന്നിനെയും ഞാൻ പങ്കുചേർക്കുകയില്ല».", "malayalamMatn": "(നബിയേ,)പറയുക: ഞാന്‍ എന്‍റെ രക്ഷിതാവിനെ മാത്രമേ വിളിച്ചു പ്രാര്‍ത്ഥിക്കുകയുള്ളൂ. അവനോട് യാതൊരാളെയും ഞാന്‍ പങ്കുചേര്‍ക്കുകയില്ല."}, {"ayahNumber": 21, "quranText": "قُلۡ إِنِّی لَاۤ أَمۡلِكُ لَكُمۡ ضَرࣰّا وَلَا رَشَدࣰا\n", "jalalayn": "«قُلْ إنِّي لا أمْلِك لَكُمْ ضَرًّا» غَيًّا «ولا رَشَدًا» خَيْرًا", "malayalam": "«പറയുക: നിങ്ങൾക്ക് യാതൊരു ഉപദ്രവമോ നന്മയോ വരുത്തിവെക്കാൻ എനിക്ക് അധികാരമില്ല».", "malayalamMatn": "പറയുക: നിങ്ങള്‍ക്ക് ഉപദ്രവം ചെയ്യുക എന്നതോ (നിങ്ങളെ) നേര്‍വഴിയിലാക്കുക എന്നതോ എന്‍റെ അധീനതയിലല്ല."}, {"ayahNumber": 22, "quranText": "قُلۡ إِنِّی لَن یُجِیرَنِی مِنَ ٱللَّهِ أَحَدࣱ وَلَنۡ أَجِدَ مِن دُونِهِۦ مُلۡتَحَدًا\n", "jalalayn": "«قُلْ إنِّي لَنْ يُجِيرنِي مِن اللَّه» مِن عَذابه إنْ عَصَيْته «أحَد ولَنْ أجِد مِن دُونه» أيْ غَيْره «مُلْتَحَدًا» مُلْتَجَأ", "malayalam": "«പറയുക: അല്ലാഹുവിന്റെ ശിക്ഷയിൽ നിന്ന് എന്നെ രക്ഷിക്കാൻ ഒരാൾക്കുമാവില്ല; അവനെയല്ലാതെ യാതൊരു സങ്കേതവും ഞാൻ കണ്ടെത്തുകയുമില്ല».", "malayalamMatn": "പറയുക: അല്ലാഹുവി (ന്‍റെ ശിക്ഷയി) ല്‍ നിന്ന് ഒരാളും എനിക്ക് അഭയം നല്‍കുകയേ ഇല്ല; തീര്‍ച്ചയായും അവന്നു പുറമെ ഒരു അഭയസ്ഥാനവും ഞാന്‍ ഒരിക്കലും കണ്ടെത്തുകയുമില്ല."}, {"ayahNumber": 23, "quranText": "إِلَّا بَلَـٰغࣰا مِّنَ ٱللَّهِ وَرِسَـٰلَـٰتِهِۦۚ وَمَن یَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۤ أَبَدًا\n", "jalalayn": "«إلّا بَلاغًا» اسْتِثْناء مِن مَفْعُول أمْلِك أيْ لا أمْلِك لَكُمْ إلّا البَلاغ إلَيْكُمْ «مِن اللَّه» أيْ عَنْهُ «ورِسالاته» عَطْف عَلى بَلاغًا وما بَيْن المُسْتَثْنى مِنهُ والِاسْتِثْناء اعْتِراض لِتَأْكِيدِ نَفْي الِاسْتِطاعَة «ومَن يَعْصِ اللَّه ورَسُوله» فِي التَّوْحِيد فَلَمْ يُؤْمِن «فَإنَّ لَهُ نار جَهَنَّم خالِدِينَ» حال مِن ضَمِير مِن فِي ما رِعايَة فِي مَعْناها وهِيَ حال مُقَدَّرَة والمَعْنى يَدْخُلُونَها مِقْدار خُلُودهمْ", "malayalam": "«അല്ലാഹുവിങ്കൽ നിന്നുള്ള സന്ദേശങ്ങളും അവന്റെ ദൗത്യങ്ങളും എത്തിച്ചുകൊടുക്കുകയല്ലാതെ; ആരെങ്കിലും അല്ലാഹുവെയും അവന്റെ റസൂലിനെയും അനുസരിക്കാതിരിക്കുന്ന പക്ഷം തീർച്ചയായും അവന്നുള്ളത് നരകാഗ്നിയാകുന്നു; അവരതിൽ എന്നെന്നേക്കുമായി ശാശ്വതരായിരിക്കും».", "malayalamMatn": "അല്ലാഹുവിങ്കല്‍ നിന്നുള്ള പ്രബോധനവും അവന്‍റെ സന്ദേശങ്ങളും ഒഴികെ (മറ്റൊന്നും എന്‍റെ അധീനതയിലില്ല.) വല്ലവനും അല്ലാഹുവെയും അവന്‍റെ ദൂതനെയും ധിക്കരിക്കുന്ന പക്ഷം തീര്‍ച്ചയായും അവന്നുള്ളതാണ് നരകാഗ്നി. അത്തരക്കാര്‍ അതില്‍ നിത്യവാസികളായിരിക്കും."}, {"ayahNumber": 24, "quranText": "حَتَّىٰۤ إِذَا رَأَوۡا۟ مَا یُوعَدُونَ فَسَیَعۡلَمُونَ مَنۡ أَضۡعَفُ نَاصِرࣰا وَأَقَلُّ عَدَدࣰا\n", "jalalayn": "«حَتّى إذا رَأَوْا» ابْتِدائِيَّة فِيها مَعْنى الغايَة لِمُقَدَّرٍ قَبْلها أيْ لا يَزالُونَ عَلى كُفْرهمْ إلى أنْ يَرَوْا «ما يُوعَدُونَ» بِهِ مِن العَذاب «فَسَيَعْلَمُونَ» عِنْد حُلُوله بِهِمْ يَوْم بَدْر أوْ يَوْم القِيامَة «مَن أضْعَف ناصِرًا وأَقَلّ عَدَدًا» أعْوانًا أهُمْ أمْ المُؤْمِنُونَ ؟ ! عَلى القَوْل الأَوَّل أوْ أنا أمْ هُمْ عَلى الثّانِي فَقالَ بَعْضهمْ مَتى هَذا الوَعْد", "malayalam": "«അങ്ങനെ അവർക്ക് താക്കീത് നൽകപ്പെടുന്ന ശിക്ഷ അവർ നേരിൽ കാണുമ്പോൾ, ആർക്കാണ് സഹായികൾ ദുർബലരായിട്ടുള്ളതെന്നും ആർക്കാണ് എണ്ണത്തിൽ കുറവുള്ളതെന്നും അവർ അറിഞ്ഞുകൊള്ളും! (എപ്പോഴാണ് ഈ വാഗ്ദത്തം പുലരുക എന്ന് അവർ ചോദിച്ചപ്പോൾ ഇത് അവതരിച്ചു)».", "malayalamMatn": "അങ്ങനെ അവര്‍ക്ക് താക്കീത് നല്‍കപ്പെടുന്ന കാര്യം അവര്‍ കണ്ടു കഴിഞ്ഞാല്‍ ഏറ്റവും ദുര്‍ബലനായ സഹായി ആരാണെന്നും എണ്ണത്തില്‍ ഏറ്റവും കുറവ് ആരാണെന്നും അവര്‍ മനസ്സിലാക്കികൊള്ളും."}, {"ayahNumber": 25, "quranText": "قُلۡ إِنۡ أَدۡرِیۤ أَقَرِیبࣱ مَّا تُوعَدُونَ أَمۡ یَجۡعَلُ لَهُۥ رَبِّیۤ أَمَدًا\n", "jalalayn": "«قُلْ إنْ» أيْ ما «أدْرِي أقَرِيب ما تُوعَدُونَ» مِن العَذاب «أمْ يَجْعَل لَهُ رَبِّي أمَدًا» غايَة وأَجَلًا لا يَعْلَمهُ إلّا هُوَ", "malayalam": "«പറയുക: നിങ്ങൾക്ക് താക്കീത് നൽകപ്പെടുന്ന കാര്യം അടുത്താണോ അതോ എന്റെ രക്ഷിതാവ് അതിന് വിദൂരമായ കാലാവധി വെച്ചിരിക്കുകയാണോ എന്ന് എനിക്കറിയില്ല».", "malayalamMatn": "(നബിയേ,) പറയുക: നിങ്ങള്‍ക്ക് താക്കീത് നല്‍കപ്പെടുന്ന കാര്യം അടുത്തു തന്നെയാണോ അതല്ല എന്‍റെ രക്ഷിതാവ് അതിന് അവധി വെച്ചേക്കുമോ എന്ന് എനിക്ക് അറിയില്ല."}, {"ayahNumber": 26, "quranText": "عَـٰلِمُ ٱلۡغَیۡبِ فَلَا یُظۡهِرُ عَلَىٰ غَیۡبِهِۦۤ أَحَدًا\n", "jalalayn": "«عالِم الغَيْب» ما غابَ عَنْ العِباد «فَلا يُظْهِر» يُطْلِع «عَلى غَيْبه أحَدًا» مِن النّاس", "malayalam": "«അവൻ അദൃശ്യജ്ഞാനിയാകുന്നു; തന്റെ അദൃശ്യജ്ഞാനം അവൻ ഒരാൾക്കും വെളിപ്പെടുത്തിക്കൊടുക്കുകയില്ല».", "malayalamMatn": "അവന്‍ അദൃശ്യം അറിയുന്നവനാണ്‌. എന്നാല്‍ അവന്‍ തന്‍റെ അദൃശ്യജ്ഞാനം യാതൊരാള്‍ക്കും വെളിപ്പെടുത്തി കൊടുക്കുകയില്ല."}, {"ayahNumber": 27, "quranText": "إِلَّا مَنِ ٱرۡتَضَىٰ مِن رَّسُولࣲ فَإِنَّهُۥ یَسۡلُكُ مِنۢ بَیۡنِ یَدَیۡهِ وَمِنۡ خَلۡفِهِۦ رَصَدࣰا\n", "jalalayn": "«إلّا مَن ارْتَضى مِن رَسُول فَإنَّهُ» مَعَ إطْلاعه عَلى ما شاءَ مِنهُ مُعْجِزَة لَهُ «يَسْلُك» يَجْعَل ويَسِير «مِن بَيْن يَدَيْهِ» أيْ الرَّسُول «ومِن خَلْفه رَصَدًا» مَلائِكَة يَحْفَظُونَهُ حَتّى يُبَلِّغهُ فِي جُمْلَة الوَحْي", "malayalam": "«റസൂലുകളിൽ നിന്ന് അവൻ തൃപ്തിപ്പെട്ടവർക്കൊഴികെ; അപ്പോൾ അവൻ അവരുടെ മുന്നിലും പിന്നിലും കാവൽക്കാരെ (മലക്കുകളെ) ഏർപ്പെടുത്തുന്നു».", "malayalamMatn": "അവന്‍ തൃപ്തിപ്പെട്ട വല്ല ദൂതന്നുമല്ലാതെ. എന്നാല്‍ അദ്ദേഹത്തിന്‍റെ (ദൂതന്‍റെ) മുന്നിലും പിന്നിലും അവന്‍ കാവല്‍ക്കാരെ ഏര്‍പെടുത്തുക തന്നെ ചെയ്യുന്നതാണ്‌."}, {"ayahNumber": 28, "quranText": "لِّیَعۡلَمَ أَن قَدۡ أَبۡلَغُوا۟ رِسَـٰلَـٰتِ رَبِّهِمۡ وَأَحَاطَ بِمَا لَدَیۡهِمۡ وَأَحۡصَىٰ كُلَّ شَیۡءٍ عَدَدَۢا\n", "jalalayn": "«لِيَعْلَم» اللَّه عِلْم ظُهُور «أنْ» مُخَفَّفَة مِن الثَّقِيلَة أيْ أنَّهُ «قَدْ أُبْلِغُوا» أيْ الرُّسُل «رِسالات رَبّهمْ» رُوعِيَ بِجَمْعِ الضَّمِير مَعْنى مِن «وأَحاطَ بِما لَدَيْهِمْ» عَطْف عَلى مُقَدَّر أيْ فَعَلِمَ ذَلِكَ «وأَحْصى كُلّ شَيْء عَدَدًا» تَمْيِيز وهُوَ مُحَوَّل مِن المَفْعُول والأَصْل أحْصى عَدَد كُلّ شَيْء", "malayalam": "«അവർ തങ്ങളുടെ രക്ഷിതാവിന്റെ ദൗത്യങ്ങൾ കൃത്യമായി എത്തിച്ചുകൊടുത്തിട്ടുണ്ടെന്ന് അവൻ അറിയുവാൻ വേണ്ടി; അവരുടെ പക്കലുള്ളതിനെ അവൻ പൂർണ്ണമായി വലയം ചെയ്തിരിക്കുന്നു; സർവ്വ വസ്തുക്കളുടെയും കണക്കുകൾ അവൻ കൃത്യമായി തിട്ടപ്പെടുത്തിയിരിക്കുന്നു».", "malayalamMatn": "അവര്‍ (ദൂതന്‍മാര്‍) തങ്ങളുടെ രക്ഷിതാവിന്‍റെ ദൌത്യങ്ങള്‍ എത്തിച്ചുകൊടുത്തിട്ടുണ്ട് എന്ന് അവന്‍ (അല്ലാഹു) അറിയാന്‍ വേണ്ടി. അവരുടെ പക്കലുള്ളതിനെ അവന്‍ പരിപൂര്‍ണ്ണമായി അറിഞ്ഞിരിക്കുന്നു. എല്ലാ വസ്തുവിന്‍റെയും എണ്ണം അവന്‍ തിട്ടപ്പെടുത്തിയിരിക്കുന്നു."}], "topPoints": ["ജിന്നുകൾ ഖുർആൻ കേട്ട് വിശ്വസിച്ചത് (خلاصة السورة)", "അദൃശ്യകാര്യങ്ങൾ അല്ലാഹുവിന് മാത്രം അറിയാം"], "topQuestions": [{"q": "ഈ സൂറത്തിൽ ജിന്നുകളെക്കുറിച്ച് എന്ത് പറയുന്നു?", "a": "അവർ ഖുർആൻ കേട്ട് അതിശയിക്കുകയും അതിൽ വിശ്വസിക്കുകയും ചെയ്തു."}], "asbabAlNuzul": [{"ayahNumber": 1, "quranText": "قُلۡ أُوحِیَ إِلَیَّ أَنَّهُ ٱسۡتَمَعَ نَفَرࣱ مِّنَ ٱلۡجِنِّ فَقَالُوۤا۟ إِنَّا سَمِعۡنَا قُرۡءَانًا عَجَبࣰا", "arabicSnippet": "نزلت حين ضربت الحراسة على السماء ورجمت الشياطين بالشهب، فخرجت الجن تبحث عن سبب ذلك، فمر ركب منهم ببطن نخلة والنبي ﷺ يصلي الفجر بأصحابه فاستمعوا لقراءته وآمنوا به.", "malayalamExplanation": "ആകാശത്തുനിന്നുള്ള രഹസ്യങ്ങൾ ചോർത്തുന്നതിൽ നിന്ന് ജിന്നുകൾക്ക് തടസ്സം നേരിടുകയും ഉൽക്കകൾ കൊണ്ട് എറിയപ്പെടുകയും ചെയ്തപ്പോൾ, ലോകത്ത് എന്ത് പുതിയ സംഭവമാണ് ഉണ്ടായതെന്ന് അന്വേഷിക്കാൻ ജിന്നുകൾ പല ഭാഗങ്ങളിലേക്കും സംഘങ്ങളായി ഇറങ്ങിത്തിരിച്ചു. നസ്വീബീൻ നിവാസികളായ ഒരുകൂട്ടം ജിന്നുകൾ 'ബത്‌നു നഖ്‌ല' എന്ന സ്ഥലത്ത് വെച്ച് നബി ﷺ സ്വഹാബികളോടൊപ്പം സുബ്ഹ് നമസ്കരിക്കുമ്പോൾ ഓതിയ ഖുർആൻ കേൾക്കുകയും, വിസ്മയം പൂണ്ട് അവർ അല്ലാഹുവിലും പ്രവാചകനിലും വിശ്വസിക്കുകയും ചെയ്തു. ഈ സംഭവത്തെക്കുറിച്ചാണ് സൂറത്തുൽ ജിന്നിന്റെ തുടക്കത്തിൽ പരാമർശിക്കുന്നത്."}]}, {"surahNumber": 73, "surahNameArabic": "سُورَةُ المُزَّمِّلِ", "surahNameMalayalam": "സൂറത്തുൽ മുസ്സമ്മിൽ (പുതച്ചു മൂടിയവൻ)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ یَـٰۤأَیُّهَا ٱلۡمُزَّمِّلُ\n", "jalalayn": "«يا أيّها المُزَّمِّل» النَّبِيّ وأَصْله المُتَزَمِّل أُدْغِمَتْ التّاء فِي الزّاي أيْ المُتَلَفِّف بِثِيابِهِ حِين مَجِيء الوَحْي لَهُ خَوْفًا مِنهُ لِهَيْبَتِهِ", "malayalam": "«ഹേ വസ്ത്രം മൂടിപ്പുതച്ചവനേ! (നബിയേ!)».", "malayalamMatn": "ഹേ, വസ്ത്രം കൊണ്ട് മൂടിയവനേ,"}, {"ayahNumber": 2, "quranText": "قُمِ ٱلَّیۡلَ إِلَّا قَلِیلࣰا\n", "jalalayn": "«قُمْ اللَّيْل» صَلِّ", "malayalam": "«രാത്രിയിൽ നീ നമസ്കാരത്തിനായി എഴുന്നേറ്റു നിൽക്കുക; അല്പം സമയമൊഴികെ».", "malayalamMatn": "രാത്രി അല്‍പസമയം ഒഴിച്ച് എഴുന്നേറ്റ് നിന്ന് പ്രാര്‍ത്ഥിക്കുക."}, {"ayahNumber": 3, "quranText": "نِّصۡفَهُۥۤ أَوِ ٱنقُصۡ مِنۡهُ قَلِیلًا\n", "jalalayn": "«نِصْفه» بَدَل مِن قَلِيلًا وقِلَّته بِالنَّظَرِ إلى الكُلّ «أوْ اُنْقُصْ مِنهُ» مِن النِّصْف «قَلِيلًا» إلى الثُّلُث", "malayalam": "«അതിന്റെ പകുതി സമയം; അല്ലെങ്കിൽ അതിൽ നിന്ന് അല്പം കുറച്ചുകൊള്ളുക».", "malayalamMatn": "അതിന്‍റെ (രാത്രിയുടെ) പകുതി, അല്ലെങ്കില്‍ അതില്‍ നിന്നു (അല്‍പം) കുറച്ചു കൊള്ളുക."}, {"ayahNumber": 4, "quranText": "أَوۡ زِدۡ عَلَیۡهِ وَرَتِّلِ ٱلۡقُرۡءَانَ تَرۡتِیلًا\n", "jalalayn": "«أوْ زِدْ عَلَيْهِ» إلى الثُّلُثَيْنِ وأَوْ لِلتَّخْيِيرِ «ورَتِّلْ القُرْآن» تَثَبَّتْ فِي تِلاوَته", "malayalam": "«അതല്ലെങ്കിൽ അതിനേക്കാൾ അല്പം വർദ്ധിപ്പിക്കുക; ഖുർആൻ സാവകാശത്തിലും വ്യക്തതയോടെയും പാരായണം ചെയ്യുക».", "malayalamMatn": "അല്ലെങ്കില്‍ അതിനെക്കാള്‍ വര്‍ദ്ധിപ്പിച്ചു കൊള്ളുക. ഖുര്‍ആന്‍ സാവകാശത്തില്‍ പാരായണം നടത്തുകയും ചെയ്യുക."}, {"ayahNumber": 5, "quranText": "إِنَّا سَنُلۡقِی عَلَیۡكَ قَوۡلࣰا ثَقِیلًا\n", "jalalayn": "«إنّا سَنُلْقِي عَلَيْك قَوْلًا» قُرْآنًا «ثَقِيلًا» مُهِيبًا أوْ شَدِيدًا لِما فِيهِ مِن التَّكالِيف", "malayalam": "«തീർച്ചയായും ഭാരമേറിയ ഒരു വചനത്തെ നാം നിന്റെ മേൽ അവതരിപ്പിക്കാൻ പോകുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും നാം നിന്‍റെ മേല്‍ ഒരു കനപ്പെട്ട വാക്ക് ഇട്ടുതരുന്നതാണ്‌."}, {"ayahNumber": 6, "quranText": "إِنَّ نَاشِئَةَ ٱلَّیۡلِ هِیَ أَشَدُّ وَطۡـࣰٔا وَأَقۡوَمُ قِیلًا\n", "jalalayn": "«إنّ ناشِئَة اللَّيْل» القِيام بَعْد النَّوْم «هِيَ أشَدّ وطْئًا» مُوافَقَة السَّمْع لِلْقَلْبِ عَلى تَفَهُّم القُرْآن «وأَقْوَم قِيلًا» أبْيَن قَوْلًا", "malayalam": "«തീർച്ചയായും രാത്രിയിലെ എഴുന്നേൽപ് മനസ്സിന് കൂടുതൽ ഇണക്കമുള്ളതും സംസാരത്തിന് കൂടുതൽ കൃത്യതയുള്ളതുമാകുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും രാത്രിയില്‍ എഴുന്നേറ്റു നമസ്കരിക്കല്‍ കൂടുതല്‍ ശക്തമായ ഹൃദയസാന്നിദ്ധ്യം നല്‍കുന്നതും വാക്കിനെ കൂടുതല്‍ നേരെ നിര്‍ത്തുന്നതുമാകുന്നു."}, {"ayahNumber": 7, "quranText": "إِنَّ لَكَ فِی ٱلنَّهَارِ سَبۡحࣰا طَوِیلࣰا\n", "jalalayn": "«إنّ لَك فِي النَّهار سَبْحًا طَوِيلًا» تَصَرُّفًا فِي إشْغالك لا تَفْرُغ فِيهِ لِتِلاوَةِ القُرْآن", "malayalam": "«തീർച്ചയായും പകലിൽ നിനക്ക് ദീർഘമായ ജോലിത്തിരക്കുകളുണ്ട്».", "malayalamMatn": "തീര്‍ച്ചയായും നിനക്ക് പകല്‍ സമയത്ത് ദീര്‍ഘമായ ജോലിത്തിരക്കുണ്ട്‌."}, {"ayahNumber": 8, "quranText": "وَٱذۡكُرِ ٱسۡمَ رَبِّكَ وَتَبَتَّلۡ إِلَیۡهِ تَبۡتِیلࣰا\n", "jalalayn": "«واذْكُرْ اسْم رَبّك» أيْ قُلْ بِسْمِ اللَّه الرَّحْمَن الرَّحِيم فِي ابْتِداء قِراءَتك «وتَبَتَّلْ» انْقَطِعْ «إلَيْهِ تَبْتِيلًا» مَصْدَر بَتَلَ جِيءَ بِهِ رِعايَة لِلْفَواصِلِ وهُوَ مَلْزُوم التَّبَتُّل", "malayalam": "«നിന്റെ രക്ഷിതാവിന്റെ നാമം നീ സ്മരിക്കുകയും മറ്റെല്ലാറ്റിൽ നിന്നും വിട്ട് അവനിലേക്ക് പൂർണ്ണമായി തിരിയുകയും ചെയ്യുക».", "malayalamMatn": "നിന്‍റെ രക്ഷിതാവിന്‍റെ നാമം സ്മരിക്കുകയും, (മറ്റു ചിന്തകള്‍ വെടിഞ്ഞ്‌) അവങ്കലേങ്കു മാത്രമായി മടങ്ങുകയും ചെയ്യുക."}, {"ayahNumber": 9, "quranText": "رَّبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ لَاۤ إِلَـٰهَ إِلَّا هُوَ فَٱتَّخِذۡهُ وَكِیلࣰا\n", "jalalayn": "هُوَ «رَبّ المَشْرِق والمَغْرِب لا إلَه إلّا هُوَ فاِتَّخِذْهُ وكِيلًا» مُوَكِّلًا لَهُ أُمُورك", "malayalam": "«ഉദയത്തിന്റെയും അസ്തമയത്തിന്റെയും രക്ഷിതാവാകുന്നു അവൻ; അവനല്ലാതെ യാതൊരു ദൈവവുമില്ല; അതിനാൽ അവനെ നീ സംരക്ഷകനായി സ്വീകരിക്കുക».", "malayalamMatn": "ഉദയസ്ഥാനത്തിന്‍റെയും, അസ്തമനസ്ഥാനത്തിന്‍റെയും രക്ഷിതാവാകുന്നു അവന്‍. അവനല്ലാതെ യാതൊരു ദൈവവുമില്ല. അതിനാല്‍ ഭരമേല്‍പിക്കപ്പെടേണ്ടവനായി അവനെ സ്വീകരിക്കുക."}, {"ayahNumber": 10, "quranText": "وَٱصۡبِرۡ عَلَىٰ مَا یَقُولُونَ وَٱهۡجُرۡهُمۡ هَجۡرࣰا جَمِیلࣰا\n", "jalalayn": "«واصْبِرْ عَلى ما يَقُولُونَ» أيْ كُفّار مَكَّة مِن أذاهُمْ «واهْجُرْهُمْ هَجْرًا جَمِيلًا» لا جَزَع فِيهِ وهَذا قَبْل الأَمْر بِقِتالِهِمْ", "malayalam": "«അവർ പറയുന്നതിനെപ്പറ്റി നീ ക്ഷമിക്കുകയും ഭംഗിയായ രീതിയിൽ അവരിൽ നിന്ന് ഒഴിഞ്ഞുമാറുകയും ചെയ്യുക».", "malayalamMatn": "അവര്‍ (അവിശ്വാസികള്‍) പറയുന്നതിനെപ്പറ്റി നീ ക്ഷമിക്കുകയും, ഭംഗിയായ വിധത്തില്‍ അവരില്‍ നിന്ന് ഒഴിഞ്ഞു നില്‍ക്കുകയും ചെയ്യുക."}, {"ayahNumber": 11, "quranText": "وَذَرۡنِی وَٱلۡمُكَذِّبِینَ أُو۟لِی ٱلنَّعۡمَةِ وَمَهِّلۡهُمۡ قَلِیلًا\n", "jalalayn": "«وذَرْنِي» اُتْرُكْنِي «والمُكَذِّبِينَ» عَطْف عَلى المَفْعُول أوْ مَفْعُول مَعَهُ والمَعْنى أنا كافِيكَهُمْ وهُمْ صَنادِيد قُرَيْش «أُولِي النَّعْمَة» التَّنَعُّم «ومَهِّلْهُمْ قَلِيلًا» مِن الزَّمَن فَقُتِلُوا بَعْد يَسِير مِنهُ بِبَدْرٍ", "malayalam": "«സത്യനിഷേധികളായ ആ സുഖലോലുപരെയും എന്നെയും നീ വിട്ടേക്കുക; അവർക്ക് അല്പം സമയം നീ നീട്ടിക്കൊടുക്കുക».", "malayalamMatn": "എന്നെയും, സുഖാനുഗ്രഹങ്ങള്‍ ഉള്ളവരായ സത്യനിഷേധികളെയും വിട്ടേക്കുക. അവര്‍ക്കു അല്‍പം ഇടകൊടുക്കുകയും ചെയ്യുക."}, {"ayahNumber": 12, "quranText": "إِنَّ لَدَیۡنَاۤ أَنكَالࣰا وَجَحِیمࣰا\n", "jalalayn": "«إنّ لَدَيْنا أنْكالًا» قُيُودًا ثِقالًا جَمْع نِكْل بِكَسْرِ النُّون «وجَحِيمًا» نارًا مُحْرِقَة", "malayalam": "«തീർച്ചയായും നമ്മുടെ പക്കൽ കനത്ത ചങ്ങലകളും ജ്വലിക്കുന്ന നരകാഗ്നിയുമുണ്ട്».", "malayalamMatn": "തീര്‍ച്ചയായും നമ്മുടെ അടുക്കല്‍ കാല്‍ ചങ്ങലകളും ജ്വലിക്കുന്ന നരകാഗ്നിയും"}, {"ayahNumber": 13, "quranText": "وَطَعَامࣰا ذَا غُصَّةࣲ وَعَذَابًا أَلِیمࣰا\n", "jalalayn": "«وطَعامًا ذا غُصَّة» يَغَصّ بِهِ فِي الحَلْق وهُوَ الزَّقُّوم أوْ الضَّرِيع أوْ الغِسْلِين أوْ شَوْك مِن نار لا يَخْرُج ولا يَنْزِل «وعَذابًا ألِيمًا» مُؤْلِمًا زِيادَة عَلى ما ذُكِرَ لِمَن كَذَّبَ النَّبِيّ ﷺ", "malayalam": "«തൊണ്ടയിൽ കുടുങ്ങുന്ന ഭക്ഷണവും (സഖൂമും മുಳ್ಳുകളും) വേദനാജനകമായ ശിക്ഷയുമുണ്ട്».", "malayalamMatn": "തൊണ്ടയില്‍ അടഞ്ഞു നില്‍ക്കുന്ന ഭക്ഷണവും വേദനയേറിയ ശിക്ഷയുമുണ്ട്‌."}, {"ayahNumber": 14, "quranText": "یَوۡمَ تَرۡجُفُ ٱلۡأَرۡضُ وَٱلۡجِبَالُ وَكَانَتِ ٱلۡجِبَالُ كَثِیبࣰا مَّهِیلًا\n", "jalalayn": "«يَوْم تَرْجُف» تُزَلْزَل «الأَرْض والجِبال وكانَتْ الجِبال كَثِيبًا» رَمْلًا مُجْتَمِعًا «مَهِيلًا» سائِلًا بَعْد اجْتِماعه وهُوَ مِن هالَ يَهِيل وأَصْله مَهْيُول اُسْتُثْقِلَتْ الضَّمَّة عَلى الياء فَنُقِلَتْ إلى الهاء وحُذِفَتْ الواو ثانِي السّاكِنَيْنِ لِزِيادَتِها وقُلِبَتْ الضَّمَّة كَسْرَة لِمُجانَسَةِ الياء", "malayalam": "«ഭൂമിയും പർവ്വതങ്ങളും പ്രകമ്പനം കൊള്ളുകയും, പർവ്വതങ്ങൾ ചിതറിത്തെറിക്കുന്ന മണൽക്കൂനകൾ പോലെയായിത്തീരുകയും ചെയ്യുന്ന ദിവസം!».", "malayalamMatn": "ഭൂമിയും പര്‍വ്വതങ്ങളും വിറകൊള്ളുകയും പര്‍വ്വതങ്ങള്‍ ഒലിച്ചു പോകുന്ന മണല്‍ കുന്ന് പോലെയാവുകയും ചെയ്യുന്ന ദിവസത്തില്‍."}, {"ayahNumber": 15, "quranText": "إِنَّاۤ أَرۡسَلۡنَاۤ إِلَیۡكُمۡ رَسُولࣰا شَـٰهِدًا عَلَیۡكُمۡ كَمَاۤ أَرۡسَلۡنَاۤ إِلَىٰ فِرۡعَوۡنَ رَسُولࣰا\n", "jalalayn": "«إنّا أرْسَلْنا إلَيْكُمْ» يا أهْل مَكَّة «رَسُولًا» هُوَ مُحَمَّد ﷺ «شاهِدًا عَلَيْكُمْ» يَوْم القِيامَة بِما يَصْدُر مِنكُمْ مِن العِصْيان «كَما أرْسَلْنا إلى فِرْعَوْن رَسُولًا» هُوَ مُوسى عَلَيْهِ الصَّلاة والسَّلام", "malayalam": "«തീർച്ചയായും ഫിർഔന്റെ അടുക്കലേക്ക് ഒരു റസൂലിനെ നാം അയച്ചതുപോലെ നിങ്ങളുടെ നേരെയും സാക്ഷിയായിക്കൊണ്ട് ഒരു റസൂലിനെ നാം അയച്ചിരിക്കുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും നിങ്ങളിലേക്ക് നിങ്ങളുടെ കാര്യത്തിന് സാക്ഷിയായിട്ടുള്ള ഒരു ദൂതനെ നാം നിയോഗിച്ചിരിക്കുന്നു. ഫിര്‍ഔന്‍റെ അടുത്തേക്ക് നാം ഒരു ദൂതനെ നിയോഗിച്ചത് പോലെത്തന്നെ."}, {"ayahNumber": 16, "quranText": "فَعَصَىٰ فِرۡعَوۡنُ ٱلرَّسُولَ فَأَخَذۡنَـٰهُ أَخۡذࣰا وَبِیلࣰا\n", "jalalayn": "«فَعَصى فِرْعَوْن الرَّسُول فَأَخَذْناهُ أخْذًا وبِيلًا» شَدِيدًا", "malayalam": "«എന്നിട്ട് ഫിർഔൻ ആ റസൂലിനോട് അനുസരണക്കേട് കാണിച്ചു; അപ്പോൾ അതികഠിനമായ പിടിത്തം കൊണ്ട് നാം അവനെ പിടികൂടി».", "malayalamMatn": "എന്നിട്ട് ഫിര്‍ഔന്‍ ആ ദൂതനോട് ധിക്കാരം കാണിച്ചു. അപ്പോള്‍ നാം അവനെ കടുത്ത ഒരു പിടുത്തം പിടിക്കുകയുണ്ടായി."}, {"ayahNumber": 17, "quranText": "فَكَیۡفَ تَتَّقُونَ إِن كَفَرۡتُمۡ یَوۡمࣰا یَجۡعَلُ ٱلۡوِلۡدَ ٰ⁠نَ شِیبًا\n", "jalalayn": "«فَكَيْفَ تَتَّقُونَ إنْ كَفَرْتُمْ» فِي الدُّنْيا «يَوْمًا» مَفْعُول تَتَّقُونَ أيْ عَذابه بِأَيِّ حِصْن تَتَحَصَّنُونَ مِن عَذاب يَوْم «يَجْعَل الوِلْدان شِيبًا» جَمْع أشْيَب لِشِدَّةِ هَوْله وهُوَ يَوْم القِيامَة والأَصْل فِي شِين شِيبًا الضَّمّ وكُسِرَتْ لِمُجانَسَةِ الياء ويُقال فِي اليَوْم الشَّدِيد يَوْم يَشِيب نَواصِي الأَطْفال وهُوَ مَجاز ويَجُوز أنْ يَكُون المُراد فِي الآيَة الحَقِيقَة", "malayalam": "«എന്നിരിക്കെ നിങ്ങൾ അവിശ്വസിക്കുകയാണെങ്കിൽ കുട്ടികളെ നരച്ചവരാക്കി മാറ്റുന്ന ആ ദിവസത്തെ നിങ്ങൾ എങ്ങനെ പ്രതിരോധിക്കും?».", "malayalamMatn": "എന്നാല്‍ നിങ്ങള്‍ അവിശ്വസിക്കുകയാണെങ്കില്‍, കുട്ടികളെ നരച്ചവരാക്കിത്തീര്‍ക്കുന്ന ഒരു ദിവസത്തെ നിങ്ങള്‍ക്ക് എങ്ങനെ സൂക്ഷിക്കാനാവും?"}, {"ayahNumber": 18, "quranText": "ٱلسَّمَاۤءُ مُنفَطِرُۢ بِهِۦۚ كَانَ وَعۡدُهُۥ مَفۡعُولًا\n", "jalalayn": "«السَّماء مُنْفَطِر» ذات انْفِطار أيْ انْشِقاق «بِهِ» بِذَلِكَ اليَوْم لِشِدَّتِهِ «كانَ وعْده» تَعالى بِمَجِيءِ ذَلِكَ «مَفْعُولًا» أيْ هُوَ كائِن لا مَحالَة", "malayalam": "«ആകാശം അത് കാരണം പൊട്ടിപ്പിളരുന്നതായിരിക്കും; അവന്റെ വാഗ്ദത്തം നടപ്പിലാക്കപ്പെടുന്നതാകുന്നു».", "malayalamMatn": "അതു നിമിത്തം ആകാശം പൊട്ടിപ്പിളരുന്നതാണ്‌. അല്ലാഹുവിന്‍റെ വാഗ്ദാനം പ്രാവര്‍ത്തികമാക്കപ്പെടുന്നതാകുന്നു."}, {"ayahNumber": 19, "quranText": "إِنَّ هَـٰذِهِۦ تَذۡكِرَةࣱۖ فَمَن شَاۤءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِیلًا\n", "jalalayn": "«إنّ هَذِهِ» الآيات المَخُوفَة «تَذْكِرَة» عِظَة لِلْخَلْقِ «فَمَن شاءَ اتَّخَذَ إلى رَبّه سَبِيلًا» طَرِيقًا بِالإيمانِ والطّاعَة", "malayalam": "«തീർച്ചയായും ഇതൊരു ഉൽബോധനമാകുന്നു; അതിനാൽ ആരെങ്കിലും ഉദ്ദേശിക്കുന്ന പക്ഷം തന്റെ രക്ഷിതാവിങ്കലേക്ക് ഒരു മാർഗ്ഗം സ്വീകരിക്കട്ടെ».", "malayalamMatn": "തീര്‍ച്ചയായും ഇതൊരു ഉല്‍ബോധനമാകുന്നു. അതിനാല്‍ വല്ലവനും ഉദ്ദേശിക്കുന്ന പക്ഷം അവന്‍ തന്‍റെ രക്ഷിതാവിങ്കലേക്ക് ഒരു മാര്‍ഗം സ്വീകരിച്ചു കൊള്ളട്ടെ."}, {"ayahNumber": 20, "quranText": "۞ إِنَّ رَبَّكَ یَعۡلَمُ أَنَّكَ تَقُومُ أَدۡنَىٰ مِن ثُلُثَیِ ٱلَّیۡلِ وَنِصۡفَهُۥ وَثُلُثَهُۥ وَطَاۤىِٕفَةࣱ مِّنَ ٱلَّذِینَ مَعَكَۚ وَٱللَّهُ یُقَدِّرُ ٱلَّیۡلَ وَٱلنَّهَارَۚ عَلِمَ أَن لَّن تُحۡصُوهُ فَتَابَ عَلَیۡكُمۡۖ فَٱقۡرَءُوا۟ مَا تَیَسَّرَ مِنَ ٱلۡقُرۡءَانِۚ عَلِمَ أَن سَیَكُونُ مِنكُم مَّرۡضَىٰ وَءَاخَرُونَ یَضۡرِبُونَ فِی ٱلۡأَرۡضِ یَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ وَءَاخَرُونَ یُقَـٰتِلُونَ فِی سَبِیلِ ٱللَّهِۖ فَٱقۡرَءُوا۟ مَا تَیَسَّرَ مِنۡهُۚ وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَقۡرِضُوا۟ ٱللَّهَ قَرۡضًا حَسَنࣰاۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنۡ خَیۡرࣲ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَیۡرࣰا وَأَعۡظَمَ أَجۡرࣰاۚ وَٱسۡتَغۡفِرُوا۟ ٱللَّهَۖ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمُۢ\n", "jalalayn": "«إنّ رَبّك يَعْلَم أنَّك تَقُوم أدْنى» أقَلّ «مِن ثُلُثَيْ اللَّيْل ونِصْفه وثُلُثه» بِالجَرِّ عَطْف عَلى ثُلُثَيْ وبِالنَّصْبِ عَلى أدْنى وقِيامه كَذَلِكَ نَحْو ما أمَرَ بِهِ أوَّل السُّورَة «وطائِفَة مِن الَّذِينَ مَعَك» عَطْف عَلى ضَمِير تَقُوم وجازَ مِن غَيْر تَأْكِيد لِلْفَصْلِ وقِيام طائِفَة مِن أصْحابه كَذَلِكَ لِلتَّأَسِّي بِهِ ومِنهُمْ مَن كانَ لا يَدْرِي كَمْ صَلّى مِن اللَّيْل وكَمْ بَقِيَ مِنهُ فَكانَ يَقُوم اللَّيْل كُلّه احْتِياطًا فَقامُوا حَتّى انْتَفَخَتْ أقْدامهمْ سَنَة أوْ أكْثَر فَخُفِّفَ عَنْهُمْ «واللَّه يُقَدِّر» يُحْصِي «اللَّيْل والنَّهار عَلِمَ أنْ» مُخَفَّفَة مِن الثَّقِيلَة واسْمها مَحْذُوف أيْ أنَّهُ «لَنْ تُحْصُوهُ» أيْ اللَّيْل لِتَقُومُوا فِيما يَجِب القِيام فِيهِ إلّا بِقِيامِ جَمِيعه وذَلِكَ يَشُقّ عَلَيْكُمْ «فَتابَ عَلَيْكُمْ» رَجَعَ بِكُمْ إلى التَّخْفِيف «فاقْرَءُوا ما تَيَسَّرَ مِن القُرْآن» فِي الصَّلاة بِأَنْ تُصَلُّوا ما تَيَسَّرَ «عَلِمَ أنْ» مُخَفَّفَة مِن الثَّقِيلَة أيْ أنَّهُ «سَيَكُونُ مِنكُمْ مَرْضى وآخَرُونَ يَضْرِبُونَ فِي الأَرْض» يُسافِرُونَ «يَبْتَغُونَ مِن فَضْل اللَّه» يَطْلُبُونَ مِن رِزْقه بِالتِّجارَةِ وغَيْرها «وآخَرُونَ يُقاتِلُونَ فِي سَبِيل اللَّه» وكُلّ مِن الفِرَق الثَّلاثَة يَشُقّ عَلَيْهِمْ ما ذُكِرَ فِي قِيام اللَّيْل فَخَفَّفَ عَنْهُمْ بِقِيامِ ما تَيَسَّرَ مِنهُ ثُمَّ نَسَخَ ذَلِكَ بِالصَّلَواتِ الخَمْس «فاقْرَءُوا ما تَيَسَّرَ مِنهُ» كَما تَقَدَّمَ «وأَقِيمُوا الصَّلاة» المَفْرُوضَة «وآتُوا الزَّكاة وأَقْرِضُوا اللَّه» بِأَنْ تُنْفِقُوا ما سِوى المَفْرُوض مِن المال فِي سَبِيل الخَيْر «قَرْضًا حَسَنًا» عَنْ طِيب قَلْب «وما تُقَدِّمُوا لِأَنْفُسِكُمْ مِن خَيْر تَجِدُوهُ عِنْد اللَّه هُوَ خَيْرًا» مِمّا خَلَفْتُمْ وهُوَ فَصْل وما بَعْده وإنْ لَمْ يَكُنْ مَعْرِفَة يُشْبِهها لِامْتِناعِهِ مِن التَّعْرِيف «وأَعْظَم أجْرًا واسْتَغْفِرُوا اللَّه إنّ اللَّه غَفُور رَحِيم» لِلْمُؤْمِنِينَ", "malayalam": "«രാത്രിയുടെ മൂന്നിൽ രണ്ട് ഭാഗത്തോ പകുതിയോ മൂന്നിലൊന്നോ നീയും നിന്റെ കൂടെയുള്ളവരിൽ നിന്നൊരു വിഭാഗവും നമസ്കാരത്തിനായി എഴുന്നേറ്റു നിൽക്കുന്നുണ്ടെന്ന് നിന്റെ രക്ഷിതാവ് തീർച്ചയായും അറിയുന്നു; അല്ലാഹുവാണ് രാത്രിയെയും പകലിനെയും കൃത്യമായി കണക്കാക്കുന്നത്; അത് പൂർണ്ണമായി തിട്ടപ്പെടുത്താൻ നിങ്ങൾക്ക് സാധിക്കുകയില്ലെന്ന് അവൻ അറിഞ്ഞിരിക്കുന്നു, അതിനാൽ അവൻ നിങ്ങളുടെ മേൽ ഇളവ് നൽകിയിരിക്കുന്നു; ആകയാൽ ഖുർആനിൽ നിന്ന് നിങ്ങൾക്ക് എളുപ്പമായത് നിങ്ങൾ പാരായണം ചെയ്യുവിൻ; നിങ്ങളിൽ രോഗികളുണ്ടാകുമെന്നും, അല്ലാഹുവിന്റെ ഔദാര്യം തേടിക്കൊണ്ട് ഭൂമിയിൽ യാത്ര ചെയ്യുന്ന മറ്റുചിലരുണ്ടാകുമെന്നും, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുന്ന വേറെ ചിലരുണ്ടാകുമെന്നും അവൻ അറിഞ്ഞിരിക്കുന്നു; അതിനാൽ അതിൽ നിന്ന് എളുപ്പമായത് നിങ്ങൾ ഓതുക; നിങ്ങൾ നമസ്കാരം മുറപ്രകാരം നിലനിർത്തുകയും സകാത്ത് നൽകുകയും അല്ലാഹുവിന് ഉത്തമമായ കടം നൽകുകയും ചെയ്യുവിൻ; നിങ്ങളുടെ സ്വന്തം ശരീരങ്ങൾക്കായി നന്മയിൽ നിന്ന് എന്തൊന്ന് നിങ്ങൾ മുൻകൂട്ടി ചെയ്തുവെച്ചാലും അല്ലാഹുവിങ്കൽ കൂടുതൽ ഉത്തമവും പ്രതിഫലത്തിൽ ഏറ്റവും വലുതുമായി അത് നിങ്ങൾ കണ്ടെത്തുന്നതാണ്; നിങ്ങൾ അല്ലാഹുവോട് പാപമോചനം തേടുവിൻ, തീർച്ചയായും അല്ലാഹു ഏറെ പൊറുക്കുന്നവനും ദയാപരനുമാകുന്നു!».", "malayalamMatn": "നീയും നിന്‍റെ കൂടെയുള്ളവരില്‍ ഒരു വിഭാഗവും രാത്രിയുടെ മിക്കവാറും മൂന്നില്‍ രണ്ടു ഭാഗവും (ചിലപ്പോള്‍) പകുതിയും (ചിലപ്പോള്‍) മൂന്നിലൊന്നും നിന്നു നമസ്കരിക്കുന്നുണ്ട് എന്ന് തീര്‍ച്ചയായും നിന്‍റെ രക്ഷിതാവിന്നറിയാം. അല്ലാഹുവാണ് രാത്രിയെയും പകലിനെയും കണക്കാക്കുന്നത്‌. നിങ്ങള്‍ക്ക് അത് ക്ലിപ്തപ്പെടുത്താനാവുകയില്ലെന്ന് അവന്നറിയാം. അതിനാല്‍ അവന്‍ നിങ്ങള്‍ക്ക് ഇളവ് ചെയ്തിരിക്കുന്നു. ആകയാല്‍ നിങ്ങള്‍ ഖുര്‍ആനില്‍ നിന്ന് സൌകര്യപ്പെട്ടത് ഓതിക്കൊണ്ട് നമസ്കരിക്കുക. നിങ്ങളുടെ കൂട്ടത്തില്‍ രോഗികളും ഭൂമിയില്‍ സഞ്ചരിച്ച് അല്ലാഹുവിന്‍റെ അനുഗ്രഹം തേടിക്കൊണ്ടിരിക്കുന്ന വേറെ ചിലരും അല്ലാഹുവിന്‍റെ മാര്‍ഗത്തില്‍ യുദ്ധം ചെയ്യുന്ന മറ്റ് ചിലരും ഉണ്ടാകും എന്ന് അല്ലാഹുവിന്നറിയാം. അതിനാല്‍ അതില്‍ (ഖുര്‍ആനില്‍) നിന്ന് സൌകര്യപ്പെട്ടത് നിങ്ങള്‍ പാരായണം ചെയ്തു കൊള്ളുകയും നമസ്കാരം മുറപ്രകാരം നിര്‍വഹിക്കുകയും സകാത്ത് നല്‍കുകയും അല്ലാഹുവിന്ന് ഉത്തമമായ കടം നല്‍കുകയും ചെയ്യുക. സ്വദേഹങ്ങള്‍ക്ക് വേണ്ടി നിങ്ങള്‍ എന്തൊരു നന്‍മ മുന്‍കൂട്ടി ചെയ്ത് വെക്കുകയാണെങ്കിലും അല്ലാഹുവിങ്കല്‍ അത് ഗുണകരവും ഏറ്റവും മഹത്തായ പ്രതിഫലമുള്ളതുമായി നിങ്ങള്‍ കണ്ടെത്തുന്നതാണ്‌. നിങ്ങള്‍ അല്ലാഹുവോട് പാപമോചനം തേടുകയും ചെയ്യുക. തീര്‍ച്ചയായും അല്ലാഹു ഏറെ പൊറുക്കുന്നവനും കരുണാനിധിയുമാകുന്നു."}], "topPoints": ["രാത്രി നമസ്കാരത്തിന്റെ (തഹജ്ജുദ്) പ്രാധാന്യം", "ഖുർആൻ സാവകാശം പാരായണം ചെയ്യുക"], "topQuestions": [{"q": "ഈ സൂറത്തിൽ നബി(സ)യോടുള്ള ആദ്യ കൽപന?", "a": "രാത്രി എഴുന്നേറ്റ് നിന്ന് നമസ്കരിക്കുക എന്നത്."}], "asbabAlNuzul": []}, {"surahNumber": 74, "surahNameArabic": "سُورَةُ المُدَّثِّرِ", "surahNameMalayalam": "സൂറത്തുൽ മുദ്ദസ്സിർ (വസ്ത്രം ചുറ്റിയവൻ)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ یَـٰۤأَیُّهَا ٱلۡمُدَّثِّرُ\n", "jalalayn": "«يا أيّها المُدَّثِّر» النَّبِيّ ﷺ وأَصْله المُتَدَثِّر أُدْغِمَتْ التّاء فِي الدّال أيْ المُتَلَفِّف بِثِيابِهِ عِنْد نُزُول الوَحْي عَلَيْهِ", "malayalam": "«ഹേ വസ്ത്രം ചുറ്റിപ്പൊതിഞ്ഞവനേ! (നബിയേ!)».", "malayalamMatn": "ഹേ, പുതച്ചു മൂടിയവനേ,"}, {"ayahNumber": 2, "quranText": "قُمۡ فَأَنذِرۡ\n", "jalalayn": "«قُمْ فَأَنْذِرْ» خَوِّفْ أهْل مَكَّة النّار إنْ لَمْ يُؤْمِنُوا", "malayalam": "«നീ എഴുന്നേൽക്കുക, എന്നിട്ട് താക്കീത് നൽകുക!».", "malayalamMatn": "എഴുന്നേറ്റ് (ജനങ്ങളെ) താക്കീത് ചെയ്യുക."}, {"ayahNumber": 3, "quranText": "وَرَبَّكَ فَكَبِّرۡ\n", "jalalayn": "«ورَبّك فَكَبِّرْ» عَظِّمْ عَنْ إشْراك المُشْرِكِينَ", "malayalam": "«നിന്റെ രക്ഷിതാവിന്റെ മഹത്വത്തെ നീ പ്രകീർത്തിക്കുക!».", "malayalamMatn": "നിന്‍റെ രക്ഷിതാവിനെ മഹത്വപ്പെടുത്തുകയും"}, {"ayahNumber": 4, "quranText": "وَثِیَابَكَ فَطَهِّرۡ\n", "jalalayn": "«وثِيابك فَطَهِّرْ» عَنْ النَّجاسَة أوْ قَصِّرْها خِلاف جَرّ العَرَب ثِيابهمْ خُيَلاء فَرُبَّما أصابَتْها نَجاسَة", "malayalam": "«നിന്റെ വസ്ത്രങ്ങളെ നീ ശുദ്ധിയാക്കുക!».", "malayalamMatn": "നിന്‍റെ വസ്ത്രങ്ങള്‍ ശുദ്ധിയാക്കുകയും"}, {"ayahNumber": 5, "quranText": "وَٱلرُّجۡزَ فَٱهۡجُرۡ\n", "jalalayn": "«والرُّجْز» فَسَّرَهُ النَّبِيّ ﷺ بِالأَوْثانِ «فاهْجُرْ» أيْ دُمْ عَلى هَجْره", "malayalam": "«സർവ്വവിധ അഴുക്കുകളെയും (വിഗ്രഹങ്ങളെയും പാപങ്ങളെയും) നീ വെടിയുക!».", "malayalamMatn": "പാപം വെടിയുകയും ചെയ്യുക."}, {"ayahNumber": 6, "quranText": "وَلَا تَمۡنُن تَسۡتَكۡثِرُ\n", "jalalayn": "«ولا تَمْنُنْ تَسْتَكْثِر» بِالرَّفْعِ حال أيْ لا تُعْطِ شَيْئًا لِتَطْلُب أكْثَر مِنهُ وهَذا خاصّ بِهِ ﷺ لِأَنَّهُ مَأْمُور بِأَجْمَل الأَخْلاق وأَشْرَف الآداب", "malayalam": "«കൂടുതൽ നേട്ടം കൊതിച്ചുകൊണ്ട് നീ ദാനം ചെയ്യരുത്!».", "malayalamMatn": "കൂടുതല്‍ നേട്ടം കൊതിച്ചു കൊണ്ട് നീ ഔദാര്യം ചെയ്യരുത്‌."}, {"ayahNumber": 7, "quranText": "وَلِرَبِّكَ فَٱصۡبِرۡ\n", "jalalayn": "«ولِرَبِّك فاصْبِرْ» عَلى الأَوامِر والنَّواهِي", "malayalam": "«നിന്റെ രക്ഷിതാവിന് വേണ്ടി നീ ക്ഷമയോടെ കാത്തിരിക്കുക!».", "malayalamMatn": "നിന്‍റെ രക്ഷിതാവിനു വേണ്ടി നീ ക്ഷമ കൈക്കൊള്ളുക."}, {"ayahNumber": 8, "quranText": "فَإِذَا نُقِرَ فِی ٱلنَّاقُورِ\n", "jalalayn": "«فَإذا نُقِرَ فِي النّاقُور» نُفِخَ فِي الصُّور وهُوَ القَرْن النَّفْخَة الثّانِيَة", "malayalam": "«കാഹളത്തിൽ ഊതപ്പെട്ടാൽ!».", "malayalamMatn": "എന്നാല്‍ കാഹളത്തില്‍ മുഴക്കപ്പെട്ടാല്‍"}, {"ayahNumber": 9, "quranText": "فَذَ ٰ⁠لِكَ یَوۡمَىِٕذࣲ یَوۡمٌ عَسِیرٌ\n", "jalalayn": "«فَذَلِكَ» أيْ وقْت النَّقْر «يَوْمئِذٍ» بَدَل مِمّا قَبْله المُبْتَدَأ وبُنِيَ لِإضافَتِهِ إلى غَيْر مُتَمَكِّن وخَبَر المُبْتَدَأ «يَوْم عَسِير» والعامِل فِي إذا ما دَلَّتْ عَلَيْهِ الجُمْلَة اشْتَدَّ الأَمْر", "malayalam": "«അന്നേ ദിവസം വളരെ പ്രയാസകരമായ ഒരു ദിവസമായിരിക്കും!».", "malayalamMatn": "അന്ന് അത് ഒരു പ്രയാസകരമായ ദിവസമായിരിക്കും."}, {"ayahNumber": 10, "quranText": "عَلَى ٱلۡكَـٰفِرِینَ غَیۡرُ یَسِیرࣲ\n", "jalalayn": "«عَلى الكافِرِينَ غَيْر يَسِير» فِيهِ دَلالَة عَلى أنَّهُ يَسِير عَلى المُؤْمِنِينَ فِي عُسْره", "malayalam": "«സത്യനിഷേധികൾക്ക് ഒട്ടും എളുപ്പമല്ലാത്ത ദിവസം!».", "malayalamMatn": "സത്യനിഷേധികള്‍ക്ക് എളുപ്പമുള്ളതല്ലാത്ത ഒരു ദിവസം!"}, {"ayahNumber": 11, "quranText": "ذَرۡنِی وَمَنۡ خَلَقۡتُ وَحِیدࣰا\n", "jalalayn": "«ذَرْنِي» اُتْرُكْنِي «ومَن خَلَقْت» عَطْف عَلى المَفْعُول أوْ مَفْعُول مَعَهُ «وحِيدًا» حال مِن مَن أوْ مِن ضَمِيره المَحْذُوف مِن خَلَقْت مُنْفَرِدًا بِلا أهْل ولا مال هُوَ الوَلِيد بْن المُغِيرَة المَخْزُومِيّ", "malayalam": "«ഞാൻ ഒറ്റയായി സൃഷ്ടിച്ച ആ വ്യക്തിയെയും എന്നെയും നീ വിട്ടേക്കുക! (വലീദ് ബിൻ മുഗീറയെ)».", "malayalamMatn": "എന്നെയും ഞാന്‍ ഏകനായിക്കൊണ്ട് സൃഷ്ടിച്ച ഒരുത്തനെയും വിട്ടേക്കുക."}, {"ayahNumber": 12, "quranText": "وَجَعَلۡتُ لَهُۥ مَالࣰا مَّمۡدُودࣰا\n", "jalalayn": "«وجَعَلْت لَهُ مالًا مَمْدُودًا» واسِعًا مُتَّصِلًا مِن الزُّرُوع والضُّرُوع والتِّجارَة", "malayalam": "«അവന് ഞാൻ ധാരാളം സമ്പത്ത് നൽകി».", "malayalamMatn": "അവന്ന് ഞാന്‍ സമൃദ്ധമായ സമ്പത്ത് ഉണ്ടാക്കി കൊടുക്കുകയും ചെയ്തു."}, {"ayahNumber": 13, "quranText": "وَبَنِینَ شُهُودࣰا\n", "jalalayn": "«وبَنِينَ» عَشَرَة أوْ أكْثَر «شُهُودًا» يَشْهَدُونَ المَحافِل وتُسْمَع شَهاداتهمْ", "malayalam": "«എപ്പോഴും കൂടെയുണ്ടായിരുന്ന മക്കളെയും നൽകി».", "malayalamMatn": "സന്നദ്ധരായി നില്‍ക്കുന്ന സന്തതികളെയും"}, {"ayahNumber": 14, "quranText": "وَمَهَّدتُّ لَهُۥ تَمۡهِیدࣰا\n", "jalalayn": "«ومَهَّدْت» بَسَطْت «لَهُ» فِي العَيْش والعُمُر والوَلَد", "malayalam": "«അവന് ഞാൻ ജീവിതസൗകര്യങ്ങൾ വിശാലമാക്കി നൽകുകയും ചെയ്തു».", "malayalamMatn": "അവന്നു ഞാന്‍ നല്ല സൌകര്യങ്ങള്‍ ചെയ്തു കൊടുക്കുകയും ചെയ്തു."}, {"ayahNumber": 15, "quranText": "ثُمَّ یَطۡمَعُ أَنۡ أَزِیدَ\n", "jalalayn": "«ثُمَّ یَطۡمَعُ أَنۡ أَزِیدَ».", "malayalam": "«എന്നിട്ടും ഞാൻ ഇനിയും വർദ്ധിപ്പിച്ചു നൽകണമെന്ന് അവൻ കൊതിക്കുകയാണ്!».", "malayalamMatn": "പിന്നെയും ഞാന്‍ കൂടുതല്‍ കൊടുക്കണമെന്ന് അവന്‍ മോഹിക്കുന്നു."}, {"ayahNumber": 16, "quranText": "كَلَّاۤۖ إِنَّهُۥ كَانَ لِـَٔایَـٰتِنَا عَنِیدࣰا\n", "jalalayn": "«كَلّا» لا أزِيدهُ عَلى ذَلِكَ «إنّهُ كانَ لِآياتِنا» القُرْآن «عَنِيدًا» مُعانِدًا", "malayalam": "«ഒരിക്കലുമില്ല! തീർച്ചയായും അവൻ നമ്മുടെ ദൃഷ്ടാന്തങ്ങളോട് കടുത്ത ശത്രുത പുലർത്തുന്നവനായിരുന്നു».", "malayalamMatn": "അല്ല, തീര്‍ച്ചയായും അവന്‍ നമ്മുടെ ദൃഷ്ടാന്തങ്ങളോട് മാത്സര്യം കാണിക്കുന്നവനായിരിക്കുന്നു."}, {"ayahNumber": 17, "quranText": "سَأُرۡهِقُهُۥ صَعُودًا\n", "jalalayn": "«سَأُرْهِقُهُ» أُكَلِّفهُ «صَعُودًا» مَشَقَّة مِن العَذاب أوْ جَبَلًا مِن نار يَصْعَد فِيهِ ثُمَّ يَهْوِي أبَدًا", "malayalam": "«വഴിയെ കയറാൻ പ്രയാസമുള്ള ഒരു കഠിനശിക്ഷയിലേക്ക് നാം അവനെ കയറ്റുന്നതാണ്!».", "malayalamMatn": "പ്രയാസമുള്ള ഒരു കയറ്റം കയറാന്‍ നാം വഴിയെ അവനെ നിര്‍ബന്ധിക്കുന്നതാണ്‌."}, {"ayahNumber": 18, "quranText": "إِنَّهُۥ فَكَّرَ وَقَدَّرَ\n", "jalalayn": "«إنّهُ فَكَّرَ» فِيما يَقُول فِي القُرْآن الَّذِي سَمِعَهُ مِن النَّبِيّ ﷺ «وقَدَّرَ» فِي نَفْسه ذَلِكَ", "malayalam": "«തീർച്ചയായും അവൻ ചിന്തിക്കുകയും പദ്ധതി തയ്യാറാക്കുകയും ചെയ്തു».", "malayalamMatn": "തീര്‍ച്ചയായും അവനൊന്നു ചിന്തിച്ചു, അവനൊന്നു കണക്കാക്കുകയും ചെയ്തു."}, {"ayahNumber": 19, "quranText": "فَقُتِلَ كَیۡفَ قَدَّرَ\n", "jalalayn": "«فَقُتِلَ» لُعِنَ وعُذِّبَ «كَيْفَ قَدَّرَ» عَلى أيّ حال كانَ تَقْدِيره", "malayalam": "«അവൻ നശിക്കട്ടെ! എങ്ങനെയാണവൻ പദ്ധതിയിട്ടത്!».", "malayalamMatn": "അതിനാല്‍ അവന്‍ നശിക്കട്ടെ. എങ്ങനെയാണവന്‍ കണക്കാക്കിയത്‌?"}, {"ayahNumber": 20, "quranText": "ثُمَّ قُتِلَ كَیۡفَ قَدَّرَ\n", "jalalayn": "«ثُمَّ قُتِلَ كَیۡفَ قَدَّرَ».", "malayalam": "«വീണ്ടും അവൻ നശിക്കട്ടെ! എങ്ങനെയാണവൻ കണക്കുകൂട്ടിയത്!».", "malayalamMatn": "വീണ്ടും അവന്‍ നശിക്കട്ടെ, എങ്ങനെയാണവന്‍ കണക്കാക്കിയത്‌?"}, {"ayahNumber": 21, "quranText": "ثُمَّ نَظَرَ\n", "jalalayn": "«ثُمَّ نَظَرَ» فِي وُجُوه قَوْمه أوْ فِيما يَقْدَح بِهِ فِيهِ", "malayalam": "«പിന്നീട് അവൻ നോക്കി».", "malayalamMatn": "പിന്നീട് അവനൊന്നു നോക്കി."}, {"ayahNumber": 22, "quranText": "ثُمَّ عَبَسَ وَبَسَرَ\n", "jalalayn": "«ثُمَّ عَبَسَ» قَبَضَ وجْهه وكَلَّحَهُ ضِيقًا بِما يَقُول «وبَسَرَ» زادَ فِي القَبْض والكُلُوح", "malayalam": "«പിന്നെ അവൻ നെറ്റി ചുളിക്കുകയും മുഖം കറുപ്പിക്കുകയും ചെയ്തു».", "malayalamMatn": "പിന്നെ അവന്‍ മുഖം ചുളിക്കുകയും മുഖം കറുപ്പിക്കുകയും ചെയ്തു."}, {"ayahNumber": 23, "quranText": "ثُمَّ أَدۡبَرَ وَٱسۡتَكۡبَرَ\n", "jalalayn": "«ثُمَّ أدْبَرَ» عَنْ الإيمان «واسْتَكْبَرَ» تَكَبَّرَ عَنْ اتِّباع النَّبِيّ ﷺ", "malayalam": "«പിന്നീട് അവൻ പുറംതിരിഞ്ഞു പോകുകയും അഹങ്കരിക്കുകയും ചെയ്തു».", "malayalamMatn": "പിന്നെ അവന്‍ പിന്നോട്ട് മാറുകയും അഹങ്കാരം നടിക്കുകയും ചെയ്തു."}, {"ayahNumber": 24, "quranText": "فَقَالَ إِنۡ هَـٰذَاۤ إِلَّا سِحۡرࣱ یُؤۡثَرُ\n", "jalalayn": "«فَقالَ» فِيما جاءَ بِهِ «إنْ» ما «هَذا إلّا سِحْر يُؤْثَر» يُنْقَل عَنْ السَّحَرَة", "malayalam": "«എന്നിട്ട് അവൻ പറഞ്ഞു: ഇത് പൂർവ്വികരിൽ നിന്ന് ഉദ്ധരിക്കപ്പെടുന്ന ജാലവിദ്യയല്ലാതെ മറ്റൊന്നുമല്ല!».", "malayalamMatn": "എന്നിട്ടവന്‍ പറഞ്ഞു: ഇത് (ആരില്‍ നിന്നോ) ഉദ്ധരിക്കപ്പെടുന്ന മാരണമല്ലാതെ മറ്റൊന്നുമല്ല."}, {"ayahNumber": 25, "quranText": "إِنۡ هَـٰذَاۤ إِلَّا قَوۡلُ ٱلۡبَشَرِ\n", "jalalayn": "«إنْ» ما «هَذا إلّا قَوْل البَشَر» كَما قالُوا إنّما يُعَلِّمهُ بَشَر", "malayalam": "«ഇത് മനുഷ്യന്റെ വാക്കല്ലാതെ മറ്റൊന്നുമല്ല!».", "malayalamMatn": "ഇത് മനുഷ്യന്‍റെ വാക്കല്ലാതെ മറ്റൊന്നുമല്ല."}, {"ayahNumber": 26, "quranText": "سَأُصۡلِیهِ سَقَرَ\n", "jalalayn": "«سَأُصْلِيهِ» أُدْخِلهُ «سَقَر» جَهَنَّم", "malayalam": "«വഴിയെ അവനെ നാം സഖർ എന്ന നരകത്തിലിട്ട് എരിക്കുന്നതാണ്!».", "malayalamMatn": "വഴിയെ ഞാന്‍ അവനെ സഖറില്‍ (നരകത്തില്‍) ഇട്ട് എരിക്കുന്നതാണ്‌."}, {"ayahNumber": 27, "quranText": "وَمَاۤ أَدۡرَىٰكَ مَا سَقَرُ\n", "jalalayn": "«وما أدْراك ما سَقَر» تَعْظِيمًا لِشَأْنِها", "malayalam": "«സഖർ എന്നാൽ എന്താണെന്ന് നിനക്ക് എന്തറിയാം?».", "malayalamMatn": "സഖര്‍ എന്നാല്‍ എന്താണെന്ന് നിനക്കറിയുമോ?"}, {"ayahNumber": 28, "quranText": "لَا تُبۡقِی وَلَا تَذَرُ\n", "jalalayn": "«لا تُبْقِي ولا تَذَر» شَيْئًا مِن لَحْم ولا عَصَب إلّا أهْلَكَتْهُ ثُمَّ يَعُود كَما كانَ", "malayalam": "«അത് ഒന്നിനെയും ബാക്കിവെക്കുകയില്ല, ഒന്നിനെയും ഉപേക്ഷിക്കുകയുമില്ല!».", "malayalamMatn": "അത് ഒന്നും ബാക്കിയാക്കുകയോ വിട്ടുകളയുകയോ ഇല്ല."}, {"ayahNumber": 29, "quranText": "لَوَّاحَةࣱ لِّلۡبَشَرِ\n", "jalalayn": "«لَوّاحَة لِلْبَشَرِ» مُحَرِّقَة لِظاهِرِ الجِلْد", "malayalam": "«തൊലിയെ കരിച്ചു കറുപ്പിക്കുന്ന നരകം!».", "malayalamMatn": "അത് തൊലി കരിച്ച് രൂപം മാറ്റിക്കളയുന്നതാണ്‌."}, {"ayahNumber": 30, "quranText": "عَلَیۡهَا تِسۡعَةَ عَشَرَ\n", "jalalayn": "«عَلَيْها تِسْعَة عَشَر» مَلَكًا خَزَنَتها قالَ بَعْض الكُفّار وكانَ قَوِيًّا شَدِيد البَأْس أنا أكْفِيكُمْ سَبْعَة عَشَر واكْفُونِي أنْتُمْ اثْنَيْنِ قالَ تَعالى:", "malayalam": "«അതിന്മേൽ പത്തൊമ്പത് കാവൽക്കാരുണ്ട് (മലക്കുകൾ)».", "malayalamMatn": "അതിന്‍റെ മേല്‍നോട്ടത്തിന് പത്തൊമ്പത് പേരുണ്ട്‌."}, {"ayahNumber": 31, "quranText": "وَمَا جَعَلۡنَاۤ أَصۡحَـٰبَ ٱلنَّارِ إِلَّا مَلَـٰۤىِٕكَةࣰۖ وَمَا جَعَلۡنَا عِدَّتَهُمۡ إِلَّا فِتۡنَةࣰ لِّلَّذِینَ كَفَرُوا۟ لِیَسۡتَیۡقِنَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ وَیَزۡدَادَ ٱلَّذِینَ ءَامَنُوۤا۟ إِیمَـٰنࣰا وَلَا یَرۡتَابَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ وَٱلۡمُؤۡمِنُونَ وَلِیَقُولَ ٱلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ وَٱلۡكَـٰفِرُونَ مَاذَاۤ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلࣰاۚ كَذَ ٰ⁠لِكَ یُضِلُّ ٱللَّهُ مَن یَشَاۤءُ وَیَهۡدِی مَن یَشَاۤءُۚ وَمَا یَعۡلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَۚ وَمَا هِیَ إِلَّا ذِكۡرَىٰ لِلۡبَشَرِ\n", "jalalayn": "«وما جَعَلْنا أصْحاب النّار إلّا مَلائِكَة» أيْ فَلا يُطاقُونَ كَما يَتَوَهَّمُونَ «وما جَعَلْنا عِدَّتهمْ» ذَلِكَ «إلّا فِتْنَة» ضَلالًا «لِلَّذِينَ كَفَرُوا» بِأَنْ يَقُولُوا لِمَ كانُوا تِسْعَة عَشَر «لِيَسْتَيْقِن» لِيَسْتَبِينَ «الَّذِينَ أُوتُوا الكِتاب» أيْ اليَهُود صِدْق النَّبِيّ ﷺ فِي كَوْنهمْ تِسْعَة عَشَر المُوافِق لِما فِي كِتابهمْ «ويَزْداد الَّذِينَ آمَنُوا» مِن أهْل الكِتاب «إيمانًا» تَصْدِيقًا لِمُوافَقَتِهِ ما أتى بِهِ النَّبِيّ ﷺ لِما فِي كِتابهمْ «ولا يَرْتاب الَّذِينَ أُوتُوا الكِتاب والمُؤْمِنُونَ» مِن غَيْرهمْ فِي عَدَد المَلائِكَة «ولِيَقُولَ الَّذِينَ فِي قُلُوبهمْ مَرَض» شَكّ بِالمَدِينَةِ «والكافِرُونَ» بِمَكَّة «ماذا أرادَ اللَّه بِهَذا» العَدَد «مَثَلًا» سَمَّوْهُ لِغَرابَتِهِ بِذَلِكَ وأُعْرِبَ حالًا «كَذَلِكَ» أيْ مِثْل إضْلال مُنْكِر هَذا العَدَد وهَدى مُصَدِّقه «يُضِلّ اللَّه مَن يَشاء ويَهْدِي مَن يَشاء وما يَعْلَم جُنُود رَبّك» أيْ المَلائِكَة فِي قُوَّتهمْ وأَعْوانهمْ «إلّا هُوَ وما هِيَ» أيْ سَقَر", "malayalam": "«നരകത്തിന്റെ കാവൽക്കാരായി മലക്കുകളെയല്ലാതെ നാം നിശ്ചയിച്ചിട്ടില്ല; അവരുടെ എണ്ണത്തെ സത്യനിഷേധികൾക്കുള്ള ഒരു പരീക്ഷണമായിട്ടല്ലാതെ നാം ആക്കിയിട്ടുമില്ല; വേദം നൽകപ്പെട്ടവർക്ക് ദൃഢബോധ്യം വരുവാനും, സത്യവിശ്വാസികൾക്ക് വിശ്വാസം വർദ്ധിക്കുവാനും, വേദക്കാരും വിശ്വാസികളും സംശയിക്കാതിരിക്കുവാനും, ഹൃദയങ്ങളിൽ രോഗമുള്ളവരും അവിശ്വാസികളും ഇത് കൊണ്ട് അല്ലാഹു എന്തൊരു ഉപമയാണ് ഉദ്ദേശിച്ചതെന്ന് ചോദിക്കുവാനും വേണ്ടിയത്രെ അത്; അപ്രകാരം അല്ലാഹു താൻ ഉദ്ദേശിക്കുന്നവരെ വഴിപിഴപ്പിക്കുകയും താൻ ഉദ്ദേശിക്കുന്നവരെ നേർവഴിയിലാക്കുകയും ചെയ്യുന്നു; നിന്റെ രക്ഷിതാവിന്റെ സൈന്യങ്ങളെ അവനല്ലാതെ മറ്റാരും അറിയുകയില്ല; ഇത് മനുഷ്യർക്കുള്ള ഒരു ഉൽബോധനമല്ലാതെ മറ്റൊന്നുമല്ല».", "malayalamMatn": "നരകത്തിന്‍റെ മേല്‍നോട്ടക്കാരായി നാം മലക്കുകളെ മാത്രമാണ് നിശ്ചയിച്ചിരിക്കുന്നത്‌. അവരുടെ എണ്ണത്തെ നാം സത്യനിഷേധികള്‍ക്ക് ഒരു പരീക്ഷണം മാത്രമാക്കിയിരിക്കുന്നു. വേദം നല്‍കപ്പെട്ടിട്ടുള്ളവര്‍ക്ക് ദൃഢബോധ്യം വരുവാനും സത്യവിശ്വാസികള്‍ക്ക് വിശ്വാസം വര്‍ദ്ധിക്കാനും വേദം നല്‍കപ്പെട്ടവരും സത്യവിശ്വാസികളും സംശയത്തിലകപ്പെടാതിരിക്കാനും അല്ലാഹു എന്തൊരു ഉപമയാണ് ഇതു കൊണ്ട് ഉദ്ദേശിച്ചിട്ടുള്ളതെന്ന് ഹൃദയങ്ങളില്‍ രോഗമുള്ളവരും സത്യനിഷേധികളും പറയുവാനും വേണ്ടിയത്രെ അത്‌. അപ്രകാരം അല്ലാഹു താന്‍ ഉദ്ദേശിക്കുന്നവരെ പിഴപ്പിക്കുകയും, താന്‍ ഉദ്ദേശിക്കുന്നവരെ നേര്‍വഴിയിലാക്കുകയും ചെയ്യുന്നു. നിന്‍റെ രക്ഷിതാവിന്‍റെ സൈന്യങ്ങളെ അവനല്ലാതെ മറ്റാരും അറിയുകയില്ല. ഇത് മനുഷ്യര്‍ക്ക് ഒരു ഉല്‍ബോധനമല്ലാതെ മറ്റൊന്നുമല്ല."}, {"ayahNumber": 32, "quranText": "كَلَّا وَٱلۡقَمَرِ\n", "jalalayn": "«كَلّا» اسْتِفْتاح بِمَعْنى ألّا", "malayalam": "«തീർച്ചയായും ചന്ദ്രനെക്കൊണ്ട് സത്യം!».", "malayalamMatn": "നിസ്സംശയം, ചന്ദ്രനെ തന്നെയാണ സത്യം."}, {"ayahNumber": 33, "quranText": "وَٱلَّیۡلِ إِذۡ أَدۡبَرَ\n", "jalalayn": "«واللَّيْل إذا» بِفَتْحِ الذّال «أدْبَرَ» جاءَ بَعْد النَّهار وفِي قِراءَة إذا أدْبَرَ بِسُكُونِ الذّال بَعْدها هَمْزَة أيْ مَضى", "malayalam": "«പിൻവാങ്ങിപ്പോകുന്ന രാത്രിയെക്കൊണ്ട് സത്യം!».", "malayalamMatn": "രാത്രി പിന്നിട്ട് പോകുമ്പോള്‍ അതിനെ തന്നെയാണ സത്യം."}, {"ayahNumber": 34, "quranText": "وَٱلصُّبۡحِ إِذَاۤ أَسۡفَرَ\n", "jalalayn": "«والصُّبْح إذا أسْفَرَ» ظَهَرَ", "malayalam": "«വെളിച്ചം പരത്തുന്ന പ്രഭാതത്തെക്കൊണ്ട് സത്യം!».", "malayalamMatn": "പ്രഭാതം പുലര്‍ന്നാല്‍ അതു തന്നെയാണ സത്യം."}, {"ayahNumber": 35, "quranText": "إِنَّهَا لَإِحۡدَى ٱلۡكُبَرِ\n", "jalalayn": "«إنّها» أيْ سَقَر «لَإحْدى الكُبَر» البَلايا العِظام", "malayalam": "«തീർച്ചയായും അത് ഏറ്റവും വലിയ വിപത്തുകളിൽ ഒന്നാകുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും അത് (നരകം) ഗൌരവമുള്ള കാര്യങ്ങളില്‍ ഒന്നാകുന്നു."}, {"ayahNumber": 36, "quranText": "نَذِیرࣰا لِّلۡبَشَرِ\n", "jalalayn": "«نَذِيرًا» حال مِن إحْدى وذُكِّرَ لِأَنَّها بِمَعْنى العَذاب", "malayalam": "«മനുഷ്യർക്കുള്ള ഒരു താക്കീതായിക്കൊണ്ട്».", "malayalamMatn": "മനുഷ്യര്‍ക്ക് ഒരു താക്കീതെന്ന നിലയില്‍."}, {"ayahNumber": 37, "quranText": "لِمَن شَاۤءَ مِنكُمۡ أَن یَتَقَدَّمَ أَوۡ یَتَأَخَّرَ\n", "jalalayn": "«لِمَن شاءَ مِنكُمْ» بَدَل مِن البَشَر «أنْ يَتَقَدَّم» إلى الخَيْر أوْ الجَنَّة بِالإيمانِ «أوْ يَتَأَخَّر» إلى الشَّرّ أوْ النّار بِالكُفْرِ", "malayalam": "«നിങ്ങളിൽ നിന്ന് മുന്നോട്ട് വരാനോ പിന്നോട്ട് പോകാനോ ഉദ്ദേശിക്കുന്നവർക്കായിക്കൊണ്ട്».", "malayalamMatn": "അതായത് നിങ്ങളില്‍ നിന്ന് മുന്നോട്ട് പോകുവാനോ, പിന്നോട്ട് വെക്കുവാനോ ഉദ്ദേശിക്കുന്നവര്‍ക്ക്‌."}, {"ayahNumber": 38, "quranText": "كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡ رَهِینَةٌ\n", "jalalayn": "«كُلّ نَفْس بِما كَسَبَتْ رَهِينَة» مَرْهُونَة مَأْخُوذَة بِعَمَلِها فِي النّار", "malayalam": "«ഓരോ വ്യക്തിയും താൻ സമ്പാദിച്ചുവെച്ച കർമ്മങ്ങൾക്ക് പണയപ്പെട്ടവനാകുന്നു».", "malayalamMatn": "ഓരോ വ്യക്തിയും താന്‍ സമ്പാദിച്ചു വെച്ചതിന് പണയപ്പെട്ടവനാകുന്നു."}, {"ayahNumber": 39, "quranText": "إِلَّاۤ أَصۡحَـٰبَ ٱلۡیَمِینِ\n", "jalalayn": "«إلّا أصْحاب اليَمِين» وهُمْ المُؤْمِنُونَ فَناجُونَ مِنها كائِنُونَ", "malayalam": "«വലതുപക്ഷക്കാരൊഴികെ!».", "malayalamMatn": "വലതുപക്ഷക്കാരൊഴികെ."}, {"ayahNumber": 40, "quranText": "فِی جَنَّـٰتࣲ یَتَسَاۤءَلُونَ\n", "jalalayn": "«فِي جَنّات يَتَساءَلُونَ» بَيْنهمْ", "malayalam": "«അവർ സ്വർഗ്ഗത്തോപ്പുകളിലായിരിക്കും; അവർ പരസ്പരം അന്വേഷിക്കും:».", "malayalamMatn": "ചില സ്വര്‍ഗത്തോപ്പുകളിലായിരിക്കും അവര്‍. അവര്‍ അന്വേഷിക്കും;"}, {"ayahNumber": 41, "quranText": "عَنِ ٱلۡمُجۡرِمِینَ\n", "jalalayn": "«عَنْ المُجْرِمِينَ» وحالهمْ ويَقُولُونَ لَهُمْ بَعْد إخْراج المُوَحِّدِينَ مِن النّار", "malayalam": "«ആ കുറ്റവാളികളെക്കുറിച്ച്:».", "malayalamMatn": "കുറ്റവാളികളെപ്പറ്റി"}, {"ayahNumber": 42, "quranText": "مَا سَلَكَكُمۡ فِی سَقَرَ\n", "jalalayn": "«ما سَلَكَكُمْ» أدْخَلَكُمْ", "malayalam": "«എന്ത് കാര്യമാണ് നിങ്ങളെ സഖർ എന്ന നരകത്തിലെത്തിച്ചത്?».", "malayalamMatn": "നിങ്ങളെ നരകത്തില്‍ പ്രവേശിപ്പിച്ചത് എന്തൊന്നാണെന്ന്‌."}, {"ayahNumber": 43, "quranText": "قَالُوا۟ لَمۡ نَكُ مِنَ ٱلۡمُصَلِّینَ\n", "jalalayn": "«قَالُوا۟ لَمۡ نَكُ مِنَ ٱلۡمُصَلِّینَ».", "malayalam": "«അവർ പറയും: ഞങ്ങൾ നമസ്കരിക്കുന്നവരുടെ കൂട്ടത്തിലായിരുന്നില്ല!».", "malayalamMatn": "അവര്‍ (കുറ്റവാളികള്‍) മറുപടി പറയും: ഞങ്ങള്‍ നമസ്കരിക്കുന്നവരുടെ കൂട്ടത്തിലായില്ല."}, {"ayahNumber": 44, "quranText": "وَلَمۡ نَكُ نُطۡعِمُ ٱلۡمِسۡكِینَ\n", "jalalayn": "«وَلَمۡ نَكُ نُطۡعِمُ ٱلۡمِسۡكِینَ».", "malayalam": "«ഞങ്ങൾ അഗതികൾക്ക് ഭക്ഷണം നൽകുമായിരുന്നില്ല!».", "malayalamMatn": "ഞങ്ങള്‍ അഗതിക്ക് ആഹാരം നല്‍കുമായിരുന്നില്ല."}, {"ayahNumber": 45, "quranText": "وَكُنَّا نَخُوضُ مَعَ ٱلۡخَاۤىِٕضِینَ\n", "jalalayn": "«وكُنّا نَخُوض» فِي الباطِل", "malayalam": "«വ്യർത്ഥവർത്തമാനങ്ങളിൽ ഏർപ്പെടുന്നവരോടൊപ്പം ഞങ്ങളും മുഴുകുമായിരുന്നു!».", "malayalamMatn": "തോന്നിവാസത്തില്‍ മുഴുകുന്നവരുടെ കൂടെ ഞങ്ങളും മുഴുകുമായിരുന്നു."}, {"ayahNumber": 46, "quranText": "وَكُنَّا نُكَذِّبُ بِیَوۡمِ ٱلدِّینِ\n", "jalalayn": "«وكُنّا نُكَذِّب بِيَوْمِ الدِّين» البَعْث والجَزاء", "malayalam": "«പ്രതിഫലദിനത്തെ ഞങ്ങൾ നിഷേധിച്ചു തള്ളുമായിരുന്നു!».", "malayalamMatn": "പ്രതിഫലത്തിന്‍റെ നാളിനെ ഞങ്ങള്‍ നിഷേധിച്ചു കളയുമായിരുന്നു."}, {"ayahNumber": 47, "quranText": "حَتَّىٰۤ أَتَىٰنَا ٱلۡیَقِینُ\n", "jalalayn": "«حَتّى أتانا اليَقِين» المَوْت", "malayalam": "«അങ്ങനെ ആ ഉറപ്പായ കാര്യം (മരണം) ഞങ്ങൾക്ക് വന്നെത്തുന്നതുവരെ!».", "malayalamMatn": "അങ്ങനെയിരിക്കെ ആ ഉറപ്പായ മരണം ഞങ്ങള്‍ക്ക് വന്നെത്തി."}, {"ayahNumber": 48, "quranText": "فَمَا تَنفَعُهُمۡ شَفَـٰعَةُ ٱلشَّـٰفِعِینَ\n", "jalalayn": "«فَما تَنْفَعهُمْ شَفاعَة الشّافِعِينَ» مِن المَلائِكَة والأَنْبِياء والصّالِحِينَ والمَعْنى لا شَفاعَة لَهُمْ", "malayalam": "«അപ്പോൾ ശുപാർശക്കാരുടെ ശുപാർശയൊന്നും അവർക്ക് ഉപകരിക്കുകയില്ല».", "malayalamMatn": "ഇനി അവര്‍ക്ക് ശുപാര്‍ശക്കാരുടെ ശുപാര്‍ശയൊന്നും പ്രയോജനപ്പെടുകയില്ല."}, {"ayahNumber": 49, "quranText": "فَمَا لَهُمۡ عَنِ ٱلتَّذۡكِرَةِ مُعۡرِضِینَ\n", "jalalayn": "«فَما» مُبْتَدَأ «لَهُمْ» خَبَره مُتَعَلِّق بِمَحْذُوفٍ انْتَقَلَ ضَمِيره إلَيْهِ «عَنْ التَّذْكِرَة مُعْرِضِينَ» حال مِن الضَّمِير والمَعْنى أيّ شَيْء حَصَلَ لَهُمْ فِي إعْراضهمْ عَنْ الِاتِّعاظ", "malayalam": "«എന്നിരിക്കെ അവർക്ക് എന്തു പറ്റി, ഉൽബോധനത്തിൽ നിന്ന് തിരിഞ്ഞുകളയുവാൻ?».", "malayalamMatn": "എന്നിരിക്കെ അവര്‍ക്കെന്തു പറ്റി? അവര്‍ ഉല്‍ബോധനത്തില്‍ നിന്ന് തിരിഞ്ഞുകളയുന്നവരായിരിക്കുന്നു."}, {"ayahNumber": 50, "quranText": "كَأَنَّهُمۡ حُمُرࣱ مُّسۡتَنفِرَةࣱ\n", "jalalayn": "«كَأَنَّهُمْ حُمُر مُسْتَنْفِرَة» وحْشِيَّة", "malayalam": "«വിരണ്ടോടുന്ന കാട്ടുകഴുതകളെപ്പോലെ!».", "malayalamMatn": "അവര്‍ വിറളി പിടിച്ച കഴുതകളെപ്പോലിരിക്കുന്നു."}, {"ayahNumber": 51, "quranText": "فَرَّتۡ مِن قَسۡوَرَةِۭ\n", "jalalayn": "«فَرَّتْ مِن قَسْوَرَة» أسَد أيْ هَرَبَتْ مِنهُ أشَدّ الهَرَب", "malayalam": "«സിംഹത്തെക്കണ്ട് ഭയന്നോടിയവയെപ്പോലെ!».", "malayalamMatn": "സിംഹത്തില്‍ നിന്ന് ഓടിരക്ഷപ്പെടുന്ന (കഴുതകള്‍)"}, {"ayahNumber": 52, "quranText": "بَلۡ یُرِیدُ كُلُّ ٱمۡرِئࣲ مِّنۡهُمۡ أَن یُؤۡتَىٰ صُحُفࣰا مُّنَشَّرَةࣰ\n", "jalalayn": "«بَلْ يُرِيد كُلّ امْرِئٍ مِنهُمْ أنْ يُؤْتى صُحُفًا مُنَشَّرَة» أيْ مِن اللَّه تَعالى بِاتِّباعِ النَّبِيّ كَما قالُوا: لَنْ نُؤْمِن لَك حَتّى تُنَزِّل عَلَيْنا كِتابًا نَقْرَؤُهُ", "malayalam": "«അല്ല, അവരിൽ ഓരോരുത്തരും ആഗ്രഹിക്കുന്നത് തങ്ങൾക്ക് തുറന്നുവെച്ച ഏടുകൾ നൽകപ്പെടണമെന്നാണ്! (നബിയെ പിന്തുടരണമെന്ന് ഓരോരുത്തർക്കും പ്രത്യേകം കത്ത് വരണമെന്ന് അവർ വാദിച്ചു)».", "malayalamMatn": "അല്ല, അവരില്‍ ഓരോരുത്തരും ആഗ്രഹിക്കുന്നു; തനിക്ക് അല്ലാഹുവിങ്കല്‍ നിന്ന് നിവര്‍ത്തിയ ഏടുകള്‍ നല്‍കപ്പെടണമെന്ന്‌."}, {"ayahNumber": 53, "quranText": "كَلَّاۖ بَل لَّا یَخَافُونَ ٱلۡـَٔاخِرَةَ\n", "jalalayn": "«كَلّا» رَدْع عَمّا أرادُوهُ «بَلْ لا يَخافُونَ الآخِرَة» أيْ عَذابها", "malayalam": "«ഒരിക്കലുമില്ല! അവർ പരലോകത്തെ ഭയപ്പെടുന്നില്ല».", "malayalamMatn": "അല്ല; പക്ഷെ, അവര്‍ പരലോകത്തെ ഭയപ്പെടുന്നില്ല."}, {"ayahNumber": 54, "quranText": "كَلَّاۤ إِنَّهُۥ تَذۡكِرَةࣱ\n", "jalalayn": "«كَلّا» اسْتِفْتاح «إنّهُ» أيْ القُرْآن «تَذْكِرَة» عِظَة", "malayalam": "«തീർച്ചയായും ഇത് മഹത്തായ ഒരു ഉൽബോധനം തന്നെയാകുന്നു».", "malayalamMatn": "അല്ല; തീര്‍ച്ചയായും ഇത് ഒരു ഉല്‍ബോധനമാകുന്നു."}, {"ayahNumber": 55, "quranText": "فَمَن شَاۤءَ ذَكَرَهُۥ\n", "jalalayn": "«فَمَن شاءَ ذَكَرَهُ» قَرَأَهُ فاتَّعَظَ بِهِ", "malayalam": "«ആകയാൽ ആരെങ്കിലും ഉദ്ദേശിക്കുന്ന പക്ഷം അതോർത്തു മനസ്സിലാക്കട്ടെ».", "malayalamMatn": "ആകയാല്‍ ആര്‍ ഉദ്ദേശിക്കുന്നുവോ അവരത് ഓര്‍മിച്ചു കൊള്ളട്ടെ."}, {"ayahNumber": 56, "quranText": "وَمَا یَذۡكُرُونَ إِلَّاۤ أَن یَشَاۤءَ ٱللَّهُۚ هُوَ أَهۡلُ ٱلتَّقۡوَىٰ وَأَهۡلُ ٱلۡمَغۡفِرَةِ\n", "jalalayn": "«وما يَذْكُرُونَ» بِالياءِ والتّاء «إلّا أنْ يَشاء اللَّه هُوَ أهْل التَّقْوى» بِأَنْ يُتَّقى «وأَهْل المَغْفِرَة» بِأَنْ يَغْفِر لِمَن اتَّقاهُ", "malayalam": "«എന്നാൽ അല്ലാഹു ഉദ്ദേശിച്ചാലല്ലാതെ അവരത് ഓർക്കുകയില്ല; അവനാകുന്നു ഭയപ്പെടാൻ അർഹതയുള്ളവൻ, പാപങ്ങൾ പൊറുത്തുതരാൻ അർഹതയുള്ളവനും അവൻ തന്നെയാകുന്നു».", "malayalamMatn": "അല്ലാഹു ഉദ്ദേശിക്കുന്നുവെങ്കിലല്ലാതെ അവര്‍ ഓര്‍മിക്കുന്നതല്ല. അവനാകുന്നു ഭക്തിക്കവകാശപ്പെട്ടവന്‍; പാപമോചനത്തിന് അവകാശപ്പെട്ടവന്‍."}], "topPoints": ["പ്രബോധന രംഗത്തേക്കിറങ്ങാനുള്ള കൽപന (خلاصة السورة)", "നരകത്തിന്റെ കാവൽക്കാരുടെ എണ്ണം"], "topQuestions": [{"q": "ഈ സൂറത്തിൽ അല്ലാഹു നബിയോട് എന്ത് ആവശ്യപ്പെടുന്നു?", "a": "എഴുന്നേറ്റ് ജനങ്ങൾക്ക് മുന്നറിയിപ്പ് നൽകാനും നാഥന്റെ മഹത്വം പ്രകീർത്തിക്കാനും."}], "asbabAlNuzul": [{"ayahNumber": 1, "quranText": "یَـٰۤأَیُّهَا ٱلۡمُدَّثِّرُ • قُمۡ فَأَنذِرۡ", "arabicSnippet": "نزلت لما رأى النبي ﷺ الملك الذي جاءه بحراء بين السماء والأرض فرعب منه ورجع إلى أهله فقال: دثروني دثروني وصبوا علي ماء باردا، فأنزل الله: «يا أيها المدثر قم فأنذر».", "malayalamExplanation": "ഹിറാ ഗുഹയിൽ ആദ്യ വഹ്‌യ് ലഭിച്ചതിന് ശേഷം കുറച്ചുകാലം വഹ്‌യ് നിലച്ചുനിന്നിരുന്നു (ഫത്‌റത്തുൽ വഹ്‌യ്). ഒരിക്കൽ നടന്നുപോകുമ്പോൾ ആകാശത്ത് നിന്ന് ഒരു ശബ്ദം കേട്ട് തലയുയർത്തി നോക്കിയപ്പോൾ ഹിറാ ഗുഹയിൽ വന്ന അതേ ജിബ്‌രീൽ (അ) ആകാശത്തിനും ഭൂമിക്കുമിടയിൽ ഒരു പീഠത്തിൽ ഇരിക്കുന്നത് കണ്ട് നബി ﷺ ഭയവിഹ്വലനായി വീട്ടിലെത്തി 'എന്നെ പുതപ്പിച്ചു തരൂ, എന്നെ പുതപ്പിച്ചു തരൂ' എന്ന് പറഞ്ഞു. ആ സന്ദർഭത്തിലാണ് പുതച്ചു മൂടിയ നബിയോട് എഴുന്നേറ്റ് ലോകത്തിന് താക്കീത് നൽകാൻ കൽപ്പിച്ചുകൊണ്ട് സൂറത്തുൽ മുദ്ദഥ്ഥിർ അവതരിച്ചത്."}]}, {"surahNumber": 75, "surahNameArabic": "سُورَةُ القِيَامَةِ", "surahNameMalayalam": "സൂറത്തുൽ ഖിയാമ (ഉയിർത്തെഴുന്നേൽപ്)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ لَاۤ أُقۡسِمُ بِیَوۡمِ ٱلۡقِیَـٰمَةِ\n", "jalalayn": "«لا» زائِدَة فِي المَوْضِعَيْنِ", "malayalam": "«ഖിയാമത്ത് നാളിനെക്കൊണ്ട് ഞാൻ സത്യം ചെയ്തു പറയുന്നു!».", "malayalamMatn": "ഉയിര്‍ത്തെഴുന്നേല്‍പിന്‍റെ നാളുകൊണ്ട് ഞാനിതാ സത്യം ചെയ്യുന്നു."}, {"ayahNumber": 2, "quranText": "وَلَاۤ أُقۡسِمُ بِٱلنَّفۡسِ ٱللَّوَّامَةِ\n", "jalalayn": "«ولا أُقْسِم بِالنَّفْسِ اللَّوّامَة» الَّتِي تَلُوم نَفْسها وإنْ اجْتَهَدَتْ فِي الإحْسان وجَواب القَسَم مَحْذُوف أيْ لَتُبْعَثُنَّ دَلَّ عَلَيْهِ:", "malayalam": "«സ്വയം പഴിചാകുന്ന മനസ്സിനെക്കൊണ്ടും ഞാൻ സത്യം ചെയ്തു പറയുന്നു!».", "malayalamMatn": "കുറ്റപ്പെടുത്തുന്ന മനസ്സിനെക്കൊണ്ടും ഞാന്‍ സത്യം ചെയ്തു പറയുന്നു."}, {"ayahNumber": 3, "quranText": "أَیَحۡسَبُ ٱلۡإِنسَـٰنُ أَلَّن نَّجۡمَعَ عِظَامَهُۥ\n", "jalalayn": "«أيَحْسَبُ الإنْسان» أيْ الكافِر «ألَّنْ نَجْمَع عِظامه» لِلْبَعْثِ والإحْياء", "malayalam": "«മനുഷ്യൻ വിചാരിക്കുകയാണോ അവന്റെ അസ്ഥികളെ നാം ഒരുമിച്ചുകൂട്ടുകയേ ഇല്ലെന്ന്?».", "malayalamMatn": "മനുഷ്യന്‍ വിചാരിക്കുന്നുണ്ടോ; നാം അവന്‍റെ എല്ലുകളെ ഒരുമിച്ചുകൂട്ടുകയില്ലെന്ന്‌?"}, {"ayahNumber": 4, "quranText": "بَلَىٰ قَـٰدِرِینَ عَلَىٰۤ أَن نُّسَوِّیَ بَنَانَهُۥ\n", "jalalayn": "«بَلى» نَجْمَعها «قادِرِينَ» مَعَ جَمْعها «عَلى أنْ نُسَوِّيَ بَنانه» وهُوَ الأَصابِع أيْ نُعِيد عِظامها كَما كانَتْ مَعَ صِغَرها فَكَيْفَ بِالكَبِيرَةِ", "malayalam": "«അതെ, അവന്റെ വിരൽത്തുമ്പുകളെപ്പോലും കൃത്യമായി പുനർനിർമ്മിക്കുവാൻ നാം ശക്തനാകുന്നു!».", "malayalamMatn": "അതെ, നാം അവന്‍റെ വിരല്‍ത്തുമ്പുകളെ പോലും ശരിപ്പെടുത്താന്‍ കഴിവുള്ളവനായിരിക്കെ."}, {"ayahNumber": 5, "quranText": "بَلۡ یُرِیدُ ٱلۡإِنسَـٰنُ لِیَفۡجُرَ أَمَامَهُۥ\n", "jalalayn": "«بَلْ يُرِيد الإنْسان لِيَفْجُر» اللّام زائِدَة ونَصَبَهُ بِأَنْ مُقَدَّرَة أيْ أنْ يُكَذِّب «أمامه» أيْ يَوْم القِيامَة دَلَّ عَلَيْهِ:", "malayalam": "«പക്ഷേ മനുഷ്യൻ തന്റെ ഭാവിജീവിതത്തിലും തിന്മകൾ ചെയ്തുകൊണ്ടിരിക്കാൻ ആഗ്രഹിക്കുകയാണ്».", "malayalamMatn": "പക്ഷെ (എന്നിട്ടും) മനുഷ്യന്‍ അവന്‍റെ ഭാവി ജീവിതത്തില്‍ തോന്നിവാസം ചെയ്യാന്‍ ഉദ്ദേശിക്കുന്നു."}, {"ayahNumber": 6, "quranText": "یَسۡـَٔلُ أَیَّانَ یَوۡمُ ٱلۡقِیَـٰمَةِ\n", "jalalayn": "«يَسْأَل أيّانَ» مَتى «يَوْم القِيامَة» سُؤال اسْتِهْزاء وتَكْذِيب", "malayalam": "«അവൻ ചോദിക്കുന്നു: എപ്പോഴാണ് ഈ ഉയിർത്തെഴുന്നേൽപിന്റെ നാൾ?».", "malayalamMatn": "എപ്പോഴാണ് ഈ ഉയിര്‍ത്തെഴുന്നേല്‍പിന്‍റെ നാള്‍ എന്നവന്‍ ചോദിക്കുന്നു."}, {"ayahNumber": 7, "quranText": "فَإِذَا بَرِقَ ٱلۡبَصَرُ\n", "jalalayn": "«فَإذا بَرِقَ البَصَر» بِكَسْرِ الرّاء وفَتْحها فِي بَرِقَ بِمَعْنى دَهَشَ وتَحَيَّرَ لِما رَأى مِمّا كانَ يُكَذِّبهُ", "malayalam": "«എന്നാൽ കാഴ്ച ഭയത്താൽ മിഴിച്ചുപോകുകയും!».", "malayalamMatn": "എന്നാല്‍ കണ്ണ് അഞ്ചിപ്പോകുകയും"}, {"ayahNumber": 8, "quranText": "وَخَسَفَ ٱلۡقَمَرُ\n", "jalalayn": "«وخَسَفَ القَمَر» أظْلَمَ وذَهَبَ ضَوْءُهُ", "malayalam": "«ചന്ദ്രന് ഗ്രഹണം ബാധിക്കുകയും!».", "malayalamMatn": "ചന്ദ്രന്ന് ഗ്രഹണം ബാധിക്കുകയും"}, {"ayahNumber": 9, "quranText": "وَجُمِعَ ٱلشَّمۡسُ وَٱلۡقَمَرُ\n", "jalalayn": "«وجُمِعَ الشَّمْس والقَمَر» فَطَلَعا مِن المَغْرِب أوْ ذَهَبَ ضَوْءُهُما وذَلِكَ فِي يَوْم القِيامَة", "malayalam": "«സൂര്യനും ചന്ദ്രനും ഒരുമിച്ചുകൂട്ടപ്പെടുകയും ചെയ്താൽ!».", "malayalamMatn": "സൂര്യനും ചന്ദ്രനും ഒരുമിച്ചുകൂട്ടപ്പെടുകയും ചെയ്താല്‍!"}, {"ayahNumber": 10, "quranText": "یَقُولُ ٱلۡإِنسَـٰنُ یَوۡمَىِٕذٍ أَیۡنَ ٱلۡمَفَرُّ\n", "jalalayn": "«يَقُول الإنْسان يَوْمئِذٍ أيْنَ المَفَرّ» الفِرار", "malayalam": "«അന്നേ ദിവസം മനുഷ്യൻ പറയും: എങ്ങോട്ടാണ് രക്ഷപ്പെടാനുള്ള വഴി?».", "malayalamMatn": "അന്നേ ദിവസം മനുഷ്യന്‍ പറയും; എവിടെയാണ് ഓടിരക്ഷപ്പെടാനുള്ളതെന്ന്‌."}, {"ayahNumber": 11, "quranText": "كَلَّا لَا وَزَرَ\n", "jalalayn": "«كَلّا» رَدْع عَنْ طَلَب الفِرار «لا وزَر» لا مَلْجَأ يَتَحَصَّن بِهِ", "malayalam": "«ഒരിക്കലുമില്ല! യാതൊരു അഭയകേന്ദ്രവുമില്ല!».", "malayalamMatn": "ഇല്ല. യാതൊരു രക്ഷയുമില്ല."}, {"ayahNumber": 12, "quranText": "إِلَىٰ رَبِّكَ یَوۡمَىِٕذٍ ٱلۡمُسۡتَقَرُّ\n", "jalalayn": "«إلى رَبّك يَوْمئِذٍ المُسْتَقَرّ» مُسْتَقَرّ الخَلائِق فَيُحاسَبُونَ ويُجازُونَ", "malayalam": "«അന്നേ ദിവസം നിന്റെ രക്ഷിതാവിങ്കലേക്ക് മാത്രമാകുന്നു സ്ഥിരവാസസ്ഥലം».", "malayalamMatn": "നിന്‍റെ രക്ഷിതാവിങ്കലേക്കാണ് അന്നേ ദിവസം ചെന്നുകൂടല്‍."}, {"ayahNumber": 13, "quranText": "یُنَبَّؤُا۟ ٱلۡإِنسَـٰنُ یَوۡمَىِٕذِۭ بِمَا قَدَّمَ وَأَخَّرَ\n", "jalalayn": "«يُنَبَّأ الإنْسان يَوْمئِذٍ بِما قَدَّمَ وأَخَّرَ» بِأَوَّلِ عَمَله وآخِره", "malayalam": "«താൻ മുൻകൂട്ടി ചെയ്തതിനെക്കുറിച്ചും പിന്നോട്ട് മാറ്റിവെച്ചതിനെക്കുറിച്ചും അന്നേ ദിവസം മനുഷ്യന് വിവരമറിയിക്കപ്പെടും».", "malayalamMatn": "അന്നേ ദിവസം മനുഷ്യന്‍ മുന്‍കൂട്ടി ചെയ്തതിനെപ്പറ്റിയും നീട്ടിവെച്ചതിനെപ്പറ്റിയും അവന്ന് വിവരമറിയിക്കപ്പെടും."}, {"ayahNumber": 14, "quranText": "بَلِ ٱلۡإِنسَـٰنُ عَلَىٰ نَفۡسِهِۦ بَصِیرَةࣱ\n", "jalalayn": "«بَلْ الإنْسان عَلى نَفْسه بَصِيرَة» شاهِد تَنْطِق جَوارِحه بِعَمَلِهِ والهاء لِلْمُبالَغَةِ فَلا بُدّ مِن جَزائِهِ", "malayalam": "«തന്റെ സ്വന്തം ശരീരത്തിനെതിരിൽ മനുഷ്യൻ തന്നെ വ്യക്തമായ സാക്ഷിയാകുന്നു».", "malayalamMatn": "തന്നെയുമല്ല. മനുഷ്യന്‍ തനിക്കെതിരില്‍ തന്നെ ഒരു തെളിവായിരിക്കും."}, {"ayahNumber": 15, "quranText": "وَلَوۡ أَلۡقَىٰ مَعَاذِیرَهُۥ\n", "jalalayn": "«ولَوْ ألْقى مَعاذِيره» جَمْع مَعْذِرَة عَلى غَيْر قِياس أيْ لَوْ جاءَ بِكُلِّ مَعْذِرَة ما قُبِلَتْ مِنهُ", "malayalam": "«അവൻ എന്തൊക്കെ ഒഴികഴിവുകൾ സമർപ്പിച്ചാലും ശരി!».", "malayalamMatn": "അവന്‍ ഒഴികഴിവുകള്‍ സമര്‍പ്പിച്ചാലും ശരി."}, {"ayahNumber": 16, "quranText": "لَا تُحَرِّكۡ بِهِۦ لِسَانَكَ لِتَعۡجَلَ بِهِۦۤ\n", "jalalayn": "قالَ تَعالى لِنَبِيِّهِ «لا تُحَرِّك بِهِ» بِالقُرْآنِ قَبْل فَراغ جِبْرِيل مِنهُ «لِسانك لِتَعْجَل بِهِ» خَوْف أنْ يَنْفَلِت مِنك", "malayalam": "«വഹ്‌യ് ധൃതിപ്പെട്ട് മനഃപാഠമാക്കാനായി നിന്റെ നാവ് അതുകൊണ്ട് ചലിപ്പിക്കരുത്! (ജിബ്‌രീൽ ഓതിത്തരുമ്പോൾ തിടുക്കം കാണിക്കേണ്ടതില്ല)».", "malayalamMatn": "നീ അത് (ഖുര്‍ആന്‍) ധൃതിപ്പെട്ട് ഹൃദിസ്ഥമാക്കാന്‍ വേണ്ടി അതും കൊണ്ട് നിന്‍റെ നാവ് ചലിപ്പിക്കേണ്ട."}, {"ayahNumber": 17, "quranText": "إِنَّ عَلَیۡنَا جَمۡعَهُۥ وَقُرۡءَانَهُۥ\n", "jalalayn": "«إنّ عَلَيْنا جَمْعه» فِي صَدْرك «وقُرْآنه» قِراءَتك إيّاهُ أيْ جَرَيانه عَلى لِسانك", "malayalam": "«തീർച്ചയായും അത് നിന്റെ ഹൃദയത്തിൽ ഒരുമിച്ചുകൂട്ടുന്നതും നിനക്കത് ഓതിത്തരുന്നതും നമ്മുടെ ബാധ്യതയാകുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും അതിന്‍റെ (ഖുര്‍ആന്‍റെ) സമാഹരണവും അത് ഓതിത്തരലും നമ്മുടെ ബാധ്യതയാകുന്നു."}, {"ayahNumber": 18, "quranText": "فَإِذَا قَرَأۡنَـٰهُ فَٱتَّبِعۡ قُرۡءَانَهُۥ\n", "jalalayn": "«فَإذا قَرَأْناهُ» عَلَيْك بِقِراءَةِ جِبْرِيل «فاتَّبِعْ قُرْآنه» اسْتَمِعْ قِراءَته فَكانَ ﷺ يَسْتَمِع ثُمَّ يَقْرَؤُهُ", "malayalam": "«അങ്ങനെ നാം അത് ഓതിത്തന്നാൽ അതിന്റെ പാരായണത്തെ നീ പിന്തുടരുക».", "malayalamMatn": "അങ്ങനെ നാം അത് ഓതിത്തന്നാല്‍ ആ ഓത്ത് നീ പിന്തുടരുക."}, {"ayahNumber": 19, "quranText": "ثُمَّ إِنَّ عَلَیۡنَا بَیَانَهُۥ\n", "jalalayn": "«ثُمَّ إنّ عَلَيْنا بَيانه» بِالتَّفْهِيمِ لَك والمُناسَبَة بَيْن هَذِهِ الآيَة وما قَبْلها أنَّ تِلْكَ تَضَمَّنَتْ الإعْراض عَنْ آيات اللَّه وهَذِهِ تَضَمَّنَتْ المُبادَرَة إلَيْها بِحِفْظِها", "malayalam": "«പിന്നീട് അത് വിശദീകരിച്ചു തരുന്നതും നമ്മുടെ ബാധ്യതയാകുന്നു».", "malayalamMatn": "പിന്നീട് അത് വിവരിച്ചുതരലും നമ്മുടെ ബാധ്യതയാകുന്നു."}, {"ayahNumber": 20, "quranText": "كَلَّا بَلۡ تُحِبُّونَ ٱلۡعَاجِلَةَ\n", "jalalayn": "«كَلّا» اسْتِفْتاح بِمَعْنى ألا «بَلْ تُحِبُّونَ العاجِلَة» الدُّنْيا بِالياءِ والتّاء فِي الفِعْلَيْنِ", "malayalam": "«തീർച്ചയായും അങ്ങനെയല്ല, വേഗത്തിൽ നശിക്കുന്ന ഇഹലോകത്തെ നിങ്ങൾ സ്നേഹിക്കുന്നു».", "malayalamMatn": "അല്ല, നിങ്ങള്‍ ക്ഷണികമായ ഈ ജീവിതത്തെ ഇഷ്ടപ്പെടുന്നു."}, {"ayahNumber": 21, "quranText": "وَتَذَرُونَ ٱلۡـَٔاخِرَةَ\n", "jalalayn": "«وتَذَرُونَ الآخِرَة» فَلا يَعْمَلُونَ لَها", "malayalam": "«പരലോകത്തെ നിങ്ങൾ ഉപേക്ഷിക്കുകയും ചെയ്യുന്നു».", "malayalamMatn": "പരലോകത്തെ നിങ്ങള്‍ വിട്ടേക്കുകയും ചെയ്യുന്നു."}, {"ayahNumber": 22, "quranText": "وُجُوهࣱ یَوۡمَىِٕذࣲ نَّاضِرَةٌ\n", "jalalayn": "«وُجُوه يَوْمئِذٍ» أيْ فِي يَوْم القِيامَة «ناضِرَة» حَسَنَة مُضِيئَة", "malayalam": "«അന്നേ ദിവസം ചില മുഖങ്ങൾ പ്രസന്നമായിരിക്കും».", "malayalamMatn": "ചില മുഖങ്ങള്‍ അന്ന് പ്രസന്നതയുള്ളതും"}, {"ayahNumber": 23, "quranText": "إِلَىٰ رَبِّهَا نَاظِرَةࣱ\n", "jalalayn": "«إلى رَبّها ناظِرَة» أيْ يَرَوْنَ اللَّه سُبْحانه وتَعالى فِي الآخِرَة", "malayalam": "«തങ്ങളുടെ രക്ഷിതാവിങ്കലേക്ക് നോക്കിക്കൊണ്ടിരിക്കുന്നവയായിരിക്കും!».", "malayalamMatn": "അവയുടെ രക്ഷിതാവിന്‍റെ നേര്‍ക്ക് ദൃഷ്ടി തിരിച്ചവയുമായിരിക്കും."}, {"ayahNumber": 24, "quranText": "وَوُجُوهࣱ یَوۡمَىِٕذِۭ بَاسِرَةࣱ\n", "jalalayn": "«ووُجُوه يَوْمئِذٍ باسِرَة» كالِحَة شَدِيدَة العُبُوس", "malayalam": "«മറ്റുചില മുഖങ്ങൾ അന്നേ ദിവസം കറുത്തുവികൃതമായിരിക്കും».", "malayalamMatn": "ചില മുഖങ്ങള്‍ അന്നു കരുവാളിച്ചതായിരിക്കും."}, {"ayahNumber": 25, "quranText": "تَظُنُّ أَن یُفۡعَلَ بِهَا فَاقِرَةࣱ\n", "jalalayn": "«تَظُنّ» تُوقِن «أنْ يُفْعَل بِها فاقِرَة» داهِيَة عَظِيمَة تَكْسِر فَقار الظَّهْر", "malayalam": "«നടുവൊടിക്കുന്ന വൻവിപത്ത് തങ്ങളുടെ മേൽ വന്നെത്തുമെന്ന് അവർ വിചാരിക്കും».", "malayalamMatn": "ഏതോ അത്യാപത്ത് അവയെ പിടികൂടാന്‍ പോകുകയാണ് എന്ന് അവര്‍ വിചാരിക്കും."}, {"ayahNumber": 26, "quranText": "كَلَّاۤ إِذَا بَلَغَتِ ٱلتَّرَاقِیَ\n", "jalalayn": "«كَلّا» بِمَعْنى ألا «إذا بَلَغَتْ» النَّفْس «التَّراقِيَ» عِظام الحَلْق", "malayalam": "«ഒരിക്കലുമില്ല, പ്രാണൻ തൊണ്ടക്കുഴിയിൽ എത്തുമ്പോൾ!».", "malayalamMatn": "അല്ല, (പ്രാണന്‍) തൊണ്ടക്കുഴിയില്‍ എത്തുകയും,"}, {"ayahNumber": 27, "quranText": "وَقِیلَ مَنۡۜ رَاقࣲ\n", "jalalayn": "«وقِيلَ» قالَ مَن حَوْله «مَن راقٍ» أيْ يَرْقِيه لِيُشْفى", "malayalam": "«മന്ത്രിച്ചു സുഖപ്പെടുത്താൻ ആരുണ്ടെന്ന് പറയപ്പെടുകയും!».", "malayalamMatn": "മന്ത്രിക്കാനാരുണ്ട് എന്ന് പറയപ്പെടുകയും,"}, {"ayahNumber": 28, "quranText": "وَظَنَّ أَنَّهُ ٱلۡفِرَاقُ\n", "jalalayn": "«وظَنَّ» أيْقَنَ مَن بَلَغَتْ نَفْسه ذَلِكَ «أنَّهُ الفِراق» أيْ فِراق الدُّنْيا", "malayalam": "«അത് തന്റെ വേർപാടാണെന്ന് അവൻ ഉറപ്പിക്കുകയും!».", "malayalamMatn": "അത് (തന്‍റെ) വേര്‍പാടാണെന്ന് അവന്‍ വിചാരിക്കുകയും,"}, {"ayahNumber": 29, "quranText": "وَٱلۡتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ\n", "jalalayn": "«والتَفَّتْ السّاق بِالسّاقِ» أيْ إحْدى ساقَيْهِ بِالأُخْرى عِنْد المَوْت أوْ التَفَّتْ شِدَّة فِراق الدُّنْيا بِشِدَّةِ إقْبال الآخِرَة", "malayalam": "«കണങ്കാലുകൾ പരസ്പരം കൂട്ടിമുട്ടുകയും ചെയ്താൽ!».", "malayalamMatn": "കണങ്കാലും കണങ്കാലുമായി കൂടിപ്പിണയുകയും ചെയ്താല്‍,"}, {"ayahNumber": 30, "quranText": "إِلَىٰ رَبِّكَ یَوۡمَىِٕذٍ ٱلۡمَسَاقُ\n", "jalalayn": "«إلى رَبّك يَوْمئِذٍ المَساق» أيْ السَّوْق وهَذا يَدُلّ عَلى العامِل فِي إذا والمَعْنى إذا بَلَغَتْ النَّفْس الحُلْقُوم تُساق إلى حُكْم رَبّها", "malayalam": "«അന്നേ ദിവസം നിന്റെ രക്ഷിതാവിങ്കലേക്കാകുന്നു തെളിച്ചുകൊണ്ടുപോകുന്നത്».", "malayalamMatn": "അന്ന് നിന്‍റെ രക്ഷിതാവിങ്കലേക്കായിരിക്കും തെളിച്ചു കൊണ്ടു പോകുന്നത്‌."}, {"ayahNumber": 31, "quranText": "فَلَا صَدَّقَ وَلَا صَلَّىٰ\n", "jalalayn": "«فَلا صَدَّقَ» الإنْسان «ولا صَلّى» أيْ لَمْ يُصَدِّق ولَمْ يُصَلِّ", "malayalam": "«എന്നാൽ അവൻ വിശ്വസിച്ചതുമില്ല, അവൻ നമസ്കരിച്ചതുമില്ല!».", "malayalamMatn": "എന്നാല്‍ അവന്‍ വിശ്വസിച്ചില്ല. അവന്‍ നമസ്കരിച്ചതുമില്ല."}, {"ayahNumber": 32, "quranText": "وَلَـٰكِن كَذَّبَ وَتَوَلَّىٰ\n", "jalalayn": "«ولَكِنْ كَذَّبَ» بِالقُرْآنِ «وتَوَلّى» عَنْ الإيمان", "malayalam": "«മറിച്ച് അവൻ നിഷേധിച്ചു തള്ളുകയും പിന്തിരിഞ്ഞു കളയുകയുമാണ് ചെയ്തത്!».", "malayalamMatn": "പക്ഷെ അവന്‍ നിഷേധിക്കുകയും പിന്തിരിയുകയും ചെയ്തു."}, {"ayahNumber": 33, "quranText": "ثُمَّ ذَهَبَ إِلَىٰۤ أَهۡلِهِۦ یَتَمَطَّىٰۤ\n", "jalalayn": "«ثُمَّ ذَهَبَ إلى أهْله يَتَمَطّى» يَتَبَخْتَر فِي مِشْيَته إعْجابًا", "malayalam": "«പിന്നീട് അവൻ അഹങ്കാരം നടിച്ചുകൊണ്ട് തന്റെ കുടുംബത്തിലേക്ക് പോയി».", "malayalamMatn": "എന്നിട്ടു ദുരഭിമാനം നടിച്ചു കൊണ്ട് അവന്‍ അവന്‍റെ സ്വന്തക്കാരുടെ അടുത്തേക്ക് പോയി"}, {"ayahNumber": 34, "quranText": "أَوۡلَىٰ لَكَ فَأَوۡلَىٰ\n", "jalalayn": "«أوْلى لَك» فِيهِ التِفات عَنْ الغِيبَة والكَلِمَة اسْم فِعْل واللّام لِلتَّبْيِينِ أيْ ولِيّك ما تَكْرَه «فَأَوْلى» أيْ فَهُوَ أوْلى بِك مِن غَيْرك", "malayalam": "«നിനക്ക് നാശം! വീണ്ടും നിനക്ക് നാശം!».", "malayalamMatn": "(ശിക്ഷ) നിനക്കേറ്റവും അര്‍ഹമായതു തന്നെ. നിനക്കേറ്റവും അര്‍ഹമായതു തന്നെ."}, {"ayahNumber": 35, "quranText": "ثُمَّ أَوۡلَىٰ لَكَ فَأَوۡلَىٰۤ\n", "jalalayn": "«ثُمَّ أوْلى لَك فَأَوْلى» تَأْكِيد", "malayalam": "«പിന്നെയും നിനക്ക് നാശം! വീണ്ടും നിനക്ക് നാശം!».", "malayalamMatn": "വീണ്ടും നിനക്കേറ്റവും അര്‍ഹമായത് തന്നെ. നിനക്കേറ്റവും അര്‍ഹമായത് തന്നെ"}, {"ayahNumber": 36, "quranText": "أَیَحۡسَبُ ٱلۡإِنسَـٰنُ أَن یُتۡرَكَ سُدًى\n", "jalalayn": "«أيَحْسَبُ» يَظُنّ «الإنْسان أنْ يُتْرَك سُدًى» هَمْلًا لا يُكَلَّف بِالشَّرائِعِ لا يَحْسَب ذَلِكَ", "malayalam": "«മനുഷ്യൻ വിചാരിക്കുകയാണോ തന്നെ വെറുതെ വിട്ടേക്കുമെന്ന്? (കൽപനകളോ വിചാരണയോ ഇല്ലാതെ വിടുമെന്ന്?)».", "malayalamMatn": "മനുഷ്യന്‍ വിചാരിക്കുന്നുവോ; അവന്‍ വെറുതെ വിട്ടേക്കപ്പെടുമെന്ന്‌!"}, {"ayahNumber": 37, "quranText": "أَلَمۡ یَكُ نُطۡفَةࣰ مِّن مَّنِیࣲّ یُمۡنَىٰ\n", "jalalayn": "«ألَمْ يَكُ» أيْ كانَ «نُطْفَة مِن مَنِيّ يُمْنى» بِالياءِ والتّاء تُصَبّ فِي الرَّحِم", "malayalam": "«സ്രവിക്കപ്പെടുന്ന ഒരു ശുക്ലത്തുള്ളിയായിരുന്നില്ലയോ അവൻ?».", "malayalamMatn": "അവന്‍ സ്രവിക്കപ്പെടുന്ന ശുക്ലത്തില്‍ നിന്നുള്ള ഒരു കണമായിരുന്നില്ലേ?"}, {"ayahNumber": 38, "quranText": "ثُمَّ كَانَ عَلَقَةࣰ فَخَلَقَ فَسَوَّىٰ\n", "jalalayn": "«ثُمَّ كانَ» المَنِيّ «عَلَقَة فَخَلَقَ» اللَّه مِنها الإنْسان «فَسَوّى» أيْ عَدَّلَ أعْضاءَهُ", "malayalam": "«പിന്നീട് അവൻ ഒരു ഭ്രൂണമായിത്തീർന്നു; അങ്ങനെ അല്ലാഹു അവനെ സൃഷ്ടിക്കുകയും രൂപപ്പെടുത്തുകയും ചെയ്തു».", "malayalamMatn": "പിന്നെ അവന്‍ ഒരു ഭ്രൂണമായി. എന്നിട്ട് അല്ലാഹു (അവനെ) സൃഷ്ടിച്ചു സംവിധാനിച്ചു."}, {"ayahNumber": 39, "quranText": "فَجَعَلَ مِنۡهُ ٱلزَّوۡجَیۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰۤ\n", "jalalayn": "«فَجَعَلَ مِنهُ» مِن المَنِيّ الَّذِي صارَ عَلَقَة قِطْعَة دَم ثُمَّ مُضْغَة أيْ قِطْعَة لَحْم «الزَّوْجَيْنِ» النَّوْعَيْنِ «الذَّكَر والأُنْثى» يَجْتَمِعانِ تارَة ويَنْفَرِد كُلّ مِنهُما عَنْ الآخَر تارَة", "malayalam": "«എന്നിട്ട് അതിൽ നിന്ന് ആണും പെണ്ണുമാകുന്ന ഇണകളെ അവൻ ഉണ്ടാക്കി».", "malayalamMatn": "അങ്ങനെ അതില്‍ നിന്ന് ആണും പെണ്ണുമാകുന്ന രണ്ടു ഇണകളെ അവന്‍ ഉണ്ടാക്കി."}, {"ayahNumber": 40, "quranText": "أَلَیۡسَ ذَ ٰ⁠لِكَ بِقَـٰدِرٍ عَلَىٰۤ أَن یُحۡـِۧیَ ٱلۡمَوۡتَىٰ\n", "jalalayn": "«ألَيْسَ ذَلِكَ» الفَعّال لِهَذِهِ الأَشْياء «بِقادِرٍ عَلى أنْ يُحْيِيَ المَوْتى» قالَ ﷺ بَلى", "malayalam": "«അങ്ങനെയുള്ളവൻ മരിച്ചവരെ ജീവിപ്പിക്കാൻ കഴിവുള്ളവനല്ലയോ? (അതെ, അവൻ സർവ്വശക്തനാകുന്നു!)».", "malayalamMatn": "അങ്ങനെയുള്ളവന്‍ മരിച്ചവരെ ജീവിപ്പിക്കാന്‍ കഴിവുള്ളവനല്ലെ?"}], "topPoints": ["മനുഷ്യന്റെ ഉയിർത്തെഴുന്നേൽപ് (خلاصة السورة)", "മരണവേളയിലെ മനുഷ്യന്റെ അവസ്ഥ"], "topQuestions": [{"q": "മനുഷ്യന്റെ വിരൽത്തുമ്പുകൾ പോലും രൂപപ്പെടുത്താൻ അല്ലാഹുവിന് കഴിയുമോ?", "a": "അതെ, അസ്ഥികൾ ഒരുമിച്ചുകൂട്ടി വിരൽത്തുമ്പുകൾ വരെ കൃത്യമാക്കാൻ അവൻ ശക്തനാണ്."}], "asbabAlNuzul": []}, {"surahNumber": 76, "surahNameArabic": "سُورَةُ الإِنسَانِ", "surahNameMalayalam": "സൂറത്തുൽ ഇൻസാൻ (മനുഷ്യൻ)", "ayahs": [{"ayahNumber": 1, "quranText": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ هَلۡ أَتَىٰ عَلَى ٱلۡإِنسَـٰنِ حِینࣱ مِّنَ ٱلدَّهۡرِ لَمۡ یَكُن شَیۡـࣰٔا مَّذۡكُورًا\n", "jalalayn": "«هل» قد «أتى على الإنسان» آدم «حين من الدهر» أربعون سنة «لم يكن» فيه «شيئا مذكورا» كان فيه مصورا من طين لا يذكر أو المراد بالإنسان الجنس وبالحين مدة الحمل", "malayalam": "«മനുഷ്യന് സ്മരണീയമായ ഒരു വസ്തുവേ അല്ലാതിരുന്ന ഒരു നീണ്ട കാലഘട്ടം അവന്റെ മേൽ കഴിഞ്ഞുപോയിട്ടില്ലയോ?».", "malayalamMatn": "മനുഷ്യന്‍ പ്രസ്താവ്യമായ ഒരു വസ്തുവേ ആയിരുന്നില്ലാത്ത ഒരു കാലഘട്ടം അവന്‍റെ മേല്‍ കഴിഞ്ഞുപോയിട്ടുണ്ടോ?"}, {"ayahNumber": 2, "quranText": "إِنَّا خَلَقۡنَا ٱلۡإِنسَـٰنَ مِن نُّطۡفَةٍ أَمۡشَاجࣲ نَّبۡتَلِیهِ فَجَعَلۡنَـٰهُ سَمِیعَۢا بَصِیرًا\n", "jalalayn": "«إنا خلقنا الإنسان» الجنس «من نطفة أمشاج» أخلاط، أي من ماء الرجل وماء المرأة المختلطين الممتزجين «نبتليه» نختبره بالتكليف والجملة مستأنفة أو حال مقدرة، أي مريدين ابتلاءه حين تأهله «فجعلناه» بسبب ذلك", "malayalam": "«കൂടിക്കലർന്ന ഒരു ബീജത്തിൽ നിന്നാണ് (സ്ത്രീ-പുരുഷ സംഗമത്തിലൂടെ) നാം മനുഷ്യനെ സൃഷ്ടിച്ചത്; നാം അവനെ പരീക്ഷിക്കുവാനായി; അങ്ങനെ നാം അവനെ കേൾവിയുള്ളവനും കാഴ്ചയുള്ളവനുമാക്കി മാറ്റി».", "malayalamMatn": "കൂടിച്ചേര്‍ന്നുണ്ടായ ഒരു ബീജത്തില്‍ നിന്ന് തീര്‍ച്ചയായും നാം മനുഷ്യനെ സൃഷ്ടിച്ചിരിക്കുന്നു. നാം അവനെ പരീക്ഷിക്കുവാനായിട്ട്‌. അങ്ങനെ അവനെ നാം കേള്‍വിയുള്ളവനും കാഴ്ചയുള്ളവനുമാക്കിയിരിക്കുന്നു."}, {"ayahNumber": 3, "quranText": "إِنَّا هَدَیۡنَـٰهُ ٱلسَّبِیلَ إِمَّا شَاكِرࣰا وَإِمَّا كَفُورًا\n", "jalalayn": "«إنا هديناه السبيل» بينا له طريق الهدى ببعث الرسل «إما شاكرا» أي مؤمنا «وإما كفورا» حالان من المفعول، أي بينا له في حال شكره أو كفره المقدرة وإما لتفصيل الأحوال", "malayalam": "«തീർച്ചയായും നാം അവന് സന്മാർഗ്ഗം കാണിച്ചു കൊടുത്തു; ഒന്നുകിൽ അവൻ നന്ദിയുള്ളവനാകാം, അല്ലെങ്കിൽ നന്ദികെട്ടവനാകാം».", "malayalamMatn": "തീര്‍ച്ചയായും നാം അവന്ന് വഴി കാണിച്ചുകൊടുത്തിരിക്കുന്നു. എന്നിട്ട് ഒന്നുകില്‍ അവന്‍ നന്ദിയുള്ളവനാകുന്നു. അല്ലെങ്കില്‍ നന്ദികെട്ടവനാകുന്നു."}, {"ayahNumber": 4, "quranText": "إِنَّاۤ أَعۡتَدۡنَا لِلۡكَـٰفِرِینَ سَلَـٰسِلَا۟ وَأَغۡلَـٰلࣰا وَسَعِیرًا\n", "jalalayn": "«إنا أعتدنا» هيأنا «للكافرين سلاسلا» يسحبون بها في النار «وأغلالا» في أعناقهم تشد فيها السلاسل «وسعيرا» نارا مسعرة، أي مهيجة يعذبون بها", "malayalam": "«സത്യനിഷേധികൾക്കായി ചങ്ങലകളും വിലങ്ങുകളും ജ്വലിക്കുന്ന നരകാഗ്നിയും നാം ഒരുക്കിവെച്ചിരിക്കുന്നു».", "malayalamMatn": "തീര്‍ച്ചയായും സത്യനിഷേധികള്‍ക്ക് നാം ചങ്ങലകളും വിലങ്ങുകളും കത്തിജ്വലിക്കുന്ന നരകാഗ്നിയും ഒരുക്കി വെച്ചിരിക്കുന്നു."}, {"ayahNumber": 5, "quranText": "إِنَّ ٱلۡأَبۡرَارَ یَشۡرَبُونَ مِن كَأۡسࣲ كَانَ مِزَاجُهَا كَافُورًا\n", "jalalayn": "«إن الأبرار» جمع بر أو بار وهم المطيعون «يشربون من كأس» هو إناء شرب الخمر وهي فيه والمراد من خمر تسمية للحال باسم المحل ومن للتبعيض «كان مزاجها» ما تمزج به", "malayalam": "«തീർച്ചയായും സജ്ജനങ്ങൾ കർപ്പൂരം കലർത്തപ്പെട്ട ഒരു പാനപാത്രത്തിൽ നിന്ന് കുടിക്കുന്നതാണ്».", "malayalamMatn": "തീര്‍ച്ചയായും പുണ്യവാന്‍മാര്‍ (സ്വര്‍ഗത്തില്‍) ഒരു പാനപാത്രത്തില്‍ നിന്ന് കുടിക്കുന്നതാണ്‌. അതിന്‍റെ ചേരുവ കര്‍പ്പൂരമായിരിക്കും."}, {"ayahNumber": 6, "quranText": "عَیۡنࣰا یَشۡرَبُ بِهَا عِبَادُ ٱللَّهِ یُفَجِّرُونَهَا تَفۡجِیرࣰا\n", "jalalayn": "«عينا» بدل من كافورا فيها رائحته «يشرب بها» منها «عباد الله» أولياؤه «يفجرونها تفجيرا» يقودونها حيث شاءوا من منازلهم", "malayalam": "«അല്ലാഹുവിന്റെ ദാസന്മാർ കുടിക്കുന്ന ഒരു ഉറവയാണത്; അവർക്കിഷ്ടമുള്ളിടത്തേക്ക് അവർ അത് ഒഴുക്കിക്കൊണ്ടിരിക്കും».", "malayalamMatn": "അല്ലാഹുവിന്‍റെ ദാസന്‍മാര്‍ കുടിക്കുന്ന ഒരു ഉറവു വെള്ളമത്രെ അത്‌. അവരത് പൊട്ടിച്ചൊഴുക്കിക്കൊണ്ടിരിക്കും."}, {"ayahNumber": 7, "quranText": "یُوفُونَ بِٱلنَّذۡرِ وَیَخَافُونَ یَوۡمࣰا كَانَ شَرُّهُۥ مُسۡتَطِیرࣰا\n", "jalalayn": "«يوفون بالنذر» في طاعة الله «ويخافون يوما كان شره مستطيرا» منتشرا", "malayalam": "«നേർച്ചകൾ നിറവേറ്റുന്നവരും, വിപത്ത് പടർന്നുപിടിക്കുന്ന ആ ഭയാനകമായ ദിവസത്തെ ഭയപ്പെടുന്നവരുമാകുന്നു അവർ».", "malayalamMatn": "നേര്‍ച്ച അവര്‍ നിറവേറ്റുകയും ആപത്തു പടര്‍ന്ന് പിടിക്കുന്ന ഒരു ദിവസത്തെ അവര്‍ ഭയപ്പെടുകയും ചെയ്യും."}, {"ayahNumber": 8, "quranText": "وَیُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِینࣰا وَیَتِیمࣰا وَأَسِیرًا\n", "jalalayn": "«ويطعمون الطعام على حبه» أي الطعام وشهوتهم له «مسكينا» فقيرا «ويتيما» لا أب له «وأسيرا» يعني المحبوس بحق", "malayalam": "«ഭക്ഷണത്തോട് കൊതിയുള്ളതോടൊപ്പം തന്നെ അഗതിക്കും അനാഥയ്ക്കും തടവുകാരനും അവർ ഭക്ഷണം നൽകുകയും ചെയ്യും».", "malayalamMatn": "ആഹാരത്തോട് പ്രിയമുള്ളതോടൊപ്പം തന്നെ അഗതിക്കും അനാഥയ്ക്കും തടവുകാരന്നും അവരത് നല്‍കുകയും ചെയ്യും."}, {"ayahNumber": 9, "quranText": "إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِیدُ مِنكُمۡ جَزَاۤءࣰ وَلَا شُكُورًا\n", "jalalayn": "«إنما نطعمكم لوجه الله» لطلب ثوابه «لا نريد منكم جزاء ولا شكورا» شكرا فيه علة الإطعام وهل تكلموا بذلك أو علمه الله منهم فأثنى عليهم به، قولان", "malayalam": "«അവർ പറയും: അല്ലാഹുവിന്റെ പ്രീതി കാംക്ഷിച്ച് മാത്രമാണ് ഞങ്ങൾ നിങ്ങൾക്ക് ഭക്ഷണം നൽകുന്നത്; നിങ്ങളുടെ പക്കൽ നിന്ന് യാതൊരു പ്രതിഫലമോ നന്ദിയോ ഞങ്ങൾ ആഗ്രഹിക്കുന്നില്ല!».", "malayalamMatn": "(അവര്‍ പറയും:) അല്ലാഹുവിന്‍റെ പ്രീതിക്കു വേണ്ടി മാത്രമാണ് ഞങ്ങള്‍ നിങ്ങള്‍ക്കു ആഹാരം നല്‍കുന്നത്‌. നിങ്ങളുടെ പക്കല്‍ നിന്നു യാതൊരു പ്രതിഫലവും നന്ദിയും ഞങ്ങള്‍ ആഗ്രഹിക്കുന്നില്ല."}, {"ayahNumber": 10, "quranText": "إِنَّا نَخَافُ مِن رَّبِّنَا یَوۡمًا عَبُوسࣰا قَمۡطَرِیرࣰا\n", "jalalayn": "«إنا نخاف من ربنا يوما عبوسا» تكلح الوجوه فيه أي كريه المنظر لشدته «قمطريرا» شديدا في ذلك", "malayalam": "«മുഖം ചുളിപ്പിക്കുന്ന ഭയാനകമായ ഒരു ദിവസത്തെ ഞങ്ങളുടെ രക്ഷിതാവിങ്കൽ നിന്ന് ഞങ്ങൾ ഭയപ്പെടുന്നു!».", "malayalamMatn": "മുഖം ചുളിച്ചു പോകുന്നതും, ദുസ്സഹവുമായ ഒരു ദിവസത്തെ ഞങ്ങളുടെ രക്ഷിതാവിങ്കല്‍ നിന്ന് തീര്‍ച്ചയായും ഞങ്ങള്‍ ഭയപ്പെടുന്നു."}, {"ayahNumber": 11, "quranText": "فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَ ٰ⁠لِكَ ٱلۡیَوۡمِ وَلَقَّىٰهُمۡ نَضۡرَةࣰ وَسُرُورࣰا\n", "jalalayn": "«فوقاهم الله شر ذلك اليوم ولقاهم» أعطاهم «نضرة» حسنا وإضاءة في وجوههم", "malayalam": "«അതിനാൽ ആ ദിവസത്തിന്റെ തിന്മയിൽ നിന്ന് അല്ലാഹു അവരെ കാത്തുരക്ഷിക്കുകയും സന്തോഷവും പ്രസന്നതയും അവർക്ക് നൽകുകയും ചെയ്തു».", "malayalamMatn": "അതിനാല്‍ ആ ദിവസത്തിന്‍റെ തിന്‍മയില്‍ നിന്ന് അല്ലാഹു അവരെ കാത്തുരക്ഷിക്കുകയും, പ്രസന്നതയും സന്തോഷവും അവര്‍ക്കു അവന്‍ നല്‍കുകയും ചെയ്യുന്നതാണ്‌."}, {"ayahNumber": 12, "quranText": "وَجَزَىٰهُم بِمَا صَبَرُوا۟ جَنَّةࣰ وَحَرِیرࣰا\n", "jalalayn": "«وجزاهم بما صبروا» بصبرهم عن المعصية «جنة» أدخلوها «وحريرا» البسوه", "malayalam": "«അവർ ക്ഷമിച്ചതിന് പ്രതിഫലമായി സ്വർഗ്ഗവും പട്ടുനൂൽ വസ്ത്രങ്ങളും അവൻ അവർക്ക് നൽകി».", "malayalamMatn": "അവര്‍ ക്ഷമിച്ചതിനാല്‍ സ്വര്‍ഗത്തോപ്പും പട്ടു വസ്ത്രങ്ങളും അവര്‍ക്കവന്‍ പ്രതിഫലമായി നല്‍കുന്നതാണ്‌."}, {"ayahNumber": 13, "quranText": "مُّتَّكِـِٔینَ فِیهَا عَلَى ٱلۡأَرَاۤىِٕكِۖ لَا یَرَوۡنَ فِیهَا شَمۡسࣰا وَلَا زَمۡهَرِیرࣰا\n", "jalalayn": "«متكئين» حال من مرفوع أدخلوها المقدر «فيها على الأرائك» السرر في الحجال «لا يرون» لا يجدون حال ثانية «فيها شمسا ولا زمهريرا» لا حرا ولا بردا وقيل الزمهرير القمر فهي مضيئة من غير شمس ولا قمر", "malayalam": "«അവിടെ അലങ്കരിച്ച കട്ടിലുകളിൽ ചാരിയിരിക്കുന്നവരായിരിക്കും അവർ; കഠിനമായ വെയിലോ അതിശൈത്യമോ അവിടെ അവർ കാണുകയില്ല».", "malayalamMatn": "അവരവിടെ സോഫകളില്‍ ചാരിയിരിക്കുന്നവരായിരിക്കും. വെയിലോ കൊടും തണുപ്പോ അവര്‍ അവിടെ കാണുകയില്ല."}, {"ayahNumber": 14, "quranText": "وَدَانِیَةً عَلَیۡهِمۡ ظِلَـٰلُهَا وَذُلِّلَتۡ قُطُوفُهَا تَذۡلِیلࣰا\n", "jalalayn": "«ودانية» قريبة عطف على محل لا يرون، أي غير رائين «عليهم» منهم «ظلالها» شجرها «وذللت قطوفها تذليلا» أدنيت ثمارها فينالها القائم والقاعد والمضطجع", "malayalam": "«അതിലെ തണലുകൾ അവരുടെ മേൽ അടുത്തതായിരിക്കും; അതിലെ പഴങ്ങൾ പറിച്ചെടുക്കാൻ അങ്ങേയറ്റം എളുപ്പമാക്കപ്പെട്ടിരിക്കും».", "malayalamMatn": "ആ സ്വര്‍ഗത്തിലെ തണലുകള്‍ അവരുടെ മേല്‍ അടുത്തു നില്‍ക്കുന്നതായിരിക്കും. അതിലെ പഴങ്ങള്‍ പറിച്ചെടുക്കാന്‍ സൌകര്യമുള്ളതാക്കപ്പെടുകയും ചെയ്തിരിക്കുന്നു."}, {"ayahNumber": 15, "quranText": "وَیُطَافُ عَلَیۡهِم بِـَٔانِیَةࣲ مِّن فِضَّةࣲ وَأَكۡوَابࣲ كَانَتۡ قَوَارِیرَا۠\n", "jalalayn": "«ويطاف عليهم» فيها «بآنية من فضة وأكواب» أقداح بلا عرى", "malayalam": "«വെള്ളിപ്പാത്രങ്ങളും സ്ഫടികച്ചഷകങ്ങളുമായി അവർക്കിടയിൽ പരിചാരകർ ചുറ്റിനടക്കും».", "malayalamMatn": "വെള്ളിയുടെ പാത്രങ്ങളും (മിനുസം കൊണ്ട്‌) സ്ഫടികം പോലെയായിതീര്‍ന്നിട്ടുള്ള കോപ്പകളുമായി അവര്‍ക്കിടയില്‍ (പരിചാരകന്‍മാര്‍) ചുറ്റി നടക്കുന്നതാണ്‌."}, {"ayahNumber": 16, "quranText": "قَوَارِیرَا۟ مِن فِضَّةࣲ قَدَّرُوهَا تَقۡدِیرࣰا\n", "jalalayn": "«قواريرا من فضة» أي أنها من فضة يرى باطنها من ظاهرها كالزجاج «قدروها» أي الطائفون «تقديرا» على قدر ري الشاربين من غير زيادة ولا نقص وذلك ألذ الشراب", "malayalam": "«വെള്ളി കൊണ്ടുള്ള സ്ഫടികപ്പാത്രങ്ങൾ; കൃത്യമായ അളവനുസരിച്ച് അവർ അത് കണക്കാക്കിയിരിക്കുന്നു».", "malayalamMatn": "വെള്ളിക്കോപ്പകള്‍. അവര്‍ അവയ്ക്ക് (പാത്രങ്ങള്‍ക്ക്‌) ഒരു തോതനുസരിച്ച് അളവ് നിര്‍ണയിച്ചിരിക്കും."}, {"ayahNumber": 17, "quranText": "وَیُسۡقَوۡنَ فِیهَا كَأۡسࣰا كَانَ مِزَاجُهَا زَنجَبِیلًا\n", "jalalayn": "«ويسقون فيها كأسا» خمرا «كان مزاجها» ما تمزج به «زنجبيلا» يعنى أن ماءها كالزنجبيل الذى تستلذ به العرب", "malayalam": "«ഇഞ്ചി കലർത്തപ്പെട്ട മറ്റൊരു പാനപാത്രവും അവിടെ അവർക്ക് കുടിക്കാൻ നൽകപ്പെടും».", "malayalamMatn": "ഇഞ്ചിനീരിന്‍റെ ചേരുവയുള്ള ഒരു കോപ്പ അവര്‍ക്ക് അവിടെ കുടിക്കാന്‍ നല്‍കപ്പെടുന്നതാണ്‌."}, {"ayahNumber": 18, "quranText": "عَیۡنࣰا فِیهَا تُسَمَّىٰ سَلۡسَبِیلࣰا\n", "jalalayn": "«عينا» بدل من زنجبيلا «فيها تسمى سلسبيلا» سهل المساغ في الحلق", "malayalam": "«സൽസബീൽ എന്ന് പേരുള്ള സ്വർഗ്ഗത്തിലെ ഒരു ഉറവയാണത്».", "malayalamMatn": "അതായത് അവിടത്തെ (സ്വര്‍ഗത്തിലെ) സല്‍സബീല്‍ എന്നു പേരുള്ള ഒരു ഉറവിലെ വെള്ളം."}, {"ayahNumber": 19, "quranText": "۞ وَیَطُوفُ عَلَیۡهِمۡ وِلۡدَ ٰ⁠نࣱ مُّخَلَّدُونَ إِذَا رَأَیۡتَهُمۡ حَسِبۡتَهُمۡ لُؤۡلُؤࣰا مَّنثُورࣰا\n", "jalalayn": "«ويطوف عليهم ولدان مخلدون» بصفة الولدان لا يشيبون «إذا رأيتهم حسبتهم» لحسنهم وانتشارهم في الخدمة «لؤلؤا منثورا» من سلكه أو من صدفه وهو أحسن منه في غير ذلك", "malayalam": "«ശാശ്വത യൗവനം നൽകപ്പെട്ട ബാലന്മാർ അവരുടെ ചുറ്റും നടക്കും; അവരെ നീ കണ്ടാൽ ചിതറിപ്പരന്ന മുത്തുകളാണെന്ന് നീ വിചാരിച്ചുപോകും!».", "malayalamMatn": "അനശ്വര ജീവിതം നല്‍കപ്പെട്ട ചില കുട്ടികള്‍ അവര്‍ക്കിടയിലൂടെ ചുറ്റി നടന്നുകൊണ്ടുമിരിക്കും. അവരെ നീ കണ്ടാല്‍ വിതറിയ മുത്തുകളാണ് അവരെന്ന് നീ വിചാരിക്കും."}, {"ayahNumber": 20, "quranText": "وَإِذَا رَأَیۡتَ ثَمَّ رَأَیۡتَ نَعِیمࣰا وَمُلۡكࣰا كَبِیرًا\n", "jalalayn": "«وإذا رأيت ثم» أي وجدت الرؤية منك في الجنة «رأيت» جواب إذا «نعيما» لا يوصف «وملكا كبيرا» واسعا لا غاية له", "malayalam": "«അവിടെ നീ നോക്കുകയാണെങ്കിൽ വലിയ അനുഗ്രഹങ്ങളും മഹത്തായ രാജാധിപത്യവും നിനക്ക് കാണാം!».", "malayalamMatn": "അവിടം നീ കണ്ടാല്‍ സുഖാനുഗ്രഹവും വലിയൊരു സാമ്രാജ്യവും നീ കാണുന്നതാണ്‌."}, {"ayahNumber": 21, "quranText": "عَـٰلِیَهُمۡ ثِیَابُ سُندُسٍ خُضۡرࣱ وَإِسۡتَبۡرَقࣱۖ وَحُلُّوۤا۟ أَسَاوِرَ مِن فِضَّةࣲ وَسَقَىٰهُمۡ رَبُّهُمۡ شَرَابࣰا طَهُورًا\n", "jalalayn": "«عاليهم» فوقهم فنصبه على الظرفية وهو خبر لمبتدأ بعده وفي قراءة بسكون الياء مبتدأ وما بعده خبر والضمير المتصل به للمعطوف عليهم «ثياب سندس» حرير «خضر» بالرفع «وإستبرق» بالجر ما غلظ من الديباج فهو البطائن والسندس الظهائر وفي قراءة عكس ما ذكر فيهما وفي أخرى، برفعهما وفي أخرى بجرهما «وحلوا أساور من فضة» وفي موضع من ذهب للإيذان بأنهم يحلون من النوعين معا ومفرقا «وسقاهم ربهم شرابا طهورا» مبالغة في طهارته ونظافته بخلاف خمر الدنيا", "malayalam": "«പച്ച നിറത്തിലുള്ള നേർത്ത പട്ടു വസ്ത്രങ്ങളും കട്ടിപ്പട്ടും അവരുടെ മേലുണ്ടായിരിക്കും; വെള്ളി കൊണ്ടുള്ള വളകൾ അവർക്ക് അണിയിക്കപ്പെടും; അവരുടെ രക്ഷിതാവ് അവർക്ക് പരിശുദ്ധമായ പാനീയം കുടിക്കാൻ നൽകുകയും ചെയ്യും».", "malayalamMatn": "അവരുടെ മേല്‍ പച്ച നിറമുള്ള നേര്‍ത്ത പട്ടുവസ്ത്രങ്ങളും കട്ടിയുള്ള പട്ടു വസ്ത്രവും ഉണ്ടായിരിക്കും. വെള്ളിയുടെ വളകളും അവര്‍ക്ക് അണിയിക്കപ്പെടുന്നതാണ്‌. അവര്‍ക്ക് അവരുടെ രക്ഷിതാവ് തികച്ചും ശുദ്ധമായ പാനീയം കുടിക്കാന്‍ കൊടുക്കുന്നതുമാണ്‌."}, {"ayahNumber": 22, "quranText": "إِنَّ هَـٰذَا كَانَ لَكُمۡ جَزَاۤءࣰ وَكَانَ سَعۡیُكُم مَّشۡكُورًا\n", "jalalayn": "«إن هذا» النعيم", "malayalam": "«തീർച്ചയായും ഇത് നിങ്ങൾക്ക് നൽകപ്പെട്ട പ്രതിഫലമാകുന്നു; നിങ്ങളുടെ പ്രയത്നം നന്ദിപൂർവ്വം സ്വീകരിക്കപ്പെട്ടിരിക്കുന്നു!».", "malayalamMatn": "(അവരോട് പറയപ്പെടും:) തീര്‍ച്ചയായും അത് നിങ്ങള്‍ക്കുള്ള പ്രതിഫലമാകുന്നു. നിങ്ങളുടെ പരിശ്രമം നന്ദിപൂര്‍വ്വം സ്വീകരിക്കപ്പെട്ടിരിക്കയാകുന്നൂ."}, {"ayahNumber": 23, "quranText": "إِنَّا نَحۡنُ نَزَّلۡنَا عَلَیۡكَ ٱلۡقُرۡءَانَ تَنزِیلࣰا\n", "jalalayn": "«إنا نحن» تأكيد لاسم إن أو فصل «نزلنا عليك القرآن تنزيلا» خبر إن أي فصلناه ولم ننزله جملة واحدة", "malayalam": "«തീർച്ചയായും നാം തന്നെയാണ് നിന്റെ മേൽ ഖുർആൻ അല്പാല്പമായി അവതരിപ്പിച്ചു തന്നത്».", "malayalamMatn": "തീര്‍ച്ചയായും നാം നിനക്ക് ഈ ഖുര്‍ആനിനെ അല്‍പാല്‍പമായി അവതരിപ്പിച്ചു തന്നിരിക്കുന്നു."}, {"ayahNumber": 24, "quranText": "فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تُطِعۡ مِنۡهُمۡ ءَاثِمًا أَوۡ كَفُورࣰا\n", "jalalayn": "«فاصبر لحكم ربك» عليك بتبليغ رسالته «ولا تطع منهم» أي الكفار «آثما أو كفورا» أي عتبة بن ربيعة والوليد بن المغيرة قالا للنبي ﷺ ارجع عن هذا الأمر ويجوز أن يراد كل آثم وكافر أي لا تطع أحدهما أيا كان فيما دعاك إليه من إثم أو كفر", "malayalam": "«ആകയാൽ നിന്റെ രക്ഷിതാവിന്റെ കൽപനക്കായി നീ ക്ഷമയോടെ കാത്തിരിക്കുക; അവരിൽ നിന്നുള്ള യാതൊരു പാപിയെയോ കടുത്ത നന്ദികെട്ടവനെയോ നീ അനുസരിക്കരുത്».", "malayalamMatn": "ആകയാല്‍ നിന്‍റെ രക്ഷിതാവിന്‍റെ തീരുമാനത്തിന് നീ ക്ഷമയോടെ കാത്തിരിക്കുക. അവരുടെ കൂട്ടത്തില്‍ നിന്ന് യാതൊരു പാപിയെയും നന്ദികെട്ടവനെയും നീ അനുസരിച്ചു പോകരുത്‌."}, {"ayahNumber": 25, "quranText": "وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةࣰ وَأَصِیلࣰا\n", "jalalayn": "«واذكر اسم ربك» في الصلاة «بكرة وأصيلا» يعني الفجر والظهر والعصر", "malayalam": "«രാവിലെയും വൈകുന്നേരവും നിന്റെ രക്ഷിതാവിന്റെ നാമം നീ സ്മരിക്കുക».", "malayalamMatn": "നിന്‍റെ രക്ഷിതാവിന്‍റെ നാമം കാലത്തും വൈകുന്നേരവും നീ സ്മരിക്കുകയും ചെയ്യുക."}, {"ayahNumber": 26, "quranText": "وَمِنَ ٱلَّیۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَیۡلࣰا طَوِیلًا\n", "jalalayn": "«ومن الليل فاسجد له» يعني المغرب والعشاء «وسبحه ليلا طويلا» صل التطوع فيه كما تقدم من ثلثيه أو نصفه أو ثلثه", "malayalam": "«രാത്രിയിൽ നിന്ന് അല്പസമയം അവന് സാഷ്ടാംഗം ചെയ്യുകയും, രാത്രിയിൽ ദീർഘനേരം അവന്റെ പരിശുദ്ധിയെ പ്രകീർത്തിക്കുകയും ചെയ്യുക».", "malayalamMatn": "രാത്രിയില്‍ നീ അവനെ പ്രണമിക്കുകയും ദീര്‍ഘമായ നിശാവേളയില്‍ അവനെ പ്രകീര്‍ത്തിക്കുകയും ചെയ്യുക."}, {"ayahNumber": 27, "quranText": "إِنَّ هَـٰۤؤُلَاۤءِ یُحِبُّونَ ٱلۡعَاجِلَةَ وَیَذَرُونَ وَرَاۤءَهُمۡ یَوۡمࣰا ثَقِیلࣰا\n", "jalalayn": "«إن هؤلاء يحبون العاجلة» الدنيا «ويذرون وراءهم يوما ثقيلا» شديدا أي يوم القيامة لا يعملون له", "malayalam": "«തീർച്ചയായും ഇവർ വേഗത്തിൽ നശിക്കുന്ന ഇഹലോകത്തെ സ്നേഹിക്കുകയും, ഭാരമേറിയ ആ ദിവസത്തെ (പരലോകത്തെ) തങ്ങളുടെ പിന്നിലേക്ക് തള്ളിക്കളയുകയുമാണ് ചെയ്യുന്നത്».", "malayalamMatn": "തീര്‍ച്ചയായും ഇക്കൂട്ടര്‍ ക്ഷണികമായ ഐഹികജീവിതത്തെ ഇഷ്ടപ്പെടുന്നു. ഭാരമേറിയ ഒരു ദിവസത്തിന്‍റെ കാര്യം അവര്‍ തങ്ങളുടെ പുറകില്‍ വിട്ടുകളയുകയും ചെയ്യുന്നു."}, {"ayahNumber": 28, "quranText": "نَّحۡنُ خَلَقۡنَـٰهُمۡ وَشَدَدۡنَاۤ أَسۡرَهُمۡۖ وَإِذَا شِئۡنَا بَدَّلۡنَاۤ أَمۡثَـٰلَهُمۡ تَبۡدِیلًا\n", "jalalayn": "«نحن خلقناهم وشددنا» قوينا «أسرهم» أعضاءهم ومفاصلهم «وإذا شئنا بدلنا» جعلنا «أمثالهم» في الخلقة بدلا منهم بأن نهلكهم «تبديلا» تأكيد ووقعت إذا موقع إن نحو إن يشأ يذهبكم لأنه تعالى لم يشأ ذلك وإذا لما يقع", "malayalam": "«നാമാണ് അവരെ സൃഷ്ടിക്കുകയും അവരുടെ ശരീരഘടനയെ ശക്തമാക്കുകയും ചെയ്തത്; നാം ഉദ്ദേശിക്കുമ്പോൾ അവർക്ക് പകരം അവരെപ്പോലെയുള്ളവരെ പൂർണ്ണമായും മാറ്റിക്കൊണ്ടുവരാൻ നമുക്ക് സാധിക്കുന്നതാണ്».", "malayalamMatn": "നാമാണ് അവരെ സൃഷ്ടിക്കുകയും അവരുടെ ശരീരഘടന ബലപ്പെടുത്തുകയും ചെയ്തത്‌. നാം ഉദ്ദേശിക്കുന്ന പക്ഷം അവര്‍ക്ക് തുല്യരായിട്ടുള്ളവരെ നാം അവര്‍ക്കു പകരം കൊണ്ടു വരുന്നതുമാണ്‌."}, {"ayahNumber": 29, "quranText": "إِنَّ هَـٰذِهِۦ تَذۡكِرَةࣱۖ فَمَن شَاۤءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِیلࣰا\n", "jalalayn": "«إن هذه» السورة «تذكرة» عظة للخلق «فمن شاء اتخذ إلى ربه سبيلا» طريقا بالطاعة", "malayalam": "«തീർച്ചയായും ഇതൊരു ഉൽബോധനമാകുന്നു; ആകയാൽ ആരെങ്കിലും ഉദ്ദേശിക്കുന്ന പക്ഷം തന്റെ രക്ഷിതാവിങ്കലേക്ക് ഒരു മാർഗ്ഗം സ്വീകരിക്കട്ടെ».", "malayalamMatn": "തീര്‍ച്ചയായും ഇത് ഒരു ഉല്‍ബോധനമാകുന്നു. ആകയാല്‍ വല്ലവനും ഉദ്ദേശിക്കുന്ന പക്ഷം തന്‍റെ രക്ഷിതാവിങ്കലേക്കുള്ള മാര്‍ഗം സ്വീകരിച്ചു കൊള്ളട്ടെ."}, {"ayahNumber": 30, "quranText": "وَمَا تَشَاۤءُونَ إِلَّاۤ أَن یَشَاۤءَ ٱللَّهُۚ إِنَّ ٱللَّهَ كَانَ عَلِیمًا حَكِیمࣰا\n", "jalalayn": "«وما تشاءون» بالتاء والياء اتخاذ السبيل بالطاعة «إلا أن يشاء الله» ذلك «إن الله كان عليما» بخلقه «حكيما» في فعله", "malayalam": "«എന്നാൽ അല്ലാഹു ഉദ്ദേശിച്ചാലല്ലാതെ നിങ്ങൾ ഉദ്ദേശിക്കുകയില്ല; തീർച്ചയായും അല്ലാഹു സർവ്വജ്ഞനും പരമയുക്തിമാനുമാകുന്നു».", "malayalamMatn": "അല്ലാഹു ഉദ്ദേശിക്കുന്ന പക്ഷമല്ലാതെ നിങ്ങള്‍ ഉദ്ദേശിക്കുകയില്ല. തീര്‍ച്ചയായും അല്ലാഹു സര്‍വ്വജ്ഞനും യുക്തിമാനുമാകുന്നു."}, {"ayahNumber": 31, "quranText": "یُدۡخِلُ مَن یَشَاۤءُ فِی رَحۡمَتِهِۦۚ وَٱلظَّـٰلِمِینَ أَعَدَّ لَهُمۡ عَذَابًا أَلِیمَۢا\n", "jalalayn": "«يدخل من يشاء في رحمته» جنته وهم المؤمنون «والظالمين» ناصبه فعل مقدر، أي أعد يفسره «أعد لهم عذابا أليما» مؤلما وهم الكافرون", "malayalam": "«താൻ ഉദ്ദേശിക്കുന്നവരെ അവൻ തന്റെ കാരുണ്യത്തിൽ പ്രവേശിപ്പിക്കുന്നു; അക്രമികൾക്കാകട്ടെ അവൻ വേദനാജനകമായ ശിക്ഷ ഒരുക്കിവെച്ചിരിക്കുന്നു».", "malayalamMatn": "അവന്‍ ഉദ്ദേശിക്കുന്നവരെ അവന്‍റെ കാരുണ്യത്തില്‍ അവന്‍ പ്രവേശിപ്പിക്കുന്നതാണ്‌. അക്രമകാരികള്‍ക്കാവട്ടെ അവന്‍ വേദനയേറിയ ശിക്ഷ ഒരുക്കി വെച്ചിരിക്കുന്നു."}], "topPoints": ["മനുഷ്യന്റെ സൃഷ്ടിപ്പും പരീക്ഷണവും (خلاصة السورة)", "സ്വർഗ്ഗവാസികൾക്കുള്ള അനുഗ്രഹങ്ങൾ"], "topQuestions": [{"q": "സ്വർഗ്ഗവാസികൾക്ക് ഭക്ഷണം നൽകുന്നതിലെ അവരുടെ മനോഭാവം എന്തായിരുന്നു?", "a": "അല്ലാഹുവിന്റെ പ്രീതി മാത്രം കാംക്ഷിച്ച് അഗതികൾക്കും അനാഥർക്കും അവർ ഭക്ഷണം നൽകി."}], "asbabAlNuzul": [{"ayahNumber": 8, "quranText": "وَیُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِینࣰا وَیَتِیمࣰا وَأَسِیرًا", "arabicSnippet": "نزلت في علي وفاطمة رضي الله عنهما وجارية لهما يقال لها فضة، حين مرض الحسن والحسين فنذروا صوم ثلاثة أيام إن شفاهما الله، فلما صاموا آثروا بطعامهم مسكينا ويتيما وأسيرا وباتوا جياعا.", "malayalamExplanation": "ഹസൻ (റ), ഹുസൈൻ (റ) എന്നിവർക്ക് അസുഖം ബാധിച്ചപ്പോൾ അവർക്ക് രോഗശമനം ലഭിച്ചാൽ മൂന്ന് ദിവസം നേർച്ച നോമ്പ് അനുഷ്ഠിക്കാമെന്ന് അലി (റ), ഫാത്വിമ (റ), അവരുടെ ഭൃത്യ ഫിദ്ദ എന്നിവർ നേർച്ചയാക്കി. അവർ സുഖം പ്രാപിച്ചപ്പോൾ നോമ്പനുഷ്ഠിക്കുകയും, ഓരോ ദിവസവും നോമ്പുതുറക്കാനുള്ള ഭക്ഷണം തയ്യാറാക്കുമ്പോൾ വാതിലിൽ വന്ന അഗതിക്കും അനാഥയ്ക്കും തടവുകാരനും നൽകി സ്വന്തം വിശപ്പ് വകവെക്കാതെ മൂന്ന് ദിവസവും വെള്ളം മാത്രം കുടിച്ച് പട്ടിണി കിടക്കുകയും ചെയ്തു. അവരുടെ ഈ അപാരമായ ത്യാഗത്തെ പ്രകീർത്തിച്ചുകൊണ്ടാണ് അല്ലാഹു ഈ വചനം അവതരിപ്പിച്ചത്."}]}];
